function isFnV(f) local t = type(f) return t == "function" or t == "cdata" end
function typeFnV(f) local t = type(f) if t == "cdata" then return "function" end return t end
_G.GRND_IMGUI_IN_FRAME = false
do
    local ffiOk, ffiMod = pcall(require, "ffi")
    function grndValidPtr(p)
        if p == nil or p == false then return false end
        if type(p) ~= "cdata" then return true end
        if ffiOk and ffiMod and ffiMod.cast then
            local ok, addr = pcall(function() return tonumber(ffiMod.cast("uintptr_t", p)) end)
            if ok then
                return type(addr) == "number" and addr >= 0x10000
            end
            local s = tostring(p)
            if s:find("NULL", 1, true) or s:find(": 0x0$", 1, false) then return false end
        end
        return true
    end
end
function grndSafeGetIO(im)
    if _G.GRND_IMGUI_IN_FRAME ~= true then return nil end
    im = im or _G.GRND_IM
    if not im then return nil end
    local tf = type(im.GetIO)
    if tf ~= "function" and tf ~= "cdata" then return nil end
    local tc = type(im.GetCurrentContext)
    if tc == "function" or tc == "cdata" then
        local okCtx, ctx = pcall(im.GetCurrentContext)
        if not okCtx or not grndValidPtr(ctx) then return nil end
    end
    local okIo, io = pcall(im.GetIO)
    if not okIo or not grndValidPtr(io) then return nil end
    return io
end
script_name("grnd_adm_tools")
GRND_SCRIPT_VERSION = "1.29"
script_version(GRND_SCRIPT_VERSION)
script_dependencies("SAMPFUNCS")
require "lib.moonloader"
require "lib.sampfuncs"
local libList = {
    { "cjson",       "cjson",    false },
    { "lfs",         "lfs",      false },
    { "socket.http", "http",     false },
    { "inspect",     "inspect",  false },
    { "lume",        "lume",     false },
    { "memory",      "memory",   false },
    { "vkeys",       "vkeys",    false },
    { "encoding",    "encoding", false },
    { "bit",         "bit",      false },
    { "requests",    "requests", false },
}
local libs = {}
local failed = {}
for _, item in ipairs(libList) do
    local name, var, required = item[1], item[2], item[3]
    local ok, mod = pcall(require, name)
    if ok then
        libs[var] = mod
        _G[var] = mod
    else
        failed[#failed + 1] = name
        if required then error("Обязательная библиотека не найдена: " .. name) end
    end
end
GRND_STORAGE = {paths={}}
function grndStoragePath(kind,name)
    local S=GRND_STORAGE
    local key=kind.."/"..name
    if S.paths[key] then return S.paths[key] end
    local sep=package.config:sub(1,1)
    if not S.root then
        local dir
        if type(thisScript)=="function" then
            pcall(function()
                local script=thisScript()
                if script then dir=tostring(script.path or ""):match("^(.*)[/\\]") end
            end)
        end
        if not dir and type(getWorkingDirectory)=="function" then
            local ok,value=pcall(getWorkingDirectory)
            if ok and value and value~="" then dir=tostring(value) end
        end
        if not dir and type(this_script_dir)=="function" then
            local ok,value=pcall(this_script_dir)
            if ok and value and value~="" then dir=tostring(value) end
        end
        dir=(dir or "."):gsub("[/\\]+$", "")
        local function mkdir(path)
            if type(createDirectory)=="function" then pcall(createDirectory,path) end
            if libs.lfs and type(libs.lfs.mkdir)=="function" then pcall(libs.lfs.mkdir,path) end
        end
        mkdir(dir..sep.."resource")
        S.root=dir..sep.."resource"..sep.."grnd"
        mkdir(S.root)
        mkdir(S.root..sep.."logs")
        mkdir(S.root..sep.."cache")
    end
    S.paths[key]=S.root..sep..kind..sep..name
    return S.paths[key]
end
GRND_CONFIG = {schema=1, sources={
    grnd_settings="settings", grnd_ui="ui", grnd_killlist="killlist",
    grnd_admins="admins", grnd_binder="binder", grnd_ring="ring",
    grnd_char="character", grnd_punish="punishments", grnd_chat="legacyFont",
    grnd_repquick="reportTemplates", grnd_reppunish="reportPunish",
    grnd_repauto="reportAuto",
    grnd_punauto="punishAuto",
    grnd_soft="soft", grnd_far_chat="farChat",
    grnd_update="update"
}}
do
    local C=GRND_CONFIG
    local ARRAY={}
    function C.array(t) return setmetatable(t or {},ARRAY) end
    local NULL={}
    local function utf(cp)
        if cp<128 then return string.char(cp) end
        if cp<2048 then return string.char(192+math.floor(cp/64),128+cp%64) end
        if cp<65536 then return string.char(224+math.floor(cp/4096),128+math.floor(cp/64)%64,128+cp%64) end
        return string.char(240+math.floor(cp/262144),128+math.floor(cp/4096)%64,128+math.floor(cp/64)%64,128+cp%64)
    end
    local function quote(s)
        return '"'..s:gsub('[%z\1-\31\\"]',function(ch)
            local escapes={['"']='\\"',['\\']='\\\\',['\n']='\\n',['\r']='\\r',['\t']='\\t'}
            return escapes[ch] or string.format('\\u%04x',ch:byte())
        end)..'"'
    end
    function C.encode(value,depth)
        depth=depth or 0;assert(depth<48,'JSON too deep')
        local t=type(value)
        if value==NULL or value==nil then return 'null' end
        if t=='string' then return quote(value) end
        if t=='boolean' then return value and 'true' or 'false' end
        if t=='number' then
            assert(value==value and math.abs(value)<math.huge,'Invalid JSON number')
            return (string.format('%.15g',value):gsub(',','.'))
        end
        assert(t=='table','Unsupported JSON value')
        local arr=getmetatable(value)==ARRAY or #value>0
        local result={};local indent=string.rep('  ',depth+1)
        if arr then
            for i=1,#value do result[#result+1]=indent..C.encode(value[i],depth+1) end
        else
            local keys={};for k in pairs(value) do assert(type(k)=='string','Non-string JSON key');keys[#keys+1]=k end
            table.sort(keys)
            for _,k in ipairs(keys) do result[#result+1]=indent..quote(k)..': '..C.encode(value[k],depth+1) end
        end
        local left,right=arr and '[' or '{',arr and ']' or '}'
        if #result==0 then return left..right end
        return left..'\n'..table.concat(result,',\n')..'\n'..string.rep('  ',depth)..right
    end
    function C.decode(s)
        assert(type(s)=='string' and #s<=2097152,'Invalid/oversized JSON')
        s=s:gsub('^\239\187\191','');local pos=1
        local function ws() local _,e=s:find('^[ \r\n\t]*',pos);pos=(e or pos-1)+1 end
        local function str()
            assert(s:sub(pos,pos)=='"','Expected string');pos=pos+1
            local out={}
            while pos<=#s do
                local ch=s:sub(pos,pos);pos=pos+1
                if ch=='"' then return table.concat(out) end
                if ch=='\\' then
                    ch=s:sub(pos,pos);pos=pos+1
                    local escapes={['"']='"',['\\']='\\',['/']='/',b='\b',f='\f',n='\n',r='\r',t='\t'}
                    if ch=='u' then
                        local h=s:sub(pos,pos+3);assert(h:match('^%x%x%x%x$'),'Bad unicode escape');pos=pos+4
                        local cp=tonumber(h,16)
                        if cp>=55296 and cp<=56319 then
                            assert(s:sub(pos,pos+1)=='\\u','Missing low surrogate');pos=pos+2
                            h=s:sub(pos,pos+3);assert(h:match('^%x%x%x%x$'),'Bad surrogate');pos=pos+4
                            local lo=tonumber(h,16);assert(lo>=56320 and lo<=57343,'Bad low surrogate')
                            cp=65536+(cp-55296)*1024+lo-56320
                        else assert(cp<56320 or cp>57343,'Unpaired surrogate') end
                        out[#out+1]=utf(cp)
                    else assert(escapes[ch],'Bad JSON escape');out[#out+1]=escapes[ch] end
                else assert(ch:byte()>=32,'Control in string');out[#out+1]=ch end
            end
            error('Unterminated string')
        end
        local parse
        parse=function(depth)
            assert(depth<48,'JSON too deep');ws();local ch=s:sub(pos,pos)
            if ch=='"' then return str() end
            if ch=='{' or ch=='[' then
                local arr=ch=='[';local result=arr and C.array() or {};pos=pos+1;ws()
                local ending=arr and ']' or '}'
                if s:sub(pos,pos)==ending then pos=pos+1;return result end
                while true do
                    if arr then result[#result+1]=parse(depth+1)
                    else
                        ws();local k=str();ws();assert(s:sub(pos,pos)==':','Missing colon');pos=pos+1
                        assert(result[k]==nil,'Duplicate key');result[k]=parse(depth+1)
                    end
                    ws();ch=s:sub(pos,pos);pos=pos+1
                    if ch==ending then return result end
                    assert(ch==',','Missing comma');ws()
                end
            end
            for word,v in pairs({['true']=true,['false']=false,['null']=NULL}) do
                if s:sub(pos,pos+#word-1)==word then pos=pos+#word;return v end
            end
            local start=pos
            if ch=='-' then pos=pos+1 end
            if s:sub(pos,pos)=='0' then pos=pos+1
            else assert(s:sub(pos,pos):match('[1-9]'),'Bad JSON value')
                repeat pos=pos+1 until not s:sub(pos,pos):match('%d')
            end
            if s:sub(pos,pos)=='.' then
                pos=pos+1;assert(s:sub(pos,pos):match('%d'),'Bad fraction')
                repeat pos=pos+1 until not s:sub(pos,pos):match('%d')
            end
            ch=s:sub(pos,pos)
            if ch=='e' or ch=='E' then
                pos=pos+1;ch=s:sub(pos,pos);if ch=='+' or ch=='-' then pos=pos+1 end
                assert(s:sub(pos,pos):match('%d'),'Bad exponent')
                repeat pos=pos+1 until not s:sub(pos,pos):match('%d')
            end
            local n=tonumber(s:sub(start,pos-1));assert(n and n==n and math.abs(n)<math.huge,'Bad number');return n
        end
        local result=parse(0);ws();assert(pos>#s,'Trailing JSON data');return result
    end
    function C.base()
        if C.baseDir then return C.baseDir end
        local dir
        if type(getWorkingDirectory)=='function' then local ok,v=pcall(getWorkingDirectory);if ok and v~='' then dir=v end end
        if not dir and type(thisScript)=='function' then
            pcall(function() dir=tostring(thisScript().path or ''):match('^(.*)[/\\]') end)
        end
        C.baseDir=tostring(dir or '.'):gsub('[/\\]+$','');return C.baseDir
    end
    function C.path()
        local sep=package.config:sub(1,1)
        local dir=C.base()..sep..'config'
        local function mkdir(p)
            if type(createDirectory)=='function' then pcall(createDirectory,p) end
            if libs.lfs and libs.lfs.mkdir then pcall(libs.lfs.mkdir,p) end
        end
        mkdir(dir);dir=dir..sep..'grnd_tools';mkdir(dir)
        C.filename=dir..sep..'config.json';return C.filename
    end
    local function read(path)
        local f,err,code=io.open(path,'rb');if not f then return nil,err,code end
        local s=f:read(2097153);f:close();return s or ''
    end
    function C.warn(message)
        C.error=tostring(message)
        if C.lastError~=C.error then
            C.lastError=C.error
            print('[GRND config] '..C.error)
            if type(grndChatSay)=='function' then pcall(grndChatSay,'[GRND] Ошибка config.json: '..C.error,-1) end
        end
    end
    local function unescape(s)
        return (s:gsub('\\(.)',function(c) if c=='n' then return '\n' end;return c end))
    end
    local function escape(s) return tostring(s):gsub('\\','\\\\'):gsub('\n','\\n'):gsub('\r','') end
    local function scalar(v,k)
        if k~='name' and k~='text' and k~='fontName' and k~='fontPath' and k~='playDate' and v:match('^%-?%d+%.?%d*$') then
            local n=tonumber(v);if n and n==n and math.abs(n)<math.huge then return n end
        end
        return v
    end
    function C.fromLegacy(section,body)
        local result={};local current=result
        if section=='binder' or section=='character' then result.items=C.array() end
        if section=='ring' then result.slots=C.array() end
        if section=='reportTemplates' or section=='reportPunish' then result.items=C.array() end
        for line in (body..'\n'):gmatch('([^\n]*)\n') do
            line=line:gsub('\r$','')
            if line=='---' and result.items then
                current={};result.items[#result.items+1]=current
            else
                local k,v=line:match('^([%w_%.]+)=(.*)$')
                if k then
                    local private=(section~='binder' and section~='character') and
                        (k:lower():find('password',1,true) or k:lower():find('passwd',1,true) or
                         k:lower():find('secret',1,true) or k:lower():find('token',1,true) or k=='login')
                    if not private and not (section=='admins' and (k=='playDate' or k=='playSec')) then
                        if result.items and (k=='name' or k=='text') then current[k]=unescape(v)
                        elseif section=='character' and current~=result and k=='id' then current[k]=v
                        elseif section=='punishments' and k:match('%.[rt]$') then
                            local values=C.array()
                            for item in v:gmatch('[^|]+') do values[#values+1]=k:match('%.t$') and (tonumber(item) or 1) or item end
                            current[k]=values
                        else current[k]=scalar(v,k) end
                    end
                elseif section=='ring' then
                    local side,index,key,mods,name,command=line:match('^([LRV])|(%d+)|(%d+)|(%d+)|([^|]*)|([^|]*)$')
                    if side then
                        local function dec(t) return (t:gsub('%%7[Cc]','|'):gsub('%%25','%%')) end
                        result.slots[#result.slots+1]={side=side,index=tonumber(index),key=tonumber(key),mods=tonumber(mods),name=dec(name),command=dec(command)}
                    end
                end
            end
        end
        if result.items and #result.items>0 and next(result.items[#result.items])==nil then table.remove(result.items) end
        if section=='ui' and result.fontPath then result.fontPath=tostring(result.fontPath):match('[^/\\]+$') end
        return result
    end
    function C.toLegacy(section,record)
        local out={}
        local function fields(t,item)
            local keys={};for k in pairs(t) do if k~='items' and k~='slots' then keys[#keys+1]=k end end;table.sort(keys)
            for _,k in ipairs(keys) do
                local v=t[k]
                if type(v)=='table' then v=table.concat(v,'|')
                elseif type(v)=='boolean' then v=v and '1' or '0'
                elseif item and (k=='name' or k=='text') then v=escape(v)
                else v=tostring(v) end
                out[#out+1]=k..'='..v
            end
        end
        fields(record,false)
        for _,item in ipairs(record.items or {}) do out[#out+1]='---';fields(item,true) end
        if section=='ring' then
            for _,item in ipairs(record.slots or {}) do
                local function esc(t) return (tostring(t or ''):gsub('%%','%%25'):gsub('|','%%7C')) end
                out[#out+1]=table.concat({item.side,item.index,item.key,item.mods,esc(item.name),esc(item.command)},'|')
            end
        end
        return table.concat(out,'\n')..'\n'
    end
    local function plain(t)
        assert(type(t)=='table' and t~=NULL and getmetatable(t)~=ARRAY,'Expected JSON object')
    end
    function C.validate(doc)
        plain(doc);assert(doc.schemaVersion==1 and doc.tool=='grnd_tools','Unsupported config schema')
        plain(doc.sections);plain(doc.layout or {});plain(doc.hotkeys or {});plain(doc.clickwarp or {})
        local count=0
        local function scalarObject(t)
            plain(t)
            for k,v in pairs(t) do
                assert(type(k)=='string' and k:match('^[%w_%.]+$'),'Invalid key')
                assert(type(v)=='string' or type(v)=='number' or type(v)=='boolean','Invalid scalar')
                if type(v)=='string' then assert(not v:find('%z') and #v<=131072,'Invalid string') end
            end
        end
        for section,t in pairs(doc.sections) do
            plain(t);count=count+1;assert(count<32,'Too many sections')
            local normal={}
            for k,v in pairs(t) do
                if k=='items' or k=='slots' then
                    assert(type(v)=='table' and v~=NULL and #v<=1000,'Invalid items')
                    for _,item in ipairs(v) do
                        scalarObject(item)
                        if k=='slots' then
                            assert(item.side=='L' or item.side=='R' or item.side=='V','Invalid ring side')
                            for _,n in ipairs({'index','key','mods'}) do assert(type(item[n])=='number','Invalid ring key') end
                        end
                    end
                elseif section=='punishments' and k:match('%.[rt]$') then
                    assert(type(v)=='table' and v~=NULL and #v<=1000,'Invalid punishment list')
                    for _,q in ipairs(v) do assert(type(q)=='string' or type(q)=='number','Invalid reason/time') end
                else normal[k]=v end
            end
            scalarObject(normal)
        end
        scalarObject(doc.hotkeys or {});scalarObject(doc.clickwarp or {})
        for _,v in pairs(doc.layout or {}) do scalarObject(v) end
        return true
    end
    function C.ensure()
        if C.loaded then return C.doc end
        C.loaded=true
        C.doc={schemaVersion=1,tool='grnd_tools',sections={},layout={},hotkeys={},clickwarp={}}
        local filename=C.path();local body,readError,readCode=read(filename)
        if not body and readCode and readCode~=2 then
            C.readOnly=true;C.warn(readError);return C.doc
        end
        if not body then
            body,readError,readCode=read(filename..'.bak')
            if not body and readCode and readCode~=2 then
                C.readOnly=true;C.warn(readError);return C.doc
            end
            if body then C.recovered=true end
        end
        if body then
            local ok,doc=pcall(C.decode,body)
            local valid,why=false,doc
            if ok then valid,why=pcall(C.validate,doc) end
            if not valid then
                C.readOnly=true;C.warn('config.json повреждён или имеет неизвестную версию; файл НЕ перезаписан: '..tostring(why))
                return C.doc
            end
            C.doc=doc;doc.layout=doc.layout or {};doc.hotkeys=doc.hotkeys or {};doc.clickwarp=doc.clickwarp or {}
            C.lastSaved=C.recovered and nil or C.encode(doc);C.existed=true
            if C.recovered then C.dirty=true;C.lastSaved=nil end
            return doc
        end
        local dirs={C.base()}
        if type(thisScript)=='function' then
            pcall(function() local d=tostring(thisScript().path or ''):match('^(.*)[/\\]');if d then table.insert(dirs,1,d) end end)
        end
        if type(this_script_dir)=='function' then local ok,d=pcall(this_script_dir);if ok and d then dirs[#dirs+1]=d end end
        local sep=package.config:sub(1,1)
        for base,section in pairs(C.sources) do
            if section~='legacyFont' then
                for _,dir in ipairs(dirs) do
                    local text=read(dir..sep..base..'.cfg')
                    if text and #text<=2097152 then C.doc.sections[section]=C.fromLegacy(section,text);break end
                end
            end
        end
        if not C.doc.sections.ui then
            for _,dir in ipairs(dirs) do
                local text=read(dir..sep..'grnd_chat.cfg')
                if text then
                    local old=C.fromLegacy('ui',text);local ui={}
                    for _,k in ipairs({'fontPath','fontName','fontSize','fontUser'}) do ui[k]=old[k] end
                    C.doc.sections.ui=ui;break
                end
            end
        end
        C.dirty=true;return C.doc
    end
    function C.open(path,mode)
        local base=tostring(path):match('([^/\\]+)%.cfg$')
        local section=C.sources[base]
        if not section then error('Unknown configuration domain: '..tostring(path)) end
        C.ensure();mode=mode or 'r'
        if mode:sub(1,1)=='r' then
            local record=C.doc.sections[section]
            if not record then return nil,'section not present' end
            local body=C.toLegacy(section,record);local cursor=1;local closed=false
            return {
                read=function(self,format) assert(not closed,'closed file');if format=='*a' then local out=body:sub(cursor);cursor=#body+1;return out end;error('Unsupported read') end,
                lines=function() return function() if closed or cursor>#body then return nil end;local last=body:find('\n',cursor,true) or #body+1;local line=body:sub(cursor,last-1);cursor=last+1;return line end end,
                close=function() closed=true;return true end
            }
        end
        if C.readOnly then return nil,'config.json is protected after a read error' end
        assert(mode:sub(1,1)=='w','Unsupported configuration mode')
        local chunks={};local closed=false
        return {
            write=function(self,...) assert(not closed,'closed file');for i=1,select('#',...) do chunks[#chunks+1]=tostring(select(i,...)) end;return self end,
            close=function()
                if closed then return true end;closed=true
                local record=C.fromLegacy(section,table.concat(chunks))
                if C.encode(record)~=C.encode(C.doc.sections[section]) then C.doc.sections[section]=record;C.dirty=true end
                return true
            end
        }
    end
    function C.flush()
        C.ensure();if C.readOnly or not C.dirty then return not C.readOnly end
        local ok,body=pcall(C.encode,C.doc)
        if not ok then C.warn(body);return false end
        if #body>2097152 then C.warn('Конфиг больше 2 MB; предыдущая версия сохранена');return false end
        if body==C.lastSaved then C.dirty=false;return true end
        local path=C.filename or C.path();local tmp=path..'.tmp';local bak=path..'.bak'
        local f,err=io.open(tmp,'wb');if not f then C.warn(err);return false end
        local written,why=pcall(function() assert(f:write(body..'\n'));assert(f:flush());assert(f:close()) end)
        if not written then pcall(f.close,f);os.remove(tmp);C.warn(why);return false end
        local existing,readError,readCode=read(path)
        if not existing and readCode and readCode~=2 then
            os.remove(tmp);C.warn(readError);return false
        end
        if existing then
            os.remove(bak)
            local moved,e=os.rename(path,bak)
            if not moved then os.remove(tmp);C.warn(e);return false end
        end
        local moved,e=os.rename(tmp,path)
        if not moved then
            if existing then os.rename(bak,path) end
            C.warn(e);return false
        end
        C.lastSaved=body;C.dirty=false;C.error=nil;C.lastError=nil;return true
    end
    function C.setLayout(name,values)
        C.ensure()
        if C.encode(C.doc.layout[name])~=C.encode(values) then C.doc.layout[name]=values;C.dirty=true end
    end
    C.hotkeyNames={'GRND_MENU_HOTKEY','GRND_SPEC_WARP_KEY'}
    function C.restoreHotkeys()
        C.ensure()
        for _,key in ipairs(C.hotkeyNames) do
            local v=C.doc.hotkeys[key]
            if type(v)=='number' and v>=1 and v<=255 and v==math.floor(v) then _G[key]=v end
        end
    end
    C.clickFields={'enabled','mode','keyToggle','keyApply','markerColor','maxDist'}
    function C.bindClickwarp(ref)
        C.ensure();C.clickRef=ref
        for _,key in ipairs(C.clickFields) do
            local v=C.doc.clickwarp[key]
            if type(v)==type(ref[key]) then
                if key=='mode' then
                    if v=='click' or v=='blip' or v=='aim' then ref[key]=v end
                elseif key:match('^key') then
                    if v>=1 and v<=255 and v==math.floor(v) then ref[key]=v end
                elseif key=='markerColor' then ref[key]=math.floor(math.max(0,math.min(255,v)))
                elseif key=='maxDist' then ref[key]=math.max(1,math.min(2000,v))
                else ref[key]=v end
            end
        end
    end
    C.panelFields={
        cameraExpanded={'GRND_CAM','expanded'},chatExpanded={'GRND_CHAT','expanded'},
        whExpanded={'GRND_WH','expanded'},tracerExpanded={'GRND_TRACER','expanded'},
        tracerPage={'GRND_TRACER','page'}
    }
    function C.restorePanels()
        local layout=C.ensure().layout
        local saved=layout.panels or {}
        local rc=_G.GRND_RC;local pos=layout.reconPunishments
        if rc and type(pos)=='table' and type(pos.x)=='number' and type(pos.y)=='number' then
            rc.punishPosX,rc.punishPosY=pos.x,pos.y
        end
        for key,field in pairs(C.panelFields) do
            local ref=_G[field[1]];local v=saved[key]
            if ref then
                if field[2]=='page' then
                    if v==1 or v==2 then ref[field[2]]=v end
                elseif type(v)=='boolean' then ref[field[2]]=v end
            end
        end
    end
    function C.extraSnapshot()
        local panels={}
        for key,field in pairs(C.panelFields) do
            local ref=_G[field[1]]
            if ref and (type(ref[field[2]])=='boolean' or type(ref[field[2]])=='number') then
                panels[key]=ref[field[2]]
            end
        end
        C.setLayout('panels',panels)
        local rc=_G.GRND_RC
        if rc and type(rc.punishPosX)=='number' and type(rc.punishPosY)=='number' then
            C.setLayout('reconPunishments',{x=rc.punishPosX,y=rc.punishPosY})
        end
        for _,key in ipairs(C.hotkeyNames) do
            local v=_G[key]
            if type(v)=='number' and C.doc.hotkeys[key]~=v then C.doc.hotkeys[key]=v;C.dirty=true end
        end
        if C.clickRef then
            for _,key in ipairs(C.clickFields) do
                local v=C.clickRef[key]
                if C.doc.clickwarp[key]~=v then C.doc.clickwarp[key]=v;C.dirty=true end
            end
        end
    end
end
GRND_LOG = {queue={},seen={},flags={},dates={},page=1,category='chat',history={}}
do
    local L=GRND_LOG
    L.types={{'chat','Общий чат'},{'action_admins','Действия администрации'},
        {'form_admin','Формы администраторов'},{'report','Репорты и ответы'},{'kill_list','Kill List'}}
    L.allowed={};for _,v in ipairs(L.types) do L.allowed[v[1]]=true end
    function L.utf(s) return grndUtf8Text and grndUtf8Text(s) or tostring(s or '') end
    function L.clean(s) return (L.utf(s):gsub('{%x%x%x%x%x%x%x%x}',''):gsub('{%x%x%x%x%x%x}',''):gsub('[\r\n%z]',' ')) end
    function L.lower(s) return grndLowerUtf and grndLowerUtf(s) or s:lower() end
    function L.warn(s,kind)
        s=tostring(s);kind=kind or 'viewer'
        if kind=='write' then L.writeError=s;L.error=s
        elseif kind=='dates' then L.dateError=s
        elseif kind=='read' then L.viewError=s
        else L.uiError=s end
        L.lastErrors=L.lastErrors or {}
