    end
    function L.response(text)
        local t=L.clean(text):gsub('^%s*%[%d%d:%d%d:%d%d%]%s*',''):gsub('^%s+','')
        local target=t:match('^Администратор%s+%S+%s+для%s+([^:]+):')
        if not target then
            local a=t:match('^<ADM>%s*(.*)$')
            if a then
                a=a:gsub('^%(%d+%)%s*','')
                target=a:match('^%S+%s+ответил%s+([^:]+):') or a:match('^%S+%s+ответила%s+([^:]+):')
            end
        end
        if not target then return end
        target=target:match('^%s*(.-)%s*$')
        local nick,id=target:match('^(.-)%[(%d+)%]$')
        if not nick then nick,id=target:match('^(.-)%((%d+)%)$') end
        nick=(nick or target):gsub('%s+$','')
        if nick=='' or nick:find('%s') then return end
        return nick,tonumber(id)
    end
    function L.resolve(text)
        local nick,id=L.response(text);if not nick then return end
        local H=_G.GRND_REPHUD
        if H and H.items then
            for i=#H.items,1,-1 do
                local item=H.items[i]
                if L.lower(L.clean(item.nick))==L.lower(nick) and (not id or tonumber(item.pid)==id) then
                    table.remove(H.items,i)
                end
            end
        end
    end
    function L.duplicate(text,source)
        local key=L.clean(text):gsub('^%s*%[%d%d:%d%d:%d%d%]%s*','')
        local now=os.clock()
        for i=#L.seen,1,-1 do
            local e=L.seen[i]
            if now-e.at>1 then table.remove(L.seen,i) end
        end
        for _,e in ipairs(L.seen) do
            if e.key==key and not e.sources[source] then e.sources[source]=true;return true end
        end
        L.seen[#L.seen+1]={key=key,at=now,sources={[source]=true}}
        if #L.seen>512 then table.remove(L.seen,1) end
        return false
    end
    L.muted={}
    function L.muteKey(text)
        return L.clean(text):gsub('^%s*%[%d%d:%d%d:%d%d%]%s*','')
    end
    function L.muteText(text,seconds)
        local key=L.muteKey(text)
        if key=='' then return false end
        local now=os.clock();local life=tonumber(seconds) or 3
        local list=L.muted
        for i=#list,1,-1 do if list[i].until_<now then table.remove(list,i) end end
        list[#list+1]={key=key,until_=now+math.max(0.5,math.min(30,life))}
        if #list>64 then table.remove(list,1) end
        return true
    end
    function L.isMuted(text)
        local list=L.muted
        if type(list)~='table' or #list==0 then return false end
        local key=L.muteKey(text)
        if key=='' then return false end
        local now=os.clock()
        for i=#list,1,-1 do
            local e=list[i]
            if e.until_<now then table.remove(list,i)
            elseif e.key==key then return true end
        end
        return false
    end
    function L.capture(text,source)
        text=L.utf(text);if text=='' then return end
        if L.isMuted and L.isMuted(text) then return end
        L.resolve(text)
        if L.duplicate(text,source or 'direct') then return end
        local stamp=os.time()
        L.append('chat',text,stamp)
        local t=L.clean(text):gsub('^%s*%[%d%d:%d%d:%d%d%]%s*',''):gsub('^%s+','')
        if t:match('^Администратор%s+') then L.append('action_admins',text,stamp) end
        if L.response(text) or t:find('[К-во репорта:',1,true) then L.append('report',text,stamp) end
        if grndFormAdminLine then
            local _,_,body=grndFormAdminLine(text)
            if body and (body:find('/%a[%w_]*%s+') or body:match('^%s*%[ATOOLS%]%s*:')) then L.append('form_admin',text,stamp) end
        end
    end
    function L.nick(id)
