        return 'Неизвестно'
    end
    L.weapons={[0]='Кулак',[1]='Кастет',[2]='Клюшка',[3]='Дубинка',[4]='Нож',[5]='Бита',[6]='Лопата',
        [7]='Кий',[8]='Катана',[9]='Бензопила',[16]='Граната',[17]='Слезоточивый газ',[18]='Коктейль Молотова',
        [22]='Colt 45',[23]='Silenced Pistol',[24]='Desert Eagle',[25]='Shotgun',[26]='Sawnoff Shotgun',
        [27]='Combat Shotgun',[28]='Micro Uzi',[29]='MP5',[30]='AK-47',[31]='M4',[32]='TEC-9',
        [33]='Rifle',[34]='Sniper Rifle',[35]='Rocket Launcher',[36]='Heat Seeker',[37]='Flamethrower',
        [38]='Minigun',[39]='Satchel Charge',[41]='Spraycan',[42]='Огнетушитель',[49]='Транспорт',
        [50]='Лопасти вертолёта',[51]='Взрыв',[53]='Утопление',[54]='Падение'}
    function L.death(killer,victim,reason)
        killer,victim,reason=tonumber(killer),tonumber(victim),tonumber(reason) or 0
        if not victim or victim<0 or victim==65535 then return end
        local v=L.nick(victim)..'['..victim..']';local weapon=(L.weapons[reason] or 'Неизвестно')..'['..reason..']'
        if killer and killer>=0 and killer~=65535 and killer~=victim then
            L.append('kill_list',L.nick(killer)..'['..killer..'] убил с помощью "'..weapon..'" > '..v)
        else L.append('kill_list',v..' погиб. Причина: "'..weapon..'"') end
    end
    function L.scanDates()
        L.init();L.flush();L.dateError=nil;local found={}
        local function add(n) if L.validDate(n) then found[n]=true end end
        if libs.lfs then
            local ok,e=pcall(function() for n in libs.lfs.dir(L.root) do
                if libs.lfs.attributes(L.root..L.sep..n,'mode')=='directory' then add(n) end
            end end);if not ok then L.warn(e,'dates') end
        elseif findFirstFile and findNextFile and findClose then
            local h,n=findFirstFile(L.root..L.sep..'*')
            if h and h~=-1 then
                repeat if n then add(n) end;n=findNextFile(h) until not n
                findClose(h)
            end
        else L.warn('Для списка дат требуется lfs или функции поиска файлов MoonLoader','dates') end
        if L.currentDay then add(L.currentDay) end
        L.dates={};for d in pairs(found) do L.dates[#L.dates+1]=d end
        local function order(d) return d:sub(7,10)..d:sub(4,5)..d:sub(1,2) end
        table.sort(L.dates,function(a,b) return order(a)>order(b) end);L.page=1
    end
    function L.openDates(kind)
        L.uiError=nil;L.category=kind;L.scanDates();L.dateOpen=true;L.viewerOpen=false;L.stopRead()
    end
    function L.stopRead()
