    function L.bufferText(b,kind)
        if kind=='ffi' then return require('ffi').string(b) end
        return tostring(b.v or b.value or '')
    end
    function L.windows(C)
        if not L.dateOpen and not L.viewerOpen then return false end
        local im=C.im;local colors,vars=0,0
        local TH=GRND_UIKIT.TH
        local function solid(c)
            c=c or TH.bg;local a=(c[4] or 255)/255
            return {(TH.bg[1] or 20)*(1-a)+(c[1] or 20)*a,
                (TH.bg[2] or 20)*(1-a)+(c[2] or 20)*a,
                (TH.bg[3] or 24)*(1-a)+(c[3] or 24)*a,255}
        end
        local edge=solid({TH.textHi[1],TH.textHi[2],TH.textHi[3],65})
        local divider=solid({TH.accent[1],TH.accent[2],TH.accent[3],95})
        for _,e in ipairs({{'WindowBg',solid(TH.bg)},{'Text',TH.textHi},{'Border',edge},{'Separator',divider},
            {'FrameBg',solid(TH.card)},{'FrameBgHovered',solid(TH.itemHover)},
            {'FrameBgActive',solid(TH.card)},{'ScrollbarBg',solid(TH.card)},
            {'ScrollbarGrab',TH.itemSel},{'ScrollbarGrabActive',TH.accent},
            {'Button',solid(TH.itemHover)},{'ButtonHovered',solid(TH.itemSel)},
            {'ButtonActive',solid(TH.itemPress)},
            {'TextSelectedBg',{TH.accent[1],TH.accent[2],TH.accent[3],100}}}) do
            if C.push(im.Col[e[1]],C.color(e[2])) then colors=colors+1 end
        end
        local function style(name,value)
            if im.StyleVar and im.StyleVar[name] and im.PushStyleVar then
                local ok=pcall(im.PushStyleVar,im.StyleVar[name],value)
                if ok then vars=vars+1 end
            end
        end
        style('Alpha',1);style('WindowRounding',12);style('FrameRounding',6)
        style('WindowBorderSize',1);style('FrameBorderSize',1)
        style('WindowPadding',im.ImVec2(16,14));style('FramePadding',im.ImVec2(10,7))
        style('ItemSpacing',im.ImVec2(8,10));style('ScrollbarSize',7)
        local function tip(text)
            if im.IsItemHovered and im.IsItemHovered() and im.SetTooltip then im.SetTooltip(text) end
        end
        local function draw()
            local dates=L.dateOpen;local key=dates and 'logDates' or 'logViewer'
            local sx,sy=getScreenResolution()
            local w=dates and 286 or math.min(1000,sx-32)
            local h=dates and math.min(438,sy-32) or math.min(650,sy-32)
            local p=GRND_CONFIG.ensure().layout[key] or {}
            im.SetNextWindowPos(im.ImVec2(math.max(0,math.min(sx-w,tonumber(p.x) or (sx-w)/2)),math.max(0,math.min(sy-h,tonumber(p.y) or (sy-h)/2))),C.once)
            im.SetNextWindowSize(im.ImVec2(w,h),C.always)
            if im.SetNextWindowBgAlpha then im.SetNextWindowBgAlpha(1) end
            if C.begin(dates and '##grnd_log_dates' or '##grnd_log_viewer',C.flags) then
                local pos=im.GetWindowPos();GRND_CONFIG.setLayout(key,{x=pos.x,y=pos.y})
                local caption='Дата'
                if not dates then
                    if im.Button('<##logback',im.ImVec2(30,28)) then L.openDates(L.category) end
                    tip('Выбрать другую дату');im.SameLine()
                    for _,t in ipairs(L.types) do if t[1]==L.category then caption=t[2] end end
                    caption=caption..'  /  '..L.date:gsub('%-','.')
                end
                if im.AlignTextToFramePadding then im.AlignTextToFramePadding() end
                im.TextUnformatted(caption)
                im.SameLine(w-44)
                if im.Button('x##logclose',im.ImVec2(28,28)) then L.close() end
                tip('Закрыть · Esc')
                im.Separator()
                if dates then
                    if L.dateError then im.TextWrapped('Не удалось прочитать список дат');tip(L.dateError)
                    elseif #L.dates==0 then im.TextUnformatted('Пока пусто') end
                    for i=(L.page-1)*7+1,math.min(#L.dates,L.page*7) do
                        local d=L.dates[i]
                        if im.Button(d:gsub('%-','.')..'##date'..d,im.ImVec2(w-32,32)) then
                            L.date=d;L.dateOpen=false;L.viewerOpen=true;L.query='';L.search=nil
                            L.searchPending=nil;L.history={};L.loadPage(0)
                        end
                    end
                    if #L.dates>7 then
                        if im.Button('<##datesprev',im.ImVec2(30,26)) and L.page>1 then L.page=L.page-1 end
                        im.SameLine();im.TextUnformatted(L.page..' / '..math.ceil(#L.dates/7));im.SameLine()
                        if im.Button('>##datesnext',im.ImVec2(30,26)) and L.page<math.ceil(#L.dates/7) then L.page=L.page+1 end
                    end
                else
                    if not L.search then L.search,L.searchKind=L.newBuffer(im,L.query or '',256) end
                    local searchColors=0
                    for _,entry in ipairs({{'FrameBg',{0,0,0,255}},
                        {'FrameBgHovered',{0,0,0,255}},{'FrameBgActive',{0,0,0,255}},
                        {'Border',{105,105,120,255}}}) do
                        if C.push(im.Col[entry[1]],C.color(entry[2])) then
                            searchColors=searchColors+1;colors=colors+1
                        end
                    end
                    local searchWidth=math.max(100,w-100)
                    local beforeSearchVars=vars
                    style('FrameRounding',8)
                    im.PushItemWidth(searchWidth)
                    local okInput,changed=pcall(function()
                        if L.searchKind=='ffi' then return im.InputText('Поиск##log_search',L.search,256) end
                        return im.InputText('Поиск##log_search',L.search)
                    end)
                    im.PopItemWidth()
                    if vars>beforeSearchVars then
                        im.PopStyleVar(vars-beforeSearchVars);vars=beforeSearchVars
                    end
                    if okInput and C.color32 and im.GetWindowDrawList and im.GetItemRectMin and im.GetItemRectMax then
                        local dl=im.GetWindowDrawList()
                        local lo,hi=im.GetItemRectMin(),im.GetItemRectMax()
                        local active=im.IsItemActive and im.IsItemActive()
                        local outline=active and {TH.accent[1],TH.accent[2],TH.accent[3],230}
                            or {135,135,151,255}
                        if dl and dl.AddRect then
                            pcall(dl.AddRect,dl,im.ImVec2(lo.x+0.5,lo.y+0.5),
                                im.ImVec2(lo.x+searchWidth-0.5,hi.y-0.5),C.color32(outline),8,0,1.2)
                        end
                    end
                    C.pop(searchColors);colors=colors-searchColors
                    if not okInput then error(changed) end
                    if changed then L.searchPending=os.clock()+0.3 end
                    im.Separator()
                    local paged=#L.history>0 or L.nextOffset~=nil
                    if L.viewError then im.TextWrapped(L.viewError)
                    elseif L.busy then im.TextUnformatted('Поиск…')
                    elseif L.display=='' then im.TextUnformatted((L.query or '')~='' and 'Ничего не найдено' or 'Пока пусто')
                    else
                        if not L.buffer then L.buffer,L.bufferKind=L.newBuffer(im,L.display or '',65536) end
                        local aw,ah=w-32,h-(paged and 202 or 154)
                        if im.GetContentRegionAvail then
                            local ok,x,y=pcall(im.GetContentRegionAvail)
                            if ok then
                                if type(x)=='number' and type(y)=='number' then aw,ah=x,y-(paged and 54 or 2)
                                elseif x then
                                    local vector,vx,vy=pcall(function() return x.x,x.y end)
                                    if vector and tonumber(vx) and tonumber(vy) then aw,ah=vx,vy-(paged and 54 or 2) end
                                end
                            end
                        end
                        local size=im.ImVec2(math.max(40,aw),math.max(60,ah))
                        local flags=(im.InputTextFlags and im.InputTextFlags.ReadOnly) or im.ImGuiInputTextFlags_ReadOnly or 16384
                        if L.bufferKind=='ffi' then im.InputTextMultiline('##log_text',L.buffer,65536,size,flags)
                        else im.InputTextMultiline('##log_text',L.buffer,size,flags) end
                    end
                    if paged then
                        im.Separator()
                        if im.Button('<##logprev',im.ImVec2(30,26)) and #L.history>0 then L.loadPage(table.remove(L.history)) end
                        im.SameLine();im.TextUnformatted(tostring(#L.history+1));im.SameLine()
                        if im.Button('>##lognext',im.ImVec2(30,26)) and L.nextOffset then
                            L.history[#L.history+1]=L.offset;L.loadPage(L.nextOffset)
                        end
                    end
                    local down=false
                    if type(isKeyDown)=='function' then
                        local ok,value=pcall(isKeyDown,0x74)
                        down=ok and value and true or false
                    end
                    local pressed=down and not L.f5Down
                    L.f5Down=down
                    if pressed and im.IsWindowFocused then
                        local ok,focused=pcall(im.IsWindowFocused,0)
                        if ok and focused then L.history={};L.loadPage(0) end
                    end
                end
            end
            C.finish()
        end
        local ok,err=pcall(draw)
        if not ok then C.recover();L.warn(err,'viewer')
        else L.uiError=nil end
        if vars>0 then im.PopStyleVar(vars) end
        C.pop(colors)
        return L.dateOpen or L.viewerOpen
    end
end
