local function grndDialogPartsNow()
    if type(sampIsDialogActive) ~= "function" then return "", "" end
    local okActive, active = pcall(sampIsDialogActive)
    if not okActive or not active then return "", "" end
    local caption, text = "", ""
    if type(sampGetDialogCaption) == "function" then
        local ok, value = pcall(sampGetDialogCaption)
        if ok and type(value) == "string" then caption = value end
    end
    if type(sampGetDialogText) == "function" then
        local ok, value = pcall(sampGetDialogText)
        if ok and type(value) == "string" then text = value end
    end
    return caption, text
end
function grndDialogTextNow()
