local GRND_TAP = {}
local function grndTapState(vk)
    local st = GRND_TAP[vk]
    if not st then st = { held = false, downAt = 0, downFrame = -9999 }
        GRND_TAP[vk] = st end
    return st
end
local function grndTapBegin(vk)
    local st = grndTapState(vk)
    if st.held then return false end
    st.held = true
    st.downAt = os.clock()
    st.downFrame = GRND_UIFRAME
    return true
end
local function grndTapEnd(vk)
    grndTapState(vk).held = false
end
local function grndTapHeldFrames(vk)
    return GRND_UIFRAME - (grndTapState(vk).downFrame or GRND_UIFRAME)
end
local function grndPollTap(vk)
    local st = grndTapState(vk)
    if st.held then return false end
    st.held, st.downAt, st.downFrame = true, os.clock(), GRND_UIFRAME
    return true
end
local GRND_REF = { im = nil, menu = nil, clw = nil, spec = nil, gm = nil,
                   clwSetAiming = nil, clwApplyAim = nil }
GRND_MOUSE = { x = 0, y = 0, down = false, clicked = false, rdown = false,
               rclicked = false, mdown = false, mclicked = false,
               at = -99, frame = -1 }
GRND_UIFRAME = 0
local function grndMouseXY(lparam)
    local lp = tonumber(lparam) or 0
    if lp < 0 then lp = lp + 0x100000000 end
    local x = lp % 65536
    local y = math.floor(lp / 65536) % 65536
    if x >= 32768 then x = x - 65536 end
    if y >= 32768 then y = y - 65536 end
    return x, y
end
function grndMouseInside(r)
    if not r or not r.w or r.w <= 0 then return false end
    local mx, my = GRND_MOUSE.x, GRND_MOUSE.y
    return mx >= r.x and mx <= r.x + r.w and my >= r.y and my <= r.y + r.h
end
function grndCursorXY()
    if type(getCursorPos) == "function" then
        local ok, x, y = pcall(getCursorPos)
        if ok and type(x) == "number" and type(y) == "number" then return x, y end
    end
    return GRND_MOUSE.x, GRND_MOUSE.y
end
function grndCursorX() local x = grndCursorXY() return x end
function grndCursorY() local _, y = grndCursorXY() return y end
function grndClickAlive()
    return (GRND_MOUSE.frame or -9999) - GRND_UIFRAME <= 0
       and (GRND_MOUSE.frame or -9999) >= GRND_UIFRAME - 1
end
function grndLeftClickPending()
    local M = GRND_MOUSE
    if type(M) ~= "table" or not M.clicked then return false end
    local btn = M.clickedBtn
    if btn ~= nil and btn ~= 1 then return false end
    if not grndClickAlive() then return false end
    return true
end
function grndRightClickPending()
    local M = GRND_MOUSE
    if type(M) ~= "table" or not M.rclicked then return false end
    if M.rclickedBtn ~= nil and M.rclickedBtn ~= 2 then return false end
    if not grndClickAlive() then return false end
    return true
end
local grndGAKS = nil
do
    local okF, ffi = pcall(require, "ffi")
    if okF and type(ffi) == "table" and ffi.cdef and ffi.load then
        pcall(function()
            ffi.cdef("short __stdcall GetAsyncKeyState(int vKey);")
            grndGAKS = ffi.load("user32").GetAsyncKeyState
        end)
    end
end
function grndRmbHeldWin()
    if not grndGAKS then return nil end
    local ok, st = pcall(grndGAKS, 0x02)
    if not ok or st == nil then return nil end
    local v = tonumber(st)
    if not v then return nil end
    if v < 0 then v = v + 65536 end
    return v >= 32768
end
function grndMouseFrameBegin()
    local M = GRND_MOUSE
    if type(M) ~= "table" then return end
    local fr = M.frame
    if not fr then return end
    local cur = tonumber(GRND_UIFRAME) or 0
    if fr > cur - 1 then return end
    M.frame = nil
    M.clicked, M.rclicked, M.mclicked = false, false, false
    M.clickedBtn, M.rclickedBtn, M.mclickedBtn = nil, nil, nil
end
function grndCheckerRectOk(r)
    if type(r) ~= "table" and type(r) ~= "userdata" then return false end
    local rx, ry = tonumber(r.x), tonumber(r.y)
    local rw, rh = tonumber(r.w), tonumber(r.h)
    if not (rx and ry and rw and rh) then return false end
    if rw <= 0 or rh <= 0 then return false end
    return true
end
function grndCheckerCovers()
    do
        local kl = _G.GRND_KL
        local ao = _G.GRND_AO
        local fc = _G.GRND_FCHAT
        if (kl and kl.moving) or (ao and ao.moving) or (fc and fc.moving) then
            _G.GRND_CHECKER_COVERS_FRAME = nil
            _G.GRND_CHECKER_COVERS = nil
            return {}
        end
    end
    local fr = _G.GRND_UIFRAME
    if fr and _G.GRND_CHECKER_COVERS_FRAME == fr
       and type(_G.GRND_CHECKER_COVERS) == "table" then
        return _G.GRND_CHECKER_COVERS
    end
    local out = {}
    local RC = _G.GRND_RC
    if RC and RC.show then
        local p, sz = RC.windowPos, RC.windowSize
        if type(p) == "table" and type(sz) == "table" then
            local r = { x = tonumber(p.x), y = tonumber(p.y),
                        w = tonumber(sz.w), h = tonumber(sz.h) }
            if grndCheckerRectOk(r) then out[#out + 1] = r end
        end
        if RC.edge then
            if grndCheckerRectOk(RC.edge.leftRect) then out[#out + 1] = RC.edge.leftRect end
            if grndCheckerRectOk(RC.edge.statsRect) then out[#out + 1] = RC.edge.statsRect end
        end
        if RC.statsPop and grndCheckerRectOk(RC.statsPopRect) then
            out[#out + 1] = RC.statsPopRect
        end
        if RC.actionsWinOpen and grndCheckerRectOk(RC.actionsWinRect) then
            out[#out + 1] = RC.actionsWinRect
        end
    end
    local R = _G.GRND_REPHUD
    if R and R.enabled and grndCheckerRectOk(R.rect) then
        out[#out + 1] = R.rect
    end
    local SFR = _G.GRND_SFR
    if SFR and (SFR.enabled or SFR.moving) and grndCheckerRectOk(SFR.rect) then
        out[#out + 1] = SFR.rect
    end
    local FC = _G.GRND_FCHAT
    if FC and (FC.enabled or FC.moving) and grndCheckerRectOk(FC.rect) then
        out[#out + 1] = FC.rect
    end
    if fr then
        _G.GRND_CHECKER_COVERS_FRAME = fr
        _G.GRND_CHECKER_COVERS = out
    end
    return out
end
function grndCheckerPointTaken(x, y)
    x, y = tonumber(x), tonumber(y)
    if not x or not y then return false end
    local list = grndCheckerCovers()
    for i = 1, #list do
        local r = list[i]
        if x >= r.x and x <= r.x + r.w and y >= r.y and y <= r.y + r.h then
            return true
        end
    end
    return false
end
function grndCheckerCanSelectRow(cursorOn, leftClick, moving, ignoreUntil, now)
    if moving then return false end
    now = tonumber(now) or os.clock()
    if now < (tonumber(ignoreUntil) or 0) then return false end
    return cursorOn == true or leftClick == true
end
-- skip — прямоугольник, который считать перекрытием нельзя (своё же окно)
function grndCheckerBandTaken(x1, y1, x2, y2, skip)
    x1, y1, x2, y2 = tonumber(x1), tonumber(y1), tonumber(x2), tonumber(y2)
    if not x1 or not y1 or not x2 or not y2 then return false end
    if x2 < x1 then x1, x2 = x2, x1 end
    if y2 < y1 then y1, y2 = y2, y1 end
    local list = grndCheckerCovers()
    -- своё окно сравниваем и по ссылке, и по геометрии: прямоугольник списка
    -- пересоздаётся каждый кадр, а список перекрытий может прийти из кэша кадра
    local sx, sy, sw, sh
    if type(skip) == "table" then
        sx, sy = tonumber(skip.x), tonumber(skip.y)
        sw, sh = tonumber(skip.w), tonumber(skip.h)
    end
    for i = 1, #list do
        local r = list[i]
        local same = (r == skip)
        if not same and sx and sy and sw and sh then
            same = math.abs((tonumber(r.x) or -999) - sx) < 1
                and math.abs((tonumber(r.y) or -999) - sy) < 1
                and math.abs((tonumber(r.w) or -999) - sw) < 1
                and math.abs((tonumber(r.h) or -999) - sh) < 1
        end
        if not same
           and x1 <= r.x + r.w and x2 >= r.x and y1 <= r.y + r.h and y2 >= r.y then
            return true
        end
    end
    return false
end
