    local barY = sbSave and tonumber(sbSave.y) or (savedBar and tonumber(savedBar.barY))
    if barX and barY then
        f:write("barX=" .. tostring(math.floor(barX + 0.5)) .. "\n")
        f:write("barY=" .. tostring(math.floor(barY + 0.5)) .. "\n")
