        f:write("reconX=" .. tostring(math.floor(rcSave.posX + 0.5)) .. "\n")
        f:write("reconY=" .. tostring(math.floor(rcSave.posY + 0.5)) .. "\n")
    end
    pcall(f.close, f)
    GRND_FONT.cfgDirty = false
    GRND_FONT.cfgSavedAt = os.clock()
    if not GRND_CONFIG.collecting then pcall(grndTrace, "cfg", "записан config/grnd_tools/config.json") end
    return true
end
function grndUiCfgLoad()
    if GRND_FONT.cfgLoaded then return end
    GRND_FONT.cfgLoaded = true
    local function parse(path)
        local ok, f = pcall(GRND_CONFIG.open, path, "r")
        if not ok or not f then return nil end
        local okc, content = pcall(function() return f:read("*a") end)
        pcall(function() f:close() end)
        if not okc or type(content) ~= "string" then return nil end
        return content
    end
    local content = parse(grndUiCfgPath())
    if not content then
        local d = grndUiCfgDir()
        local old = d and (d .. grndUiCfgSep() .. "grnd_chat.cfg") or "grnd_chat.cfg"
        content = parse(old)
        if content then
            pcall(grndTrace, "cfg", "шрифт перенесён из старого конфига: " .. old)
            GRND_FONT.cfgDirty = true
        end
    end
    if not content then
        pcall(grndTrace, "cfg", "конфига шрифта нет — берём системный/первый найденный")
        return
    end
    for line in (content .. "\n"):gmatch("([^\n]*)\n") do
        local k, v = line:match("^(%w+)=(.+)$")
        if k and v then
            if k == "fontName" or k == "fontPath" then
                GRND_FONT[k] = v
            elseif k == "fontUser" then
                GRND_FONT.fontUserChosen = (v == "1")
            elseif k == "fontSize" then
                local num = tonumber(v)
                if num then
                    GRND_FONT.fontSize = math.max(9, math.min(40, math.floor(num + 0.5)))
                end
            elseif k == "barX" or k == "barY" then
                local num = tonumber(v)
                if num then
                    _G.GRND_UI_BAR_SAVED = _G.GRND_UI_BAR_SAVED or {}
                    _G.GRND_UI_BAR_SAVED[k] = num
                end
            elseif k == "reconX" or k == "reconY" then
                local num = tonumber(v)
                if num then
                    local saved = _G.GRND_RECON_SAVED or {}
                    local field = k == "reconX" and "x" or "y"
                    saved[field] = num
                    _G.GRND_RECON_SAVED = saved
                end
            end
        end
    end
    local saved = _G.GRND_RECON_SAVED
    if saved and _G.GRND_RC then
        if saved.x then _G.GRND_RC.posX = saved.x end
        if saved.y then _G.GRND_RC.posY = saved.y end
    end
end
local grndCamMem, grndIsPlayerAiming
local GRND_CAM = {
    enabled = false,
    dist = 12.0,
    curDist = 12.0,
    heightMult = 1.0,
    inVehicle = true,
    resetOnAim = true,
    wheelAdjust = true,
    wasActive = false,
    cfgDirty = false,
    cfgLoaded = false,
    fovOn = true,
    fov = 100.0,
    fovApplied = nil,
    fovLerpUntil = 0,
    fovEndHold = nil,
}
_G.GRND_CAM = GRND_CAM
function grndCamNow()
    if type(getGameTimer)=='function' then
        local ok,v=pcall(getGameTimer)
        if ok and type(v)=='number' then return v/1000 end
    end
    return os.clock()
end
function grndCamReportError(part,err)
    GRND_CAM.errors=GRND_CAM.errors or {}
    local now=grndCamNow();local last=GRND_CAM.errors[part]
    if not last or now<last or now-last>=10 then
        GRND_CAM.errors[part]=now
        print('[GRND camera/'..tostring(part)..'] '..tostring(err))
    end
end
function grndCamSpectating()
    if _G.grndSpecNative and _G.grndSpecNative.camOn then return true end
    if _G.GRND_SPEC and _G.GRND_SPEC.active then return true end
    if _G.GRND_RC and _G.GRND_RC.show and tonumber(_G.GRND_RC.id) then return true end
    if type(sampIsPlayerSpectating)=='function' then
        local ok,v=pcall(sampIsPlayerSpectating);if ok and v then return true end
    end
    return false
end
function grndCamActiveBase()
    local M=grndCamMem and grndCamMem()
    if not M or not M.r8 then return nil end
    local ok,i=pcall(M.r8,0xB6F028+0x59)
    if not ok or type(i)~='number' or i<0 or i>2 then return nil end
    return 0xB6F028+0x174+i*0x238,M
end
function grndCamFovMem(fov,base)
    local active,M=grndCamActiveBase()
    base=base or active
    if not base or not M or not M.wf or type(fov)~='number'
        or fov~=fov or fov<5 or fov>170 then return false end
    if GRND_CAM.fovSniff then grndFovSniffNote(GRND_CAM, fov, "t") end
    return pcall(M.wf,base+0xB4,fov)
end
function grndFovNativeSeed(C, target)
    if type(C) ~= "table" then return false end
    local now = grndCamNow()
    local base, M = grndCamActiveBase()
    if not base or not M or type(M.rf) ~= "function" or type(M.wf) ~= "function" then
        C.fovNativeSeedRetryAt = now + 0.5
        return false
    end
    if now < (C.fovNativeSeedRetryAt or 0) then return false end
    local okMode, mode = pcall(M.r32, base + 0x0C)
    if not okMode or type(mode) ~= "number" or ((mode % 65536) ~= 4 and (mode % 65536) ~= 18) then
        C.fovNativeSeedRetryAt = now + 0.5
        return false
    end
    local okRead, current = pcall(M.rf, base + 0xB4)
    if not okRead or type(current) ~= "number" or current ~= current or current < 5 or current > 170 then
        C.fovNativeSeedRetryAt = now + 0.5
        return false
    end

    local sameSeed = C.fovNativeSeedBase == base and C.fovNativeSeedTarget == target
    if sameSeed then
        if C.fovNativeSeedBlocked then return false end
        if current >= target - 8 then
            C.fovNativeDropN = 0
            return true
        end
        C.fovNativeDropN = (C.fovNativeDropN or 0) + 1
        if C.fovNativeDropN < 2 then return false end
        if now - (C.fovNativeSeedAt or 0) < 0.25 then return false end
        if not C.fovNativeReseedWindowAt or now - C.fovNativeReseedWindowAt > 3.0 then
            C.fovNativeReseedWindowAt = now
            C.fovNativeReseedCount = 0
        end
        if (C.fovNativeReseedCount or 0) >= 3 then
            C.fovNativeSeedBlocked = true
            C.fovNativeSeedReason = "FOV снова сброшен несколько раз; повторные записи остановлены"
            print("[GRND FOV] повторные сбросы угла: дальнейшая коррекция остановлена для защиты от тряски")
            return false
        end
    else
        C.fovNativeReseedCount = 0
        C.fovNativeReseedWindowAt = now
        C.fovNativeSeedBlocked = nil
        C.fovNativeSeedReason = nil
    end

    if math.abs(current - target) > 0.05 then
        local okWrite, result = pcall(M.wf, base + 0xB4, target)
        if not okWrite or result == false then
            C.fovNativeSeedRetryAt = now + 1.0
            if not C.fovNativeSeedErrorLogged then
                C.fovNativeSeedErrorLogged = true
                print("[GRND FOV] однократная установка текущего угла не прошла; повтор через секунду")
            end
            return false
        end
        if sameSeed then
            C.fovNativeReseedCount = (C.fovNativeReseedCount or 0) + 1
            print(string.format("[GRND FOV] сброс после действия обнаружен; угол однократно возвращён к %.1f° (%d/3)",
                target, C.fovNativeReseedCount))
        else
            print(string.format("[GRND FOV] текущая камера однократно установлена на %.1f°", target))
        end
    end
    C.fovNativeSeedBase, C.fovNativeSeedTarget = base, target
    C.fovNativeSeedAt = now
    C.fovNativeDropN = 0
    C.fovNativeSeedRetryAt = nil
    C.fovNativeSeedErrorLogged = nil
    return true
end
function grndCamFovReset()
    if type(grndFov70NormalizerRestore) == "function" then
        pcall(grndFov70NormalizerRestore)
    end
    if type(grndFovFstpSuppressRestore) == "function" then
        pcall(grndFovFstpSuppressRestore)
    end
    local C=GRND_CAM;local S=C.fovState
    if S and type(S.original)=='number' then C.fovLastOriginal=S.original end
    if S then
        local M=grndCamMem and grndCamMem()
        if M and M.rf and M.wf then
            local ok,v=pcall(M.rf,S.base+0xB4)
            if ok and type(v)=='number' and math.abs(v-S.current)<0.25 then
                pcall(M.wf,S.base+0xB4,S.original)
            end
        end
    end
    C.fovState=nil;C.fovApplied=nil;C.fovEndHold=nil
    C.fovNativePatchActive=nil
    C.fovNativeSeedBase=nil;C.fovNativeSeedTarget=nil;C.fovNativeSeedRetryAt=nil
    C.fovNativeSeedAt=nil;C.fovNativeDropN=nil;C.fovNativeReseedCount=nil
    C.fovNativeReseedWindowAt=nil;C.fovNativeSeedBlocked=nil;C.fovNativeSeedReason=nil
    C.fovOnStreak=0
    C.fovDriftN=nil;C.fovPendBase=nil;C.fovPendN=nil
    C.fovFightUntil=nil;C.fovFightLost=nil
    C.fovAdopt=nil;C.fovPrevMean=nil;C.fovFarN=nil
    C.fovLowN=nil;C.fovLowNotifiedAt=nil
end
function grndCamFovTransfer(base)
    local C=GRND_CAM;local old=C.fovState
    if not old or old.base==base then return end
    local value,original=old.current,old.original
    grndCamFovReset()
    C.fovState={base=base,current=value,original=original,at=grndCamNow()}
    C.fovApplied=value
    grndCamFovMem(value,base)
end
local function grndFovWhy(why)
    local C=GRND_CAM
    if C.fovWhy~=why then
        print("{8FBF7F}[GRND рыбий глаз]{FFFFFF} " .. why)
    end
    C.fovWhy=why;C.fovWhyAt=grndCamNow()
end
local function grndFovHoldNotify(seconds)
    local C=GRND_CAM
    local now=grndCamNow()
    if C.fovHoldNotifiedAt and now-C.fovHoldNotifiedAt<60 then return end
    C.fovHoldNotifiedAt=now
    local msg="Рыбий глаз: сторонний код удерживает угол около 70°. Скрипт прекратил запись, чтобы не трясти камеру. Выполни /modules и пришли строки [GRND поиск-запись] из moonloader.log."
    local n=_G.notify
    if type(n)=='table' and type(n.say)=='function' then pcall(n.say,msg,'warn') end
end
local function grndFovNoteFix(cur, now)
    local C=GRND_CAM
    if not C.fovFixSince then
        C.fovFixSince=now;C.fovFixN=0;C.fovFixSum=0;C.fovFixCnt=0
        C.fovFixMin=nil;C.fovFixMax=nil
    end
    C.fovFixN=(C.fovFixN or 0)+1
    C.fovFixLast=cur
    C.fovFixSum=(C.fovFixSum or 0)+cur
    C.fovFixCnt=(C.fovFixCnt or 0)+1
    if not C.fovFixMin or cur<C.fovFixMin then C.fovFixMin=cur end
    if not C.fovFixMax or cur>C.fovFixMax then C.fovFixMax=cur end
end
local function grndFovAdoptCheck(now)
    local C=GRND_CAM
    if not C.fovFixSince or now-C.fovFixSince<=5 then return end
    local n=C.fovFixN or 0
    if n>=12 and C.fovFixCnt and C.fovFixCnt>0
       and C.fovFixMin and C.fovFixMax and (C.fovFixMax-C.fovFixMin)<=3.0 then
        local mean=C.fovFixSum/C.fovFixCnt
        local prev=C.fovPrevMean
        local floorFov=(tonumber(C.fov) or 100)-3
        if C.fovAdopt then
            if mean<C.fovAdopt-3.0 or mean>C.fovAdopt+3.0 then
                C.fovFarN=(C.fovFarN or 0)+1
                if C.fovFarN>=2 then
                    grndFovWhy(string.format(
                        "подстройка отменена: писатель ушёл на %.0f°",mean))
                    C.fovAdopt=nil;C.fovFarN=nil;C.fovPrevMean=nil
                end
            else
                C.fovFarN=nil
            end
        elseif mean>=90 and mean<=110 and mean>=floorFov then
            if prev and math.abs(mean-prev)<=0.5 then
                C.fovAdopt=mean;C.fovFarN=nil
                grndFovWhy(string.format("подстройка: цель %.1f° по чужому писателю",mean))
            elseif prev and mean<prev-0.5 then
                if not C.fovNormNotifiedAt or now-C.fovNormNotifiedAt>60 then
                    C.fovNormNotifiedAt=now
                    grndFovWhy("нормализатор: клиент плавно тянет угол к стандарту")
                    local nt=_G.notify
                    if type(nt)=='table' and type(nt.say)=='function' then
                        pcall(nt.say,"Рыбий глаз: в клиенте найден нормализатор FOV — он постоянно тянет угол к стандарту 70°. Скрипт держит 100°, но лёгкая тряска возможна, пока модуль активен. Ищи его среди ASI-плагинов в папке игры.",'warn')
                    end
                end
            end
        end
        if mean<=95 then C.fovLowN=(C.fovLowN or 0)+1 else C.fovLowN=0 end
        if (C.fovLowN or 0)>=2 and (not C.fovLowNotifiedAt
           or now-C.fovLowNotifiedAt>120) then
            C.fovLowNotifiedAt=now
            grndFovWhy(string.format("нормализатор утянул угол до %.0f°",mean))
            local nt=_G.notify
            if type(nt)=='table' and type(nt.say)=='function' then
                pcall(nt.say,string.format(
                    "Рыбий глаз: модуль клиента тянет угол всё ниже (уже ~%.0f°). Поставь свой угол обзора (100) в настройках лаунчера или отключи его плагин — тряска уйдёт полностью. Скрипт продолжает держать 100°.",
                    mean),'warn')
            end
        end
        C.fovPrevMean=mean
    end
    C.fovFixSince=nil;C.fovFixN=0;C.fovFixSum=nil;C.fovFixCnt=nil
    C.fovFixMin=nil;C.fovFixMax=nil;C.fovFixCtx=nil
end
function grndCamFovApply()
    local C=GRND_CAM
    local now=grndCamNow()
    if not C.fovPatchDisabled then
        pcall(grndFovPatchDisable)
        C.fovPatchDisabled = true
    end
    if C.fovProbeUntil then
        grndFovProbeTick(C, now)
        return
    end
    local aiming=type(grndIsPlayerAiming)=='function' and grndIsPlayerAiming()
    local spawned=true
    if type(grndIsSpawned)=='function' then spawned=grndIsSpawned() end
    local spectating=grndCamSpectating()
    -- UI state (chat, menus, dialogs, pause windows) must not pause or reset FOV.
    local gate=spectating or aiming or not spawned
    C.fovGateActive=gate or nil
    if gate then
        pcall(grndFov70NormalizerRestore)
        pcall(grndFovFstpSuppressRestore)
        C.fovNativePatchActive=nil
        C.fovNativeSeedBase=nil;C.fovNativeSeedTarget=nil;C.fovNativeSeedRetryAt=nil
        C.fovNativeSeedAt=nil;C.fovNativeDropN=nil;C.fovNativeReseedCount=nil
        C.fovNativeReseedWindowAt=nil;C.fovNativeSeedBlocked=nil;C.fovNativeSeedReason=nil
        C.fovOffStreak=math.min(100,(C.fovOffStreak or 0)+1)
        C.fovOnStreak=0
        C.fovDriftN=nil
        C.fovExtN=nil;C.fovExtAt=nil
        C.fovForeignWriter=nil
        if C.fovOffStreak==5 then
            grndFovWhy(aiming and "сброс: прицеливание"
                or (spectating and "сброс: слежка"
                    or "сброс: не спавнен"))
            grndCamFovReset()
        end
        return
    end
    C.fovOffStreak=0
    C.fovOnStreak=math.min(100,(C.fovOnStreak or 0)+1)
    if C.fovOn then
        local target=math.max(45,math.min(110,tonumber(C.fovAdopt or C.fov) or 100))
        local wasActive=C.fovNativePatchActive==true
        local patched,why=grndFov70NormalizerApply(target)
        if patched then
            local fstpOk,fstpWhy=grndFovFstpSuppressApply()
            if not fstpOk then
                pcall(grndFov70NormalizerRestore)
                pcall(grndFovFstpSuppressRestore)
                patched=false
                why="FSTP-коррекция не применена: "..tostring(fstpWhy)
            end
        end
        if patched then
            if not wasActive then
                grndFovWhy(string.format(
                    "адресная коррекция GTA SA включена: три значения FOV изменены на %.1f°, три сглаживающих записи отключены",target))
                print(string.format(
                    "[GRND FOV] адресная коррекция включена: 3 immediate + 3 FSTP, цель %.1f°",target))
            end
            C.fovNativePatchActive=true
            grndFovNativeSeed(C,target)
            C.fovForeignWriter=nil
            C.fovDriftN=nil;C.fovExtN=nil;C.fovExtAt=nil
            C.fovState=nil;C.fovApplied=target
            return
        end
        pcall(grndFov70NormalizerRestore)
        pcall(grndFovFstpSuppressRestore)
        C.fovNativePatchActive=nil
        C.fovNativeSeedBase=nil;C.fovNativeSeedTarget=nil;C.fovNativeSeedRetryAt=nil
        C.fovNativeSeedAt=nil;C.fovNativeDropN=nil;C.fovNativeReseedCount=nil
        C.fovNativeReseedWindowAt=nil;C.fovNativeSeedBlocked=nil;C.fovNativeSeedReason=nil
        local P=grndFovPatchState()
        if P.fov70LastFailure~=why then
            P.fov70LastFailure=why
            print("[GRND FOV] точечная коррекция не применена: "..tostring(why))
        end
        -- Fail closed: do not fall back to continuous FOV writes if the guarded patch fails.
        C.fovForeignWriter=nil
        C.fovState=nil;C.fovApplied=nil
        return
    else
        pcall(grndFov70NormalizerRestore)
        pcall(grndFovFstpSuppressRestore)
        C.fovNativePatchActive=nil
        C.fovNativeSeedBase=nil;C.fovNativeSeedTarget=nil;C.fovNativeSeedRetryAt=nil
        C.fovNativeSeedAt=nil;C.fovNativeDropN=nil;C.fovNativeReseedCount=nil
        C.fovNativeReseedWindowAt=nil;C.fovNativeSeedBlocked=nil;C.fovNativeSeedReason=nil
    end
    if C.fovForeignWriter then return end
    grndFovAdoptCheck(now)
    local base,M=grndCamActiveBase()
    if not base or not M.rf or not M.r32 then return end
    local okMode,mode=pcall(M.r32,base+0x0C)
    if not okMode or type(mode)~='number' then return end
    mode=mode%65536
    if mode~=4 and mode~=18 then return end
    local ok,current=pcall(M.rf,base+0xB4)
    if not ok or type(current)~='number' or current~=current or current<5 or current>170 then return end
    local S=C.fovState
    if S and S.base~=base then
        if C.fovPendBase==base then C.fovPendN=(C.fovPendN or 0)+1
        else C.fovPendBase=base;C.fovPendN=1 end
        if C.fovPendN>=2 then
            C.fovPendBase=nil;C.fovPendN=nil
            local good,m2=false,nil
            if M.r32 then good,m2=pcall(M.r32,base+0x0C) end
            if good and type(m2)=='number' and (m2%65536==4 or m2%65536==18) then
                grndFovWhy("смена слота камеры")
                grndCamFovTransfer(base);S=C.fovState
            else
                grndFovWhy("сброс: чужой слот камеры")
                grndCamFovReset();S=nil
            end
        end
    elseif C.fovPendBase then
        C.fovPendBase=nil;C.fovPendN=nil
    end
    if not S then
        if C.fovOn then
            if (C.fovOnStreak or 0)<2 then return end
            S={base=base,original=C.fovLastOriginal or current,current=current,at=now-1/60}
            C.fovState=S
        else
            local def=tonumber(GRND_SCRIPT_DEFAULT_FOV) or 70
            if math.abs(current-def)<0.5 then return end
            S={base=base,original=def,current=current,at=now-1/60}
            C.fovState=S
        end
    end
    local holdWrite=false
    if math.abs(current-S.current)>0.5 then
        if not C.fovOn then
            C.fovDriftN=(C.fovDriftN or 0)+1
            if C.fovDriftN>=2 then
                C.fovDriftN=nil
                grndFovWhy(string.format(
                    "выключен: угол держит чужой модуль (держит %.0f°), не вмешиваюсь",current))
                C.fovState=nil;C.fovApplied=nil
                return
            end
            holdWrite=true
        else
            C.fovDriftN=(C.fovDriftN or 0)+1
            holdWrite=true
            if C.fovDriftN>=2 then
                C.fovDriftN=nil
                if not C.fovExtAt or now-C.fovExtAt>2.0 then C.fovExtN=0 end
                C.fovExtN=(C.fovExtN or 0)+1
                C.fovExtAt=now
                if C.fovExtN>=2 then
                    C.fovForeignWriter=true
                    C.fovState=nil;C.fovApplied=nil
                    C.fovFightUntil=nil;C.fovFightLost=nil
                    grndFovWhy(string.format(
                        "чужой писатель обнаружен (%.0f°): скрипт прекратил менять угол",current))
                    grndFovHoldNotify(0)
                    return
                end
            end
        end
    else
        C.fovDriftN=nil
        C.fovExtN=nil;C.fovExtAt=nil
    end
    local dt=math.max(0,math.min(0.1,now-S.at));S.at=now
    local fovTarget=tonumber(C.fovAdopt or C.fov) or 100
    local target=C.fovOn and math.max(45,math.min(110,fovTarget)) or S.original
    S.current=S.current+(target-S.current)*(1-math.exp(-10*dt))
    if math.abs(S.current-target)<0.02 then S.current=target end
    if not holdWrite and math.abs(current-S.current)>0.05 then
        grndCamFovMem(grndFovSniffQ(S.current),base)
    end
    C.fovApplied=S.current
    if not C.fovOn and S.current==target then C.fovState=nil;C.fovApplied=nil end
end
function grndFovRenderTick()
    local C=GRND_CAM
    if C.fovNativePatchActive then return end
    if C.fovForeignWriter then return end
    if C.fovProbeUntil then return end
    if C.fovPatchPauseUntil then return end
    if not C.fovOn or C.fovHoldUntil or C.fovGateActive then return end
    local S=C.fovState
    if not S or not S.base then return end
    local now=grndCamNow()
    C.fovRenderAt=now
    grndFovAdoptCheck(now)
    local M=grndCamMem and grndCamMem()
    if not M or not M.rf then return end
    local ok,cur=pcall(M.rf,S.base+0xB4)
    if not ok or type(cur)~='number' or cur~=cur or cur<5 or cur>170 then return end
    if math.abs(cur-S.current)>0.3 then
        grndFovNoteFix(cur,now)
        local ctx=C.fovFixCtx
        if type(ctx)~="table" then ctx={car=0,aim=0,menu=0};C.fovFixCtx=ctx end
        if type(isCharInAnyCar)=="function" and PLAYER_PED then
            local okC,inC=pcall(isCharInAnyCar,PLAYER_PED)
            if okC and inC then ctx.car=ctx.car+1 end
        end
        if type(grndIsPlayerAiming)=="function" and grndIsPlayerAiming() then
            ctx.aim=ctx.aim+1
        end
        if GRND_KEYS and GRND_KEYS.uiBusy then ctx.menu=ctx.menu+1 end
        local hist=C.fovFixHist
        if type(hist)~="table" then hist={};C.fovFixHist=hist end
        hist[#hist+1]=string.format("%.1f",cur)
        if #hist>5 then table.remove(hist,1) end
    end
end
