function grndFovProbeStart(C, now, reason)
    if C.fovProbeUntil then return end
    _G.grndProbeDone = true
    local b, M = grndCamActiveBase()
    local cur
    if b and M and M.rf then
        local okv, v = pcall(M.rf, b + 0xB4)
        if okv and type(v) == "number" and v == v and v > 5 and v < 165 then
            cur = v
        end
    end
    C.fovProbeUntil = now + 3.0
    C.fovProbeRealEnd = os.clock() + 20
    C.fovProbe = { pts = {}, reason = tostring(reason), observed = cur }
    print("[GRND зонд] старт (" .. tostring(reason) ..
        "): 3 секунды только наблюдаю угол без изменений" ..
        (cur and string.format("; текущее значение %.1f", cur) or ""))
    if type(grndChatSay) == "function" then
        pcall(grndChatSay,
            "{00D6AA}[GRND]{FFFFFF} Зонд угла: 3 секунды наблюдения (не двигай прицел)", -1)
    end
    if not _G.grndLuaListTried then
        _G.grndLuaListTried = true
        pcall(grndListMoonloaderLua, "зонд")
    end
end
function grndFovProbeTick(C, now)
    local p = C.fovProbe
    if not p then C.fovProbeUntil = nil return end
    local b, M = grndCamActiveBase()
    if b and M and M.rf then
        local okv, v = pcall(M.rf, b + 0xB4)
        if okv and type(v) == "number" and v == v and v > 5 and v < 170 then
            p.pts[#p.pts + 1] = { t = now, v = v }
        end
    end
    if now >= C.fovProbeUntil or os.clock() > (C.fovProbeRealEnd or 0) then
        C.fovProbeUntil = nil
        grndFovProbeAnalyze(C)
    end
end
function grndFovProbeAnalyze(C)
    local p = C.fovProbe
    C.fovProbe = nil
    if not p or #p.pts < 3 then
        print("[GRND зонд] мало точек, анализ невозможен")
        return
    end
    local pts = p.pts
    local n = #pts
    local dur = pts[n].t - pts[1].t
    if dur <= 0 then dur = 1 end
    local evN = 0
    local firstV, lastV = pts[1].v, pts[n].v
    local evBefore, evDv = {}, {}
    for i = 2, n do
        local dv = pts[i].v - pts[i - 1].v
        if math.abs(dv) > 0.01 then
            evN = evN + 1
            evBefore[#evBefore + 1] = pts[i - 1].v
            evDv[#evDv + 1] = dv
        end
    end
    print(string.format("[GRND зонд] точек=%d за %.1f с; изменений угла=%d (%.1f/с)",
        n, dur, evN, evN / dur))
    print(string.format("[GRND зонд] угол: начало=%.2f конец=%.2f (дрейф %+.2f)",
        firstV, lastV, lastV - firstV))
    if evN == 0 then
        print("[GRND зонд] ВЫВОД: без наших записей угол НЕ меняется. " ..
            "Внешнего писателя нет — вибрацию создаёт наша запись/сама игра")
        if type(grndChatSay) == "function" then
            pcall(grndChatSay,
                "{00D6AA}[GRND]{FFFFFF} Зонд: внешнего писателя угла нет", -1)
        end
        return
    end
    local evT = {}
    for i = 2, n do
        if math.abs(pts[i].v - pts[i - 1].v) > 0.01 then
            evT[#evT + 1] = pts[i].t
        end
    end
    if #evT >= 3 then
        local gaps = {}
        for i = 2, #evT do gaps[#gaps + 1] = (evT[i] - evT[i - 1]) * 1000 end
        table.sort(gaps)
        local gmin, gmed, gmax = gaps[1], gaps[math.ceil(#gaps / 2)], gaps[#gaps]
        print(string.format("[GRND зонд] интервалы записей: мин=%.0f медиана=%.0f макс=%.0f мс",
            gmin, gmed, gmax))
    end
    local m = #evBefore
    local sx, sy, sxx, sxy = 0, 0, 0, 0
    for i = 1, m do
        local x, y = evBefore[i], evDv[i]
        sx = sx + x; sy = sy + y
        sxx = sxx + x * x; sxy = sxy + x * y
    end
    local den = m * sxx - sx * sx
    local r2, kE, T = nil, nil, nil
    if math.abs(den) > 1e-9 and m >= 3 then
        local b = (m * sxy - sx * sy) / den
        local a = (sy - b * sx) / m
        kE = -b
        T = (kE ~= 0) and (a / kE) or 0
        local mean = sy / m
        local ssTot, ssRes = 0, 0
        for i = 1, m do
            local y = evDv[i]
            local pred = a + b * evBefore[i]
            ssTot = ssTot + (y - mean) ^ 2
            ssRes = ssRes + (y - pred) ^ 2
        end
        if ssTot > 1e-12 then r2 = 1 - ssRes / ssTot end
        print(string.format("[GRND зонд] модель-1 (плавный доводчик): k=%.3f, цель T=%.1f град%s",
            kE, T, r2 and string.format(", r2=%.2f", r2) or ""))
    end
    local rate = (lastV - firstV) / dur
    print(string.format("[GRND зонд] модель-2 (постоянная скорость): %.2f град/с", rate))
    if math.abs(rate) > 0.2 then
        local dir = rate < 0 and "вниз" or "вверх"
        print(string.format("[GRND зонд] модель-2: доводчик тянет %s со скоростью ~%.1f град/с",
            dir, math.abs(rate)))
    end
    if m >= 3 and r2 and r2 > 0.8 and kE and kE > 0.02 and T > 5 and T < 170 then
        print(string.format("[GRND зонд] ВЫВОД: внешний писатель ЕСТЬ (плавный доводчик), тянет к %.0f градусам", T))
    elseif evN > 0 then
        print(string.format("[GRND зонд] ВЫВОД: внешний писатель ЕСТЬ, %d изменений за %.1f с; см. модели выше",
            evN, dur))
    end
    if type(grndChatSay) == "function" then
        pcall(grndChatSay,
            "{00D6AA}[GRND]{FFFFFF} Зонд: внешний писатель подтверждён — детали в логе", -1)
    end
end
function grndFovProbeCommand()
    local C = GRND_CAM
    if C.fovProbeUntil then
        if type(grndChatSay) == "function" then
            pcall(grndChatSay, "{00D6AA}[GRND]{FFFFFF} Зонд уже идёт", -1)
        end
        return
    end
    local now = grndCamNow()
    pcall(grndFovProbeStart, C, now, "команда /fovprobe")
end
