        return ok and v or nil
    end
    local function pedFor(id)
        if type(sampGetCharHandleBySampPlayerId)~='function' then return nil end
        local ok,a,b=pcall(sampGetCharHandleBySampPlayerId,id)
        local p=type(a)=='boolean' and b or a
        if ok and a~=false and type(p)=='number' and p>0 and p~=PLAYER_PED
            and call(doesCharExist,p) then return p end
    end
    function W.load(k,v)
        if k=='enabled' then W.enabled=(v=='1')
        elseif k=='new' then W.newwh=false
        elseif k=='skeleton' then W.skeleton=(v=='1')
        elseif k=='stats' then W.autoStats=(v=='1')
        elseif k=='distance' then
            local n=tonumber(v)
            if n and n==n then W.distance=math.max(10,math.min(800,n)) end
        end
    end
    function W.devGate()
