            pcall(notify.add,'Новый WH на игроков находится в разработке','warn',3,true)
        end
    end
    function W.setEnabled(on)
        W.enabled=on and true or false
        W.dirtyAt=os.clock()
        if not W.enabled then W.players={};W.scanAt=-999 end
        W.nativeAt=-999
    end
    function W.normalizePointer(value)
        local n=tonumber(value)
        if not n or n~=n or n~=math.floor(n) then return nil end
        if n<0 and n>=-2147483648 then n=n+4294967296 end
        if n<0x10000 or n>0xFFFFFFC0 then return nil end
        return n
    end
    function W.rangeAccessible(address,length)
        if W.queryMemory==nil then
            W.queryMemory=false
            local ok,F=pcall(require,'ffi')
            if ok and F.os=='Windows' and F.arch=='x86' then
                pcall(F.cdef, [[
                    typedef struct { uint32_t BaseAddress, AllocationBase, AllocationProtect,
                                     RegionSize, State, Protect, Type; } GRND_MBI32;
                    uint32_t __stdcall VirtualQuery(const void* a, GRND_MBI32* b, uint32_t n);
                ]])
                local loaded,k32=pcall(F.load,'kernel32')
                local typed=pcall(F.typeof,'GRND_MBI32')
                if loaded and typed then
                    W.queryMemory=function(ptr,bytes)
                        local mbi=F.new('GRND_MBI32[1]')
                        local cursor,finish=ptr,ptr+bytes
                        if finish>4294967296 then return false end
                        while cursor<finish do
                            local count=k32.VirtualQuery(F.cast('const void*',cursor),mbi,F.sizeof(mbi[0]))
                            if count<F.sizeof(mbi[0]) then return false end
                            local m=mbi[0]
                            local base,size=tonumber(m.BaseAddress),tonumber(m.RegionSize)
                            local prot=tonumber(m.Protect)
                            if tonumber(m.State)~=0x1000 or math.floor(prot/256)%2~=0
                                or (prot%256~=0x04 and prot%256~=0x08
                                    and prot%256~=0x40 and prot%256~=0x80)
                                or size<=0 or base>cursor or base+size<=cursor then return false end
                            cursor=math.min(finish,base+size)
                        end
                        return true
                    end
                end
            end
        end
        if not W.queryMemory then return false,'VirtualQuery недоступен' end
        local ok,accessible=pcall(W.queryMemory,address,length)
        return ok and accessible==true, 'область памяти недоступна для чтения/записи'
    end
    local function nativeContext()
        if type(isSampAvailable)=='function' and not isSampAvailable() then
            W.nativeError='SA:MP не подключён';return nil
        end
        local mem=memory or (libs and libs.memory)
        if not mem then W.nativeError='нет библиотеки memory';return nil end
        if type(sampGetServerSettingsPtr)~='function' then
            W.nativeError='нет sampGetServerSettingsPtr';return nil
        end
        local r8,w8=mem.getuint8 or mem.getint8,mem.setuint8 or mem.setint8
        if type(mem.getfloat)~='function' or type(mem.setfloat)~='function'
            or type(r8)~='function' or type(w8)~='function' then
            W.nativeError='неполный API memory';return nil
        end
        local ok,first,second=pcall(sampGetServerSettingsPtr)
        local value
        if ok then
            if type(first)=='boolean' then
                if first then value=second end
            else value=first end
        end
        local ptr=W.normalizePointer(value)
        if not ptr then
            W.nativeError='неверный указатель настроек: '..tostring(first);return nil
        end
        local accessible,why=W.rangeAccessible(ptr,58)
        if not accessible then
            W.nativeError=string.format('0x%08X: %s',ptr,why);return nil
        end
        W.nativeError=nil
        return ptr,mem,r8,w8
    end
    local function readNative(ptr,mem,r8)
        local d=call(mem.getfloat,ptr+39,false)
        local wall=call(r8,ptr+47,false)
        local tags=call(r8,ptr+56,false)
        if type(d)~='number' or d~=d or d<0 or d>20000
            or (wall~=0 and wall~=1) or (tags~=0 and tags~=1) then return nil end
        return {distance=d,wall=wall,tags=tags}
    end
    function W.restoreNative()
        local saved=W.native
        W.native=nil;W.nativeAt=-999;W.nativeVerified=false;W.nativeActual=nil
        if not saved then return end
        local ptr,mem,r8,w8=nativeContext()
        if not ptr or ptr~=saved.ptr then return end
        local current=readNative(ptr,mem,r8)
        if not current then return end
        if current.distance==saved.applied.distance then
            pcall(mem.setfloat,ptr+39,saved.original.distance,false)
        end
        if current.wall==saved.applied.wall then pcall(w8,ptr+47,saved.original.wall,false) end
        if current.tags==saved.applied.tags then pcall(w8,ptr+56,saved.original.tags,false) end
    end
    function W.nativeTagsWanted() return W.newwh and 0 or 1 end
    function W.nativeTick()
        if not W.enabled then W.restoreNative();return end
        local now=W.clock()
        if W.nativeAt and now>=W.nativeAt and now-W.nativeAt<0.2
            and W.native and W.native.applied.distance==W.distance
            and W.native.applied.tags==W.nativeTagsWanted() then return end
        W.nativeAt=now
        local ptr,mem,r8,w8=nativeContext()
        if not ptr then
            W.native=nil;W.nativeVerified=false;W.nativeStatus=W.nativeError or 'Штатные nametag: API недоступен.';return
        end
        local current=readNative(ptr,mem,r8)
        if not current then
            W.native=nil;W.nativeVerified=false;W.nativeStatus='Штатные nametag: структура не распознана.';return
        end
        local saved=W.native
        if not saved or saved.ptr~=ptr then
            saved={ptr=ptr,original=current,applied={}}
            W.native=saved
        else
            for _,key in ipairs({'distance','wall','tags'}) do
                if current[key]~=saved.applied[key] then saved.original[key]=current[key] end
            end
        end
        local d=math.max(10,math.min(800,W.distance))
        local tags=W.nativeTagsWanted()
        local okD,okW,okT=true,true,true
        if current.distance~=d then okD=pcall(mem.setfloat,ptr+39,d,false) end
        if current.wall~=0 then okW=pcall(w8,ptr+47,0,false) end
        if current.tags~=tags then okT=pcall(w8,ptr+56,tags,false) end
        saved.applied={distance=d,wall=0,tags=tags}
        local actual=readNative(ptr,mem,r8)
        W.nativeActual=actual
        W.nativeVerified=(okD and okW and okT and actual
            and math.abs(actual.distance-d)<0.05 and actual.wall==0 and actual.tags==tags) and true or false
        if W.nativeVerified then
            W.nativeStatus=(tags==1)
                and string.format('SA:MP: %.0f м; сквозь стены — да.',actual.distance)
                or string.format('Новый WH: %.0f м; штатные ники скрыты.',actual.distance)
        elseif actual then
            W.nativeStatus=string.format('Не применилось: %.0f м; LOS=%d, tags=%d.',actual.distance,actual.wall,actual.tags)
        else
            W.nativeStatus='Не удалось прочитать результат записи.'
        end
    end
    function W.diagnose()
        if not W.enabled then return end
