        if not f then return end
        local actual=W.nativeActual or {}
        local original=W.native and W.native.original or {}
        f:write(string.format('v1.14.54 t=%.2f requested=%.1f verified=%s ptr=%s read=%s,%s,%s original=%s,%s,%s streamed=%d inRange=%d farthest=%.1f status=%s error=%s\n',
            now,W.distance,tostring(W.nativeVerified),tostring(W.native and W.native.ptr),
            tostring(actual.distance),tostring(actual.wall),tostring(actual.tags),
            tostring(original.distance),tostring(original.wall),tostring(original.tags),
