        end
        local ok,F=pcall(require,'ffi')
        if not ok or F.os~='Windows' or F.arch~='x86' or type(getCharPointer)~='function' then return end
        local native=F.cast('void (__thiscall *)(void*, float*, int, bool)',0x5E4280)
