        end
    end
    local function project(x,y,z,w,h)
        local _,sx,sy,depth=convert3DCoordsToScreenEx(x,y,z,false,false)
        if not valid(sx,sy,depth) or depth<=0.1 then return nil end
        if sx<0 or sx>w or sy<0 or sy>h then return nil end
