        if not e.bonesAt or now<e.bonesAt or now-e.bonesAt>=0.05 then
            local pts={}
            for _,pair in ipairs(links) do
                for _,id in ipairs(pair) do
                    if pts[id]==nil then
                        local ok,bx,by,bz=pcall(W.bone,e.ped,id)
                        if ok and valid(bx,by,bz) and (bx-x)^2+(by-y)^2+(bz-z)^2<36 then
                            pts[id]={bx-x,by-y,bz-z}
                        else pts[id]=false end
                    end
                end
            end
            e.bones=pts;e.bonesAt=now
        end
