        for id,p in pairs(e.bones or {}) do
            if p then
                local sx,sy=project(x+p[1],y+p[2],z+p[3],w,h)
                if sx then screen[id]={sx,sy} end
            end
        end
        for _,pair in ipairs(links) do
            local a,b=screen[pair[1]],screen[pair[2]]
