        boxShadow = 0x8C000000,
        famText   = 0xFFFFFFFF,
        barBg     = 0xC0000000,
        hp        = 0xFFFF3B30,
        armor     = 0xFFEAF2FC,
        idText    = 0xFFFFFFFF,
