    }
    W.colors = WH_C
    local function whScale()
        local sh = 1080
        if type(getScreenResolution) == 'function' then
            local ok, _, y = pcall(getScreenResolution)
            if ok and tonumber(y) then sh = tonumber(y) end
        end
        local k = sh / 1080
        if k < 0.85 then k = 0.85 elseif k > 1.5 then k = 1.5 end
        return k
    end
    W.scale = whScale
    local function whFont(px, outlined)
        local F = W.fonts
        if not F then F = {} W.fonts = F end
        px = math.max(9, math.min(30, math.floor(px + 0.5)))
        local key = px * 2 + (outlined and 1 or 0)
        local rec = F[key]
        if rec then return rec[1], rec[2] end
        local font, ok
        if type(renderCreateFont) == 'function' then
            local flags = outlined and 5 or 1
            ok, font = pcall(renderCreateFont, 'Tahoma', -px, flags, 204)
            if not ok or not font then ok, font = pcall(renderCreateFont, 'Tahoma', -px, flags) end
            if outlined and (not ok or not font) then
                ok, font = pcall(renderCreateFont, 'Tahoma', -px, 1, 204)
                if not ok or not font then ok, font = pcall(renderCreateFont, 'Tahoma', -px, 1) end
                outlined = false
            end
        end
        if not ok or not font then return nil, false end
        rec = { font, outlined and true or false }
        F[key] = rec
        return rec[1], rec[2]
    end
    local function whAnsi(raw)
        local str = tostring(raw or '')
        if type(_G.grndAnsiText) == 'function' then
            local ok, out = pcall(_G.grndAnsiText, str)
            if ok and type(out) == 'string' then return out end
        end
        return str
    end
    local function whMeasure(px, txt, outlined)
        local str = whAnsi(txt)
        local C = W.mw
        if not C then C = {} W.mw = C end
        local byPx = C[px]
        if not byPx then byPx = {} C[px] = byPx end
        local key = (outlined and '1|' or '0|') .. str
        local cached = byPx[key]
        if cached then return cached end
        local w
        local f = whFont(px, outlined and true or false)
        if f and type(renderGetFontDrawTextLength) == 'function' then
            local ok, v = pcall(renderGetFontDrawTextLength, f, str)
            if ok and type(v) == 'number' and v >= 0 then w = v end
        end
        if not w then
            w = #str * px * 0.55
            if outlined then w = w * 1.12 end
        end
        if (W.mwN or 0) > 800 then W.mw = {} W.mwN = 0 C = W.mw byPx = {}
            C[px] = byPx end
        W.mwN = (W.mwN or 0) + 1
        byPx[key] = w
        return w
    end
    local function whPlayerColor(id)
        if type(sampGetPlayerColor) ~= 'function' then return nil end
        id = tonumber(id)
        if not id or id < 0 or id == 65535 then return nil end
        local ok, c = pcall(sampGetPlayerColor, id)
        if not ok or type(c) ~= 'number' then return nil end
        if c < 0 then c = c + 0x100000000 end
        local r = math.floor(c / 0x10000) % 256
        local g = math.floor(c / 0x100) % 256
        local b = c % 256
        if r + g + b == 0 then return nil end
        return 0xFF000000 + r * 0x10000 + g * 0x100 + b
    end
    function W.labelLayout(cx, top, d, measure)
        d = d or {}
        local k = tonumber(d.scale) or 1
        local m = measure or function(px, txt) return #tostring(txt) * px * 0.55 end
        local pxN   = math.floor(15 * k + 0.5)
        local pxF   = math.floor(13 * k + 0.5)
        local pxB   = math.floor(14 * k + 0.5)
        local padX  = math.max(4, math.floor(7 * k + 0.5))
        local function th(px) return math.floor(px * 1.3 + 0.5) end
        local gap   = math.max(2, math.floor(3 * k + 0.5))
        local nameH = th(pxN) + gap + math.max(2, math.floor(4 * k + 0.5))
        local famH  = pxF + math.max(9, math.floor(12 * k + 0.5))
        local barH  = math.max(4, math.floor(6 * k + 0.5))
        local armH  = math.max(3, math.floor(5 * k + 0.5))
        local armG  = math.max(1, math.floor(2 * k + 0.5))
        local boxH  = famH
        local nick  = tostring(d.nick or '')
        local fam   = (d.family ~= nil and d.family ~= '') and tostring(d.family) or nil
        local lvl   = tonumber(d.lvl)
        local id    = tostring(d.id or '')
        local hp    = tonumber(d.hp) or 0
        local armor = tonumber(d.armor) or 0
        local ops   = {}
        local function box(x, y, w, h, c) ops[#ops+1] = {kind='box', x=x, y=y, w=w, h=h, col=c} end
        local function txt(t, x, y, px, c, sh, inY, inH)
            ops[#ops+1] = {kind='text', s=t, x=x, y=y, px=px, col=c, shadow=sh and true or false,
                inY=inY, inH=inH}
        end
        local function r(v) return math.floor(v + 0.5) end
        cx, top = r(cx), r(top)
        local y = top
        if d.afk then
            local pxA = math.max(9, math.floor(11 * k + 0.5))
            local aw  = m(pxA, 'AFK')
            local ph  = math.max(13, math.floor(16 * k + 0.5))
            local pw  = r(math.max(aw + math.floor(12 * k + 0.5), math.floor(26 * k + 0.5)))
            local px0 = r(cx - pw / 2)
            local rad = ph / 2
            for i = 0, pw - 1 do
                local dx = i + 0.5 - pw / 2
                local half = rad
                local flat = pw / 2 - rad
                if math.abs(dx) > flat then
                    local ex = math.abs(dx) - flat
                    half = math.sqrt(math.max(0, rad * rad - ex * ex))
                end
                local bh = math.max(1, r(half * 2))
                box(px0 + i, r(y + (ph - bh) / 2), 1, bh, WH_C.afkBg)
            end
            txt('AFK', r(px0 + (pw - aw) / 2), y, pxA, WH_C.afkText, false, y, ph)
            y = y + ph + gap
        end
        local nw = m(pxN, nick, true)
        txt(nick, r(cx - nw / 2), y, pxN, d.nameColor or WH_C.nick, true)
        y = y + nameH
        if fam then
            local famTxt = fam
            local famW = r(math.max(m(pxF, famTxt) + padX * 2, math.floor(96 * k + 0.5)))
            local famX = r(cx - famW / 2)
            box(famX + 1, y + 1, famW, famH, WH_C.boxShadow)
            box(famX, y, famW, famH, WH_C.dark)
            txt(famTxt, r(famX + (famW - m(pxF, famTxt)) / 2), r(y + (famH - th(pxF)) / 2), pxF,
                WH_C.famText, false, y, famH)
            y = y + famH + gap
        end
        local barW = r(math.max(60, math.floor(96 * k + 0.5)))
        local bx   = r(cx - barW / 2)
        local hpFrac = hp / 100
        if hpFrac < 0 then hpFrac = 0 elseif hpFrac > 1 then hpFrac = 1 end
        box(bx, y, barW, barH, WH_C.barBg)
        if hpFrac > 0 then box(bx, y, math.max(1, math.floor(barW * hpFrac + 0.5)), barH, WH_C.hp) end
        y = y + barH
        if armor > 0 then
            y = y + armG
            local aFrac = armor / 100
            if aFrac > 1 then aFrac = 1 end
            box(bx, y, barW, armH, WH_C.barBg)
            box(bx, y, math.max(1, math.floor(barW * aFrac + 0.5)), armH, WH_C.armor)
            y = y + armH
        end
        y = y + gap
        local spinT = tonumber(d.spinT) or os.clock()
        local lvlTxt = lvl and (tostring(lvl) .. ' LVL') or WH_C.noLvl
        local idW  = r(math.max(boxH, m(pxB, id) + padX * 2))
        local lvlW = r(math.max(m(pxB, lvlTxt) + padX * 2, idW + math.floor(14 * k + 0.5)))
        local rowW = idW + gap + lvlW
        local rx   = r(cx - rowW / 2)
        box(rx, y, idW, boxH, WH_C.dark)
        txt(id, r(rx + (idW - m(pxB, id)) / 2), r(y + (boxH - th(pxB)) / 2), pxB, WH_C.idText,
            false, y, boxH)
        local lx = rx + idW + gap
        box(lx, y, lvlW, boxH, WH_C.lvlBg)
        if lvl then
            txt(lvlTxt, r(lx + (lvlW - m(pxB, lvlTxt)) / 2), r(y + (boxH - th(pxB)) / 2), pxB,
                WH_C.lvlText, false, y, boxH)
        else
            local x0  = lx + (lvlW - m(pxB, lvlTxt)) / 2
            local csx = r(x0 + m(pxB, '—') / 2)
            local csy = r(y + boxH / 2)
            local head = math.floor(spinT / 0.09) % 8
            local rad  = math.max(3, math.floor(4 * k + 0.5))
            for i = 0, 7 do
                local trail = (i - head) % 8
                local ang = i * math.pi / 4
                local col = WH_C.lvlText
                if trail == 1 then col = 0x991A1512
                elseif trail == 2 then col = 0x551A1512
                elseif trail > 2 then col = 0x2E1A1512 end
                local dot = (trail == 0) and 3 or 2
                box(r(csx + rad * math.cos(ang)) - 1, r(csy + rad * math.sin(ang)) - 1,
                    dot, dot, col)
            end
            txt('LVL', r(x0 + m(pxB, '— ')), r(y + (boxH - th(pxB)) / 2), pxB,
                WH_C.lvlDim, false, y, boxH)
        end
        y = y + boxH
        return ops, (y - top)
    end
    function W.labelHeight(d)
        local _, h = W.labelLayout(0, 0, d or {})
        return h or 0
    end
    local HEAD_LIFT = 0.14
    local HEAD_MIN  = 0.12
    local HEAD_MAX  = 2.9
    local HEAD_BONES = { 8, 7, 6, 5 }
    W.headOff = {}
    W.SYNC_POS_TTL = 10
    function W.headTop(e, x, y, z)
        local model = call(getCharModel, e.ped)
        local bd, bx, by, bz
        W.initBones()
        if W.bone and z then
            for _, bid in ipairs(HEAD_BONES) do
                local ok, qx, qy, qz = pcall(W.bone, e.ped, bid)
                if ok and valid(qx, qy, qz) then
                    local d = qz - z
                    if d >= HEAD_MIN and d <= HEAD_MAX and (not bd or d > bd) then
                        bd, bx, by, bz = d, qx, qy, qz
                    end
                end
            end
        end
        if bd and model then W.headOff[model] = bd + HEAD_LIFT end
        local dz = bd and (bd + HEAD_LIFT) or ((model and W.headOff[model]) or 1.86)
        local now = W.clock()
        local slot = W.sync[tonumber(e.id) or e.id]
        local sx, sy, sz
        if slot and slot.x and now - (slot.at or -999) <= W.SYNC_POS_TTL then
            sx, sy, sz = slot.x, slot.y, slot.z
        end
        local stale = sx ~= nil
        if sx and x then
            local ddx, ddy = sx - x, (sy or 0) - (y or 0)
            stale = (ddx * ddx + ddy * ddy) > 0.25
        end
        if not stale and bx then
            return bx, by, bz + HEAD_LIFT
        end
        if stale and sx then
            return sx, sy, (sz or z or 0) + dz
        end
        return x, y, (z or 0) + dz
    end
    function W.headPoint(x, y, z, sw, sh)
        local sx, sy = project(x, y, z, sw, sh)
        if not sx then return nil end
        return sx, sy
    end
    W.BUBBLE_TTL = 6
    W.bubble = W.bubble or {}
    function W.noteChat(id, text)
        id = tonumber(id)
        if not id or text == nil then return end
        W.bubble[id] = { at = W.clock(), text = tostring(text) }
    end
    function W.noteChatMsg(text)
        local t = tostring(text or '')
        local id = t:match('%[(%d+)%]') or t:match('%((%d+)%)')
        if id then W.noteChat(id, t) end
    end
    function W.drawBubble(cx, top, text, sh)
        if type(renderFontDrawText) ~= 'function' then return end
        local str = tostring(text or '')
        if str == '' then return end
        if #str > 84 then str = str:sub(1, 84):gsub('[\128-\191]+$', '') .. '…' end
        local px = math.max(10, math.floor(13 * (tonumber(sh) or 1080) / 1080 + 0.5))
        local f, outlined = whFont(px, true)
        if not f then return end
        str = whAnsi(str)
        local w = whMeasure(px, str, true)
        local ty = math.floor(top - px * 1.6 + 0.5) - 2
        if ty < 0 then ty = 0 end
        local x = math.floor(cx - w / 2 + 0.5)
        if not outlined then
            pcall(renderFontDrawText, f, str, x + 1, ty + 1, WH_C.textShadow)
        end
        pcall(renderFontDrawText, f, str, x, ty, WH_C.nick, true)
    end
    function W.onSync(id, hp, armor, x, y, z)
        id = tonumber(id)
        if not id then return end
        local slot = W.sync[id]
        if not slot then slot = {} W.sync[id] = slot end
        slot.at = W.clock()
        if x and y and z and valid(x, y, z) then
            slot.x, slot.y, slot.z = x, y, z
        end
        hp, armor = tonumber(hp), tonumber(armor)
        if hp then
            if hp < 0 then hp = 0 elseif hp > 100 then hp = 100 end
            slot.hp = math.floor(hp + 0.5)
        end
        if armor then
            if armor < 0 then armor = 0 elseif armor > 100 then armor = 100 end
            slot.armor = math.floor(armor + 0.5)
        end
    end
    function W.vitals(e)
        local now = W.clock()
        local slot = W.sync[tonumber(e.id) or e.id]
        if slot then
            if slot.hp ~= nil then e.hp = slot.hp end
            if slot.armor ~= nil then e.armor = slot.armor end
            if e.hp ~= nil and now - (slot.at or -999) <= 2 then
                if type(getCharHealth) == 'function' then
                    local okP, v = pcall(getCharHealth, e.ped)
                    v = okP and tonumber(v) or nil
                    if v and v > 0 and v < e.hp then e.hp = v end
                end
            end
            if e.hp ~= nil then return e.hp, e.armor or 0 end
        end
        if e.slowAt and now - e.slowAt < 0.2 and e.hp ~= nil then
            return e.hp or 0, e.armor or 0
        end
        e.slowAt = now
        local hp, armor = nil, nil
        local SN = _G.grndSpecNative
        if type(SN) == 'table' then
            if hp == nil and type(SN.getHealth) == 'function' then
                local ok, v = pcall(SN.getHealth, e.id)
                if ok and tonumber(v) then hp = tonumber(v) end
            end
            if armor == nil and type(SN.getArmor) == 'function' then
                local ok, v = pcall(SN.getArmor, e.id)
                if ok and tonumber(v) then armor = tonumber(v) end
            end
        end
        if hp == nil and type(getCharHealth) == 'function' then
            local ok, v = pcall(getCharHealth, e.ped)
            if ok and tonumber(v) and tonumber(v) > 0 then hp = tonumber(v) end
        end
        if armor == nil and type(getCharArmour) == 'function' then
            local ok, v = pcall(getCharArmour, e.ped)
            if ok and tonumber(v) and tonumber(v) > 0 then armor = tonumber(v) end
        end
        e.hp = hp or e.hp or 0
        e.armor = armor or e.armor or 0
        return e.hp, e.armor
    end
    local function whCell(id)
        local RC = _G.GRND_RC
        if type(RC) ~= 'table' then return nil end
        if tonumber(RC.id) == tonumber(id) and type(RC.live) == 'table'
           and (RC.live.rc_family or RC.live.rc_level or RC.live.rc_level_exp) then
            return RC.live
        end
        local cache = RC.statsCache
        if type(cache) == 'table' and type(cache[id]) == 'table' then return cache[id] end
        return nil
    end
    local function whFamily(cell)
        local f = cell and tostring(cell.rc_family or '') or ''
        f = f:gsub('^%s+', ''):gsub('%s+$', '')
        if f == '' or f == 'Нет' or f == '—' or f == '-' or f == 'нет' then return nil end
        return f
    end
    local function whLevel(cell)
        local raw = cell and (cell.rc_level_exp or cell.rc_level) or nil
        if not raw then return nil end
        local n = tostring(raw):match('(%d+)')
        return n and tonumber(n) or nil
    end
    W.familyOf, W.levelOf = whFamily, whLevel
    W.statQueue, W.statAsked, W.statNextAt = {}, {}, -999
    W.statTries = {}
    W.statDist = {}
    local WH_STAT_GAP   = 0.05
    local WH_STAT_RETRY = 600
    local WH_STAT_REASK = 4
    local WH_STAT_RANGE = 200
    local WH_STAT_TRIES = 4
    local function statComplete(cell)
        return cell ~= nil and cell.rc_family ~= nil
            and (cell.rc_level_exp ~= nil or cell.rc_level ~= nil)
    end
    local function statGap(id)
        local cell = whCell(id)
        if statComplete(cell) then return nil end
        local gotFam = cell ~= nil and cell.rc_family ~= nil
        local gotLvl = cell ~= nil and (cell.rc_level_exp ~= nil or cell.rc_level ~= nil)
        if (cell == nil or gotFam ~= gotLvl) and (W.statTries[id] or 0) < WH_STAT_TRIES then
            return WH_STAT_REASK
        end
        return WH_STAT_RETRY
    end
    function W.wantStats(id, dist)
        id = tonumber(id)
        if not id or not W.autoStats then return end
        local cell = whCell(id)
        if statComplete(cell) then return end
        local RC = _G.GRND_RC
        if type(RC) == 'table' and tonumber(RC.id) == id then return end
        if dist and dist > WH_STAT_RANGE then return end
        local now = W.clock()
        local at = W.statAsked[id]
        if at then
            local gap = statGap(id)
            if gap and now - at < gap then return end
        end
        for i = 1, #W.statQueue do
            if W.statQueue[i] == id then return end
        end
        W.statDist[id] = tonumber(dist) or 99999
        local pos = #W.statQueue + 1
        for i = 1, #W.statQueue do
            if W.statDist[W.statQueue[i]] and W.statDist[W.statQueue[i]] > W.statDist[id] then
                pos = i
                break
            end
        end
        table.insert(W.statQueue, pos, id)
    end
    function W.statsTick()
        if not W.enabled or not W.newwh or not W.autoStats then
            if #W.statQueue > 0 then W.statQueue = {} end
            return
        end
        if #W.statQueue == 0 then return end
        local now = W.clock()
        if now - W.statNextAt < WH_STAT_GAP then return end
        if type(_G.grndStatsRequest) ~= 'function' then return end
        if type(_G.grndStatsIsManual) == 'function' and _G.grndStatsIsManual() then return end
        if type(_G.grndStatsBusy) == 'function' and _G.grndStatsBusy() then return end
        if type(grndIsSpawnedSafe) == 'function' and not grndIsSpawnedSafe() then return end
        if type(grndIsTyping) == 'function' and grndIsTyping() then return end
        local id = table.remove(W.statQueue, 1)
        if not id then return end
        local was = W.statAsked[id]
        if was then
            local gap = statGap(id)
            if gap and now - was < gap then return end
        end
        W.statAsked[id] = now
        W.statNextAt = now
        W.statTries[id] = (W.statTries[id] or 0) + 1
        pcall(_G.grndStatsRequest, id, 'wh')
    end
    function W.drawLabel(cx, top, d, covers)
        if type(renderDrawBox) ~= 'function' or type(renderFontDrawText) ~= 'function' then
            return false
        end
        local ops, height = W.labelLayout(cx, top, d, whMeasure)
        for i = 1, #ops do
            local o = ops[i]
            if o.kind == 'box' then
                pcall(renderDrawBox, o.x, o.y, o.w, o.h, o.col)
            end
        end
        for i = 1, #ops do
            local o = ops[i]
            if o.kind == 'text' then
                local f, outlined = whFont(o.px, o.shadow)
                if f then
                    local str = whAnsi(o.s)
                    local ty = o.y
                    if o.inY and o.inH and type(renderGetFontDrawHeight) == 'function' then
                        local okH, dh = pcall(renderGetFontDrawHeight, f)
                        if okH and type(dh) == 'number' and dh > 0 then
                            ty = math.floor(o.inY + (o.inH - dh) / 2 + 0.5)
                        end
                    end
                    if o.shadow and not outlined then
                        pcall(renderFontDrawText, f, str, o.x + 1, ty + 1, WH_C.textShadow)
                    end
                    pcall(renderFontDrawText, f, str, o.x, ty, o.col, true)
                end
            end
        end
        W.drawnAt = W.clock()
        return true
    end
    function W.labels(now, cx, cy, cz, sw, sh, covers, selfId)
        if not W.newwh then return end
        local ok
        for _, e in ipairs(W.players) do
            if e.id ~= selfId and pedFor(e.id) == e.ped then
                local good, x, y, z = pcall(getCharCoordinates, e.ped)
                if good and valid(x, y, z) then
                    local dist2 = (x - cx) ^ 2 + (y - cy) ^ 2 + (z - cz) ^ 2
                    if dist2 <= W.distance ^ 2 then
                        local dist = math.sqrt(dist2)
                        local hx, hy, hz = W.headTop(e, x, y, z)
                        local sx, sy = W.headPoint(hx, hy, hz, sw, sh)
                        if sx then
                            local cell = whCell(e.id)
                            local nick = e.nick
                            if (not nick or nick == '') and now - (e.nickAt or -999) > 5 then
                                nick = call(sampGetPlayerNickname, e.id)
                                e.nick, e.nickAt = nick, now
                            end
                            if not nick or nick == '' then nick = 'ID ' .. tostring(e.id) end
                            if W.autoStats and not (whFamily(cell) and whLevel(cell)) then
                                W.wantStats(e.id, dist)
                            end
                            local hp, armor = W.vitals(e)
                            local afk = false
                            if type(sampIsPlayerPaused) == 'function' then
                                local okA, pa = pcall(sampIsPlayerPaused, e.id)
                                afk = okA and pa and true or false
                            end
                            local d = {
                                nick = nick, family = whFamily(cell), lvl = whLevel(cell),
                                id = e.id, hp = hp, armor = armor,
                                known = (cell ~= nil), scale = whScale(),
                                afk = afk, nameColor = whPlayerColor(e.id),
                                spinT = now,
                            }
                            local h = W.labelHeight(d)
                            local top = sy - h
                            if W.drawLabel(sx, top, d, covers) then
                                ok = true
                                local bub = W.bubble and W.bubble[e.id]
                                if bub and now - (bub.at or -999) < W.BUBBLE_TTL then
                                    W.drawBubble(sx, top, bub.text, sh)
                                end
                            end
                        end
                    end
                end
            end
        end
        W.labelsDrawn = ok and true or false
    end
    function W.frame()
        if W.dirtyAt and os.clock()-W.dirtyAt>0.4 then
            W.dirtyAt=nil;pcall(grndCamCfgSave)
        end
        W.nativeTick()
        if (W.diagCount or 0)<60 or W.expanded then pcall(W.diagnose) end
        if not W.enabled or (not W.skeleton and not W.newwh) then
            if #W.players>0 then W.players={};W.scanAt=-999 end
            return
        end
        if type(isSampAvailable)=='function' and not isSampAvailable() then W.players={};W.scanAt=-999;return end
        if type(isPauseMenuActive)=='function' and isPauseMenuActive() then return end
        if type(getCharCoordinates)~='function' or type(convert3DCoordsToScreenEx)~='function' then return end
        if W.skeleton and type(renderDrawLine)~='function' then return end
        if W.newwh and (type(renderDrawBox)~='function' or type(renderFontDrawText)~='function') then return end
        local now=W.clock()
        if now<W.scanAt then W.scanAt=-999 end
        if now-W.scanAt>=0.5 then
            W.scanAt=now
            local old={};for _,e in ipairs(W.players) do old[e.id]=e end
            local list={}
            for id=0,1003 do
                local p=pedFor(id)
                if p then
                    local e=old[id]
                    if not e or e.ped~=p then e={id=id,ped=p} end
                    list[#list+1]=e
                end
            end
            W.players=list
        end
        local ok,cx,cy,cz=pcall(getActiveCameraCoordinates)
        if not ok or not valid(cx,cy,cz) then return end
        local sw,sh=getScreenResolution()
        local covers=nil
        if W.newwh and type(grndCheckerCovers)=='function' then
            local okC,c=pcall(grndCheckerCovers)
            if okC then covers=c end
        end
        local selfId=nil
        if type(sampGetPlayerIdByCharHandle)=='function' and PLAYER_PED then
            local okS,a,b=pcall(sampGetPlayerIdByCharHandle,PLAYER_PED)
            if okS then selfId=tonumber(type(a)=='boolean' and b or a) end
        end
        for _,e in ipairs(W.players) do
            if pedFor(e.id)==e.ped then
                local good,x,y,z=pcall(getCharCoordinates,e.ped)
                if good and valid(x,y,z) and (x-cx)^2+(y-cy)^2+(z-cz)^2<=W.distance^2 then
                    local sx=project(x,y,z+0.5,sw,sh)
                    if sx then bones(e,now,x,y,z,sw,sh) end
                end
            end
        end
        if W.newwh then pcall(W.labels,now,cx,cy,cz,sw,sh,covers,selfId) end
        pcall(W.statsTick)
    end
    function W.ui(C)
        local im,dl,at=C.im,C.dl,C.at
        local x,y,w=C.x,C.y,C.w
        local text,rect,col=C.uiText,C.roundRect,C.col32
        local hi=C.rgba(232,237,246,255)
        local dim=C.rgba(145,155,172,255)
        rect(dl,at(x,y),at(x+w,y+48),col(255,255,255,10),9)
        text(x+14,y+8,'WH на игроков',hi,1.02)
        text(x+14,y+28,'Штатные ник, HP и броня SA:MP',dim,0.83)
        if C.toggle(x+w-104,y+12,W.enabled,'wh_enabled') then
            W.setEnabled(not W.enabled)
        end
        im.SetCursorPos(im.ImVec2(x+w-44,y+10))
        if im.InvisibleButton('##wh_expand',im.ImVec2(32,28)) then W.expanded=not W.expanded end
        text(x+w-34,y+14,W.expanded and 'v' or '>',hi,1.1)
        if not W.expanded then return end
        local sw,sh=getScreenResolution()
        local sizeW=math.min(430,sw-16);local sizeH=244
        local pos=at(x+w-sizeW,y+52)
        im.SetNextWindowPos(im.ImVec2(math.max(8,math.min(sw-sizeW-8,pos.x)),
            math.max(8,math.min(sh-sizeH-8,pos.y))),C.cond)
        im.SetNextWindowSize(im.ImVec2(sizeW,sizeH),C.cond)
        if C.begin('##grnd_wh_settings',C.flags) then
            local wd=im.GetWindowDrawList();local wp=im.GetWindowPos()
            local function pt(a,b) return im.ImVec2(wp.x+a,wp.y+b) end
            text(14,12,'WH на игроков',hi,1.05)
            im.SetCursorPos(im.ImVec2(sizeW-34,8))
            if im.InvisibleButton('##wh_close',im.ImVec2(24,24)) then W.expanded=false end
            text(sizeW-28,12,'x',dim,0.95)
            text(14,49,'Дальность',hi,0.94)
            local ax,ay,aw=108,48,sizeW-185
            local fraction=(W.distance-10)/790
            rect(wd,pt(ax,ay+8),pt(ax+aw,ay+14),col(255,255,255,38),3)
            if aw*fraction>1 then rect(wd,pt(ax,ay+8),pt(ax+aw*fraction,ay+14),col(0,214,170,230),3) end
            im.SetCursorPos(im.ImVec2(ax-5,ay))
            im.InvisibleButton('##wh_distance',im.ImVec2(aw+10,24))
            if im.IsItemActive and im.IsItemActive() then
                local mp=im.GetMousePos and im.GetMousePos() or (im.GetIO and im.GetIO().MousePos)
                if mp then
                    local f=math.max(0,math.min(1,(mp.x-wp.x-ax)/aw))
                    W.distance=math.max(10,math.min(800,math.floor((10+790*f)/10+0.5)*10))
                    W.dirtyAt=os.clock()
                end
            end
            wd:AddCircleFilled(pt(ax+aw*((W.distance-10)/790),ay+11),6,col(240,245,250,255),16)
            text(sizeW-68,49,tostring(math.floor(W.distance))..' м',hi,0.9)
            im.SetCursorPos(im.ImVec2(14,86))
            if im.InvisibleButton('##wh_skeleton',im.ImVec2(sizeW-28,27)) then
                W.skeleton=not W.skeleton;W.dirtyAt=os.clock()
                if W.skeleton then W.initBones() end
            end
            rect(wd,pt(14,87),pt(34,107),col(255,255,255,35),4)
            if W.skeleton then
                wd:AddLine(pt(18,97),pt(23,102),col(0,214,170,255),2)
                wd:AddLine(pt(23,102),pt(31,91),col(0,214,170,255),2)
            end
            text(44,89,'Скелет',hi,0.96)
            im.SetCursorPos(im.ImVec2(14,140))
            if im.InvisibleButton('##wh_new',im.ImVec2(sizeW-28,27)) then
                W.devGate()
            end
            rect(wd,pt(14,141),pt(34,161),col(255,255,255,35),4)
            if W.newwh then
                wd:AddLine(pt(18,151),pt(23,156),col(0,214,170,255),2)
                wd:AddLine(pt(23,156),pt(31,145),col(0,214,170,255),2)
            end
            text(44,143,'Новый WH — таблички над игроками (в разработке)',hi,0.96)
            text(14,176,'В разработке; обычный WH — ники, HP и броня SA:MP.',dim,0.76)
            text(14,198,(W.skeleton and W.boneAttempt and not W.bone)
                and 'Кости недоступны в этой сборке.'
                or (W.nativeStatus or 'Ожидание проверки SA:MP...'),dim,0.76)
        end
        im.End()
    end
end
GRND_BULK={text='',lines={},delay=5,running=false,sent=0,index=1,
    status='Одна команда на строку. Отправка — только по кнопке «Выдать».',history={}}
do
    local B=GRND_BULK
    B.pairs={offjail='jail',offmute='mute',offban='ban',offwarn='warn'}
    function B.clock()
        if type(getGameTimer)=='function' then return getGameTimer()/1000 end
        return os.clock()
    end
    function B.split(text)
        local out={}
        local s=tostring(text or ''):gsub('\r\n','\n'):gsub('\r','\n')
        s=s:gsub(';%s*(/)','\n%1')
        for line in (s..'\n'):gmatch('([^\n]*)\n') do
            local t=line:match('^%s*(.-)%s*$')
            if t~='' and not t:match('^%-%-') and not t:match('^//') and not t:match('^#') then
                out[#out+1]=t
            end
        end
        return out
    end
    function B.ansi(s)
        if type(_G.grndToAnsi)=='function' then return _G.grndToAnsi(s) end
        if s:find('[\128-\255]') then return nil end
        return s
    end
    local function lower(s)
        s=B.ansi(tostring(s or ''))
        if not s then return nil end
        return (s:gsub('[\192-\223\168]',function(c)
            local n=c:byte();return string.char(n==168 and 184 or n+32)
        end):lower())
    end
    function B.findId(nick)
        if type(sampIsPlayerConnected)~='function' or type(sampGetPlayerNickname)~='function' then
            return nil,'Недоступен список игроков SA:MP.'
        end
        local key=lower(nick)
        if not key then return nil,'Ошибка кодировки ника.' end
        local found
        for id=0,1003 do
            local ok,on=pcall(sampIsPlayerConnected,id)
            if not ok then return nil,'Не удалось проверить список игроков.' end
            if on==true or on==1 then
                local good,name=pcall(sampGetPlayerNickname,id)
                if not good or type(name)~='string' then return nil,'Не удалось прочитать ник игрока.' end
                if lower(name)==key then
                    if found~=nil then return nil,'Неоднозначный ник: несколько совпадений.' end
                    found=id
                end
            end
        end
        return found
    end
    function B.resolve(raw)
        local cmd,gap,nick,tail=raw:match('^/(%a[%w_]*)(%s+)(%S+)(.*)$')
        if not cmd or nick:match('^%d+$') then return raw end
        local id,err=B.findId(nick)
        if err then return nil,err end
        if id==nil then return raw end
        local name=B.pairs[cmd:lower()] or cmd
        return '/'..name..gap..tostring(id)..tail
    end
    function B.clampDelay(value)
        local n=tonumber(value)
        if not n or n~=n then n=5 end
        return math.max(1,math.min(5,n))
    end
    function B.connected()
        B.connectionDetail=nil
        if type(isSampAvailable)=='function' then
            local ok,v=pcall(isSampAvailable)
            if not ok or v==false or v==0 then
                B.connectionDetail='SA:MP недоступен';return false
            end
        end
        if type(sampGetGamestate)=='function' then
            local ok,state=pcall(sampGetGamestate)
            state=ok and tonumber(state) or nil
            if state and state==math.floor(state) and state>=0 and state<=5 then
                B.connectionDetail='SA:MP state='..state
                return state==3
            end
            if state then
                B.connectionDetail='Неизвестное состояние SA:MP: '..tostring(state)
                return false
            end
        end
        if type(sampIsLocalPlayerConnected)=='function' then
            local ok,v=pcall(sampIsLocalPlayerConnected)
            if ok and (v==true or v==1) then B.connectionDetail='local-connected';return true end
            if ok and (v==false or v==0) then
                B.connectionDetail='локальный игрок отключён';return false
            end
        end
        local id
        if type(sampGetLocalPlayerId)=='function' then
            local ok,a,b=pcall(sampGetLocalPlayerId)
            if ok then
                if type(a)=='boolean' then if a then id=tonumber(b) end else id=tonumber(a) end
            end
        end
        if id==nil and type(sampGetPlayerIdByCharHandle)=='function' and PLAYER_PED then
            local ok,a,b=pcall(sampGetPlayerIdByCharHandle,PLAYER_PED)
            if ok then
                if type(a)=='boolean' then if a then id=tonumber(b) end else id=tonumber(a) end
            end
        end
        if id and id>=0 and id<=1003 and id==math.floor(id) and type(sampIsPlayerConnected)=='function' then
            local ok,on=pcall(sampIsPlayerConnected,id)
            if ok and (on==true or on==1) then B.connectionDetail='local-id='..id;return true end
        end
        B.connectionDetail='API подключения не подтвердил соединение'
        return false
    end
    function B.validate(line)
        if not line:match('^/%a[%w_]*') then return false,'Нужна команда со слэшем /.' end
        if line:find('[%z\1-\31\127]') then return false,'Управляющие символы в строке.' end
        local cp=B.ansi(line)
        if not cp then return false,'Не удалось преобразовать текст в CP1251.' end
        if #cp>128 then return false,'Команда длиннее 128 байт. Сократите её — обрезки не будет.' end
        return true,cp
    end
    function B.stop(message)
        B.running=false;B.nextAt=nil
        B.status=message or ('Остановлено. Отправлено: '..B.sent..' / '..tostring(B.total or 0))
    end
    function B.start()
        if B.running then return false end
        local queue=B.split(B.text)
        if #queue==0 then B.status='Список пуст.';return false end
        if #queue>500 then B.status='Максимум 500 команд за запуск.';return false end
        for i,line in ipairs(queue) do
            local ok,why=B.validate(line)
            if not ok then B.status='Строка '..i..': '..why;return false end
        end
        if not B.connected() then B.status='Нет подключения: '..tostring(B.connectionDetail or 'неизвестно');return false end
        B.queue=queue;B.total=#queue;B.index=1;B.sent=0;B.history={}
        B.delay=B.clampDelay(B.delay)
        B.runDelay=B.delay
        B.running=true;B.nextAt=B.clock();B.lastClock=B.nextAt
        B.status='Запущено: '..B.total..' команд; интервал '..B.runDelay..' сек.'
        return true
    end
    function B.tick()
        if B.dirtyAt and os.clock()-B.dirtyAt>0.5 then
            B.dirtyAt=nil;pcall(grndCamCfgSave)
        end
        if not B.running then return end
        if not B.connected() then B.stop('Соединение потеряно. Очередь остановлена.');return end
        local now=B.clock()
        if now<(B.lastClock or now) then B.stop('Игровой сеанс сменился. Очередь остановлена.');return end
        B.lastClock=now
        if now<B.nextAt then return end
        local raw=B.queue[B.index]
        if not raw then B.stop('Готово. Отправлено команд: '..B.sent..'. Результат проверяйте по ответам сервера.');return end
        local out,err=B.resolve(raw)
        if not out then B.stop('Строка '..B.index..': '..err);return end
        local valid,cp=B.validate(out)
        if not valid then B.stop('Строка '..B.index..': '..cp);return end
        if not B.connected() then B.stop('Соединение потеряно. Отправка отменена.');return end
        if type(sampSendChat)~='function' then B.stop('Отправка команд недоступна.');return end
        local ok,res=pcall(sampSendChat,cp)
        if not ok or res==false then B.stop('Ошибка отправки строки '..B.index..'. Повторите вручную после проверки.');return end
        B.sent=B.sent+1
        B.history[#B.history+1]={source=raw,sent=out}
        B.lastCommand=out
        B.index=B.index+1
        B.status='Отправлено: '..B.sent..' / '..B.total..'. Подтверждение — в ответе сервера.'
        B.nextAt=now+B.runDelay
        if B.index>B.total then B.stop('Отправлено: '..B.sent..' / '..B.total..'. Проверяйте ответы сервера.');end
    end
    function B.ensureBuffer(im)
        if B.buffer and B.bufferIm==im then return true end
        local ok,buf
        B.capacity=65536
        if im.new and im.new.char then
            ok,buf=pcall(function() return im.new.char[B.capacity]() end)
            if ok and buf then B.bufferKind='ffi' end
        end
        if not (ok and buf) and type(im.ImBuffer)=='function' then
            ok,buf=pcall(im.ImBuffer,B.capacity)
            if ok and buf then B.bufferKind='legacy' end
        end
        if not (ok and buf) then return false end
        B.buffer=buf;B.bufferIm=im;B.inputSig=nil
        if B.bufferKind=='ffi' then grndBinderWriteCBuf(buf,B.capacity,B.text)
        else pcall(function() buf.v=B.text end) end
        return true
    end
    function B.readBuffer()
        if not B.buffer then return B.text end
        if B.bufferKind=='ffi' then return grndBinderReadCBuf(B.buffer) end
        local ok,v=pcall(function() return B.buffer.v end)
        if not ok or v==nil then ok,v=pcall(function() return B.buffer.value end) end
        return ok and v~=nil and tostring(v) or B.text
    end
    function B.editor(im,w,h)
        if type(im.InputTextMultiline)~='function' then return false,'Нет многострочного ввода.' end
        local size=im.ImVec2(math.max(80,w),math.max(60,h))
        local function invoke(sig)
            if sig==1 then return im.InputTextMultiline('##grnd_bulk_text',B.buffer,B.capacity,size) end
            return im.InputTextMultiline('##grnd_bulk_text',B.buffer,size)
        end
        local sig=B.inputSig or (B.bufferKind=='legacy' and 2 or 1)
        local ok,res=pcall(invoke,sig)
        if not ok and not B.inputSig then sig=sig==1 and 2 or 1;ok,res=pcall(invoke,sig) end
        if ok then B.inputSig=sig end
        return ok,res
    end
    function B.draw(C)
        local im,dl,at=C.im,C.dl,C.at
        local x,y,w,h=C.x,C.y,C.w,C.h
        local text,rect,col=C.uiText,C.roundRect,C.col32
        local TH=grndUiTheme()
        local function color(t) return C.rgba(t[1],t[2],t[3],t[4] or 255) end
        local hi,dim=color(TH.textHi),color(TH.textMuted)
        local ac=TH.accent
        local function line(yy)
            dl:AddRectFilled(at(x+12,yy),at(x+w-12,yy+1),col(255,255,255,20))
        end
        local function center(yy,str,scale)
            local tw=C.tsize(str)*(scale or 1)
            text(x+12,yy,grndBinderFit(str,(w-24)/(scale or 1),C.tsize),hi,scale or 1)
        end
        center(y+12,'Пишите формы на наказание — скрипт проверит игроков.',0.86)
        center(y+31,'В сети: онлайн-команда и ID. Не в сети: без изменений.',0.84)
        line(y+49)
        local ty=y+63
        text(x+12,ty+7,'Строк к выдаче: '..#B.lines,hi,0.9)
        local bx=x+146;local bw=85
        local enabled=B.running or #B.lines>0
        local clicked=grndUiButton(C,'##grnd_bulk_send',bx,ty,bw,30,
            B.running and 'Стоп' or 'Выдать',
            {selected=enabled and not B.running,danger=B.running,muted=not enabled})
        if clicked then
            if B.running then B.stop() elseif enabled then B.start() end
        end
        local stacked=w<540
        local delayX=stacked and (x+12) or (bx+bw+18)
        local delayY=stacked and (ty+43) or ty
        local sw=math.max(40,w-(delayX-x)-90)
        local delay,changed=C.slider(delayX,delayY+3,sw,B.clampDelay(B.delay),1,5,0.5,'bulk_delay')
        if changed and not B.running then B.delay=B.clampDelay(delay);B.dirtyAt=os.clock() end
        text(delayX+sw+12,delayY+6,string.format('%.1f сек.',B.running and B.runDelay or B.delay),hi,0.87)
        text(delayX,delayY+28,B.running and 'Интервал зафиксирован на время выдачи' or 'Задержка между командами',dim,0.76)
        local iy=delayY+55;local ih=math.max(60,y+h-iy-57)
        rect(dl,at(x+10,iy-2),at(x+w-10,iy+ih+2),col(TH.bg[1],TH.bg[2],TH.bg[3],255),6)
        if dl.AddRect then pcall(dl.AddRect,dl,at(x+10,iy-2),at(x+w-10,iy+ih+2),col(255,255,255,22),6,0,1) end
        if B.ensureBuffer(im) then
            local pushed=0
            for _,entry in ipairs({{'FrameBg',TH.bg[1],TH.bg[2],TH.bg[3],255},
                {'FrameBgHovered',TH.sidebar[1],TH.sidebar[2],TH.sidebar[3],255},
                {'FrameBgActive',TH.bg[1],TH.bg[2],TH.bg[3],255},
                {'Text',TH.textHi[1],TH.textHi[2],TH.textHi[3],255},
                {'TextSelectedBg',ac[1],ac[2],ac[3],65}}) do
                local colorId=im.Col and im.Col[entry[1]]
                if colorId~=nil and im.PushStyleColor then
                    local ok=pcall(im.PushStyleColor,colorId,im.ImVec4(entry[2]/255,entry[3]/255,entry[4]/255,entry[5]/255))
                    if ok then pushed=pushed+1 end
                end
            end
            im.SetCursorPos(im.ImVec2(x+10,iy))
            local ok,err=B.editor(im,w-20,ih)
            if pushed>0 then grndBinderPopColors(im,pushed) end
            if not ok then text(x+16,iy+12,'Ошибка поля ввода: '..tostring(err),hi,0.85) end
            local current=B.readBuffer()
            if current~=B.text then B.text=current;B.lines=B.split(current) end
        else text(x+16,iy+12,'Многострочное поле недоступно в этой сборке ImGui.',hi,0.88) end
        line(y+h-50)
        local status=B.status
        local shown=status
        do
            while C.tsize(shown)*0.8>w-38 and #shown>6 do
                shown=shown:gsub('[%z\1-\127\194-\244][\128-\191]*$','')
            end
            if shown~=status then shown=shown..'...' end
        end
        text(x+12,y+h-43,shown,hi,0.8)
        text(x+12,y+h-23,B.running and 'Правки текста попадут только в следующий запуск. «Стоп» отменяет остаток.'
            or 'Максимум 500 команд. Закрытие меню не останавливает запущенную очередь.',dim,0.76)
    end
end
