local GRND_REPHUD = {
    enabled = false,
    items = {},
    max = 12,
    scale = 1.0,
    x = 16,
    y = 90,
    dragging = false,
    dragDX = 0,
    dragDY = 0,
}
_G.GRND_REPHUD = GRND_REPHUD
GRND_REPHUD.clampScale = function(v)
    v = tonumber(v) or 1.0
    if v < 0.7 then v = 0.7 elseif v > 1.6 then v = 1.6 end
    return math.floor(v * 20 + 0.5) / 20
end
GRND_REPHUD.metrics = function(scale, basePx, rows, fpx)
    local k = GRND_REPHUD.clampScale(scale)
    basePx = tonumber(basePx) or 16
    if basePx < 8 then basePx = 8 elseif basePx > 40 then basePx = 40 end
    local want = math.floor(basePx * k + 0.5)
    fpx = tonumber(fpx) or want
    if fpx < 9 then fpx = 9 elseif fpx > 40 then fpx = 40 end
    local us = fpx / basePx
    local function S(v) return math.floor(v * us + 0.5) end
    rows = math.max(0, math.floor(tonumber(rows) or 0))
    local m = {
        k = k, fpx = fpx, want = want, us = us, rows = rows,
        sh = S(6),
        W = S(180), minW = S(180), maxW = S(440),
        rowH = math.max(S(27), fpx + S(11)),
        headH = math.max(S(40), fpx + S(22)), pad = S(14), gap = S(9),
    }
    if rows > 0 then
        m.Hgt = 2 * m.sh + m.headH + m.gap + rows * m.rowH + m.gap
    else
        m.Hgt = 2 * m.sh + m.headH + S(52)
    end
    return m
end
