GRND_CLOCK.clampScale = function(v)
    v = tonumber(v) or 1.60
    if v < 0.75 then v = 0.75 elseif v > 4.00 then v = 4.00 end
    return math.floor(v * 20 + 0.5) / 20
end
function grndClockText()
    local months = {
        [1] = "января", [2] = "февраля", [3] = "марта", [4] = "апреля",
        [5] = "мая", [6] = "июня", [7] = "июля", [8] = "августа",
        [9] = "сентября", [10] = "октября", [11] = "ноября", [12] = "декабря",
    }
    local weekdays = {
        [1] = "воскресенье", [2] = "понедельник", [3] = "вторник",
        [4] = "среда", [5] = "четверг", [6] = "пятница", [7] = "суббота",
    }
    local ok, now = pcall(os.date, "*t")
    if not ok or type(now) ~= "table" then
        return os.date("%H:%M:%S"), ""
    end
    local hour = tonumber(now.hour) or 0
    local minute = tonumber(now.min) or 0
    local second = tonumber(now.sec) or 0
    local day = tonumber(now.day) or 1
    local month = tonumber(now.month) or 1
    local year = tonumber(now.year) or 1970
    local wday = tonumber(now.wday) or 1
    return string.format("%02d:%02d:%02d", hour, minute, second),
        string.format("%d %s %d г., %s", day, months[month] or "", year,
            weekdays[wday] or "")
end
function grndClockStartMoving()
    local C = GRND_CLOCK
    if not C then return false end
    C.moveOldX, C.moveOldY = C.x, C.y
    C.moving, C.dragging, C.escapeDown = true, false, false
    C.mouseWasDown, C.cancelMove = false, false
    C.followCursor = true
    C.moveReadyAt = os.clock() + 0.35
    C.enabled = true
    if _G.GRND_MENU then _G.GRND_MENU.open = false end
    if type(clwShowCursor) == "function" then pcall(clwShowCursor, true) end
    if type(grndUiControls) == "function" then pcall(grndUiControls, true) end
    if type(ensureRender) == "function" then pcall(ensureRender, true) end
    if type(notify) == "table" and type(notify.add) == "function" then
        pcall(notify.add, "Дата и время: ЛКМ — закрепить, ESC — отмена", "info", 4)
    end
    return true
end
function grndClockStopMoving(cancel)
    local C = GRND_CLOCK
    if not C then return false end
    if cancel and C.moveOldX ~= nil then
        C.x, C.y = C.moveOldX, C.moveOldY
    end
    C.moving, C.dragging, C.escapeDown = false, false, false
    C.mouseWasDown, C.cancelMove = false, false
    C.followCursor, C.moveReadyAt = false, 0
    if type(grndUiControls) == "function" then pcall(grndUiControls, false) end
    if type(grndCamCfgSave) == "function" then pcall(grndCamCfgSave) end
    if type(notify) == "table" and type(notify.add) == "function" then
        pcall(notify.add, cancel and "Дата и время: перемещение отменено"
            or "Дата и время: позиция сохранена", cancel and "warn" or "ok", 3)
    end
    return true
end
local GRND_CHAT = {
    key = 0x54,
    binding = false,
    expanded = false,
    anim = 0,
    timestamps = false,
    lines = 10,
    ids = true,
}
_G.GRND_CHAT = GRND_CHAT
GRND_INPUT = {
    enabled=true, showHistory=true, channel="normal", admin=false, family=false,
    history={}, maxHistory=100, visibleRows=7, scroll=0, metaScale=1.60, historyRadius=18,
    historyScale=1.05, historyRow=28, historyFrame=68,
    ownedKeys={}, opened=false, openedAt=0, hideUntil=0,
}
do
    local C=GRND_INPUT
    local function modeName(value)
        if value==true or value=='admin' then return 'admin' end
        if value=='family' then return 'family' end
        return 'normal'
    end
    C.channels={
        normal={id='normal',label='Обычный',hint='Обычный чат',prefix='',rgb={246,250,255}},
        admin={id='admin',label='Админский',hint='Админ чат',prefix='/a ',rgb={255,86,102}},
        family={id='family',label='Семейный',hint='Семейный чат',prefix='/f ',rgb={255,214,65}},
    }
    function C.currentMode() return modeName(C.channel) end
    function C.channelInfo(value)
        if value==nil then value=C.currentMode() end
        return C.channels[modeName(value)]
    end
    local function call(fn,...)
        if type(fn)~='function' then return nil end
        local ok,a,b=pcall(fn,...)
        if not ok then return nil end
        if type(a)=='boolean' and b~=nil then return a and b or nil end
        return a
    end
    local function clock() return os.clock() end
    local function utf(s)
        if type(_G.grndUtf8Text)=='function' then return _G.grndUtf8Text(s) end
        return tostring(s or '')
    end
    local function consume() grndConsumeMsg(false) end
    local function inside(r,x,y)
        return r and x and y and x>=r.x and x<=r.x+r.w and y>=r.y and y<=r.y+r.h
    end
    function C.keyHeld(vk)
        if grndGAKS then
            local ok,value=pcall(grndGAKS,vk)
            if ok and value~=nil then return (tonumber(value) or 0)%65536>=32768 end
        end
        return call(isKeyDown,vk)==true
    end
    function C.active()
        if not C.enabled or (GRND_CAM and GRND_CAM.windowFocused==false) then return false end
        if call(sampIsChatInputActive)~=true or call(sampIsDialogActive)==true then return false end
        if call(isPauseMenuActive)==true then return false end
        if type(grndSessionReady)=='function' and call(grndSessionReady)~=true then return false end
        return true
    end
    function C.wanted() return C.active() or clock()<(C.hideUntil or 0) end
    function C.readText()
        for _,name in ipairs({'sampGetChatInputText','sampGetChatInput','getChatInput'}) do
            local value=call(_G[name])
            if type(value)=='string' then return value end
        end
        return nil
    end
    function C.writeText(value)
        value=tostring(value or '')
        for _,name in ipairs({'sampSetChatInputText','sampSetChatInput','setChatInput'}) do
            local fn=_G[name]
            if type(fn)=='function' then
                local ok,result=pcall(fn,value)
                if ok and result~=false and C.readText()==value then return true end
            end
        end
        return false
    end
    function C.fail(message)
        local now=clock()
        local repeatNotice=C.error==message and now<(C.errorUntil or 0)
        C.error,C.errorUntil=message,now+4
        if not repeatNotice and notify and type(notify.add)=='function' then
            pcall(notify.add,message,'warn',4)
        end
    end
    local function historyText(raw)
        local tag,body=raw:match('^%s*/([aAfF])%s+(.*)$')
        if body and body:find('%S') then
            return body,'message',tag:lower()=='f' and 'family' or 'admin'
        end
        return raw,raw:match('^%s*/') and 'command' or 'message',nil
    end
    function C.ensureInput()
        local repair=C.inputRepair
        if not repair then return true end
        local current=C.readText()
        if current=='' then C.inputRepair=nil;C.ticket=nil;return true end
        if C.writeText(repair.raw) then
            C.inputRepair=nil
            return true
        end
        C.fail(repair.reason);return false
    end
    function C.replaceText(value,reason)
        local before=C.readText()
        if before==nil then C.fail(reason);return false end
        if C.writeText(value) then return true end
        if C.readText()~=before and not C.writeText(before) then
            C.inputRepair={raw=before,reason=reason}
        end
        C.fail(reason);return false
    end
    function C.commitPending(force)
        local ticket=C.ticket
        if ticket and (force or call(sampIsChatInputActive)==false) then
            C.ticket=nil
            if ticket.record~=false then C.remember(ticket.raw,ticket.mode,ticket.wire,ticket.kind) end
            return true
        end
        return false
    end
    function C.syncNativeRecall()
        local pending=C.nativeRecallPending
        if not pending then return true end
        if not C.ensureInput() then return false end
        local raw=C.readText()
        if raw==nil then C.fail('Не удалось прочитать историю штатного ввода. Отправка отменена.');return false end
        if not pending.body then
            if raw==pending.before then C.nativeRecallPending=nil;return true end
            pending.body,pending.kind=historyText(raw)
        end
        if raw~=pending.body and not C.replaceText(pending.body,
            'Не удалось убрать старый /a или /f из истории. Сообщение не отправлено.') then return false end
        C.nativeRecallPending=nil
        C.browse,C.draft=nil,nil
        C.loadedRecall,C.recallKind=pending.body,pending.kind
        return true
    end
    function C.restoreTicket()
        local ticket=C.ticket
        if not ticket then return true end
        local current=C.readText()
        if current==nil then C.fail('Не удалось восстановить ввод. Отправка отменена.');return false end
        if current~=ticket.wire then C.commitPending(true);return true end
        if ticket.wire~=ticket.raw and not C.replaceText(ticket.raw,
            'Не удалось сменить канал сообщения. Отправка отменена.') then return false end
        ticket.wire,ticket.prepared=ticket.raw,false
        C.loadedRecall,C.recallKind=ticket.raw,ticket.kind
        return true
    end
    function C.setMode(value)
        C.commitPending()
        local ready=C.ensureInput() and C.syncNativeRecall()
        local selected=modeName(value)
        if C.currentMode()~=selected and ready then ready=C.restoreTicket() end
        C.channel=selected
        C.admin,C.family=selected=='admin',selected=='family'
        if ready then C.error,C.errorUntil=nil,nil end
    end
    function C.cycleMode()
        local nextMode={normal='admin',admin='family',family='normal'}
        C.setMode(nextMode[C.currentMode()])
    end
    function C.setEnabled(enabled)
        C.enabled=enabled and true or false
        C.setMode(false)
        C.browse,C.draft,C.loadedRecall,C.recallKind,C.ticket=nil,nil,nil,nil,nil
        C.nativeRecallPending=nil
        C.hit,C.drag,C.nativeMouse,C.mouseCaptured=nil,nil,nil,nil
        C.hideUntil=clock()+0.25
    end
    function C.clear()
        C.history={};C.scroll=0
        C.browse,C.draft,C.ticket=nil,nil,nil
    end
    local privateCommands={login=true,register=true,reg=true,password=true,
        changepass=true,changepassword=true,auth=true,pin=true}
    function C.remember(raw,value,wire,kind)
        if not raw or raw:match('^%s*$') then return end
        local mode=modeName(value)
        if kind~='message' then
            local historicalMode
            raw,kind,historicalMode=historyText(raw)
            if historicalMode then mode=historicalMode end
        end
        local command=raw:match('^%s*/([^%s]+)')
        if command and privateCommands[command:lower()] then return end
        local last=C.history[#C.history]
        local lastMode=last and (last.channel or modeName(last.admin))
        if last and last.raw==raw and lastMode==mode and last.kind==kind then
            last.time=os.date('%H:%M');last.wire=wire
        else
            C.history[#C.history+1]={raw=raw,channel=mode,admin=mode=='admin',family=mode=='family',
                wire=wire,kind=kind,text=utf(raw):gsub('[%z\1-\31\127]',' '),time=os.date('%H:%M')}
            while #C.history>C.maxHistory do table.remove(C.history,1) end
        end
        C.scroll=0;C.browse,C.draft,C.loadedRecall,C.recallKind=nil,nil,nil,nil
    end
    function C.prepareEnter()
        if not C.ensureInput() or not C.syncNativeRecall() then
            if C.ticket then C.ticket.record=false end
            return false
        end
        local mode=C.currentMode()
        local info=C.channelInfo(mode)
        local raw=C.readText()
        if raw==nil then
            if mode=='normal' and not C.ticket then return true end
            if C.ticket then C.ticket.record=false end
            C.fail(info.hint..': API ввода недоступен. Отправка отменена.');return false
        end
        local ticket=C.ticket
        if ticket then
            if raw~=ticket.wire then C.commitPending(true)
            elseif ticket.mode~=mode or not ticket.prepared or ticket.record==false then
                if not C.restoreTicket() then ticket.record=false;return false end
                raw=C.readText()
            elseif ticket.prepared then ticket.at=clock();return true end
        end
        if raw:match('^%s*$') then return true end
        C.noteEdit()
        local kind=(C.loadedRecall==raw and C.recallKind)
            or (raw:match('^%s*/') and 'command' or 'message')
        local body=raw
        if mode~='normal' then
            if kind~='message' then
                local payload,_,explicitMode=historyText(raw)
                if explicitMode==mode then body=payload end
            end
            kind='message'
        else
            kind=raw:match('^%s*/') and 'command' or 'message'
        end
        local wire=info.prefix..body
        if #wire>128 then
            if C.ticket then C.ticket.record=false end
            C.fail(mode~='normal' and (info.hint..': максимум 125 символов + '..info.prefix:gsub('%s+$','')..'. Сократите сообщение.')
                or 'Чат: сообщение длиннее лимита 128 байт.');return false
        end
        if wire~=raw and not C.replaceText(wire,
            'Ошибка ввода ('..info.label..'): сообщение не отправлено.') then
            if C.ticket then C.ticket.record=false end
            return false
        end
        C.ticket={raw=body,wire=wire,mode=mode,kind=kind,prepared=true,record=true,at=clock()}
        C.error,C.errorUntil=nil,nil
        return true
    end
    function C.noteEdit()
        local raw=C.readText()
        if C.ticket and raw==C.ticket.wire then return end
        if raw~=nil and C.loadedRecall and C.loadedRecall~=raw then
            C.browse,C.draft,C.loadedRecall,C.recallKind=nil,nil,nil,nil
        end
    end
    function C.reveal(index)
        local visible=C.pageRows or C.visibleRows
        local first=math.max(1,#C.history-visible-C.scroll+1)
        local last=math.min(#C.history,first+visible-1)
        if index<first then C.scroll=math.max(0,#C.history-visible-index+1)
        elseif index>last then C.scroll=math.max(0,#C.history-index) end
    end
    function C.recall(index)
        local entry=C.history[index]
        if not entry then return false end
        if not C.ensureInput() or not C.syncNativeRecall() or not C.restoreTicket() then return false end
        C.noteEdit()
        local draft=C.draft
        if not C.browse then
            local current=C.readText() or ''
            draft={raw=current,kind=(C.loadedRecall==current and C.recallKind)
                or (current:match('^%s*/') and 'command' or 'message')}
        end
        local body,kind=entry.raw,entry.kind
        if not kind then body,kind=historyText(body) end
        if not C.replaceText(body,'Не удалось вернуть сообщение в штатную строку.') then return false end
        C.draft,C.browse,C.loadedRecall,C.recallKind=draft,index,body,kind
        C.ticket=nil;C.error=nil
        C.reveal(index)
        return true
    end
    function C.navigate(direction)
        if not C.ensureInput() or not C.syncNativeRecall() then return false end
        C.noteEdit()
        if #C.history==0 then return false end
        if direction<0 then return C.recall(math.max(1,(C.browse or (#C.history+1))-1)) end
        if not C.browse then return true end
        if C.browse<#C.history then return C.recall(C.browse+1) end
        local draft=C.draft or {raw='',kind='message'}
        if not C.restoreTicket() or not C.replaceText(draft.raw,
            'Не удалось восстановить черновик. Отправка отменена.') then return false end
        C.browse,C.draft,C.ticket=nil,nil,nil
        C.loadedRecall,C.recallKind=draft.raw,draft.kind
        C.scroll=0;return true
    end
    function C.scrollBy(amount)
        local maximum=math.max(0,#C.history-(C.pageRows or C.visibleRows))
        C.scroll=math.max(0,math.min(maximum,C.scroll+amount))
    end
    function C.geometry()
        local sx,sy=1280,720
        if type(getScreenResolution)=='function' then
            local ok,x,y=pcall(getScreenResolution)
            if ok and tonumber(x) and tonumber(y) then sx,sy=x,y end
        end
        local W=GRND_WH
        local mem=memory or (libs and libs.memory)
        local rd=mem and (mem.getint32 or mem.readint32)
        if W and W.rangeAccessible and W.normalizePointer and rd then
            local p=W.normalizePointer(call(sampGetInputInfoPtr))
            if p and W.rangeAccessible(p+8,4) then
                local edit=W.normalizePointer(call(rd,p+8))
                if edit and W.rangeAccessible(edit+8,16) then
                    local x,y,w,h=call(rd,edit+8),call(rd,edit+12),call(rd,edit+16),call(rd,edit+20)
                    if x and y and w and h and x>=0 and y>=0 and x<sx-100 and y<sy-16
                        and w>=120 and w<=sx*2 and h>=16 and h<=120 then
                        C.geometrySource='штатный CDXUTEditBox (только чтение)'
                        C.rect={x=x,y=y,w=math.min(w,sx-x-8),h=h,native=true}
                        return C.rect,sx,sy
                    end
                end
            end
        end
        local lineHeight=20
        if GRND_CHAT and GRND_CHAT.dbg and GRND_CHAT.dbg.charH then
            lineHeight=math.max(14,math.min(32,tonumber(GRND_CHAT.dbg.charH) or 20))
        end
        local x=math.min(40,math.max(8,sx-240))
        local y=math.max(8,math.min(sy-140,40+((GRND_CHAT and GRND_CHAT.lines) or 10)*lineHeight))
        C.geometrySource='резервная привязка (API геометрии недоступен)'
        C.rect={x=x,y=y,w=math.max(120,math.min(800,sx-x-12)),h=0,native=false}
        return C.rect,sx,sy
    end
    function C.layout(measure,actualFontHeight)
        local r,sx,sy=C.geometry()
        local fontHeight=math.ceil(tonumber(actualFontHeight) or 16*C.metaScale)
        local rowHeight=math.max(20,fontHeight+2)
        local oldRowHeight=math.max(32,math.ceil(16*C.metaScale)+4)
        local topPadding=math.max(0,math.floor((oldRowHeight-rowHeight)/2))
        local meta={x=r.x,y=r.y+r.h+2,w=r.w,h=topPadding+rowHeight}
        local origin=r.x+12
        local maxWidth=math.max(40,sx-r.x-8)
        local available=math.max(0,maxWidth-24)
        local gap=18
        local widths,total={},0
        for index,name in ipairs({'normal','admin','family'}) do
            widths[index]=measure(C.channels[name].label,C.metaScale)+32
            total=total+widths[index]
        end
        local space=measure(' ',C.metaScale)
        local fullLayout='Раскладка: '..(C.layoutName or 'не определена')
        local shortLayout='Раскладка: '..(C.layoutShort or '--')
        local choices={
            {'TAB для смены чата |',fullLayout},
            {'TAB для смены чата |',shortLayout},
            {'TAB - смена чата |',shortLayout},
            {'TAB |',shortLayout},
            {'TAB |',C.layoutShort or '--'},
        }
        local tabText,layoutText,tabWidth,layoutWidth
        local infoGap=space
        for _,choice in ipairs(choices) do
            tabText,layoutText=choice[1],choice[2]
            tabWidth=measure(tabText,C.metaScale);layoutWidth=measure(layoutText,C.metaScale)
            if total+3*gap+tabWidth+infoGap+layoutWidth<=available then break end
        end
        if total+3*gap+tabWidth+infoGap+layoutWidth>available then
            gap=math.min(18,math.max(0,math.floor((available-60)/4)))
            local reserve=math.min(tabWidth+infoGap+layoutWidth,math.max(0,available-60-3*gap))
            local budget=math.max(0,available-3*gap-reserve)
            total=0
            for index=1,3 do widths[index]=math.min(widths[index],budget/3);total=total+widths[index] end
            local rest=math.max(0,available-total-3*gap)
            tabWidth=math.min(tabWidth,rest)
            infoGap=math.min(infoGap,math.max(0,rest-tabWidth))
            layoutWidth=math.min(layoutWidth,math.max(0,rest-tabWidth-infoGap))
        end
        local groups={}
        local x,y=origin,meta.y+topPadding
        for index,name in ipairs({'normal','admin','family'}) do
            groups[#groups+1]={kind=name,text=C.channels[name].label,
                x=x,y=y,w=widths[index],h=rowHeight,hitPad=math.min(3,gap/2)}
            x=x+widths[index]+gap
        end
        groups[#groups+1]={kind='tab',text=tabText,x=x,y=y,w=tabWidth,h=rowHeight}
        groups[#groups+1]={kind='layout',text=layoutText,
            x=x+tabWidth+infoGap,y=y,w=layoutWidth,h=rowHeight}
        local rowWidth=total+3*gap+tabWidth+infoGap+layoutWidth
        meta.w=math.min(maxWidth,math.max(r.w,rowWidth+24))
        local metaAbove=meta.y+meta.h>sy-8 and r.y>meta.h+6
        if metaAbove then
            local shift=r.y-meta.h-4-meta.y
            meta.y=meta.y+shift
            for _,group in ipairs(groups) do group.y=group.y+shift end
        end
        local panelY=meta.y+meta.h+2
        local room=sy-panelY-10
        local above=metaAbove
        local minimum=C.historyFrame+C.historyRow
        if metaAbove then room=meta.y-6
        elseif room<minimum and r.y>minimum+6 then room=r.y-6;above=true end
        local visible=math.max(1,math.min(C.visibleRows,math.floor((room-C.historyFrame)/C.historyRow)))
        local panelH=math.max(minimum,math.min(room,C.historyFrame+visible*C.historyRow))
        if above then panelY=math.max(4,(metaAbove and meta.y or r.y)-panelH-2) end
        C.pageRows=visible;C.scrollBy(0)
        local panel=C.showHistory and room>=minimum and {x=r.x,y=panelY,w=r.w,h=panelH} or nil
        local warning=not panel and C.error and {x=r.x,
            y=metaAbove and math.max(4,meta.y-28) or meta.y+meta.h+2,w=r.w,h=24} or nil
        local top=math.min(r.y,meta.y,panel and panel.y or meta.y,warning and warning.y or meta.y)-4
        local bottom=math.max(r.y+r.h,meta.y+meta.h,panel and panel.y+panel.h or meta.y+meta.h,
            warning and warning.y+warning.h or 0)+4
        return {input=r,meta=meta,groups=groups,panel=panel,warning=warning,
            window={x=r.x-4,y=math.max(0,top),w=meta.w+8,h=bottom-math.max(0,top)},sx=sx,sy=sy}
    end
    function C.updateLayoutLanguage()
        if not C.layoutWinTried then
            C.layoutWinTried=true
            local ok,F=pcall(require,'ffi')
            if ok and F.os=='Windows' then
                pcall(F.cdef,'void* __stdcall GetKeyboardLayout(unsigned long threadId);')
                local loaded,user=pcall(F.load,'user32')
                if loaded then
                    C.getLayout=function()
                        return tonumber(F.cast('uintptr_t',user.GetKeyboardLayout(0)))
                    end
                end
            end
        end
        local now=clock()
        if now<(C.nextLayoutAt or 0) then return end
        C.nextLayoutAt=now+0.12
        local value=call(C.getLayout)
        if value then
            local language=value%1024
            local known={ [0x19]={'Русский','RU'},[0x09]={'Английский','EN'},
                [0x22]={'Украинский','UK'},[0x23]={'Белорусский','BE'},
                [0x07]={'Немецкий','DE'},[0x0C]={'Французский','FR'},
                [0x0A]={'Испанский','ES'},[0x1F]={'Турецкий','TR'} }
            local names=known[language] or {('0x%04X'):format(value%65536),'?'}
            C.layoutName,C.layoutShort=names[1],names[2]
        else C.layoutName,C.layoutShort='не определена','--' end
    end
    function C.tick()
        C.commitPending()
        local native=call(sampIsChatInputActive)==true
        local active=C.active()
        if native and not C.nativeOpened then
            C.scroll=0
            C.browse,C.draft,C.loadedRecall,C.recallKind=nil,nil,nil,nil
            C.nativeRecallPending=nil
            C.geometry()
        elseif not native and C.nativeOpened then
            C.browse,C.draft,C.loadedRecall,C.recallKind=nil,nil,nil,nil
            C.nativeRecallPending,C.inputRepair=nil,nil
        end
        C.nativeOpened=native
        if active and not C.opened then C.openedAt=clock()
        elseif not active and C.opened then
            C.hideUntil=clock()+0.25
            C.hit,C.drag,C.nativeMouse,C.mouseCaptured=nil,nil,nil,nil
        end
        C.opened=active
        if active then
            C.syncNativeRecall();C.noteEdit();C.updateLayoutLanguage()
        end
        if C.error and clock()>(C.errorUntil or 0) then C.error=nil end
        if grndGAKS and C.tabHeld and not C.keyHeld(0x09) then C.tabHeld=false end
    end
    function C.onMessage(msg,wp,lp)
        local down=msg==0x0100 or msg==0x0104
        local up=msg==0x0101 or msg==0x0105
        local rc=_G.GRND_RC
        if up and (wp==0x26 or wp==0x28) and rc and rc.camKeys then rc.camKeys[wp]=false end
        if call(sampIsDialogActive)==true then
            if up and wp==0x09 then grndTapEnd(wp) end
            C.ownedKeys={};C.tabHeld,C.enterHeld,C.enterRepeat,C.blockEnter=nil,nil,nil,nil
            C.drag,C.nativeMouse,C.mouseCaptured=nil,nil,nil;return false
        end
        if msg==0x001C and wp==0 or msg==0x0008 then
            C.ownedKeys={};C.tabHeld,C.enterHeld,C.enterRepeat,C.blockEnter=nil,nil,nil,nil
            C.drag,C.nativeMouse,C.mouseCaptured=nil,nil,nil;grndTapEnd(0x09);return false
        end
        if up then
            if wp==0x09 then C.tabHeld=false;grndTapEnd(wp) end
            if wp==0x0D then C.enterHeld,C.enterRepeat,C.blockEnter,C.charEnterSeen=nil,nil,nil,nil end
            if C.ownedKeys[wp] then C.ownedKeys[wp]=nil;consume();return true end
        end
        if msg==0x0102 and ((wp==0x09 and C.ownedKeys[0x09])
            or (wp==0x0D and (C.blockEnter or C.enterRepeat))) then consume();return true end
        if not C.active() then C.tick();return false end
        if not C.opened then C.tick() end
        if C.nativeRecallPending and not (down and (wp==0x26 or wp==0x28)) then C.syncNativeRecall() end
        if down and wp==0x1B then C.ticket=nil;C.nativeRecallPending=nil end
        local repeatKey=math.floor((tonumber(lp) or 0)/1073741824)%2==1
        if down and wp==0x09 and msg==0x0100 and not C.keyHeld(0x12) and not C.keyHeld(0x11) then
            if not repeatKey and not C.tabHeld then C.cycleMode() end
            C.tabHeld=true;C.ownedKeys[wp]=true
            grndTapBegin(wp)
            GRND_TAB.held=false;consume();return true
        end
        if down and wp==0x0D then
            if C.enterHeld or repeatKey then C.enterRepeat=true;consume();return true end
            C.enterHeld=true;C.enterRepeat=false;C.charEnterSeen=false
            C.blockEnter=not C.prepareEnter()
            if C.blockEnter then C.ownedKeys[wp]=true;consume() end
            return true
        end
        if msg==0x0102 and wp==0x0D then
            if C.charEnterSeen then consume();return true end
            C.charEnterSeen=true
            if not C.prepareEnter() then C.blockEnter=true;consume() end
            return true
        end
        if down and (wp==0x26 or wp==0x28)
            and not C.keyHeld(0x11) and not C.keyHeld(0x12) and not C.keyHeld(0x10) then
            if #C.history>0 then
                C.navigate(wp==0x26 and -1 or 1)
                C.ownedKeys[wp]=true;consume();return true
            end
            if not C.ensureInput() or not C.restoreTicket() then consume();return true end
            C.ticket=nil
            C.nativeRecallPending={before=C.readText()}
            return true
        end
        if msg<0x0200 or msg>0x020E then return false end
        local mx,my
        if msg==0x020A or msg==0x020E then
            mx,my=C.mouseX,C.mouseY
        else
            mx,my=grndMouseXY(lp);C.mouseX,C.mouseY=mx,my
        end
        local hit=C.hit
        if msg==0x0202 and C.nativeMouse then C.nativeMouse=nil;return true end
        if C.drag then
            if msg==0x0202 then C.drag,C.mouseCaptured=nil,nil;consume();return true end
            if msg==0x0200 and hit and hit.track and hit.thumb then
                local maxScroll=math.max(0,#C.history-C.pageRows)
                local span=math.max(1,hit.track.h-hit.thumb.h)
                local fraction=math.max(0,math.min(1,(my-C.drag.offset-hit.track.y)/span))
                C.scroll=math.floor((1-fraction)*maxScroll+0.5)
            end
            consume();return true
        end
        if C.mouseCaptured and msg==0x0202 then C.mouseCaptured=nil;consume();return true end
        if hit and clock()-(C.drawAt or -10)<0.5 and inside(hit.panel,mx,my) then
            if msg==0x020A then
                local delta=math.floor((tonumber(wp) or 0)/65536)%65536
                if delta>=32768 then delta=delta-65536 end
                if delta~=0 then C.scrollBy((delta>0 and 1 or -1)*math.max(1,math.floor(math.abs(delta)/120))*3) end
            elseif msg==0x0201 or msg==0x0203 then
                C.mouseCaptured=true
                if inside(hit.track,mx,my) then
                    if inside(hit.thumb,mx,my) then C.drag={offset=my-hit.thumb.y}
                    else
                        local span=math.max(1,hit.track.h-(hit.thumb and hit.thumb.h or 0))
                        local fraction=math.max(0,math.min(1,(my-hit.track.y)/span))
                        C.scroll=math.floor((1-fraction)*math.max(0,#C.history-C.pageRows)+0.5)
                    end
                else
                    for _,row in ipairs(hit.rows or {}) do
                        if inside(row,mx,my) then C.recall(row.index);break end
                    end
                end
            end
            consume();return true
        end
        if hit and clock()-(C.drawAt or -10)<0.5 and inside(hit.meta,mx,my) then
            if msg==0x0201 or msg==0x0203 then
                C.mouseCaptured=true
                if inside(hit.normal,mx,my) then C.setMode('normal')
                elseif inside(hit.admin,mx,my) then C.setMode('admin')
                elseif inside(hit.family,mx,my) then C.setMode('family') end
            end
            consume();return true
        end
        local r=C.rect
        if r and r.native and inside(r,mx,my) then
            if msg==0x0201 or msg==0x0203 then C.nativeMouse=true end
            return true
        end
        if msg==0x0201 or msg==0x0203 then C.ticket=nil end
        return false
    end
    local function fit(text,width,measure,scale)
        if measure(text,scale)<=width then return text end
        local chars={}
        for ch in text:gmatch('[%z\1-\127\194-\244][\128-\191]*') do chars[#chars+1]=ch end
        local lo,hi=0,#chars
        while lo<hi do
            local mid=math.ceil((lo+hi)/2)
            if measure(table.concat(chars,'',1,mid)..'...',scale)<=width then lo=mid else hi=mid-1 end
        end
        return table.concat(chars,'',1,lo)..'...'
    end
    function C.roundFlags(im)
        for _,choice in ipairs({
            {'DrawFlags','RoundCornersAll'},{'ImDrawFlags','RoundCornersAll'},
            {false,'ImDrawFlags_RoundCornersAll'},
            {'DrawCornerFlags','All'},{'ImDrawCornerFlags','All'},{'CornerFlags','All'},
            {false,'ImDrawCornerFlags_All'},
        }) do
            local ok,value=pcall(function()
                if choice[1] then return im[choice[1]][choice[2]] end
                return im[choice[2]]
            end)
            value=ok and tonumber(value) or nil
            if value and value>0 then return value end
        end
        return nil
    end
    function C.draw(ctx)
        if not C.active() then C.hit=nil;return false end
        local im=ctx.im
        C.updateLayoutLanguage()
        local pushed=ctx.pushFont()
        local ok,result=pcall(function()
            local fontCache={}
            local basePx=(GRND_FONT and GRND_FONT.fontBase) or 16
            local function fontCall(fn,scale,...)
                scale=scale or 1
                local cached=fontCache[scale]
                if not cached then
                    cached={}
                    if type(_G.grndUiFontPick)=='function' then
                        local got,font,pixels=pcall(_G.grndUiFontPick,basePx*scale)
                        if got and font then cached.font,cached.pixels=font,pixels end
                        if cached.font and tonumber(cached.pixels) and cached.pixels>0 then
                            local ratio=(basePx*scale)/cached.pixels
                            if math.abs(ratio-1)>0.02 then cached.ratio=ratio end
                        end
                    end
                    fontCache[scale]=cached
                end
                local native=cached.font and isFnV(im.PushFont) and isFnV(im.PopFont)
                    and pcall(im.PushFont,cached.font)
                GRND_FONT.lastCall={want=basePx*scale,pick=cached.pixels,ratio=cached.ratio or 1,native=native and true or false}
                local success,a,b=pcall(fn,native and (cached.ratio or 1) or scale,...)
                if native then pcall(im.PopFont) end
                if not success then error(a) end
                return a,b,native,cached.pixels
            end
            local function metrics(label,scale)
                local width,height,native,pixels=fontCall(function(k,str)
                    local fallbackWidth=ctx.measure(str,k)
                    local scaled=false
                    if k~=1 and isFnV(im.SetWindowFontScale) then
                        scaled=pcall(im.SetWindowFontScale,k)
                    end
                    local ok,a,b=pcall(function()return im.CalcTextSize(str)end)
                    local w,h
                    if ok then
                        if type(a)=='table' or type(a)=='cdata' then
                            w,h=tonumber(a.x),tonumber(a.y)
                        elseif type(a)=='number' then w,h=a,tonumber(b) end
                    end
                    h=h or tonumber(call(im.GetFontSize))
                    if scaled then pcall(im.SetWindowFontScale,1) end
                    return w or fallbackWidth,h
                end,scale,tostring(label))
                if native and GRND_FONT and GRND_FONT.noMeasure then
                    width=width*((tonumber(pixels) or basePx*(scale or 1))/basePx)
                end
                height=tonumber(height) or (native and tonumber(pixels))
                    or ((GRND_FONT and GRND_FONT.fontSize) or 14)
                return width,math.max(1,height)
            end
            local function measure(label,scale) return (metrics(label,scale)) end
            local function measureFont(str,scale)
                local w=fontCall(function(k) return ctx.measure(str,k) end,scale)
                return tonumber(w) or 0
            end
            local _,metaFontHeight=metrics(C.channels.normal.label,C.metaScale)
            local L=C.layout(measureFont,metaFontHeight)
            local win=L.window
            im.SetNextWindowPos(im.ImVec2(win.x,win.y),ctx.always)
            im.SetNextWindowSize(im.ImVec2(win.w,win.h),ctx.always)
            if not ctx.begin('##grnd_native_input_overlay',ctx.flags) then C.hit=nil;return end
            local pos=im.GetWindowPos()
            local dl=im.GetWindowDrawList()
            local function point(x,y) return im.ImVec2(math.floor(x),math.floor(y)) end
            local function color(r,g,b,a) return ctx.col32(r,g,b,a or 255) end
            local allCorners=C.roundFlags(im)
            local function rect(r,col,round)
                local p1,p2=point(r.x,r.y),point(r.x+r.w,r.y+r.h)
                round=round or 0
                if round>0 and not allCorners and dl.AddRectFilled then
                    if pcall(dl.AddRectFilled,dl,p1,p2,col,round) then return end
                end
                ctx.roundRect(dl,p1,p2,col,round,round>0 and allCorners or nil)
            end
            local function text(x,y,label,rgba,scale)
                return fontCall(function(k)
                    return ctx.text(math.floor(x-pos.x),math.floor(y-pos.y),label,ctx.rgba(unpack(rgba)),k)
                end,scale)
            end
            local function centerY(top,height,label,scale)
                local _,textHeight=metrics(label,scale)
                return math.floor(top+(height-textHeight)/2)
            end
            local function centeredText(x,top,height,label,rgba,scale)
                return text(x,centerY(top,height,label,scale),label,rgba,scale)
            end
            local green={63,209,145}
            local info=C.channelInfo()
            local accent=C.currentMode()=='normal' and green or info.rgb
            local alpha=math.max(0,math.min(1,(clock()-C.openedAt)/0.12))
            local r=L.input
            if r.native then
                rect({x=r.x+1,y=r.y+6,w=2,h=math.max(2,r.h-12)},color(accent[1],accent[2],accent[3],210),1)
                if C.readText()=='' then
                    local hint=info.hint..'  |  Введите сообщение...'
                    centeredText(r.x+15,r.y,r.h,fit(hint,r.w-28,measureFont,1.8),{160,164,174,155},1.8)
                end
            end
            local hit={panel=L.panel,meta=L.meta,rows={}}
            local function metaText(x,y,label,rgba)
                if label=='' then return end
                text(x+1,y+1,label,{0,0,0,195},C.metaScale)
                text(x,y,label,rgba,C.metaScale)
            end
            local function metaFit(label,width)
                if measureFont(label,C.metaScale)<=width then return label end
                if measureFont('...',C.metaScale)<=width then return fit(label,width,measureFont,C.metaScale) end
                return ''
            end
            for _,group in ipairs(L.groups) do
                local radio=C.channels[group.kind]~=nil
                if radio then
                    local selected=group.kind==C.currentMode()
                    local rgb=C.channels[group.kind].rgb
                    local cp=point(group.x+9,group.y+group.h/2)
                    if dl.AddCircle then dl:AddCircle(cp,9,color(rgb[1],rgb[2],rgb[3],selected and 255 or 215),24,1.9) end
                    if selected then dl:AddCircleFilled(cp,4.5,color(rgb[1],rgb[2],rgb[3],255),20) end
                    local label=metaFit(group.text,group.w-30)
                    metaText(group.x+28,centerY(group.y,group.h,label,C.metaScale),label,{rgb[1],rgb[2],rgb[3],255})
                    local padding=group.hitPad or 3
                    hit[group.kind]={x=group.x-padding,y=group.y,w=group.w+2*padding,h=group.h}
                else
                    local label=metaFit(group.text,group.w)
                    metaText(group.x,centerY(group.y,group.h,label,C.metaScale),label,{245,248,255,255})
                end
            end
            if L.panel then
                local p=L.panel
                local radius=math.min(C.historyRadius,p.w/2,p.h/2)
                rect({x=p.x+2,y=p.y+3,w=p.w,h=p.h},color(0,0,0,math.floor(55*alpha)),radius)
                rect(p,color(10,14,20,math.floor(166*alpha)),radius)
                if dl.AddRect then
                    local p1,p2=point(p.x,p.y),point(p.x+p.w,p.y+p.h)
                    local edge=color(255,255,255,math.floor(32*alpha))
                    if allCorners then dl:AddRect(p1,p2,edge,radius,allCorners,1)
                    else dl:AddRect(p1,p2,edge,radius) end
                end
                rect({x=p.x+14,y=p.y+13,w=3,h=15},color(green[1],green[2],green[3],240),1)
                local title=C.error or 'История ввода'
                centeredText(p.x+25,p.y+13,15,fit(title,p.w-130,measure,1),C.error and {255,119,129,255} or {230,237,247,255},1)
                local count=tostring(#C.history)..' / '..tostring(C.maxHistory)
                centeredText(p.x+p.w-18-measure(count,0.85),p.y+13,15,count,{150,164,184,235},0.85)
                rect({x=p.x+12,y=p.y+35,w=p.w-24,h=1},color(255,255,255,22))
                local first=math.max(1,#C.history-C.pageRows-C.scroll+1)
                local last=math.min(#C.history,first+C.pageRows-1)
                local rowY=p.y+41
                if #C.history==0 then
                    local message='Здесь появятся введённые сообщения'
                    centeredText(p.x+16,rowY,C.historyRow,fit(message,p.w-40,measure,C.historyScale),{158,173,196,235},C.historyScale)
                else
                    for index=first,last do
                        local entry=C.history[index]
                        local row={x=p.x+8,y=rowY,w=p.w-26,h=C.historyRow-1,index=index}
                        hit.rows[#hit.rows+1]=row
                        local selected=C.browse==index
                        local hovered=inside(row,C.mouseX,C.mouseY)
                        if selected or hovered then rect(row,color(green[1],green[2],green[3],selected and 38 or 19),5) end
                        local isCommand=entry.kind=='command' or (not entry.kind and entry.raw:match('^%s*/')~=nil)
                        local historic=C.channelInfo(entry.channel or (entry.admin and 'admin' or 'normal'))
                        local rgb=isCommand and {126,174,241} or (historic.id=='normal' and {174,188,205} or historic.rgb)
                        dl:AddCircleFilled(point(p.x+17,rowY+C.historyRow/2),3,color(rgb[1],rgb[2],rgb[3],230),12)
                        local available=p.w-108
                        centeredText(p.x+29,rowY,C.historyRow,fit(entry.text,available,measure,C.historyScale),{236,241,249,255},C.historyScale)
                        centeredText(p.x+p.w-68,rowY,C.historyRow,entry.time,{145,163,187,230},0.8)
                        rowY=rowY+C.historyRow
                    end
                end
                local track={x=p.x+p.w-10,y=p.y+42,w=4,h=math.max(20,C.pageRows*C.historyRow-3)}
                local total=#C.history
                if total>C.pageRows then
                    local thumbH=math.max(18,track.h*C.pageRows/total)
                    local fraction=(total-C.pageRows-C.scroll)/(total-C.pageRows)
                    local thumb={x=track.x,y=track.y+(track.h-thumbH)*fraction,w=4,h=thumbH}
                    hit.track={x=track.x-4,y=track.y,w=12,h=track.h};hit.thumb=thumb
                    rect(track,color(255,255,255,30),2)
                    rect(thumb,color(green[1],green[2],green[3],215),2)
                end
                local footer=C.error and 'Сообщение осталось в строке - исправьте ввод.'
                    or 'Вверх/вниз - вернуть ввод   |   Колесо - история'
                centeredText(p.x+14,p.y+p.h-28,28,fit(footer,p.w-30,measure,0.85),C.error and {244,178,184,245} or {151,169,194,235},0.85)
            elseif L.warning then
                rect(L.warning,color(35,12,18,160),5)
                centeredText(L.warning.x+10,L.warning.y,L.warning.h,fit(C.error,L.warning.w-20,measure,0.8),{255,119,129,255},0.8)
            end
            C.hit,C.drawAt=hit,clock()
        end)
        ctx.finish();ctx.popFont(pushed)
        if not ok then C.hit=nil;error(result) end
        return false
    end
    function C.command(arg)
        local a=tostring(arg or ''):lower():gsub('^%s+',''):gsub('%s+$','')
        if a=='on' or a=='off' then
            C.setEnabled(a=='on');pcall(grndCamCfgSave)
        elseif a=='history on' or a=='history off' then
            C.showHistory=a=='history on';pcall(grndCamCfgSave)
        elseif a=='clear' then C.clear() end
        local r=C.rect
        local lines={
            'Панель ввода: '..(C.enabled and 'ВКЛ' or 'ВЫКЛ')..'; канал: '..(C.channelInfo().label..(C.channelInfo().prefix~='' and (' ('..C.channelInfo().prefix:gsub('%s+$','')..')') or '')),
            'История: '..tostring(#C.history)..' / '..tostring(C.maxHistory)..' (только текущая сессия).',
            'Привязка: '..tostring(C.geometrySource or 'откройте штатную строку чата')
                ..(r and ('; x=%d y=%d w=%d h=%d'):format(r.x,r.y,r.w,r.h) or ''),
            '/grnd input on | off | clear; /grnd input history on | off.',
        }
        for _,line in ipairs(lines) do pcall(grndChatSay,'{00D6AA}[GRND]{FFFFFF} '..line,-1) end
        return true
    end
end
function grndChatOpen(apiOnly)
    if type(sampIsChatInputActive) == "function" then
        local ok, a = pcall(sampIsChatInputActive)
        if ok and a then return true end
    end
    if type(sampSetChatInputEnabled) == "function" then
        local ok = pcall(sampSetChatInputEnabled, true)
        if ok and type(sampIsChatInputActive) == "function" then
            local ok2, a = pcall(sampIsChatInputActive)
            if ok2 and a then return true end
        elseif ok then
            return true
        end
    end
    if apiOnly then return false end
    do
        local okF, ffi = pcall(require, "ffi")
        if okF and ffi then
            pcall(function()
                ffi.cdef[[ void keybd_event(unsigned char bVk, unsigned char bScan, unsigned long dwFlags, unsigned long dwExtraInfo); ]]
                GRND_CHAT.synthT = os.clock()
                ffi.C.keybd_event(0x54, 0, 0, 0)
                ffi.C.keybd_event(0x54, 0, 2, 0)
            end)
            return true
        end
    end
    return false
end
GRND_CHAT.EP_VER = {
    [0x31DF13] = "0.3.7-R1",
    [0x3195DD] = "0.3.7-R2",
    [0x0CC4D0] = "0.3.7-R3-1",
    [0x0CBCB0] = "0.3.7-R4",
    [0x0CBC90] = "0.3.7-R5-1",
    [0x0FDB60] = "0.3.DL-1",
}
GRND_CHAT.PTR_BY_VER = {
    ["0.3.7-R1"] = 0x21A0E4, ["0.3.7-R2"] = 0x21A0EC,
    ["0.3.7-R3"] = 0x26E8C8, ["0.3.7-R3-1"] = 0x26E8C8,
    ["0.3.7-R4"] = 0x26E9F8, ["0.3.7-R4-2"] = 0x26E9F8,
    ["0.3.7-R5"] = 0x26EB80, ["0.3.7-R5-1"] = 0x26EB80,
    ["0.3.DL"] = 0x2ACA10,   ["0.3.DL-1"] = 0x2ACA10,
}
GRND_CHAT.PTR_OFFS = { 0x26EB80, 0x26E8C8, 0x26E9F8, 0x21A0E4, 0x21A0EC,
                        0x2ACA10, 0x2ACA14, 0x21A0E8 }
GRND_CHAT.dbg = GRND_CHAT.dbg or {}
function grndChatMem()
    if GRND_CHAT._mem ~= nil then
        if GRND_CHAT._mem ~= false then return GRND_CHAT._mem end
        if (os.clock() - (GRND_CHAT._memAt or 0)) < 5 then return false end
    end
    local api, m = nil, (type(libs) == "table" and libs.memory) or nil
    if not m then
        local ok, r = pcall(require, "memory")
        if ok and type(r) == "table" then m = r end
    end
    if m and type(m.getint32) == "function" and type(m.setint32) == "function" then
        m._get8 = m.getint8 or m.readint8
        m._set8 = m.setint8 or m.writeint8
        api = {
            name = "memory.lua",
            r32 = function(a)
                local o, v = pcall(m.getint32, a)
                if o and type(v) == "number" then return v end
            end,
            r8 = function(a)
                local o, v = pcall(m._get8 or m.getint8, a)
                if o and type(v) == "number" then return math.floor(v) % 256 end
            end,
            w32 = function(a, v) return pcall(m.setint32, a, v, true) end,
            w8 = function(a, v) return pcall(m._set8 or m.setint8, a, v, true) end,
        }
    elseif type(readMemory) == "function" and type(writeMemory) == "function" then
        api = {
            name = "readMemory/writeMemory",
            r32 = function(a)
                local o, v = pcall(readMemory, a, 4, true)
                if o and type(v) == "number" then return v end
            end,
            r8 = function(a)
                local o, v = pcall(readMemory, a, 1, true)
                if o and type(v) == "number" then return math.floor(v) % 256 end
            end,
            w32 = function(a, v) return pcall(writeMemory, a, 4, v, true) end,
            w8 = function(a, v) return pcall(writeMemory, a, 1, v, true) end,
        }
    end
    GRND_CHAT._mem = api or false
    GRND_CHAT._memAt = os.clock()
    if api then
        GRND_CHAT.memErr = nil
    else
        GRND_CHAT.memErr =
            "нет ни memory.lua, ни readMemory/writeMemory — запись в память невозможна"
    end
    GRND_CHAT.dbg.mem = api and api.name or "НЕТ"
    return GRND_CHAT._mem
end
function grndChatU32(v)
    if type(v) ~= "number" then return nil end
    v = math.floor(v)
    if v < 0 then v = v + 0x100000000 end
    return v % 0x100000000
end
function grndChatRd32(a)
    local mem = grndChatMem()
    if not mem then return nil end
    return mem.r32(a)
end
function grndChatRd8(a)
    local mem = grndChatMem()
    if not mem then return nil end
    return mem.r8(a)
end
function grndChatWr32(a, v)
    local mem = grndChatMem()
    if not mem then return false end
    local u = grndChatU32(v) or 0
    if u > 0x7FFFFFFF then u = u - 0x100000000 end
    local ok, r = mem.w32(a, u)
    if ok and r == false then return false end
    return true
end
function grndChatWr8(a, v)
    local mem = grndChatMem()
    if not mem then return false end
    local ok, r = mem.w8(a, v)
    if ok and r == false then return false end
    return true
end
function grndChatPtrPlausible(p)
    p = grndChatU32(p)
    return p ~= nil and p >= 0x10000 and p <= 0xFFFF0000
end
function grndChatPeInfo(base)
    if not base then return nil end
    local pe = grndChatU32(grndChatRd32(base + 0x3C))
    if not pe or pe == 0 or pe > 0x1000 then return nil end
    if grndChatU32(grndChatRd32(base + pe)) ~= 0x00004550 then return nil end
    local ep   = grndChatU32(grndChatRd32(base + pe + 0x28))
    local size = grndChatU32(grndChatRd32(base + pe + 0x50))
    return ep, size
end
function grndChatBase()
    if type(getModuleHandle) ~= "function" then return nil end
    local ok, b = pcall(getModuleHandle, "samp.dll")
    if ok and type(b) == "number" and b ~= 0 then return grndChatU32(b) end
    return nil
end
function grndChatColorsOk(p)
    p = grndChatU32(p)
    if not p then return false end
    local c1 = grndChatU32(grndChatRd32(p + 0x122))
    local c2 = grndChatU32(grndChatRd32(p + 0x126))
    local c3 = grndChatU32(grndChatRd32(p + 0x12A))
    return c1 == 0xFFFFFFFF and c2 == 0xFF88AA62 and c3 == 0xFFA9C4E4
end
function grndChatWhyNot(p)
    p = grndChatU32(p)
    if not p or p == 0 then return "переменная пуста — чат ещё не создан" end
    if p < 0x10000 or p > 0xFFFF0000 then return ("не адрес памяти (0x%X)"):format(p) end
    local page = grndChatU32(grndChatRd32(p + 0x000))
    if not page then return ("по адресу 0x%X не читается"):format(p) end
    if page < 1 or page > 100 then
        return ("поле строк = %s (нужно 1..100) — это не CChat"):format(tostring(page))
    end
    if not grndChatColorsOk(p) then return "цвета CChat не совпали — это не CChat" end
    return "похоже на чат"
end
function grndChatPtrOk(p, strict)
    p = grndChatU32(p)
    if not grndChatPtrPlausible(p) then return false end
    local page = grndChatU32(grndChatRd32(p + 0x000))
    if not page or page < 1 or page > 100 then return false end
    local mode = grndChatU32(grndChatRd32(p + 0x008))
    if not mode or mode > 2 then return false end
    local ts = grndChatU32(grndChatRd32(p + 0x00C))
    if not ts or ts > 0x1FF then return false end
    local ch = grndChatU32(grndChatRd32(p + 0x63E2))
    local tw = grndChatU32(grndChatRd32(p + 0x63E6))
    local chOk = ch and ch >= 4 and ch <= 64
    local twOk = tw and tw <= 400
    local colorOk = grndChatColorsOk(p)
    if not (colorOk or (chOk and twOk)) then return false end
    return true, chOk, twOk, colorOk
end
function grndChatSections(base)
    local out = {}
    local pe = grndChatU32(grndChatRd32(base + 0x3C))
    if not pe or pe == 0 or pe > 0x1000 then return out end
    local nsec    = grndChatU32(grndChatRd32(base + pe + 0x06))
    local optSize = grndChatU32(grndChatRd32(base + pe + 0x14))
    if not nsec or nsec <= 0 or nsec > 96 then return out end
    if not optSize or optSize > 0x400 then return out end
    local st = base + pe + 0x18 + optSize
    for i = 0, nsec - 1 do
        local b = st + i * 40
        local vsize = grndChatU32(grndChatRd32(b + 0x08)) or 0
        local va    = grndChatU32(grndChatRd32(b + 0x0C)) or 0
        local rsize = grndChatU32(grndChatRd32(b + 0x10)) or 0
        local chars = grndChatU32(grndChatRd32(b + 0x24)) or 0
        local sz = math.min(vsize > 0 and vsize or rsize, rsize > 0 and rsize or vsize)
        out[#out + 1] = {
            va = va, size = sz,
            writable = (chars >= 0x80000000),
            exec = (math.floor(chars / 0x20000000) % 2 == 1),
        }
    end
    return out
end
GRND_CHAT.SCAN_WINDOWS = {
    { 0x26E700, 0x600 },
    { 0x21A000, 0x200 },
    { 0x2AC9C0, 0x100 },
}
function grndChatScanWindows()
    local base = GRND_CHAT.dbg.base or grndChatBase()
    if not base then return nil end
    GRND_CHAT.dbg.base = base
    local checked, words = 0, 0
    for w = 1, #GRND_CHAT.SCAN_WINDOWS do
        local from, size = GRND_CHAT.SCAN_WINDOWS[w][1], GRND_CHAT.SCAN_WINDOWS[w][2]
        local i = 0
        while i < size do
            words = words + 1
            local slot = from + i
            local p = grndChatU32(grndChatRd32(base + slot))
            if grndChatPtrPlausible(p) and (p % 4) == 0 then
                checked = checked + 1
                if grndChatPtrOk(p) then
                    GRND_CHAT.dbg.scanStat =
                        ("окон %d, слов %d, кандидатов %d — нашёл samp.dll+0x%X")
                        :format(#GRND_CHAT.SCAN_WINDOWS, words, checked, slot)
                    return p, slot
                end
            end
            i = i + 4
        end
    end
    return nil, checked, words
end
function grndChatScanPtr(budget)
    local base = GRND_CHAT.dbg.base or grndChatBase()
    if not base then return nil end
    GRND_CHAT.dbg.base = base
    budget = budget or 40000
    local st = GRND_CHAT._sc
    if not st or st.base ~= base then
        local wp, slot, checkedW = grndChatScanWindows()
        if wp then
            GRND_CHAT._p, GRND_CHAT._src = wp, ("поиск рядом с офсетами (samp.dll+0x%X)"):format(slot)
            GRND_CHAT.dbg.ptr, GRND_CHAT.dbg.src = GRND_CHAT._p, GRND_CHAT._src
            GRND_CHAT._sc = nil
            return wp
        end
        local secs = grndChatSections(base)
        table.sort(secs, function(a, b)
            return (a.writable and 1 or 0) > (b.writable and 1 or 0)
        end)
        st = { base = base, secs = secs, si = 1, i = 0, secN = 0, seen = 0, checked = 0, checkedW = checkedW or 0 }
        GRND_CHAT._sc = st
    end
    local t0 = os.clock()
    while st.si <= #st.secs do
        local s = st.secs[st.si]
        if s.writable and s.size > 0 and s.size <= 1024 * 1024 then
            if st.i == 0 then st.secN = st.secN + 1 end
            while st.i + 4 <= s.size do
                st.seen = st.seen + 1
                local p = grndChatU32(grndChatRd32(base + s.va + st.i))
                if grndChatPtrPlausible(p) and (p % 4) == 0 then
                    st.checked = st.checked + 1
                    if grndChatPtrOk(p, true) then
                        GRND_CHAT.dbg.scanStat =
                            ("секций %d, слов %d, кандидатов %d — нашёл samp.dll+0x%X")
                            :format(st.secN, st.seen, st.checked, s.va + st.i)
                        GRND_CHAT._p = p
                        GRND_CHAT._src = ("поиск по секциям (samp.dll+0x%X)"):format(s.va + st.i)
                        GRND_CHAT.dbg.ptr, GRND_CHAT.dbg.src = p, GRND_CHAT._src
                        GRND_CHAT._sc = nil
                        return p
                    end
                    if st.checked >= budget then
                        GRND_CHAT._sc = nil
                        GRND_CHAT.dbg.scanStat = ("секций %d, слов %d, кандидатов %d — лимит кандидатов")
                            :format(st.secN, st.seen, st.checked)
                        return nil
                    end
                end
                st.i = st.i + 4
                if (st.seen % 2048) == 0 and (os.clock() - t0) >= 0.004 then
                    return nil
                end
            end
        end
        st.si = st.si + 1
        st.i = 0
    end
    GRND_CHAT._sc = nil
    GRND_CHAT.dbg.scanStat = ("секций %d, слов %d, кандидатов %d (окна: кандидатов %d) — не нашёл")
        :format(st.secN, st.seen, st.checked, st.checkedW or 0)
    return nil
end
function grndChatInfoPtr()
    local p = GRND_CHAT._p
    if p and grndChatPtrOk(p) then return p, GRND_CHAT._src end
    GRND_CHAT._p, GRND_CHAT._src = nil, nil
    if not GRND_CHAT._sc and (GRND_CHAT._lookAt or -1) > os.clock() then return nil end
    local D = GRND_CHAT.dbg
    local base = grndChatBase()
    D.base = base
    if not base then
        D.ptr, D.src = nil, "нет samp.dll"
        return nil
    end
    local ep = grndChatPeInfo(base)
    D.ep = ep
    D.ver = ep and GRND_CHAT.EP_VER[ep] or nil
    local order = {}
    if D.ver and GRND_CHAT.PTR_BY_VER[D.ver] then
        order[#order + 1] = { off = GRND_CHAT.PTR_BY_VER[D.ver], src = "версия " .. D.ver }
    end
    for i = 1, #GRND_CHAT.PTR_OFFS do
        order[#order + 1] = { off = GRND_CHAT.PTR_OFFS[i],
            src = ("офсет 0x%X"):format(GRND_CHAT.PTR_OFFS[i]) }
    end
    if type(GRND_KL) == "table" and type(GRND_KL.off) == "number" and GRND_KL.off > 8 then
        order[#order + 1] = { off = GRND_KL.off - 8, src = "килл-лист - 8" }
    end
    if D.ver and GRND_CHAT.PTR_BY_VER[D.ver] then
        local off = GRND_CHAT.PTR_BY_VER[D.ver]
        local qv = grndChatU32(grndChatRd32(base + off))
        D.verOff, D.verVal, D.verWhy = off, qv, grndChatWhyNot(qv)
    end
    for i = 1, #order do
        local c = order[i]
        local q = grndChatU32(grndChatRd32(base + c.off))
        if grndChatPtrOk(q) then
            GRND_CHAT._p, GRND_CHAT._src = q, c.src
            D.ptr, D.src = q, c.src
            D.sig = grndChatColorsOk(q) and "по подписи цветов CChat" or "по полям структуры"
            return q, c.src
        end
    end
    if type(sampGetChatInfoPtr) == "function" then
        local ok, q = pcall(sampGetChatInfoPtr)
        if ok and type(q) == "number" and q ~= 0 then
            q = grndChatU32(q)
            if grndChatPtrOk(q) then
                GRND_CHAT._p, GRND_CHAT._src = q, "sampGetChatInfoPtr"
                D.ptr, D.src = q, GRND_CHAT._src
                return q, GRND_CHAT._src
            end
            D.apiBad = q
        end
    end
    D.ptr, D.src = nil, "не найден"
    local now = os.clock()
    GRND_CHAT._lookAt = now + 0.5
    if (not GRND_CHAT.scanDone) and type(grndIsSpawnedSafe) == "function" and grndIsSpawnedSafe() then
        local paused = GRND_CHAT._sc ~= nil
        if paused or (now - (GRND_CHAT.scanAt or 0)) > 15 then
            if not paused then
                GRND_CHAT.scanAt = now
                GRND_CHAT.scanTries = (GRND_CHAT.scanTries or 0) + 1
            end
            local ok, q = pcall(grndChatScanPtr, 40000)
            if ok and q then
                GRND_CHAT.scanDone = true
                return q, GRND_CHAT._src
            end
            if not ok then GRND_CHAT._sc = nil end
            if GRND_CHAT._sc == nil and (GRND_CHAT.scanTries or 0) >= 3 then GRND_CHAT.scanDone = true end
        end
    end
    return nil
end
function grndChatApplyNow(force)
    local D = GRND_CHAT.dbg
    local p, src = grndChatInfoPtr()
    D.ptr, D.src = p, src
    if not p then return false end
    local changed = false
    local wantTs = GRND_CHAT.timestamps and 1 or 0
    if grndChatRd8(p + 0x00C) ~= wantTs then
        grndChatWr8(p + 0x00C, wantTs)
        D.tsWrote = wantTs
        changed = true
    end
    local want = math.floor(tonumber(GRND_CHAT.lines) or 10)
    if want < 10 then want = 10 elseif want > 60 then want = 60 end
    GRND_CHAT.lines=want
    local cur = grndChatRd32(p + 0x000)
    local pageChanged = (grndChatU32(cur) ~= want)
    if pageChanged then
        grndChatWr32(p + 0x000, want)
        D.pageWrote = want
        changed = true
    end
    if pageChanged or force or not GRND_CHAT._sbSynced then
        local sb = grndChatU32(grndChatRd32(p + 0x11E))
        D.sb = sb
        if grndChatPtrPlausible(sb) then
            local ch = grndChatU32(grndChatRd32(p + 0x63E2)) or 0
            if ch < 4 or ch > 64 then ch = 14 end
            local pos = 100 - want
            if pos < 1 then pos = 1 end
            if grndChatRd32(sb + 0x08) ~= 10 then grndChatWr32(sb + 0x08, 10) end
            if grndChatRd32(sb + 0x0C) ~= 40 then grndChatWr32(sb + 0x0C, 40) end
            if grndChatRd32(sb + 0x10) ~= 20 then grndChatWr32(sb + 0x10, 20) end
            local h = (ch + 1) * want - 60
            if h < 0 then h = 0 end
            if grndChatRd32(sb + 0x14) ~= h then grndChatWr32(sb + 0x14, h) end
            if grndChatRd32(sb + 0x92) ~= want then grndChatWr32(sb + 0x92, want) end
            if grndChatRd32(sb + 0x8E) ~= pos then grndChatWr32(sb + 0x8E, pos) end
            GRND_CHAT._sbSynced = true
            D.sbPos, D.sbPage, D.sbH = pos, want, h
        end
    end
    if changed or force then
        grndChatWr32(p + 0x63DA, 1)
        D.redraw = 1
    end
    D.page   = grndChatRd32(p + 0x000)
    D.ts     = grndChatRd8(p + 0x00C)
    D.mode   = grndChatRd32(p + 0x008)
    D.ch     = grndChatRd32(p + 0x63E2)
    D.tw     = grndChatRd32(p + 0x63E6)
    D.redraw = grndChatRd32(p + 0x63DA)
    D.at     = os.clock()
    return true
end
function grndChatApply(force)
    local C = GRND_CHAT
    local now = os.clock()
    if not force and C._applyAt and (now - C._applyAt) < 0.2 then return C._applyOk end
    C._applyAt = now
    C._applyOk = grndChatApplyNow(force) and true or false
    return C._applyOk
end
grndChatStampApply = grndChatApply
function grndChatDbgLines()
    local D = GRND_CHAT.dbg or {}
    local function hx(v)
        if type(v) ~= "number" then return "—" end
        return ("0x%X"):format(grndChatU32(v) or 0)
    end
    local out = {}
    out[#out + 1] = ("чат SA-MP: %s%s"):format(
        D.ptr and ("CChat " .. hx(D.ptr)) or "указатель НЕ найден",
        D.src and (" — " .. tostring(D.src)) or "")
    out[#out + 1] = ("  клиент: %s, entry point %s, память: %s"):format(
        tostring(D.ver or "неизвестная сборка"), hx(D.ep), tostring(D.mem or "нет"))
    out[#out + 1] = ("  строк=%s (нужно %s), время=%s (нужно %s), m_bRedraw=%s"):format(
        tostring(D.page), tostring(GRND_CHAT.lines),
        tostring(D.ts), GRND_CHAT.timestamps and "1" or "0", tostring(D.redraw))
    out[#out + 1] = ("  m_nMode=%s, высота строки=%s, ширина метки=%s"):format(
        tostring(D.mode), tostring(D.ch), tostring(D.tw))
    out[#out + 1] = ("  полоса прокрутки: позиция=%s страница=%s высота=%s%s"):format(
        tostring(D.sbPos), tostring(D.sbPage), tostring(D.sbH),
        (D.sb and (" (объект " .. hx(D.sb) .. ")")) or " (нет)")
    if D.pageWrote or D.tsWrote then
        out[#out + 1] = ("  последняя запись: строк=%s время=%s"):format(
            tostring(D.pageWrote), tostring(D.tsWrote))
    end
    if D.scanStat then out[#out + 1] = "  поиск по секциям: " .. tostring(D.scanStat) end
    if D.apiBad then
        out[#out + 1] = ("  sampGetChatInfoPtr вернула %s — это не CChat, игнорирую"):format(hx(D.apiBad))
    end
    if D.verOff then
        out[#out + 1] = ("  переменная версии: сам.dll+0x%X = %s — %s"):format(
            D.verOff, (D.verVal and hx(D.verVal)) or "0", tostring(D.verWhy or "?"))
        local vv = grndChatU32(D.verVal or 0)
        if vv and vv >= 0x80000000 then
            out[#out + 1] = "    (адрес выше 2 ГБ — для игры с флагом больших адресов это норма)"
        end
    end
    if D.ptr and D.sig then out[#out + 1] = "  указатель принят: " .. tostring(D.sig) end
    if GRND_CHAT.memErr then out[#out + 1] = "  " .. GRND_CHAT.memErr end
    if not D.ptr then
        out[#out + 1] = "  что делать: /grnd chat — состояние перехвата чата"
    end
    return out
end
function grndChatTest(arg)
    local a = tostring(arg or ""):lower():gsub("%s+", "")
    local function say(s)
        if type(notify) == "table" and type(notify.say) == "function" then
            pcall(notify.say, "[grndchat] " .. s, "info")
        else
            print("{00FFAA}[GRND]{FFFFFF} [grndchat] " .. s)
        end
    end
    if a == "scan" then
        GRND_CHAT.scanDone, GRND_CHAT.scanTries = false, 0
        GRND_CHAT._p, GRND_CHAT._sbSynced = nil, false
        local t0 = os.clock()
        local ok, q = pcall(grndChatScanPtr, 80000)
        local ms = math.floor((os.clock() - t0) * 1000)
        say(("поиск указателя: %s, время %d мс"):format(
            (ok and q) and ("нашёл 0x" .. ("%X"):format(grndChatU32(q))) or "не нашёл", ms))
        if ok and q then GRND_CHAT.scanDone = true end
    end
    pcall(grndChatApply, true)
    local lines = grndChatDbgLines()
    for i = 1, #lines do say(lines[i]) end
    if not GRND_CHAT.dbg.ptr then
        say("чат не найден — скопируйте этот вывод и пришлите автору скрипта")
    end
    return true
end
local _pedAlphaFn = nil
local function grndSetPedAlpha(ped, alpha)
    if not (ped and type(doesCharExist) == "function" and doesCharExist(ped)) then return end
    if type(getCharPointer) ~= "function" then return end
    local okP, ptr = pcall(getCharPointer, ped)
    if not (okP and ptr and ptr ~= 0) then return end
    local okF, ffi = pcall(require, "ffi")
    if not (okF and ffi) then return end
    if not _pedAlphaFn then
        local okCast, fn = pcall(function()
            return ffi.cast("void (__thiscall *)(int, int)", 0x5332C0)
        end)
        if okCast and fn then
            _pedAlphaFn = fn
        end
    end
    if _pedAlphaFn then
        pcall(_pedAlphaFn, ptr, math.max(0, math.min(255, math.floor(alpha or 255))))
    end
end
local function grndInvisFrame()
    if not (PLAYER_PED and type(doesCharExist) == "function" and doesCharExist(PLAYER_PED)) then return end
    if GRND_INVIS and GRND_INVIS.on and GRND_INVIS.ghost then
        grndSetPedAlpha(PLAYER_PED, GRND_INVIS.alpha or 140)
        GRND_INVIS.wasGhost = true
    elseif GRND_INVIS and GRND_INVIS.wasGhost then
        grndSetPedAlpha(PLAYER_PED, 255)
        GRND_INVIS.wasGhost = false
    end
end
local GRND_AIR = { on = false, obj = nil, objZ = nil, objX = nil, objY = nil, lastZ = nil, prevKey = false, debug = false }
_G.GRND_AIR = GRND_AIR
do
    local PLATFORM_MODEL = 1271
    local PLATFORM_SCALE = 2.0
    local FEET_OFF = 1.0
    local HALF_H = 0.25 * PLATFORM_SCALE
    local OBJ_OFF = FEET_OFF + HALF_H
    local ON_TOL = 0.35
    local STEP_DOWN = 0.6
    local GAP = 0.10
    local function airKeyDown(vk)
        if type(isKeyDown) ~= "function" then return false end
        local ok, d = pcall(isKeyDown, vk)
        return ok and d == true
    end
    local function airLogPath()
        local dir = (type(getWorkingDirectory) == "function" and getWorkingDirectory()) or "."
        return dir .. "\\grnd_air_log.txt"
    end
    local function airLogOpen(A)
        local ok, fh = pcall(io.open, airLogPath(), "w")
        if ok and fh then A.log = fh; A.logT0 = os.clock() end
    end
    local function airLog(A, text)
        if not A.log then return end
        local ok = pcall(function()
            A.log:write(string.format("%8.2f  %s\n", os.clock() - (A.logT0 or 0), text))
            A.log:flush()
        end)
        if not ok then A.log = nil end
    end
    local function airLogClose(A)
        if A.log then pcall(function() A.log:close() end) end
        A.log = nil
    end
    local function airDespawn(A, why)
        airLog(A, "REMOVE: " .. why)
        if A.obj and type(deleteObject) == "function" then pcall(deleteObject, A.obj) end
        A.obj, A.objZ = nil, nil
    end
    local function airRemove(A)
        airLog(A, "REMOVE: объект удалён (F4 или выключен чит)")
        if A.obj and type(deleteObject) == "function" then pcall(deleteObject, A.obj) end
        A.obj, A.objZ = nil, nil
        airLogClose(A)
    end
    local function airFrame()
        local A = GRND_AIR
        local key = airKeyDown(0x73)
