        A.prevKey = key
        if not A.on then
            if A.obj then airRemove(A) end
            return
        end
        if not (PLAYER_PED and type(doesCharExist) == "function" and doesCharExist(PLAYER_PED)) then return end
        local specNow = false
        if type(grndCamSpectating) == "function" then
            local okS, sv = pcall(grndCamSpectating)
            specNow = okS and sv == true
        end
        local deadNow = false
        if type(isCharDead) == "function" then
            local okD, dv = pcall(isCharDead, PLAYER_PED)
            deadNow = okD and dv == true
        end
        if deadNow then
            if A.obj then airDespawn(A, "персонаж умер (больница)") end
            A.needSpawn = false
            A.lastPX = nil
            return
        end
        if specNow then
            if A.obj then airDespawn(A, "слежка") end
            A.needSpawn = false
            A.lastPX = nil
            return
        end
        if (fresh or A.needSpawn) and not (type(grndIsTyping) == "function" and grndIsTyping())
           and not (type(GRND_KEYS) == "table" and GRND_KEYS.uiBusy) then
            if A.obj then
                airRemove(A)
            else
                local okP, x, y, z = pcall(getCharCoordinates, PLAYER_PED)
                if okP and type(z) == "number" and type(createObject) == "function" then
                    local okO, obj = pcall(createObject, PLATFORM_MODEL, x, y, z - OBJ_OFF)
                    if okO and obj then
                        A.obj = obj
                        A.objZ = z - OBJ_OFF
                        A.objX, A.objY, A.lastZ = x, y, A.objZ
                        A.needSpawn = false
                        if not A.log then airLogOpen(A) end
                        airLog(A, string.format("CREATE: модель=%d масштаб=%.2f персонаж=(%.2f, %.2f, %.2f) объект=(%.2f, %.2f, %.2f)",
                            PLATFORM_MODEL, PLATFORM_SCALE, x, y, z, x, y, A.objZ))
                        if type(setObjectScale) == "function" then pcall(setObjectScale, obj, PLATFORM_SCALE) end
                        if type(setObjectCollision) == "function" then pcall(setObjectCollision, obj, true) end
                    end
                end
            end
        end
        if not A.obj then return end
        local okP, x, y, z = pcall(getCharCoordinates, PLAYER_PED)
        if not okP or type(z) ~= "number" then return end
        if A.lastPX and not A.needSpawn then
            local jx, jy, jz = x - A.lastPX, y - A.lastPY, z - A.lastPZ
            if math.sqrt(jx * jx + jy * jy + jz * jz) > 6 then
                airDespawn(A, string.format("телепорт персонажа (сдвиг %.1f м)", math.sqrt(jx * jx + jy * jy + jz * jz)))
                A.lastPX = nil
                return
            end
        end
        A.lastPX, A.lastPY, A.lastPZ = x, y, z
        local vx, vy, vz = 0, 0, 0
        if type(getCharVelocity) == "function" then
            local okV, a1, a2, a3 = pcall(getCharVelocity, PLAYER_PED)
            if okV and type(a1) == "number" then vx, vy, vz = a1, a2 or 0, a3 or 0 end
        end
        local nowT = os.clock()
        local dtS = math.min(0.1, nowT - (A.tFrame or nowT))
        A.tFrame = nowT
        local feetZ = z - FEET_OFF
        local topZ = A.objZ + HALF_H
        local grounded = math.abs(vz) < 0.3
        local newZ = feetZ - HALF_H - GAP
        local canMove = grounded and feetZ <= topZ + ON_TOL and feetZ >= topZ - STEP_DOWN
        if canMove and newZ < A.objZ and feetZ > topZ - 0.3 then canMove = false end
        if canMove then
            if math.abs(newZ - A.objZ) > 0.001 then
                airLog(A, string.format("OBJZ: %.3f -> %.3f (ступни=%.2f)", A.objZ, newZ, feetZ))
            end
            A.objZ = newZ
        end
        if not grounded and vz > 0.3 and newZ > A.objZ then
            local stepUp = math.min(newZ - A.objZ, (vz + 1.0) * dtS)
            if stepUp > 0.001 then
                A.objZ = A.objZ + stepUp
                airLog(A, string.format("JUMP-UP: objZ -> %.3f (ступни=%.2f vz=%.2f)", A.objZ, feetZ, vz))
            end
        end
        if not grounded then
            A.objX, A.objY = x, y
        end
        local dx, dy = x - A.objX, y - A.objY
        local dist = math.sqrt(dx * dx + dy * dy)
        if dist > 0.0001 then
            local maxStep = (math.sqrt(vx * vx + vy * vy) + 1.5) * dtS
            local k = math.min(1, maxStep / dist)
            A.objX = A.objX + dx * k
            A.objY = A.objY + dy * k
        end
        if type(setObjectCoordinates) == "function" then
            pcall(setObjectCoordinates, A.obj, A.objX, A.objY, A.objZ)
        end
        A.lastZ = A.objZ
        local now = os.clock()
        if A.log then
            if not A.logAt or now - A.logAt >= 0.1 then
                A.logAt = now
                local vx, vy, vz = 0, 0, 0
                if type(getCharVelocity) == "function" then
                    local okV, a1, a2, a3 = pcall(getCharVelocity, PLAYER_PED)
                    if okV and type(a1) == "number" then vx, vy, vz = a1, a2 or 0, a3 or 0 end
                end
                local inAir = "?"
                if type(isCharInAir) == "function" then
                    local okA, r = pcall(isCharInAir, PLAYER_PED)
                    if okA then inAir = tostring(r) end
                end
                local oz = "?"
                if type(getObjectCoordinates) == "function" then
                    local _, c1, c2, c3, c4 = pcall(getObjectCoordinates, A.obj)
                    local zz = (type(c4) == "number" and c4) or (type(c3) == "number" and c3) or nil
                    if zz then oz = string.format("%.2f", zz) end
                end
                airLog(A, string.format(
                    "STATE: перс=(%.2f, %.2f, %.2f) ступни=%.2f верх=%.2f objZ=%.2f объект_z_игры=%s смещение=%.2f vel=(%.2f, %.2f, %.2f) вВоздухе=%s",
                    x, y, z, feetZ, topZ, A.objZ, oz, math.sqrt(dx * dx + dy * dy), vx, vy, vz, inAir))
            end
        end
        local spaceNow = airKeyDown(0x20)
        if spaceNow and not A.prevSpace then airLog(A, string.format("SPACE: нажат пробел, перс z=%.2f", z)) end
        A.prevSpace = spaceNow
    end
    GRND_AIR.frame = airFrame
end
