local function grndKeyName(vk)
    if not vk or vk <= 0 then return "Назначить" end
    if type(libs) == "table" and libs.vkeys and libs.vkeys.id_to_name then
        local ok, n = pcall(libs.vkeys.id_to_name, vk)
        if ok and n and #n > 0 then
            return n:gsub("^VK_", "")
        end
    end
    if VK_NAMES[vk] then return VK_NAMES[vk] end
    return string.format("0x%02X", vk)
end
local function grndInvisToggle()
