local _camMem = { ffi = nil, triedFfi = false }
local function grndCamMemFfi()
    if _camMem.triedFfi then return _camMem.ffi end
    _camMem.triedFfi = true
    local ok, ffi = pcall(require, "ffi")
    if ok and ffi then _camMem.ffi = ffi end
    return _camMem.ffi
end
local function grndWrFloat(addr, val)
    val = tonumber(val) or 0.0
    local ffi = grndCamMemFfi()
    if ffi then
        local ok = pcall(function()
            local p = ffi.cast("float*", addr)
            p[0] = val
        end)
        if ok then return true end
    end
    local mem = (type(libs) == "table" and libs.memory) or grndMemLib()
    if mem then
        local fn = mem.setfloat or mem.writefloat
        if type(fn) == "function" then
            local ok = pcall(fn, addr, val, true)
            if ok then return true end
        end
    end
    if type(writeMemory) == "function" and type(representFloatAsInt) == "function" then
        local ok = pcall(writeMemory, addr, 4, representFloatAsInt(val), true)
        if ok then return true end
    end
    return false
end
local function grndRdFloat(addr)
    local ffi = grndCamMemFfi()
    if ffi then
        local ok, v = pcall(function()
            local p = ffi.cast("float*", addr)
            return tonumber(p[0])
        end)
        if ok and type(v) == "number" then return v end
    end
    local mem = (type(libs) == "table" and libs.memory) or grndMemLib()
    if mem then
        local fn = mem.getfloat or mem.readfloat
        if type(fn) == "function" then
            local ok, v = pcall(fn, addr, true)
            if ok and type(v) == "number" then return v end
        end
    end
    return nil
end
local function grndWrU8(addr, val)
