        if ok then return true end
    end
    local mem = (type(libs) == "table" and libs.memory) or grndMemLib()
    if mem then
        local fn = mem._set8 or mem.setint8 or mem.setuint8 or mem.writeint8
        if type(fn) == "function" then
            local ok = pcall(fn, addr, val, true)
            if ok then return true end
        end
    end
    if type(writeMemory) == "function" then
        local ok = pcall(writeMemory, addr, 1, val, true)
        if ok then return true end
    end
    return false
end
local function grndRdU8(addr)
    local ffi = grndCamMemFfi()
    if ffi then
        local ok, v = pcall(function()
            local p = ffi.cast("uint8_t*", addr)
            return tonumber(p[0])
        end)
        if ok and type(v) == "number" then return v end
    end
    local mem = (type(libs) == "table" and libs.memory) or grndMemLib()
    if mem then
        local fn = mem._get8 or mem.getint8 or mem.getuint8 or mem.readint8
        if type(fn) == "function" then
            local ok, v = pcall(fn, addr, true)
            if ok and type(v) == "number" then return v end
        end
