grndIsPlayerAiming = function()
    local wmode = grndRdU8(0xB6F028 + 0x830)
    if wmode and wmode > 0 then return true end
    local activeCam = grndRdU8(0xB6F028 + 0x59) or 0
    local camMode = grndRdU8(0xB6F028 + 0x174 + (activeCam % 3) * 0x238 + 0x0C)
    if camMode == 53 or camMode == 7 or camMode == 8 or camMode == 40 or camMode == 51 then
        return true
    end
    if type(getCharPlayerIsTargeting) == "function" then
        local ok, res = pcall(getCharPlayerIsTargeting, PLAYER_HANDLE or 0)
        if ok and res then return true end
    end
    return false
end
