function grndAfkInit()
    local A = GRND_AFK
    local okF, ffi = pcall(require, "ffi")
    if not (okF and type(ffi) == "table" and ffi.cdef and ffi.load and ffi.new) then return false end
    pcall(ffi.cdef, "unsigned long long __stdcall GetTickCount64(void);")
    pcall(ffi.cdef, "void* __stdcall GetForegroundWindow(void);")
    pcall(ffi.cdef, "unsigned long __stdcall GetWindowThreadProcessId(void* hWnd, unsigned long* lpdwProcessId);")
    pcall(ffi.cdef, "unsigned long __stdcall GetCurrentProcessId(void);")
    local okL, k32, u32 = pcall(function() return ffi.load("kernel32"), ffi.load("user32") end)
    if not (okL and k32 and u32) then return false end
    local okP, pid = pcall(function() return tonumber(k32.GetCurrentProcessId()) end)
    if not (okP and pid) then return false end
    local okB, pidBuf = pcall(ffi.new, "unsigned long[1]")
    if not okB then return false end
    A.ffi, A.k32, A.u32, A.pid, A.pidBuf = ffi, k32, u32, pid, pidBuf
    local okT, tv = pcall(k32.GetTickCount64)
    A.useWall = (okT and tonumber(tv) ~= nil) and true or false
    A.ffiReady = true
    return true
end
pcall(grndAfkInit)
function grndAfkNow()
    local A = GRND_AFK
    if A.useWall then
        local ok, v = pcall(A.k32.GetTickCount64)
        local n = ok and tonumber(v)
        if n then return n / 1000 end
    end
    return os.clock()
end
function grndAfkWindowFocused()
    local A = GRND_AFK
    if not A.ffiReady then return nil end
    local okF, fg = pcall(A.u32.GetForegroundWindow)
    if not okF or fg == nil then return nil end
    local okH, hc = pcall(A.ffi.cast, "uintptr_t", fg)
    local hv = okH and tonumber(hc)
    if not hv then return nil end
    if hv == 0 then return false end
    local okP = pcall(A.u32.GetWindowThreadProcessId, fg, A.pidBuf)
    if not okP then return nil end
    return tonumber(A.pidBuf[0]) == A.pid
end
function grndAfkSuspendFrame()
    local A = GRND_AFK
