end
function grndAfkReadBytes(addr, n)
    local out = {}
    for i = 0, n - 1 do
        local b = grndRdU8(addr + i)
        if type(b) ~= "number" then return nil end
        out[#out + 1] = b % 256
    end
    return out
end
function grndAfkBytesEq(a, b)
    if type(a) ~= "table" or type(b) ~= "table" or #a ~= #b then return false end
    for i = 1, #a do
        if a[i] ~= b[i] then return false end
    end
    return true
end
function grndAfkWriteByte(addr, value)
    local mem = grndMemLib()
    if mem then
        if type(mem.setuint8) == "function" and pcall(mem.setuint8, addr, value, true) then return true end
        if type(mem._set8) == "function" and pcall(mem._set8, addr, value >= 128 and value - 256 or value, true) then return true end
    end
    if type(writeMemory) == "function" and pcall(writeMemory, addr, 1, value, true) then return true end
    return false
end
function grndAfkPatchApply()
    local A = GRND_AFK
    local now = grndAfkNow()
    local matched = 0
    for _, p in ipairs(A.patches) do
        local cur = grndAfkReadBytes(p.addr, #p.on)
        local isOn = false
        if grndAfkBytesEq(cur, p.on) then
            isOn = true
        elseif grndAfkBytesEq(cur, p.off) then
            local retryLater = A.retryAt[p.addr] and now < A.retryAt[p.addr]
            if not retryLater then
                local done = 0
                for i, b in ipairs(p.on) do
                    if not grndAfkWriteByte(p.addr + i - 1, b) then break end
                    done = i
                end
                if done == #p.on and grndAfkBytesEq(grndAfkReadBytes(p.addr, #p.on), p.on) then
                    A.patchApplied[p.addr] = true
                    A.retryAt[p.addr] = nil
                    isOn = true
                else
                    A.patchApplied[p.addr] = nil
                    A.retryAt[p.addr] = now + 5
                    for i = 1, done do grndAfkWriteByte(p.addr + i - 1, p.off[i]) end
                end
            end
        else
            A.patchApplied[p.addr] = nil
        end
        if isOn then matched = matched + 1 end
    end
    return matched
end
function grndAfkPatchRestore()
    local A = GRND_AFK
    for _, p in ipairs(A.patches) do
        if A.patchApplied[p.addr] then
            if grndAfkBytesEq(grndAfkReadBytes(p.addr, #p.on), p.on) then
                for i, b in ipairs(p.off) do grndAfkWriteByte(p.addr + i - 1, b) end
            end
            A.patchApplied[p.addr] = nil
        end
    end
    A.retryAt = {}
end
function grndAfkCamBase()
    local ad = GRND_AFK.addr
    local idx = grndRdU8(ad.cam + ad.activeIdx)
    if type(idx) ~= "number" then return nil end
    return ad.cam + ad.cams + (idx % 3) * ad.stride
end
function grndAfkInVehicle()
    if type(isCharInAnyCar) ~= "function" or not PLAYER_PED then return false end
    local ok, v = pcall(isCharInAnyCar, PLAYER_PED)
    return (ok and v) and true or false
end
function grndAfkRand(lo, hi)
    return lo + math.random() * (hi - lo)
end
function grndAfkClamp(home, value, lim)
    if value > home + lim then return home + lim end
    if value < home - lim then return home - lim end
    return value
end
function grndAntiAfkTick()
    local A = GRND_AFK
    if A.stopping then return end
    local cfg = A.cfg
    if not A.on then
        if next(A.patchApplied) ~= nil then grndAfkPatchRestore() end
        A.anim = nil
        return
    end
    local now = grndAfkNow()
    if cfg.unpausePatch then
        local matched = grndAfkPatchApply()
        if not A.patchNoticed then
            A.patchNoticed = true
            if matched < #A.patches then
                grndAfkNotify(string.format("Анти-AFK: патч паузы применён не полностью (%d из %d). Сборка игры может отличаться, пауза при свёрнутом окне возможна.",
                    matched, #A.patches), "info", 8)
