    end
    if not spawned then A.anim = nil; return end
    local base = grndAfkCamBase()
    if not base then A.anim = nil; return end
    if grndCamSpectating() then A.anim = nil; return end
    if not cfg.rotateInVehicle and grndAfkInVehicle() then A.anim = nil; return end
    local focus = grndAfkWindowFocused()
    local blockReason = nil
    if cfg.onlyWhenUnfocused and focus ~= false then
        blockReason = (focus == nil) and "focusunknown" or "focus"
    elseif (now - A.lastInputAt) < cfg.idleSeconds then
        blockReason = "input"
    end
    local ad = A.addr
    if A.anim then
        if blockReason == "focus" or blockReason == "focusunknown" or (now - A.lastInputAt) < 0.5 then
            A.anim = nil
            return
        end
        local a = A.anim
        local t = (now - a.t0) / a.dur
        if t >= 1 then
            grndWrFloat(base + ad.horz, a.to)
            if a.vertBase then grndWrFloat(base + ad.vert, a.vertBase) end
            A.anim = nil
        else
            local e = t * t * (3 - 2 * t)
            local v = a.from + (a.to - a.from) * e
            grndWrFloat(base + ad.horz, v)
            if a.vertBase and cfg.verticalWobbleDeg > 0 then
                grndWrFloat(base + ad.vert,
                    a.vertBase + math.sin(t * math.pi) * cfg.verticalWobbleDeg * math.pi / 180)
            end
        end
        return
    end
    local az = grndRdFloat(base + ad.horz)
    if not (az and az == az) then return end
    if now < A.nextTurnAt then return end
    if blockReason then
        A.nextTurnAt = now + grndAfkRand(4, 8)
        return
    end
    if not A.homeAz then A.homeAz = az end
    local eps = 0.5 * math.pi / 180
    local lim = cfg.maxDriftDeg * math.pi / 180
    local swing = cfg.maxSwingDeg * math.pi / 180
    local step = grndAfkRand(cfg.turnMinDeg, cfg.turnMaxDeg) * math.pi / 180
    if math.random() < 0.5 then step = -step end
    local target = grndAfkClamp(A.homeAz, az + step, lim)
    local d1 = target - az
    if math.abs(d1) > swing then target = az + (d1 > 0 and swing or -swing) end
    if math.abs(target - az) < eps then
        target = grndAfkClamp(A.homeAz, az - step, lim)
        local d2 = target - az
        if math.abs(d2) > swing then target = az + (d2 > 0 and swing or -swing) end
    end
    if math.abs(target - az) < eps then
        A.nextTurnAt = now + grndAfkRand(cfg.turnMinInterval, cfg.turnMaxInterval)
        return
    end
    local vert = grndRdFloat(base + ad.vert)
    local dur = math.max(0.2, cfg.turnDuration)
    A.anim = { from = az, to = target, t0 = now, dur = dur,
               vertBase = (vert and vert == vert) and vert or nil }
    A.nextTurnAt = now + dur + grndAfkRand(cfg.turnMinInterval, cfg.turnMaxInterval)
end
function grndAfkStartThread()
    local A = GRND_AFK
    if A.threadStarted then return true end
    if not (lua_thread and type(lua_thread.create) == "function") then return false end
    local okT = pcall(lua_thread.create, function()
        while true do
            wait(30)
            local ok, err = pcall(grndAntiAfkTick)
            if not ok and not A.errLogged then
                A.errLogged = true
                print("{FF6666}[GRND]{FFFFFF} Анти-AFK: ошибка в потоке: " .. tostring(err))
            end
        end
    end)
    A.threadStarted = (okT and true) or false
    return A.threadStarted
end
function grndAfkNotify(text, kind, life)
    if notify and type(notify.add) == "function" then
        pcall(notify.add, text, kind, life)
    else
        pcall(grndChatSay, "{00D6AA}[GRND]{FFFFFF} " .. tostring(text))
    end
end
function grndAfkToggle()
    local A = GRND_AFK
    A.on = not A.on
    A.anim = nil
    A.patchNoticed = false
    A.retryAt = {}
    if not A.on then
        pcall(grndAfkPatchRestore)
    end
    pcall(grndCamCfgSave)
    if A.on then
        grndAfkNotify("Анти-AFK: ВКЛ", "ok", 3)
    else
        grndAfkNotify("Анти-AFK: ВЫКЛ", "warn", 3)
    end
    return A.on
end
local function camCfgPath()
    if type(this_script_dir) == "function" then
        local okd, sd = pcall(this_script_dir)
        if okd and sd and tostring(sd) ~= "" then
            local pp = tostring(sd)
            while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
            local sep = "\\"
            local okc, cf = pcall(function() return package.config end)
            if okc and type(cf) == "string" and #cf > 0 then sep = cf:sub(1, 1) end
            return pp .. sep .. "grnd_settings.cfg"
        end
    end
    return "grnd_settings.cfg"
end
GRND_RING_KEY = GRND_RING_KEY or { on = true }
function grndRunFrame()
    local R = GRND_RUN
    if not R or type(setPlayerNeverGetsTired) ~= "function" or PLAYER_HANDLE == nil then return end
    if R.on then
        local now = os.clock()
        if now - (R.at or 0) >= 1 then
            R.at = now
            pcall(setPlayerNeverGetsTired, PLAYER_HANDLE, true)
        end
        R.applied = true
    elseif R.applied then
        R.applied = false
        R.at = 0
        pcall(setPlayerNeverGetsTired, PLAYER_HANDLE, false)
    end
end
function grndOxyFrame()
    local O = GRND_OXY
    if not O or type(setCharDrownsInWater) ~= "function" or PLAYER_PED == nil then return end
    if O.on then
        local now = os.clock()
        if now - (O.at or 0) >= 1 then
            O.at = now
            pcall(setCharDrownsInWater, PLAYER_PED, false)
        end
        O.applied = true
    elseif O.applied then
        O.applied = false
        O.at = 0
        pcall(setCharDrownsInWater, PLAYER_PED, true)
    end
end
local GRND_GETUP_ANIMS = {
    "FALL_FRONT", "FALL_BACK", "KO_SKID_FRONT", "KO_SKID_BACK", "FLOOR_HIT",
    "FLOOR_HIT_F", "GETUP_FRONT", "GETUP_BACK",
}
function grndGetupFrame()
    local G = GRND_GETUP
    if not G or not G.on then return end
    if type(isCharPlayingAnim) ~= "function" or type(clearCharTasksImmediately) ~= "function" then return end
    if PLAYER_PED == nil then return end
    for _, anim in ipairs(GRND_GETUP_ANIMS) do
        local ok, playing = pcall(isCharPlayingAnim, PLAYER_PED, anim)
        if ok and playing then
            pcall(clearCharTasksImmediately, PLAYER_PED)
            return
        end
    end
end
function grndCamCfgSave()
    local ok, f = pcall(GRND_CONFIG.open, camCfgPath(), "w")
    if not ok or not f then return false end
    f:write("camEnabled=" .. (GRND_CAM.enabled and "1" or "0") .. "\n")
    f:write("camDist=" .. string.format("%.1f", GRND_CAM.dist or 12.0) .. "\n")
    f:write("camHeight=" .. string.format("%.2f", GRND_CAM.heightMult or 1.0) .. "\n")
    f:write("camInVeh=" .. (GRND_CAM.inVehicle and "1" or "0") .. "\n")
    f:write("camResetAim=" .. (GRND_CAM.resetOnAim and "1" or "0") .. "\n")
    f:write("camWheel=" .. (GRND_CAM.wheelAdjust and "1" or "0") .. "\n")
    f:write("camFishEye=" .. (GRND_CAM.fovOn and "1" or "0") .. "\n")
    f:write("camFovOn=" .. (GRND_CAM.fovOn and "1" or "0") .. "\n")
    f:write("camFov=" .. string.format("%.1f", tonumber(GRND_CAM.fov) or 100.0) .. "\n")
    f:write("invisKey=" .. tostring(GRND_INVIS.key or 0) .. "\n")
    f:write("invisOn=" .. (GRND_INVIS.on and "1" or "0") .. "\n")
    f:write("invisGhost=" .. (GRND_INVIS.ghost and "1" or "0") .. "\n")
    f:write("invisAlpha=" .. tostring(GRND_INVIS.alpha or 140) .. "\n")
    f:write("abrOn=" .. (GRND_ABRK.on and "1" or "0") .. "\n")
    f:write("abrKey=" .. tostring(GRND_ABRK.key or 0) .. "\n")
    f:write("abrSpeed=" .. tostring(math.floor(GRND_ABRK.speed or 15)) .. "\n")
    f:write("afkOn=" .. ((GRND_AFK and GRND_AFK.on) and "1" or "0") .. "\n")
    f:write("airOn=" .. ((GRND_AIR and GRND_AIR.on) and "1" or "0") .. "\n")
    f:write("skipZZOn=" .. ((GRND_SKIPZZ and GRND_SKIPZZ.on) and "1" or "0") .. "\n")
    f:write("runOn=" .. ((GRND_RUN and GRND_RUN.on) and "1" or "0") .. "\n")
    f:write("oxyOn=" .. ((GRND_OXY and GRND_OXY.on) and "1" or "0") .. "\n")
    f:write("getupOn=" .. ((GRND_GETUP and GRND_GETUP.on) and "1" or "0") .. "\n")
    f:write("ringKeyOn=" .. ((GRND_RING_KEY and GRND_RING_KEY.on == false) and "0" or "1") .. "\n")
    f:write("arepOn=" .. (GRND_AREP.enabled and "1" or "0") .. "\n")
    f:write("arepKey=" .. tostring(GRND_AREP.key or 0) .. "\n")
    f:write("catchOn=" .. (GRND_CATCH.enabled and "1" or "0") .. "\n")
    f:write("catchKey=" .. tostring(GRND_CATCH.key or 0) .. "\n")
    f:write("rephudOn=" .. (GRND_REPHUD.enabled and "1" or "0") .. "\n")
    f:write("rephudScale=" .. string.format("%.2f",
        GRND_REPHUD.clampScale(GRND_REPHUD.scale)) .. "\n")
    f:write("rephudX=" .. tostring(math.floor(GRND_REPHUD.x or 16)) .. "\n")
    f:write("rephudY=" .. tostring(math.floor(GRND_REPHUD.y or 90)) .. "\n")
    if GRND_REPHUD.forceMode then
        f:write("rephudTextMode=" .. tostring(GRND_REPHUD.forceMode) .. "\n")
    end
    f:write("chatKey=" .. tostring(GRND_CHAT.key or 0) .. "\n")
    f:write("chatTime=" .. (GRND_CHAT.timestamps and "1" or "0") .. "\n")
    f:write("chatLines=" .. tostring(math.max(10, math.floor(GRND_CHAT.lines or 10))) .. "\n")
    f:write("chatIds=" .. ((GRND_CHAT.ids == false) and "0" or "1") .. "\n")
    f:write("clockOn=" .. (GRND_CLOCK.enabled and "1" or "0") .. "\n")
    f:write("clockScale=" .. string.format("%.2f", GRND_CLOCK.clampScale(GRND_CLOCK.scale)) .. "\n")
    f:write("clockX=" .. tostring(math.floor(tonumber(GRND_CLOCK.x) or 10)) .. "\n")
    f:write("clockY=" .. tostring(math.floor(tonumber(GRND_CLOCK.y) or 8)) .. "\n")
    f:write("chatInputOverlay=" .. (GRND_INPUT.enabled and "1" or "0") .. "\n")
    f:write("chatInputHistory=" .. (GRND_INPUT.showHistory and "1" or "0") .. "\n")
    f:write("gmAuto=" .. ((_G.GRND_GM and _G.GRND_GM.autoClient) and "1" or "0") .. "\n")
    f:write("gmSrv=" .. ((_G.GRND_GM and _G.GRND_GM.srv) and "1" or "0") .. "\n")
    f:write("uiTheme=" .. tostring((_G.GRND_UIKIT and _G.GRND_UIKIT.current) or "obsidian") .. "\n")
    if type(_G.grndMainExtSaveLines) == "function" then
        pcall(_G.grndMainExtSaveLines, f)
    end
    if GRND_UIKIT and GRND_UIKIT.customRGB then
        f:write("uiAccent=" .. table.concat(GRND_UIKIT.customRGB,",") .. "\n")
    end
    if _G.GRND_RC and _G.GRND_RC.posX and _G.GRND_RC.posY then
        f:write("rcX=" .. tostring(math.floor(_G.GRND_RC.posX)) .. "\n")
        f:write("rcY=" .. tostring(math.floor(_G.GRND_RC.posY)) .. "\n")
    end
    if _G.GRND_RC and _G.GRND_RC.cardW and _G.GRND_RC.cardH then
        f:write("rcW=" .. tostring(math.floor(_G.GRND_RC.cardW)) .. "\n")
        f:write("rcH=" .. tostring(math.floor(_G.GRND_RC.cardH)) .. "\n")
    end
    if _G.GRND_FORM_UI and _G.GRND_FORM_UI.x and _G.GRND_FORM_UI.y then
        f:write("formX=" .. tostring(math.floor(_G.GRND_FORM_UI.x)) .. "\n")
        f:write("formY=" .. tostring(math.floor(_G.GRND_FORM_UI.y)) .. "\n")
    end
    f:write("formWait=" .. string.format("%.2f", tonumber(_G.GRND_FORM_WAIT_SEC) or 2.5) .. "\n")
    do
        local settleSec = tonumber(_G.GRND_FORM_SETTLE_SEC)
        if not settleSec then settleSec = 0 end
        if settleSec < 0 then settleSec = 0 elseif settleSec > 2 then settleSec = 2 end
        f:write("formSettle=" .. string.format("%.2f", settleSec) .. "\n")
    end
    f:write("bulkDelay=" .. tostring(GRND_BULK.delay) .. "\n")
    f:write("wh_enabled=" .. (GRND_WH.enabled and "1" or "0") .. "\n")
    f:write("wh_skeleton=" .. (GRND_WH.skeleton and "1" or "0") .. "\n")
    f:write("wh_new=" .. (GRND_WH.newwh and "1" or "0") .. "\n")
    f:write("wh_stats=" .. (GRND_WH.autoStats and "1" or "0") .. "\n")
    f:write("wh_distance=" .. tostring(GRND_WH.distance) .. "\n")
    for k, v in pairs(GRND_TRACER.cfg) do
        local value = type(v) == "boolean" and (v and "1" or "0") or tostring(v)
        f:write("tr_" .. k .. "=" .. value .. "\n")
    end
    if GRND_RK then f:write("rkEnabled=" .. (GRND_RK.enabled and "1" or "0") .. "\n") end
    for k, v in pairs(GRND_ADMIN_CFG) do
        f:write("adm_" .. k .. "=" .. (v and "1" or "0") .. "\n")
    end
    do
        local SN = _G.grndSpecNative
        if SN then
            f:write("specCamDist=" .. string.format("%.1f",
                math.max(2.0, math.min(100.0, tonumber(SN.camStartDist) or 7.0))) .. "\n")
            f:write("specCamPitch=" .. string.format("%.2f",
                math.max(-0.15, math.min(0.45, tonumber(SN.camStartPitch) or 0.35))) .. "\n")
            f:write("specCamAngle=" .. string.format("%.2f",
                math.max(-6.283185, math.min(6.283185, tonumber(SN.camStartAngle) or 0.0))) .. "\n")
        end
    end
    pcall(function() f:close() end)
    GRND_CAM.cfgDirty = false
    return true
end
local function camCfgLoad()
    if GRND_CAM.cfgLoaded then return end
    GRND_CAM.cfgLoaded = true
    local ok, f = pcall(GRND_CONFIG.open, camCfgPath(), "r")
    if not ok or not f then return end
    local okc, content = pcall(function() return f:read("*a") end)
    pcall(function() f:close() end)
    if not okc or type(content) ~= "string" then return end
    local rhScaleSet, rhLegacyFont, rhLegacyScale = false, false, nil
    for line in (content .. "\n"):gmatch("([^\n]*)\n") do
        local k, v = line:match("^([%w_]+)=(.+)$")
        if k and v then
            local num = tonumber(v)
            if k == "camEnabled" then GRND_CAM.enabled = (v == "1")
            elseif k == "camDist" and num then
                GRND_CAM.dist = math.max(2.0, math.min(60.0, num))
                GRND_CAM.curDist = GRND_CAM.dist
            elseif k == "camHeight" and num then
                GRND_CAM.heightMult = math.max(0.5, math.min(3.0, num))
            elseif k == "camInVeh" then GRND_CAM.inVehicle = (v == "1")
            elseif k == "camResetAim" then GRND_CAM.resetOnAim = (v == "1")
            elseif k == "camWheel" then GRND_CAM.wheelAdjust = (v == "1")
            elseif k == "camFishEye" then GRND_CAM.fovOn = (v == "1")
            elseif k == "specCamDist" and num then
                local SN = _G.grndSpecNative
                if SN then
                    -- Old accidental extreme distances make the follow camera look down from far above.
                    if num > 20 then num = 7.0 end
                    SN.camStartDist = math.max(2.0, math.min(100.0, num))
                end
            elseif k == "specCamPitch" and num then
                local SN = _G.grndSpecNative
                if SN then
                    -- Keep saved entry angles in a normal third-person range; older/high values
                    -- can make the camera start above the target and immediately look down.
                    if num > 0.45 or num < -0.15 then num = 0.35 end
                    SN.camStartPitch = math.max(-0.15, math.min(0.45, num))
                end
            elseif k == "specCamAngle" and num then
                local SN = _G.grndSpecNative
                if SN then SN.camStartAngle = math.max(-6.283185, math.min(6.283185, num)) end
            elseif k == "invisKey" and num then
                GRND_INVIS.key = (num > 0) and num or nil
            elseif k == "invisOn" then
                GRND_INVIS.on = (v == "1")
            elseif k == "invisGhost" then
                GRND_INVIS.ghost = (v == "1")
            elseif k == "invisAlpha" and num then
                GRND_INVIS.alpha = math.max(10, math.min(255, num))
            elseif k == "abrOn" then
                GRND_ABRK.on = (v == "1")
            elseif k == "abrKey" and num then
                GRND_ABRK.key = (num > 0) and num or 0xA1
            elseif k == "abrSpeed" and num then
                GRND_ABRK.speed = math.max(1, math.min(700, num))
            elseif k == "afkOn" then
                if GRND_AFK then GRND_AFK.on = (v == "1") end
            elseif k == "airOn" then
                if GRND_AIR then GRND_AIR.on = (v == "1") end
            elseif k == "skipZZOn" then
                if GRND_SKIPZZ then GRND_SKIPZZ.on = (v == "1") end
            elseif k == "runOn" then
                if GRND_RUN then GRND_RUN.on = (v == "1") end
            elseif k == "oxyOn" then
                if GRND_OXY then GRND_OXY.on = (v == "1") end
            elseif k == "getupOn" then
                if GRND_GETUP then GRND_GETUP.on = (v == "1") end
            elseif k == "ringKeyOn" then
                if GRND_RING_KEY then GRND_RING_KEY.on = (v ~= "0") end
            elseif k == "arepOn" then
                GRND_AREP.enabled = (v == "1")
            elseif k == "arepKey" and num then
                GRND_AREP.key = (num > 0) and num or nil
            elseif k == "catchOn" then
                GRND_CATCH.enabled = (v == "1")
            elseif k == "catchKey" and num then
                GRND_CATCH.key = (num > 0) and num or nil
            elseif k == "rephudOn" then
                GRND_REPHUD.enabled = (v == "1")
            elseif k == "rephudScale" and num then
                GRND_REPHUD.scale = GRND_REPHUD.clampScale(num)
                rhScaleSet = true
            elseif k == "rephudFont" and num then
                if not rhScaleSet and not rhLegacyFont then
                    rhLegacyFont, rhLegacyScale = true, GRND_REPHUD.clampScale(num / 16)
                end
            elseif k == "rephudWidth" and num then
                if not rhScaleSet and not rhLegacyFont then
                    rhLegacyScale = GRND_REPHUD.clampScale(num / 360)
                end
            elseif k == "rephudTextMode" then
                local m = tostring(v or "")
                if m == "dx" or m == "scale" or m == "pushsize" or m == "push"
                    or m == "global" or m == "none" then
                    GRND_REPHUD.forceMode = m
                end
            elseif k == "rephudX" and num then
                GRND_REPHUD.x = num
            elseif k == "rephudY" and num then
                GRND_REPHUD.y = num
            elseif k == "chatKey" and num then
                GRND_CHAT.key = (num > 0) and num or 0x54
            elseif k == "chatTime" then
                GRND_CHAT.timestamps = (v == "1")
            elseif k == "chatLines" and num then
                GRND_CHAT.lines = math.max(10, math.min(20, math.floor(num + 0.5)))
            elseif k == "chatIds" then
                GRND_CHAT.ids = (v == "1")
            elseif k == "clockOn" then
                GRND_CLOCK.enabled = (v == "1")
            elseif k == "clockScale" and num then
                GRND_CLOCK.scale = GRND_CLOCK.clampScale(num)
            elseif k == "clockX" and num then
                GRND_CLOCK.x = math.floor(num + 0.5)
            elseif k == "clockY" and num then
                GRND_CLOCK.y = math.floor(num + 0.5)
            elseif k == "chatInputOverlay" then
                GRND_INPUT.enabled = (v == "1")
            elseif k == "chatInputHistory" then
                GRND_INPUT.showHistory = (v == "1")
            elseif k == "gmSrv" then
                _G.GRND_GM_SRV = (v == "1")
            elseif k == "gmAuto" then
                _G.GRND_GM_AUTO = (v == "1")
                if _G.GRND_GM then
                    _G.GRND_GM.autoClient = (v == "1")
                    _G.GRND_GM.autoServer = (v == "1")
                end
            elseif k == "uiAccent" then
                local r,g,b = v:match("^(%d+),(%d+),(%d+)$")
                if r and GRND_UIKIT then GRND_UIKIT.setCustom(r,g,b,false) end
            elseif k == "uiTheme" then
                if _G.GRND_UIKIT and _G.GRND_UIKIT.PALETTES[v] then
                    _G.GRND_UIKIT.apply(v)
                end
            elseif k:sub(1, 5) == "mext_" and type(_G.grndMainExtLoadLine) == "function" then
                pcall(_G.grndMainExtLoadLine, k:sub(6), v, num)
            elseif k == "rcX" and num then
                if _G.GRND_RC then _G.GRND_RC.posX = num end
            elseif k == "rcY" and num then
                if _G.GRND_RC then _G.GRND_RC.posY = num end
            elseif k == "rcW" and num then
                if _G.GRND_RC then _G.GRND_RC.cardW = num end
            elseif k == "rcH" and num then
                if _G.GRND_RC then _G.GRND_RC.cardH = num end
            elseif k == "formX" and num then
                if _G.GRND_FORM_UI then _G.GRND_FORM_UI.x = num end
            elseif k == "formY" and num then
                if _G.GRND_FORM_UI then _G.GRND_FORM_UI.y = num end
            elseif k == "formWait" and num then
                _G.GRND_FORM_WAIT_SEC = math.max(0.5, math.min(10.0, num))
            elseif k == "formSettle" and num then
                _G.GRND_FORM_SETTLE_SEC = math.max(0, math.min(2.0, num))
            elseif k == "bulkDelay" and num and num == num then
                GRND_BULK.delay = GRND_BULK.clampDelay(num)
            elseif k == "rkEnabled" then
                _G.GRND_RK_ENABLED = (v == "1")
            elseif k:sub(1, 3) == "wh_" then
                GRND_WH.load(k:sub(4), v)
            elseif k:sub(1, 3) == "tr_" then
                GRND_TRACER.load(k:sub(4), v)
            elseif k:sub(1, 4) == "adm_" then
                local admKey = k:sub(5)
                if GRND_ADMIN_CFG[admKey] ~= nil then
                    GRND_ADMIN_CFG[admKey] = (v == "1")
                end
            end
        end
    end
    if not rhScaleSet and rhLegacyScale then
        GRND_REPHUD.scale = GRND_REPHUD.clampScale(rhLegacyScale)
    end
end
GRND_CHATID = {cmdReg=false,roster={},at=-10}
do
    local I=GRND_CHATID
    function I.register()
        if I.cmdReg or type(sampRegisterChatCommand)~='function' then return end
        I.cmdReg=true
        sampRegisterChatCommand('chatid',function() I.setEnabled(GRND_CHAT.ids==false) end)
    end
    function I.setEnabled(on)
        GRND_CHAT.ids=on and true or false
        I.at=-10
        if grndCamCfgSave then pcall(grndCamCfgSave) end
        if GRND_CONFIG then GRND_CONFIG.flush() end
    end
    function I.refresh()
        if os.clock()-I.at<1 then return end
        I.at=os.clock();I.roster={}
        local maxid=1003
        if sampGetMaxPlayerId then local ok,n=pcall(sampGetMaxPlayerId);if ok and tonumber(n) then maxid=math.min(1003,math.max(0,n)) end end
        local function add(id)
            local ok,n=pcall(sampGetPlayerNickname,id)
            if ok and type(n)=='string' and #n>=2 and #n<=24 then I.roster[#I.roster+1]={nick=n,id=id} end
        end
        if sampIsPlayerConnected and sampGetPlayerNickname then
            for id=0,maxid do local ok,on=pcall(sampIsPlayerConnected,id);if ok and on then add(id) end end
        end
        if sampGetPlayerIdByCharHandle and PLAYER_PED and sampGetPlayerNickname then
            local ok,found,id=pcall(sampGetPlayerIdByCharHandle,PLAYER_PED)
            if ok and found and type(id)=='number' then add(id) end
        end
        table.sort(I.roster,function(a,b) return #a.nick>#b.nick end)
    end
    function I.flatten(text,base)
        local chars,map,cols={},{},{};local i=1;local color=base
        while i<=#text do
            local tag=text:sub(i,i+7)
            if tag:match('^{%x%x%x%x%x%x}$') then color=tonumber(tag:sub(2,7),16);i=i+8
            else
                chars[#chars+1]=text:sub(i,i);map[#chars]=i;cols[#chars]=color;i=i+1
            end
        end
        return table.concat(chars),map,cols
    end
    local function word(c) return c~='' and c:match('[%w_$@%%=]')~=nil end
    function I.transform(text,base)
        if GRND_CHAT.ids==false or type(text)~='string' or text=='' then return text,false end
        I.refresh()
        local plain,map,cols=I.flatten(text,base)
        local lower=plain:lower();local edits,occupied={},{}
        for _,player in ipairs(I.roster) do
            do
                local start=1
                while true do
                    local a,b=lower:find(player.nick:lower(),start,true)
                    if not a then break end;start=b+1
                    local before,after=plain:sub(a-1,a-1),plain:sub(b+1,b+1)
                    local free=not word(before) and not word(after)
                    if before=='.' and word(plain:sub(a-2,a-2)) then free=false end
                    if after=='.' and word(plain:sub(b+2,b+2)) then free=false end
                    for pos=a,b do if occupied[pos] then free=false;break end end
                    if free then
                        local ok,live=pcall(sampGetPlayerNickname,player.id)
                        free=ok and live==player.nick
                        if free and sampIsPlayerConnected then
                            local connected,on=pcall(sampIsPlayerConnected,player.id)
                            free=connected and on and true or false
                        end
                    end
                    if free then
                        local tail=plain:sub(b+1)
                        local spaces,id=tail:match('^(%s*)%[(%d+)%]')
                        local close=']'
                        if not id then spaces,id=tail:match('^(%s*)%((%d+)%)');close=')' end
                        local prefixStart,prefix=plain:sub(1,a-1):match('()%[(%d+)%]%s*$')
                        if id then
                            local first=b+1+#spaces;local last=first+#id+1
                            local desired=cols[b]
                            if cols[first]~=desired or cols[last]~=desired then
                                local marker=(close==']' and '[' or '(')..id..close
                                edits[#edits+1]={a=map[first],b=map[last],s=string.format('{%06X}%s{%06X}',desired,marker,cols[last])}
                            end
                            for pos=a,last do occupied[pos]=true end
                        elseif not prefix then
                            edits[#edits+1]={a=map[b]+1,b=map[b],s='['..player.id..']'}
                            for pos=a,b do occupied[pos]=true end
                        else
                            local last=prefixStart+#prefix+1;local desired=cols[b]
                            if cols[prefixStart]~=desired or cols[last]~=desired then
                                edits[#edits+1]={a=map[prefixStart],b=map[last],s=string.format('{%06X}[%s]{%06X}',desired,prefix,cols[last])}
                            end
                            for pos=prefixStart,b do occupied[pos]=true end
                        end
                    end
                end
            end
        end
        for _,pattern in ipairs({'()%[(%d+)%]()','()%((%d+)%)()'}) do
            for first,id,after in plain:gmatch(pattern) do
                local last=after-1
                if first>1 and word(plain:sub(first-1,first-1)) and not occupied[first] then
                    local desired=cols[first-1]
                    if cols[first]~=desired or cols[last]~=desired then
                        local marker=plain:sub(first,last)
                        edits[#edits+1]={a=map[first],b=map[last],s=string.format('{%06X}%s{%06X}',desired,marker,cols[last])}
                    end
                    for pos=first,last do occupied[pos]=true end
                end
            end
        end
        if #edits==0 then return text,false end
        table.sort(edits,function(a,b) return a.a>b.a end)
        local out=text
        for _,e in ipairs(edits) do out=out:sub(1,e.a-1)..e.s..out:sub(e.b+1) end
        return out,true
    end
    function I.emit(text,argb)
        if not sampAddChatMessage then return false end
        local ok,res=pcall(sampAddChatMessage,text,grndChatNativeColor(text,argb))
        return ok and res~=false
    end
    function grndChatIdOnMsg(color,text)
        I.register()
        if GRND_CHAT.ids==false then return false end
        local c=(tonumber(color) or -1)%4294967296
        local rgb=math.floor(c/256);local argb=(c%256)*16777216+rgb
        local out,changed=I.transform(text,rgb)
        if not changed then return false end
        if not grndChatLeadingRgb(out) then out=string.format('{%06X}%s',rgb,out) end
        if #out>144 then return false end
        return {color,out}
    end
    function grndChatIdOnPlayerMessage(id,text)
        if GRND_CHAT.ids==false or not sampGetPlayerNickname then return false end
        local ok,nick=pcall(sampGetPlayerNickname,id)
        if not ok or type(nick)~='string' or nick=='' then return false end
        local color=0xFFFFFFFF
        if sampGetPlayerColor then local good,c=pcall(sampGetPlayerColor,id);if good and type(c)=='number' then color=c%4294967296 end end
        local rgb=color%16777216
        local line=string.format('{%06X}%s[%d]: {FFFFFF}%s',rgb,nick,id,text)
        line=I.transform(line,rgb)
        return I.emit(line,color)
    end
end
local function grndAbrkTarget()
    if type(isCharInAnyCar) == "function" and type(getCarCharIsUsing) == "function" then
        local okI, ic = pcall(isCharInAnyCar, PLAYER_PED)
        if okI and ic then
            local okC, cv = pcall(getCarCharIsUsing, PLAYER_PED)
            if okC and cv and cv ~= 0 then return true, cv end
        end
    end
    return false, nil
end
local function grndAbrkGetPos(inCar, car)
    if inCar and type(getCarCoordinates) == "function" then
        local ok, x, y, z = pcall(getCarCoordinates, car)
        if ok and type(x) == "number" then return x, y, z end
    end
    if type(getCharCoordinates) == "function" then
        local ok, x, y, z = pcall(getCharCoordinates, PLAYER_PED)
        if ok and type(x) == "number" then return x, y, z end
    end
    return nil
end
local function grndAbrkSetPos(inCar, car, x, y, z)
    if inCar and car and type(setCarCoordinates) == "function" then
        pcall(setCarCoordinates, car, x, y, z)
        return
    end
    if type(setCharCoordinates) == "function" then
        pcall(setCharCoordinates, PLAYER_PED, x, y, z)
    end
end
local function grndAbrkStopMotion(inCar, car)
    if inCar and car then
        if type(setCarVelocity) == "function" then
            pcall(setCarVelocity, car, 0, 0, 0)
        end
    elseif type(setCharVelocity) == "function" then
        pcall(setCharVelocity, PLAYER_PED, 0, 0, 0)
    end
end
local function grndAbrkMem()
    if GRND_ABRK.mm ~= nil then
        return GRND_ABRK.mm or nil
    end
    local mem
    local ok, m2 = pcall(require, "memory")
    if ok and type(m2) == "table" then
        mem = m2
    elseif type(_G.memory) == "table" then
        mem = _G.memory
    end
    if mem then
        GRND_ABRK.mm = {
            rf = mem.getfloat or mem.readfloat,
            r8 = mem.getint8 or mem.readint8 or mem.readbyte or mem.getbyte,
        }
    else
        GRND_ABRK.mm = false
    end
    return GRND_ABRK.mm or nil
end
local function grndAbrkKeyHeld(vk)
    if not vk or vk <= 0 then return false end
    if (vk == 0xA0 or vk == 0xA1) and GRND_ABRK.wmShiftDown == vk then
        return true
    end
    if grndGAKS then
        local ok, st = pcall(grndGAKS, vk)
        if ok and st ~= nil then
            local v = tonumber(st)
            if v then
                if v < 0 then v = v + 65536 end
                return v >= 32768
            end
        end
    end
    if type(isKeyDown) == "function" then
        local ok, d = pcall(isKeyDown, vk)
        if ok and d then return true end
    end
    return false
end
local function grndAbrkToggle()
    GRND_ABRK.on = not GRND_ABRK.on
    GRND_ABRK.fly = false
    GRND_ABRK.prevKey = false
    pcall(grndCamCfgSave)
    if notify and type(notify.add) == "function" then
        pcall(notify.add, "AirBreak: " .. (GRND_ABRK.on and "ВКЛ" or "ВЫКЛ"),
            GRND_ABRK.on and "ok" or "warn", 3)
    elseif type(sampAddChatMessage) == "function" then
        pcall(grndChatSay, string.format(
            "{00D6AA}[GRND]{FFFFFF} AirBreak: {00D6AA}%s{FFFFFF}",
            GRND_ABRK.on and "ВКЛ" or "ВЫКЛ"), -1)
    end
end
function grndAirBreakTick()
    if not GRND_ABRK.on then
        GRND_ABRK.prevKey = false
        return
    end
    local nativeDialogOpen = grndServerWinBlocks()
    local typing = (type(grndIsTyping) == "function") and grndIsTyping() or false
    typing = typing or nativeDialogOpen
    if not (PLAYER_PED and type(doesCharExist) == "function"
        and doesCharExist(PLAYER_PED)) then return end
    local nowT = os.clock()
    local dt = nowT - (GRND_ABRK.lastT or nowT)
    GRND_ABRK.lastT = nowT
    if dt <= 0 or dt > 0.1 then dt = 0.016 end
    local held = grndAbrkKeyHeld(GRND_ABRK.key or 0xA1)
    if held and not GRND_ABRK.prevKey and not typing then
        GRND_ABRK.fly = not GRND_ABRK.fly
        GRND_ABRK.prevKey = held
        if GRND_ABRK.fly then
            local inCar0, car0 = grndAbrkTarget()
            local x0, y0, z0 = grndAbrkGetPos(inCar0, car0)
            if x0 then
                grndAbrkSetPos(inCar0, car0, x0, y0, z0)
                local x1, y1, z1 = grndAbrkGetPos(inCar0, car0)
                local off = (z1 and z0 and (z1 - z0)) or 0
                if math.abs(off) > 2 then off = 0 end
                GRND_ABRK.zOff = off
                GRND_ABRK.z = z1 or z0
                GRND_ABRK.hx, GRND_ABRK.hy = x0, y0
            end
        else
            GRND_ABRK.z, GRND_ABRK.zOff = nil, nil
            GRND_ABRK.hx, GRND_ABRK.hy = nil, nil
        end
        if notify and type(notify.add) == "function" then
            pcall(notify.add, "AirBreak: полёт " .. (GRND_ABRK.fly and "ВКЛ" or "ВЫКЛ"),
                GRND_ABRK.fly and "ok" or "warn", 2)
        end
        return
    end
    GRND_ABRK.prevKey = held
    if not GRND_ABRK.fly then return end
    if typing then
        local chatOpen = false
        if type(sampIsChatInputActive) == "function" then
            local okChat, activeChat = pcall(sampIsChatInputActive)
            chatOpen = okChat and activeChat and true or false
        end
        local holdForDialog = false
        if nativeDialogOpen and not chatOpen then
            if type(grndSessionReady) == "function" then
                local okReady, ready = pcall(grndSessionReady)
                holdForDialog = okReady and ready and true or false
            elseif type(grndUiBlocked) == "function" then
                local okBlocked, blocked = pcall(grndUiBlocked)
                holdForDialog = okBlocked and not blocked and true or false
            else
                holdForDialog = true
            end
        end
        if chatOpen or holdForDialog then
            local inCarChat, carChat = grndAbrkTarget()
            if type(GRND_ABRK.hx) ~= "number" or type(GRND_ABRK.hy) ~= "number"
                or type(GRND_ABRK.z) ~= "number" then
                local ax, ay, az = grndAbrkGetPos(inCarChat, carChat)
                if type(ax) == "number" and type(ay) == "number" and type(az) == "number" then
                    GRND_ABRK.hx, GRND_ABRK.hy = ax, ay
                    GRND_ABRK.z, GRND_ABRK.zOff = az, 0
                end
            end
            if type(GRND_ABRK.hx) == "number" and type(GRND_ABRK.hy) == "number"
                and type(GRND_ABRK.z) == "number" then
                grndAbrkSetPos(inCarChat, carChat, GRND_ABRK.hx, GRND_ABRK.hy,
                    GRND_ABRK.z - (GRND_ABRK.zOff or 0))
            end
            grndAbrkStopMotion(inCarChat, carChat)
        end
        return
    end
    local inCar, car = grndAbrkTarget()
    local cx, cy, cz = grndAbrkGetPos(inCar, car)
    if not cx then return end
    local fx, fy, rx, ry
    GRND_ABRK.camDir = false
    local MM = grndAbrkMem()
    if MM and MM.rf and MM.r8 then
        local oki, ci = pcall(MM.r8, 0xB6F028 + 0x59)
        if oki and type(ci) == "number" then
            if ci < 0 then ci = ci + 256 end
            ci = ci % 256
            if ci < 3 then
                local base = 0xB6F028 + 0x174 + ci * 0x238
                local okx, fxv = pcall(MM.rf, base + 0x190)
                local oky, fyv = pcall(MM.rf, base + 0x194)
                if okx and oky and type(fxv) == "number" and type(fyv) == "number"
                    and math.abs(fxv) < 10 and math.abs(fyv) < 10
                    and (fxv ~= 0 or fyv ~= 0) then
                    local hn = math.sqrt(fxv * fxv + fyv * fyv)
                    if hn > 0.15 then
                        fx, fy = fxv / hn, fyv / hn
                        rx, ry = fy, -fx
                        GRND_ABRK.camDir = true
                    end
                end
            end
        end
    end
    if not fx then
        fx, fy, rx, ry = 0, 1, 1, 0
        if type(getCharHeading) == "function" then
            local okH, hd = pcall(getCharHeading, PLAYER_PED)
            if okH and type(hd) == "number" then
                local rad = math.rad(hd)
                fx, fy = -math.sin(rad), math.cos(rad)
                rx, ry = math.cos(rad), math.sin(rad)
            end
        end
    end
    local mx, my, mz = 0, 0, 0
    if grndAbrkKeyHeld(0x57) then mx, my = mx + fx, my + fy end
    if grndAbrkKeyHeld(0x53) then mx, my = mx - fx, my - fy end
    if grndAbrkKeyHeld(0x44) then mx, my = mx + rx, my + ry end
    if grndAbrkKeyHeld(0x41) then mx, my = mx - rx, my - ry end
    if grndAbrkKeyHeld(0x26) then mz = mz + 1 end
    if grndAbrkKeyHeld(0x28) then mz = mz - 1 end
    if GRND_ABRK.camDir and not inCar
        and type(setCharHeading) == "function" then
        local hd2 = math.deg(math.atan2(-fx, fy))
        pcall(setCharHeading, PLAYER_PED, hd2)
    end
    if mx == 0 and my == 0 and mz == 0 then
        if type(GRND_ABRK.z) == "number" and GRND_ABRK.hx then
            grndAbrkSetPos(inCar, car, GRND_ABRK.hx, GRND_ABRK.hy,
                GRND_ABRK.z - (GRND_ABRK.zOff or 0))
        end
        grndAbrkStopMotion(inCar, car)
        return
    end
    local sp = (GRND_ABRK.speed or 15) * dt
    local n = math.sqrt(mx * mx + my * my + mz * mz)
    local hx, hy, hz = mx / n * sp, my / n * sp, mz / n * sp
    if type(GRND_ABRK.z) ~= "number" then
        if inCar and car and type(setCarCoordinates) == "function" then
            pcall(setCarCoordinates, car, cx, cy, cz)
        elseif type(setCharCoordinates) == "function" then
            pcall(setCharCoordinates, PLAYER_PED, cx, cy, cz)
        end
        local cz2
        if inCar and car and type(getCarCoordinates) == "function" then
            local ok2, _, _, z2 = pcall(getCarCoordinates, car)
            if ok2 and type(z2) == "number" then cz2 = z2 end
        end
        if not cz2 and type(getCharCoordinates) == "function" then
            local ok2, _, _, z2 = pcall(getCharCoordinates, PLAYER_PED)
            if ok2 and type(z2) == "number" then cz2 = z2 end
        end
        local off = (cz2 and (cz2 - cz)) or 0
        if math.abs(off) > 2 then off = 0 end
        GRND_ABRK.zOff = off
        GRND_ABRK.z = cz2 or cz
    end
    GRND_ABRK.z = GRND_ABRK.z + hz
    local nzW = GRND_ABRK.z - (GRND_ABRK.zOff or 0)
    local nx, ny = cx + hx, cy + hy
    GRND_ABRK.hx, GRND_ABRK.hy = nx, ny
    grndAbrkSetPos(inCar, car, nx, ny, nzW)
    grndAbrkStopMotion(inCar, car)
end
function grndCamPlayerAnchor()
    if not PLAYER_PED or type(getCharCoordinates)~='function' then return nil end
    local ok,x,y,z
    if type(isCharInAnyCar)=='function' and isCharInAnyCar(PLAYER_PED)
        and type(storeCarCharIsInNoSave)=='function' and type(getCarCoordinates)=='function' then
        local good,car=pcall(storeCarCharIsInNoSave,PLAYER_PED)
        if good and type(car)=='number' and car>0 then ok,x,y,z=pcall(getCarCoordinates,car) end
    end
    if not ok then ok,x,y,z=pcall(getCharCoordinates,PLAYER_PED) end
    if ok and type(x)=='number' and type(y)=='number' and type(z)=='number'
        and x==x and y==y and z==z then return {x=x,y=y,z=z+0.9} end
end
function grndCamReadView()
    if grndCamSpectating() or grndIsPlayerAiming() then return nil end
    local base,M=grndCamActiveBase()
    if not base or not M.rf or not M.r32 then return nil end
    local okMode,mode=pcall(M.r32,base+0x0C)
    if not okMode or type(mode)~='number' then return nil end
    mode=mode%65536
    if mode==15 or mode==7 or mode==8 or mode==40 or mode==51 or mode==53 then return nil end
    if type(getActiveCameraCoordinates)~='function' then return nil end
    local ok,x,y,z=pcall(getActiveCameraCoordinates)
    local function valid(a,b,c)
        return type(a)=='number' and type(b)=='number' and type(c)=='number'
            and a==a and b==b and c==c and math.abs(a)<20000 and math.abs(b)<20000 and math.abs(c)<20000
    end
    if not ok or not valid(x,y,z) then return nil end
    local fx,fy,fz
    if type(getActiveCameraPointAt)=='function' then
        local good,tx,ty,tz=pcall(getActiveCameraPointAt)
        if good and valid(tx,ty,tz) then fx,fy,fz=tx-x,ty-y,tz-z end
    end
    local length=fx and math.sqrt(fx*fx+fy*fy+fz*fz) or 0
    if length<0.001 then
        local good,a,b,c=pcall(function()
            return M.rf(0xB6F028+0x994),M.rf(0xB6F028+0x998),M.rf(0xB6F028+0x99C)
        end)
        if not good or not valid(a,b,c) then return nil end
        fx,fy,fz=a,b,c;length=math.sqrt(a*a+b*b+c*c)
    end
    if length<0.001 then return nil end
    local anchor=grndCamPlayerAnchor()
    local v={x=x,y=y,z=z,fx=fx/length,fy=fy/length,fz=fz/length,
        anchor=anchor,at=grndCamNow(),mode=mode,base=base,wall={}}
    v.alpha=grndRdFloat(base+0xAC);v.beta=grndRdFloat(base+0xBC)
    v.fov=grndRdFloat(base+0xB4)
    v.native=grndCamUiSnapshot(base,M)
    return v
end
function grndCamUiSnapshot(base,M)
    if not (M and M.r32 and M.w32 and M.r8 and M.w8 and M.rf and M.wf) then return nil end
    local ok,N=pcall(function()
        local A=0xB6F028
        local mode=M.r32(base+0x0C)%65536
        if (mode~=4 and mode~=18) or M.r8(A+0x58)~=0 or M.r8(A+0x32)~=0 then return nil end
        local n={base=base,index=M.r8(A+0x59),words={},refs={},flags={},zoom={},
            at=grndCamNow(),ped=PLAYER_PED,target=M.r32(A+0x958),
            owner=M.r32(A+0xB0),nextMode=M.r32(A+0xC38)%65536,
            switch=M.r32(A+0xC3C)%65536,anchor=grndCamPlayerAnchor()}
        n.fovOriginal=GRND_CAM.fovState and GRND_CAM.fovState.original or M.rf(base+0xB4)
        n.inCar=type(isCharInAnyCar)=='function' and isCharInAnyCar(PLAYER_PED) or false
        if n.inCar then
            if type(storeCarCharIsInNoSave)~='function' then return nil end
            n.car=storeCarCharIsInNoSave(PLAYER_PED)
        end
        if type(getCharPointer)=='function' then n.pedPtr=getCharPointer(PLAYER_PED) end
        for _,off in ipairs({0x110,0x114,0x21C,0x22C,0x230}) do n.refs[off]=M.r32(base+off) end
        for off=0,0x234,4 do
            if n.refs[off]==nil then n.words[off]=M.r32(base+off) end
        end
        for _,off in ipairs({0x1A,0x1B,0x1C,0x29,0x2A,0x2B,0x2C,0x30,0x32,
            0x37,0x38,0x39,0x3A,0x4F,0x57,0x58}) do n.flags[off]=M.r8(A+off) end
        for _,off in ipairs({0xC0,0xC4,0xD4,0xD8}) do n.zoom[off]=M.r32(A+off) end
        return n
    end)
    if ok then return N end
end
function grndCamUiRestoreState(H)
    local N=H.native
    local _,M=grndCamActiveBase()
    if not N or not M then return false end
    local A=0xB6F028
    local valid=pcall(function()
        assert(PLAYER_PED==N.ped)
        assert(type(grndIsSpawned)~='function' or grndIsSpawned())
        if N.pedPtr then assert(getCharPointer(PLAYER_PED)==N.pedPtr) end
        local inCar=type(isCharInAnyCar)=='function' and isCharInAnyCar(PLAYER_PED) or false
        assert(inCar==N.inCar)
        if inCar then assert(storeCarCharIsInNoSave(PLAYER_PED)==N.car) end
        assert(M.r32(A+0x958)==N.target and M.r32(A+0xB0)==1)
        for off,value in pairs(N.refs) do assert(M.r32(N.base+off)==value) end
    end)
    if not valid then return false end
    local anchor=grndCamPlayerAnchor()
    local dx,dy,dz=0,0,0
    if anchor and N.anchor then
        dx,dy,dz=anchor.x-N.anchor.x,anchor.y-N.anchor.y,anchor.z-N.anchor.z
        if dx*dx+dy*dy+dz*dz>625 then return false end
    end
    local C=GRND_CAM
    local fov=C.fovState and C.fovState.current or N.fovOriginal
    local original=C.fovState and C.fovState.original
    local ok=pcall(function()
        for off,value in pairs(N.words) do M.w32(N.base+off,value) end
        if math.abs(dx)+math.abs(dy)+math.abs(dz)>0.001 then
            for _,off in ipairs({0x148,0x178,0x19C,0x1A8,0x1D8,0x1E4,0x1F0,0x1FC}) do
                M.wf(N.base+off,M.rf(N.base+off)+dx)
                M.wf(N.base+off+4,M.rf(N.base+off+4)+dy)
                M.wf(N.base+off+8,M.rf(N.base+off+8)+dz)
            end
        end
        local elapsed=math.max(0,math.floor((grndCamNow()-N.at)*1000))
        for _,off in ipairs({0x10,0x120,0x208,0x20C,0x210,0x214}) do
            local value=N.words[off]
            if value and value~=0 then M.w32(N.base+off,(value+elapsed)%4294967296) end
        end
        for off,value in pairs(N.zoom) do M.w32(A+off,value) end
        for off,value in pairs(N.flags) do M.w8(A+off,value) end
        M.w32(A+0xB0,N.owner)
        assert(grndCamWriteMode(M,A+0xC38,N.nextMode))
        assert(grndCamWriteMode(M,A+0xC3C,N.switch))
        M.w8(A+0x59,N.index)
        if type(fov)=='number' and fov==fov and fov>=5 and fov<=170 then M.wf(N.base+0xB4,fov) end
    end)
    if not ok then return false end
    if fov and original then
        C.fovState={base=N.base,current=fov,original=original,at=grndCamNow()}
        C.fovApplied=fov
    end
    C.heightBase=N.base;C.frameAt=grndCamNow()
