function grndCamUiApply(H,dt)
    local base,M=grndCamActiveBase()
    if not base or not M.wf or not M.r32 then return end
    local x,y,z=H.x,H.y,H.z
    local anchor=grndCamPlayerAnchor()
    if anchor and H.anchor then
        local dx,dy,dz=anchor.x-H.anchor.x,anchor.y-H.anchor.y,anchor.z-H.anchor.z
        x,y,z=x+dx,y+dy,z+dz
        if dx*dx+dy*dy+dz*dz>0.000001 or H.wallMoved then
            H.wallMoved=true
            local nx,ny,nz,hit=grndCamAvoidWalls(anchor.x,anchor.y,anchor.z,x,y,z,0)
            local ax,ay,az=x-anchor.x,y-anchor.y,z-anchor.z
            local desired=math.sqrt(ax*ax+ay*ay+az*az)
            local safe=math.sqrt((nx-anchor.x)^2+(ny-anchor.y)^2+(nz-anchor.z)^2)
            local d=grndCamClearance(H.wall,desired,safe,hit,grndCamNow(),dt)
            if desired>0.001 then x,y,z=anchor.x+ax*d/desired,anchor.y+ay*d/desired,anchor.z+az*d/desired end
        end
    end
    local changed=H.appliedBase~=base or not H.appliedX
        or math.abs(x-H.appliedX)+math.abs(y-H.appliedY)+math.abs(z-H.appliedZ)>0.001
    if not changed then return end
    grndCamWriteMode(M,base+0x0C,15)
    local function vec(addr,a,b,c) M.wf(addr,a);M.wf(addr+4,b);M.wf(addr+8,c) end
    local tx,ty,tz=x+H.fx*10,y+H.fy*10,z+H.fz*10
    vec(base+0x160,x,y,z);vec(base+0x154,tx,ty,tz);vec(base+0x16C,0,0,1)
    vec(0xB6F028+0x86C,x,y,z);vec(0xB6F028+0x860,tx,ty,tz);vec(0xB6F028+0x878,0,0,1)
    if H.appliedBase~=base then
        grndCamFovTransfer(base)
        local fov=GRND_CAM.fovState and GRND_CAM.fovState.current
            or (H.native and H.native.fovOriginal) or H.fov
        if type(fov)=='number' then grndCamFovMem(fov,base) end
    end
    H.appliedBase,H.appliedX,H.appliedY,H.appliedZ=base,x,y,z
end
