function grndCamMouseDelta(S,blocked)
    local now=grndCamNow()
    local mx,my=GRND_MOUSE and GRND_MOUSE.x or 0,GRND_MOUSE and GRND_MOUSE.y or 0
    blocked=blocked or GRND_CAM.windowFocused==false
    if blocked then S.mouseReady=nil;S.mouseTick=now;S.mouseX,S.mouseY=mx,my;return 0,0,false end
    if S.mouseTick==now then return 0,0,false end
    S.mouseTick=now
    if not S.mouseReady then
        S.mouseReady=true;S.mouseX,S.mouseY=mx,my;return 0,0,false
    end
    if type(getPcMouseMovement)=='function' then
        local ok,dx,dy=pcall(getPcMouseMovement)
        if ok and type(dx)=='number' and type(dy)=='number'
            and dx==dx and dy==dy and math.abs(dx)<4096 and math.abs(dy)<4096 then
            S.mouseX,S.mouseY=mx,my
            return dx,dy,true
        end
    end
    local dx,dy=mx-(S.mouseX or mx),my-(S.mouseY or my)
    S.mouseX,S.mouseY=mx,my
    if math.abs(dx)>160 or math.abs(dy)>160 then return 0,0,false end
    return dx,dy,false
end
function grndCamNormalMouseTick()
    local C=GRND_CAM
    C.mouseNormal=C.mouseNormal or {}
    local S=C.mouseNormal
    local blocked=grndCamSpectating() or grndIsPlayerAiming()
        or (type(grndIsSpawned)=='function' and not grndIsSpawned())
    local dx,dy,relative=grndCamMouseDelta(S,blocked)
    if blocked then S.base=nil;S.stallX=0;S.stallY=0;return end
    local base,M=grndCamActiveBase()
    if not base or not M.r32 then return end
    local ok,mode=pcall(M.r32,base+0x0C)
    if not ok or (mode%65536~=4 and mode%65536~=18) then S.base=nil;return end
    local alpha,beta=grndRdFloat(base+0xAC),grndRdFloat(base+0xBC)
    if type(alpha)~='number' or type(beta)~='number' or alpha~=alpha or beta~=beta
        or math.abs(alpha)>100 or math.abs(beta)>10000 then return end
    local edgeX,edgeY=false,false
    if type(getScreenResolution)=='function' and GRND_MOUSE and GRND_MOUSE.hasPosition then
        local good,w,h=pcall(getScreenResolution)
        if good and type(w)=='number' and type(h)=='number' then
            local x,y=GRND_MOUSE.x or 0,GRND_MOUSE.y or 0
            edgeX=x<=2 or x>=w-3;edgeY=y<=2 or y>=h-3
        end
    end
    local same=S.base==base
    local movedX=same and S.beta and math.abs((beta-S.beta+math.pi)%(2*math.pi)-math.pi)>0.00001
    local movedY=same and S.alpha and math.abs(alpha-S.alpha)>0.00001
    S.stallX=(same and relative and edgeX and dx~=0 and not movedX) and ((S.stallX or 0)+1) or 0
    S.stallY=(same and relative and edgeY and dy~=0 and not movedY) and ((S.stallY or 0)+1) or 0
    if S.stallX>=2 then
        local sensitivity=math.abs(grndRdFloat(0xB6EC1C) or 0.0025)
        beta=beta-math.max(-0.12,math.min(0.12,dx*sensitivity))
        grndWrFloat(base+0xBC,beta)
    end
    if S.stallY>=2 then
        local sensitivity=math.abs(grndRdFloat(0xB6EC18) or 0.0015)
        alpha=math.max(-1.5,math.min(1.5,alpha-math.max(-0.12,math.min(0.12,dy*sensitivity))))
        grndWrFloat(base+0xAC,alpha)
    end
    S.base,S.alpha,S.beta=base,alpha,beta
end
function grndCamDistanceRelease()
    local C=GRND_CAM;local old=C.distanceSaved
    if old then
        for addr,v in pairs(old.floats) do grndWrFloat(addr,v) end
        for addr,v in pairs(old.bytes) do grndWrU8(addr,v) end
    end
    C.distanceSaved=nil;C.wasActive=false;C.wallDist=nil;C.wallFilter=nil;C.wallAnchor=nil;C.heightCurrent=nil;C.heightBase=nil
end
local function grndCamTick()
    camCfgLoad()
    local C=GRND_CAM;local now=grndCamNow()
    local dt=math.max(0,math.min(0.1,now-(C.frameAt or (now-1/60))));C.frameAt=now
    grndCamFovApply()
    if not _G.grndModListTried and _G.GRND_CAM_VERBOSE then
        C.tickStartAt = C.tickStartAt or now
        if now - C.tickStartAt > 15 then
            pcall(grndListModules, "авто: 15 с после старта")
        end
    end
    if _G.grndWriterScan and not _G.grndWriterScan.done then
        pcall(grndFovWriterScanStep)
    end
    local spawned=false
    if type(grndIsSpawned)=='function' then
        local ok,v=pcall(grndIsSpawned);spawned=ok and v
    elseif type(sampIsLocalPlayerSpawned)=='function' then
        local ok,v=pcall(sampIsLocalPlayerSpawned);spawned=ok and v
    end
    local inCar=false
    if PLAYER_PED and type(isCharInAnyCar)=='function' then
        local ok,v=pcall(isCharInAnyCar,PLAYER_PED);inCar=ok and v
    end
    if not C.enabled or not spawned or grndCamSpectating()
        or (C.resetOnAim and grndIsPlayerAiming()) or (inCar and not C.inVehicle) then
        grndCamDistanceRelease();return
    end
    local base,M=grndCamActiveBase();if not base or not M or not M.r32 then return end
    local okMode,mode=pcall(M.r32,base+0x0C)
    if not okMode or type(mode)~='number' then return end
    mode=mode%65536
    if mode~=4 and mode~=18 then return end
    if not C.distanceSaved then
        local old={floats={},bytes={}}
        for _,off in ipairs({0xD4,0xD8,0xC0,0xC4}) do
            local v=grndRdFloat(0xB6F028+off)
            if type(v)=='number' and v==v then old.floats[0xB6F028+off]=v end
        end
        for _,off in ipairs({0x38,0x39}) do
            local v=grndRdU8(0xB6F028+off);if v then old.bytes[0xB6F028+off]=v end
        end
        C.distanceSaved=old
    end
    if C.distanceSaved.floats[base+0xD8]==nil then
        local v=grndRdFloat(base+0xD8)
        if type(v)=='number' and v==v then C.distanceSaved.floats[base+0xD8]=v end
    end
    local target=math.max(2,math.min(60,tonumber(C.dist) or 12))
    C.curDist=C.curDist or target
    C.curDist=C.curDist+(target-C.curDist)*(1-math.exp(-8*dt))
    if math.abs(target-C.curDist)<0.02 then C.curDist=target end
    grndWrU8(0xB6F028+0x38,1)
    grndWrU8(0xB6F028+0x39,C.inVehicle and 1 or 0)
    local distance=C.curDist
    local anchor=grndCamPlayerAnchor()
    if anchor and type(getActiveCameraCoordinates)=='function' then
        local ok,x,y,z=pcall(getActiveCameraCoordinates)
        if ok and type(x)=='number' and type(y)=='number' and type(z)=='number' then
            local dx,dy,dz=x-anchor.x,y-anchor.y,z-anchor.z
            local length=math.sqrt(dx*dx+dy*dy+dz*dz)
            if length>0.01 then
                local scale=inCar and 1.15 or 1
                local desired=C.curDist*scale
                local px,py,pz=anchor.x+dx/length*desired,anchor.y+dy/length*desired,anchor.z+dz/length*desired
                local nx,ny,nz,hit=grndCamAvoidWalls(anchor.x,anchor.y,anchor.z,px,py,pz,0)
                local safe=math.sqrt((nx-anchor.x)^2+(ny-anchor.y)^2+(nz-anchor.z)^2)
                if C.wallAnchor and ((anchor.x-C.wallAnchor.x)^2+(anchor.y-C.wallAnchor.y)^2+(anchor.z-C.wallAnchor.z)^2)>625 then
                    C.wallFilter=nil
                end
                C.wallAnchor=anchor
                C.wallFilter=C.wallFilter or {}
                distance=grndCamClearance(C.wallFilter,desired,safe,hit,now,dt)/scale
            end
        end
    end
    grndWrFloat(0xB6F028+0xD8,distance)
    if C.inVehicle then grndWrFloat(0xB6F028+0xC4,distance*1.15) end
    local heightTarget=math.max(0.4,math.min(3.5,tonumber(C.heightMult) or 1))
    if C.heightBase~=base or not C.heightCurrent then
        local h=grndRdFloat(base+0xD8)
        C.heightCurrent=(type(h)=='number' and h==h and h>0 and h<10) and h or heightTarget
        C.heightBase=base
    end
    C.heightCurrent=C.heightCurrent+(heightTarget-C.heightCurrent)*(1-math.exp(-6*dt))
    if math.abs(C.heightCurrent-heightTarget)<0.002 then C.heightCurrent=heightTarget end
    grndWrFloat(base+0xD8,C.heightCurrent)
    C.wasActive=true
end
