local function grndUiMovementGuardTick()
    local approvalPopupOpen = false
    if not (approvalPopupOpen or GRND_UI_MOUSE.uiGuard or GRND_UI_MOUSE.active) then return end
    if grndNativeChatInputActive() and not approvalPopupOpen then return end
    if type(grndIsSpawned)=="function" then
        local ok,spawned=pcall(grndIsSpawned)
        if not ok or not spawned then return end
    end
    if GRND_ABRK and GRND_ABRK.fly then return end
    if type(grndCamSpectating)=="function" then
        local ok,spec=pcall(grndCamSpectating)
        if ok and spec then return end
    end
    if type(isKeyDown)~="function" or not PLAYER_PED then return end
    local movingKey=false
    for i=1,#GRND_UI_MOVE_KEYS do
        local ok,down=pcall(isKeyDown,GRND_UI_MOVE_KEYS[i])
        if ok and down then movingKey=true;break end
    end
    if not movingKey and not approvalPopupOpen then return end
    local inCar=false
    if type(isCharInAnyCar)=="function" then
        local ok,value=pcall(isCharInAnyCar,PLAYER_PED)
        inCar=ok and value and true or false
    end
    if inCar then
        if type(storeCarCharIsInNoSave)=="function" and type(setCarVelocity)=="function" then
            local ok,car=pcall(storeCarCharIsInNoSave,PLAYER_PED)
            if ok and type(car)=="number" and car>0 then pcall(setCarVelocity,car,0,0,0) end
        end
    elseif type(setCharVelocity)=="function" then
        pcall(setCharVelocity,PLAYER_PED,0,0,0)
    end
end
function grndCamWindowsOpen()
    local now=grndCamNow()
    if grndCamWindowsRaw() then GRND_CAM.uiHoldUntil=now+0.12;return true end
    local untilTime=GRND_CAM.uiHoldUntil
    if untilTime and untilTime-now>0.2 then GRND_CAM.uiHoldUntil=nil;return false end
    return untilTime~=nil and now<untilTime
end
local GRND_CAM_DIAG = {
    enabled=false, file=nil, path=nil, started=0, lastSignature=nil,
    nextSample=0, sampleUntil=0, lines=0, maxLines=1800,
    lastCameraError=nil, lastErrorAt=0,
}
local function grndCamDiagWrite(tag, body)
    local D=GRND_CAM_DIAG
    if not D.enabled or not D.file then return false end
    local now=grndCamNow()
    local line=string.format("[%8.3f] %-10s %s\n", now-(D.started or now), tostring(tag or "LOG"), tostring(body or ""))
    local ok=pcall(function() D.file:write(line);D.file:flush() end)
    if not ok then
        local f=D.file;D.file=nil;D.enabled=false
        if f then pcall(function() f:close() end) end
        return false
    end
    D.lines=(D.lines or 0)+1
    if D.lines>=D.maxLines then
        local f=D.file;D.file=nil;D.enabled=false
        if f then pcall(function() f:write("[limit] max log lines reached; auto-stopped\n");f:flush();f:close() end) end
    end
    return true
end
local function grndCamDiagStop(reason)
    local D=GRND_CAM_DIAG
    if not D.enabled and not D.file then return false,D.path end
    local path,f=D.path,D.file
    D.enabled=false;D.file=nil
    if f then
        pcall(function()
            f:write(string.format("[%8.3f] STOP       %s\n", grndCamNow()-(D.started or 0), tostring(reason or "manual")))
            f:flush();f:close()
        end)
    end
    return true,path
end
local function grndCamDiagStart()
    local D=GRND_CAM_DIAG
    if D.enabled then return true,D.path end
    if D.file then pcall(function() D.file:close() end);D.file=nil end
    local okPath,path=pcall(grndStoragePath,"logs","grnd_camera_diag.log")
    if not okPath or type(path)~="string" then return false,tostring(path) end
    if not io or type(io.open)~="function" then return false,"io.open unavailable" end
    local okFile,f=pcall(io.open,path,"w")
    if not okFile or not f then return false,tostring(f or "cannot open log") end
    D.file,D.path=f,path
    D.enabled=true;D.started=grndCamNow();D.lastSignature=nil
    D.nextSample=0;D.sampleUntil=D.started+1.0;D.lines=0
    D.lastCameraError=nil;D.lastErrorAt=0
    GRND_UI_MOUSE.blockedGameMessages=0;GRND_UI_MOUSE.blockedGameKeys=0
    grndCamDiagWrite("START","v1.15.43; 5-second forms/GNEWS; allowlist; AirBreak chat/server-dialog hold")
    return true,path
end
local function grndCamDiagBoolCall(fn)
    if type(fn)~="function" then return false end
    local ok,value=pcall(fn)
    return ok and value and true or false
end
local function grndCamDiagWindowSignature()
    local flags={}
    local function add(name,value) if value then flags[#flags+1]=name end end
    local K=GRND_KEYS or {}
    add("chat",K.typing or grndCamDiagBoolCall(sampIsChatInputActive))
    add("dialog",K.dlgActive or grndCamDiagBoolCall(sampIsDialogActive))
    add("pause",grndCamDiagBoolCall(isPauseMenuActive))
    add("score",grndCamDiagBoolCall(sampIsScoreboardOpen))
    add("menu",GRND_REF and GRND_REF.menu and GRND_REF.menu.open)
    add("tab",GRND_TAB and GRND_TAB.open)
    add("report",_G.GRND_REP and _G.GRND_REP.open)
    add("clwAim",GRND_REF and GRND_REF.clw and GRND_REF.clw.aiming)
    add("recon",_G.GRND_RC and _G.GRND_RC.show)
    add("reconPrompt",_G.GRND_RC and _G.GRND_RC.prompt)
    add("forms",_G.GRND_FORMS and _G.GRND_FORMS.active)
    add("gnews",_G.GRND_GNEWS and _G.GRND_GNEWS.active)
    add("log",_G.GRND_LOG and (_G.GRND_LOG.viewerOpen or _G.GRND_LOG.dateOpen))
    add("targetRing",_G.GRND_TARGET_RING and _G.GRND_TARGET_RING.capture)
    add("killList",_G.GRND_KL and _G.GRND_KL.moving)
    add("adminOverlay",_G.GRND_AO and _G.GRND_AO.moving)
    add("softChecker",_G.GRND_SFR and _G.GRND_SFR.moving)
    add("farChat",_G.GRND_FCHAT and _G.GRND_FCHAT.moving)
    add("weekStats",_G.GRND_WEEKSTATS and _G.GRND_WEEKSTATS.moving)
    local imguiCapture=(GRND_KEYS and (GRND_KEYS.imguiCaptureMouse or GRND_KEYS.imguiCaptureKeyboard)) and true or false
    if not imguiCapture then
        local ioState=grndSafeGetIO(_G.GRND_IM)
        imguiCapture=ioState and (ioState.WantCaptureMouse or ioState.WantCaptureKeyboard) and true or false
    end
    add("imgui",imguiCapture)
    local raw=grndCamDiagBoolCall(grndCamWindowsRaw)
    if raw and #flags==0 then add("other",true) end
    return (#flags>0 and table.concat(flags,"+") or "none"),raw
end
local function grndCamDiagN(v)
    if type(v)~="number" or v~=v or math.abs(v)>100000 then return "-" end
    return string.format("%.3f",v)
end
local function grndCamDiagSnapshot(signature,raw,extraError)
    local C=GRND_CAM
    local okBase,base,M=pcall(grndCamActiveBase)
    if not okBase then base,M=nil,nil end
    local idx
    if type(grndRdU8)=="function" then local ok,v=pcall(grndRdU8,0xB6F028+0x59);if ok then idx=v end end
    local mode,alpha,beta,baseDist,baseFov
    if base and M then
        if M.r32 then
            local ok,v=pcall(M.r32,base+0x0C);if ok and type(v)=="number" then mode=v%65536 end
        end
        if M.rf then
            local okA,vA=pcall(M.rf,base+0xAC);if okA then alpha=vA end
            local okB,vB=pcall(M.rf,base+0xBC);if okB then beta=vB end
            local okD,vD=pcall(M.rf,base+0xD8);if okD then baseDist=vD end
            local okF,vF=pcall(M.rf,base+0xB4);if okF then baseFov=vF end
        end
    end
    local function globalFloat(addr)
        local fn=M and M.rf
        if type(fn)=="function" then local ok,v=pcall(fn,addr);if ok then return v end end
        if type(grndRdFloat)=="function" then local ok,v=pcall(grndRdFloat,addr);if ok then return v end end
        return nil
    end
    local camX,camY,camZ
    if type(getActiveCameraCoordinates)=="function" then
        local ok,x,y,z=pcall(getActiveCameraCoordinates)
        if ok then camX,camY,camZ=x,y,z end
    end
    local anchor
    if type(grndCamPlayerAnchor)=="function" then local ok,v=pcall(grndCamPlayerAnchor);if ok then anchor=v end end
    local ax,ay,az
    if anchor then ax,ay,az=anchor.x,anchor.y,anchor.z end
    local inCar=false
    if PLAYER_PED and type(isCharInAnyCar)=="function" then
        local ok,v=pcall(isCharInAnyCar,PLAYER_PED);inCar=ok and v and true or false
    end
    local spec=grndCamDiagBoolCall(grndCamSpectating)
    local aiming=grndCamDiagBoolCall(grndIsPlayerAiming)
    local spawned=grndCamDiagBoolCall(grndIsSpawned)
    local FS=C.fovState
    local SC=_G.grndSpecNative or {}
    local SD=type(SC.camDbg)=="table" and SC.camDbg or {}
    local specActive=(_G.GRND_SPEC and _G.GRND_SPEC.active) and true or false
    local err=tostring(extraError or "-"):gsub("[\r\n\t]"," "):sub(1,120)
    return string.format(
        "ui=%s raw=%d focus=%s menuBusy=%s enabled=%s dist=%s cur=%s d8=%s d4=%s c4=%s base=%s mode=%s idx=%s baseD8=%s saved=%s heightCfg=%s heightNow=%s fovOn=%s fovCfg=%s fovRaw=%s fovState=%s/orig=%s fovHold=%s fovExt=%s fovFight=%s fovWhy=%s fovFix=%s/%s alpha=%s beta=%s cam=%s,%s,%s ped=%s,%s,%s spec=%s aim=%s spawn=%s inCar=%s orbitOn=%s orbitActive=%s orbitPitch=%s orbitAngle=%s orbitDist=%s orbitSrc=%s orbitXYZ=%s orbitPre=%s orbitMode=%s err=%s mouseGate=%s uiGuard=%s keyDrop=%d mouseDrop=%d stick=%d/%s",
        tostring(signature),raw and 1 or 0,tostring(C.windowFocused),tostring(GRND_KEYS and GRND_KEYS.uiBusy),
        tostring(C.enabled),grndCamDiagN(C.dist),grndCamDiagN(C.curDist),grndCamDiagN(globalFloat(0xB6F028+0xD8)),
        grndCamDiagN(globalFloat(0xB6F028+0xD4)),grndCamDiagN(globalFloat(0xB6F028+0xC4)),
        base and string.format("0x%X",base) or "-",grndCamDiagN(mode),grndCamDiagN(idx),grndCamDiagN(baseDist),
        tostring(C.distanceSaved~=nil),grndCamDiagN(C.heightMult),grndCamDiagN(C.heightCurrent),tostring(C.fovOn),grndCamDiagN(C.fov),
        grndCamDiagN(baseFov),grndCamDiagN(FS and FS.current),grndCamDiagN(FS and FS.original),
        tostring(C.fovHoldUntil and string.format("%.1fs",(C.fovHoldUntil-grndCamNow())) or "-"),
        grndCamDiagN(C.fovExtN),
        tostring(C.fovFightUntil and "fight" or ((FS and FS.fightWon) and "won" or "-")),
        tostring(C.fovWhy and (C.fovWhy .. "@" .. string.format("%.0f", C.fovWhyAt or 0)) or "-"),
        tostring(C.fovFixN or 0),grndCamDiagN(C.fovFixLast),
        grndCamDiagN(alpha),grndCamDiagN(beta),grndCamDiagN(camX),grndCamDiagN(camY),grndCamDiagN(camZ),
        grndCamDiagN(ax),grndCamDiagN(ay),grndCamDiagN(az),tostring(spec),tostring(aiming),tostring(spawned),tostring(inCar),
        tostring(SC.camOn==true),tostring(specActive),grndCamDiagN(SC.camPitch),
        grndCamDiagN(SC.camAngle),grndCamDiagN(SC.camDistCur or SC.camDist),
        tostring(SD.src or "-"),tostring(SD.xyz or "-"),grndCamDiagN(SD.preMode),
        grndCamDiagN(SC.camAppliedMode),err,
        tostring(GRND_UI_MOUSE.active or grndCamNow()<(GRND_UI_MOUSE.blockUntil or 0)),
        tostring(GRND_UI_MOUSE.uiGuard),math.floor(tonumber(GRND_UI_MOUSE.blockedGameKeys) or 0),
        math.floor(tonumber(GRND_UI_MOUSE.blockedGameMessages) or 0),
        math.floor(tonumber(GRND_STICKY and GRND_STICKY.clears) or 0),
        tostring(GRND_STICKY and GRND_STICKY.reason or "-"))
end
local function grndCamDiagTick(cameraError)
    local D=GRND_CAM_DIAG
    if not D.enabled then return end
    local now=grndCamNow()
    if now-(D.started or now)>180 then grndCamDiagStop("180s timeout");return end
    local signature,raw=grndCamDiagWindowSignature()
    if D.lastSignature~=signature then
        grndCamDiagWrite("UI_CHANGE",tostring(D.lastSignature or "start").." -> "..tostring(signature))
        D.lastSignature=signature;D.sampleUntil=now+3.0
    end
    local interval=(now<(D.sampleUntil or 0)) and 0.10 or 0.50
    if now>=(D.nextSample or 0) then
        grndCamDiagWrite("SAMPLE",grndCamDiagSnapshot(signature,raw,cameraError))
        D.nextSample=now+interval
    elseif cameraError then
        local message=tostring(cameraError):gsub("[\r\n\t]"," "):sub(1,180)
        if message~=D.lastCameraError or now-(D.lastErrorAt or 0)>=0.5 then
            grndCamDiagWrite("CAM_ERROR",message)
            D.lastCameraError,D.lastErrorAt=message,now
        end
    end
end
GRND_TARGET_RING = _G.GRND_TARGET_RING or {
    on = false, mode = "player", radiusMeters = 400,
    radiusRatio = 0.34, minPlayerDistance = 2.0, lastTarget = nil,
    slots = { left = {}, right = {}, vehicle = {} },
    loaded = false, dirty = false, armed = {}, consumed = {},
    uiMode = "player", uiSide = "right", uiIndex = 1,
}
GRND_SPEC_CAR_NODE_NEAR = nil
GRND_RING_FIXED_LEFT = {
    { name = "Починить транспорт", key = 0x31, command = "/fixcar" },
    { name = "Перевернуть транспорт", key = 0x32, command = "/flip" },
    { name = "Отобрать все оружие", key = 0x33, command = "/rgun" },
    { name = "Следить за игроком", key = 0x34, command = "/sp" },
    { name = "ТП на дорогу", key = 0x35, action = "tproad" },
}
local function grndRingSlot(side, index)
    local R = _G.GRND_TARGET_RING
    if not R then return nil end
    R.slots = R.slots or { left = {}, right = {}, vehicle = {} }
    local max = (side == "vehicle") and 3 or 9
    if side ~= "vehicle" and side ~= "left" and side ~= "right" then return nil end
    index = tonumber(index)
    if not index or index ~= math.floor(index) or index < 1 or index > max then
        return nil
    end
    R.slots[side] = R.slots[side] or {}
    local slot = R.slots[side][index]
    if not slot then
        slot = { name = "", command = "", key = 0, mods = 0 }
        R.slots[side][index] = slot
    end
    return slot
end
local function grndRingClean(s, maxChars)
    s = tostring(s or ""):gsub("[%z\r\n]", " ")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")
    if type(grndBinderUtf8Cut) == "function" then
        return (grndBinderUtf8Cut(s, maxChars))
    end
    return s:sub(1, maxChars)
end
local function grndRingCfgPath()
    if type(this_script_dir) == "function" then
        local ok, dir = pcall(this_script_dir)
        if ok and type(dir) == "string" and dir ~= "" then
            dir = dir:gsub("[/\\]+$", "")
            local sep = (type(package.config) == "string")
                and package.config:sub(1, 1) or "\\"
            return dir .. sep .. "grnd_ring.cfg"
        end
    end
    return "grnd_ring.cfg"
end
local function grndRingCfgEncode(s)
    return (tostring(s or ""):gsub("%%", "%%25"):gsub("|", "%%7C"))
end
local function grndRingCfgDecode(s)
    return (tostring(s or ""):gsub("%%7[Cc]", "|"):gsub("%%25", "%%"))
end
function grndRingApplyFixedDefaults(R)
    local changed = false
    for i = 1, 9 do
        local slot = grndRingSlot("left", i)
        if slot.name ~= "" or slot.command ~= "" or slot.key ~= 0 or slot.mods ~= 0 then
            slot.name, slot.command, slot.key, slot.mods = "", "", 0, 0
            changed = true
        end
    end
    for i = 1, 9 do
        local slot = grndRingSlot("right", i)
        local key, mods = tonumber(slot.key) or 0, tonumber(slot.mods) or 0
        if key >= 0x31 and key <= 0x35 and mods == 4 then
            slot.key, slot.mods = 0, 0
            changed = true
        end
    end
    if changed then
        R.dirty, R.saveAt = true, os.clock() + 0.6
    end
end
function grndRingLoad()
    local R = _G.GRND_TARGET_RING
    if not R then return end
    if R.loaded then grndRingApplyFixedDefaults(R); return end
    R.loaded = true
    for _, side in ipairs({ "left", "right", "vehicle" }) do
        for i = 1, side == "vehicle" and 3 or 9 do
            grndRingSlot(side, i)
        end
    end
    local ok, f = pcall(GRND_CONFIG.open, grndRingCfgPath(), "r")
    if not ok or not f then grndRingApplyFixedDefaults(R); return end
    local got, content = pcall(function() return f:read("*a") end)
    pcall(function() f:close() end)
    if not got or type(content) ~= "string" or #content > 20000 then
        grndRingApplyFixedDefaults(R)
        return
    end
    local seen = { player = {}, vehicle = {} }
    for line in (content .. "\n"):gmatch("([^\n]*)\n") do
        line = line:gsub("\r$", "")
        local radius = line:match("^radius=(%d+)$")
        if radius then
            R.radiusMeters = math.max(20, math.min(600, tonumber(radius) or 400))
        end
        local side, i, k, m, name, cmd = line:match(
            "^([LRV])|(%d+)|(%d+)|(%d+)|([^|]*)|([^|]*)$")
        local si = ({ L = "left", R = "right", V = "vehicle" })[side]
        local slot = si and grndRingSlot(si, tonumber(i)) or nil
        if slot and si ~= "left" then
            slot.name = grndRingClean(grndRingCfgDecode(name), 32)
            slot.command = grndRingClean(grndRingCfgDecode(cmd), 144)
            slot.key = math.floor(math.max(0, math.min(255, tonumber(k) or 0)))
            slot.mods = math.floor(math.max(0, math.min(7, tonumber(m) or 0)))
            local group = si == "vehicle" and "vehicle" or "player"
            local code = slot.key * 8 + slot.mods
            if slot.key > 0 and seen[group][code] then slot.key, slot.mods = 0, 0 end
            if slot.key > 0 then seen[group][code] = true end
        end
    end
    grndRingApplyFixedDefaults(R)
end
function grndRingSerialize()
    local R = _G.GRND_TARGET_RING
    grndRingLoad()
    local lines = { "v=1", "radius=" .. tostring(math.floor(
        math.max(20, math.min(600, tonumber(R.radiusMeters) or 400)))) }
    for _, side in ipairs({ "left", "right", "vehicle" }) do
        local letter = ({ left = "L", right = "R", vehicle = "V" })[side]
        for i = 1, side == "vehicle" and 3 or 9 do
            local v = grndRingSlot(side, i)
            lines[#lines + 1] = table.concat({ letter, tostring(i),
                tostring(v.key or 0), tostring(v.mods or 0),
                grndRingCfgEncode(grndRingClean(v.name, 32)),
                grndRingCfgEncode(grndRingClean(v.command, 144)) }, "|")
        end
    end
    return table.concat(lines, "\n") .. "\n"
end
function grndRingTouch()
    local R = _G.GRND_TARGET_RING
    R.dirty = true
    R.saveAt = os.clock() + 0.6
end
function grndRingSave()
    local R = _G.GRND_TARGET_RING
    grndRingLoad()
    local ok, file = pcall(GRND_CONFIG.open, grndRingCfgPath(), "w")
    if not ok or not file then
        R.dirty = true
        R.saveAt = os.clock() + 3
        return false
    end
    local written = pcall(function() file:write(grndRingSerialize()); file:close() end)
    if not written then
        pcall(function() file:close() end)
        R.dirty = true
        R.saveAt = os.clock() + 3
        return false
    end
    R.dirty = false
    return true
end
function grndRingSpectating()
    if _G.GRND_SPEC and _G.GRND_SPEC.active then return true end
    if _G.GRND_RC and _G.GRND_RC.show then return true end
    if type(sampIsPlayerSpectating) == "function" then
        local ok, spec = pcall(sampIsPlayerSpectating)
        if ok and (spec == true or (type(spec) == "number" and spec == 9)) then
            return true
        end
    end
    return false
end
local function grndTargetRingMeters(R)
    local meters = tonumber(R.radiusMeters)
    if not meters or meters ~= meters then meters = 400 end
    meters = math.max(20, math.min(600, meters))
    R.radiusMeters = meters
    R.radiusRatio = 0.18 + (meters - 20) * (0.22 / 580)
    return meters
end
function grndTargetRingSceneReady()
    local spec = grndRingSpectating()
    if type(grndAuthDialogOpen) == "function" and grndAuthDialogOpen() then
        return false
    end
    if type(grndUiBlocked) == "function" and grndUiBlocked() and not spec then
        return false
    end
    if not spec and type(grndIsSpawnedSafe) == "function"
        and not grndIsSpawnedSafe() then return false end
    if type(grndIsTyping) == "function" and grndIsTyping() then return false end
    if GRND_KEYS and GRND_KEYS.blocked then return false end
    if (GRND_REF.menu and GRND_REF.menu.open)
        or (GRND_REF.clw and GRND_REF.clw.aiming)
        or (GRND_TAB and GRND_TAB.open)
        or (_G.GRND_RC and _G.GRND_RC.prompt)
        or (_G.GRND_REP and _G.GRND_REP.open)
        then
        return false
    end
    return true
end
function grndRingKeyOn()
    return not (GRND_RING_KEY and GRND_RING_KEY.on == false)
end
function grndRingSetKeyOn(v)
    GRND_RING_KEY.on = v and true or false
    local R = _G.GRND_TARGET_RING
    if not GRND_RING_KEY.on and R then
        R.on = false
        R.lastTarget = nil
        R.capture = nil
        R.armed, R.lastDownAt = {}, {}
    end
end
function grndTargetRingCanUseKey(vk)
    local R = _G.GRND_TARGET_RING
    if vk ~= 0x52 and vk ~= 0x45 then return false end
    if not grndRingKeyOn() then return false end
    if vk == 0x45 and (not R or not R.on) then return false end
    if not grndTargetRingSceneReady() then return false end
    local B = _G.GRND_BINDER
    if B and (B.binding or (B.byKey and B.byKey[vk])) then return false end
    if (GRND_CHAT and GRND_CHAT.key == vk)
        or (GRND_INVIS and GRND_INVIS.key == vk)
        or (GRND_AREP and GRND_AREP.key == vk)
        or (GRND_CATCH and GRND_CATCH.key == vk)
        or (GRND_ABRK and GRND_ABRK.key == vk) then return false end
    return true
end
local grndRingArmHeldOnSwitch
function grndTargetRingUseKey(vk)
    if not grndTargetRingCanUseKey(vk) then return false end
    grndRingLoad()
    local R = GRND_TARGET_RING
    if vk == 0x52 then
        R.on = not R.on
        if not R.on then R.lastTarget = nil end
    else
        R.mode = (R.mode == "vehicle") and "player" or "vehicle"
        R.lastTarget = nil
    end
    R.armed, R.lastDownAt = {}, {}
    R.consumed = R.consumed or {}
    if grndRingArmHeldOnSwitch then grndRingArmHeldOnSwitch() end
    return true
end
function grndTargetRingOnWheel(wparam)
    local R = _G.GRND_TARGET_RING
    if not R or not R.on or not grndTargetRingSceneReady() then return false end
    grndRingLoad()
    if type(isKeyDown) ~= "function" then return false end
    local ok, alt = pcall(isKeyDown, 0x12)
    if not ok or not alt then return false end
    local raw = math.floor((tonumber(wparam) or 0) / 65536) % 65536
    if raw >= 32768 then raw = raw - 65536 end
    if raw == 0 then return false end
    local notch = math.max(-3, math.min(3, raw / 120))
    if math.abs(notch) < 1 then notch = (raw > 0) and 1 or -1 end
    R.radiusMeters = math.max(20, math.min(600,
        grndTargetRingMeters(R) + notch * 25))
    grndTargetRingMeters(R)
    grndRingTouch()
    return true
end
local function grndRingScreenPoint(x, y, z, w, h)
    if type(x) ~= "number" or type(y) ~= "number" or type(z) ~= "number"
        or type(convert3DCoordsToScreen) ~= "function" then return nil end
    if type(isPointOnScreen) == "function" then
        local ok, seen = pcall(isPointOnScreen, x, y, z, 0.25)
        if ok and not seen then return nil end
    end
    local ok, sx, sy = pcall(convert3DCoordsToScreen, x, y, z)
    if not ok or type(sx) ~= "number" or type(sy) ~= "number"
        or sx ~= sx or sy ~= sy or sx < 0 or sy < 0 or sx > w or sy > h then
        return nil
    end
    return sx, sy
end
local function grndRingWorldOrigin()
    local spec = grndRingSpectating()
    if spec then
        local sid = (_G.GRND_SPEC and _G.GRND_SPEC.active)
            and tonumber(_G.GRND_SPEC.id) or nil
        if not sid and _G.GRND_RC and _G.GRND_RC.show then
            sid = tonumber(_G.GRND_RC.id)
        end
        if sid and sid >= 0 and sid <= 1003 then
            local ped
            if _G.grndSpecNative and type(_G.grndSpecNative.pedOf) == "function" then
                local ok, v = pcall(_G.grndSpecNative.pedOf, sid)
                if ok and type(v) == "number" then ped = v end
            end
            if not ped and type(sampGetCharHandleBySampPlayerId) == "function" then
                local ok, a, b = pcall(sampGetCharHandleBySampPlayerId, sid)
                if ok then
                    if type(a) == "number" then ped = a
                    elseif a == true and type(b) == "number" then ped = b end
                end
            end
            if ped and ped > 0 and type(getCharCoordinates) == "function" then
                local exists = true
                if type(doesCharExist) == "function" then
                    local ok, yes = pcall(doesCharExist, ped)
                    exists = ok and yes and true or false
                end
                if exists then
                    local ok, x, y, z = pcall(getCharCoordinates, ped)
                    if ok and type(x) == "number" and type(y) == "number"
                        and type(z) == "number" then return x, y, z, ped end
                end
            end
        end
        if type(getActiveCameraCoordinates) == "function" then
            local ok, x, y, z = pcall(getActiveCameraCoordinates)
            if ok and type(x) == "number" and type(y) == "number"
                and type(z) == "number" then return x, y, z, nil end
        end
        return nil
    end
    if type(getCharCoordinates) ~= "function" then return nil end
    local ok, x, y, z = pcall(getCharCoordinates, PLAYER_PED)
    if not ok or type(x) ~= "number" or type(y) ~= "number"
        or type(z) ~= "number" then return nil end
    return x, y, z, PLAYER_PED
end
local function grndRingVehicleId(car)
    if type(sampGetVehicleIdByCarHandle) ~= "function" then return nil end
    local ok, a, b = pcall(sampGetVehicleIdByCarHandle, car)
    if not ok then return nil end
    local vid = (type(a) == "number" and a) or (a == true and b) or nil
    if type(vid) ~= "number" or vid < 1 or vid > 2000
        or vid ~= math.floor(vid) then return nil end
    return vid
end
function grndTargetRingFind(w, h, cx, cy, radius)
    local R = _G.GRND_TARGET_RING
    if type(R) ~= "table" or type(radius) ~= "number" or radius <= 0 then return nil end
    grndRingLoad()
    local nowR = os.clock()
    local cached = R.cacheTgt
    if cached and (nowR - (R.cacheAt or 0)) < 0.25 then
        local alive, wx, wy, wz = true, nil, nil, nil
        if cached.kind == "player" then
            if type(doesCharExist) == "function" then
                local ok, yes = pcall(doesCharExist, cached.handle)
                alive = ok and (yes and true or false) or false
            end
            if alive and type(getCharCoordinates) == "function" then
                local ok, x, y, z = pcall(getCharCoordinates, cached.handle)
                if ok and type(x) == "number" and type(y) == "number"
                    and type(z) == "number" then wx, wy, wz = x, y, z end
            end
        elseif cached.kind == "vehicle" then
            if type(doesVehicleExist) == "function" then
                local ok, yes = pcall(doesVehicleExist, cached.handle)
                alive = ok and (yes and true or false) or false
            elseif type(doesCarExist) == "function" then
                local ok, yes = pcall(doesCarExist, cached.handle)
                alive = ok and (yes and true or false) or false
            end
            if alive and type(getCarCoordinates) == "function" then
                local ok, x, y, z = pcall(getCarCoordinates, cached.handle)
                if ok and type(x) == "number" and type(y) == "number"
                    and type(z) == "number" then wx, wy, wz = x, y, z + 0.7 end
            end
        end
        if not alive then
            R.cacheTgt = nil
        elseif wx then
            local sx, sy
            if cached.kind == "player" then
                local hx, hy = grndRingScreenPoint(wx, wy, wz + 0.95, w, h)
                local fx, fy = grndRingScreenPoint(wx, wy, wz - 0.75, w, h)
                if hx and fx then sx, sy = (hx + fx) * 0.5, (hy + fy) * 0.5 end
                if not sx then sx, sy = grndRingScreenPoint(wx, wy, wz + 0.10, w, h) end
            else
                sx, sy = grndRingScreenPoint(wx, wy, wz, w, h)
            end
            if sx then
                cached.x, cached.y = sx, sy
                return cached
            end
            R.cacheTgt = nil
        end
    end
    local meX, meY, meZ, watchPed = grndRingWorldOrigin()
    if not meX then return nil end
    local maxMeters = grndTargetRingMeters(R)
    local maxDist2 = maxMeters * maxMeters
    local r2, best = radius * radius, nil
    local function worldDist2(x, y, z)
        local dx, dy, dz = x - meX, y - meY, z - meZ
        return dx * dx + dy * dy + dz * dz
    end
    local function closer(d2, watched)
        return d2 <= r2 and (not best
            or (best.watched and not watched)
            or (best.watched == watched and d2 < best.dist2))
    end
    local function consider(kind, handle, id, x, y, z, distance, watched)
        local sx, sy = grndRingScreenPoint(x, y, z, w, h)
        if not sx then return end
        local dx, dy = sx - cx, sy - cy
        local d2 = dx * dx + dy * dy
        watched = watched and true or false
        if closer(d2, watched) then
            best = { kind = kind, handle = handle, id = id,
                x = sx, y = sy, dist2 = d2, distance = distance,
                watched = watched }
        end
    end
    if R.mode == "vehicle" then
        if type(getAllVehicles) ~= "function" or type(getCarCoordinates) ~= "function" then
            return nil
        end
        local ownCar = nil
        if type(isCharInAnyCar) == "function" and type(getCarCharIsUsing) == "function" then
            local ok, inCar = pcall(isCharInAnyCar, PLAYER_PED)
            if ok and inCar then
                local got, car = pcall(getCarCharIsUsing, PLAYER_PED)
                if got then ownCar = car end
            end
        end
        local ok, cars = pcall(getAllVehicles)
        if not ok or type(cars) ~= "table" then return nil end
        for _, car in ipairs(cars) do
            if type(car) == "number" and car > 0 and car ~= ownCar then
                local exists = true
                if type(doesVehicleExist) == "function" then
                    local good, res = pcall(doesVehicleExist, car)
                    exists = good and res and true or false
                elseif type(doesCarExist) == "function" then
                    local good, res = pcall(doesCarExist, car)
                    exists = good and res and true or false
                end
                if exists then
                    local got, x, y, z = pcall(getCarCoordinates, car)
                    if got and type(x) == "number" and type(y) == "number"
                        and type(z) == "number" then
                        local d2 = worldDist2(x, y, z)
                        if d2 <= maxDist2 then
                            local vid = grndRingVehicleId(car)
                            if vid then
                                consider("vehicle", car, vid, x, y, z + 0.7,
                                    math.sqrt(d2))
                            end
                        end
                    end
                end
            end
        end
    else
        if type(getAllChars) ~= "function"
            or type(sampGetPlayerIdByCharHandle) ~= "function" then return nil end
        local minDist2 = (tonumber(R.minPlayerDistance) or 2.0) ^ 2
        local ok, peds = pcall(getAllChars)
        if not ok or type(peds) ~= "table" then return nil end
        for _, ped in ipairs(peds) do
            if type(ped) == "number" and ped > 0 and ped ~= PLAYER_PED then
                local exists = true
                if type(doesCharExist) == "function" then
                    local good, res = pcall(doesCharExist, ped)
                    exists = good and res and true or false
                end
                if exists and type(isCharDead) == "function" then
                    local good, dead = pcall(isCharDead, ped)
                    if good and dead then exists = false end
                end
                if exists then
                    local got, a, b = pcall(sampGetPlayerIdByCharHandle, ped)
                    local id = nil
                    if got then
                        if type(a) == "boolean" and a and type(b) == "number" then id = b
                        elseif type(a) == "number" then id = a end
                    end
                    if id and id >= 0 and id < 1004 and id == math.floor(id) then
                        local connected = true
                        if type(sampIsPlayerConnected) == "function" then
                            local good, res = pcall(sampIsPlayerConnected, id)
                            connected = good and res and true or false
                        end
                        if connected then
                            local posOK, x, y, z = pcall(getCharCoordinates, ped)
                            if posOK and type(x) == "number" and type(y) == "number"
                                and type(z) == "number" then
                                local distance2 = worldDist2(x, y, z)
                                local watched = watchPed and ped == watchPed
                                    and grndRingSpectating() or false
                                if (distance2 >= minDist2 or watched)
                                    and distance2 <= maxDist2 then
                                    local meters = math.sqrt(distance2)
                                    local hx, hy = grndRingScreenPoint(x, y, z + 0.95, w, h)
                                    local fx, fy = grndRingScreenPoint(x, y, z - 0.75, w, h)
                                    if hx and fx then
                                        local sx, sy = (hx + fx) * 0.5, (hy + fy) * 0.5
                                        local dx, dy = sx - cx, sy - cy
                                        local d2 = dx * dx + dy * dy
                                        if closer(d2, watched) then
                                            best = { kind = "player", handle = ped, id = id,
                                                x = sx, y = sy, dist2 = d2,
                                                distance = meters, watched = watched }
                                        end
                                    else
                                        consider("player", ped, id, x, y, z + 0.10,
                                            meters, watched)
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    R.cacheAt, R.cacheTgt = os.clock(), best
    return best
end
local function grndTargetRingFont(w, h)
    local R = _G.GRND_TARGET_RING
    if not R or type(renderCreateFont) ~= "function"
        or type(renderFontDrawText) ~= "function" then return nil end
    local px = math.max(11, math.min(16,
        math.floor(math.min(w, h) * 0.015 + 0.5)))
    if R.fontPx ~= px or not R.font then
        local ok, font = pcall(renderCreateFont, "Tahoma", -px, 5, 204)
        if not ok or not font then
            ok, font = pcall(renderCreateFont, "Tahoma", -px, 1, 204)
        end
        if not ok or not font then
            ok, font = pcall(renderCreateFont, "Tahoma", -px, 1)
        end
        if not ok or not font then return nil end
        if R.font and type(renderReleaseFont) == "function" then
            pcall(renderReleaseFont, R.font)
        end
        R.font, R.fontPx = font, px
    end
    return R.font, px
end
local function grndTargetRingAnsi(raw)
    local str = tostring(raw or "")
    if type(grndAnsiText) == "function" then
        local ok, converted = pcall(grndAnsiText, str)
        if ok and type(converted) == "string" then return converted end
    end
    return str
end
local function grndTargetRingTextWidth(font, px, str)
    if type(renderGetFontDrawTextLength) == "function" then
        local ok, tw = pcall(renderGetFontDrawTextLength, font, str)
        if ok and type(tw) == "number" and tw >= 0 then return tw end
    end
    return #str * px * 0.52
end
local function grndTargetRingText(font, str, x, y, textColor)
    renderFontDrawText(font, str, x + 1, y + 1, 0xCC000000)
    renderFontDrawText(font, str, x, y, textColor or 0xFFF6F7F9)
end
function grndRingKeyLabel(slot)
    if not slot or type(slot.key) ~= "number" or slot.key <= 0 then return "" end
    local mods = tonumber(slot.mods) or 0
    local parts = {}
    if mods % 2 >= 1 then parts[#parts + 1] = "SHIFT" end
    if math.floor(mods / 2) % 2 >= 1 then parts[#parts + 1] = "CTRL" end
    if math.floor(mods / 4) % 2 >= 1 then parts[#parts + 1] = "ALT" end
    local keyName = (type(grndKeyName) == "function") and grndKeyName(slot.key)
        or string.format("0x%02X", slot.key)
    parts[#parts + 1] = keyName
    return table.concat(parts, "+")
end
function grndRingFitText(font, px, maxWidth, raw)
    local str = grndTargetRingAnsi(raw)
    if grndTargetRingTextWidth(font, px, str) <= maxWidth then return str end
    local chars = {}
    for ch in raw:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
        chars[#chars + 1] = ch
    end
    for i = #chars - 1, 1, -1 do
        local short = grndTargetRingAnsi(table.concat(chars, "", 1, i) .. "...")
        if grndTargetRingTextWidth(font, px, short) <= maxWidth then
            return short
        end
    end
    return grndTargetRingAnsi("...")
end
local function grndRingVisualRow(font, px, maxWidth, slot)
    local key = grndRingKeyLabel(slot)
    local title = (slot and slot.name and slot.name ~= "")
        and slot.name or "Без названия"
    return grndRingFitText(font, px, maxWidth,
        (key ~= "" and key or "[   ]") .. " - " .. title)
end
function grndTargetRingLabels(w, h, cx, cy, radius)
    local R = _G.GRND_TARGET_RING
    local font, px = grndTargetRingFont(w, h)
    if not font then return false end
    local a = grndTargetRingAnsi((R.mode == "vehicle")
        and "[ E ] - Сменить режим на ИГРОКОВ"
        or "[ E ] - Сменить режим на ТРАНСПОРТ")
    local b = grndTargetRingAnsi(string.format(
        "[ ALT + Колесико ] - изменить радиус: %d м",
        grndTargetRingMeters(R)))
    local target = R.lastTarget
    local showDistance = target and target.kind == "player"
        and type(target.distance) == "number"
    local gap = px + 5
    local age = os.clock() - (R.lastSentAt or -10)
    local showSent = type(R.lastSentLine) == "string" and age >= 0 and age < 1.3
    local rows = 2 + (showDistance and 1 or 0) + (showSent and 1 or 0)
    local bottomY = math.min(cy + radius + 9,
        h - (gap * (rows - 1) + px + 8))
    grndTargetRingText(font, a,
        math.max(4, cx - grndTargetRingTextWidth(font, px, a) * 0.5), bottomY)
    grndTargetRingText(font, b,
        math.max(4, cx - grndTargetRingTextWidth(font, px, b) * 0.5), bottomY + gap)
    if showDistance then
        local distance = grndTargetRingAnsi(string.format(
            "Расстояние до игрока: %.1f м", target.distance))
        grndTargetRingText(font, distance,
            math.max(4, cx - grndTargetRingTextWidth(font, px, distance) * 0.5),
            bottomY + gap * 2)
    end
    if showSent then
        local text = grndTargetRingAnsi("Отправлено: "
            .. (R.lastSentCommand or ""))
            .. (R.lastSentSuffix or (" " .. tostring(R.lastSentId)))
        if grndTargetRingTextWidth(font, px, text) > w - 12 then
            text = grndTargetRingAnsi("Отправлено с ID ") .. tostring(R.lastSentId)
        end
        grndTargetRingText(font, text,
            math.max(4, cx - grndTargetRingTextWidth(font, px, text) * 0.5),
            bottomY + gap * (rows - 1))
    end
    local rowH = px + 5
    if R.mode == "vehicle" then
        local topY = math.max(4, cy - rowH * 1.5)
        local rightEdge = cx + radius + 15
        local maxW = math.max(32, w - rightEdge - 5)
        for i = 1, 3 do
            local row = grndRingVisualRow(font, px, maxW,
                grndRingSlot("vehicle", i))
            local rw = grndTargetRingTextWidth(font, px, row)
            local rx = math.max(4, math.min(w - rw - 4, rightEdge))
            grndTargetRingText(font, row, rx, topY + (i - 1) * rowH)
        end
    else
        local leftEdge, rightEdge = cx - radius - 15, cx + radius + 15
        local leftW = math.max(32, leftEdge - 5)
        local rightW = math.max(32, w - rightEdge - 5)
        local theme
        if type(grndUiTheme) == "function" then
            local okTheme, value = pcall(grndUiTheme)
            if okTheme then theme = value end
        end
        local accent = type(theme) == "table" and theme.accent or nil
        local leftColor = type(accent) == "table"
            and (0xFF000000 + (tonumber(accent[1]) or 164) * 65536
                + (tonumber(accent[2]) or 112) * 256
                + (tonumber(accent[3]) or 224)) or 0xFFA470E0
        local leftTopY = math.max(4, cy - rowH * (#GRND_RING_FIXED_LEFT / 2))
        for i, action in ipairs(GRND_RING_FIXED_LEFT) do
            local left = grndRingFitText(font, px, leftW,
                "ALT+" .. tostring(i) .. " - " .. action.name)
            local lw = grndTargetRingTextWidth(font, px, left)
            grndTargetRingText(font, left, math.max(4, leftEdge - lw),
                leftTopY + (i - 1) * rowH, leftColor)
        end
        local rightTopY = math.max(4, cy - rowH * 4.5)
        for i = 1, 9 do
            local y = rightTopY + (i - 1) * rowH
            local right = grndRingVisualRow(font, px, rightW,
                grndRingSlot("right", i))
            local rw = grndTargetRingTextWidth(font, px, right)
            grndTargetRingText(font, right,
                math.max(4, math.min(w - rw - 4, rightEdge)), y)
        end
    end
    return true
end
function grndTargetRingName(w, h, target)
    if not target or target.kind ~= "player"
        or type(target.id) ~= "number" then return false end
    local font, px = grndTargetRingFont(w, h)
    if not font then return false end
    local nick = nil
    if type(sampGetPlayerNickname) == "function" then
        local ok, name = pcall(sampGetPlayerNickname, target.id)
        if ok and type(name) == "string" and name ~= "" then nick = name end
    end
    local raw = (nick and (nick .. " ") or "")
        .. "[" .. tostring(target.id) .. "]"
    local str = grndTargetRingAnsi(raw)
    local tw = grndTargetRingTextWidth(font, px, str)
    local tx = target.x + 9
    if tx + tw > w - 5 then tx = target.x - tw - 9 end
    tx = math.max(4, math.min(tx, w - tw - 4))
    local ty = math.max(4, math.min(target.y - px - 6, h - px - 4))
    grndTargetRingText(font, str, tx, ty)
    return true
end
function grndTargetRingVehicleInfo(w, h, target)
    if not target or target.kind ~= "vehicle" or type(target.handle) ~= "number"
        or type(target.id) ~= "number" then return false end
    local car = target.handle
    local exists = doesVehicleExist or doesCarExist
    if type(exists) == "function" then
        local ok, alive = pcall(exists, car)
        if not ok or not alive then return false end
    end
    if grndRingVehicleId(car) ~= target.id then return false end
    local font, px = grndTargetRingFont(w, h)
    if not font then return false end
    local function numberFrom(fn)
        if type(fn) ~= "function" then return nil end
        local ok, value = pcall(fn, car)
        if ok and type(value) == "number" and value == value
            and value ~= math.huge and value ~= -math.huge then return value end
    end
    local model, hp = numberFrom(getCarModel), numberFrom(getCarHealth)
    local modelText = model and string.format("%.0f", model) or "?"
    local hpText = hp and string.format("%.0f", hp) or "?"
    local str = grndTargetRingAnsi("ID: " .. tostring(target.id)
        .. " | Model: " .. modelText .. " | HP: " .. hpText)
    local tw = grndTargetRingTextWidth(font, px, str)
    local tx = target.x + 9
    if tx + tw > w - 5 then tx = target.x - tw - 9 end
    tx = math.max(4, math.min(tx, w - tw - 4))
    local ty = math.max(4, math.min(target.y - px - 6, h - px - 4))
    grndTargetRingText(font, str, tx, ty)
    return true
end
function grndTargetRingFrame()
    local R = _G.GRND_TARGET_RING
    if type(R) ~= "table" then return false end
    R.lastTarget = nil
    if not R.on or not grndTargetRingSceneReady()
        or type(renderDrawLine) ~= "function"
        or type(getScreenResolution) ~= "function" then return false end
    grndRingLoad()
    local ok, w, h = pcall(getScreenResolution)
    if not ok or type(w) ~= "number" or type(h) ~= "number"
        or w < 160 or h < 120 then return false end
    local cx, cy = w * 0.5, h * 0.5
    grndTargetRingMeters(R)
    local radius = math.max(80, math.floor(math.min(w, h)
        * R.radiusRatio + 0.5))
    local color = (R.mode == "vehicle") and 0xFFFF5656 or 0xFFF7FAFF
    R.lastTarget = grndTargetRingFind(w, h, cx, cy, radius)
    local segments = 128
    local px, py = cx + radius, cy
    for i = 1, segments do
        local a = i * math.pi * 2 / segments
        local nx, ny = cx + radius * math.cos(a), cy + radius * math.sin(a)
        renderDrawLine(px, py, nx, ny, 1.6, color)
        px, py = nx, ny
    end
    local t = R.lastTarget
    if t then
        renderDrawLine(cx, cy, t.x, t.y, 1.7, color)
        if type(renderDrawBox) == "function" then
            renderDrawBox(t.x - 2, t.y - 2, 4, 4, color)
        end
    end
    if type(renderDrawBox) == "function" then
        renderDrawBox(cx - 2, cy - 2, 4, 4, color)
    end
    if t then pcall(grndTargetRingLabels, w, h, cx, cy, radius) end
    if t and t.kind == "player" then
        pcall(grndTargetRingName, w, h, t)
    elseif t and t.kind == "vehicle" then
        pcall(grndTargetRingVehicleInfo, w, h, t)
    end
    return true
end
function grndRingReservedKey(vk, mods)
    if type(vk) ~= "number" or vk < 7 or vk > 255 then return "клавиша не поддерживается" end
    if tonumber(mods) == 4 and vk >= 0x31 and vk <= 0x35 then
        return "ALT+1–ALT+5 заняты штатными действиями кольцевого меню"
    end
    if vk == 0x08 or vk == 0x2E or vk == 0x1B then return "служебная клавиша редактора" end
    if vk == 0x10 or vk == 0x11 or vk == 0x12
        or (vk >= 0xA0 and vk <= 0xA5) then return "модификатор без основной клавиши" end
    if vk == 0x09 or vk == 0x0D or vk == 0x20 or vk == 0x70
        or vk == 0x71 or vk == 0x52 or vk == 0x45
        or vk == GRND_MENU_HOTKEY or vk == 0x54
        or vk == 0x75 or vk == 0x76 or vk == 0x47 then
        return "занята скриптом/игрой"
    end
    if (vk >= 0x25 and vk <= 0x28) or vk == 0xBB or vk == 0xBD
        or vk == 0x6B or vk == 0x6D then return "камера слежки" end
    if (GRND_CHAT and GRND_CHAT.key == vk)
        or (GRND_INVIS and GRND_INVIS.key == vk)
        or (GRND_AREP and GRND_AREP.key == vk)
        or (GRND_CATCH and GRND_CATCH.key == vk)
        or (GRND_ABRK and GRND_ABRK.key == vk)
        or (_G.GRND_SPEC_WARP_KEY and _G.GRND_SPEC_WARP_KEY == vk) then
        return "занята другой функцией"
    end
    local B = _G.GRND_BINDER
    if B and B.byKey and B.byKey[vk] then return "клавиша занята биндером" end
    return nil
end
function grndRingBind(side, index, vk, mods)
    grndRingLoad()
    local slot = grndRingSlot(side, index)
    if not slot then return false, "Слот не найден" end
    if side == "left" then return false, "левый ряд — штатный и не настраивается" end
    vk, mods = tonumber(vk) or 0, tonumber(mods) or 0
    vk, mods = math.floor(vk), math.floor(mods)
    if vk == 0 then
        slot.key, slot.mods = 0, 0
        grndRingTouch()
        return true
    end
    local why = grndRingReservedKey(vk, mods)
    if why or mods < 0 or mods > 7 then
        return false, why or "Неподдерживаемая комбинация"
    end
    local group = (side == "vehicle") and { "vehicle" } or { "right" }
    for _, oneSide in ipairs(group) do
        for i = 1, oneSide == "vehicle" and 3 or 9 do
            local other = grndRingSlot(oneSide, i)
            if other ~= slot and other.key == vk and other.mods == mods then
                other.key, other.mods = 0, 0
            end
        end
    end
    slot.key, slot.mods = vk, mods
    grndRingTouch()
    return true
end
local function grndRingModifier(vk)
    if vk == 0x10 or vk == 0xA0 or vk == 0xA1 then return "shift" end
    if vk == 0x11 or vk == 0xA2 or vk == 0xA3 then return "ctrl" end
    if vk == 0x12 or vk == 0xA4 or vk == 0xA5 then return "alt" end
    return nil
end
local function grndRingHeld(vk)
    if type(grndBinderKeyHeld) == "function" then
        local ok, down = pcall(grndBinderKeyHeld, vk)
        if ok then return down and true or false end
    end
    if type(isKeyDown) == "function" then
        local ok, down = pcall(isKeyDown, vk)
        if ok then return down and true or false end
    end
    return false
end
grndRingArmHeldOnSwitch = function()
    local R = GRND_TARGET_RING
    if not R.on then return end
    local visited = {}
    for _, side in ipairs({ "right", "vehicle" }) do
        for i = 1, side == "vehicle" and 3 or 9 do
            local vk = grndRingSlot(side, i).key
            if vk > 0 and not visited[vk] then
                visited[vk] = true
                if grndRingHeld(vk) then
                    R.armed[vk] = true
                    R.lastDownAt[vk] = os.clock()
                end
            end
        end
    end
    if grndRingHeld(0x12) or grndRingHeld(0xA4) or grndRingHeld(0xA5) then
        for vk = 0x31, 0x35 do
            if grndRingHeld(vk) then
                R.armed[vk], R.consumed[vk] = true, true
                R.lastDownAt[vk] = os.clock()
            end
        end
    end
    for vk in pairs(R.consumed) do
        if not grndRingHeld(vk) then R.consumed[vk] = nil end
    end
end
local function grndRingMods()
    local R = _G.GRND_TARGET_RING
    local wm = R.wmMods or {}
    local shift = wm.shift or grndRingHeld(0x10)
        or grndRingHeld(0xA0) or grndRingHeld(0xA1)
    local ctrl = wm.ctrl or grndRingHeld(0x11)
        or grndRingHeld(0xA2) or grndRingHeld(0xA3)
    local alt = wm.alt or grndRingHeld(0x12)
        or grndRingHeld(0xA4) or grndRingHeld(0xA5)
    return (shift and 1 or 0) + (ctrl and 2 or 0) + (alt and 4 or 0)
end
local function grndRingActionFor(vk, mods)
    local R = _G.GRND_TARGET_RING
    if R.mode == "vehicle" then
        for i = 1, 3 do
            local slot = grndRingSlot("vehicle", i)
            if slot.key == vk and slot.mods == mods then return slot end
        end
    else
        if tonumber(mods) == 4 and vk >= 0x31 and vk <= 0x35 then
            return GRND_RING_FIXED_LEFT[vk - 0x30]
        end
        for i = 1, 9 do
            local slot = grndRingSlot("right", i)
            if slot.key == vk and slot.mods == mods then return slot end
        end
    end
    return nil
end
local function grndRingActionNote(text)
    local R = _G.GRND_TARGET_RING
    local now = os.clock()
    if now - (R.actionNoteAt or -10) < 1 then return end
    R.actionNoteAt = now
    if notify and type(notify.add) == "function" then
        pcall(notify.add, "Круг: " .. text, "warn", 2)
    end
end
local function grndRingCommandParts(cmd, id, kind)
    local idText = tostring(id)
    if kind == "player" then
        local lower = cmd:lower()
        if lower == "/hp" then
            return cmd, " " .. idText .. " 100"
        end
        local root, arg = cmd:match("^(/[hH][pP])%s+(.+)$")
        if root then
            local token, value = arg:lower():match("^(%S+)%s+(%d+)$")
            local placeholder = token == "id" or token == "<id>" or token == "{id}"
            local simple = arg:lower()
            local n = (simple == "id" or simple == "<id>" or simple == "{id}")
                and 100 or (placeholder and tonumber(value)
                    or (simple:match("^%d+$") and tonumber(simple)))
            if not n or n > 100 then
                return nil, nil, "для /hp укажите значение ХП от 0 до 100"
            end
            return root, " " .. idText .. " " .. tostring(n)
        end
    end
    return cmd, " " .. idText
end
function grndRingDispatch(slot)
    local R = _G.GRND_TARGET_RING
    if not R or not R.on or not grndTargetRingSceneReady() then return false end
    if _G.GRND_RC and _G.GRND_RC.show and _G.GRND_RC.cursor then return false end
    local roadAction = slot and slot.action == "tproad"
    local cmd = grndRingClean(slot and slot.command, 144)
    if not roadAction and (cmd == "" or not cmd:match("^/[%w_]+")) then
        grndRingActionNote("у слота нет корректной команды с /")
        return false
    end
    if type(getScreenResolution) ~= "function" then return false end
    local ok, w, h = pcall(getScreenResolution)
    if not ok or type(w) ~= "number" or type(h) ~= "number"
        or w < 160 or h < 120 then return false end
    grndTargetRingMeters(R)
    local radius = math.max(80, math.floor(math.min(w, h) * R.radiusRatio + 0.5))
    local t = R.lastTarget or grndTargetRingFind(w, h, w * 0.5, h * 0.5, radius)
    if not t or (R.mode == "vehicle" and t.kind ~= "vehicle")
        or (R.mode ~= "vehicle" and t.kind ~= "player") then
        grndRingActionNote("в круге нет выбранной цели")
        return false
    end
    local id = tonumber(t.id)
    if not id or id < 0 or id ~= math.floor(id) then return false end
    if t.kind == "vehicle" then
        local existsFn = type(doesVehicleExist) == "function" and doesVehicleExist
            or (type(doesCarExist) == "function" and doesCarExist)
        if existsFn then
            local got, exists = pcall(existsFn, t.handle)
            if not got or not exists then return false end
        end
        if grndRingVehicleId(t.handle) ~= id then
            grndRingActionNote("SA-MP ID машины больше не доступен")
            return false
        end
    else
        if type(doesCharExist) == "function" then
            local got, exists = pcall(doesCharExist, t.handle)
            if not got or not exists then return false end
        end
        if type(sampIsPlayerConnected) == "function" then
            local got, connected = pcall(sampIsPlayerConnected, id)
            if not got or not connected then return false end
        end
    end
    if roadAction then
        if t.kind ~= "player" or type(getCharCoordinates) ~= "function"
            or type(GRND_SPEC_CAR_NODE_NEAR) ~= "function" then
            notify.add("Скрипт не нашел ближайшую дорогу", "warn", 3)
            return false
        end
        local targetPed = grndGetTargetPedHandle(id, t.handle)
        if not targetPed then
            notify.add("Скрипт не нашел ближайшую дорогу", "warn", 3)
            return false
        end
        local targetInterior = grndGetTargetInterior(id, targetPed)
        if targetInterior == nil then
            notify.add("Скрипт не нашел ближайшую дорогу", "warn", 3)
            return false
        elseif targetInterior ~= 0 then
            notify.add("Скрипт не нашел ближайшую дорогу", "warn", 3)
            return false
        end
        local got, x, y, z = pcall(getCharCoordinates, targetPed)
        if not got or type(x) ~= "number" or type(y) ~= "number"
            or type(z) ~= "number" then
            notify.add("Скрипт не нашел ближайшую дорогу", "warn", 3)
            return false
        end
        local nx, ny, nz = GRND_SPEC_CAR_NODE_NEAR(x, y, z)
        if type(nx) ~= "number" or type(ny) ~= "number" or type(nz) ~= "number" then
            notify.add("Скрипт не нашел ближайшую дорогу", "warn", 3)
            return false
        end
        if type(GRND_SPEC_PLAYER_CMD) ~= "string" or type(sampSendChat) ~= "function" then
            return false
        end
        local okRoad, outgoing = pcall(string.format, GRND_SPEC_PLAYER_CMD,
            id, nx, ny, nz + 1.0)
        if not okRoad or type(outgoing) ~= "string" or #outgoing > 127 then
            grndRingActionNote("не удалось подготовить ТП на дорогу")
            return false
        end
        local sentOk, sent = pcall(sampSendChat, outgoing)
        if not sentOk or sent == false then
            grndRingActionNote("не удалось отправить ТП на дорогу")
            return false
        end
        R.lastSentLine, R.lastSentCommand = outgoing, outgoing
        R.lastSentSuffix, R.lastSentId, R.lastSentAt = "", id, os.clock()
        return true
    end
    local source, suffix, syntaxErr = grndRingCommandParts(cmd, id, t.kind)
    if not source then
        grndRingActionNote(syntaxErr or "некорректная команда")
        return false
    end
    local prefix = source
    if type(grndAnsiText) == "function" then
        local good, ansi = pcall(grndAnsiText, source)
        if not good or type(ansi) ~= "string" then
            grndRingActionNote("не удалось преобразовать команду")
            return false
        end
        prefix = ansi
    end
    local outgoing = prefix .. suffix
    if #outgoing > 127 then
        grndRingActionNote("команда слишком длинная: сократите её, чтобы уместить ID")
        return false
    end
    if type(sampSendChat) ~= "function" then return false end
    local ok, sent = pcall(sampSendChat, outgoing)
    if not ok or sent == false then
        grndRingActionNote("не удалось отправить команду")
        return false
    end
    local specCommand = source:lower()
    if specCommand == "/sp" or specCommand == "/spec"
        or specCommand == "/spectate" or specCommand == "/recon" then
        if type(_G.grndSpecTrackCommand) == "function" then
            pcall(_G.grndSpecTrackCommand, outgoing)
        end
    end
    R.lastSentLine = source .. suffix
    R.lastSentCommand = source
    R.lastSentSuffix = suffix
    R.lastSentId = id
    R.lastSentAt = os.clock()
    return true
end
function grndRingOnKeyMsg(isDown, vk, lp)
    local R = _G.GRND_TARGET_RING
    if not R or type(vk) ~= "number" or vk < 1 or vk > 255 then return false end
    local modifier = grndRingModifier(vk)
    if modifier then
        R.wmMods = R.wmMods or {}
        R.wmMods[modifier] = isDown and true or false
    end
    local cap = R.capture
    if cap and GRND_REF.menu and GRND_REF.menu.open then
        if not isDown then return true end
        if modifier then return true end
        if math.floor((tonumber(lp) or 0) / 0x40000000) % 2 == 1 then return true end
        if vk == 0x1B then
            R.capture = nil
            R.uiStatus = "Назначение отменено"
        elseif vk == 0x08 or vk == 0x2E then
            grndRingBind(cap.side, cap.index, 0, 0)
            R.capture = nil
            R.uiStatus = "Горячая клавиша очищена"
        else
            local ok, why = grndRingBind(cap.side, cap.index, vk, grndRingMods())
            if ok then
                R.capture = nil
                R.armed[vk], R.consumed[vk] = true, true
                R.lastDownAt = R.lastDownAt or {}
                R.lastDownAt[vk] = os.clock()
                R.uiStatus = "Назначено: " .. grndRingKeyLabel(
                    grndRingSlot(cap.side, cap.index))
            else
                R.uiStatus = "Нельзя назначить: " .. tostring(why)
            end
        end
        return true
    end
    if cap then R.capture = nil end
    if not isDown then
        local eaten = R.consumed and R.consumed[vk]
        if R.armed then R.armed[vk] = nil end
        if R.consumed then R.consumed[vk] = nil end
        if R.lastDownAt then R.lastDownAt[vk] = nil end
        return eaten and true or false
    end
    if modifier or not R.on or grndRingReservedKey(vk) then return false end
    grndRingLoad()
    if not grndTargetRingSceneReady()
        or (_G.GRND_RC and _G.GRND_RC.show and _G.GRND_RC.cursor) then
        for _, side in ipairs(R.mode == "vehicle"
            and { "vehicle" } or { "right" }) do
            for i = 1, side == "vehicle" and 3 or 9 do
                if grndRingSlot(side, i).key == vk then
                    R.armed = R.armed or {}
                    R.armed[vk] = true
                    break
                end
            end
        end
        return false
    end
    local slot = grndRingActionFor(vk, grndRingMods())
    if not slot then return false end
    R.armed, R.consumed = R.armed or {}, R.consumed or {}
    if R.armed[vk] then return R.consumed[vk] and true or false end
    R.armed[vk], R.consumed[vk] = true, true
    R.lastDownAt = R.lastDownAt or {}
    R.lastDownAt[vk] = os.clock()
    if math.floor((tonumber(lp) or 0) / 0x40000000) % 2 == 0 then
        grndRingDispatch(slot)
    end
    return true
end
function grndRingTick()
    local R = _G.GRND_TARGET_RING
    if not R then return end
    grndRingLoad()
    if not R.termHook and type(grndOnTerm) == "function" then
        R.termHook = true
        grndOnTerm(function()
            if GRND_TARGET_RING and GRND_TARGET_RING.dirty then
                pcall(grndRingSave)
            end
        end)
    end
    if R.dirty and os.clock() >= (R.saveAt or 0) then
        pcall(grndRingSave)
    end
    if R.capture and not (GRND_REF.menu and GRND_REF.menu.open) then
        R.capture = nil
    end
    R.armed, R.consumed = R.armed or {}, R.consumed or {}
    R.lastDownAt = R.lastDownAt or {}
    if not R.on or not grndTargetRingSceneReady() then
        for vk in pairs(R.armed) do
            if not grndRingHeld(vk)
                and os.clock() - (R.lastDownAt[vk] or -10) > 0.25 then
                R.armed[vk], R.consumed[vk], R.lastDownAt[vk] = nil, nil, nil
            end
        end
        return
    end
    local keys = {}
    for _, side in ipairs(R.mode == "vehicle"
        and { "vehicle" } or { "right" }) do
        for i = 1, side == "vehicle" and 3 or 9 do
            local slot = grndRingSlot(side, i)
            if slot.key > 0 then keys[slot.key] = true end
        end
    end
    if R.mode ~= "vehicle" then
        for vk = 0x31, 0x35 do keys[vk] = true end
    end
    for vk in pairs(keys) do
        local down = grndRingHeld(vk)
        if not down then
            if os.clock() - (R.lastDownAt[vk] or -10) > 0.25 then
                R.armed[vk], R.consumed[vk], R.lastDownAt[vk] = nil, nil, nil
            end
        elseif not R.armed[vk] and not grndRingReservedKey(vk)
            and not (_G.GRND_RC and _G.GRND_RC.show and _G.GRND_RC.cursor) then
            R.armed[vk] = true
            R.lastDownAt[vk] = os.clock()
            local slot = grndRingActionFor(vk, grndRingMods())
            if slot then
                R.consumed[vk] = true
                grndRingDispatch(slot)
            end
        end
    end
    for vk in pairs(R.armed) do
        if not keys[vk] and not grndRingHeld(vk)
            and os.clock() - (R.lastDownAt[vk] or -10) > 0.25 then
            R.armed[vk], R.consumed[vk], R.lastDownAt[vk] = nil, nil, nil
        end
    end
end
local function grndKeyIsRepeat(lparam)
    local lp = tonumber(lparam) or 0
    if bit and bit.band then return bit.band(lp, 0x40000000) ~= 0 end
    return math.floor(lp / 1073741824) % 2 == 1
end
local function grndIsChatInput()
    if sampIsChatInputActive then
        local ok, res = pcall(sampIsChatInputActive)
        if ok and res then return true end
    end
    return GRND_KEYS.typing and true or false
end
local function grndF1Debounced()
    local nowT = os.clock()
    if nowT - (GRND_F1.lastToggle or -9) < 0.2 then return false end
    GRND_F1.lastToggle = nowT
    return true
end
local F1H = { state = "new", why = "проверка ещё не запускалась", site = nil, orig = nil,
    lastTry = -1000, mem = nil, ffi = nil }
do
    local okF, ffiMod = pcall(require, "ffi")
    if okF then F1H.ffi = ffiMod end
end
function F1H.bytes(addr, n)
    return F1H.ffi.string(F1H.ffi.cast("const char*", addr), n)
end
local function f1hU32(addr)
    return tonumber(F1H.ffi.cast("const uint32_t*", addr)[0])
end
local function f1hU16(addr)
    return tonumber(F1H.ffi.cast("const uint16_t*", addr)[0])
end
local function f1hLe32(v)
    v = v % 4294967296
    return string.char(v % 256, math.floor(v / 256) % 256,
        math.floor(v / 65536) % 256, math.floor(v / 16777216) % 256)
end
local function f1hS32(s, i)
    local a, b, c, d = s:byte(i, i + 3)
    local v = a + b * 256 + c * 65536 + d * 16777216
    if v >= 2147483648 then v = v - 4294967296 end
    return v
end
function F1H.sections(base)
    local pe = base + f1hU32(base + 0x3C)
    if F1H.bytes(pe, 4) ~= "PE\0\0" then return nil, "нет PE-заголовка" end
    local nsec, optsz = f1hU16(pe + 6), f1hU16(pe + 20)
    local secs = {}
    for i = 0, nsec - 1 do
        local sh = pe + 24 + optsz + i * 40
        local name = F1H.bytes(sh, 8):match("^[^%z]*")
        secs[name] = { va = f1hU32(sh + 12), vsize = f1hU32(sh + 8) }
    end
    return secs
end
function F1H.scan(base)
    local secs, err = F1H.sections(base)
    if not secs then return "notfound", err end
    local text = secs[".text"]
    if not text or text.vsize <= 0 then return "notfound", "нет секции .text" end
    local T = F1H.bytes(base + text.va, text.vsize)
    local textLo, textHi = text.va, text.va + text.vsize
    local TITLE = "SA-MP Keys:\0"
    local titles = {}
    for _, name in ipairs({ ".rdata", ".data" }) do
        local s = secs[name]
        if s and s.vsize > 0 then
            local d = F1H.bytes(base + s.va, s.vsize)
            local i = 1
            while true do
                local p = d:find(TITLE, i, true)
                if not p then break end
                titles[#titles + 1] = base + s.va + p - 1
                i = p + 1
            end
        end
    end
    if #titles ~= 1 then
        return "notfound", "строка «SA-MP Keys:» найдена " .. #titles .. " раз"
    end
    local titleVA = titles[1]
    local refs = {}
    local function addRefs(op)
        local needle = op .. f1hLe32(titleVA)
        local i = 1
        while true do
            local p = T:find(needle, i, true)
            if not p then break end
            refs[#refs + 1] = textLo + p - 1
            i = p + 1
        end
    end
    addRefs(string.char(0x68))
    for op = 0xB8, 0xBF do addRefs(string.char(op)) end
    if #refs == 0 then
        return "notfound", "в коде нет ссылки на строку «SA-MP Keys:»"
    end
    local function refInside(lo, hi)
        for _, r in ipairs(refs) do
            if r >= lo and r < hi then return true end
        end
        return false
    end
    local calls = {}
    local i = 1
    while true do
        local p = T:find("\232", i, true)
        if not p then break end
        i = p + 1
        if p + 4 <= #T then
            local callRVA = textLo + p - 1
            local target = callRVA + 5 + f1hS32(T, p + 1)
            if target >= textLo and target < textHi and refInside(target, target + 0x100) then
                local lo = p - 64
                if lo < 1 then lo = 1 end
                if T:sub(lo, p - 1):find("\106\112", 1, true) then
                    calls[#calls + 1] = { site = callRVA, orig = T:sub(p, p + 4) }
                end
            end
        end
    end
    local patchedSet, patchedCount = {}, 0
    local j = 1
    while true do
        local p = T:find("\106\112", j, true)
        if not p then break end
        j = p + 1
        local hi = p + 64
        if hi > #T then hi = #T end
        local q = T:sub(p + 2, hi):find("\144\144\144\144\144", 1, true)
        if q then
            local rva = textLo + (p + 2 + q - 1) - 1
            if not patchedSet[rva] then
                patchedSet[rva] = true
                patchedCount = patchedCount + 1
            end
        end
    end
    if #calls == 1 then
        return "ready", { site = calls[1].site, orig = calls[1].orig }
    end
    if #calls == 0 and patchedCount == 1 then
        return "already", next(patchedSet)
    end
    if #calls == 0 and patchedCount == 0 then
        return "notfound", "вызов справки после проверки F1 не найден"
    end
    return "ambiguous", "мест вызова справки: " .. #calls .. ", следов патча: " .. patchedCount
end
function F1H.getmem()
    if F1H.mem == nil then
        local okM, m = pcall(require, "memory")
        if okM and type(m) == "table" and type(m.getint8) == "function"
           and type(m.setint8) == "function" then
            F1H.mem = m
        else
            F1H.mem = false
        end
    end
    return F1H.mem or nil
end
function F1H.attempt()
    local okB, base = pcall(getModuleHandle, "samp.dll")
    if not okB or type(base) ~= "number" or base == 0 then
        F1H.state, F1H.why = "wait", "samp.dll ещё не загружен"
        return
    end
    if not F1H.ffi then
        F1H.state, F1H.why = "notfound", "нет модуля ffi"
        return
    end
    local okS, kind, data = pcall(F1H.scan, base)
    if not okS then
        F1H.state, F1H.why = "notfound", "ошибка поиска: " .. tostring(kind)
        return
    end
    if kind == "already" then
        F1H.state, F1H.why = "already", "патч уже стоит (от прошлой загрузки скрипта)"
        return
    end
    if kind ~= "ready" then
        F1H.state, F1H.why = kind, tostring(data)
        return
    end
    local mem = F1H.getmem()
    if not mem then
        F1H.state, F1H.why = "notfound", "нет модуля memory"
        return
    end
    local addr = base + data.site
    if F1H.bytes(addr, 5) ~= data.orig then
        F1H.state, F1H.why = "notfound", "байты изменились во время поиска"
        return
    end
    local okW = pcall(function()
        for k = 0, 4 do mem.setint8(addr + k, 0x90, true) end
    end)
    if not okW or F1H.bytes(addr, 5) ~= "\144\144\144\144\144" then
        pcall(function()
            for k = 0, 4 do mem.setint8(addr + k, data.orig:byte(k + 1), true) end
        end)
        F1H.state, F1H.why = "notfound", "запись не удалась, исходный код возвращён"
        return
    end
    F1H.site, F1H.orig = addr, data.orig
    F1H.state = "patched"
    F1H.why = ("вызов справки в samp.dll +0x%X заменён на NOP"):format(math.floor(data.site))
end
function F1H.tick()
    local s = F1H.state
    if s == "patched" or s == "already" or s == "notfound" or s == "ambiguous" or s == "restored" then
        return
    end
    local now = os.clock()
    if now - F1H.lastTry < 1.0 then return end
    F1H.lastTry = now
    F1H.attempt()
    if F1H.state ~= s then F1H.announce(false) end
end
function F1H.announce(force)
end
function F1H.rerun()
    if F1H.state == "patched" or F1H.state == "already" then
        return
    end
    F1H.lastTry = -1000
    F1H.attempt()
    F1H.announce(true)
end
function F1H.restore()
    if F1H.state ~= "patched" or not F1H.site or not F1H.orig then return end
    local mem = F1H.getmem()
    if not mem then return end
    for k = 0, 4 do pcall(mem.setint8, F1H.site + k, F1H.orig:byte(k + 1), true) end
    F1H.state, F1H.why = "restored", "патч снят при выгрузке скрипта"
end
function grndF1Status()
    local s = F1H.state
    if s == "patched" then return "окно справки ОТКЛЮЧЕНО (" .. F1H.why .. ")" end
    if s == "already" then return "окно справки отключено (патч уже стоит)" end
    if s == "wait" then return "ждём samp.dll" end
    if s == "new" then return "проверка ещё не запускалась" end
    if s == "restored" then return "патч снят (скрипт выгружен)" end
    return "окно справки НЕ отключено: " .. F1H.why
end
function grndF1BlockReason()
    if not (GRND_REF and GRND_REF.menu ~= nil) or type(grndTogglePlainCursor) ~= "function" then
        return "скрипт ещё запускается, подождите секунду"
    end
    if GRND_KEYS and GRND_KEYS.blocked then return "открыто окно авторизации скрипта" end
    if GRND_RC and GRND_RC.show then return "открыт рекон: курсором управляет карточка" end
    local okT, typing = pcall(grndIsTyping)
    if okT and typing then return "идёт ввод в чат или в окне" end
    local okS, spawned = pcall(grndIsSpawnedSafe)
    if not (okS and spawned) then return "курсор работает только после входа в игру" end
    return nil
end
function grndF1Hint()
    return false
end
function grndF1Press()
    if type(grndTogglePlainCursor) ~= "function" then return false end
    if grndF1BlockReason() ~= nil then return false end
    if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    local ok, e = pcall(grndTogglePlainCursor)
    if not ok then
        pcall(logRenderErr, "f1", e)
        return false
    end
    return true
end
local grndUiControlsOn = false
function grndUiControls(on)
    on = on and true or false
    if on == grndUiControlsOn then return end
    if not on and GRND_KEYS.aiming then return end
    GRND_UI_MOUSE.uiGuard=on
    grndUiMouseUpdate()
    GRND_UI_MOUSE.blockUntil=math.max(GRND_UI_MOUSE.blockUntil or 0,os.clock()+0.20)
    grndUiControlsOn = on
end
function grndEscAction()
    if GRND_LOG and (GRND_LOG.viewerOpen or GRND_LOG.dateOpen) then GRND_LOG.close();return true end
    local done = false
    if _G.GRND_CLOCK and _G.GRND_CLOCK.moving then
        _G.GRND_CLOCK.cancelMove = true
        return true
    end
    if _G.grndQrOnEsc and _G.grndQrOnEsc() then return true end
    if _G.grndBinderOnEsc and _G.grndBinderOnEsc() then return true end
    if GRND_KL and GRND_KL.moving then
        GRND_KL.cancel = true
        return true
    end
    if GRND_AO and GRND_AO.moving then
        GRND_AO.cancel = true
        return true
    end
    if _G.GRND_SFR and _G.GRND_SFR.moving then
        _G.GRND_SFR.cancel = true
        return true
    end
    if _G.GRND_FCHAT and _G.GRND_FCHAT.moving then
        _G.GRND_FCHAT.cancel = true
        return true
    end
    if _G.GRND_WEEKSTATS and _G.GRND_WEEKSTATS.moving then
        _G.GRND_WEEKSTATS.cancel = true
        return true
    end
    if _G.GRND_RC and type(_G.GRND_RC.statsPop) == "table" then
        _G.GRND_RC.statsPop = nil
        return true
    end
    if _G.GRND_PUN and _G.GRND_PUN.editId then
        _G.GRND_PUN.editId = nil
        _G.GRND_PUN.addCol = nil
        done = true
    elseif _G.GRND_RC and _G.GRND_RC.actionsWinOpen then
        _G.GRND_RC.actionsWinOpen = false
        _G.GRND_RC.actSubPopup = nil
        done = true
    elseif _G.GRND_RC and type(_G.GRND_RC.statsView) == "table"
       and not (_G.GRND_SPEC and _G.GRND_SPEC.active) then
        _G.GRND_RC.statsView = nil
        _G.GRND_RC.show = false
        done = true
    elseif type(GRND_REF.clwSetAiming) == "function" and GRND_REF.clw
       and GRND_REF.clw.aiming then
        GRND_REF.clwSetAiming(false); done = true
    elseif GRND_REF.menu and GRND_REF.menu.open and MENU_CLOSE_ON_ESC then
        GRND_REF.menu.open = false; done = true
    elseif GRND_TAB.open then
        GRND_TAB.open = false; GRND_TAB.held = false; done = true
    end
    return done
end
local function grndShiftSideVK(wp, lp)
    if wp ~= 0x10 or type(lp) ~= "number" then return wp end
    local sc = math.floor(lp / 65536) % 256
    if sc == 0x2A then return 0xA0 end
    if sc == 0x36 then return 0xA1 end
    return wp
end
function onWindowMessage(msg, wparam, lparam)
    local WM_KEYDOWN, WM_KEYUP       = 0x0100, 0x0101
    local WM_SYSKEYDOWN, WM_SYSKEYUP = 0x0104, 0x0105
    local WM_LBUTTONDOWN, WM_RBUTTONDBLCLK = 0x0201, 0x0206
    do
        local T = GRND_TRACE
        if T and T.on and (msg == WM_KEYDOWN or msg == WM_SYSKEYDOWN) then
            T.gseen = (T.gseen or 0) + 1
            T.seen = (T.seen or 0) + 1
            T.keys = T.keys or {}
            local kk = string.format("0x%02X", tonumber(wparam) or 0)
            T.keys[kk] = (T.keys[kk] or 0) + 1
        end
    end
    local msgN = tonumber(msg) or 0
    if GRND_AFK and GRND_AFK.inputMsg and GRND_AFK.inputMsg[msgN] then GRND_AFK.lastInputAt = grndAfkNow() end
    local wp = tonumber(wparam) or 0
    if msgN==0x001C then GRND_CAM.windowFocused=wp~=0
    elseif msgN==0x0006 then GRND_CAM.windowFocused=(wp%65536)~=0 end
    if msgN>=0x0200 and msgN<=0x020E then GRND_MOUSE.hasPosition=true end
    if wp > 255 then wp = wp % 256 end
    local lp = tonumber(lparam) or 0
    local isDown = (msgN == WM_KEYDOWN or msgN == WM_SYSKEYDOWN)
    local isUp   = (msgN == WM_KEYUP   or msgN == WM_SYSKEYUP)
    local isMouse = (msgN >= WM_LBUTTONDOWN and msgN <= WM_RBUTTONDBLCLK)
    local isMouseInput=(msgN==0x0200 or (msgN>=0x0201 and msgN<=0x020E))
    local isKeyInput=isDown or isUp or msgN==0x0102 or msgN==0x0106 or msgN==0x0109
    if (isMouseInput or isKeyInput) and GRND_CAM and GRND_CAM.fovOn == true
       and type(grndFovRenderTick) == "function" then
        pcall(grndFovRenderTick)
    end
    local eventNow=os.clock()
    local synthEscUntil=GRND_UI_MOUSE.syntheticChatEscapeUntil or 0
    if wp == 0x70 and (isDown or isUp) then
        if isDown and not grndKeyIsRepeat(lp) then pcall(grndF1Hint) end
        if type(consumeWindowMessage) == "function" then pcall(consumeWindowMessage, true, false) end
    end
    if (isDown or isUp) and wp==0x1B and eventNow<=synthEscUntil then
        if isUp then GRND_UI_MOUSE.syntheticChatEscapeUntil=nil end
        return
    end
    -- Перемещаемые SOFT и Дальний чат забирают клик фиксации до прочих UI.
    local sfrMove = _G.GRND_SFR
    local farMove = _G.GRND_FCHAT
    local activeMove = sfrMove and sfrMove.moving and sfrMove
        or (farMove and farMove.moving and farMove)
    if activeMove then
        if isMouse then
            if msgN == WM_LBUTTONDOWN or msgN == 0x0203 then
                activeMove.click = true
                GRND_MOUSE.clicked, GRND_MOUSE.clickedBtn = true, 1
            end
            if msgN == WM_LBUTTONDOWN then
                GRND_MOUSE.down = true
            elseif msgN == 0x0202 then
                GRND_MOUSE.down = false
            end
            local okPos, mx, my = pcall(grndMouseXY, lp)
            if okPos then GRND_MOUSE.x, GRND_MOUSE.y = mx, my end
            GRND_MOUSE.at = eventNow
            if msgN == WM_LBUTTONDOWN or msgN == 0x0203 then
                GRND_MOUSE.frame = GRND_UIFRAME + 1
            end
            grndConsumeMsg(true)
            return
        elseif isDown and wp == 0x1B then
            activeMove.cancel = true
            grndConsumeMsg(true)
            return
        end
    end
    do
        local okInput,handled=pcall(GRND_INPUT.onMessage,msgN,tonumber(wparam) or 0,lp)
        if okInput and handled then return end
        if not okInput then
            pcall(logRenderErr,'native_input',handled)
            if GRND_INPUT.enabled
                and ((isDown and wp==0x0D) or (msgN==0x0102 and wp==0x0D))
                and grndNativeChatInputActive() and not grndServerWinBlocks() then
                grndConsumeMsg(false);return
            end
        end
    end
    local nativeChatActive=false
    if isKeyInput or msgN==0x020A or msgN==0x020E then
        nativeChatActive=grndNativeChatInputActive()
    end
    local nativeChatInput=isKeyInput and nativeChatActive
    local serverDialogActive=grndServerDialogOpen()
    local nativeChatWheel=(msgN==0x020A or msgN==0x020E) and nativeChatActive
    local nativeChatOpeningKey=(isDown or isUp) and not nativeChatActive
        and grndSpectatorChatOpenKey(wp)
    local spectatorExitKey=(isDown or isUp) and not nativeChatActive
        and grndSpectatorExitKey(wp)
    local chatClickUpUntil=GRND_UI_MOUSE.nativeChatClickUpUntil or 0
    local chatDoubleClickUntil=GRND_UI_MOUSE.nativeChatDoubleClickUntil or 0
    if eventNow>chatClickUpUntil then
        GRND_UI_MOUSE.nativeChatClickUpPending=nil
    end
    if eventNow>chatDoubleClickUntil then
        GRND_UI_MOUSE.nativeChatDoubleClickUntil=nil
    end
    if msgN==0x0201 or msgN==0x0203 then
        if grndNativeChatInputActive() then
            GRND_UI_MOUSE.nativeChatClickUpPending=true
            GRND_UI_MOUSE.nativeChatClickUpUntil=eventNow+0.75
            GRND_UI_MOUSE.nativeChatDoubleClickUntil=eventNow+0.40
            GRND_MOUSE.x,GRND_MOUSE.y=grndMouseXY(lparam)
            GRND_MOUSE.down,GRND_MOUSE.clicked=false,false
            grndNativeChatClose()
            grndConsumeMsg(false)
            return
        elseif msgN==0x0203 and eventNow<=chatDoubleClickUntil then
            GRND_UI_MOUSE.nativeChatClickUpPending=true
            GRND_UI_MOUSE.nativeChatClickUpUntil=eventNow+0.75
            GRND_MOUSE.x,GRND_MOUSE.y=grndMouseXY(lparam)
            GRND_MOUSE.down,GRND_MOUSE.clicked=false,false
            grndConsumeMsg(false)
            return
        end
    elseif msgN==0x0202 and GRND_UI_MOUSE.nativeChatClickUpPending then
        GRND_UI_MOUSE.nativeChatClickUpPending=nil
        GRND_UI_MOUSE.nativeChatClickUpUntil=nil
        GRND_MOUSE.x,GRND_MOUSE.y=grndMouseXY(lparam)
        GRND_MOUSE.down,GRND_MOUSE.clicked=false,false
        grndConsumeMsg(false)
        return
    end
    if isMouseInput or isKeyInput then
        local uiGate=GRND_UI_MOUSE.uiGuard or grndUiMouseUpdate()
        local pressMsg=grndMsgIsPress(msgN)
        if uiGate and isMouseInput and not nativeChatWheel
            and not serverDialogActive and pressMsg then
            grndConsumeMsg(false)
            GRND_UI_MOUSE.blockedGameMessages=(GRND_UI_MOUSE.blockedGameMessages or 0)+1
        end
        if uiGate and isKeyInput and not nativeChatInput and not serverDialogActive
            and not nativeChatOpeningKey and not spectatorExitKey and pressMsg then
            grndConsumeMsg(false)
            GRND_UI_MOUSE.blockedGameKeys=(GRND_UI_MOUSE.blockedGameKeys or 0)+1
        end
    end
    if (isDown or isUp) and wp == 0x10 and GRND_ABRK then
        local scS = math.floor(lp / 65536) % 256
        if isDown then
            if scS == 0x2A then GRND_ABRK.wmShiftDown = 0xA0
            elseif scS == 0x36 then GRND_ABRK.wmShiftDown = 0xA1 end
        else
            local sideS = (scS == 0x2A and 0xA0) or (scS == 0x36 and 0xA1) or nil
            if not sideS or GRND_ABRK.wmShiftDown == sideS then
                GRND_ABRK.wmShiftDown = nil
            end
        end
    end
    if msgN == 0x020A and grndNativeChatInputActive() then return end
    if msgN == 0x020A then
        if _G.grndBinderOnWheel and _G.grndBinderOnWheel(wparam, lparam) then
            grndConsumeMsg(true)
            return
        end
        if grndTargetRingOnWheel(wparam) then
            grndConsumeMsg(true)
            return
        end
        if GRND_RC and GRND_RC.show and GRND_RC.cursor and GRND_RC.edge
            and GRND_RC.edge.leftRect and grndMouseInside(GRND_RC.edge.leftRect) then
            -- прокрутка панели с кнопками у левого края
            local wpRaw = tonumber(wparam) or 0
            local dRaw = math.floor(wpRaw / 65536) % 65536
            if dRaw >= 32768 then dRaw = dRaw - 65536 end
            local notch = (dRaw > 0 and 1) or (dRaw < 0 and -1) or 0
            if notch ~= 0 then
                GRND_RC.edge.lScroll = math.max(0,
                    (tonumber(GRND_RC.edge.lScroll) or 0) - notch * 24)
            end
            grndConsumeMsg(true)
            return
        end
        if GRND_RC and GRND_RC.show and GRND_RC.cursor and GRND_RC.edge
            and GRND_RC.edge.statsRect and grndMouseInside(GRND_RC.edge.statsRect) then
            -- прокрутка панели статистики у правого края
            local wpRaw = tonumber(wparam) or 0
            local dRaw = math.floor(wpRaw / 65536) % 65536
            if dRaw >= 32768 then dRaw = dRaw - 65536 end
            local notch = (dRaw > 0 and 1) or (dRaw < 0 and -1) or 0
            if notch ~= 0 then
                GRND_RC.edge.rScroll = math.max(0,
                    (tonumber(GRND_RC.edge.rScroll) or 0) - notch * 24)
            end
            grndConsumeMsg(true)
            return
        end
        if GRND_RC and GRND_RC.show and grndSpecNative
            and not grndCamWindowsOpen() and not grndServerDialogOpen() then
            local wpRaw = tonumber(wparam) or 0
            local dRaw = math.floor(wpRaw / 65536) % 65536
            if dRaw >= 32768 then dRaw = dRaw - 65536 end
            local notch = (dRaw > 0 and 1) or (dRaw < 0 and -1) or 0
            if notch ~= 0 then
                local S = grndSpecNative
                S.camDist = math.max(2.0, math.min(100.0,
                    (S.camDist or 10.0) - notch * 2.0))
                S.camLastInput = os.clock()
                S.wheelN = (S.wheelN or 0) + 1
            end
            grndConsumeMsg(true)
            return
        end
        if GRND_CAM.enabled and GRND_CAM.wheelAdjust
           and not grndCamWindowsOpen() and not grndServerDialogOpen() then
            local altHeld = false
            if type(isKeyDown) == "function" then
                local okA, a = pcall(isKeyDown, 0x12)
                if okA and a then altHeld = true end
            end
            if altHeld then
                local wpRaw = tonumber(wparam) or 0
                local dRaw = math.floor(wpRaw / 65536) % 65536
                if dRaw >= 32768 then dRaw = dRaw - 65536 end
                local notch = (dRaw > 0 and 1) or (dRaw < 0 and -1) or 0
                if notch ~= 0 then
                    local step = 1.5
                    GRND_CAM.dist = math.max(2.0, math.min(50.0, (GRND_CAM.dist or 12.0) + notch * step))
                    GRND_CAM.cfgDirty = true
                    pcall(grndCamCfgSave)
                    grndConsumeMsg(true)
                    return
                end
            end
        end
        return
    end
    if msgN == 0x0201 then
        GRND_MOUSE.down, GRND_MOUSE.clicked = true, true
        GRND_MOUSE.clickedBtn = 1
        GRND_MOUSE.x, GRND_MOUSE.y = grndMouseXY(lparam)
    elseif msgN == 0x0202 then
        GRND_MOUSE.down = false
        GRND_MOUSE.x, GRND_MOUSE.y = grndMouseXY(lparam)
    elseif msgN == 0x0203 then
        GRND_MOUSE.clicked = true
        GRND_MOUSE.clickedBtn = 1
        GRND_MOUSE.x, GRND_MOUSE.y = grndMouseXY(lparam)
    elseif msgN == 0x0204 then
        GRND_MOUSE.rdown, GRND_MOUSE.rclicked = true, true
        GRND_MOUSE.rclickedBtn = 2
        GRND_MOUSE.x, GRND_MOUSE.y = grndMouseXY(lparam)
    elseif msgN == 0x0205 then
        GRND_MOUSE.rdown = false
        GRND_MOUSE.x, GRND_MOUSE.y = grndMouseXY(lparam)
    elseif msgN == 0x0206 then
        GRND_MOUSE.rclicked = true
        GRND_MOUSE.rclickedBtn = 2
        GRND_MOUSE.x, GRND_MOUSE.y = grndMouseXY(lparam)
    elseif msgN == 0x0207 then
        GRND_MOUSE.mdown, GRND_MOUSE.mclicked = true, true
        GRND_MOUSE.mclickedBtn = 3
        GRND_MOUSE.x, GRND_MOUSE.y = grndMouseXY(lparam)
    elseif msgN == 0x0208 then
        GRND_MOUSE.mdown = false
        GRND_MOUSE.x, GRND_MOUSE.y = grndMouseXY(lparam)
    elseif msgN == 0x0209 then
        GRND_MOUSE.mclicked = true
        GRND_MOUSE.mclickedBtn = 3
        GRND_MOUSE.x, GRND_MOUSE.y = grndMouseXY(lparam)
    elseif msgN == 0x0200 or msgN == 0x020A or msgN == 0x020D then
        GRND_MOUSE.x, GRND_MOUSE.y = grndMouseXY(lparam)
    end
    GRND_MOUSE.at = os.clock()
    if isMouse and not isDown and not isUp then
        if msgN == 0x0201 or msgN == 0x0203 or msgN == 0x0204 or msgN == 0x0206 then
            GRND_MOUSE.frame = GRND_UIFRAME + 1
        end
    end
    if GRND_RC and GRND_RC.show
        and (wp == 0x25 or wp == 0x26 or wp == 0x27 or wp == 0x28
            or wp == 0xBB or wp == 0x6B or wp == 0xBD or wp == 0x6D) then
        if grndCamWindowsOpen() or grndServerDialogOpen() then
            GRND_RC.camKeys = GRND_RC.camKeys or {}
            GRND_RC.camKeys[wp] = false
        else
            GRND_RC.camKeys = GRND_RC.camKeys or {}
            GRND_RC.camKeys[wp] = not isUp
            grndConsumeMsg(true)
            return
        end
    end
    if GRND_RC and GRND_RC.show
        and (msgN == 0x0204 or msgN == 0x0205 or msgN == 0x0206) then
        if msgN == 0x0204 then
            GRND_RC.rmbWmTap = true
            GRND_RC.rmbWmHeld = true
            GRND_RC.rmbWmHeldAt = os.clock()
            GRND_RC.rmbWmSeen = true
        elseif msgN == 0x0205 then
            GRND_RC.rmbWmUp = true
            GRND_RC.rmbWmHeld = false
            GRND_RC.rmbWmSeen = true
        end
        grndConsumeMsg(true)
        return
    end
    if (GRND_KL and GRND_KL.moving) or (GRND_AO and GRND_AO.moving)
       or (_G.GRND_SFR and _G.GRND_SFR.moving)
       or (_G.GRND_FCHAT and _G.GRND_FCHAT.moving) then
        if isMouse then
            if msgN == 0x0201 then
                if GRND_KL and GRND_KL.moving then GRND_KL.click = true end
                if GRND_AO and GRND_AO.moving then GRND_AO.click = true end
                if _G.GRND_SFR and _G.GRND_SFR.moving then _G.GRND_SFR.click = true end
                if _G.GRND_FCHAT and _G.GRND_FCHAT.moving then _G.GRND_FCHAT.click = true end
            end
            grndConsumeMsg(true)
            return
        end
        if isDown and wp == 0x1B then
            if GRND_KL and GRND_KL.moving then GRND_KL.cancel = true end
