function grndMemLib()
    if GRND_MEM.tried then return GRND_MEM.lib end
    GRND_MEM.tried = true
    local ok, m = pcall(require, "memory")
    if ok and type(m) == "table" then
        m._get32 = m.getint32 or m.readint32
        m._set32 = m.setint32 or m.writeint32
        m._get8  = m.getint8  or m.readint8
        m._set8  = m.setint8  or m.writeint8
        if type(m._get32) == "function" and type(m._get8) == "function" then
            GRND_MEM.lib = m
        else
            pcall(grndTrace, "mem", "memory.lua: нет getint32/getint8 — доступ к памяти выключен")
        end
    end
    return GRND_MEM.lib
end
local function grndMemS2u(v)
    if v == nil then return nil end
    return math.floor(v) % 0x100000000
end
local grndMemU32 = grndMemS2u
local function grndMemValidPtr(v)
    local u = grndMemU32(v)
    return u ~= nil and u >= 0x10000 and u < 0xFFFF0000
end
local function grndMemRd32(a)
    local mem = grndMemLib()
    if not mem then return nil end
    local ok, v = pcall(mem._get32 or mem.getint32, a)
    return ok and v or nil
end
local function grndMemRd8(a)
    local mem = grndMemLib()
    if not mem then return nil end
    local ok, v = pcall(mem._get8 or mem.getint8, a)
    if ok and type(v) == "number" then return math.floor(v) % 256 end
    return nil
end
local function grndMemWr32(a, v)
    local mem = grndMemLib()
    if not mem then return end
    v = math.floor(tonumber(v) or 0)
    if v > 0x7FFFFFFF then v = v - 0x100000000 end
    pcall(mem._set32 or mem.setint32, a, v, true)
end
local function grndMemWr8(a, v)
    local mem = grndMemLib()
    if not mem then return end
    pcall(mem._set8 or mem.setint8, a, v, true)
end
local function grndMemRdStr(a, maxlen)
    local mem = grndMemLib()
    if not mem or not a or a == 0 then return nil end
    local buf = {}
    local ok = pcall(function()
        for i = 0, maxlen - 1 do
            local b = (mem._get8 or mem.getint8)(a + i)
            if b == nil then break end
            b = b % 256
            if b == 0 then break end
            buf[#buf + 1] = string.char(b)
        end
    end)
    if not ok then return nil end
    return table.concat(buf)
end
local function grndIsUtf8(s)
    if type(s) ~= "string" then return false end
    local i, n = 1, #s
    while i <= n do
        local b = s:byte(i)
        local len
        if b < 0x80 then len = 1
        elseif b >= 0xC2 and b <= 0xDF then len = 2
        elseif b >= 0xE0 and b <= 0xEF then len = 3
        elseif b >= 0xF0 and b <= 0xF4 then len = 4
        else return false end
        for k = 1, len - 1 do
            local c = s:byte(i + k)
            if not c or c < 0x80 or c > 0xBF then return false end
        end
        i = i + len
    end
    return true
end
