local function grndU8Put(cp)
    if cp < 0x80 then return string.char(cp) end
    if cp < 0x800 then
        return string.char(0xC0 + math.floor(cp / 64), 0x80 + (cp % 64))
    end
    return string.char(
        0xE0 + math.floor(cp / 4096),
        0x80 + (math.floor(cp / 64) % 64),
        0x80 + (cp % 64))
end
local function grndCp1251ToUtf8(s)
    local t = {}
    for i = 1, #s do
        local b = s:byte(i)
        if b < 0x80 then
            t[i] = string.char(b)
        elseif b >= 0xC0 then
            t[i] = grndU8Put(0x0410 + (b - 0xC0))
        else
            t[i] = grndU8Put(GRND_CP1251_HI[b - 0x7F] or b)
        end
    end
    return table.concat(t)
end
local GRND_U2CP = nil
local function grndUtf8ToCp1251(s)
    if not GRND_U2CP then
        GRND_U2CP = {}
        for i = 1, 64 do GRND_U2CP[GRND_CP1251_HI[i]] = 0x7F + i end
        for b = 0xC0, 0xFF do GRND_U2CP[0x0410 + (b - 0xC0)] = b end
    end
    local t, i, n = {}, 1, #s
    while i <= n do
        local b = s:byte(i)
        local cp, step
        if b < 0x80 then
            t[#t + 1] = string.char(b); i = i + 1
        else
            if b < 0xE0 then
                cp = (b % 0x20) * 0x40 + ((s:byte(i + 1) or 0) % 0x40)
                step = 2
            elseif b < 0xF0 then
                cp = (b % 0x10) * 0x1000
                    + ((s:byte(i + 1) or 0) % 0x40) * 0x40
                    + ((s:byte(i + 2) or 0) % 0x40)
                step = 3
            else
                cp, step = 0x3F, 4
            end
            local byte = GRND_U2CP[cp]
            t[#t + 1] = byte and string.char(byte) or "?"
            i = i + step
        end
    end
    return table.concat(t)
end
local function grndEncLib()
    return encoding or (type(libs) == "table" and libs.encoding) or nil
end
local function grndToUtf(s)
    if type(s) ~= "string" or s == "" then return s end
    if not s:find("[\128-\255]") then return s end
    if grndIsUtf8(s) then return s end
    local enc = grndEncLib()
    if enc and enc.UTF8 then
        local prev = enc.default
        enc.default = "CP1251"
        local ok, out = pcall(function() return enc.UTF8:encode(s) end)
        enc.default = prev
        if ok and type(out) == "string" and out ~= "" and grndIsUtf8(out) then
            return out
        end
    end
    return grndCp1251ToUtf8(s)
end
local function grndToAnsi(s)
    if type(s) ~= "string" or s == "" then return s end
    if not s:find("[\128-\255]") then return s end
    if not grndIsUtf8(s) then return s end
    local enc = grndEncLib()
    if enc and enc.UTF8 then
        local prev = enc.default
        enc.default = "CP1251"
        local ok, out = pcall(function() return enc.UTF8:decode(s) end)
        enc.default = prev
        if ok and type(out) == "string" and out ~= "" then return out end
    end
