_G.grndUtf8ToCp1251 = grndUtf8ToCp1251
do
    local grndRawPrint = print
    if type(grndRawPrint) == "function" then
        print = function(...)
            local n = select("#", ...)
            local out = {}
            for i = 1, n do
                local v = select(i, ...)
                if type(v) == "string" then
                    local cvt = _G.grndToAnsi
                    if type(cvt) == "function" then
                        local ok, c = pcall(cvt, v)
                        if ok and type(c) == "string" then v = c end
                    end
                end
                out[i] = tostring(v)
            end
            return grndRawPrint(table.concat(out, "\t"))
        end
    end
end
function grndAnsiText(text)
    local out = tostring(text or "")
    if out == "" then return out end
    local cvt = _G.grndToAnsi
    if type(cvt) == "function" then
        local ok, ansi = pcall(cvt, out)
        if ok and type(ansi) == "string" and ansi ~= "" then return ansi end
    end
    local pure = _G.grndUtf8ToCp1251
    if type(pure) == "function" then
        local ok2, cp = pcall(pure, out)
        if ok2 and type(cp) == "string" and cp ~= "" then return cp end
    end
    return out
end
function grndUtf8Text(v)
    local out = tostring(v or "")
    if out == "" then return out end
    local cvt = _G.grndToUtf
    if type(cvt) == "function" then
        local ok, u = pcall(cvt, out)
        if ok and type(u) == "string" and u ~= "" then return u end
    end
    return out
end
