    ["Ч"] = "X", ["С"] = "C", ["М"] = "V", ["И"] = "B", ["Т"] = "N",
    ["Ь"] = "M", ["Б"] = "<", ["Ю"] = ">",
}
function grndChatCommandToEnglishLayout(text, allowMissingSlash)
    local source = tostring(text or "")
    local utf = (type(grndToUtf) == "function") and grndToUtf(source) or source
    local lead, command, tail = utf:match("^(%s*/)([^%s]+)(.*)$")
    if not command and allowMissingSlash then
        lead, command, tail = utf:match("^(%s*)([^%s]+)(.*)$")
    end
    if not command then return utf, false end
    local converted = command:gsub("[%z\1-\127\194-\244][\128-\191]*",
        function(ch) return _G.GRND_CHAT_RU_KEY_LAYOUT[ch] or ch end)
    if converted == command then return utf, false end
    return lead .. converted .. tail, true
end

function grndChatSend(cmd)
    if type(cmd) ~= "string" or cmd == "" then return false end
    if type(sampSendChat) ~= "function" then return false end
    return pcall(sampSendChat, grndAnsiText(cmd)) and true or false
end
function grndChatSay(text, color)
    if type(text) ~= "string" or text == "" then return false end
    if type(sampAddChatMessage) ~= "function" then return false end
    return pcall(sampAddChatMessage, grndAnsiText(text), grndChatNativeColor(text, color or -1)) and true or false
end
_G.GRND_FORM_CH = _G.GRND_FORM_CH or "a"
_G.GRND_FORM_EX_TAG = _G.GRND_FORM_EX_TAG or "Пример правильной команды >> "
function grndFormAcceptMsg(nick)
    return "/" .. tostring(_G.GRND_FORM_CH or "a") .. " Форма от "
        .. grndUtf8Text(nick) .. " принята."
end
function grndFormAcceptSend(nick)
    local msg = grndFormAcceptMsg(nick)
    return msg, grndChatSend(msg)
end
function grndFormPrefix()
    return "/" .. tostring(_G.GRND_FORM_CH or "a") .. " "
end
function grndFormFitText(text, prefix)
    text = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then return "" end
    local head = tostring(prefix or "")
    local limit = tonumber(_G.GRND_FORM_MSG_LIMIT) or 140
    if grndFormAnsiLen(head .. text) <= limit then return head .. text end
    local room = limit - grndFormAnsiLen(head) - 3
    if room < 8 then return "" end
    local cut = grndFormUtf8Cut(text, room * 2)
    while #cut > 2 and grndFormAnsiLen(head .. cut .. "...") > limit do
        cut = grndFormUtf8Cut(cut, #cut - 2)
    end
    if cut == "" then return "" end
    return head .. cut .. "..."
end
function grndFormBadMsg(nick)
    return grndFormPrefix() .. "Форма от " .. grndUtf8Text(nick) .. " отклонена!"
end
function grndFormBadSend(nick)
    local msg = grndFormBadMsg(nick)
    return msg, grndChatSend(msg)
end
function grndFormSignTailPattern()
    return "|%s*[%a\128-\255][%w\128-\255%.%-]-%.[%w\128-\255%.%-]+%s*"
end
function grndFormPipeToArrow(s)
    local t = tostring(s or "")
    if t == "" then return t end
    local tail = t:match("(" .. grndFormSignTailPattern() .. ")$")
    local body = t
    if tail then body = t:sub(1, #t - #tail) end
    body = body:gsub("%s*|%s*", " >> ")
    body = body:gsub("^%s+", "")
    body = body:gsub("%s+$", "")
    if tail then
        tail = tail:gsub("^%s+", "")
        tail = tail:gsub("%s+$", "")
        if body == "" then return tail end
        body = body .. " " .. tail
    end
    return body
end
function grndFormDetailMsg(reason)
    return grndFormFitText(grndFormPipeToArrow(grndFormWaitNorm(reason)), grndFormPrefix())
end
function grndFormDetailSend(reason)
    local msg = grndFormDetailMsg(reason)
    if msg == "" then return "", false end
    return msg, grndChatSend(msg)
end
function grndFormFixList(limit)
    limit = tonumber(limit) or ((tonumber(_G.GRND_FORM_MSG_LIMIT) or 140) - 6)
    local t = {}
    for k in pairs(GRND_FORM_SYNTAX) do t[#t + 1] = "/" .. k end
    table.sort(t)
    local out = "Команды:"
    for i = 1, #t do
        local cand = out .. " " .. t[i]
        if grndFormAnsiLen(cand) > limit then break end
        out = cand
    end
    return out
end
function grndFormFixCmd(cmd, suggest, example, limit)
    local ex = tostring(example or "")
    if ex ~= "" then return ex end
    return grndFormFixList(limit)
end
function grndFormFixSend(cmd, example, suggest)
    local prefix = grndFormPrefix() .. tostring(_G.GRND_FORM_EX_TAG or "")
    local limit = (tonumber(_G.GRND_FORM_MSG_LIMIT) or 140) - grndFormAnsiLen(prefix)
    local text = grndFormFixCmd(cmd, suggest, example, limit)
    if text == "" then return "", false end
    local msg = grndFormFitText(text, prefix)
    return text, grndChatSend(msg)
end
GRND_FORM_SYNTAX = {
