    unjail = { args = "i",        example = "/unjail ID игрока" },
    rmute  = { args = "i t r",    example = "/rmute {ID игрока} {время} {причина}" },
    ban    = { args = "i t r",    example = "/ban {ID игрока} {время в днях} {причина}" },
    warn   = { args = "n r",      idOk = true, example = "/warn {ID или NickName игрока} {причина}" },
    unwarn = { args = "n r",      example = "/unwarn {ID игрока} {причина}" },
    spcar  = { args = "v",        example = "/spcar ID транспорта" },
