    offmute = { args = "n t r",   example = "/offmute {NickName игрока} {время в минутах} {причина}" },
    offban  = { args = "n t r",   example = "/offban {NickName игрока} {время в днях} {причина}" },
    offwarn = { args = "n r",     example = "/offwarn {NickName игрока} {причина}" },
