    offjail = true, offmute = true, offban = true, offwarn = true,
}
function grndFormIsPunish(name)
    return GRND_FORM_PUNISH[tostring(name or ""):lower()] == true
end
GRND_FORM_ALLOWED_EXTRA = {
    uncuff = true, arm = true, unwarn = true, offunwarn = true, unjail = true,
    unfreeze = true, auninvite = true, rgun = true, runmute = true,
    unmute = true, unban = true, offunjail = true, spawn = true,
    flip = true, fixcar = true, setskin = true, untie = true,
}
function grndFormCommandName(cmd)
    local s = tostring(cmd or ""):gsub("^%s+", "")
    local name = s:match("^/([%a][%w_]*)")
    if not name then name = s:match("^([%a][%w_]*)") end
    return name and name:lower() or nil
end
function grndFormIsAllowed(name)
    local key = tostring(name or ""):lower()
    return grndFormIsPunish(key) or GRND_FORM_ALLOWED_EXTRA[key] == true
end
GRND_FORM_SIGNED = {
    jail = true, warn = true, kick = true, mute = true, ban = true, rmute = true,
    offjail = true, offmute = true, offwarn = true, offban = true,
}
function grndFormSignTail(s)
    return tostring(s or ""):match("|%s*([%a\128-\255][%w\128-\255%.%-]-%.[%w\128-\255%.%-]+)%s*$")
end
function grndFormInitials(nick)
    local u=grndUtf8Text(nick)
    u=u:gsub("{%x%x%x%x%x%x%x%x}",""):gsub("{%x%x%x%x%x%x}","")
    u=u:gsub("%s*%[%d+%]%s*$",""):match("^%s*(.-)%s*$") or ""
    local first,last=u:match("^([^_%.]+)[_%.](.+)$")
    if not first or first=="" or last=="" then return nil end
    local ch=first:match("^[%z\1-\127\194-\244][\128-\191]*")
    if not ch then return nil end
    local lower="абвгдеёжзийклмнопрстуфхцчшщъыьэюя"
    local upper="АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ"
    local n=0
    for c in lower:gmatch("[\194-\244][\128-\191]*") do
        n=n+1
        if c==ch then
            local j=0
            for cap in upper:gmatch("[\194-\244][\128-\191]*") do
                j=j+1;if j==n then ch=cap;break end
            end
            break
        end
    end
    return ch:upper().."."..last
end
function grndFormAuthorSignature(form)
    local nick=grndUtf8Text(form.adminNick)
    nick=nick:gsub("{%x%x%x%x%x%x%x%x}",""):gsub("{%x%x%x%x%x%x%x}","")
    nick=nick:gsub("%s*%[%d+%]%s*$",""):match("^%s*(.-)%s*$") or ""
    if nick=="" and tonumber(form.adminId) and type(sampGetPlayerNickname)=="function" then
        local ok,name=pcall(sampGetPlayerNickname,tonumber(form.adminId))
        if ok and type(name)=="string" then nick=grndUtf8Text(name) end
    end
    if nick=="" or nick:find("[%s|/%c]") then return nil end
    return grndFormInitials(nick) or nick
end
function grndFormWarnIdCfgOn()
    return true
end
function grndFormArgsStrictOn()
    return true
end
function grndFormArgIsNick(cmdName)
    local syn = GRND_FORM_SYNTAX[tostring(cmdName or ""):lower()]
    if type(syn) ~= "table" or type(syn.args) ~= "string" then return false end
    return syn.args:sub(1, 1) == "n"
end
function grndFormTargetIdOf(cmd, cmdName)
    if not grndFormArgIsNick(cmdName) then return nil end
    local s = tostring(cmd or ""):gsub("^%s*[/%!%.]?%a[%w_]*%s*", "")
    local v = s:match("^(%S+)")
    if not v or not v:find("^%d+$") then return nil end
    return tonumber(v)
end
function grndFormTargetOnline(id)
    local num = tonumber(id)
    if not num then return false, "", "цель — не число" end
    if type(sampIsPlayerConnected) ~= "function" then
        return false, "", "нет API SA-MP"
    end
    local okC, conn = pcall(sampIsPlayerConnected, num)
    if (not okC) or (not conn) then return false, "", "нет в списке игроков" end
    local nick = ""
    if type(sampGetPlayerNickname) == "function" then
        local okN, n = pcall(sampGetPlayerNickname, num)
        if okN and type(n) == "string" and n ~= "" then
            if type(_G.grndUtf8Text) == "function" then
                local okU, u = pcall(_G.grndUtf8Text, n)
                nick = (okU and type(u) == "string" and u ~= "") and u or n
            else
                nick = n
            end
        end
    end
    return true, nick, ""
end
function grndFormTargetNote(cmd, cmdName)
    local id = grndFormTargetIdOf(cmd, cmdName)
    if not id then return nil end
    local on, nick, why = grndFormTargetOnline(id)
    local who = "#" .. tostring(id)
    if nick ~= "" then who = who .. " (" .. nick .. ")" end
    if on then return who .. " в сети", true end
    return who .. " НЕ в сети (" .. tostring(why) .. ")", false
end
function grndFormLev(a, b)
    a, b = tostring(a or ""):lower(), tostring(b or ""):lower()
    if a == b then return 0 end
    if #a == 0 then return #b end
    if #b == 0 then return #a end
    local prev, cur = {}, {}
    for j = 0, #b do prev[j] = j end
    for i = 1, #a do
        cur[0] = i
        for j = 1, #b do
            local cost = (a:sub(i, i) == b:sub(j, j)) and 0 or 1
            cur[j] = math.min((prev[j] or 0) + 1, (cur[j - 1] or 0) + 1, (prev[j - 1] or 0) + cost)
        end
        for j = 0, #b do prev[j] = cur[j] end
    end
    return prev[#b] or 0
end
function grndFormSuggest(name)
    local key = tostring(name or ""):lower()
    if key == "" then return nil end
    local best, bestD = nil, 99
    for k in pairs(GRND_FORM_SYNTAX) do
        local d = grndFormLev(key, k)
        if d < bestD then bestD, best = d, k end
    end
    if best and bestD < #key and (bestD <= 1 or #key >= 5) then return best end
    return nil
end
function grndFormKnownList()
    local t = {}
    for k in pairs(GRND_FORM_SYNTAX) do t[#t + 1] = "/" .. k end
    table.sort(t)
    return table.concat(t, ", ")
end
function grndFormBaseCheck(cmd)
    local s = tostring(cmd or ""):gsub("^%s+", "")
    if s == "" then return false, "", "пустая команда", nil end
    if s:sub(1, 1) ~= "/" then
        local nm = s:match("^[/%!%.]?(%a[%w_]*)")
        local sug = nm and grndFormSuggest(nm) or nil
        local ex = (sug and GRND_FORM_SYNTAX[sug]) and GRND_FORM_SYNTAX[sug].example or ""
        return false, ex, "команда без слэша", sug
    end
    local name = s:match("^/(%a[%w_]*)")
    if not name then return false, "", "не вижу имени команды", nil end
    local key = name:lower()
    if grndFormIsPunish(key) and not GRND_FORM_SYNTAX[key] then
        local sug = grndFormSuggest(key)
        local ex = (sug and GRND_FORM_SYNTAX[sug]) and GRND_FORM_SYNTAX[sug].example or ""
        return false, ex, "нет синтаксиса наказания /" .. name, sug
    end
    return true, "", "", key
end
function grndFormBareCmd(msg)
    return nil
end
function grndFormCheck(cmd)
    local s = tostring(cmd or ""):gsub("^%s+", "")
    if s == "" then return false, "", "пустая команда", nil end
    if s:sub(1, 1) ~= "/" then
        local nm = s:match("^[/%!%.]?(%a[%w_]*)")
        local sug = nm and grndFormSuggest(nm) or nil
        local ex = (sug and GRND_FORM_SYNTAX[sug]) and GRND_FORM_SYNTAX[sug].example or ""
        return false, ex, "команда без слэша", sug
    end
    local name, rest = s:match("^/(%a[%w_]*)%s*(.*)$")
    if not name then
        return false, "", "не вижу имени команды", nil
    end
    local key = name:lower()
    if not grndFormIsPunish(key) then return true end
    local syn = GRND_FORM_SYNTAX[key]
    if not syn then
        local sug = grndFormSuggest(key)
        local ex = (sug and GRND_FORM_SYNTAX[sug]) and GRND_FORM_SYNTAX[sug].example or ""
        return false, ex, "нет синтаксиса наказания /" .. name, sug
    end
    local head = rest:match("^(.-)%s*|%s*[%a\128-\255][%w\128-\255%.%-]-%.[%w\128-\255%.%-]+%s*$")
    if head ~= nil then rest = head end
    if rest:find("[\t\r\n%z]") then
        return false, syn.example, "недопустимый перенос строки или табуляция", nil
    end
    local spec = {}
    for w in syn.args:gmatch("%S+") do spec[#spec + 1] = w end
    local toks = {}
    for w in rest:gmatch("%S+") do toks[#toks + 1] = w end
    local needReason = (spec[#spec] == "r")
    local fixed = needReason and (#spec - 1) or #spec
    if #toks < fixed then return false, syn.example, "мало аргументов", nil end
    if needReason and #toks <= fixed then return false, syn.example, "не указана причина", nil end
    local prefix = rest
    if needReason then
        local cursor = 1
        for i = 1, fixed do
            local _, last = rest:find("%S+", cursor)
            cursor = last + 1
        end
        prefix = rest:sub(1, cursor - 1)
    end
    if prefix:find("%s%s") then return false, syn.example, "лишние пробелы в аргументах", nil end
    if not needReason and rest:find("%s$") then
        return false, syn.example, "лишний пробел в конце", nil
    end
    if not needReason and #toks > #spec and grndFormArgsStrictOn() then
        return false, syn.example, "лишние аргументы", nil
    end
    for k = 1, fixed do
        local v, kind = toks[k], spec[k]
        if kind == "i" then
            if not v:find("^%d+$") then return false, syn.example, "ID игрока — не число", nil end
            local num = tonumber(v)
            if not num or num > 1000 then return false, syn.example, "неверный ID игрока", nil end
        elseif kind == "v" then
            if not v:find("^%d+$") then return false, syn.example, "ID транспорта — не число", nil end
            local num = tonumber(v)
            if not num or num < 1 or num > 2000 then
                return false, syn.example, "неверный ID транспорта", nil
            end
        elseif kind == "t" then
            if not v:find("^%d+$") then return false, syn.example, "время — не число", nil end
            local num = tonumber(v)
            if not num or num == 0 then return false, syn.example, "время должно быть больше 0", nil end
            if num > 100000 then return false, syn.example, "слишком большое время", nil end
        elseif kind == "n" then
            if v:find("^%d+$") then
                if not (syn.idOk and grndFormWarnIdCfgOn()) then
                    return false, syn.example, "вместо ника указан ID игрока", nil
                end
                local num = tonumber(v)
                if not num or num > 1000 then
                    return false, syn.example, "неверный ID игрока", nil
                end
                local note = grndFormTargetNote(s, key)
                if note then
                    pcall(grndTrace, "forms", "цель формы — ID: " .. note
                        .. " | " .. tostring(s))
                end
            elseif not v:find("[%a\128-\255]") then
                return false, syn.example, "вместо ника указан ID игрока", nil
            else
                if #v < 3 then return false, syn.example, "слишком короткий ник", nil end
                if v:find("[^%w\128-\255_%.%[%]%-%@]") then
                    return false, syn.example, "недопустимые символы в нике", nil
                end
            end
        end
    end
    return true
end
function grndFormUnbanDiscord(form)
    if type(form) ~= "table" then return false end
    local nick = grndUtf8Text(form.adminNick)
    nick = nick:gsub("{%x%x%x%x%x%x%x%x}", ""):gsub("{%x%x%x%x%x%x}", "")
        :gsub("%s*%[%d+%]%s*$", ""):gsub("[%c/|]", "")
        :gsub("^%s+", ""):gsub("%s+$", "")
    if nick == "" then nick = "ID " .. tostring(tonumber(form.adminId) or 0) end
    local firstOk = grndChatSend("/a Форма от " .. nick .. " отклонена!")
    local secondOk = grndChatSend("/a Пропиши форму в Discord")
    pcall(grndTrace, "forms", "форма /unban перенаправлена в Discord: " .. nick)
    return firstOk and secondOk
end
function grndFormApply(form)
    if type(form) ~= "table" then return nil, "bad" end
    local name = grndFormCommandName(form.cmd) or ""
    if not grndFormIsAllowed(name) then
        pcall(grndTrace, "forms", "команда вне списка форм проигнорирована: " .. tostring(form.cmd))
        return nil, "ignored", "команда не входит в разрешённый список"
    end
    if name == "unban" then
        if grndFormUnbanDiscord(form) then return nil, "redirected" end
        return nil, "redirected", "не удалось отправить сообщение в админ-чат"
    end
    local punish = grndFormIsPunish(name)
    local ok, example, why, suggest = grndFormCheck(form.cmd)
    if not ok then
        grndFormBadSend(form.adminNick)
        local fixed = grndFormFixSend(form.cmd, example, suggest)
        pcall(grndTrace, "forms", "форма отклонена до отправки: " .. tostring(why)
            .. " | " .. tostring(form.cmd) .. " | правильная форма: " .. tostring(fixed))
        return nil, "bad", tostring(why or "команда неверна")
    end
    local cmd = grndUtf8Text(form.cmd)
    do
        local note, on = grndFormTargetNote(cmd, name)
        if note then
            pcall(grndTrace, "forms", "принята форма с целью-ID: " .. tostring(note))
            if type(notify) == "table" and notify.add then
                pcall(notify.add, "Цель формы: " .. tostring(note), on and "info" or "warn", 4)
            end
        end
    end
    if GRND_FORM_SIGNED[name] and not grndFormSignTail(cmd) then
        local ini=grndFormAuthorSignature(form)
        if not ini then
            pcall(grndTrace,"forms","не удалось определить подпись автора формы")
            return nil,"bad","Не удалось определить автора формы; команда не отправлена"
        end
        cmd=cmd:gsub("%s+$","").." | "..ini
        pcall(grndTrace,"forms","подпись формы: "..name.." | "..ini)
    end
    if not grndChatSend(cmd) then
        return nil,"bad","Не удалось отправить команду на сервер"
    end
    local started = false
    if type(grndFormWatchStart) == "function" then
        local okW, resW = pcall(grndFormWatchStart, form, cmd, name, not punish)
        started = (okW and resW == true)
    end
    if not started then
        grndFormAcceptSend(form.adminNick)
    end
    return cmd, "ok"
end
