function grndLowerUtf(s)
    s = tostring(s or "")
    if s == "" then return s end
    local out, i, n = {}, 1, #s
    while i <= n do
        local b = s:byte(i)
        if b < 0x80 then
            out[#out + 1] = (b >= 0x41 and b <= 0x5A) and string.char(b + 0x20) or string.char(b)
            i = i + 1
        elseif b >= 0xC2 and b <= 0xDF then
            local b2 = s:byte(i + 1) or 0
            local cp = (b % 0x20) * 0x40 + (b2 % 0x40)
            local res
            if cp >= 0x0410 and cp <= 0x042F then res = 0x0430 + (cp - 0x0410)
            elseif cp == 0x0401 then res = 0x0451
            elseif cp >= 0x00C0 and cp <= 0x00DE and cp ~= 0x00D7 then res = cp + 0x20
            else res = cp end
            out[#out + 1] = grndU8Put(res)
            i = i + 2
        elseif b >= 0xE0 then
            out[#out + 1] = s:sub(i, i + 2)
            i = i + 3
        else
            out[#out + 1] = string.char(b)
            i = i + 1
        end
    end
    return table.concat(out)
end
function grndWeaponFold(s)
    s = tostring(s or "")
    if s == "" then return s end
    s = s:lower()
    local utf8 = false
    if type(_G.grndIsUtf8) == "function" then
        local ok, r = pcall(_G.grndIsUtf8, s)
        utf8 = ok and r or false
    end
    if not utf8 then
        local out = {}
        for i = 1, #s do
            local b = s:byte(i)
            if b >= 192 and b <= 223 then out[i] = string.char(b + 32)
            elseif b == 168 then out[i] = string.char(184)
            else out[i] = string.char(b) end
        end
        return table.concat(out)
    end
    local D0, D1 = string.char(208), string.char(209)
    local out, i, n = {}, 1, #s
    while i <= n do
        local b = s:byte(i)
        if b == 208 and i < n then
            local b2 = s:byte(i + 1)
            if b2 >= 144 and b2 <= 159 then
                out[#out + 1] = D0 .. string.char(b2 + 32)
            elseif b2 >= 160 and b2 <= 175 then
                out[#out + 1] = D1 .. string.char(b2 - 32)
            elseif b2 == 129 then
                out[#out + 1] = D1 .. string.char(145)
            else
                out[#out + 1] = D0 .. string.char(b2)
            end
            i = i + 2
        else
            out[#out + 1] = string.char(b)
            i = i + 1
        end
    end
    return table.concat(out)
end
function grndWeaponAliasFold()
    local folded = GRND_WEAPON_ALIAS_FOLD
    if folded then return folded end
    folded = {}
    for k, v in pairs(GRND_WEAPON_ALIAS) do
        folded[grndWeaponFold(k):gsub("[%s%-%._]", "")] = v
    end
    GRND_WEAPON_ALIAS_FOLD = folded
    return folded
end
function grndWeaponJunkWord(s)
    for w in tostring(s or ""):gmatch("%a+") do
        local latin, vowel = true, false
        for i = 1, #w do
            local b = w:byte(i)
            if b > 127 then latin = false break end
            local c = string.char(b):lower()
            if c == "a" or c == "e" or c == "i" or c == "o" or c == "u" then vowel = true end
        end
        if latin and #w >= 3 and not vowel then return true end
    end
    return false
end
function grndWeaponRead(raw)
    local s = tostring(raw or "")
    local wasEmpty = (s == "")
    if not wasEmpty then
        if type(grndUtf8Text) == "function" then s = grndUtf8Text(s) end
        s = s:gsub("{%x%x%x%x%x%x}", ""):gsub("{%X%X%X%X%X%X}", "")
        s = s:gsub("~%a~", " ")
        s = s:gsub("[_%.]+", " ")
        s = s:gsub("^%s*[%a%s]*:%s*", "")
        s = s:gsub("[%p]+", " ")
        s = s:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    end
    if wasEmpty or #s < 2 then return nil, "empty" end
    if GRND_WEAPON_EMPTY[s] or GRND_WEAPON_EMPTY[s:lower()] then return nil, "empty" end
    if s:match("^%d+$") then
        local idw = tonumber(s)
        if idw and idw > 0 and GRND_WEAPON_NAMES[idw] then
            return GRND_WEAPON_NAMES[idw], "name"
        end
        return nil, "empty"
    end
    local folded = grndWeaponAliasFold()
    local key = grndWeaponFold(s):gsub("[%s%-%._]", "")
    if folded[key] then return folded[key], "name" end
    local cut = s:gsub("%s+%d+%s*$", "")
    if cut ~= s and cut ~= "" then
        local key2 = grndWeaponFold(cut):gsub("[%s%-%._]", "")
        if folded[key2] then return folded[key2], "name" end
    end
    if grndWeaponJunkWord(s) then return nil, "junk" end
    local nonAscii = false
    for i = 1, #s do
        if s:byte(i) > 127 then nonAscii = true break end
    end
    if nonAscii then return s, "name" end
    if #s >= 3 and s:match("^[%a%d ]+$") and s:match("[aeiouAEIOU]") then
        return s, "name"
    end
    return nil, "junk"
end
function grndWeaponInHand(id)
    local SN = _G.grndSpecNative
    if not SN or type(SN.pedOf) ~= "function" then return nil end
    local okP, ped = pcall(SN.pedOf, id)
    if not okP or not ped then return nil end
    if type(getCurrentCharWeapon) == "function" then
        local ok, w = pcall(getCurrentCharWeapon, ped)
        if ok and type(w) == "number" then
            if w <= 0 then return false end
            if GRND_WEAPON_NAMES[w] then return GRND_WEAPON_NAMES[w] end
            if w <= 46 then return "Оружие #" .. tostring(w) end
        end
    end
    if type(getCharWeaponInSlot) ~= "function" then return nil end
    local found, slotN = nil, 0
    for slot = 1, 10 do
        local okS, w = pcall(getCharWeaponInSlot, ped, slot)
        if okS and type(w) == "number" and w > 0 and w <= 46 then
            found = found or w
            slotN = slotN + 1
        end
    end
    if slotN == 0 then return false end
    if slotN == 1 then
        return GRND_WEAPON_NAMES[found] or ("Оружие #" .. tostring(found))
    end
    return nil
end
function grndWeaponLabel(serverValue, id)
    local sname, kind = grndWeaponRead(serverValue)
    local inHand = grndWeaponInHand(id)
    if type(inHand) == "string" then return inHand end
    if inHand == false then
        if kind == "name" then return sname end
        local rawAmmo = _G.GRND_RC and _G.GRND_RC.live and _G.GRND_RC.live.ammo or nil
        local ammo = tonumber(tostring(rawAmmo or ""):match("%d+"))
        if ammo and ammo > 0 then
            return "оружие (патронов " .. tostring(ammo) .. ")"
        end
        return "Нет оружия в руках"
    end
    if kind == "name" then return sname end
    if kind == "empty" then return "Нет оружия в руках" end
    return "—"
end
