GRND_STATS_VIEW_KEEP = 60
function grndStatsViewFresh(now)
    local RC = _G.GRND_RC
    if type(RC) ~= "table" or type(RC.statsView) ~= "table" then return false end
    return ((tonumber(now) or os.clock()) - (RC.statsView.at or 0))
        < (tonumber(GRND_STATS_VIEW_KEEP) or 60)
end
function grndStatsCopy(t)
    local out = {}
    if type(t) == "table" then
        for k, v in pairs(t) do out[k] = v end
    end
    return out
end
function grndStatsPopup(id, nick)
    if type(grndSessionReady) == "function" then
        local okReady, ready = pcall(grndSessionReady)
        if not okReady or not ready then return false end
    elseif type(grndUiBlocked) == "function" then
        local okBlocked, blocked = pcall(grndUiBlocked)
        if not okBlocked or blocked then return false end
    end
    local RC = _G.GRND_RC
    if type(RC) ~= "table" then return false end
    id = tonumber(id)
    local specOn = (_G.GRND_SPEC and _G.GRND_SPEC.active) and true or false
    if not specOn and _G.grndSpecNative and _G.grndSpecNative.camOn then
        specOn = true
    end
    if not specOn and RC.show and RC.id and (not RC.statsOnly or RC.reconTdActive) then
        specOn = true
    end
    if not specOn and type(sampIsPlayerSpectating) == "function" then
        local okSpec, active = pcall(sampIsPlayerSpectating)
        specOn = okSpec and active and true or false
    end
    local wasShown = (RC.show == true)
    if id and not specOn then RC.id = id end
    RC.show = true
    RC.infoOpen, RC.paramsOpen = true, true
    if (not nick or nick == "") and id
        and type(sampGetPlayerNickname) == "function" then
        local okn, nm = pcall(sampGetPlayerNickname, id)
        if okn and type(nm) == "string" and nm ~= "" then nick = nm end
    end
    if nick and nick ~= "" then RC.nick = tostring(nick) end
    RC.statsView = { at = os.clock(), id = id or tonumber(RC.id) }
    if not specOn and not RC.reconTdActive then RC.statsOnly = true end
    local mine = type(RC.statsCache) == "table"
        and RC.statsCache[tonumber(RC.id) or 0] or nil
    if type(mine) == "table" then
        RC.live = grndStatsCopy(mine)
    elseif not specOn then
        RC.live = {}
    end
    if wasShown or specOn then
        local pid = tonumber(id) or tonumber(RC.id) or 0
        local pnick = ""
        if id and tonumber(id) ~= tonumber(RC.id) then
            if type(sampGetPlayerNickname) == "function" then
                local okn, nm = pcall(sampGetPlayerNickname, id)
                if okn and type(nm) == "string" then pnick = nm end
            end
            if pnick == "" and nick and nick ~= "" then pnick = tostring(nick) end
        else
            pnick = tostring(RC.nick or "")
        end
        RC.statsPop = { id = pid, nick = pnick, at = os.clock(), frontPending = true }
    end
    if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    return true
end
