        RC.live = RC.live or {}
        for k, v in pairs(pack) do RC.live[k] = v end
        if type(RC.statsView) == "table" then
            local reqAgo = os.clock()
                - math.max(ST.reqAt or -999, ST.manualAt or -999)
            if reqAgo < 20 then RC.statsView.at = os.clock() end
        end
        if type(RC.statsPop) == "table" then
            local pid = tonumber(ST.targetId or ST.lastTarget or 0)
            if pid == tonumber(RC.statsPop.id) then RC.statsPop.at = os.clock() end
        end
        local cid = pid
        if cid and cid > 0 then
            RC.statsCache = RC.statsCache or {}
            RC.statsCache[cid] = grndStatsCopy(RC.live)
        end
        return true
    end
    local function stIngest(fullText, source)
        fullText = grndToUtf(tostring(fullText or ""))
        local u = stLower(fullText)
        if not ST.waiting and not stLooksStats(u) then return false end
        ST.awaitHave = true
        local lines = {}
        for seg in (fullText .. "\n"):gmatch("(.-)\n") do
            local s = stTrim(stNorm(seg))
            if s ~= "" then
                local ls = stLower(s)
                if ls:find("статистик", 1, true) or ls:find("stats", 1, true) then
                    local nick, idn = s:match("(%S+)%[%s*(%d+)%s*%]")
                    if idn then ST.targetId = tonumber(idn) end
                    if nick then ST.targetNick = stTrim(nick) end
                end
                local label, value = stSplitLine(s)
                if label and value then
                    lines[#lines + 1] = { label = label, value = value, key = stFieldFor(label) }
                end
            end
        end
        if #lines == 0 then return true end
        do
            local buf = ST.fields
            if ST.src == "wh" then
                if type(ST.whFields) ~= "table" then ST.whFields = {} end
                buf = ST.whFields
            end
            for i = 1, #lines do
                local ln = lines[i]
                if ln.key then buf[ln.key] = ln.value end
            end
        end
        ST.lastIngestAt = os.clock()
        ST.statsAt = os.date("%H:%M:%S")
        stPushToRecon()
        ST.doneKey = grndStSessionKey(ST.targetId or ST.lastTarget or 0)
        return true
    end
    local function stSpecActive()
        local GS = _G.GRND_SPEC
        if GS and GS.active then return true end
        for _, name in ipairs({ "sampIsPlayerSpectating", "isPlayerSpectating" }) do
            local f = _G[name]
            if type(f) == "function" then
                local ok, r = pcall(f)
                if ok and r == true then return true end
            end
        end
        local RC = _G.GRND_RC
        if type(RC) == "table" and RC.show and RC.id
            and (not RC.statsOnly or RC.reconTdActive) then return true end
        return false
    end
    local MANUAL_SHOW, MANUAL_HOLD = 15, 6
    local function stIsManual()
        return os.clock() - (ST.manualAt or -999) < MANUAL_SHOW
    end
    _G.grndStatsIsManual = stIsManual
    local function stOurs()
        if ST.ownPending then return true end
        if ST.waiting and os.clock() - (ST.waitAt or -999) <= 15 then return true end
        return os.clock() - (ST.reqAt or -999) <= 15
    end
    local AWAIT_MAX = 6
    local function stOursAwaiting()
        if ST.ownPending then return true end
        return ST.awaitAt ~= nil and not ST.awaitHave
            and os.clock() - ST.awaitAt <= AWAIT_MAX
    end
    local PAGE_GAP = 3.5
    local function stTargetIn(full)
        local tid = tostring(ST.targetId or "")
        if tid == "" then return false end
        return tostring(full or ""):find("[" .. tid .. "]", 1, true) ~= nil
    end
    local function stOurPage(full)
        if not ST.waiting then return false end
        local last = ST.lastIngestAt or 0
        if last <= 0 or os.clock() - last > PAGE_GAP then return false end
        return stTargetIn(full)
    end
    local function stOursIngest(full)
        if not stOurs() then return false end
        if stOursAwaiting() or stOurPage(full) then return true end
        return ST.waiting and stTargetIn(full)
    end
    _G.grndStatsShouldHide = function(title, text)
        local full = ("%s\n%s"):format(tostring(title or ""), tostring(text or ""))
        local looks = stLooksStats(stLower(grndToUtf(full)))
        if not looks then return false end
        if stIsManual() then return false end
        if stSpecActive() then return stOursAwaiting() or stOurPage(full) end
        return stOursAwaiting() or stOurPage(full)
    end
    function grndSkipZZMatch(title, text)
        local t = grndLowerUtf(grndToUtf(tostring(title or "")))
        t = t:gsub("^%s+", ""):gsub("%s+$", "")
        if t == "зеленая зона" or t == "зелёная зона" then return true end
        local b = grndLowerUtf(grndToUtf(tostring(text or "")))
        b = b:gsub("{%x%x%x%x%x%x}", "")
        if b:find("в этом месте запрещено", 1, true) and b:find("стрелять", 1, true) then
            return true
        end
        if b:find("в данном месте", 1, true) and b:find("запрещено", 1, true) then
            return true
        end
        return b:find("вы находитесь в зел", 1, true) ~= nil
    end
    GRND_SKIPZZ.tdIds = GRND_SKIPZZ.tdIds or {}
    GRND_SKIPZZ.tdLastId, GRND_SKIPZZ.tdLastAt = nil, 0
    function grndSkipZZTextDraw(id, text)
        if not (GRND_SKIPZZ and GRND_SKIPZZ.on) then return false end
        local ids = GRND_SKIPZZ.tdIds
        local hasText = type(text) == "string" and text ~= ""
        if hasText and grndSkipZZMatch(text, text) then
            ids[id] = true
            GRND_SKIPZZ.tdLastId, GRND_SKIPZZ.tdLastAt = id, os.clock()
            return true
        end
        if ids[id] then
            if hasText then ids[id] = nil; return false end
            return true
        end
        local lastId = GRND_SKIPZZ.tdLastId
        if lastId and (os.clock() - GRND_SKIPZZ.tdLastAt) <= 1.0
            and math.abs(id - lastId) <= 10 then
            ids[id] = true
            return true
        end
        return false
    end
    function grndSkipZZForget(id)
        if GRND_SKIPZZ and GRND_SKIPZZ.tdIds then GRND_SKIPZZ.tdIds[id] = nil end
    end
    _G.grndStatsOnDialog = function(id, style, title, b1, b2, text)
        local full = ("%s\n%s"):format(tostring(title or ""), tostring(text or ""))
        local looks = stLooksStats(stLower(grndToUtf(full)))
        local fresh = ST.waiting and (os.clock() - ST.waitAt) <= 6
        if looks then
            ST.dlgSeen = (ST.dlgSeen or 0) + 1
            ST.lastDlgTitle = tostring(title or "?")
            if _G.grndStatsIsManual and _G.grndStatsIsManual() then
                ST.manualDialog = (ST.manualDialog or 0) + 1
                return nil
            end
            if not stOursIngest(full) then return nil end
            local hideNow = _G.grndStatsShouldHide(title, text)
            local okI, errI = pcall(stIngest, full, id)
            if not okI then ST.lastIngestErr = tostring(errI) end
            if hideNow then
                ST.dlgHidden = (ST.dlgHidden or 0) + 1
                return true
            end
        end
        return nil
    end
    _G.grndStatsOnSendChat = function(msg)
        local m = stLower(stTrim(tostring(msg or "")))
        if not (m:match("^/stats%s") or m == "/stats") then return nil end
        local now = os.clock()
        local ours = ST.ownPending
            and m == ("/stats " .. tostring(ST.ownId or ""))
            and now - (ST.ownSentAt or -999) <= 1.0
        if not ours then
            ST.ownPending = false
            ST.awaitAt, ST.awaitHave = nil, true
            ST.src = "chat"
            ST.manualAt = now
            ST.manualHold = true
            ST.manualDialog = 0
            ST.waiting = false
            ST.targetNick = ""
            return nil
        end
        ST.ownPending = false
        ST.manualAt = -999
        ST.fields = {}
        ST.lastIngestAt = 0
        ST.waiting = true
        ST.waitAt = now
        ST.targetId = tonumber(tostring(msg):match("^/stats%s+(%d+)"))
        ST.targetNick = ""
        return nil
    end
    _G.grndStatsOnTextDraw = function(text)
        if stIsManual() then return end
        local full = grndToUtf(tostring(text or ""))
        if not stOursIngest(full) then return end
        if type(text) == "string" and text ~= "" then
            stIngest(text, "textdraw")
        end
    end
    function grndStSessionKey(id)
        local GS = _G.GRND_SPEC
        local sess = (GS and GS.active and GS.confirmT) or nil
        return tostring(sess or "none") .. ":" .. tostring(id or 0)
    end
    local function stRequest(id, src)
        if type(sampSendChat) ~= "function" then return false end
        ST.ownSentAt = os.clock()
        ST.ownPending, ST.ownId = true, tonumber(id)
        ST.awaitAt, ST.awaitHave = os.clock(), false
        ST.src = src or "auto"
        ST.reqId = tonumber(id)
        if ST.src == "wh" then
            ST.whFields = {}
        else
            ST.manualAt = -999
            ST.manualHold = false
            ST.fields = {}
            ST.lastIngestAt = 0
            ST.reqAt = os.clock()
            ST.lastTarget = tonumber(id) or 0
        end
        pcall(sampSendChat, "/stats " .. tostring(id))
        ST.waiting, ST.waitAt, ST.targetId = true, os.clock(), tonumber(id)
        return true
    end
    _G.grndStatsRequest = stRequest
    _G.grndStatsBusy = function()
        return stOursAwaiting() and true or false
    end
    _G.grndStatsTick = function()
        local now = os.clock()
        if not ST.cmdReg and type(sampRegisterChatCommand) == "function" then
            ST.cmdReg = true
        end
        if ST.ownPending and now - (ST.ownSentAt or -999) > 1.5 then
            ST.ownPending = false
        end
        local manualHold = (os.clock() - (ST.manualAt or -999)) < MANUAL_HOLD
        if ST.manualHold and not manualHold then
            ST.manualHold = false
            ST.pendingOpen = true
        end
        if ST.waiting then
            local quiet = (ST.lastIngestAt or 0) > 0 and now - ST.lastIngestAt > 4
            local expired = now - ST.waitAt > 15
            if quiet or expired then
                ST.waiting = false
            end
        end
        local RC = _G.GRND_RC
        local show = (type(RC) == "table") and (RC.show and true or false) or false
        local id = (type(RC) == "table") and tonumber(RC.id) or nil
        local opened = show and not ST.wasShow
        if opened then ST.pendingOpen = true end
        if show and id and id > 0
            and not manualHold
            and now - (ST.reqAt or -999) > 5
            and grndIsSpawnedSafe() and not grndIsTyping() then
            local key = grndStSessionKey(id)
            if ST.curKey ~= key then
                ST.curKey, ST.tries, ST.doneKey = key, 0, nil
            end
            local retry = ST.tries == 1 and not ST.waiting
                and not next(ST.fields)
            if ST.doneKey ~= key
                and (ST.pendingOpen or id ~= ST.lastTarget or retry) then
                if stRequest(id) then
                    ST.pendingOpen = false
                    ST.tries = (ST.tries or 0) + 1
                    if ST.tries >= 2 then ST.doneKey = key end
                end
            end
        end
        if show and id then ST.lastTarget = id end
        ST.wasShow = show
        if next(ST.fields) and type(RC) == "table" then
            stPushToRecon()
        end
    end
end
GRND_KL = _G.GRND_KL or {}
function grndKlEmptyLabel(KL, visibleRows)
    if tonumber(visibleRows) == 0 and not (KL and KL.hasKillData) then
        return "пока нет убийств"
    end
    return nil
end
