    local function klUtf(s)
        if type(s) ~= "string" or s == "" then return s end
        local ok, r = pcall(grndToUtf, s)
        if ok and type(r) == "string" then return r end
        return s
    end
    local function klFfi()
        if KL.ffiTried then return KL.ffiStr ~= nil end
        KL.ffiTried = true
        local ok, ffi = pcall(require, "ffi")
        if ok and ffi then
            KL.ffi = ffi
            local ok2, fn = pcall(function()
                return function(a, n)
                    return ffi.string(ffi.cast("const char*", a), n)
                end
            end)
            if ok2 and type(fn) == "function" then KL.ffiStr = fn end
        end
        return KL.ffiStr ~= nil
    end
    local function klClip(s)
        if type(s) ~= "string" then return "" end
        local cut = s:find("%z")
        if cut then s = s:sub(1, cut - 1) end
        if #s > 24 then s = s:sub(1, 24) end
        return s
    end
    local function klNickSafe(a)
        local s
        if type(grndMemRdStr) == "function" then
            local ok, r = pcall(grndMemRdStr, a, 25)
            if ok and type(r) == "string" then s = r end
        end
        return klClip(s or "")
    end
    local function klNickFast(a)
        if klFfi() then
            local ok, r = pcall(KL.ffiStr, a, 25)
            if ok and type(r) == "string" then return klClip(r) end
        end
        return klNickSafe(a)
    end
    local function klEntryAt(p, i)
        local e = p + 4 + (i - 1) * 59
        local k = klNickFast(e)
        local v = klNickFast(e + 25)
        local kc = grndMemRd32(e + 50) or 0
        local vc = grndMemRd32(e + 54) or 0
        local ty = grndMemRd8(e + 58) or 0
        return { k = k, v = v, kc = kc, vc = vc, t = ty }
    end
    local function klNorm(v)
        v = tonumber(v)
        if not v then return nil end
        v = math.floor(v)
        if v < 0 then v = v + 0x100000000 end
        return v
    end
    local function klPtrPlausible(p)
        p = klNorm(p)
        if not p then return false end
        if p < 0x10000 or p > 0xFFFF0000 then return false end
        if p % 4 ~= 0 then return false end
        return true
    end
    local klQueryTried, klQueryMemory = false, nil
    local klReadableProtect = { [0x02] = true, [0x04] = true, [0x08] = true,
                                [0x20] = true, [0x40] = true, [0x80] = true }
    local function klReadable(a, n)
        a, n = klNorm(a), tonumber(n)
        if not a or not n or n <= 0 or a + n > 0x100000000 then return false end
        if not klQueryTried then
            klQueryTried = true
            if klFfi() and type(grndMakeVQ) == "function" then
                local ok, query = pcall(grndMakeVQ, KL.ffi)
                if ok and type(query) == "function" then klQueryMemory = query end
            end
        end
        local query = klQueryMemory
        if not query then return false end
        local finish, cursor = a + n, a
        while cursor < finish do
            local ok, base, _, size, state, protect = pcall(query, cursor)
            if not ok or not base or not size or size <= 0 or state ~= 0x1000 then return false end
            protect = tonumber(protect) or 0
            local access = protect % 0x100
            if math.floor(protect / 0x100) % 2 ~= 0 or not klReadableProtect[access] then return false end
            local nextRegion = base + size
            if nextRegion <= cursor then return false end
            cursor = math.min(nextRegion, finish)
        end
        return true
    end
    local function klRawBytes(a, n)
        if klFfi() then
            local ok, s = pcall(KL.ffiStr, a, n)
            if ok and type(s) == "string" and #s == n then return s end
        end
        local t = {}
        for i = 0, n - 1 do
            local b = grndMemRd8(a + i)
            if b == nil then return nil end
            t[#t + 1] = string.char(b)
        end
        return table.concat(t)
    end
    local function klNickBytesSane(s)
        if type(s) ~= "string" or #s ~= 25 then return false end
        for i = 1, 25 do
            local b = s:byte(i)
            if b ~= 0 and b < 0x20 then return false end
        end
        return true
    end
    local function klPtrOk(p)
        p = klNorm(p)
        if not klPtrPlausible(p) then return false, 0, "адрес" end
        if not klReadable(p, 0x14B) then return false, 0, "область памяти не читается" end
        local en = grndMemRd32(p)
        if en == nil then return false, 0, "не читается" end
        en = klNorm(en)
        if en ~= 0 and en ~= 1 then return false, 0, "iEnabled=" .. tostring(en) end
        for i = 1, 5 do
            local e = p + 4 + (i - 1) * 59
            if not (klNickBytesSane(klRawBytes(e, 25)) and klNickBytesSane(klRawBytes(e + 25, 25))) then
                return false, 0, "записи"
            end
        end
        local score = 0
        local pdev  = klNorm(grndMemRd32(p + 0x147) or 0)
        local pfont = klNorm(grndMemRd32(p + 0x137) or 0)
        local posx  = grndMemRd32(p + 0x12F)
        local posy  = grndMemRd32(p + 0x133)
        local nickw = grndMemRd32(p + 0x12B)
        if pdev  >= 0x10000 and pdev  <= 0xFFFF0000 and pdev  % 4 == 0 then score = score + 3 end
        if pfont >= 0x10000 and pfont <= 0xFFFF0000 and pfont % 4 == 0 then score = score + 2 end
        if type(posx) == "number" and posx >= -4000 and posx <= 4000
            and type(posy) == "number" and posy >= -4000 and posy <= 4000 then score = score + 2 end
        if type(nickw) == "number" and nickw >= 0 and nickw <= 4096 then score = score + 1 end
        for i = 1, 5 do
            local e = p + 4 + (i - 1) * 59
            if klNickFast(e) ~= "" or klNickFast(e + 25) ~= "" then
                score = score + 2
                break
            end
        end
        return true, score, nil
    end
    local function klPeInfo(h)
        local pe = klNorm(grndMemRd32(h + 0x3C) or 0)
        if pe == 0 or pe > 0x1000 then return nil end
        if klNorm(grndMemRd32(h + pe) or 0) ~= 0x00004550 then return nil end
        local ep   = klNorm(grndMemRd32(h + pe + 0x28) or 0)
        local size = klNorm(grndMemRd32(h + pe + 0x50) or 0)
        return ep, size
    end
    local function klProbeRecord(off, src, p)
        local rec = { off = off, p = p, src = src }
        if not p or p == 0 then
            rec.why = "нуль"
            return rec
        end
        local ok, score, why = klPtrOk(p)
        rec.ok, rec.score, rec.why = ok, score, why
        if ok then rec.en = klNorm(grndMemRd32(p)) end
        return rec
    end
    local function klSections(h)
        local out = {}
        local pe = klNorm(grndMemRd32(h + 0x3C) or 0)
        if pe == 0 or pe > 0x1000 then return out end
        if klNorm(grndMemRd32(h + pe) or 0) ~= 0x00004550 then return out end
        local nsec    = klNorm(grndMemRd32(h + pe + 0x06) or 0) or 0
        local optSize = klNorm(grndMemRd32(h + pe + 0x14) or 0) or 0
        if nsec <= 0 or nsec > 96 or optSize > 0x400 then return out end
        local st = h + pe + 0x18 + optSize
        for i = 0, nsec - 1 do
            local b = st + i * 40
            local name = (klRawBytes(b, 8) or ""):gsub("%z.*$", "")
            local vsize = klNorm(grndMemRd32(b + 0x08) or 0) or 0
            local va    = klNorm(grndMemRd32(b + 0x0C) or 0) or 0
            local rsize = klNorm(grndMemRd32(b + 0x10) or 0) or 0
            local chars = klNorm(grndMemRd32(b + 0x24) or 0) or 0
            local sz = math.min(vsize > 0 and vsize or rsize,
                                rsize > 0 and rsize or vsize)
            out[#out + 1] = {
                name = name, va = va, size = sz,
                writable = (chars >= 0x80000000),
                exec = (math.floor(chars / 0x20000000) % 2 == 1),
            }
        end
        return out
    end
    function klScanCandidates(limit, maxBytes, timeLimit)
        local out = {}
        local startedAt = os.clock()
        local h = KL.base
        if not h then
            local ok, mh = pcall(getModuleHandle, "samp.dll")
            if ok and type(mh) == "number" and mh ~= 0 then h = klNorm(mh); KL.base = h end
        end
        if not h then KL.scanWhy = "нет samp.dll" return out end
        local secs = klSections(h)
        KL.secs = secs
        local order = {}
        for _, s in ipairs(secs) do
            if s.size > 0 and s.size <= 4 * 1024 * 1024 and not (s.exec and not s.writable) then
                order[#order + 1] = s
            end
        end
        table.sort(order, function(a, b)
            if a.writable ~= b.writable then return a.writable end
            return a.size > b.size
        end)
        local budget = limit or 4096
        local checked, scanned = 0, 0
        for _, s in ipairs(order) do
            local bytes
            if klFfi() then
                local okr, str = pcall(KL.ffiStr, h + s.va, s.size)
                if okr and type(str) == "string" and #str == s.size then bytes = str end
            end
            local n = bytes and #bytes or math.min(s.size, 262144)
            if maxBytes and n > maxBytes then n = maxBytes end
            local i = 0
            while i + 4 <= n do
                local p
                if bytes then
                    local b1, b2, b3, b4 = bytes:byte(i + 1, i + 4)
                    p = b1 + b2 * 256 + b3 * 65536 + b4 * 16777216
                else
                    p = klNorm(grndMemRd32(h + s.va + i) or -1) or -1
                end
                if klPtrPlausible(p) and klReadable(p, 0x14B) then
                    local en = klNorm(grndMemRd32(p) or -1)
                    if en == 0 or en == 1 then
                        checked = checked + 1
                        local okc, score = klPtrOk(p)
                        if okc then
                            out[#out + 1] = { p = p, slot = h + s.va + i,
                                              score = score or 0, sec = s.name }
                        end
                        if checked >= budget then break end
                    end
                end
                i = i + 4
            end
            scanned = scanned + 1
            if checked >= budget then break end
            if timeLimit and (os.clock() - startedAt) >= timeLimit then
                KL.scanStat = "перебор прерван по времени — продолжаю позже"
                break
            end
        end
        KL.scanStat = ("секций %d, проверено кандидатов %d, подошло %d, бюджет %d")
            :format(scanned, checked, #out, budget)
        table.sort(out, function(a, b) return a.score > b.score end)
        return out
    end
    function grndKlScanNow()
        grndKlSay("ищу структуру килл-листа перебором памяти…")
        local t0 = os.clock()
        local cands = klScanCandidates(8192)
        local ms = math.floor((os.clock() - t0) * 1000)
        grndKlSay((KL.scanStat or "") .. (", время " .. ms .. " мс"))
        if #cands == 0 then
            grndKlSay("кандидатов нет — структуры в памяти samp.dll ещё нет (или клиент другой)")
            return false
        end
        for i = 1, math.min(#cands, 5) do
            local c = cands[i]
            grndKlSay(("  %d) %s  (переменная samp.dll+0x%X, секция %s, оценка %d)")
                :format(i, grndKlHx(c.p), c.slot - (KL.base or 0), tostring(c.sec), c.score))
        end
        local best = cands[1]
        KL.ptr, KL.slot, KL.off = best.p, best.slot, best.slot - (KL.base or 0)
        KL.src, KL.score = "поиск", best.score
        KL.origEn = klNorm(grndMemRd32(best.p))
        KL.memFail, KL.badReads, KL.badValid = 0, 0, 0
        grndKlSay(("структура принята: %s (iEnabled=%s)")
            :format(grndKlHx(best.p), tostring(KL.origEn)))
        return true
    end
    function grndKlResolve()
        if KL.ptr then return true end
        local ok, h = pcall(getModuleHandle, "samp.dll")
        if not ok or type(h) ~= "number" or h == 0 then return false end
        h = klNorm(h)
        KL.base = h
        KL.probe = {}
        local cands = {}
        local rank = { ["api"] = 3, ["версия"] = 2, ["офсет"] = 1, ["поиск"] = 1 }
        local function add(p, off, src, score, slot)
            cands[#cands + 1] = { p = p, off = off, src = src, score = score or 0, slot = slot }
        end
        local ep, imgsize = klPeInfo(h)
        KL.entry, KL.imgsize = ep, imgsize
        local vi = ep and GRND_KL_VERS[ep]
        if vi then
            KL.ver = vi.ver
            local slot = h + vi.off
            local rec = klProbeRecord(vi.off, "версия", klNorm(grndMemRd32(slot)))
            KL.probe[#KL.probe + 1] = rec
            if rec.ok then add(rec.p, vi.off, "версия", rec.score, slot) end
        end
        if type(sampGetKillInfoPtr) == "function" then
            local ok2, p = pcall(sampGetKillInfoPtr)
            if ok2 and type(p) == "number" then
                local rec = klProbeRecord(0, "api", klNorm(p))
                KL.apiOk = rec.ok and true or false
                KL.probe[#KL.probe + 1] = rec
                if rec.ok then add(rec.p, 0, "api", rec.score, nil) end
            end
        end
        for _, off in ipairs(GRND_KL_OFFS) do
            if not (vi and vi.off == off) then
                local slot = h + off
                local rec = klProbeRecord(off, "офсет", klNorm(grndMemRd32(slot)))
                KL.probe[#KL.probe + 1] = rec
                if rec.ok then add(rec.p, off, "офсет", rec.score, slot) end
            end
        end
        do
            local now = os.clock()
            local auto = (KL.scanTries or 0) < 3
            if ((now - (KL.scanAt or 0)) >= 6.0) and auto then
                KL.scanAt = now
                KL.scanTries = (KL.scanTries or 0) + 1
                local okS, found = pcall(klScanCandidates, 1024, 524288, 0.04)
                if okS and found and #found > 0 then
                    KL.scanTop = found
                    for i = 1, math.min(#found, 3) do
                        local c = found[i]
                        if c.score >= 4 then
                            add(c.p, c.slot - h, "поиск", c.score, c.slot)
                        end
                    end
                    pcall(grndTrace, "killlist", ("перебор памяти: подходящих структур %d (%s)")
                        :format(#found, tostring(KL.scanStat)))
                end
            end
        end
        local best
        for _, c in ipairs(cands) do
            if (c.src == "офсет" or c.src == "поиск") and c.score < 4 then c = nil end
            if c then
                if not best then
                    best = c
                else
                    local rb, rc = rank[best.src] or 0, rank[c.src] or 0
                    if rc > rb or (rc == rb and c.score > best.score) then best = c end
                end
            end
        end
        if not best then return false end
        KL.ptr    = best.p
        KL.off    = best.off
        KL.src    = best.src
        KL.score  = best.score or 0
        KL.slot   = best.slot or ((best.off and best.off > 0) and (h + best.off) or nil)
        KL.origEn = klNorm(grndMemRd32(KL.ptr))
        KL.err    = nil
        KL.memFail, KL.badReads, KL.badValid = 0, 0, 0
        if KL.src == "поиск" then
            pcall(grndTrace, "killlist", ("структура найдена перебором памяти: %s (samp.dll+0x%X, оценка %d)")
                :format(grndKlHx(KL.ptr), KL.off or 0, KL.score or 0))
        end
        return true
    end
    local function klForgetPtr()
        KL.ptr, KL.slot, KL.off, KL.src = nil, nil, nil, nil
        KL.origEn, KL.score = nil, 0
        KL.memFail, KL.badReads, KL.badValid = 0, 0, 0
        if KL.heapDone and (KL.heapAt or 0) > 0 then
            KL.heapDone, KL.heapAt, KL.heapBytes = false, nil, nil
            KL.heapStat = "указатель потерян — ищем заново"
        end
    end
    function grndKlNativeShow(show)
        local KL2 = GRND_KL
        local ptr = KL2.ptr or KL2.apiPtr
        if not ptr then return false end
        local target = show and 1 or 0
        local ok = pcall(grndMemWr32, ptr, target)
        pcall(grndMemWr8, ptr, target)
        local rb = klNorm(grndMemRd32(ptr))
        KL2.nativeOff = (target == 0)
        if not (ok and rb == target) then return false end
        KL2.badReads = 0
        return true
    end
    local function klConnected(id)
        if type(id) ~= "number" then return false end
        if type(sampIsPlayerConnected) ~= "function" then return false end
        local ok, conn = pcall(sampIsPlayerConnected, id)
        return (ok and conn) and true or false
    end
    local function klNickOf(id)
        if type(sampGetPlayerNickname) ~= "function" then return nil end
        if not klConnected(id) then return nil end
        local ok, n = pcall(sampGetPlayerNickname, id)
        if ok and type(n) == "string" and n ~= "" then return n end
        return nil
    end
    local function klScore(id)
        if type(id) ~= "number" then return nil end
        if type(sampGetPlayerScore) ~= "function" then return nil end
        if not klConnected(id) then return nil end
        local ok, s = pcall(sampGetPlayerScore, id)
        if ok and type(s) == "number" then return s end
        return nil
    end
    local function klSampReady()
        if type(isSampAvailable) ~= "function" then return true end
        local ok, avail = pcall(isSampAvailable)
        return (ok and avail) and true or false
    end
    local function klScoreMapRefresh()
        local now = os.clock()
        local last = tonumber(KL.scoreMapAt) or 0
        if last ~= 0 and (now - last) < 3.0 then return end
        KL.scoreMapAt = now
        local map = {}
        if type(sampIsPlayerConnected) ~= "function" or not klSampReady() then
            KL.scoreMap = map
            return
        end
        local maxId = 999
        if type(sampGetMaxPlayerId) == "function" then
            local ok, m = pcall(sampGetMaxPlayerId)
            if ok and type(m) == "number" and m > 0 and m < 1000 then maxId = m end
        end
        for id = 0, maxId do
            local n = klNickOf(id)
            if n then map[n] = id end
        end
        KL.scoreMap = map
    end
    local function klFreezeIds(rec)
        pcall(klScoreMapRefresh)
        local kidNow = KL.scoreMap[rec.k]
        local vidNow = KL.scoreMap[rec.v]
        if kidNow ~= nil then rec.kid = kidNow end
        if vidNow ~= nil then rec.vid = vidNow end
        if rec.kidF == nil and kidNow ~= nil then rec.kidF = kidNow end
        if rec.vidF == nil and vidNow ~= nil then rec.vidF = vidNow end
        if rec.ks == nil and rec.kidF ~= nil then rec.ks = klScore(rec.kidF) end
        if rec.vs == nil and rec.vidF ~= nil then rec.vs = klScore(rec.vidF) end
    end
    local klResolveIds = klFreezeIds
    local function klScoreRefreshHist()
        for n = #KL.hist, math.max(1, #KL.hist - 19), -1 do
            local r = KL.hist[n]
            if r then pcall(klFreezeIds, r) end
        end
    end
    local function klPush(e, src)
        local now = os.clock()
        src = src or "mem"
        for n = #KL.hist, 1, -1 do
            local r = KL.hist[n]
            if (now - (r.t or 0)) > 3.0 then break end
            if r.k == e.k and r.v == e.v and r.src ~= src then
                if (not r.wnameu) and e.wnameu then r.wnameu = e.wnameu end
                if (not r.typ or r.typ == 0) and e.t and e.t ~= 0 then r.typ = e.t end
                if src == "mem" or src == "rpc" then
                    if (not r.kc or r.kc == 0) and e.kc and e.kc ~= 0 then r.kc = e.kc end
                    if (not r.vc or r.vc == 0) and e.vc and e.vc ~= 0 then r.vc = e.vc end
                end
                return false
            end
        end
        local rec = {
            k = e.k, v = e.v,
            ku = klUtf(e.k), vu = klUtf(e.v),
            kc = e.kc, vc = e.vc, typ = e.t,
            wnameu = e.wnameu,
            t = now, time = os.date("%H:%M:%S"),
            kid = nil, vid = nil, ks = nil, vs = nil,
            kidF = nil, vidF = nil,
            src = src,
        }
        pcall(klFreezeIds, rec)
        table.insert(KL.hist, rec)
        while #KL.hist > (KL.maxHist or 60) do table.remove(KL.hist, 1) end
        KL.hasKillData = true
        return true
    end
    function grndKlClear()
        GRND_KL.hist = {}
        GRND_KL.snap = {}
        KL.hasKillData = false
    end
    function grndKlFeedRpc(killerId, killedId, reason)
        if not KL.enabled then return false end
        killerId = tonumber(killerId) or 65535
        killedId = tonumber(killedId) or 65535
        reason = tonumber(reason) or 0
        local function nickOf(id)
            if id == 65535 or id < 0 then return "" end
            if type(sampGetPlayerNickname) ~= "function" then return "" end
            local okc, conn = pcall(sampIsPlayerConnected, id)
            local isMe = false
            if type(sampGetPlayerIdByCharHandle) == "function" then
                local okMe, res, myId = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
                isMe = okMe and res and (tonumber(myId) == id) or false
            end
            if not ((okc and conn) or isMe) then return "" end
            local ok, n = pcall(sampGetPlayerNickname, id)
            if ok and type(n) == "string" then return n end
            return ""
        end
        local function colorOf(id)
            if id == 65535 or id < 0 or type(sampGetPlayerColor) ~= "function" then return 0 end
            local ok, c = pcall(sampGetPlayerColor, id)
            if ok and type(c) == "number" then
                if c < 0 then c = c + 0x100000000 end
                return c % 0x1000000
            end
            return 0
        end
        local k = nickOf(killerId)
        local v = nickOf(killedId)
        if v == "" then return false end
        local e = { k = k, v = v, kc = colorOf(killerId), vc = colorOf(killedId), t = reason }
        local pushed = klPush(e, "rpc")
        if pushed then
            local r = KL.hist[#KL.hist]
            if r then r.kid, r.vid = (killerId ~= 65535) and killerId or nil, killedId end
            KL.rpcAt = os.clock()
            KL.rpcCount = (KL.rpcCount or 0) + 1
        end
        return true
    end
    function grndKlFeedChat(text)
        local clog
        do
            KL.chatLog = KL.chatLog or {}
            clog = KL.chatLog
            while #clog >= 14 do table.remove(clog, 1) end
            clog[#clog + 1] = { t = os.date("%H:%M:%S"), s = tostring(text or ""):sub(1, 96), r = "?" }
        end
        local clogEntry = clog[#clog]
        local function ret(v, tag)
            if clogEntry then clogEntry.r = tag end
            return v
        end
        if not KL.fromChat then return ret(false, "подхват выключен") end
        local s = tostring(text or "")
        s = s:gsub("{%x%x%x%x%x%x}", "")
        s = s:gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then return ret(false, "пустая строка") end
        s = klUtf(s)
        local wname
        do
            local w = s:match("%s*%(([^%)]*)%)%s*$")
            if w then
                w = w:gsub("^%s+", ""):gsub("%s+$", "")
                if w == "" or #w > 24 or w:match("^%d+$") then w = nil end
            end
            if w then wname = klUtf(w) end
        end
        local k, v
        k, v = s:match("^(.-)%s+убил%.?%s+(.-)$")
        if not k then k, v = s:match("^(.-)%s+убила%.?%s+(.-)$") end
        if not k then k, v = s:match("^(.-)%s+killed%s+(.-)$") end
        if not k then k, v = s:match("^(.-)%s+застрелил%.?%s+(.-)$") end
        if not k then return ret(false, "не «Ник убил Ник»") end
        local function nickChars(x)
            local n, i, len = 0, 1, #x
            while i <= len do
                local b = x:byte(i)
                if b >= 0xF0 then i = i + 4
                elseif b >= 0xE0 then i = i + 3
                elseif b >= 0xC0 then i = i + 2
                else i = i + 1 end
                n = n + 1
            end
            return n
        end
        local function clean(x)
            x = tostring(x or "")
            x = x:gsub("%s*%([^%)]*%)%s*$", "")
            x = x:gsub("^%[%d+%]%s*", "")
            x = x:gsub("%s*%[%d+%]%s*$", "")
            x = x:gsub("^%s+", ""):gsub("%s+$", "")
            return x
        end
        k, v = clean(k), clean(v)
        if k == "" or v == "" then return ret(false, "пустые ники") end
        if nickChars(k) > 24 or nickChars(v) > 24 then return ret(false, "ник длиннее 24") end
        local function nickOk(n)
            if n:find("[%c%s]") then return false end
            return n:find("[^%w_%.%-%[%]\128-\255]") == nil
        end
        if not nickOk(k) or not nickOk(v) then
            return ret(false, "ники не по шаблону")
        end
        local vl = v:lower()
        if vl == "вас" or vl == "you" or vl == "его" or vl == "её" then
            return ret(false, "жертва — «вас/you»")
        end
        local pushed = klPush({ k = k, v = v, kc = 0, vc = 0, t = 0, wnameu = wname }, "chat")
        return ret(pushed, pushed and ("распознано: " .. k .. " -> " .. v) or "дубль (уже есть)")
    end
    function grndKlIdsNow()
        pcall(klScoreMapRefresh)
        return KL.scoreMap or {}
    end
    function grndKlFindId(nick)
        nick = tostring(nick or "")
        if nick == "" then return nil end
        local map = KL.scoreMap
        if (not map) or (not next(map)) or (os.clock() - (KL.scoreMapAt or 0)) > 3.0 then
            map = grndKlIdsNow()
        end
        if not map then return nil end
        if map[nick] then return map[nick] end
        local function core(s)
            s = tostring(s or ""):gsub("^%[%d+%]%s*", "")
            if #s > 24 then s = s:sub(1, 24) end
            return s:lower()
        end
        local want = core(nick)
        if want == "" then return nil end
        local hit
        for n, id in pairs(map) do
            if core(n) == want then
                if hit == nil then hit = id end
            end
        end
        return hit
    end
    function grndKlCfgPath()
        if type(this_script_dir) == "function" then
            local okd, sd = pcall(this_script_dir)
            if okd and sd and tostring(sd) ~= "" then
                local pp = tostring(sd)
                while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
                local sep = "\\"
                local okc, cf = pcall(function() return package.config end)
                if okc and type(cf) == "string" and #cf > 0 then sep = cf:sub(1, 1) end
                return pp .. sep .. "grnd_killlist.cfg"
            end
        end
        return "grnd_killlist.cfg"
    end
    function grndKlCfgSave()
        klMigrateAppearance()
        local ok, f = pcall(GRND_CONFIG.open, grndKlCfgPath(), "w")
        if not ok or not f then return false end
        local function w(k, v) f:write(k .. "=" .. tostring(v) .. "\n") end
        w("enabled", KL.enabled and 1 or 0)
        w("rows", math.floor(KL.rows or 6))
        w("scale", string.format("%.2f", KL.scale or 1.0))
        w("styleVersion", KL.styleVersion or 2)
        w("showScore", 0)
        w("alignK", 1)
        w("kMode", 3)
        w("textShadow", 1)
        w("showId", 1)
        w("showWName", KL.showWName and 1 or 0)
        w("showTime", KL.showTime and 1 or 0)
        w("fromChat", 1)
        w("newestTop", 1)
        w("bg", KL.bg and 1 or 0)
        w("bgAlpha", math.floor(KL.bgAlpha or 120))
        w("bgv", 2)
        if KL.x then w("x", math.floor(KL.x)) end
        if KL.y then w("y", math.floor(KL.y)) end
        w("expanded", KL.expanded and 1 or 0)
        pcall(f.close, f)
        KL.cfgSavedAt = os.clock()
        KL.cfgDirty = false
        return true
    end
    function grndKlCfgLoad()
        local ok, f = pcall(GRND_CONFIG.open, grndKlCfgPath(), "r")
        KL.cfgLoaded = true
        if not ok or not f then
            klMigrateAppearance()
            return false
        end
        local bgvSeen = false
        for line in f:lines() do
            local k, v = tostring(line):match("^%s*([%w_]+)%s*=%s*(.-)%s*$")
            if k then
                local num = tonumber(v)
                if k == "enabled" then KL.enabled = (v == "1")
                elseif k == "rows" and num then KL.rows = math.max(1, math.min(24, math.floor(num)))
                elseif k == "scale" and num then
                    KL.scale = math.max(0.25, math.min(2.5, num))
                elseif k == "styleVersion" and num then KL.styleVersion = num
                elseif k == "showScore" then KL.showScore = (v == "1")
                elseif k == "alignK" then
                    KL.alignK = (v == "1")
                elseif k == "kMode" and num then
                    KL.kMode = num
                elseif k == "textShadow" then KL.textShadow = (v == "1")
                elseif k == "showId" then KL.showId = (v == "1")
                elseif k == "showWName" then KL.showWName = (v == "1")
                elseif k == "showTime" then KL.showTime = (v == "1")
                elseif k == "fromChat" then KL.fromChat = (v == "1")
                elseif k == "newestTop" then KL.newestTop = (v == "1")
                elseif k == "bg" then KL.bg = (v == "1")
                elseif k == "bgv" and num then bgvSeen = true
                elseif k == "bgAlpha" and num then KL.bgAlpha = math.max(0, math.min(255, num))
                elseif k == "x" and num then KL.x = num
                elseif k == "y" and num then KL.y = num
                elseif k == "expanded" then KL.expanded = (v == "1")
                end
            end
        end
        pcall(f.close, f)
        klMigrateAppearance()
        KL.showId, KL.showScore = true, false
        KL.alignK, KL.textShadow = true, true
        KL.fromChat, KL.newestTop = true, true
        if not bgvSeen then
            KL.bg = false
            KL.cfgDirty = true
        end
        KL.bgv = 2
        if (tonumber(KL.kMode) or 0) < 3 then
            KL.kMode = 3
            KL.cfgDirty = true
        end
        return true
    end
