            if n and not isTime then return n end
        end
        local br = aoLvlNum(s:match("%[(%d+)%]"))
        if br then return br end
        for num, after in s:gmatch("(%d+)%s*(%S*)") do
            local isTime = after:find("мин", 1, true)
                or after:find("сек", 1, true)
                or after:find("час", 1, true)
                or after:sub(1, 1) == ":"
            local n = aoLvlNum(num)
            if n and not isTime then return n end
        end
        return nil
    end
    local function aoFindIdByNick(nick)
        if type(nick) ~= "string" or nick == "" then return nil end
        if type(sampGetPlayerIdByNickname) == "function" then
            local ok, id = pcall(sampGetPlayerIdByNickname, nick)
            if ok and type(id) == "number" and id >= 0 and id ~= 65535 then return id end
        end
        if type(sampGetMaxPlayerId) == "function"
           and type(sampIsPlayerConnected) == "function"
           and type(sampGetPlayerNickname) == "function" then
            local okm, maxid = pcall(sampGetMaxPlayerId)
            maxid = (okm and tonumber(maxid)) or 1000
            for i = 0, maxid do
                local okc, on = pcall(sampIsPlayerConnected, i)
                if okc and on then
                    local okn, n = pcall(sampGetPlayerNickname, i)
                    if okn and n == nick then return i end
                end
            end
        end
        return nil
    end
    local function aoParseLine(s)
        s=aoStrip(s)
        -- Админский ник может быть как First_Last, так и одним словом.
        -- Раньше обязательное подчёркивание выкидывало вторые ники из /admins.
        local nickPat="([A-Za-z][A-Za-z0-9_]*[A-Za-z0-9])"
        local nick,id,tail=s:match("^"..nickPat.."%s*%[(%d+)%]%s*(.*)$")
        if not nick and AO.gotHeader then
            nick,tail=s:match("^"..nickPat.."%s+(.+)$")
        end
        if not nick then return nil end
        local rest=(tail or ""):lower()
        for _,word in ipairs({"Главный администратор", "Заместитель", "Администратор",
            "главный администратор", "заместитель", "администратор",
            "Администрация", "администрация", "Админ", "админ",
            "Адм", "адм", "Модер", "модер", "Модератор", "модератор",
            "Уровень", "уровень", "УРОВЕНЬ", "Уровня", "уровня", "УРОВНЯ",
            "Уровней", "уровней", "Уровне", "уровне",
            "Уров", "уров", "Лвл", "лвл", "ЛВЛ",
            "Ур", "ур", "УР",
            "-й", "й",
            "АФК", "Афк", "афк", "Минут", "минут", "мин", "сек", "час",
            "онлайн", "в сети", "level", "lvl", "Lvl", "LVL", "afk", "online"}) do
            rest=rest:gsub(word, "")
        end
        if rest:gsub("[%s%p%d]", "")~="" then return nil end
        local lvl=aoFindLevel(tail or "")
        local afk=aoHasAfk(tail or "")
        local afkSec=aoParseAfkSec(tail or "")
        local hasAdminRole = false
        for _,word in ipairs({"Администратор", "администратор", "Админ", "админ",
            "Модератор", "модератор", "Модер", "модер", "Заместитель", "заместитель",
            "Главный", "главный", "Administration", "Administrator", "Admin", "Moderator"}) do
            if (tail or ""):find(word, 1, true) then hasAdminRole = true; break end
        end
        if not lvl and not (AO.gotHeader and (afk or id or hasAdminRole)) then return nil end
        return {nick=nick,id=tonumber(id) or aoFindIdByNick(nick),lvl=lvl,
            afk=afk or afkSec~=nil,afkSec=afkSec}
    end
    local function aoCommit()
        AO.levelProbe = false
        AO.lateCollect = false
        if not AO.gotLine and not AO.gotHeader then
            AO.collect = {}
            return
        end
        local list = grndAoSortedCopy(AO.collect or {})
        AO.list = list
        AO.parsedAt = os.clock()
        AO.collect = {}
        AO.gotHeader = false
        AO.gotLine = false
    end
    local function aoPush(e)
        if not e or not e.nick then return end
        AO.collect = AO.collect or {}
        for _, p in ipairs(AO.collect) do
            if p.nick == e.nick then
                if e.id and not p.id then p.id = e.id end
                if e.lvl and not p.lvl then p.lvl = e.lvl end
                if e.afk then p.afk = true end
                if e.afkSec then p.afkSec = e.afkSec end
                return
            end
        end
        AO.collect[#AO.collect + 1] = e
        AO.gotLine = true
        AO.lastLineAt = os.clock()
        AO.waitUntil = os.clock() + 2.2
        if not AO.waiting then
            AO.lateCollect = true
            AO.adminReplyUntil = AO.waitUntil + 4.0
        end
    end
    function grndAoOnChat(color, text)
        local now=os.clock()
        local function aoHideLine()
            if _G.GRND_LOG and type(_G.GRND_LOG.muteText) == "function" then
                pcall(_G.GRND_LOG.muteText, text, 3)
            end
            return true
        end
        if AO.replyTailUntil and now>AO.replyTailUntil then AO.replyTailUntil=nil end
        if AO.adminReplyUntil and now>AO.adminReplyUntil then AO.adminReplyUntil=nil end
        if not AO.waiting and not AO.replyTailUntil and not AO.adminReplyUntil then return false end
        local s=aoStrip(text)
        aoRememberAdminMinutes(s)
        if AO.replyTailUntil and aoIsOnlineReply(s) then
            AO.replyTailUntil=nil
            return aoHideLine()
        end
        if not AO.waiting then
            if not AO.adminReplyUntil then return false end
            if s ~= "" then
                local e = aoParseLine(s)
                if e then aoPush(e) end
                if aoIsHeader(s) then AO.gotHeader = true end
                if aoIsFooter(s) and (AO.gotHeader or AO.gotLine) then
                    aoCommit()
                    AO.adminReplyUntil = nil
                end
            end
            return false
        end
        if not AO.hide then
            local s = aoStrip(text)
            if s ~= "" then
                local e = aoParseLine(s)
                if e then aoPush(e) end
                if aoIsHeader(s) then AO.gotHeader = true end
                if aoIsFooter(s) then
                    AO.gotHeader = true
                    aoCommit()
                    AO.waiting = false
                end
            end
            return false
        end
        local s = aoStrip(text)
        if s == "" then return false end
        if aoIsOnlineReply(s) then
            AO.replyTailUntil = now + 3
            return aoHideLine()
        end
        local e = aoParseLine(s)
        if e then
            aoPush(e)
            AO.replyTailUntil=now+3
            return aoHideLine()
        end
        if aoIsFooter(s) then
            if AO.gotHeader or AO.gotLine then
                aoCommit()
                AO.replyTailUntil=now+3
                AO.waiting = false
                AO.hide = false
                AO.ours = false
                return aoHideLine()
            end
        end
        if aoIsHeader(s) then
            AO.gotHeader = true
            AO.replyTailUntil=now+3
            AO.lastLineAt = os.clock()
            AO.waitUntil = os.clock() + 2.2
            return aoHideLine()
        end
        return false
    end
    function grndAoOnDialog(dialogId, style, title, button1, button2, text)
        if not AO.waiting then
            if not AO.adminReplyUntil or os.clock() > AO.adminReplyUntil then return false end
            AO.lateCollect = true
        end
        local titleU = aoStrip(title)
        local raw = aoUtf(tostring(text or ""))
        raw = raw:gsub("\r\n", "\n"):gsub("\r", "\n")
        local head = titleU
        if head == "" then head = aoStrip(raw:sub(1, 120)) end
        if not aoIsHeader(head) then return false end
        AO.gotHeader = true
        if not raw:find("\n", 1, true) then raw = raw .. "\n" end
        for line in raw:gmatch("(.-)\n") do
            local e = aoParseLine(line)
            if e then aoPush(e) end
        end
        if not AO.gotLine then return false end
        aoCommit()
        AO.waiting = false
        local shouldHide = (AO.hide and true or false)
        if shouldHide then AO.replyTailUntil=os.clock()+3 end
        AO.hide = false
        AO.ours = false
        return shouldHide
    end
    function grndAoOnCommand(cmd)
        local c = tostring(cmd or "")
        c = c:gsub("^%s+", "")
        local low = c:lower()
        if low ~= "/admins" and not low:match("^/admins%s") then return end
        if AO.ours then
            AO.ours = false
            return
        end
        AO.replyTailUntil=nil
        AO.adminReplyUntil = os.clock() + 6
        AO.levelProbe = false
        AO.hide = false
        AO.waiting = true
        AO.waitUntil = os.clock() + 2.2
        AO.collect = {}
        AO.gotHeader = false
        AO.gotLine = false
        AO.lateCollect = false
        AO.lastLineAt = os.clock()
    end
    local function aoSampReady()
        if type(isSampAvailable) == "function" then
            local ok, r = pcall(isSampAvailable)
            if not ok or not r then return false end
        end
        return true
    end
    local function aoSpawned()
        if type(sampIsLocalPlayerSpawned) == "function" then
            local ok, r = pcall(sampIsLocalPlayerSpawned)
            if ok then return r and true or false end
        end
        return true
    end
    local function aoBusy()
        if type(grndIsTyping) == "function" then
            local ok, r = pcall(grndIsTyping)
            if ok and r then return true end
        end
        if GRND_KEYS then
            if GRND_KEYS.blocked then return true end
        end
        return false
    end
    local function aoSend()
        if type(sampSendChat) ~= "function" then return false end
        AO.ours = true
        AO.hide = true
        AO.waiting = true
        AO.waitUntil = os.clock() + 2.2
        AO.collect = {}
        AO.gotHeader = false
        AO.gotLine = false
        AO.lateCollect = false
        AO.lastLineAt = os.clock()
        AO.adminReplyUntil = os.clock() + 6
        local ok = pcall(sampSendChat, "/admins")
        if not ok then
            AO.ours = false
            AO.waiting = false
            AO.hide = false
            AO.adminReplyUntil = nil
            return false
        end
        AO.sentAt = os.clock()
        AO.nextAt = os.clock() + aoClamp(AO.interval, 3, 30)
        return true
    end
    function grndAoRequestLevels()
        if not aoSampReady() or not aoSpawned() or aoBusy()
            or AO.waiting or AO.lateCollect then return false end
        local ok = aoSend()
        if ok then AO.levelProbe = true end
        return ok
    end
    function grndAoTick()
        local now = os.clock()
        if not AO.cfgLoaded then
            AO.cfgLoaded = true
            pcall(grndAoCfgLoad)
        end
        if not AO.termReg then
            AO.termReg = true
            if type(grndOnTerm) == "function" then
                grndOnTerm(function() pcall(grndAoCfgSave) end)
            end
        end
        local today = aoToday()
        if AO.playDate ~= today then
            AO.playDate = today
            AO.playSec = 0
            AO.cfgDirty = true
        end
        if AO.adminMinutesDate ~= today then
            AO.adminMinutesDate = today
            AO.adminMinutesToday = nil
            AO.cfgDirty = true
        end
        local dt = now - (AO.tickAt or now)
        if dt < 0 then dt = 0 end
        if dt > 0.25 then dt = 0.25 end
        AO.tickAt = now
        if aoSampReady() and aoSpawned() then
            AO.playSec = (tonumber(AO.playSec) or 0) + dt
        end
        if AO.waiting or AO.lateCollect then
            if now > (AO.waitUntil or 0) then
                aoCommit()
                AO.waiting = false
                AO.hide = false
                AO.ours = false
                AO.levelProbe = false
            end
        end
        if grndUiBlocked() then
            if AO.waiting and not AO.levelProbe then
                AO.waiting, AO.hide, AO.ours = false, false, false
            end
            if not AO.levelProbe then AO.replyTailUntil=nil end
            AO.nextAt = now + 2.0
        elseif AO.enabled and aoSampReady() and not AO.waiting and not AO.lateCollect then
            if now >= (AO.nextAt or 0) and not aoBusy() then
                aoSend()
            end
        end
        if AO.cfgDirty and (now - (AO.cfgSavedAt or 0)) > 0.8 then
            pcall(grndAoCfgSave)
        end
        if now - (AO.playSavedAt or 0) > 20 then
            AO.playSavedAt = now
            pcall(grndAoCfgSave)
        end
    end
end
GRND_RC = _G.GRND_RC or {}
do
    local RC = GRND_RC
    RC.show     = false
    RC.cursor   = false
    RC.id       = RC.id
    RC.nick     = RC.nick or ""
    RC.st       = RC.st or {}
    RC.live     = RC.live or {}
    RC.hoverUi  = false
    RC.actionsWinOpen = false
    RC.actSubPopup = nil
    RC.actionsWinFocus = false
    RC.interactHover  = false
    RC.actDragging    = false
    RC.savedActionsWinX = RC.savedActionsWinX or nil
    RC.savedActionsWinY = RC.savedActionsWinY or nil
    RC.actionsWinUser = false
    RC.actionsWinAnchorX = nil
    RC.actionsWinAnchorY = nil
    RC.actionsWinCircleY = nil
    RC.actionsWinAt = nil
    RC.actionsWinRcId = nil
    RC.actionsWinRect = nil
    RC.hoverTarget    = nil
    RC.actTargetId    = nil
    RC.actTargetNick  = nil
    RC.actTargetPed   = nil
    RC.punDragging    = false
    RC.punishPosX     = nil
    RC.punishPosY     = nil
    RC.barPage  = tonumber(RC.barPage) or 1
    RC.actPage  = tonumber(RC.actPage) or 1
    RC.colP     = (RC.colP ~= false)
    RC.colS     = (RC.colS ~= false)
    RC.prompt   = nil
    RC.quick    = false
    RC.tdHide   = {}
    RC.tdOrig   = {}
    RC.tdKind   = {}
    RC.tdSeenAt = 0
    RC.rmbHeld  = false
    RC.specWasActive = false
    RC.lastTargetId = nil
    RC.reconTdActive = false
    RC.reconSeen = false
    RC.reconHidden = false
    RC.QUICK    = RC.QUICK or {
        "Приветствую, слежу за вами.",
        "Прекратите нарушение.",
        "Проследуйте в AZ.",
        "Сейчас разберусь, ожидайте.",
    }
    local function rcUtf(s)
        s = tostring(s or "")
        if s == "" then return s end
        if type(grndToUtf) == "function" then
            local ok, r = pcall(grndToUtf, s)
            if ok and type(r) == "string" then s = r end
        end
        return s
    end
    local function rcStrip(s)
        s = rcUtf(s)
        s = s:gsub("{%x%x%x%x%x%x%x%x}", "")
        s = s:gsub("{%x%x%x%x%x%x}", "")
        s = s:gsub("~%w~", "")
        s = s:gsub("<[^>]+>", "")
        s = s:gsub("[%c\r]", " ")
        s = s:gsub("^%s+", ""):gsub("%s+$", "")
        return s
    end
    local function rcSetLive(k, v)
        if v == nil then return end
        v = tostring(v):gsub("^%s+", ""):gsub("%s+$", "")
        if v == "" then return end
        RC.live = RC.live or {}
        RC.live[k] = v
    end
    local function rcAfterColon(s)
        local v = tostring(s or ""):match(":%s*(.*)$")
        if not v then return nil end
        v = v:gsub("^%s+", ""):gsub("%s+$", "")
        if v == "" then return nil end
        return v
    end
    local RC_LABEL = {
        ammo = { "AMMO" },
        weap = { "GUN" },
        ping = { "PING" },
        afk  = { "AFK" },
        speed = { "SPEED" },
        frac = { "FRACTION", "Fraction" },
        arm  = { "ARM" },
        hp   = { "HP" },
    }
    local function rcKind(s)
        if type(s) ~= "string" or s == "" then return nil end
        local u = s:gsub("^%s+", "")
        local head = u:match("^([%a]+)%s*:")
        if not head then
            local idn = u:match("^%[%s*(%d+)%s*%]%s*$")
            if idn then return "id", idn end
            return nil
        end
        local up = head:upper()
        if up == "AMMO" then return "ammo" end
        if up == "GUN" then return "weap" end
        if up == "PING" then return "ping" end
        if up == "AFK" then return "afk" end
        if up == "SPEED" then return "speed" end
        if up == "FRACTION" then return "frac" end
        if up == "ARM" then return "arm" end
        if up == "HP" then return "hp" end
        return nil
    end
    local function rcKindCount()
        local n, seen = 0, {}
        local liveKeys = { "weap", "ammo", "ping", "afk", "hp", "arm", "frac", "speed" }
        for i = 1, #liveKeys do
            local k = liveKeys[i]
            if RC.live and RC.live[k] ~= nil and tostring(RC.live[k]) ~= "" then
                seen[k] = true
                n = n + 1
            end
        end
        for _, k in pairs(RC.tdKind or {}) do
            if k ~= "id" and k ~= "name" and k ~= "recon" and not seen[k] then
                seen[k] = true
                n = n + 1
            end
        end
        return n
    end
    local function rcConfirmed()
        return rcKindCount() >= 3
    end
    local function rcApplyKind(kind, s, extra)
        if kind == "id" then
            local idn = extra or s:match("%[%s*(%d+)%s*%]")
            if idn then
                RC.id = tonumber(idn)
                rcSetLive("id", idn)
            end
            return
        end
        local v = rcAfterColon(s) or extra
        if kind == "weap" then rcSetLive("weap", v)
        elseif kind == "ammo" then rcSetLive("ammo", v)
        elseif kind == "ping" then rcSetLive("ping", v)
        elseif kind == "afk" then rcSetLive("afk", v)
        elseif kind == "hp" then rcSetLive("hp", v)
        elseif kind == "arm" then rcSetLive("arm", v)
        elseif kind == "frac" then rcSetLive("frac", v)
        elseif kind == "speed" then rcSetLive("speed", v)
        end
    end
    local RC_COMPOUND_FIELDS = {
        { kind = "weap", label = "GUN:" },
        { kind = "ammo", label = "AMMO:" },
        { kind = "ping", label = "PING:" },
        { kind = "afk",  label = "AFK:" },
        { kind = "hp",   label = "HP:" },
        { kind = "arm",  label = "ARM:" },
        { kind = "frac", label = "FRACTION:" },
        { kind = "speed", label = "SPEED:" },
    }
    local function rcParseCompound(text)
        text = tostring(text or "")
        if text == "" then return false end
        local upper = text:upper()
        local hits = {}
        for i = 1, #RC_COMPOUND_FIELDS do
            local def = RC_COMPOUND_FIELDS[i]
            local pos = upper:find(def.label, 1, true)
            if pos then
                hits[#hits + 1] = { pos = pos, kind = def.kind, label = def.label }
            end
        end
        if #hits == 0 then return false end
        table.sort(hits, function(a, b) return a.pos < b.pos end)
        local prefix = text:sub(1, hits[1].pos - 1)
        local nick, idn = prefix:match("^%s*(.-)%[%s*(%d+)%s*%]%s*$")
        if nick and nick ~= "" then
            RC.nick = nick
            RC.id = tonumber(idn)
            rcSetLive("id", idn)
        end
        for i = 1, #hits do
            local h = hits[i]
            local from = h.pos + #h.label
            local to = (hits[i + 1] and hits[i + 1].pos or (#text + 1)) - 1
            local value = text:sub(from, to)
            value = value:gsub("^%s+", ""):gsub("%s+$", "")
            rcApplyKind(h.kind, "", value)
        end
        return true
    end
    local function rcLooksName(s)
        if type(s) ~= "string" then return false end
        if #s < 3 or #s > 32 then return false end
        if s:find(":", 1, true) then return false end
        if s:match("%[%s*%d+%s*%]") then return false end
        if s:find("GUN", 1, true) or s:find("HP", 1, true) or s:find("ARM", 1, true) then return false end
        if s:find("PING", 1, true) or s:find("SPEED", 1, true) then return false end
        if s:find("_", 1, true) then return true end
        if s:find(" ", 1, true) and not s:find("%d") then return true end
        return false
    end
    local function rcParseText(text)
        text = rcStrip(text)
        if text == "" then return false end
        if rcParseCompound(text) then return true end
        local hit = false
        text = text:gsub("\r\n", "\n"):gsub("\r", "\n")
        local function one(line)
            local kind, extra = rcKind(line)
            if kind then
                rcApplyKind(kind, line, extra)
                return true
            end
            return false
        end
        if text:find("\n", 1, true) then
            for line in (text .. "\n"):gmatch("(.-)\n") do
                if one(line) then hit = true end
            end
        else
            hit = one(text)
        end
        if (not hit) and rcLooksName(text) then
            RC.nick = text
            hit = true
        end
        return hit
    end
    local function rcTdExists(id)
        if type(sampTextdrawIsExists) ~= "function" then return nil end
        local ok, r = pcall(sampTextdrawIsExists, id)
        if ok then return r and true or false end
        return nil
    end
    local function rcTdString(id)
        if type(sampTextdrawGetString) ~= "function" then return "" end
        local ok, s = pcall(sampTextdrawGetString, id)
        if ok and type(s) == "string" then return s end
        return ""
    end
    local function rcHideTd(id)
        id = tonumber(id)
        if not id then return end
        RC.tdHide[id] = true
        if RC.tdOrig[id] == nil and type(sampTextdrawGetPos) == "function" then
            local ok, x, y = pcall(sampTextdrawGetPos, id)
            if ok and type(x) == "number" then
                RC.tdOrig[id] = { x = x, y = y }
            else
                RC.tdOrig[id] = false
            end
        elseif RC.tdOrig[id] == nil then
            RC.tdOrig[id] = false
        end
        if type(sampTextdrawSetPos) == "function" then
            pcall(sampTextdrawSetPos, id, -5000.0, -5000.0)
        end
    end
    local function rcRestoreTds()
        if type(sampTextdrawSetPos) == "function" then
            for id, pos in pairs(RC.tdOrig) do
                if type(pos) == "table" and pos.x then
                    pcall(sampTextdrawSetPos, id, pos.x, pos.y)
                end
            end
        end
        RC.tdHide = {}
        RC.tdOrig = {}
        RC.tdKind = {}; RC.tdSweep = nil
    end
    function grndRcOnTextDraw(id, text)
        id = tonumber(id)
        text = tostring(text or "")
        if not id then return false end
        local stripped = rcStrip(text)
        if stripped ~= "" and type(_G.grndStatsOnTextDraw) == "function" then
            pcall(_G.grndStatsOnTextDraw, stripped)
        end
        local kind, extra = rcKind(stripped)
        local compound = rcParseCompound(stripped)
        RC.tdKind = RC.tdKind or {}
        if compound then
            RC.tdKind[id] = "recon"
            kind = "recon"
        elseif kind then
            RC.tdKind[id] = kind
            rcApplyKind(kind, stripped, extra)
        elseif RC.show and rcLooksName(stripped) then
            RC.nick = stripped
            RC.tdKind[id] = "name"
            kind = "name"
        else
            return false
        end
        if not rcConfirmed() then return false end
        RC.reconHidden = false
        RC.reconMissingAt = nil
        RC.reconTdActive = true
        RC.reconSeen = true
        RC.tdSeenAt = os.clock()
        RC.tdGoneSince = nil
        RC.show = true
        for hid, _ in pairs(RC.tdKind) do
            rcHideTd(hid)
        end
        return true
    end
    local function grndRcForceClose(reason)
        RC.show = false
        RC.cursor = false
        RC.rmbHeld = false
        RC.prompt = nil
        RC.quick = false
        RC.id = nil
        RC.nick = ""
        RC.live = {}
        RC.actionsWinOpen = false
        RC.actSubPopup = nil
        RC.actionsWinFocus = false
        RC.interactHover = false
        RC.actDragging = false
        RC.hoverTarget = nil
        RC.actTargetId = nil
        RC.actTargetNick = nil
        RC.actTargetPed = nil
        RC.punDragging = false
        RC.reconSeen = false
        RC.reconTdActive = false
        RC.reconHidden = true
        RC.reconMissingAt = nil
        RC.closedAt = os.clock()
        RC.lastCursor = false
        RC.closeHandled = true
        RC.tdGoneSince = nil
        if RC.tdKind then RC.tdKind = {}; RC.tdSweep = nil end
        if type(_G.grndPlainCursorForceOff) == "function" then
            pcall(_G.grndPlainCursorForceOff)
        end
        if type(_G.grndNativeCursorShow) == "function" then
            pcall(_G.grndNativeCursorShow, false)
        end
        if type(rcRestoreTds) == "function" then
            pcall(rcRestoreTds)
        end
        local GS = _G.GRND_SPEC
        if GS then
            GS.manualExit = true
            GS.active = false
            GS.id = nil
            GS.nick = ""
            GS.confirmT = 0
        end
        local SA = _G.GRND_SPEC_AUTOREF
        if SA then
            SA.manualExit = true
            SA.lastTargetId = nil
            SA.lostSince = nil
            SA.refreshCount = 0
        end
        if type(_G.grndSpecNativeReleaseCam) == "function" then
            pcall(_G.grndSpecNativeReleaseCam)
        end
    end
    _G.grndRcForceClose = grndRcForceClose
    function grndRcOnTextDrawHide(id)
        id = tonumber(id)
        if not id then return end
        if id == 2048 or (RC.tdKind and RC.tdKind[id]) then
            local GS = _G.GRND_SPEC
            local tid = tonumber(GS and GS.id) or tonumber(RC.id)
                or (_G.GRND_SPEC_AUTOREF and tonumber(_G.GRND_SPEC_AUTOREF.lastTargetId))
            local conn = nil
            if type(sampIsPlayerConnected) == "function" and tid then
                local okc, cc = pcall(sampIsPlayerConnected, tid)
                if okc then conn = cc and true or false end
            end
            if conn == false then
                grndRcForceClose("quit")
                return
            end
            local manualExit = (GS and GS.manualExit)
                or (_G.GRND_SPEC_AUTOREF and _G.GRND_SPEC_AUTOREF.manualExit)
            if not manualExit and conn ~= false and tid then
                RC.reconTdActive = false
                RC.tdGoneSince = RC.tdGoneSince or os.clock()
                if RC.tdKind then RC.tdKind[id] = nil end
                return
            end
            grndRcForceClose("hide")
            if RC.tdKind then RC.tdKind[id] = nil end
            RC.tdGoneAt = os.clock()
        end
    end
    local function rcIsSpectating()
        for _, name in ipairs({ "sampIsPlayerSpectating", "isPlayerSpectating" }) do
            local f = _G[name]
            if type(f) == "function" then
                local ok, r = pcall(f)
                if ok and r == true then return true end
            end
        end
        if _G.GRND_SPEC and GRND_SPEC.active then return true end
        local sn = _G.grndSpecNative
        if sn and sn.ok then
            local ok, on = pcall(sn.spectState, sn)
            if ok and on then return true end
            local ok2, on2 = pcall(sn.spectScan, sn)
            if ok2 and on2 then return true end
        end
        return false
    end
    local RC_TD_CHUNK = 64
    local function rcScanTextdraws()
        if type(sampTextdrawIsExists) ~= "function" then return 0 end
        if RC.reconHidden then
            RC.reconTdActive = false
            RC.tdSweep = nil
            return 0
        end
        local sweep = RC.tdSweep
        if not sweep then
            sweep = { at = 0, hits = 0, names = {} }
            RC.tdSweep = sweep
            RC.tdKind = {}
        end
        local names, hits = sweep.names, sweep.hits
        local idFrom = sweep.at
        local idTo = math.min(2304, idFrom + RC_TD_CHUNK - 1)
        for id = idFrom, idTo do
            local ex = rcTdExists(id)
            if ex then
                local raw = rcTdString(id)
                local s = rcStrip(raw)
                if s ~= "" then
                    local kind, extra = rcKind(s)
                    local compound = rcParseCompound(s)
                    if compound then
                        RC.tdKind[id] = "recon"
                        hits = hits + 1
                    elseif kind then
                        RC.tdKind[id] = kind
                        rcApplyKind(kind, s, extra)
                        hits = hits + 1
                    elseif rcLooksName(s) then
                        names[#names + 1] = { id = id, s = s }
                    end
                end
            end
        end
        sweep.hits, sweep.at = hits, idTo + 1
        if sweep.at <= 2304 then
            return hits
        end
        RC.tdSweep = nil
        if hits > 0 then
            RC.reconTdActive = true
            RC.reconSeen = true
            RC.reconMissingAt = nil
            RC.tdGoneSince = nil
        elseif RC.show then
            RC.reconMissingAt = RC.reconMissingAt or os.clock()
            if os.clock() - RC.reconMissingAt > 0 then
                local manualExit = (_G.GRND_SPEC and _G.GRND_SPEC.manualExit)
                    or (_G.GRND_SPEC_AUTOREF and _G.GRND_SPEC_AUTOREF.manualExit)
                local tid = tonumber(RC.id) or (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id))
                    or (_G.GRND_SPEC_AUTOREF and tonumber(_G.GRND_SPEC_AUTOREF.lastTargetId))
                local conn = nil
                if type(sampIsPlayerConnected) == "function" and tid then
                    local okc, cc = pcall(sampIsPlayerConnected, tid)
                    if okc then conn = cc and true or false end
                end
                if conn == false then
                    grndRcForceClose("quit")
                elseif (rcIsSpectating() or not manualExit) and conn ~= false and tid then
                    RC.reconTdActive = false
                    RC.tdGoneSince = RC.tdGoneSince or os.clock()
                else
                    grndRcForceClose("scan_missing")
                end
            end
        else
            RC.reconTdActive = false
        end
        if hits == 0 then
            return 0
        end
        if not rcConfirmed() then
            return hits
        end
        if #names > 0 then
            RC.nick = names[1].s
            RC.tdKind[names[1].id] = "name"
        end
        for hid, _ in pairs(RC.tdKind) do
            rcHideTd(hid)
        end
        RC.tdSeenAt = os.clock()
        return hits
    end
    local function rcRehide()
        if type(sampTextdrawSetPos) ~= "function" then return end
        for id, _ in pairs(RC.tdHide) do
            pcall(sampTextdrawSetPos, id, -5000.0, -5000.0)
        end
    end
    function grndRcSend(cmd) return false end
    function grndRcCmd() return false end
    function grndRcRefresh() end
    function grndRcExit()
        RC.show = false
        RC.prompt = nil
        RC.quick = false
        RC.id = nil
        RC.nick = ""
        RC.live = {}
        RC.reconSeen = false
        RC.reconTdActive = false
        RC.reconHidden = true
        pcall(rcRestoreTds)
    end
    function grndRcOnChat() return false end
    function grndRcOnDialog() return false end
    function grndRcOnCommand() end
    function grndRcActive()
        return RC.show and true or false
    end
    local function disableVanillaSpectate()
        if GRND_KEYS.enterPressed and RC.show then
            local inputText = ""
            if type(getChatInput) == "function" then
                inputText = getChatInput() or ""
            elseif type(sampGetChatInput) == "function" then
                inputText = sampGetChatInput() or ""
            end
            if string.find(string.lower(inputText), "^/spectate") then
                if type(clearChatInput) == "function" then
                    clearChatInput()
                elseif type(sampClearChatInput) == "function" then
                    sampClearChatInput()
                end
                GRND_KEYS.enterPressed = false
                return true
            end
        end
        return false
    end
    function grndRcTick()
        local now = os.clock()
        if type(grndSpecNativeTick) == "function" then
            local okCamera,errCamera=pcall(grndSpecNativeTick)
            if not okCamera then grndCamReportError('follow',errCamera) end
        end
        if RC.show then
            disableVanillaSpectate()
        end
        local spec = rcIsSpectating() or grndSpecInSpec()
        if RC.show then
            local down, src = false, nil
            local w = grndRmbHeldWin()
            if w ~= nil then
                down = w and true or false
                if down then src = "win" end
            else
                if type(isKeyDown) == "function" then
                    local okD, d = pcall(isKeyDown, 0x02)
                    if okD and d then down = true; src = src or "vk" end
                end
                if type(getMouseState) == "function" then
                    local okM, ms = pcall(getMouseState)
                    if okM and type(ms) == "number" and math.floor(ms / 2) % 2 == 1 then
                        down = true; src = src or "gms"
                    end
                end
                if type(isMouseButtonDown) == "function" then
                    local okB, d2 = pcall(isMouseButtonDown, 2)
                    if okB and d2 then down = true; src = src or "mbd" end
                end
                if GRND_MOUSE and GRND_MOUSE.rdown then down = true; src = src or "wm" end
            end
            local wkTap = false
            for _, fn in ipairs({ wasKeyPressed, isKeyJustPressed }) do
                if type(fn) == "function" then
                    local okP, p = pcall(fn, 0x02)
                    if okP and p then wkTap = true end
                end
            end
            local tapped = false
            if down and not (RC.rmbHeld or false) then tapped = true end
            if RC.rmbWmTap then tapped = true end
            local rcNow = (GRND_MOUSE and GRND_MOUSE.rclicked) and true or false
            if rcNow and not (RC.rmbRcPrev or false) then tapped = true end
            RC.rmbRcPrev = rcNow
            if wkTap then tapped = true end
            RC.rmbWmTap = false
            if tapped then RC.rmbSrc = src or "tap" end
            if RC.rmbWmUp then RC.rmbArmed = true end
            if (RC.rmbHeld or false) and not down then RC.rmbArmed = true end
            RC.rmbWmUp = false
            if RC.rmbWmHeld and now - (RC.rmbWmHeldAt or now) > 3 then
                RC.rmbWmHeld = false
            end
            local sinceLast = now - (RC.rmbLastToggleAt or -99)
            if not RC.rmbWmSeen and sinceLast > 0.8 then
                RC.rmbArmed = true
            end
            if tapped and (RC.rmbArmed ~= false) and sinceLast > 0.25 then
                RC.cursor = not RC.cursor
                RC.rmbLastToggleAt = now
                RC.rmbArmed = false
                RC.rmbSrc = src or "tap"
                if RC.cursor and _G.GRND_IM and _G.GRND_IM.Process ~= nil then
                    pcall(function() _G.GRND_IM.Process = true end)
                end
                if type(_G.grndNativeCursorShow) == "function" then
                    pcall(_G.grndNativeCursorShow, RC.cursor)
                end
            end
            RC.rmbHeld = down
        else
            RC.rmbHeld = false
            RC.rmbWmTap = false
            RC.rmbWmUp = false
            RC.rmbArmed = true
        end
        if (now - (RC.scanAt or 0)) > 0.12 then
            RC.scanAt = now
            pcall(rcScanTextdraws)
        end
        local targetId = (_G.GRND_SPEC and GRND_SPEC.active)
            and tonumber(GRND_SPEC.id) or nil
        local specRising = spec and not RC.specWasActive
        if specRising or (targetId and tonumber(RC.lastTargetId) ~= targetId) then
            if not RC.show then
                RC.reconHidden = false
                RC.reconSeen = false
                RC.reconTdActive = false
                RC.reconMissingAt = nil
            end
        end
        RC.specWasActive = spec
        if targetId then RC.lastTargetId = targetId end
        if targetId and RC.id and tonumber(RC.id) ~= targetId then
            RC.live = {}
            RC.nick = ""
            RC.tdKind = {}; RC.tdSweep = nil
            RC.tdHide = {}
            RC.tdOrig = {}
            RC.tdSeenAt = 0
        end
        if targetId then RC.id = targetId end
        local curTid = tonumber(RC.id)
            or (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id))
            or (_G.GRND_SPEC_AUTOREF and tonumber(_G.GRND_SPEC_AUTOREF.lastTargetId))
        if curTid and type(sampIsPlayerConnected) == "function" then
            local okc, cc = pcall(sampIsPlayerConnected, curTid)
            if okc and not cc then
                grndRcForceClose("quit")
                if type(grndSpecForget) == "function" then
                    pcall(grndSpecForget, "quit")
                end
                return
            end
        end
        local want
        local manualExit = (_G.GRND_SPEC and _G.GRND_SPEC.manualExit)
            or (_G.GRND_SPEC_AUTOREF and _G.GRND_SPEC_AUTOREF.manualExit)
        if RC.reconHidden and manualExit then
            want = false
        elseif RC.reconSeen then
            if RC.reconTdActive then
                want = true
            else
                local specHold = spec or not manualExit
                local tidHold = (_G.GRND_SPEC
                    and tonumber(_G.GRND_SPEC.id)) or tonumber(RC.id)
                    or (_G.GRND_SPEC_AUTOREF and tonumber(_G.GRND_SPEC_AUTOREF.lastTargetId))
                local isConn = true
                if tidHold and type(sampIsPlayerConnected) == "function" then
                    local okcH, ccH = pcall(sampIsPlayerConnected, tidHold)
                    if okcH and not ccH then isConn = false end
                end
                if not isConn then
                    want = false
                else
                    local goneH = now - (RC.tdGoneSince or now)
                    want = specHold or goneH < 30.0
                end
            end
        else
            want = (spec or (RC.reconTdActive and rcConfirmed()) or not manualExit)
            if want then
                local tidHold = (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id)) or tonumber(RC.id)
                if tidHold and type(sampIsPlayerConnected) == "function" then
                    local okcH, ccH = pcall(sampIsPlayerConnected, tidHold)
                    if okcH and not ccH then want = false end
                end
            end
        end
        if spec or RC.reconTdActive then
            RC.statsOnly = nil
        end
        if RC.statsOnly and not spec and not RC.reconTdActive then
            if type(_G.grndStatsViewFresh) == "function"
                and _G.grndStatsViewFresh(now) then
                want = true
            else
                RC.statsView = nil
                want = false
            end
        end
        if want then
            if not RC.show then
                RC.show = true
                if now - (RC.closedAt or -99) > 0.4 then
                    RC.cursor = false
                    if type(_G.grndPlainCursorForceOff) == "function" then
                        pcall(_G.grndPlainCursorForceOff)
                    end
                else
                    RC.cursor = RC.lastCursor and true or false
                    if type(_G.grndNativeCursorShow) == "function" then
                        pcall(_G.grndNativeCursorShow, RC.cursor)
                    end
                end
                RC.prompt = nil
                RC.quick = false
            end
            pcall(rcRehide)
            if not RC.id and _G.GRND_SPEC and GRND_SPEC.id then
                RC.id = tonumber(GRND_SPEC.id)
                if (RC.nick == "" or not RC.nick) and GRND_SPEC.nick then
                    RC.nick = tostring(GRND_SPEC.nick)
                end
            end
        elseif RC.show then
            RC.show = false
            RC.closedAt = now
            RC.lastCursor = RC.cursor and true or false
            RC.closeHandled = false
            RC.cursor = false
            RC.prompt = nil
            RC.quick = false
            RC.id = nil
            RC.nick = ""
            RC.live = {}
            RC.actionsWinOpen = false
            RC.actSubPopup = nil
            RC.interactHover = false
            RC.actDragging = false
            RC.hoverTarget = nil
            RC.actTargetId = nil
            RC.actTargetNick = nil
            RC.actTargetPed = nil
            RC.punDragging = false
            RC.reconSeen = false
            RC.reconTdActive = false
            RC.reconHidden = true
            RC.reconMissingAt = nil
            pcall(rcRestoreTds)
        end
        if not RC.show and RC.closeHandled == false and RC.closedAt then
            if now - RC.closedAt > 0.4 then
                RC.closeHandled = true
                if type(_G.grndNativeCursorShow) == "function"
                    and type(_G.grndPlainCursorIsOn) == "function" then
                    pcall(_G.grndNativeCursorShow, _G.grndPlainCursorIsOn())
                end
            end
        end
    end
end
GRND_TRACE = {
    marks = {}, size = 0, head = 0, seq = 0, on = true,
    last = {}, startedAt = nil, dumped = 0, seen = 0, keys = {}, keysN = 0,
}
function now0()
    return grndTraceClock()
end
function grndTraceClock()
    local ok, c = pcall(os.clock)
    if ok and type(c) == "number" then return c end
    return 0
end
function grndTrace(tag, info)
    local T = GRND_TRACE
    if not T.on then return end
    local now = grndTraceClock()
    local last = T.rep and T.rep[tag]
    local gap = T.gap or 1.0
    if last and last.info == tostring(info or "") and (now - last.at) < gap then
        T.sup = (T.sup or 0) + 1
        return
    end
    T.rep = T.rep or {}
    T.rep[tag] = { info = tostring(info or ""), at = now }
    T.seq = T.seq + 1
    T.head = T.head + 1
    if T.head > 900 then T.head = 1 end
    if T.size < 900 then T.size = T.size + 1 end
    T.marks[T.head] = { at = grndTraceClock(), seq = T.seq, tag = tag,
        info = tostring(info or "") }
end
function grndTraceOnce(key, tag, val)
    local T = GRND_TRACE
    if not T.on then return end
    local s = tostring(val)
    if T.last[key] == s then return end
    T.last[key] = s
    grndTrace(tag, s)
end
function grndTraceDirs()
    local out, seen = {}, {}
    local function push(d)
        d = tostring(d or "")
        if d == "" or seen[d] then return end
        while d:sub(-1) == "/" or d:sub(-1) == "\\" do d = d:sub(1, -2) end
        if d == "" then return end
        seen[d] = true
        out[#out + 1] = d
    end
    if type(this_script_dir) == "function" then
        local okd, sd = pcall(this_script_dir)
        if okd then push(sd) end
    end
    local oki, info = pcall(function() return debug.getinfo(1, "S") end)
    if oki and info and info.source then
        local sc = tostring(info.source):gsub("^@", "")
        local dir = sc:match("^(.*[/\\])[^/\\]*$")
        if dir then push(dir) end
    end
    push("moonloader")
    push("")
    return out
end
function grndTracePath()
    local path=grndStoragePath("logs","grnd_trace.txt")
    if GRND_TRACE then
        GRND_TRACE.path=path
        GRND_TRACE.dir=GRND_STORAGE.root..package.config:sub(1,1).."logs"
    end
    return path
end
function grndTraceEnv()
    local api = { "sampIsDialogActive", "sampIsChatInputActive", "sampIsLocalPlayerSpawned",
        "sampAddChatEntry", "sampRegisterChatCommand", "sampGetChatLine",
        "showCursor", "isKeyClicked", "consumeWindowMessage", "isWindowActive",
        "getD3DDevicePtr", "sampGetCharHealth" }
    local have, miss = {}, {}
    for i = 1, #api do
        if type(_G[api[i]] or rawget(_G, api[i])) == "function" then
            have[#have + 1] = api[i]
        else
            miss[#miss + 1] = api[i]
        end
    end
    return have, miss
end
function grndTraceFrames(delta)
    local T = GRND_TRACE
    T.frames = (T.frames or 0) + (delta or 0)
    return T.frames
end
function T_frames()
    return GRND_TRACE.frames or 0
end
function grndTraceState()
    local T = GRND_TRACE
    if not T.on then return end
    local K = GRND_KEYS
    grndTraceOnce("busy", "окно авторизации открыто", K.authBusy)
    grndTraceOnce("sdlg", "серверное окно открыто", K.dlgActive)
    grndTraceOnce("blocked", "перехват клавиш снят", K.blocked)
    grndTraceOnce("spawn", "флаг спавна", K.spawnedNow)
    grndTraceOnce("typing", "родной ввод чата", K.typing)
    grndTraceOnce("tfresh", "уступаем печать", K.typingFresh)
    grndTraceOnce("uib", "меню/таблица открыты", K.uiBusy)
end
function grndTraceDiag()
    local out = {}
    local K = GRND_KEYS
    if IMGUI_WRAP == nil or tostring(IMGUI_WRAP):find("НЕТ") then
        out[#out + 1] = "ImGui НЕ загружен"
    elseif T_frames() == 0 then
        out[#out + 1] = "ни ОДНОГО кадра ImGui не отрисовано"
    end
    if K.authBusy then
        out[#out + 1] = "открыто окно авторизации скрипта"
    elseif K.dlgActive then
        out[#out + 1] = "открыт серверный диалог — он работу скрипта не блокирует"
    end
    if K.typing then
        out[#out + 1] = "игрок печатает в родном чате — хоткеи уступают"
    end
    if #out == 0 then out[#out + 1] = "замечаний нет" end
    return out
end
function grndTraceDump(why)
    local T = GRND_TRACE
    local function now() return grndTraceClock() end
    T.path = nil
    local ok, f = pcall(io.open, grndTracePath(), "w")
    if not ok or not f then
        grndTrace("trace", "НЕ ЧЕГО писать: путь " .. tostring(grndTracePath()))
        return false
    end
    local have, miss = grndTraceEnv()
    local L = {}
    L[#L + 1] = "GRND TOOLS — ТРАССИРОВКА"
    L[#L + 1] = "причина: " .. tostring(why or "ручная")
    L[#L + 1] = "аптайм: " .. string.format("%.1f", grndTraceClock()) .. " с"
    L[#L + 1] = ""
    L[#L + 1] = "--- ОКРУЖЕНИЕ ---"
    L[#L + 1] = "ImGui: " .. tostring(IMGUI_WRAP or "не загружен")
    L[#L + 1] = "кадров: " .. tostring(T_frames())
    L[#L + 1] = "bit.lua: " .. (bit and "есть" or "НЕТ")
    L[#L + 1] = ""
    L[#L + 1] = "--- СОСТОЯНИЕ ---"
    local K = GRND_KEYS
    L[#L + 1] = "authBusy=" .. tostring(K.authBusy) .. " serverDlg=" .. tostring(K.dlgActive)
        .. " spawnedNow=" .. tostring(K.spawnedNow)
    L[#L + 1] = "typing(родной чат)=" .. tostring(K.typing) .. " blocked=" .. tostring(K.blocked)
    L[#L + 1] = "uiBusy=" .. tostring(K.uiBusy) .. " imguiText=" .. tostring(K.imguiText)
    L[#L + 1] = "чат: штатный ввод SA-MP + панель Tab /a; история текущей сессии"
    L[#L + 1] = "шрифт интерфейса: " .. tostring(GRND_FONT.fontLoadedPath
        or GRND_FONT.fontPath or "системный шрифт обёртки")
    L[#L + 1] = ""
    L[#L + 1] = "--- ДИАГНОЗ ---"
    local d = grndTraceDiag()
    for i = 1, #d do L[#L + 1] = i .. ") " .. d[i] end
    L[#L + 1] = ""
    L[#L + 1] = "--- ЖУРНАЛ ---"
    local i, cnt = T.head, 0
    while cnt < T.size do
        local m = T.marks[i]
        if m then
            L[#L + 1] = string.format("[%7.2f] #%d %-24s %s", m.at, m.seq, m.tag, m.info)
            cnt = cnt + 1
        end
        i = i - 1
        if i < 1 then i = 900 end
    end
    pcall(f.write, f, table.concat(L, "\n") .. "\n")
    pcall(f.close, f)
    return true, grndTracePath()
end
function grndTraceTick()
    local T = GRND_TRACE
    local now = grndTraceClock()
    if not T.startedAt then
        T.startedAt = now
        grndTrace("load", "скрипт запущен")
    end
    grndTraceState()
    if T.dumped < 1 and now - T.startedAt > 5 then
        T.dumped = 1
        pcall(grndTraceDump, "авто: 5 с после запуска")
    elseif T.dumped < 2 and now - T.startedAt > 30 then
        T.dumped = 2
        pcall(grndTraceDump, "авто: 30 с после запуска")
    end
end
function grndDialogActive()
    if type(sampIsDialogActive) == "function" then
        local ok, v = pcall(sampIsDialogActive)
        if ok then return v and true or false end
    end
    if type(sampGetDialogText) == "function" then
        local ok, txt = pcall(sampGetDialogText)
        if ok then return txt ~= nil end
    end
    return false
end
GRND_RK = {
    border = { active = false, count = 0 },
    polygon = {},
    positions = {}, playerNames = {}, roster = {}, pending = {}, watched = {}, lastDeath = {}, deathCounts = {}, eventActive = false,
    scanCursor = 0, scanNextAt = 0, rosterPruneAt = 0,
    enabled = _G.GRND_RK_ENABLED ~= false, testMode = false,
}
GRND_RK.polygon = {
    { x = 1474.8475, y = -293.3785 },
    { x = 1625.697, y = -294.067 },
    { x = 1626.150, y = -55.006 },
    { x = 1584.900, y = -54.239 },
    { x = 1583.158, y = 31.249 },
    { x = 1539.941, y = 31.952 },
    { x = 1539.059, y = -53.609 },
    { x = 1474.643, y = -55.380 },
}
function grndRkSay(text, color)
    text = tostring(text or "")
    if type(grndChatSay) == "function" then
        pcall(grndChatSay, text, color or 0xFFFF5555)
    elseif type(sampAddChatMessage) == "function" then
        pcall(sampAddChatMessage, text, color or 0xFFFF5555)
    elseif type(print) == "function" then
        print(text)
    end
end
function grndRkNow()
    if type(getGameTimer) == "function" then
        local ok, ms = pcall(getGameTimer)
        if ok and type(ms) == "number" and ms >= 0 then return ms / 1000 end
    end
    return os.clock()
end
function grndRkPosition()
    if type(getCharCoordinates) ~= "function" then return nil end
    local ped = rawget(_G, "PLAYER_PED")
    if type(ped) ~= "number" or ped == 0 then return nil end
    if type(doesCharExist) == "function" then
        local ok, exists = pcall(doesCharExist, ped)
        if not ok or not exists then return nil end
    end
    local ok, x, y, z = pcall(getCharCoordinates, ped)
    x, y, z = tonumber(x), tonumber(y), tonumber(z)
    if not ok or not x or not y or not z or x ~= x or y ~= y or z ~= z
        or math.abs(x) > 20000 or math.abs(y) > 20000 or math.abs(z) > 20000 then
        return nil
    end
    return x, y, z
end
function grndRkInsideTerritory(x, y)
    local poly = GRND_RK and GRND_RK.polygon
    if type(poly) ~= "table" or #poly < 3 then return false end
    x, y = tonumber(x), tonumber(y)
    if not x or not y then return false end
    local inside, j = false, #poly
    for i = 1, #poly do
        local a, b = poly[j], poly[i]
        if type(a) == "table" and type(b) == "table" then
            local ax, ay, bx, by = tonumber(a.x), tonumber(a.y), tonumber(b.x), tonumber(b.y)
            if ax and ay and bx and by then
                local vx, vy = bx - ax, by - ay
                local l2 = vx * vx + vy * vy
                if l2 > 0 then
                    local u = math.max(0, math.min(1, ((x - ax) * vx + (y - ay) * vy) / l2))
                    local dx, dy = x - (ax + u * vx), y - (ay + u * vy)
                    if dx * dx + dy * dy <= 1.0 then return true end
                end
                if ((ay > y) ~= (by > y)) and x < (bx - ax) * (y - ay) / (by - ay) + ax then
                    inside = not inside
                end
            end
        end
        j = i
    end
    return inside
end
function grndRkLocalInsideTerritory()
    local x, y = grndRkPosition()
    return x ~= nil and grndRkInsideTerritory(x, y) or false
end
function grndRkPlayerName(id)
    id = tonumber(id)
    if not id or id < 0 or id > 1003 or type(sampGetPlayerNickname) ~= "function" then return nil end
    local ok, name = pcall(sampGetPlayerNickname, id)
    if not ok or type(name) ~= "string" or name == "" then return nil end
    if type(grndToUtf) == "function" then
        local okUtf, converted = pcall(grndToUtf, name)
        if okUtf and type(converted) == "string" then name = converted end
    end
    name = name:gsub("{[^}]*}", ""):gsub("%c", ""):sub(1, 32)
    return name ~= "" and name or nil
end
function grndRkMigrateIdentity(id, oldKey, newIdentity)
    local R = GRND_RK
    if not oldKey or oldKey:sub(1, 3) ~= "id:" or oldKey == newIdentity.key then return end
    local newKey = newIdentity.key
    local oldDeaths, newDeaths = R.deathCounts[oldKey], R.deathCounts[newKey]
    if oldDeaths then R.deathCounts[newKey] = (newDeaths or 0) + oldDeaths end
    R.deathCounts[oldKey] = nil
    local oldAt, newAt = R.lastDeath[oldKey], R.lastDeath[newKey]
    if oldAt and (not newAt or oldAt > newAt) then R.lastDeath[newKey] = oldAt end
    R.lastDeath[oldKey] = nil
    local oldPending, newPending = R.pending[oldKey], R.pending[newKey]
    if oldPending then
        if not newPending or (oldPending.deathAt or 0) > (newPending.deathAt or 0) then
            oldPending.key, oldPending.name = newKey, newIdentity.name
            R.pending[newKey] = oldPending
        end
        R.pending[oldKey] = nil
    end
    local oldWatched, newWatched = R.watched[oldKey], R.watched[newKey]
    if oldWatched then
        if not newWatched then
            oldWatched.name = newIdentity.name
            R.watched[newKey] = oldWatched
        else
            newWatched.outside = newWatched.outside or oldWatched.outside
            newWatched.awaitingExit = newWatched.awaitingExit or oldWatched.awaitingExit
            newWatched.hospitalNotified = newWatched.hospitalNotified or oldWatched.hospitalNotified
            newWatched.hospitalCandidate = newWatched.hospitalCandidate or oldWatched.hospitalCandidate
            if oldWatched.deathAt and (not newWatched.deathAt or oldWatched.deathAt > newWatched.deathAt) then
                newWatched.deathAt, newWatched.name = oldWatched.deathAt, newIdentity.name
            end
        end
        R.watched[oldKey] = nil
    end
    R.roster = R.roster or {}
    local oldRoster, newRoster = R.roster[oldKey], R.roster[newKey]
    if oldRoster then
        if not newRoster or (oldRoster.seenAt or 0) > (newRoster.seenAt or 0) then
            oldRoster.key, oldRoster.name = newKey, newIdentity.name
            R.roster[newKey] = oldRoster
        end
        R.roster[oldKey] = nil
    end
    local position = R.positions[id]
    if position and position.key == oldKey then
        position.key, position.name = newKey, newIdentity.name
    end
end
function grndRkRememberPlayer(playerId, rawName, now)
    local R = GRND_RK
    local id = tonumber(playerId)
    if not id or id < 0 or id > 1003 or type(rawName) ~= "string" then return nil end
    local name = rawName
    if type(grndToUtf) == "function" then
        local okUtf, converted = pcall(grndToUtf, name)
        if okUtf and type(converted) == "string" then name = converted end
    end
    name = name:gsub("{[^}]*}", ""):gsub("%c", ""):sub(1, 32)
    if name == "" then return nil end
    local identity = { name = name, key = "nick:" .. name:lower(), at = now or grndRkNow() }
    local old = R.playerNames[id]
    if old then grndRkMigrateIdentity(id, old.key, identity) end
    R.playerNames[id] = identity
    return identity
end
function grndRkPlayerIdentity(playerId, now)
    local R = GRND_RK
    local id = tonumber(playerId)
    if not id or id < 0 or id > 1003 then return nil end
    now = now or grndRkNow()
    R.playerNames = R.playerNames or {}
    local cached = R.playerNames[id]
    if cached and now >= cached.at and now - cached.at < 2.0 then return cached end
    local name = grndRkPlayerName(id)
    if name then return grndRkRememberPlayer(id, name, now) end
    if cached then cached.at = now; return cached end
    local fallback = { name = nil, key = "id:" .. tostring(id), at = now }
    R.playerNames[id] = fallback
    return fallback
end
function grndRkPlayerLabel(id)
    local identity = grndRkPlayerIdentity(id)
    return (identity and identity.name) or ("ID " .. tostring(tonumber(id) or id))
end
function grndRkVictimLabel(name, playerId, includeId)
    local id = tostring(tonumber(playerId) or playerId or "?")
    if type(name) ~= "string" or name == "" then name = "ID " .. id end
    if includeId and name ~= ("ID " .. id) then return name .. "[" .. id .. "]" end
    return name
end
function grndRkSayHospital(name, playerId)
    grndRkSay("[RK] Игрок >> " .. grndRkVictimLabel(name, playerId, true)
        .. " попал в больницу!", 0xFFFF4444)
end
function grndRkSayReturned(name, playerId)
    grndRkSay("[RK] Игрок >> " .. grndRkVictimLabel(name, playerId, false)
        .. " пришел обратно после смерти!", 0xFFFF4444)
end
function grndRkClearObservations()
    local R = GRND_RK
    R.pending, R.watched, R.positions = {}, {}, {}
    R.lastDeath, R.deathCounts, R.playerNames, R.roster = {}, {}, {}, {}
    R.scanCursor, R.scanNextAt, R.rosterPruneAt = 0, 0, 0
    R.localInsideTerritory, R.areaArmed = nil, false
end
function grndRkClearEvent(waitForTerritoryExit)
    GRND_RK.eventActive = false
    GRND_RK.waitForTerritoryExit = waitForTerritoryExit and true or false
    grndRkClearObservations()
end
function grndRkClearPlayer(playerId)
    local R = GRND_RK
    local id = tonumber(playerId)
    if not id or id < 0 or id > 1003 then return end
    local identity = R.playerNames[id]
    local roster = identity and R.roster and R.roster[identity.key]
    if roster and roster.id == id then roster.streamedOutAt = grndRkNow() end
    R.positions[id], R.playerNames[id] = nil, nil
end
function grndRkForgetDisconnectedPlayer(playerId)
    local R = GRND_RK
    local id = tonumber(playerId)
    if not id or id < 0 or id > 1003 then return end
    local identity = R.playerNames[id]
    local position = R.positions[id]
    local key = identity and identity.key or position and position.key
    if not key then
        for candidateKey, row in pairs(R.roster or {}) do
            if row and tonumber(row.id) == id then key = candidateKey; break end
        end
    end
    if not key then
        for candidateKey, row in pairs(R.pending or {}) do
            if row and tonumber(row.id) == id then key = candidateKey; break end
        end
        if not key then
            for candidateKey, row in pairs(R.watched or {}) do
                if row and tonumber(row.id) == id then key = candidateKey; break end
            end
        end
    end
    if key then
        R.pending[key], R.watched[key], R.roster[key] = nil, nil, nil
        R.lastDeath[key], R.deathCounts[key] = nil, nil
    end
    R.positions[id], R.playerNames[id] = nil, nil
end
function grndRkLocalPlayerId()
    local ped = rawget(_G, "PLAYER_PED")
    if type(ped) == "number" and type(sampGetPlayerIdByCharHandle) == "function" then
        local ok, first, second = pcall(sampGetPlayerIdByCharHandle, ped)
        if ok then
            if type(first) == "number" then return first end
            if first and type(second) == "number" then return second end
        end
    end
    if type(sampGetLocalPlayerId) == "function" then
        local ok, id = pcall(sampGetLocalPlayerId)
        if ok and type(id) == "number" then return id end
    end
    return nil
end
function grndRkRememberLocalPosition()
    local R = GRND_RK
    if not R or R.areaArmed ~= true then return false end
    local playerId = tonumber(grndRkLocalPlayerId())
    if not playerId or playerId < 0 or playerId > 1003 or playerId ~= math.floor(playerId) then
        return false
    end
    local x, y, z = grndRkPosition()
    if not x then return false end
    local now = grndRkNow()
    local identity = grndRkPlayerIdentity(playerId, now)
    if not identity then return false end
    R.positions[playerId] = { x = x, y = y, z = z, at = now,
        key = identity.key, name = identity.name }
    return true
end
function grndRkMonitoring()
    local R = GRND_RK
    if not R or R.enabled ~= true then return false end
    local inside = grndRkLocalInsideTerritory()
    R.localInsideTerritory = inside
    if R.waitForTerritoryExit == true then
        if not inside then R.waitForTerritoryExit = false end
        return false
    end
    if inside and R.areaArmed ~= true then
        -- Entering the configured event polygon silently starts this event's monitoring.
        grndRkClearObservations()
        R.localInsideTerritory, R.areaArmed, R.eventActive = true, true, true
    end
    if R.areaArmed == true then grndRkRememberLocalPosition() end
    return R.areaArmed == true
end
function grndRkScanVisiblePlayers(force)
    local R = GRND_RK
    if not R or R.enabled ~= true or R.areaArmed ~= true
        or R.waitForTerritoryExit == true then return 0 end
    if type(sampGetCharHandleBySampPlayerId) ~= "function"
        or type(getCharCoordinates) ~= "function" then return 0 end
    local now = grndRkNow()
    if not force and now < (tonumber(R.scanNextAt) or 0) then return 0 end
    R.scanNextAt = now + 0.15
    -- Rotate through player IDs in bounded slices; only currently available streamed peds can be sampled.
    local maxId = 1003
    if type(sampGetMaxPlayerId) == "function" then
        local okMax, result = pcall(sampGetMaxPlayerId)
        if okMax and tonumber(result) then maxId = math.floor(tonumber(result)) end
    end
    maxId = math.max(0, math.min(1003, maxId))
    local total = maxId + 1
    local cursor = math.floor(tonumber(R.scanCursor) or 0) % total
    local budget = math.min(64, total)
    local localId = tonumber(grndRkLocalPlayerId())
    local sampled = 0
    for offset = 0, budget - 1 do
        local id = (cursor + offset) % total
        if id ~= localId then
            local connected = true
            if type(sampIsPlayerConnected) == "function" then
                local okConn, isConnected = pcall(sampIsPlayerConnected, id)
                connected = okConn and isConnected and true or false
            end
            if connected then
                local okHandle, first, second = pcall(sampGetCharHandleBySampPlayerId, id)
                local ped
                if okHandle then
                    if type(first) == "number" and first > 0 then ped = first
                    elseif first and type(second) == "number" and second > 0 then ped = second end
                end
                if ped then
                    local exists = true
                    if type(doesCharExist) == "function" then
                        local okExists, result = pcall(doesCharExist, ped)
                        exists = okExists and result and true or false
                    end
                    if exists then
                        local okPos, x, y, z = pcall(getCharCoordinates, ped)
                        x, y, z = tonumber(x), tonumber(y), tonumber(z)
                        if okPos and x and y and z then
                            grndRkObservePosition(id, { x = x, y = y, z = z }, true)
                            sampled = sampled + 1
                        end
                    end
                end
            end
        end
    end
    R.scanCursor = (cursor + budget) % total
    if now >= (tonumber(R.rosterPruneAt) or 0) then
        R.rosterPruneAt = now + 5.0
        for key, player in pairs(R.roster or {}) do
            local age = now - (tonumber(player.seenAt) or 0)
            if age > 15 and not R.pending[key] and not R.watched[key] then
                R.roster[key] = nil
            end
        end
    end
    R.lastScanAt, R.lastScanCount = now, sampled
    return sampled
end
function grndRkSetEnabled(on, quiet)
    local R = GRND_RK
    R.enabled = on and true or false
    _G.GRND_RK_ENABLED = R.enabled
    if not R.enabled then
        R.testMode = false
        grndRkClearObservations()
    end
    if type(grndCamCfgSave) == "function" then pcall(grndCamCfgSave) end
    if not quiet then
        grndRkSay(R.enabled and "[RK] Чекер включён." or "[RK] Чекер выключен.", 0xFFFF5555)
    end
end
function grndRkSetTestMode(on)
    local R = GRND_RK
    on = on and true or false
    if on and not R.enabled then grndRkSetEnabled(true, true) end
    if on ~= R.testMode then
        grndRkClearObservations()
        R.testMode = on
        if on then R.waitForTerritoryExit = false end
    end
end
function grndRkIsFamilyWarEnd(text)
    if type(text) ~= "string" or not text:find("[Семейные войны]", 1, true) then return false end
    if text:find("выиграла войну", 1, true) or text:find("выиграли войну", 1, true) then
        return true
    end
    local hasEndWord = text:find("заверш", 1, true) or text:find("оконч", 1, true)
        or text:find("законч", 1, true)
    return hasEndWord ~= nil and text:find("войн", 1, true) ~= nil
end
function grndRkOnServerMessage(text)
    local R = GRND_RK
    if type(text) ~= "string" then return end
    if type(grndToUtf) == "function" then
        local okUtf, converted = pcall(grndToUtf, text)
        if okUtf and type(converted) == "string" then text = converted end
    end
    if text:find("[Семейные войны] Началась война семей", 1, true) then
        grndRkClearObservations()
        R.waitForTerritoryExit = false
        R.eventActive = true
        return
    end
    if grndRkIsFamilyWarEnd(text) then
        grndRkClearEvent(true)
    end
end
function grndRkObservePosition(playerId, pos, monitoringAlreadyChecked)
    local R = GRND_RK
    if R.waitForTerritoryExit == true then return end
    playerId = tonumber(playerId)
    if not playerId or playerId < 0 or playerId > 1003 then return end
    local function coord(axis)
        local ok, value = pcall(function() return pos[axis] end)
        if not ok then return nil end
        local okNum, num = pcall(tonumber, value)
        if okNum then return num end
        return nil
    end
    local x, y, z = coord("x"), coord("y"), coord("z")
    if not x or not y or not z or x ~= x or y ~= y or z ~= z
        or math.abs(x) > 20000 or math.abs(y) > 20000 or math.abs(z) > 20000 then return end
    local now = grndRkNow()
    if R.enabled ~= true then return end
    local monitoring = monitoringAlreadyChecked == true or grndRkMonitoring()
    if R.waitForTerritoryExit == true then return end
    local inside = grndRkInsideTerritory(x, y)
    local identity = grndRkPlayerIdentity(playerId, now)
    if not identity then return end
    local key = identity.key
    if not monitoring then
        if not inside then R.positions[playerId] = nil; return end
        local record = R.positions[playerId]
        if not record or record.key ~= key then record = {}; R.positions[playerId] = record end
        record.id, record.key, record.name = playerId, key, identity.name
        record.x, record.y, record.z = x, y, z
        record.at, record.seenAt, record.inside = now, now, true
        return
    end
    local pending = R.pending[key]
    local watched = R.watched[key]
    local roster = R.roster[key]
    if inside or roster or pending or watched then
        local record = R.positions[playerId]
        if not record or record.key ~= key then record = {}; R.positions[playerId] = record end
        record.id, record.key, record.name = playerId, key, identity.name
        record.x, record.y, record.z = x, y, z
        record.at, record.seenAt, record.inside, record.streamedOutAt = now, now, inside, nil
        if inside then
            if not roster then roster = {}; R.roster[key] = roster end
            roster.id, roster.key, roster.name = playerId, key, identity.name
            roster.x, roster.y, roster.z = x, y, z
            roster.at, roster.seenAt, roster.inside, roster.outsideAt, roster.streamedOutAt = now, now, true, nil, nil
        elseif roster then
            roster.id, roster.name, roster.x, roster.y, roster.z = playerId, identity.name or roster.name, x, y, z
            roster.at, roster.seenAt, roster.inside, roster.outsideAt, roster.streamedOutAt = now, now, false, now, nil
        end
    else
        R.positions[playerId] = nil
        return
    end
    if pending then
        pending.id, pending.name = playerId, identity.name or pending.name
        if not inside then
            pending.outsideObserved = true
            pending.returnedDuringWindow = false
        elseif pending.outsideObserved then
            pending.returnedDuringWindow = true
        elseif now >= pending.deadline then
            pending.insideAfterGrace = true
        end
    end
    if watched then
        watched.id, watched.name = playerId, identity.name or watched.name
        local displayName = identity.name or watched.name
        if watched.awaitingExit then
            if not inside then
                grndRkSayHospital(displayName, playerId)
                watched.outside, watched.awaitingExit = true, nil
                watched.hospitalNotified = true
                watched.hospitalCandidate = false
            else
                -- A stream gap alone is not evidence of a hospital trip; only synced coordinates count.
                watched.outside, watched.awaitingExit = false, nil
            end
        elseif inside and watched.outside then
            grndRkSayReturned(displayName, playerId)
            watched.outside, watched.hospitalNotified = false, nil
        elseif not inside then
            if watched.deathAt and not watched.hospitalNotified then
                grndRkSayHospital(displayName, playerId)
                watched.hospitalNotified = true
            end
            watched.outside = true
        end
    end
end
function grndRkOnPlayerSync(playerId, data)
    local ok, pos = pcall(function() return data.position end)
    if ok then grndRkObservePosition(playerId, pos) end
end
function grndRkOnPlayerStreamIn(playerId, position)
    grndRkObservePosition(playerId, position)
end
function grndRkOnPlayerStreamOut(playerId)
    if GRND_RK.waitForTerritoryExit == true then return end
    local id = tonumber(playerId)
    if id and id >= 0 and id <= 1003 then
        local now = grndRkNow()
        local identity = grndRkPlayerIdentity(id, now)
        local roster = identity and GRND_RK.roster[identity.key]
        if roster and roster.id == id then
            -- Keep the last in-territory, nickname-keyed snapshot, but never infer a hospital from stream-out.
            roster.streamedOutAt = now
        end
        GRND_RK.positions[id] = nil
    end
end
function grndRkOnDeath(killerId, killedId)
    local R = GRND_RK
    killerId, killedId = tonumber(killerId), tonumber(killedId)
    if not grndRkMonitoring() or type(R.polygon) ~= "table" or #R.polygon < 3
        or not killerId or not killedId or killerId < 0 or killedId > 1003
        or killerId == killedId or killedId < 0 or killedId > 1003 then return end
    local now = grndRkNow()
    local victimIdentity = grndRkPlayerIdentity(killedId, now)
    local killerIdentity = grndRkPlayerIdentity(killerId, now)
    if not victimIdentity or not killerIdentity then return end
    local victim = R.roster and R.roster[victimIdentity.key]
    local observedAt = victim and (tonumber(victim.seenAt) or tonumber(victim.at))
    if not victim or victim.id ~= killedId or victim.inside ~= true
        or victim.streamedOutAt ~= nil or not observedAt
        or now < observedAt or now - observedAt > 1.25
        or not grndRkInsideTerritory(victim.x, victim.y) then
        victim = R.positions[killedId]
        observedAt = victim and (tonumber(victim.seenAt) or tonumber(victim.at))
    end
    if not victim or victim.inside == false or not observedAt
        or now < observedAt or now - observedAt > 1.25
        or not grndRkInsideTerritory(victim.x, victim.y)
        or (victim.key and victim.key ~= victimIdentity.key
            and victim.key ~= ("id:" .. tostring(killedId))) then return end
    local key = victimIdentity.key
    if R.lastDeath[key] and now - R.lastDeath[key] < 0.35 then return end
    local victimName = victimIdentity.name or ("ID " .. killedId)
    local killerName = killerIdentity.name or ("ID " .. killerId)
    R.lastDeath[key] = now
    R.deathCounts[key] = (R.deathCounts[key] or 0) + 1
    if R.deathCounts[key] == 1 then
        grndRkSay("[RK] Игрока >> " .. grndRkVictimLabel(victimIdentity.name, killedId, true)
            .. " убил >> " .. killerName, 0xFFFF4444)
    else
        grndRkSay("[RK] Игрока >> " .. grndRkVictimLabel(victimIdentity.name, killedId, true)
            .. " повторно убил >> " .. killerName .. "!", 0xFFFF4444)
    end
    R.pending[key] = { key = key, id = killedId, name = victimName,
        deathAt = now, deadline = now + 2.0, origin = { x = victim.x, y = victim.y, z = victim.z },
        outsideObserved = false, returnedDuringWindow = false }
    R.watched[key] = nil
end
function grndRkEventTick()
    local R = GRND_RK
    if not grndRkMonitoring() then return end
    grndRkScanVisiblePlayers(false)
    local now = grndRkNow()
    for key, pending in pairs(R.pending) do
        if now >= pending.deadline then
            R.pending[key] = nil
            if pending.outsideObserved and pending.returnedDuringWindow then
                -- A short post-death leave and return inside the grace window is not a hospital trip.
                R.watched[key] = { outside = false, awaitingExit = true,
                    deathAt = pending.deathAt, name = pending.name, id = pending.id }
            elseif pending.outsideObserved then
                grndRkSayHospital(pending.name, pending.id)
                R.watched[key] = { outside = true, hospitalNotified = true,
                    name = pending.name, id = pending.id }
            else
                -- Missing sync / stream-out is inconclusive. Wait for actual coordinates outside the polygon.
                R.watched[key] = { outside = false, awaitingExit = true,
                    deathAt = pending.deathAt, name = pending.name, id = pending.id }
            end
        end
    end
end
function grndRkBorderWritePoint(mark)
    local B = GRND_RK and GRND_RK.border
    if not B or not B.active or not B.file then return false end
    local x, y, z = grndRkPosition()
    if not x then return false end
    local dx, dy, dz = x - (B.lastX or x), y - (B.lastY or y), z - (B.lastZ or z)
    local moved = math.sqrt(dx * dx + dy * dy + dz * dz)
    if not mark and B.count > 0 and moved < 0.35 then return false end
    local nowMs = 0
    if type(getGameTimer) == "function" then
        local ok, value = pcall(getGameTimer)
        if ok and type(value) == "number" then nowMs = math.floor(value) end
    end
    B.count = (B.count or 0) + 1
    local ok, err = pcall(function()
        local wrote, writeErr = B.file:write(('%d,%.3f,%.3f,%.3f,%s\n'):format(
            nowMs, x, y, z, mark and "M" or "P"))
        if not wrote then error(writeErr or "write failed") end
        local flushed, flushErr = B.file:flush()
        if not flushed then error(flushErr or "flush failed") end
    end)
    if not ok then
        grndRkSay("[RK] Ошибка записи границы: " .. tostring(err), 0xFFFF5555)
        pcall(function() B.file:close() end)
        B.file, B.active = nil, false
        return false
    end
    B.lastX, B.lastY, B.lastZ = x, y, z
    return true
end
function grndRkBorderCommand(params)
    local B = GRND_RK.border
    local arg = tostring(params or ""):lower():gsub("^%s*(.-)%s*$", "%1")
    if arg == "start" or arg == "начать" then
        if B.active then
            grndRkSay("[RK] Запись границы уже идёт. /rkborder stop — остановить.", 0xFFFFCC55)
            return
        end
        local okPath, path = pcall(grndStoragePath, "logs", "rk_border_capture.csv")
        if not okPath or type(path) ~= "string" then
            grndRkSay("[RK] Не удалось определить путь для лога границы.", 0xFFFF5555)
            return
        end
        local okFile, file = pcall(io.open, path, "w")
        if not okFile or not file then
            grndRkSay("[RK] Не удалось открыть файл записи границы.", 0xFFFF5555)
            return
        end
        B.file, B.active, B.count = file, true, 0
        B.lastX, B.lastY, B.lastZ = nil, nil, nil
        B.path, B.nextAt = path, 0
        pcall(function()
            file:write("# GRND_RK_BORDER_V1\n# game_ms,x,y,z,kind (P=path,M=manual mark)\n")
            file:flush()
        end)
        grndRkBorderWritePoint(true)
        grndRkSay("[RK] Запись границы начата. Обойдите периметр и вернитесь к началу; /rkborder mark — отметить угол, /rkborder stop — закончить.", 0xFFFF5555)
        return
    elseif arg == "mark" or arg == "точка" then
        if not B.active then
            grndRkSay("[RK] Сначала запустите /rkborder start.", 0xFFFFCC55)
            return
        end
        if grndRkBorderWritePoint(true) then
            grndRkSay("[RK] Угол границы записан.", 0xFFFF5555)
        else
            grndRkSay("[RK] Не удалось прочитать координаты игрока.", 0xFFFF5555)
        end
        return
    elseif arg == "stop" or arg == "стоп" or arg == "finish" then
        if not B.active then
            grndRkSay("[RK] Запись границы сейчас не идёт.", 0xFFFFCC55)
            return
        end
        grndRkBorderWritePoint(true)
        local file, path, count = B.file, B.path, B.count or 0
        B.file, B.active, B.nextAt = nil, false, nil
        if file then pcall(function() file:flush(); file:close() end) end
        grndRkSay(("[RK] Запись завершена: %d точек. Лог: %s"):format(count, tostring(path)), 0xFFFF5555)
        return
    elseif arg == "status" or arg == "статус" then
        if B.active then
            grndRkSay(("[RK] Идёт запись: %d точек. /rkborder stop — остановить."):format(B.count or 0), 0xFFFF5555)
        else
            grndRkSay("[RK] Запись границы выключена.", 0xFFFFCC55)
        end
        return
    end
    grndRkSay("[RK] Использование: /rkborder start | mark | stop | status", 0xFFFFCC55)
end
function grndRkBorderTick()
    local B = GRND_RK and GRND_RK.border
    if not B or not B.active then return end
    local now = grndRkNow()
    if now < (B.nextAt or 0) then return end
    B.nextAt = now + 0.20
    grndRkBorderWritePoint(false)
end
local grndToolCmdsReg = false
local function grndRegisterToolCmds()
    if grndToolCmdsReg then return end
    if type(sampRegisterChatCommand) ~= "function" then return end
    grndToolCmdsReg = true
    pcall(sampRegisterChatCommand, "invis", function()
        grndInvisToggle()
    end)
    pcall(sampRegisterChatCommand, "inv", function()
        grndInvisToggle()
    end)
    local function camCmd(arg)
        local a = tostring(arg or ""):gsub("^%s*(.-)%s*$", "%1")
        local num = tonumber(a)
        if num and num > 0 then
            GRND_CAM.enabled = true
            GRND_CAM.dist = math.max(2.0, math.min(50.0, num))
            GRND_CAM.cfgDirty = true
            pcall(grndCamCfgSave)
            if type(sampAddChatMessage) == "function" then
                pcall(grndChatSay, string.format(
                    "{00D6AA}[GRND]{FFFFFF} Камера отдалена: {00D6AA}%.1f м{FFFFFF}",
                    GRND_CAM.dist), -1)
            end
        else
            GRND_CAM.enabled = not GRND_CAM.enabled
            GRND_CAM.cfgDirty = true
            pcall(grndCamCfgSave)
            if type(sampAddChatMessage) == "function" then
                local st = GRND_CAM.enabled and "{00D6AA}ВКЛ{FFFFFF}" or "{FF6666}ВЫКЛ{FFFFFF}"
                pcall(grndChatSay, string.format(
                    "{00D6AA}[GRND]{FFFFFF} Отдаление камеры: %s (дистанция %.1f м)",
                    st, GRND_CAM.dist), -1)
            end
        end
    end
    pcall(sampRegisterChatCommand, "cam", camCmd)
    pcall(sampRegisterChatCommand, "camera", camCmd)
    pcall(sampRegisterChatCommand, "rkborder", grndRkBorderCommand)
    -- /softcheck: что видит список (доходят ли выстрелы, какой ствол и порог)
    pcall(sampRegisterChatCommand, "softcheck", function()
        local S = _G.GRND_SFR
        if type(S) ~= "table" or type(grndSfrDiag) ~= "function" then
            if type(grndChatSay) == "function" then
                pcall(grndChatSay, "{FF6666}[GRND]{FFFFFF} Список SOFT не загружен", -1)
            end
            return
        end
        local rows = grndSfrDiag()
        for i = 1, #rows do
            if type(grndChatSay) == "function" then
                pcall(grndChatSay, "{00D6AA}" .. tostring(rows[i]), -1)
            end
        end
    end)
    pcall(sampRegisterChatCommand, "modules", function()
        _G.grndModListTried = nil
        pcall(grndListModules, "команда /modules")
        if type(grndChatSay) == "function" then
            pcall(grndChatSay, "{00D6AA}[GRND]{FFFFFF} Список модулей записан в moonloader.log", -1)
        end
    end)
    pcall(sampRegisterChatCommand, "fovdiag", function()
        local ok, path = grndFovDiagnosticLog()
        if type(grndChatSay) == "function" then
            pcall(grndChatSay, ok
                and ("{00D6AA}[GRND]{FFFFFF} FOV-лог готов: " .. tostring(path) .. " — отправь этот файл")
                or ("{FF6666}[GRND]{FFFFFF} FOV-лог в moonloader.log: строки [GRND FOV-DIAG]. Файл: " .. tostring(path)), -1)
        end
    end)
    pcall(sampRegisterChatCommand, "camdiag", function(params)
        local argp = tostring(params or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
        if argp == "fov" or argp == "fov now" then
            local C = GRND_CAM
            local S = C.fovState
            local raw = "-"
            local base, M
            if S and S.base then
                base = S.base
                M = type(grndCamMem) == "function" and grndCamMem() or nil
            else
                local okB, b2, m2 = pcall(grndCamActiveBase)
                if okB then base, M = b2, m2 end
            end
            if base and M and type(M.rf) == "function" then
                local okR, v = pcall(M.rf, base + 0xB4)
                if okR and type(v) == "number" and v == v then
                    raw = string.format("%.1f", v)
                end
            end
            local hold = "-"
            if C.fovHoldUntil then
                hold = string.format("%.1fs", math.max(0, C.fovHoldUntil - grndCamNow()))
            end
            local hist = "-"
            if type(C.fovFixHist) == "table" and #C.fovFixHist > 0 then
                hist = table.concat(C.fovFixHist, ",")
            end
            local ctx = C.fovFixCtx
            local ctxs = "-"
            if type(ctx) == "table" then
                ctxs = string.format("машина:%d прицел:%d меню:%d",
                    ctx.car or 0, ctx.aim or 0, ctx.menu or 0)
            end
            local targetStr = C.fovAdopt
                and string.format("%.1f(подстройка)", C.fovAdopt) or tostring(C.fov)
            pcall(grndChatSay, string.format(
                "{00D6AA}[GRND]{FFFFFF} FOV: вкл=%s цель=%s память=%s наш=%s добор(5с)=%s/чужое=%s история=%s когда=%s пауза=%s why=%s",
                tostring(C.fovOn == true), targetStr, raw,
                S and string.format("%.1f", S.current) or "-",
                tostring(C.fovFixN or 0),
                C.fovFixLast and string.format("%.1f", C.fovFixLast) or "-",
                hist, ctxs, hold, tostring(C.fovWhy or "-")), -1)
            return
        end
        if GRND_CAM_DIAG.enabled then
            local ok,path=grndCamDiagStop("manual")
            if type(grndChatSay)=="function" then
                pcall(grndChatSay,"{00D6AA}[GRND]{FFFFFF} CamDiag ВЫКЛ. Лог: " .. tostring(path or "ошибка"),-1)
            end
        else
            local ok,path=grndCamDiagStart()
            if type(grndChatSay)=="function" then
                if ok then
                    pcall(grndChatSay,"{00D6AA}[GRND]{FFFFFF} CamDiag ВКЛ. Открой/закрой проблемные окна 2–3 раза, затем снова /camdiag. Файл: resource/grnd/logs/grnd_camera_diag.log",-1)
                else
                    pcall(grndChatSay,"{FF6666}[GRND]{FFFFFF} CamDiag не стартовала: " .. tostring(path),-1)
                end
            end
            if ok then print("[GRND camera diag] log: " .. tostring(path)) end
        end
    end)
end
