        grndSpecTargetUiCache.id, grndSpecTargetUiCache.ready = nil, false
        return false
    end
    id = tonumber(id) or tonumber(GS.id)
    if not id or tonumber(GS.id) ~= id then return false end
    local now = os.clock()
    if grndSpecTargetUiCache.id == id and now - grndSpecTargetUiCache.at < 0.10 then
        return grndSpecTargetUiCache.ready
    end
    local ready = specConnected(id)
    local ped = ready and grndSpecPedHandle(id) or nil
    if not ped or ped == PLAYER_PED then
        ready = false
    else
        if type(doesCharExist) == "function" then
            local okE, exists = pcall(doesCharExist, ped)
            if not okE or not exists then ready = false end
        end
        if ready and type(getCharCoordinates) == "function" then
            local okC, x, y, z = pcall(getCharCoordinates, ped)
            if not okC or type(x) ~= "number" or type(y) ~= "number"
                or type(z) ~= "number" or x ~= x or y ~= y or z ~= z
                or (math.abs(x - 50) < 0.001 and math.abs(y - 50) < 0.001
                    and math.abs(z - 50) < 0.001) then
                ready = false
            end
        end
    end
