    return nil
end
function grndSpecRoadTp(withCars)
    if not grndSpecInSpec() then
        notify.add("ТП на дорогу: слежка не активна", "warn", 3)
        return false
    end
    local pid = tonumber(GRND_SPEC.id)
    if not pid or type(sampGetCharHandleBySampPlayerId) ~= "function" then return false end
    local ped = grndSpecPedHandle(pid)
    if not ped or type(getCharCoordinates) ~= "function" then
        notify.add(("ТП на дорогу: игрок #%d не в зоне видимости"):format(pid), "warn", 3)
        return false
    end
    local inInt = grndGetTargetInterior(pid, ped)
    if inInt == nil or inInt ~= 0 then
        notify.add("Скрипт не нашел ближайшую дорогу", "warn", 3)
        return false
    end
    local okC, px, py, pz = pcall(getCharCoordinates, ped)
    if not okC or type(px) ~= "number" then
        notify.add("Скрипт не нашел ближайшую дорогу", "warn", 3)
        return false
    end
    local R2 = SPEC_ROAD_RADIUS * SPEC_ROAD_RADIUS
    local function near(x, y, z)
        local dx, dy, dz = x - px, y - py, z - pz
        return dx * dx + dy * dy + dz * dz <= R2
    end
    local players = {}
    local cars = {}
    local carSeen = {}
    local function addCar(car, needNear)
        local okV, cx, cy, cz = pcall(getCarCoordinates, car)
        if not okV or type(cx) ~= "number" then return end
        if needNear and not near(cx, cy, cz) then return end
        local vid = grndSpecCarVid(car)
        if vid == nil or carSeen[vid] then return end
        carSeen[vid] = true
        cars[#cars + 1] = { vid = vid, x = cx, y = cy, z = cz }
    end
    local observedCar = withCars and grndSpecPlayerCar(ped) or nil
    if observedCar then
        addCar(observedCar, false)
    else
        players[#players + 1] = { id = pid, x = px, y = py, z = pz }
    end
    if withCars then
        for id = 0, 1003 do
            if id ~= pid then
                local h = grndSpecPedHandle(id)
                if h then
                    local car = grndSpecPlayerCar(h)
                    if car then
                        addCar(car, true)
                    else
                        local okQ, qx, qy, qz = pcall(getCharCoordinates, h)
                        if okQ and type(qx) == "number" and near(qx, qy, qz) then
                            players[#players + 1] = { id = id, x = qx, y = qy, z = qz }
                        end
                    end
                end
            end
        end
        if type(getCarCoordinates) == "function" then
            for vid = 0, 2000 do
                if not carSeen[vid] then
                    local h = grndSpecSampVehHandle(vid)
                    if h then
                        local okV, cx, cy, cz = pcall(getCarCoordinates, h)
                        if okV and type(cx) == "number" and near(cx, cy, cz) then
                            carSeen[vid] = true
                            cars[#cars + 1] = { vid = vid, x = cx, y = cy, z = cz }
                        end
                    end
                end
            end
        end
    end
    local pnx = GRND_SPEC_CAR_NODE_NEAR(px, py, pz)
    if not pnx then
        notify.add("Скрипт не нашел ближайшую дорогу", "warn", 3)
        return false
    end
    local msg
    if observedCar then
        msg = withCars and ("ТП на дорогу: т/с %d (игрок #%d в машине)"):format(#cars, pid)
            or ("ТП машины игрока #%d на дорогу"):format(pid)
    else
        msg = withCars and ("ТП на дорогу: игроков %d, т/с %d"):format(#players, #cars)
            or ("ТП игрока на дорогу: #%d"):format(pid)
    end
    notify.add(msg, "ok", 3)
    if lua_thread == nil or type(lua_thread.create) ~= "function" then return false end
    lua_thread.create(function()
        for _, pl in ipairs(players) do
            local nx, ny, nz = GRND_SPEC_CAR_NODE_NEAR(pl.x, pl.y, pl.z)
            if nx then
                pcall(sampSendChat, string.format(GRND_SPEC_PLAYER_CMD, pl.id, nx, ny, nz + 1.0))
                wait(300)
            end
        end
        for _, car in ipairs(cars) do
            local rx, ry, rz = GRND_SPEC_CAR_NODE_NEAR(car.x, car.y, car.z)
            if rx then
                pcall(sampSendChat, string.format(GRND_SPEC_VEH_CMD, car.vid, rx, ry, rz + 1.0))
                wait(300)
            end
        end
    end)
    return true
end
function grndSpecGotoTp()
    if not grndSpecInSpec() then
        notify.add("ТП к игроку: слежка не активна", "warn", 3)
        return false
    end
    local pid = tonumber(GRND_SPEC.id)
    if not pid or lua_thread == nil or type(lua_thread.create) ~= "function" then return false end
    lua_thread.create(function()
        pcall(sampSendChat, "/spoff")
        wait(1000)
        pcall(sampSendChat, "/goto " .. tostring(pid))
    end)
