local function grndSpecTrackCommand(cmd)
    local raw = tostring(cmd or "")
    local nowT = os.clock()
    if raw == specLastTrack and nowT - specLastTrackT < 1.0 then return end
    specLastTrack, specLastTrackT = raw, nowT
    local c = raw:gsub("^%s*/", ""):lower()
    local name, arg = c:match("^(%a+)%s*(%d*)")
    if not name then return end
    if SPEC_ON_CMDS[name] then
        local id = tonumber(arg)
        if id then
            if _G.GRND_RC then
                GRND_RC.reconHidden = false
                GRND_RC.reconSeen = false
                GRND_RC.reconTdActive = false
                GRND_RC.reconMissingAt = nil
            end
            if not specConnected(id) then
                notify.add("Слежка не начата: игрока #" .. id
                    .. " нет на сервере", "error", 5)
            else
                GRND_SPEC.active = true
                GRND_SPEC.id = id
                GRND_SPEC.cmdName = "/" .. name
                GRND_SPEC.manualExit = false
                GRND_SPEC.confirmT = os.clock()
                if _G.GRND_RC then
                    _G.GRND_RC.id = id
                    _G.GRND_RC.show = true
                    _G.GRND_RC.reconHidden = false
                    _G.GRND_RC.reconSeen = false
                    _G.GRND_RC.reconTdActive = false
                    _G.GRND_RC.reconMissingAt = nil
                end
                if type(_G.grndEnsureRender) == "function" then
                    pcall(_G.grndEnsureRender, true)
                end
                if type(sampGetPlayerNickname) == "function" then
                    local ok, n = pcall(sampGetPlayerNickname, id)
                    if ok and type(n) == "string" and n ~= "" then
                        GRND_SPEC.nick = specCp2Utf(n)
                    end
                end
                if GRND_SPEC.isAutoRefreshing then
                    GRND_SPEC.isAutoRefreshing = false
                else
                    if _G.GRND_SPEC_AUTOREF then
                        _G.GRND_SPEC_AUTOREF.manualExit = false
                        _G.GRND_SPEC_AUTOREF.lastTargetId = id
                        _G.GRND_SPEC_AUTOREF.lastTargetNick = GRND_SPEC.nick or ""
                        _G.GRND_SPEC_AUTOREF.lostSince = nil
                        _G.GRND_SPEC_AUTOREF.refreshCount = 0
                        _G.GRND_SPEC_AUTOREF.graceUntil = os.clock() + 2.5
                    end
                    local who = "#" .. id .. (GRND_SPEC.nick ~= "" and (" (" .. GRND_SPEC.nick .. ")") or "")
                end
            end
        elseif GRND_SPEC.active then
            GRND_SPEC.active = false
            GRND_SPEC.id = nil
            GRND_SPEC.nick = ""
            GRND_SPEC.confirmT = 0
            GRND_SPEC.manualExit = true
            if _G.GRND_SPEC_AUTOREF then
                _G.GRND_SPEC_AUTOREF.manualExit = true
                _G.GRND_SPEC_AUTOREF.lastTargetId = nil
                _G.GRND_SPEC_AUTOREF.lostSince = nil
                _G.GRND_SPEC_AUTOREF.refreshCount = 0
            end
        end
    elseif SPEC_OFF_CMDS[name] then
        if GRND_SPEC.active then
            GRND_SPEC.active = false
            GRND_SPEC.id = nil
            GRND_SPEC.nick = ""
            GRND_SPEC.confirmT = 0
            GRND_SPEC.manualExit = true
            if _G.GRND_SPEC_AUTOREF then
                _G.GRND_SPEC_AUTOREF.manualExit = true
                _G.GRND_SPEC_AUTOREF.lastTargetId = nil
                _G.GRND_SPEC_AUTOREF.lostSince = nil
                _G.GRND_SPEC_AUTOREF.refreshCount = 0
            end
        end
    end
end
