function grndCamLosPoint(ax, ay, az, bx, by, bz)
    if type(processLineOfSight) ~= "function" then return nil end
    local function cast(x1, y1, z1, x2, y2, z2)
        local ok, hit, a, b, c = pcall(processLineOfSight,
            x1, y1, z1, x2, y2, z2,
            true,
            false,
            false,
            true,
            false,
            false,
            false,
            false)
