            end
            RC.actSubPopup = nil
        end
        afill(apX, boxY + 27, apW, 26, (apAct or apHov) and col32(TH.accent[1], TH.accent[2], TH.accent[3], 230) or col32(TH.accent[1], TH.accent[2], TH.accent[3], 180), 6)
        aframe(apX + 0.5, boxY + 27.5, apW - 1, 25, col32(255, 255, 255, 60), 6)
        local btxt = "Выдать броню"
        local btw = drawnWb(btxt, 0.86)
