            or (type(vehGetter) == "function" and vehGetter(tid, targetPed))
            or (RC.live and tonumber(RC.live.carId))
        local vInfo = vid and ("ID транспорта: #" .. tostring(vid)) or "т/с не обнаружен"
        uiText(AH_PAD + 14, boxY + 8, "Заправить т/с (" .. vInfo .. "):", c4(TH.textHi), 0.92)
        uiText(AH_PAD + 310, boxY + 7, tostring(math.floor(RC.actFuelVal)) .. " / 150 л", c4(TH.accent), 1.05)
