function grndSetBodyCam(pc)
    local CM = GRND_CAM
    local TH = pc.TH
    local RX = pc.w - 20
    local hi = grndSetCol(pc, TH.textHi)
    local muted = grndSetCol(pc, TH.textMuted)
    local accent = grndSetCol(pc, TH.accent)
    local camOn = (CM.enabled == true)
    grndSetText(pc, 16, 14, "Дистанция", hi, 1.0)
    local nd, chD = grndSetSlider(pc, 16, 40, RX - 16, CM.dist or 12.0, 2.0, 50.0, 0.5, "cam_dist")
    if chD then
        CM.dist = nd
        CM.cfgDirty = true
    end
    local dStr = string.format("%.1f м", CM.dist or 12.0)
    grndSetText(pc, RX - pc.tsize(dStr), 14, dStr, camOn and accent or muted, 1.0)
    grndSetText(pc, 16, 64, "2.0 м", muted, 0.8)
    local maxStr = "50.0 м"
    grndSetText(pc, RX - pc.tsize(maxStr) * 0.8, 64, maxStr, muted, 0.8)
    grndSetDivider(pc, 16, 88, RX - 16)
    local fovOn = (CM.fovOn == true)
    grndSetText(pc, 16, 100, "Рыбий глаз", hi, 1.0)
    grndSetText(pc, 16, 120, "расширенное поле зрения моей камеры, угол фиксированный", muted, 0.82)
    if pc.toggle(RX - 46, 98, fovOn, "cam_fov") then
        CM.fovOn = not fovOn
        if CM.fovOn then
            CM.fovApplied = nil
            CM.fovForeignWriter = nil
            CM.fovExtN, CM.fovExtAt = nil, nil
        end
        CM.fovAdopt = nil
        if type(grndFovWhy)=="function" then
            grndFovWhy(CM.fovOn and "тумблер: включён" or "тумблер: выключен")
        end
        CM.cfgDirty = true
    end
    local fStr = string.format("%.0f°", CM.fov or 100.0)
    grndSetText(pc, RX - 46 - 12 - pc.tsize(fStr), 102, fStr, fovOn and accent or muted, 0.92)
    local hint = fovOn and "применяется к вашей камере" or "включите рыбий глаз"
    grndSetText(pc, 16 + (RX - 16 - pc.tsize(hint) * 0.8) / 2, 150, hint, muted, 0.8)
    if CM.cfgDirty then grndSetSaveCfg() end
    return 172
end
function grndSetBodyChat(pc)
    local CH = GRND_CHAT
    local TH = pc.TH
    local RX = pc.w - 20
    local hi = grndSetCol(pc, TH.textHi)
    local muted = grndSetCol(pc, TH.textMuted)
    local dim = grndSetCol(pc, TH.textDim)
    local accent = grndSetCol(pc, TH.accent)
    local acc = TH.accent or { 164, 112, 224, 255 }
    local keyText = "[ " .. grndKeyName(CH.key or 0x54) .. " ]"
    local bindLabel = "Нажмите клавишу..."
    local kbOn = (CH.binding and true) or false
    local kbW = math.max(124, pc.tsize(kbOn and bindLabel or keyText) + 24)
    local kbX, kbY, kbH = RX - kbW, 8, 26
    grndSetText(pc, 16, 14, "Открытие чата", hi, 1.0)
    pc.im.SetCursorPos(pc.im.ImVec2(kbX, kbY))
    local hit = pc.im.InvisibleButton("##grnd_chat_keybind", pc.im.ImVec2(kbW, kbH)) and true or false
    local kHov = (pc.im.IsItemHovered and pc.im.IsItemHovered()) and true or false
    if hit then
        CH.binding = not CH.binding
        if CH.binding then
            if GRND_INVIS then GRND_INVIS.binding = false end
            if GRND_AREP then GRND_AREP.binding = false end
            if GRND_CATCH then GRND_CATCH.binding = false end
            if GRND_ABRK then GRND_ABRK.binding = false end
        end
        kbOn = (CH.binding and true) or false
    end
    local bg, edge
    if kbOn then
        bg = pc.col32(acc[1], acc[2], acc[3], 45)
        edge = pc.col32(acc[1], acc[2], acc[3], 255)
    elseif kHov then
        bg = pc.col32(255, 255, 255, 22)
        edge = pc.col32(255, 255, 255, 45)
    else
        bg = pc.col32(255, 255, 255, 12)
        edge = pc.col32(255, 255, 255, 20)
    end
    pc.roundRect(pc.dl, pc.at(kbX, kbY), pc.at(kbX + kbW, kbY + kbH), bg, 6)
    pcall(pc.dl.AddRect, pc.dl, pc.at(kbX, kbY), pc.at(kbX + kbW, kbY + kbH), edge, 6)
    local label = kbOn and bindLabel or keyText
    grndSetText(pc, kbX + (kbW - pc.tsize(label)) / 2, kbY + 6, label,
        kbOn and accent or (kHov and hi or dim), 0.92)
    grndSetText(pc, 16, 36, "клавиша, которая открывает строку ввода чата", muted, 0.82)
    local y1 = 58
    if kbOn then
        grndSetText(pc, 16, 56, "Нажмите любую клавишу.", accent, 0.85)
        grndSetText(pc, 16, 72, "ESC — отмена, Backspace/DEL — вернуть T", accent, 0.85)
        y1 = 92
    end
    grndSetDivider(pc, 16, y1, RX - 16)
    local r2 = y1 + 12
    local tsOn = (CH.timestamps and true) or false
    grndSetText(pc, 16, r2 + 5, "Время в чате", hi, 1.0)
    grndSetText(pc, 16, r2 + 26, "показывать [ЧЧ:ММ:СС] слева от сообщений", muted, 0.82)
    if pc.toggle(RX - 46, r2, tsOn, "chat_ts") then
        CH.timestamps = not tsOn
        pcall(grndChatStampApply)
        grndSetSaveCfg()
    end
    local st = tsOn and "вкл" or "выкл"
    grndSetText(pc, RX - 46 - 10 - pc.tsize(st), r2 + 5, st, tsOn and accent or muted, 1.0)
    grndSetDivider(pc, 16, r2 + 46, RX - 16)
    local r3 = r2 + 58
    local idsOn = (CH.ids ~= false)
    grndSetText(pc, 16, r3 + 5, "ID игроков в чате", hi, 1.0)
    grndSetText(pc, 16, r3 + 26, "добавлять [ID] к никам игроков онлайн", muted, 0.82)
    if pc.toggle(RX - 46, r3, idsOn, "chat_ids") then
        GRND_CHATID.setEnabled(CH.ids == false)
    end
    grndSetDivider(pc, 16, r3 + 46, RX - 16)
    local r4 = r3 + 58
    local lines = CH.lines or 10
    grndSetText(pc, 16, r4 + 2, "Строк в чате", hi, 1.0)
    local nl, chL = grndSetSlider(pc, 16, r4 + 24, RX - 16, lines, 10, 20, 1, "chat_lines")
    if chL then
        CH.lines = math.max(10, math.min(20, math.floor(nl + 0.5)))
        pcall(grndChatStampApply)
        grndSetSaveCfg()
    end
    local lStr = tostring(math.floor(CH.lines or 10))
    grndSetText(pc, RX - pc.tsize(lStr), r4 + 2, lStr, accent, 1.0)
    return r4 + 52
end
function grndSetBodyClock(pc)
    local C = GRND_CLOCK
    if not C then return 40 end
    local TH = pc.TH
    local hi = grndSetCol(pc, TH.textHi)
    local muted = grndSetCol(pc, TH.textMuted)
    local accent = grndSetCol(pc, TH.accent)
    local RX = pc.w - 20
    local rX = 16
    local rW = RX - rX
    if grndSetBtn(pc, rX, 10, rW, 30, "Изменить местоположение", "clock_move") then
        grndSetUiClose()
        grndClockStartMoving()
        return 154
    end

    grndSetText(pc, rX, 52, "Размер отображения", hi, 0.95)
    local scale = GRND_CLOCK.clampScale(C.scale)
    local ns, chS = pc.slider(rX, 76, rW, scale, 0.75, 4.00, 0.05, "clock_scale")
    if chS then
        C.scale = GRND_CLOCK.clampScale(ns)
        grndSetSaveCfg()
        if type(ensureRender) == "function" then pcall(ensureRender, true) end
    end
    scale = GRND_CLOCK.clampScale(C.scale)
    local px = math.max(9, math.min(52,
        math.floor((tonumber(GRND_FONT and GRND_FONT.fontBase) or 16) * scale + 0.5)))
    local value = string.format("%.2fx · %dpx", scale, px)
    grndSetText(pc, RX - pc.tsize(value), 52, value, accent, 0.92)
    grndSetText(pc, rX, 108,
        "Наведите курсор и нажмите ЛКМ, чтобы закрепить виджет",
        muted, 0.78)
    return 130
end
function grndSetBodyWH(pc)
    local W = GRND_WH
    local TH = pc.TH
    local RX = pc.w - 20
