end
function grndSetKeyButton(pc, rightX, y, S, id, onBind)
    local im = pc.im
    local TH = pc.TH
    local bnd = S.binding and true or false
    local label
    if bnd then
        label = "Нажмите клавишу..."
    elseif S.key then
        label = "[ " .. grndKeyName(S.key) .. " ]"
    else
        label = "[ Назначить клавишу ]"
    end
    local tw, th = pc.tsize(label)
    local w, h = math.max(150, tw + 24), 26
    local bx = rightX - w
    im.SetCursorPos(im.ImVec2(bx, y))
    local clicked = im.InvisibleButton("##set_key_" .. tostring(id), im.ImVec2(w, h)) and true or false
    local hov = (im.IsItemHovered and im.IsItemHovered()) and true or false
    if clicked then
        S.binding = not bnd
        if S.binding and type(onBind) == "function" then pcall(onBind) end
    end
    local ac = TH.accent or { 0, 214, 170, 255 }
    local bg = bnd and pc.col32(ac[1], ac[2], ac[3], 45)
        or (hov and pc.col32(255, 255, 255, 22) or pc.col32(255, 255, 255, 12))
    pc.roundRect(pc.dl, pc.at(bx, y), pc.at(bx + w, y + h), bg, 6)
    if pc.dl.AddRect then
        local bord = bnd and pc.col32(ac[1], ac[2], ac[3], 255)
            or (hov and pc.col32(255, 255, 255, 45) or pc.col32(255, 255, 255, 20))
        pcall(pc.dl.AddRect, pc.dl, pc.at(bx, y), pc.at(bx + w, y + h), bord, 6)
    end
    local col
    if bnd then col = grndSetCol(pc, ac)
    elseif hov then col = grndSetCol(pc, TH.textHi)
    else col = grndSetCol(pc, TH.textDim) end
    grndSetText(pc, bx + (w - tw) / 2, y + (h - th) / 2, label, col, 0.92)
    return clicked
end
function grndCheatBindClose()
