    end
    if grndSetBtn(pc, rX + b1w + 10, y, b2w, 28, "Обновить", "ao_now") then
        AO.nextAt = 0
        if not AO.enabled then
            AO.enabled = true
            AO.cfgDirty = true
        end
    end
    y = y + 40
