    local ni, chI = pc.slider(slX, y + 2, slW, interval, 3, 30, 1, "ao_int")
    if chI then
        AO.interval = math.max(3, math.min(30, math.floor(ni + 0.5)))
        AO.cfgDirty = true
    end
    local intStr = tostring(math.floor(tonumber(AO.interval) or 8)) .. " сек"
    grndSetText(pc, RX - pc.tsize(intStr), y + 4, intStr, accent, 0.92)
    y = y + 34
    local scBase = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16
    local valSc = tonumber(AO.scale) or 1.0
    grndSetText(pc, rX, y + 4, "Размер списка", hi, 0.95)
    local nsA, chSA = pc.slider(slX, y + 2, slW, valSc, 0.25, 2.5, 0.05, "ao_scale")
    if chSA then
        AO.scale = math.max(0.25, math.min(2.5, nsA))
        AO.cfgDirty = true
    end
    valSc = tonumber(AO.scale) or valSc
    local scPx = math.max(7, math.min(40, math.floor(scBase * valSc + 0.5)))
    local scStr = string.format("%.2fx · %dpx", valSc, scPx)
    grndSetText(pc, RX - pc.tsize(scStr), y + 4, scStr, accent, 0.92)
    y = y + 34
    y = y + 8
    grndSetText(pc, rX, y + 2, "Цвета по уровню", hi, 0.95)
    y = y + 24
    AO.lvlCol = AO.lvlCol or {}
    local sq, sg = 16, 4
    for lv = 1, 8 do
        local lab = tostring(lv) .. " уровень"
        grndSetText(pc, rX, y + 2, lab, grndSetCol(pc, TH.text), 0.90)
        local col = AO.lvlCol[lv]
        if type(col) ~= "table" then
            local d = AO_PALETTE[lv] or AO_PALETTE[1]
            col = { d[1], d[2], d[3] }
            AO.lvlCol[lv] = col
        end
        local sx = rX + math.max(96, pc.tsize(lab) + 12)
        for pi = 1, #AO_PALETTE do
            local pcol = AO_PALETTE[pi]
            local bx = sx + (pi - 1) * (sq + sg)
            if bx + sq <= RX then
                pc.im.SetCursorPos(pc.im.ImVec2(bx, y + 1))
                if pc.im.InvisibleButton("##ao_pc" .. lv .. "_" .. pi, pc.im.ImVec2(sq, sq)) then
                    AO.lvlCol[lv] = { pcol[1], pcol[2], pcol[3] }
                    AO.cfgDirty = true
                end
                local hovC = (pc.im.IsItemHovered and pc.im.IsItemHovered()) and true or false
                pc.roundRect(pc.dl, pc.at(bx, y + 2), pc.at(bx + sq, y + 2 + sq),
                    pc.col32(pcol[1], pcol[2], pcol[3], 255), 3)
                local sel = col[1] == pcol[1] and col[2] == pcol[2] and col[3] == pcol[3]
                if (sel or hovC) and pc.dl.AddRect then
                    pcall(pc.dl.AddRect, pc.dl, pc.at(bx, y + 2), pc.at(bx + sq, y + 2 + sq),
                        sel and pc.col32(255, 255, 255, 240) or pc.col32(255, 255, 255, 120), 3, 0,
                        sel and 1.8 or 1.1)
                end
            end
        end
        y = y + 24
    end
    return y + 6
end
