function grndSetBodyTracer(pc)
    local T = GRND_TRACER
    local TH = pc.TH
    local RX = pc.w - 20
    local hi = grndSetCol(pc, TH.textHi)
    local muted = grndSetCol(pc, TH.textMuted)
    local accent = grndSetCol(pc, TH.accent)
    local by = 12
    local function toggleRow(key, title)
        grndSetText(pc, 16, by + 5, grndSetFit(pc, title, RX - 16 - 62, 0.92), hi, 0.92)
        if pc.toggle(RX - 46, by + 2, T.cfg[key], "tr_" .. key) then
            T.cfg[key] = not T.cfg[key]
            if key == "rateCheck" then T.rates = {} end
            if key == "check" then
                T.suspects = {}
                T.lastAlert = nil
            end
            T.dirtyAt = os.clock()
        end
        by = by + 30
    end
    local function sliderRow(key, title, step, fmt)
        local b = T.bounds[key] or { 0, 1 }
        local v, changed = grndSetSlider(pc, 16, by + 24, RX - 16, T.cfg[key], b[1], b[2], step, "tr_" .. key)
        if changed then
            T.cfg[key] = v
            T.dirtyAt = os.clock()
        end
        grndSetText(pc, 16, by + 4, grndSetFit(pc, title, RX - 16 - 70, 0.92), hi, 0.92)
        local vs = string.format(fmt or "%.1f", T.cfg[key] or 0)
        grndSetText(pc, RX - pc.tsize(vs) * 0.9, by + 4, vs, accent, 0.9)
        by = by + 46
    end
    sliderRow("life", "Время следа, с", 0.5, "%.1f")
    sliderRow("width", "Толщина линии", 0.5, "%.1f")
    local sep = "-----SOFT-CHECK-----"
    grndSetText(pc, (pc.w - pc.tsize(sep) * 0.8) / 2, by + 6, sep, muted, 0.8)
    by = by + 30
    -- «Список на экране» — отдельное окно со всеми выстрелами (включая свои).
    -- Шестерёнка рядом открывает местоположение, размер и число строк.
    local SFR = _G.GRND_SFR
    local SU = _G.GRND_SETUI
    local listOn = (SFR and SFR.enabled) and true or false
    local listTitle = "Список на экране"
    grndSetText(pc, 16, by + 5, listTitle, hi, 0.92)
    if SFR and pc.toggle(RX - 46, by + 2, listOn, "soft_on") then
        SFR.enabled = not listOn
        SFR.cfgDirty = true
        if SFR.enabled and type(ensureRender) == "function" then
            pcall(ensureRender, true)
        end
    end
    if SFR then
        local gx = 16 + pc.tsize(listTitle) + 12
        local gy = by + 14 -- центр шестерёнки совпадает с центром тумблера строки
        local gClick, gHover = grndSetGear(pc, "soft", gx, gy,
            SU ~= nil and SU.key == "soft")
        local p = pc.at(gx, gy)
        if SU then
            SU.gears = SU.gears or {}
            SU.gears[#SU.gears + 1] = { x = p.x, y = p.y }
            if gHover then SU.gearHover = true end
        end
        if gClick then grndSetUiGear("soft", "admin", p.x, p.y) end
    end
    by = by + 30
    toggleRow("check", "Проверять прострелы")
    toggleRow("checkWalls", "Проверять стены / объекты")
    toggleRow("checkCars", "Проверять транспорт")
    grndSetText(pc, 16, by + 2, grndSetFit(pc,
        "Подозрение, НЕ доказательство софта или нанесённого урона.", RX - 16, 0.78),
        muted, 0.78)
    by = by + 24
    return by + 4
end
