local function esc(s)
    s = tostring(s or "")
    s = s:gsub("\\", "\\\\"):gsub("\r", ""):gsub("\n", "\\n")
    s = s:gsub("|", "\\p"):gsub("=", "\\e"):gsub(";", "\\s")
    return s
end
local function unesc(s)
    s = tostring(s or "")
    local out, i = {}, 1
    while i <= #s do
        local c = s:sub(i, i)
        if c == "\\" then
            local n = s:sub(i + 1, i + 1)
            if n == "n" then out[#out + 1] = "\n"
            elseif n == "\\" then out[#out + 1] = "\\"
            elseif n == "p" then out[#out + 1] = "|"
            elseif n == "e" then out[#out + 1] = "="
            elseif n == "s" then out[#out + 1] = ";"
            elseif n ~= "" then out[#out + 1] = n
            else out[#out + 1] = "\\" end
            i = i + 2
        else
            out[#out + 1] = c
            i = i + 1
        end
    end
    return table.concat(out)
end
local function rowsToStr(rows)
    local out = {}
    for _, v in ipairs(rows or {}) do out[#out + 1] = esc(v) end
    return table.concat(out, ";")
end
local function strToRows(s)
    local out, buf, i = {}, {}, 1
    s = tostring(s or "")
    local function add()
        local piece = unesc(table.concat(buf)):gsub("^%s+", ""):gsub("%s+$", "")
        if piece ~= "" and #out < MAX_ROWS then out[#out + 1] = piece end
        buf = {}
    end
    while i <= #s do
        local c = s:sub(i, i)
        if c == "\\" and i < #s then
            buf[#buf + 1] = c .. s:sub(i + 1, i + 1)
            i = i + 2
        elseif c == ";" then
            add(); i = i + 1
        else
            buf[#buf + 1] = c; i = i + 1
        end
    end
    add()
    return out
end
local function legacyCfgPath()
    local sep = package.config:sub(1, 1)
    local dir
    if type(thisScript) == "function" then
        pcall(function()
            local script = thisScript()
            if script then dir = tostring(script.path or ""):match("^(.*)[/\\]") end
        end)
    end
    if (not dir or dir == "") and type(getWorkingDirectory) == "function" then
        local ok, value = pcall(getWorkingDirectory)
        if ok and value and value ~= "" then dir = tostring(value) end
    end
    if (not dir or dir == "") and type(this_script_dir) == "function" then
        local ok, value = pcall(this_script_dir)
        if ok and value and value ~= "" then dir = tostring(value) end
    end
    dir = (dir or "."):gsub("[/\\]+$", "")
    -- Read an existing legacy file if present, but never create the folder.
    local folder = dir .. sep .. "grnd_tools"
    return folder .. sep .. "grnd_mp.cfg"
end
local function cfgPath()
    if type(GRND_CONFIG) == "table" and type(GRND_CONFIG.path) == "function" then
        local ok, jsonPath = pcall(GRND_CONFIG.path)
        if ok and type(jsonPath) == "string" and jsonPath ~= "" then
            local dir = jsonPath:match("^(.*)[/\\][^/\\]+$")
            if dir and dir ~= "" then
                local sep = package.config:sub(1, 1)
                return dir .. sep .. "grnd_mp.cfg"
            end
        end
    end
    return legacyCfgPath()
end
local LEGACY_CFG_PATH = legacyCfgPath()
MP.cfgPath = cfgPath()
MP.legacyCfgPath = LEGACY_CFG_PATH
local function splitEsc(line)
    local parts, i, n = {}, 1, #line
    local buf = {}
    while i <= n do
        local c = line:sub(i, i)
        if c == "\\" then
            buf[#buf + 1] = c .. line:sub(i + 1, i + 1)
            i = i + 2
        elseif c == "|" then
            parts[#parts + 1] = table.concat(buf)
            buf = {}
            i = i + 1
        else
            buf[#buf + 1] = c
            i = i + 1
        end
    end
    parts[#parts + 1] = table.concat(buf)
    return parts
end
local function presetLine(p)
    local t = {
        esc(p.name), esc(p.trigger),
        tostring(p.msgDelay), tostring(p.gap), tostring(p.ansDelay), tostring(p.tpDelay),
        tostring(p.cooldown), tostring(p.maxPlayers),
        p.takeGun and "1" or "0", p.takeArmor and "1" or "0",
        p.gunOn and "1" or "0", rowsToStr(p.gunRows),
        p.armorOn and "1" or "0", rowsToStr(p.armorRows),
        p.hpOn and "1" or "0", rowsToStr(p.hpRows),
        p.skinOn and "1" or "0", rowsToStr(p.skinRows),
    }
    for i, m in ipairs(p.messages or {}) do
        if i > MAX_MSG then break end
        t[#t + 1] = esc(m)
    end
    return "p=" .. table.concat(t, "|")
end
local function readPreset(line)
    local parts = splitEsc(line)
    local BASE = 18
    if #parts < BASE + 1 then
        if #parts >= 21 then
            parts = { parts[1], parts[2], unpack(parts, 5) }
        elseif #parts < 19 then
            return nil
        end
    end
    local messages = {}
    for j = BASE + 1, #parts do
        if #messages >= MAX_MSG then break end
        messages[#messages + 1] = unesc(parts[j])
    end
    local p = {
        name = unesc(parts[1]), trigger = unesc(parts[2]),
        msgDelay   = numOr(parts[3], 1.5, 0.1, 60),
        gap        = numOr(parts[4], 0.35, 0.05, 10),
        ansDelay   = numOr(parts[5], 1.2, 0, 60),
        tpDelay    = numOr(parts[6], 0.8, 0, 60),
        cooldown   = numOr(parts[7], 180, 0, 86400),
        maxPlayers = numOr(parts[8], 50, 1, 500),
        takeGun = parts[9] == "1", takeArmor = parts[10] == "1",
        gunOn   = parts[11] == "1", gunRows   = strToRows(parts[12]),
        armorOn = parts[13] == "1", armorRows = strToRows(parts[14]),
        hpOn    = parts[15] == "1", hpRows    = strToRows(parts[16]),
        skinOn  = parts[17] == "1", skinRows  = strToRows(parts[18]),
        messages = messages,
    }
    return p
end
local formSnapshot
local function applyPreset(p)
    if not p then return end
    MP.form.trigger   = p.trigger or ""
    MP.form.msgDelay  = numOr(p.msgDelay, 1.5, 0.1, 60)
    MP.form.gap       = numOr(p.gap, 0.35, 0.05, 10)
    MP.form.ansDelay  = numOr(p.ansDelay, 1.2, 0, 60)
    MP.form.tpDelay   = numOr(p.tpDelay, 0.8, 0, 60)
    MP.form.cooldown  = numOr(p.cooldown, 180, 0, 86400)
    MP.form.maxPlayers = math.floor(numOr(p.maxPlayers, 50, 1, 500))
    MP.take.gun   = p.takeGun and true or false
    MP.take.armor = p.takeArmor and true or false
    MP.give.gun   = { on = p.gunOn and true or false,   rows = copyList(p.gunRows, MAX_ROWS) }
    MP.give.armor = { on = p.armorOn and true or false, rows = copyList(p.armorRows, MAX_ROWS) }
    MP.give.hp    = { on = p.hpOn and true or false,    rows = copyList(p.hpRows, MAX_ROWS) }
    MP.give.skin  = { on = p.skinOn and true or false,  rows = copyList(p.skinRows, MAX_ROWS) }
    MP.form.messages = {}
    for i, m in ipairs(p.messages or {}) do
        if i > MAX_MSG then break end
        MP.form.messages[i] = m
    end
    MP.fields = {}
    MP.trigDirty = true
    MP.touch()
end
_G.grndMpApplyPreset = applyPreset
formSnapshot = function()
    local msgs = {}
    for i, m in ipairs(MP.form.messages) do
        if i > MAX_MSG then break end
        msgs[i] = m
    end
    return {
        trigger = MP.form.trigger,
        msgDelay = MP.form.msgDelay, gap = MP.form.gap,
        ansDelay = MP.form.ansDelay, tpDelay = MP.form.tpDelay,
        cooldown = MP.form.cooldown, maxPlayers = MP.form.maxPlayers,
        takeGun = MP.take.gun, takeArmor = MP.take.armor,
        gunOn = MP.give.gun.on,   gunRows   = copyList(MP.give.gun.rows, MAX_ROWS),
        armorOn = MP.give.armor.on, armorRows = copyList(MP.give.armor.rows, MAX_ROWS),
        hpOn = MP.give.hp.on,     hpRows    = copyList(MP.give.hp.rows, MAX_ROWS),
        skinOn = MP.give.skin.on, skinRows  = copyList(MP.give.skin.rows, MAX_ROWS),
        messages = msgs,
    }
end
function MP.currentForm()
    return MP.runtimeForm or formSnapshot()
end
function MP.savePreset(name)
    local nm = utfCut(cleanText(name), 32)
    if nm == "" then return false, "Введите название заготовки" end
    local snap = formSnapshot()
    snap.name = nm
    for i, p in ipairs(MP.presets) do
        if p.name == snap.name then
            MP.presets[i] = snap
            MP.presetName = ""
            MP.touch()
            return true, "Заготовка «" .. snap.name .. "» обновлена"
        end
    end
    if #MP.presets >= MAX_PRESETS then table.remove(MP.presets, 1) end
    MP.presets[#MP.presets + 1] = snap
    MP.presetName = ""
    MP.touch()
    return true, "Заготовка «" .. snap.name .. "» сохранена"
end
function MP.usePreset(index)
    local p = tonumber(index)
    p = p and MP.presets[p]
    if not p then
        for i, v in ipairs(MP.presets) do
            if v.name == tostring(index) then p = v break end
        end
    end
    if not p then return false, "Заготовка не найдена" end
    applyPreset(p)
    return true, "Заготовка «" .. tostring(p.name) .. "» загружена"
end
function MP.deletePreset(index)
    local i = tonumber(index)
    if not i or not MP.presets[i] then
        local want = tostring(index or "")
        for k, v in ipairs(MP.presets) do
            if v.name == want then i = k break end
        end
    end
    if not i or not MP.presets[i] then return false end
    local name = MP.presets[i].name
    table.remove(MP.presets, i)
    MP.touch()
    return true, "Заготовка «" .. tostring(name) .. "» удалена"
end
function MP.save()
    local body = { "ver=2" }
    for i, m in ipairs(MP.form.messages or {}) do
        if i > MAX_MSG then break end
        body[#body + 1] = "msg" .. i .. "=" .. esc(m)
    end
    local f = MP.form
    body[#body + 1] = "trigger=" .. esc(f.trigger)
    body[#body + 1] = "msgDelay=" .. tostring(f.msgDelay)
    body[#body + 1] = "gap=" .. tostring(f.gap)
    body[#body + 1] = "ansDelay=" .. tostring(f.ansDelay)
    body[#body + 1] = "tpDelay=" .. tostring(f.tpDelay)
    body[#body + 1] = "cooldown=" .. tostring(f.cooldown)
    body[#body + 1] = "maxPlayers=" .. tostring(f.maxPlayers)
    body[#body + 1] = "takeGun=" .. (MP.take.gun and "1" or "0")
    body[#body + 1] = "takeArmor=" .. (MP.take.armor and "1" or "0")
    local order = { "gun", "armor", "hp", "skin" }
    for _, key in ipairs(order) do
        local g = MP.give[key]
        body[#body + 1] = key .. "On=" .. (g.on and "1" or "0")
        body[#body + 1] = key .. "Rows=" .. rowsToStr(g.rows)
    end
    for _, preset in ipairs(MP.presets or {}) do
        body[#body + 1] = presetLine(preset)
    end
    local encoded = ansiText(table.concat(body, "\n") .. "\n")
    if #encoded > 2 * 1024 * 1024 then
        say("конфиг слишком большой и не сохранён", "error")
        return false
    end
    local path, tmp, bak = MP.cfgPath, MP.cfgPath .. ".tmp", MP.cfgPath .. ".bak"
    local hadOld = false
    local ok, err = pcall(function()
        local fh = assert(io.open(tmp, "wb"), "не удалось открыть временный конфиг")
        local wrote, why = fh:write(encoded)
        assert(wrote, why or "ошибка записи временного конфига")
        assert(fh:flush())
        assert(fh:close())
        local probe = io.open(path, "rb")
        if probe then
            hadOld = true
            probe:close()
            os.remove(bak)
            assert(os.rename(path, bak))
        end
        local moved, moveErr = os.rename(tmp, path)
        if not moved then
            if hadOld then pcall(os.rename, bak, path) end
            error(moveErr or "не удалось заменить конфиг")
        end
    end)
    if not ok then
        os.remove(tmp)
        say("не удалось сохранить настройки: " .. tostring(err), "error")
        return false
    end
    return true
end
function MP.load()
    if MP.loaded then return end
    MP.loaded = true
    local candidates = { MP.cfgPath }
    if MP.legacyCfgPath and MP.legacyCfgPath ~= MP.cfgPath then
        candidates[#candidates + 1] = MP.legacyCfgPath
    end
    local text, source
    for _, path in ipairs(candidates) do
        local ok, fh = pcall(io.open, path, "rb")
        if ok and fh then
            local okRead, data = pcall(fh.read, fh, 2 * 1024 * 1024 + 1)
            pcall(fh.close, fh)
            if okRead and type(data) == "string" and #data > 0
                and #data <= 2 * 1024 * 1024 then
                text, source = data, path
                break
            end
        end
    end
    if not text or text == "" then return end
    local presetBuf
    local function flushPreset()
        if not presetBuf then return end
        local preset = readPreset(presetBuf)
        if preset and preset.name ~= "" and #MP.presets < MAX_PRESETS then
            MP.presets[#MP.presets + 1] = preset
        end
        presetBuf = nil
    end
    for raw in (text .. "\n"):gmatch("([^\n]*)\n") do
        local line = toUtf((tostring(raw):gsub("\r$", "")))
        line = line:gsub("^\239\187\191", "")
        local k, v = line:match("^([%w_]+)=(.*)$")
        if k == "p" then
            flushPreset()
            presetBuf = v
        elseif presetBuf then
            flushPreset()
            k, v = line:match("^([%w_]+)=(.*)$")
        end
        if not presetBuf and k then
            if k == "trigger" then MP.form.trigger = unesc(v)
            elseif k == "msgDelay" then MP.form.msgDelay = numOr(v, 1.5, 0.1, 60)
            elseif k == "gap" then MP.form.gap = numOr(v, 0.35, 0.105, 60)
            elseif k == "ansDelay" then MP.form.ansDelay = numOr(v, 1.2, 0, 60)
            elseif k == "tpDelay" then MP.form.tpDelay = numOr(v, 0.8, 0, 60)
            elseif k == "cooldown" then MP.form.cooldown = numOr(v, 180, 0, 86400)
            elseif k == "maxPlayers" then MP.form.maxPlayers = math.floor(numOr(v, 50, 1, 500))
            elseif k == "takeGun" then MP.take.gun = (v == "1")
            elseif k == "takeArmor" then MP.take.armor = (v == "1")
            elseif k == "gunOn" then MP.give.gun.on = (v == "1")
            elseif k == "armorOn" then MP.give.armor.on = (v == "1")
            elseif k == "hpOn" then MP.give.hp.on = (v == "1")
            elseif k == "skinOn" then MP.give.skin.on = (v == "1")
            elseif k == "gunRows" then MP.give.gun.rows = strToRows(v)
            elseif k == "armorRows" then MP.give.armor.rows = strToRows(v)
            elseif k == "hpRows" then MP.give.hp.rows = strToRows(v)
            elseif k == "skinRows" then MP.give.skin.rows = strToRows(v)
            else
                local idx = k:match("^msg(%d+)$")
                if idx then
                    idx = tonumber(idx)
                    if idx and idx >= 1 and idx <= MAX_MSG then
                        MP.form.messages[#MP.form.messages + 1] = unesc(v)
                    end
                end
            end
        end
    end
    flushPreset()
    if source and source ~= MP.cfgPath then MP.dirtyAt = now() end
    MP.fields = {}
    MP.trigDirty = true
end
function MP.touch()
    MP.dirtyAt = now()
end
local function stripColors(s)
    if not s:find("{", 1, true) then return s end
    local out = s:gsub("{%x%x%x%x%x%x%x%x}", ""):gsub("{%x%x%x%x%x%x}", "")
    return out
end
local function findReportMarker(msg)
    local s, e, num = msg:find("%[[^%[%]]-репорта%s*:%s*(%d*)%s*%]")
    if not s then return nil end
    if num == "" then num = "1" end
    return num, s, e
end
function MP.parseReport(text)
    if type(text) ~= "string" or text == "" then return nil end
    if #text > 600 then return nil end
    local raw = stripColors(text)
    if not raw:find("%]%s*:") then return nil end
    local t = cleanText(toUtf(raw), 600)
    local nick, pid, msg = t:match("^(.-)%s*%[(%d+)%]%s*:%s*(.+)$")
    if not nick then return nil end
    nick = nick:gsub("^%s+", ""):gsub("%s+$", "")
    local numericId = tonumber(pid)
    if nick == "" or utfLen(nick) > 32 or not numericId or numericId < 0 or numericId > 1003 then
        return nil
    end
    local cnt, ms, me = findReportMarker(msg)
    if not cnt then return nil end
    msg = msg:sub(1, ms - 1) .. " " .. msg:sub(me + 1)
    msg = cleanText(msg, 600)
    if msg == "" then msg = "текст репорта" end
    return nick, numericId, msg, 1
end
function MP.connected()
    if type(isSampAvailable) == "function" then
        local ok, v = pcall(isSampAvailable)
        if ok and (v == false or v == 0) then return false end
    end
    if type(sampGetGamestate) == "function" then
        local ok, state = pcall(sampGetGamestate)
        state = ok and tonumber(state) or nil
        if state then return state == 3 end
    end
    if type(sampIsLocalPlayerConnected) == "function" then
        local ok, v = pcall(sampIsLocalPlayerConnected)
        if ok then return v == true or v == 1 end
    end
    return true
end
function MP.online(id)
    id = tonumber(id)
    if not id or id < 0 or id > 1003 then return false end
    if type(sampIsPlayerConnected) == "function" then
        local ok, v = pcall(sampIsPlayerConnected, id)
        if ok then return v == true or v == 1 end
    end
    return true
end
function MP.realNick(id)
    if type(sampGetPlayerNickname) ~= "function" then return nil end
    local idn = tonumber(id)
    if not idn or idn < 0 or idn > 1003 or type(sampIsPlayerConnected) ~= "function" then return nil end
    local okC, conn = pcall(sampIsPlayerConnected, idn)
    if not (okC and (conn == true or conn == 1)) then return nil end
    local ok, real = pcall(sampGetPlayerNickname, idn)
    if not ok or type(real) ~= "string" or real == "" then return nil end
    local s = cleanText(toUtf(real))
    if s == "" then return nil end
    return s
end
function MP.sameOwner(job)
    if not MP.online(job.id) then return false, "gone" end
    if job.real then
        local cur = MP.realNick(job.id)
        if cur and cur ~= job.real then return false, "taken" end
    end
    return true
end
function MP.send(cmd)
    if type(cmd) ~= "string" or cmd == "" then return false end
    if cmd:find(string.char(0), 1, true)
        or cmd:find(string.char(10), 1, true)
        or cmd:find(string.char(13), 1, true) then
        logIt("команда содержит недопустимый перенос — остановлено", "error")
        return false
    end
    local text = ansiText(cmd)
    if #text > MAX_CMD_BYTES then
        logIt("команда длиннее " .. tostring(MAX_CMD_BYTES) .. " байт — остановлено", "error")
        return false
    end
    local send = _G.grndChatSend
    if type(send) == "function" then
        local ok, res = pcall(send, cmd)
        return ok and res ~= false
    end
    if type(sampSendChat) ~= "function" then return false end
    local ok = pcall(sampSendChat, text)
    return ok
end
function MP.dryRun()
    local err = MP.validate()
    if err then
        MP.preview = { ok = false, at = now(), text = err }
        return false, err
    end
    local sample = { id = 261, nick = "Nik_Name" }
    local lines = {}
    for _, st in ipairs(MP.buildSteps(sample)) do
        local cmd = tostring(st.cmd)
        cmd = cmd:gsub("%%ID%%", function() return tostring(sample.id) end)
        cmd = cmd:gsub("%%NICK%%", function() return sample.nick end)
        lines[#lines + 1] = cmd
    end
    local ann = 0
    if MP.canUseMsg() then
        for _, m in ipairs(MP.form.messages) do
            if cleanText(m) ~= "" then ann = ann + 1 end
        end
    end
    MP.preview = { ok = true, at = now(), lines = lines, announce = ann,
        text = string.format("Форма в порядке: %d команд игроку, объявлений: %d",
            #lines, ann) }
    logIt("Проверка формы: " .. MP.preview.text, "ok")
    return true, MP.preview.text, lines
end
local CATS = {
    { key = "gun",   title = "Оружие",  hint = "ID оружия и патроны, например 31 200",
      pattern = "^(%d+)%s+(%d+)$", sample = "/gun ID 31 200" },
    { key = "armor", title = "Броня",   hint = "количество, например 100",
      pattern = "^(%d+)$", sample = "/arm ID 100" },
    { key = "hp",    title = "Здоровье", hint = "количество, например 100",
      pattern = "^(%d+)$", sample = "/hp ID 100" },
    { key = "skin",  title = "Скин",    hint = "ID скина, например 27",
      pattern = "^(%d+)$", sample = "/setskin ID 27" },
}
local CAT_CMD = {
    gun = "/gun %ID% %V%",
    armor = "/arm %ID% %V%",
    hp = "/hp %ID% %V%",
    skin = "/setskin %ID% %V%",
}
function MP.validate()
    local f = MP.form
    local trig = cleanText(f.trigger)
    if trig == "" then return "Укажите триггер — без него репорты не отфильтруются" end
    if utfLen(trig) > 32 then return "Триггер длиннее 32 символов" end
    if trig:find("[%z\r\n]") then return "Триггер содержит перенос строки" end
    if MP.canUseMsg() then
        local messages = {}
        for i = 1, math.min(#(f.messages or {}), MAX_MSG) do
            local t = cleanText(f.messages[i])
            if t ~= "" then
                t = utfCut(t, 120)
                if #ansiText(ANNOUNCE_CMD .. " " .. t) > MAX_CMD_BYTES then
                    return "Объявление №" .. tostring(i) .. " слишком длинное для чата"
                end
                messages[#messages + 1] = t
            end
        end
        f.messages = messages
    end
    for _, cat in ipairs(CATS) do
        local g = MP.give[cat.key]
        local one = ""
        for i = 1, math.min(#(g.rows or {}), MAX_ROWS) do
            local candidate = cleanText(g.rows[i])
            if candidate ~= "" then
                one = candidate
                break
            end
        end
        if g.on then
            local rows = {}
            local v = one:gsub("[;|\\]", " "):gsub("%s+", " ")
            v = v:gsub("^%s+", ""):gsub("%s+$", "")
            if v ~= "" then rows[1] = v end
            if #rows == 0 then
                return "Раздел «" .. cat.title .. "» включён, но данных нет"
            end
            for _, v in ipairs(rows) do
                local a, b = v:match("^(%d+)%s+(%d+)$")
                local n = tonumber(v)
                if cat.key == "gun" then
                    if not a or not b then
                        return cat.title .. ": нужно указать ID оружия и патроны"
                    end
                    if tonumber(a) < 1 or tonumber(a) > 46 then
                        return cat.title .. ": ID оружия должен быть от 1 до 46"
                    end
                    if tonumber(b) < 1 or tonumber(b) > 9999 then
                        return cat.title .. ": патроны должны быть от 1 до 9999"
                    end
                elseif cat.key == "armor" or cat.key == "hp" then
                    if not n or n < 0 or n > 1000 then
                        return cat.title .. ": значение должно быть числом от 0 до 1000"
                    end
                elseif cat.key == "skin" then
                    if not n or n < 0 or n > 311 then
                        return cat.title .. ": ID скина должен быть от 0 до 311"
                    end
                end
            end
            g.rows = rows
        else
            g.rows = one ~= "" and { one } or {}
        end
    end
    f.trigger    = trig
    f.msgDelay   = SEND_RATE
    f.gap        = SEND_RATE
    f.ansDelay   = SEND_RATE
    f.tpDelay    = SEND_RATE
    f.cooldown   = numOr(f.cooldown, 180, 0, 86400)
    f.maxPlayers = math.floor(numOr(f.maxPlayers, 50, 1, 500))
    MP.fields = {}
    MP.trigDirty = true
    MP.touch()
    return nil
end
function MP.buildSteps(job)
    local f = MP.currentForm()
    local gap = tonumber(f.gap) or SEND_RATE
    local steps = {}
    steps[#steps + 1] = { cmd = "/ans %ID% " .. ANSWER, pause = f.ansDelay }
    steps[#steps + 1] = { cmd = "/gethere %ID%", pause = f.tpDelay }
    if f.takeGun then steps[#steps + 1] = { cmd = "/rgun %ID%", pause = gap } end
    if f.takeArmor then steps[#steps + 1] = { cmd = "/arm %ID% 1", pause = gap } end
    local sections = {
        { key = "gun", on = f.gunOn, rows = f.gunRows },
        { key = "armor", on = f.armorOn, rows = f.armorRows },
        { key = "hp", on = f.hpOn, rows = f.hpRows },
        { key = "skin", on = f.skinOn, rows = f.skinRows },
    }
    for _, cat in ipairs(sections) do
        if cat.on then
            for _, row in ipairs(cat.rows or {}) do
                local v = tostring(row):gsub("%s+", " ")
                steps[#steps + 1] = {
                    cmd = (CAT_CMD[cat.key]:gsub("%%V%%", function() return v end)),
                    pause = gap,
                }
            end
        end
    end
    return steps
end
function MP.stop(reason)
    if not MP.active then return false end
    local lost = #MP.jobs + (MP.cur and 1 or 0)
    MP.active = false
    MP.watch = false
    MP.jobs, MP.cur, MP.announce = {}, nil, nil
    MP.lock = {}
    MP.runtimeForm = nil
    MP.nextAt = 0
    local text = reason or "МП остановлено"
    if lost > 0 then text = text .. " (" .. lost .. " в очереди снято)" end
    logIt(text, "warn")
    flash(text, "warn")
    say(text, "warn")
    MP.touch()
    return true
end
function MP.start()
    if MP.active then
        flash("МП уже запущено", "warn")
        return false
    end
    if type(grndUiBlocked) == "function" then
        local okBlocked, blocked = pcall(grndUiBlocked)
        if okBlocked and blocked then
            flash("МП нельзя запустить на экране авторизации", "error")
            return false
        end
    end
    local err = MP.validate()
    if err then
        flash(err, "error")
        logIt("Запуск отменён: " .. err, "error")
        return false
    end
    if not MP.connected() then
        flash("Нет подключения к серверу", "error")
        return false
    end
    if type(_G.grndChatSend) ~= "function" and type(sampSendChat) ~= "function" then
        flash("Нет функции отправки команд в чат", "error")
        return false
    end
    if not MP.chainReady and type(installHook) == "function" then
        local okCall, hooked = pcall(installHook)
        MP.hookOk = okCall and hooked == true
        if not MP.hookOk then
            flash("Не удалось подключить обработчик чата", "error")
            return false
        end
    end
    MP.runtimeForm = formSnapshot()
    local run = MP.runtimeForm
    if not MP.canUseMsg() then
        -- Old presets/configs may still contain announcements even though the
        -- MSG editor is hidden for this player.
        run.messages = {}
    end
    local t = now()
    MP.active = true
    MP.watch = false
    MP.startedAt = t
    MP.players, MP.sent, MP.done = 0, 0, 0
    MP.jobs, MP.cur, MP.lock = {}, nil, {}
    MP.nextAt = t
    MP.tokens, MP.lastTokenAt = PARSE_BURST, t
    MP.lastMessageText, MP.lastMessageAt = nil, -math.huge
    MP.trigCache, MP.trigCacheAt, MP.trigDirty = nil, nil, true
    MP.stat = { parsed = 0, matched = 0, skipped = 0, dropped = 0 }
    local steps = {}
    for _, m in ipairs(run.messages or {}) do
        local t2 = cleanText(m)
        if t2 ~= "" then
            steps[#steps + 1] = { cmd = ANNOUNCE_CMD .. " " .. t2, pause = run.msgDelay }
        end
    end
    if #steps > 0 then
        MP.announce = { steps = steps, step = 1 }
        logIt("Отправляю объявлений: " .. #steps, "info")
    else
        MP.announce = nil
        MP.watch = true
    end
    logIt("МП запущено, триггер: «" .. run.trigger .. "»", "ok")
    if not MP.hookOk and not MP.chainReady then
        logIt("перехват чата будет проверен автоматически", "info")
    end
    flash("МП запущено", "ok")
    MP.touch()
    return true
end
local function lockAdd(key)
    MP.lock[key] = (MP.lock[key] or 0) + 1
end
local function lockDel(key)
    local n = (MP.lock[key] or 0) - 1
    if n > 0 then MP.lock[key] = n else MP.lock[key] = nil end
end
local function finishJob(job)
    lockDel(job.key)
    MP.done = MP.done + 1
    MP.cur = nil
    logIt(job.nick .. " [" .. job.id .. "] — готово", "ok")
end
function MP.pump()
    if not MP.active then return end
    local t = now()
    if t < MP.nextAt then return end
    if not MP.connected() then
        MP.stop("Соединение потеряно")
        return
    end
    local job = MP.announce or MP.cur
    if not job then
        if #MP.jobs == 0 then
            MP.nextAt = t + 0.5
            return
        end
        job = table.remove(MP.jobs, 1)
        MP.cur = job
        job.step = 1
        if job.id then
            logIt(job.nick .. " [" .. job.id .. "] — в обработке")
        end
    end
    local st = job.steps[job.step]
    if not st then
        if job.id then
            finishJob(job)
        else
            MP.announce = nil
            MP.watch = true
            logIt("Объявления отправлены, слежение включено", "ok")
            flash("Слежение за репортом включено", "ok")
        end
        return
    end
    if job.id then
        if MP.lock[job.key] == nil then
            MP.cur = nil
            return
        end
        local owner, why = MP.sameOwner(job)
        if not owner then
            if why == "taken" then
                logIt(job.nick .. " [" .. job.id .. "] — ID занят другим игроком, отменено", "warn")
            else
                logIt(job.nick .. " [" .. job.id .. "] вышел — отменено", "warn")
            end
            lockDel(job.key)
            MP.players = math.max(0, (MP.players or 0) - 1)
            MP.cur = nil
            return
        end
    end
    if MP.announce and job == MP.announce and not MP.canUseMsg() then
        MP.announce = nil
        MP.watch = true
        logIt("Объявления /msg остановлены: уровень 5+ не подтверждён", "warn")
        return
    end
    local cmd = tostring(st.cmd):gsub("%%ID%%", function() return tostring(job.id or 0) end)
    if not MP.send(cmd) then
        MP.stop("Отправка команды не удалась")
        return
    end
    job.step = job.step + 1
    if job.id then
        MP.sent = MP.sent + 1
        MP.lastCmd = cmd
    end
    local gap = tonumber(st.pause) or 0
    MP.nextAt = t + math.max(SEND_RATE, gap)
end
function MP.recoverJob(err)
    local job = MP.cur or MP.announce
    if job then
        job.fails = (job.fails or 0) + 1
        if job.fails < 3 then
            logIt("сбой очереди МП, повтор (" .. job.fails .. " из 3): " .. tostring(err), "warn")
            MP.nextAt = now() + 0.5
            return
        end
        if job.key then
            lockDel(job.key)
            MP.players = math.max(0, (MP.players or 0) - 1)
            logIt(job.nick .. " [" .. job.id .. "] — снято после сбоев: " .. tostring(err), "warn")
        else
            logIt("объявления прерваны после сбоев: " .. tostring(err), "warn")
        end
    end
    MP.cur = nil
    if MP.announce then
        MP.announce = nil
        MP.watch = true
    end
    MP.nextAt = now() + 0.5
end
function MP.onServerMessage(text)
    MP.chainSeen, MP.chainReady, MP.hookOk = true, true, true
    if not MP.active then return end
    if type(text) ~= "string" or text == "" then return end
    local t = now()
    if #text > 600 then return end
    local raw = stripColors(text)
    if not raw:find("%]%s*:") then return end
    if not (raw:find("\240\229\239\238\240\242\224", 1, true)
            or raw:find("репорта", 1, true)) then
        return
    end
    local dt = t - (MP.lastTokenAt or t)
    if dt < 0 then dt = 0 end
    MP.tokens = math.min(PARSE_BURST, (MP.tokens or PARSE_BURST) + dt * PARSE_RATE)
    MP.lastTokenAt = t
    MP.stat = MP.stat or { parsed = 0, matched = 0, skipped = 0, dropped = 0 }
    if MP.tokens < 1 then
        MP.stat.dropped = MP.stat.dropped + 1
        if t - (MP.overflowAt or -math.huge) >= 5 then
            MP.overflowAt = t
            logIt("слишком много строк с маркером репорта — лишние пропущены", "warn")
        end
        return
    end
    MP.tokens = MP.tokens - 1
    local nick, id, msg, cnt = MP.parseReport(text)
    if not id then return end
    MP.stat.parsed = MP.stat.parsed + 1
    local run = MP.currentForm()
    local trig = MP.trigCache
    if trig == nil or MP.trigDirty or (t - (MP.trigCacheAt or 0)) > 2 then
        trig = lowerUtf(cleanText(run.trigger))
        MP.trigCache, MP.trigCacheAt, MP.trigDirty = trig, t, false
    end
    if trig == "" then return end
    if not lowerUtf(msg):find(trig, 1, true) then
        MP.stat.skipped = MP.stat.skipped + 1
        return
    end
    MP.stat.matched = MP.stat.matched + 1
    if not MP.online(id) then
        logIt(nick .. " [" .. id .. "] не в сети — репорт пропущен", "warn")
        return
    end
    local real = MP.realNick(id)
    local key = tostring(real or nick) .. "\1" .. tostring(id)
    if (#MP.jobs + (MP.cur and 1 or 0)) >= MAX_QUEUE then
        MP.stat.dropped = MP.stat.dropped + 1
        logIt("очередь переполнена — " .. nick .. " [" .. id .. "] пропущен", "warn")
        return
    end
    lockAdd(key)
    MP.players = MP.players + 1
    local job = { id = id, nick = nick, key = key, real = real, at = t, step = 1, cnt = cnt }
    job.steps = MP.buildSteps(job)
    MP.jobs[#MP.jobs + 1] = job
    logIt(nick .. " [" .. id .. "] — в очередь (" .. #MP.jobs .. "), репорт №" .. tostring(cnt))
end
local HOOKED = setmetatable({}, { __mode = "k" })
installHook = function()
    local ok, sampev = pcall(require, "samp.events")
    if not ok or not sampev then
        ok, sampev = pcall(require, "lib.samp.events")
    end
    if not ok or not sampev then return false end
    local prev = sampev.onServerMessage
    if type(prev) ~= "function" then prev = nil end
    if prev and HOOKED[prev] then
        MP.hookOk = true
        MP.chainReady = true
        return true
    end
    local function wrapper(color, text, ...)
        local r1, r2, r3
        if prev then r1, r2, r3 = prev(color, text, ...) end
        pcall(MP.onServerMessage, text)
        return r1, r2, r3
    end
    HOOKED[wrapper] = true
    sampev.onServerMessage = wrapper
    MP.hookOk = true
    return true
end
local bitLib = _G.bit
local function rgba(r, g, b, a)
    local im = _G.GRND_IM
    if im and im.ImVec4 then
        return im.ImVec4((tonumber(r) or 0) / 255, (tonumber(g) or 0) / 255,
            (tonumber(b) or 0) / 255, (tonumber(a) or 255) / 255)
    end
    return { r = r, g = g, b = b, a = a }
end
local function col32(r, g, b, a)
    a = a or 255
    r = math.floor(tonumber(r) or 0) % 256
    g = math.floor(tonumber(g) or 0) % 256
    b = math.floor(tonumber(b) or 0) % 256
    a = math.floor(tonumber(a) or 0) % 256
    if bitLib and bitLib.bor and bitLib.lshift then
        return bitLib.bor(r, bitLib.lshift(g, 8), bitLib.lshift(b, 16), bitLib.lshift(a, 24))
    end
    return r + g * 0x100 + b * 0x10000 + a * 0x1000000
end
local function roundRect(dl, p1, p2, col, rounding, flags)
    if rounding and rounding > 0 then
        local ok = pcall(dl.AddRectFilled, dl, p1, p2, col, rounding, flags or 0)
        if ok then return end
    end
    pcall(dl.AddRectFilled, dl, p1, p2, col)
end
local function frameRect(dl, p1, p2, col, rounding, thickness)
    if dl.AddRect then
        pcall(dl.AddRect, dl, p1, p2, col, rounding or 0, 0, thickness or 1)
    end
end
local HAS_MULTI = nil
local function gradRect(dl, p1, p2, c1, c2, rounding)
    if HAS_MULTI == nil then
        local im = _G.GRND_IM
        HAS_MULTI = (im and im.ImDrawList_AddRectFilledMultiColor) and true or false
    end
    if HAS_MULTI then
        local im = _G.GRND_IM
        if im.ImDrawList_AddRectFilledMultiColor then
            local ok = pcall(im.ImDrawList_AddRectFilledMultiColor, dl, p1, p2, c1, c2, c2, c1)
            if ok then return end
        end
    end
    local ok = pcall(dl.AddRectFilledMultiColor, dl, p1, p2, c1, c2, c2, c1)
    if ok then return end
    roundRect(dl, p1, p2, c1, rounding or 0)
end
local function tsizeOf(im, s)
    s = tostring(s or "")
    if im and im.CalcTextSize then
        local ok, r = pcall(im.CalcTextSize, s)
        if ok then
            local tp = type(r)
            if tp == "table" or tp == "cdata" then
                local xx, yy = tonumber(r and r.x), tonumber(r and r.y)
                if xx then return xx, yy or 14 end
            elseif tp == "number" then
                return r, 14
            end
        end
    end
    return utfLen(s) * 7, 14
end
local function uiTextFallback(im)
    return function(x, y, str, col, scale)
        im.SetCursorPos(im.ImVec2(x, y))
        if scale and scale ~= 1 and isFnV(im.SetWindowFontScale) then
            pcall(im.SetWindowFontScale, scale)
        end
        if im.TextUnformatted then im.TextUnformatted(tostring(str))
        else im.Text(tostring(str)) end
        if scale and scale ~= 1 and isFnV(im.SetWindowFontScale) then
            pcall(im.SetWindowFontScale, 1)
        end
    end
end
local function newBuf(im, cap)
    if im.new and im.new.char then
        local ok, b = pcall(function() return im.new.char[cap]() end)
        if ok and b then return b, "ffi" end
    end
    if type(im.ImBuffer) == "function" then
        local ok, b = pcall(im.ImBuffer, cap)
        if ok and b then return b, "legacy" end
    end
    return nil, nil
end
local function writeBuf(f, text)
    if f.kind == "ffi" then
        local w = _G.grndBinderWriteCBuf
        if type(w) == "function" then pcall(w, f.buf, f.cap, text) return end
        local ok, ffi = pcall(require, "ffi")
        if ok then
            pcall(function()
                ffi.fill(f.buf, f.cap, 0)
                if #text > 0 then ffi.copy(f.buf, text) end
            end)
        end
    else
        pcall(function() f.buf.v = text end)
    end
end
local function readBuf(f)
    if f.kind == "ffi" then
        local r = _G.grndBinderReadCBuf
        if type(r) == "function" then
            local ok, v = pcall(r, f.buf)
            if ok and type(v) == "string" then return v end
        end
        local ok, ffi = pcall(require, "ffi")
        if ok then
            local ok2, s = pcall(ffi.string, f.buf)
            if ok2 and type(s) == "string" then return (s:gsub("%z", "")) end
        end
        return ""
    end
    local ok, v = pcall(function() return f.buf.v end)
    if not ok or v == nil then ok, v = pcall(function() return f.buf.value end) end
    return (ok and v ~= nil) and tostring(v) or ""
end
local function fieldBuf(key, cap, value)
    local f = MP.fields[key]
    if f and (f.cap ~= cap or f.im ~= _G.GRND_IM) then f = nil end
    if not f then
        f = { cap = cap, im = _G.GRND_IM }
        local buf, kind = newBuf(_G.GRND_IM, cap)
        if not buf then return nil end
        f.buf, f.kind = buf, kind
        MP.fields[key] = f
    end
    value = tostring(value or "")
    if f.model == nil or f.model ~= value then
        writeBuf(f, value)
        f.model = value
    end
    return f
end
local function fieldSync(key)
    local f = MP.fields[key]
    if f then f.model = nil end
end
local function dropFields(prefix)
    for k in pairs(MP.fields) do
        if type(k) == "string" and k:sub(1, #prefix) == prefix then MP.fields[k] = nil end
    end
end
local theme
local INPUT_SIG = nil
local FIELD_H, FIELD_IM = nil, nil
local BIG_INPUT_H = 30
local MULTILINE_MIN_H = 40
local function itemRect(im, fbX, fbY, fbW, fbH)
    if type(im.GetItemRectMin) == "function" and type(im.GetItemRectMax) == "function" then
        local ok1, a = pcall(im.GetItemRectMin)
        local ok2, b = pcall(im.GetItemRectMax)
        local okp, p = pcall(im.GetWindowPos)
        if ok1 and ok2 and okp and a and b and p and a.x and b.x and p.x then
            return a.x - p.x, a.y - p.y, b.x - a.x, b.y - a.y
        end
    end
    return fbX, fbY, fbW, fbH
end
local function mpPushCol(im, idx, r, g, b, a)
    if not (im and im.PushStyleColor and idx ~= nil and im.ImVec4) then return false end
    local okC, col = pcall(im.ImVec4, r / 255, g / 255, b / 255, (a or 255) / 255)
    if not okC then return false end
    return pcall(im.PushStyleColor, idx, col)
end
local function mpPushVar2(im, idx, vx, vy)
    if not (im and idx ~= nil) then return false end
    local v
    if im.ImVec2 then
        local okV, vec = pcall(im.ImVec2, vx, vy)
        if okV then v = vec end
    end
    if not v then v = { x = vx, y = vy } end
    if im.PushStyleVarVec2 and pcall(im.PushStyleVarVec2, idx, v) then return true end
    if im.PushStyleVar and pcall(im.PushStyleVar, idx, v) then return true end
    return false
end
local function mpPushVarF(im, idx, val)
    if not (im and idx ~= nil) then return false end
    if im.PushStyleVarFloat and pcall(im.PushStyleVarFloat, idx, val) then return true end
    if im.PushStyleVar and pcall(im.PushStyleVar, idx, val) then return true end
    return false
end
local function mpPopCols(im, n)
    n = tonumber(n) or 0
    if not im or n <= 0 then return end
    for _ = 1, n do
        if not pcall(im.PopStyleColor, 1) then pcall(im.PopStyleColor) end
    end
end
local function mpPopVars(im, n)
    n = tonumber(n) or 0
    if not im or n <= 0 then return end
    for _ = 1, n do
        if not pcall(im.PopStyleVar, 1) then pcall(im.PopStyleVar) end
    end
end
local function textInput(ctx, key, id, cap, value, x, y, w, h, hint, onChange)
    local im = ctx.im
    local f = fieldBuf(key, cap, value)
    if not f then
        ctx.uiText(x + 2, y + 5, "поля ввода недоступны в этой сборке ImGui",
            ctx.c4({ 255, 120, 120, 255 }), 0.85)
        return tostring(value or "")
    end
    local fh = h
    local oy = y
    im.SetCursorPos(ctx.pos(x, oy))
    local inputW = math.floor(w)
    if im.SetNextItemWidth then pcall(im.SetNextItemWidth, inputW) end
    local pushedWidth = false
    if im.PushItemWidth then pushedWidth = pcall(im.PushItemWidth, inputW) end
    local useMultiline = h >= MULTILINE_MIN_H and type(im.InputTextMultiline) == "function"
    local multilineUsed = useMultiline
    local padN = 0
    if im.StyleVar and im.StyleVar.FramePadding and not useMultiline then
        if mpPushVar2(im, im.StyleVar.FramePadding, 9,
            math.max(2, math.floor((h - 14) / 2))) then padN = 1 end
    end
    local borderN = 0
    if im.StyleVar and im.StyleVar.FrameBorderSize then
        if mpPushVarF(im, im.StyleVar.FrameBorderSize, 1) then borderN = 1 end
    end
    local nCol = 0
    if im.Col then
        if mpPushCol(im, im.Col.FrameBg, 12, 15, 22, 255) then nCol = nCol + 1 end
        if mpPushCol(im, im.Col.FrameBgHovered, 18, 22, 31, 255) then nCol = nCol + 1 end
        if mpPushCol(im, im.Col.FrameBgActive, 21, 26, 36, 255) then nCol = nCol + 1 end
        if mpPushCol(im, im.Col.Text, 233, 237, 246, 255) then nCol = nCol + 1 end
        if mpPushCol(im, im.Col.Border, 255, 255, 255, 36) then nCol = nCol + 1 end
    end
    local function callMultiline()
        local sz = im.ImVec2(inputW, h)
        local function invoke(sig)
            if sig == 1 then return im.InputTextMultiline(id, f.buf, cap, sz, 0) end
            if sig == 2 then return im.InputTextMultiline(id, f.buf, cap, sz) end
            if sig == 3 then return im.InputTextMultiline(id, f.buf, sz, 0) end
            return im.InputTextMultiline(id, f.buf, sz)
        end
        local order
        if f.multiSig then
            order = { f.multiSig }
        elseif f.kind == "ffi" then
            order = { 1, 2, 3, 4 }
        else
            order = { 3, 4, 1, 2 }
        end
        local lastErr = "InputTextMultiline недоступен"
        for _, sig in ipairs(order) do
            local okM, result = pcall(invoke, sig)
            if okM then
                f.multiSig = sig
                return result
            end
            lastErr = result
            if f.multiSig then f.multiSig = nil end
        end
        error(lastErr)
    end
    local function call(sig, withHint)
        if useMultiline then
            return callMultiline()
        elseif withHint and hint and im.InputTextWithHint then
            local ok, r = pcall(im.InputTextWithHint, id, hint, f.buf, cap)
            if ok then return r end
            return im.InputTextWithHint(id, hint, f.buf)
        elseif sig == 1 then
            return im.InputText(id, f.buf, cap)
        else
            return im.InputText(id, f.buf)
        end
    end
    local ok, changed = pcall(call, INPUT_SIG or 1, true)
    if not ok and useMultiline then
        useMultiline = false
        multilineUsed = false
        ok, changed = pcall(call, INPUT_SIG or 1, true)
    end
    if not ok and INPUT_SIG == nil then
        ok, changed = pcall(call, 1, false)
    end
    if not ok and INPUT_SIG == nil then
        INPUT_SIG = 2
        ok, changed = pcall(call, 2, false)
    end
    if ok and INPUT_SIG == nil then INPUT_SIG = 1 end
    local rx, ry, rw, rh = itemRect(im, x, oy, w, fh)
    if rh and rh > 4 and rh < 200 and FIELD_IM ~= im then
        FIELD_H, FIELD_IM = rh, im
    elseif rh and rh > 4 and rh < 200 then
        FIELD_H = rh
    end
    if nCol > 0 and im.PopStyleColor then mpPopCols(im, nCol) end
    if (padN + borderN) > 0 and im.PopStyleVar then mpPopVars(im, padN + borderN) end
    if pushedWidth and im.PopItemWidth then pcall(im.PopItemWidth) end
    local hov, act = false, false
    if im.IsItemHovered then pcall(function() hov = im.IsItemHovered() and true or false end) end
    if im.IsItemActive then pcall(function() act = im.IsItemActive() and true or false end) end
    local accentCol = (theme().accent) or { 164, 112, 224, 255 }
    local edge = act and col32(accentCol[1], accentCol[2], accentCol[3], 190)
        or (hov and col32(255, 255, 255, 60) or col32(255, 255, 255, 30))
    if ctx.dl.AddRect then
        pcall(ctx.dl.AddRect, ctx.dl, ctx.at(rx + 0.5, ry + 0.5),
            ctx.at(rx + rw - 0.5, ry + rh - 0.5), edge, 6, 0, 1)
    end
    local vBefore = readBuf(f)
    if multilineUsed and hint and vBefore == "" then
        local hintFontH = tonumber(im.FontSize) or 14
        if hintFontH <= 0 then hintFontH = 14 end
        local hintY = oy + math.max(2, math.floor((h - hintFontH) / 2))
        ctx.uiText(x + 10, hintY, hint, ctx.c4(theme().textMuted), 0.88)
    end
    local v = vBefore
    local modelChanged = false
    if f.model == nil or v ~= f.model then
        f.model = v
        modelChanged = true
        if onChange then pcall(onChange, v) end
    end
    if not modelChanged and onChange and tostring(value or "") ~= v then
        pcall(onChange, v)
        modelChanged = true
    end
    if modelChanged then MP.touch() end
    return v
end
theme = function()
    local fn = _G.grndUiTheme
    if type(fn) == "function" then
        local ok, t = pcall(fn)
        if ok and type(t) == "table" then return t end
    end
    local k = _G.GRND_UIKIT
    if k and type(k.TH) == "table" then return k.TH end
    return {
        bg = { 18, 17, 23, 255 }, line = { 255, 255, 255, 20 },
        textHi = { 252, 250, 255, 255 }, text = { 234, 230, 244, 255 },
        textDim = { 198, 192, 216, 255 }, textMuted = { 172, 166, 190, 255 },
        accent = { 164, 112, 224, 255 }, accent2 = { 164, 112, 224, 255 },
    }
end
local function statusColor(kind)
    local TH = theme()
    if kind == "ok" then return { 120, 220, 150, 255 } end
    if kind == "warn" then return { 247, 176, 92, 255 } end
    if kind == "error" then return { 255, 120, 120, 255 } end
    return TH.accent or { 164, 112, 224, 255 }
end
local function trashIcon(ctx, cx, cy, col)
    local dl, at = ctx.dl, ctx.at
    pcall(dl.AddRectFilled, dl, at(cx - 3.5, cy - 3), at(cx + 3.5, cy + 4.5), col)
    pcall(dl.AddLine, dl, at(cx - 5, cy - 3), at(cx + 5, cy - 3), col, 1.3)
    pcall(dl.AddLine, dl, at(cx - 1.8, cy - 5), at(cx + 1.8, cy - 5), col, 1.3)
    pcall(dl.AddLine, dl, at(cx - 1.2, cy - 1), at(cx - 1.2, cy + 2.5), col, 1.1)
    pcall(dl.AddLine, dl, at(cx + 1.2, cy - 1), at(cx + 1.2, cy + 2.5), col, 1.1)
end
local function gearIcon(ctx, cx, cy, col)
    local dl, at = ctx.dl, ctx.at
    local rRoot, rTip = 3.8, 5.8
    local aRoot, aTip = math.rad(15), math.rad(7)
    local quad = dl.AddQuadFilled
    for i = 0, 7 do
        local c0 = i * math.pi / 4
        local p1 = at(cx + math.cos(c0 - aRoot) * rRoot, cy + math.sin(c0 - aRoot) * rRoot)
        local p2 = at(cx + math.cos(c0 - aTip) * rTip, cy + math.sin(c0 - aTip) * rTip)
        local p3 = at(cx + math.cos(c0 + aTip) * rTip, cy + math.sin(c0 + aTip) * rTip)
        local p4 = at(cx + math.cos(c0 + aRoot) * rRoot, cy + math.sin(c0 + aRoot) * rRoot)
        if quad then
            pcall(quad, dl, p1, p2, p3, p4, col)
        else
            pcall(dl.AddTriangleFilled, dl, p1, p2, p3, col)
            pcall(dl.AddTriangleFilled, dl, p1, p3, p4, col)
        end
    end
    if dl.AddCircle then
        pcall(dl.AddCircle, dl, at(cx, cy), 4.0, col, 32, 2.2)
        pcall(dl.AddCircle, dl, at(cx, cy), 1.3, col, 16, 1.6)
    end
end
local MP_HOVER = { id = nil, frame = -99 }
local function mpWindowHovered(im)
    if not (im and im.IsWindowHovered) then return true end
    local ok, over = pcall(im.IsWindowHovered)
    if not ok then return true end
    return over and true or false
end
local CLICK_GATE_MISS = 0
local function onClickReady()
    local fns = { _G.onClickReady, _G.grndOnClickReady, _G.onInputReady }
    local seen = false
    for i = 1, #fns do
        local f = fns[i]
        if type(f) == "function" then
            seen = true
            local ok, ready = pcall(f)
            if ok and ready == false then return false end
        end
    end
    if not seen then
        CLICK_GATE_MISS = CLICK_GATE_MISS + 1
        if CLICK_GATE_MISS == 1 then
            pcall(print, "{FFCC66}[GRND]{FFFFFF} панель МП: сборка не сообщает готовность ввода"
                .. " (onClickReady) — резервный клик по координате мыши")
        end
    end
    return true
end
local function hoverLayer(ctx, x, y, w, h, opts)
    local c = opts.danger and { 255, 96, 96 } or theme().accent
    roundRect(ctx.dl, ctx.at(x + 1, y + 1), ctx.at(x + w - 1, y + h - 1),
        col32(c[1], c[2], c[3], 46), 6)
    frameRect(ctx.dl, ctx.at(x + 0.5, y + 0.5), ctx.at(x + w - 0.5, y + h - 0.5),
        col32(c[1], c[2], c[3], 165), 6, 1)
end
local function button(ctx, id, x, y, w, h, label, opts)
    opts = opts or {}
    local im = ctx.im
    local full = (type(id) == "string" and id:sub(1, 2) == "##") and id or ("##mp_" .. tostring(id))
    local function pointInside(mx, my)
        local ox, oy = tonumber(ctx.x), tonumber(ctx.y)
        if not mx or not my or not ox or not oy then return false end
        return mx >= ox + x and mx <= ox + x + w
            and my >= oy + y and my <= oy + y + h
    end
    local function ioMousePos()
        local im = ctx.im
        if not im or type(im.GetIO) ~= "function" then return nil, nil end
        local ok, io = pcall(im.GetIO)
        if not ok or not io or not io.MousePos then return nil, nil end
        local okp, mx, my = pcall(function() return io.MousePos.x, io.MousePos.y end)
        if okp then return tonumber(mx), tonumber(my) end
        return nil, nil
    end
    local function ownMouseInside()
        local mx, my = ioMousePos()
        if pointInside(mx, my) then return true end
        local m = _G.GRND_MOUSE
        if type(m) ~= "table" then return false end
        return pointInside(tonumber(m.x), tonumber(m.y))
    end
    local function ioMouseClicked()
        local im = ctx.im
        if not im or type(im.GetIO) ~= "function" then return false end
        local ok, io = pcall(im.GetIO)
        if not ok or not io or not io.MouseClicked then return false end
        local okc, clicked = pcall(function() return io.MouseClicked[0] end)
        return okc and clicked and true or false
    end
    local function polledMouseClick()
        local m = _G.GRND_MOUSE
        if type(m) ~= "table" then return false end
        local frame = tonumber(_G.GRND_UIFRAME) or 0
        if m._mpPollFrame == frame then return m._mpPollClick and true or false end
        m._mpPollFrame = frame
        m._mpPollClick = false
        local down
        if type(_G.isMouseButtonDown) == "function" then
            local ok, value = pcall(_G.isMouseButtonDown, 1)
            if ok then down = value and true or false end
        end
        if down == nil and type(_G.isKeyDown) == "function" then
            local ok, value = pcall(_G.isKeyDown, 0x01)
            if ok then down = value and true or false end
        end
        if down == nil then return false end
        local previous = m._mpPollDown and true or false
        m._mpPollDown = down
        m._mpPollClick = down and not previous
        return m._mpPollClick
    end
    local function ownMouseClick()
        if not ownMouseInside() then return false end
        if im.IsWindowHovered then
            local okW, overWindow = pcall(im.IsWindowHovered)
            if okW and overWindow == false then return false end
        end
        if ioMouseClicked() then return true end
        if type(_G.grndClickAlive) == "function" and _G.grndClickAlive() then
            if _G.GRND_MOUSE and _G.GRND_MOUSE.clicked then return true end
        end
        if not onClickReady() then return false end
        return polledMouseClick()
    end
    local frame = tonumber(_G.GRND_UIFRAME) or 0
    local own = ownMouseInside() and mpWindowHovered(ctx.im) or false
    local function settle(hov)
        if hov then
            MP_HOVER.id, MP_HOVER.frame = full, frame
            return true
        end
        if MP_HOVER.id == full and (frame - (MP_HOVER.frame or -99)) <= 1 then
            return true
        end
        return false
    end
    local fn = _G.grndUiButton
    if type(fn) == "function" then
        local args = opts
        if own and not opts.hover then
            args = {}
            for k, v in pairs(opts) do args[k] = v end
            args.hover = true
        end
        local ok, clicked, hov = pcall(fn, ctx, full, x, y, w, h, label, args)
        if ok then
            if not hov and own then hov = true end
            if settle(hov) then hoverLayer(ctx, x, y, w, h, opts) end
            if clicked then return true end
            if ownMouseClick() then
                _G.GRND_MOUSE.clicked = false
                return true
            end
            return false
        end
    end
    im.SetCursorPos(ctx.pos(x, y))
    local clicked = im.InvisibleButton(full, im.ImVec2(w, h)) and true or false
    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
    if not hov then hov = own end
    hov = settle(hov)
    if not clicked and ownMouseClick() then
        _G.GRND_MOUSE.clicked = false
        clicked = true
    end
    local ac0 = theme().accent
    local bg, bd
    if opts.danger then
        bg = col32(255, 96, 96, 34)
        bd = col32(255, 96, 96, 84)
    elseif opts.selected then
        bg = col32(ac0[1], ac0[2], ac0[3], 38)
        bd = col32(ac0[1], ac0[2], ac0[3], 115)
    else
        bg = col32(255, 255, 255, 22)
        bd = col32(255, 255, 255, 40)
    end
    roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h), bg, 6)
    frameRect(ctx.dl, ctx.at(x + 0.5, y + 0.5), ctx.at(x + w - 0.5, y + h - 0.5), bd, 6, 1)
    local tw = ctx.tsize(label)
    local TH = theme()
    local lx = math.max(6, (w - tw) / 2)
    if opts.align == "left" then lx = 12 end
    local lc = opts.muted and { 216, 211, 234, 255 }
        or (opts.danger and { 255, 188, 188, 255 })
        or { 250, 248, 255, 255 }
    ctx.uiText(x + lx, y + (h - 14) / 2, label, ctx.c4(lc), 1.0)
    if hov then hoverLayer(ctx, x, y, w, h, opts) end
    return clicked
end
local function switchRow(ctx, id, x, y, on)
