    local th = theme()
    local base = active and (th.accent or { 184, 135, 244 })
        or (th.textMuted or { 170, 164, 184 })
    if hovered then base = { 255, 222, 255, 255 } end
    gearIcon(ctx, cx, cy, col32(base[1], base[2], base[3], hovered and 255 or (active and 250 or 225)))
    return clicked
end
local function drawGivePopup(ctx, cx, y, cw, key)
    local G = MP.give[key]
    if not G then return y end
    if type(G.rows) ~= "table" or #G.rows == 0 then
        G.rows = { "" }
    elseif #G.rows > 1 then
        local one = ""
        for i = 1, math.min(#G.rows, MAX_ROWS) do
            local candidate = cleanText(G.rows[i])
            if candidate ~= "" then one = candidate break end
        end
        G.rows = { one }
        MP.touch()
    end
    local px, pw = cx + 8, cw - 16
    local innerX, innerW = px + 12, pw - 24
    local popupH = 58 + (M_ROW + 6) + M_ROW + 16
    local ac = theme().accent or { 164, 112, 224 }
    roundRect(ctx.dl, ctx.at(px, y), ctx.at(px + pw, y + popupH),
        col32(14, 15, 22, 245), 8)
    frameRect(ctx.dl, ctx.at(px + 0.5, y + 0.5), ctx.at(px + pw - 0.5, y + popupH - 0.5),
        col32(ac[1], ac[2], ac[3], 180), 8, 1)
    ctx.uiText(innerX, y + 10, "НАСТРОЙКА: " .. (GIVE_POPUP_TITLE[key] or key),
        ctx.c4(theme().textHi), 0.95)
    ctx.uiText(innerX, y + 31, GIVE_POPUP_HINT[key] or "Введите значение вручную",
        ctx.c4(theme().textMuted), 0.78)
    if button(ctx, "give_close_" .. key, px + pw - 92, y + 9, 80, 26, "Закрыть", {}) then
        MP.givePopup = nil
    end
    roundRect(ctx.dl, ctx.at(innerX, y + 51), ctx.at(innerX + innerW, y + 53),
        col32(255, 255, 255, 42), 1)
    textInput(ctx, "givepop:" .. key, "##mp_givepop_" .. key, 64, G.rows[1],
        innerX, y + 58, innerW, M_ROW, GIVE_POPUP_HINT[key],
        function(v) G.rows[1] = v end)
    return y + popupH
end
local function section(ctx, x, y, w, title)
    y = y + 8
    roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + 2),
        col32(255, 255, 255, 58), 1)
    y = y + 10
    local ac = theme().accent or { 164, 112, 224 }
    roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + 4, y + 14),
        col32(ac[1], ac[2], ac[3], 235), 2)
    ctx.uiText(x + 10, y - 1, title, ctx.c4(theme().textHi), 1.0)
    return y + 21
end
local function divider(ctx, x, y, w)
    roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + 2),
        col32(255, 255, 255, 64), 1)
end
local function labelAt(ctx, x, y, w, label, right)
    if right ~= nil then
        ctx.uiText(x, y + 2, label, ctx.c4(theme().textDim), 0.92)
        local rw = ctx.tsize(right)
        ctx.uiText(x + w - rw, y + 2, right, ctx.c4(theme().textMuted), 0.85)
    else
        ctx.uiText(x, y + 2, label, ctx.c4(theme().textDim), 0.92)
    end
    return y + M_LBL
end
local function fieldAt(ctx, x, y, w, label, key, id, cap, value, hint, onChange, fieldHeight)
    y = labelAt(ctx, x, y, w, label)
    local h = tonumber(fieldHeight) or M_ROW
    textInput(ctx, key, id, cap, value, x, y, w, h, hint, onChange)
    return y + h
end
local function drawRadiusView(ctx, cx, y, cw)
    y = section(ctx, cx, y, cw, "ВЫДАЧА В РАДИУСЕ")
    local RTm = _G.GRND_RT
    if type(RTm) ~= "table" or type(RTm.page) ~= "function" then
        ctx.uiText(cx + 2, y + 6, "Раздел не загружен", ctx.c4(theme().textDim), 0.9)
        return y + 20
    end
    RTm.visible = true
    local ok, res = pcall(RTm.page, {
        uiText = ctx.uiText, tsize = ctx.tsize, col32 = ctx.col32,
        c4 = ctx.c4, roundRect = ctx.roundRect, dl = ctx.dl, at = ctx.at,
        theme = theme,
        button = function(key, bx, by, bw, bh, label, opts)
            return button(ctx, key, bx, by, bw, bh, label, opts or {})
        end,
        slider = function(id, sx, sy, sw, sh, ratio)
            return grndUiSlider(ctx, id, sx, sy, sw, sh, ratio)
        end,
        gearButton = function(key, gx, gy, active)
            return gearButton(ctx, key, gx, gy, active)
        end,
        gear = function(gx, gy, col) gearIcon(ctx, gx, gy, col) end,
        textInput = function(tid, full, maxLen, value, tx, ty, tw, th,
                hint, cb)
            return textInput(ctx, tid, full, maxLen, value, tx, ty, tw, th,
                hint, cb)
        end,
        frameRect = function(x1, y1, x2, y2, col, rad, th)
            return frameRect(ctx.dl, ctx.at(x1, y1), ctx.at(x2, y2),
                col, rad, th)
        end,
    }, cx, y, cw)
    RTm.visible = false
    if ok and type(res) == "number" then
        return res
    end
    ctx.uiText(cx + 2, y + 6, "Ошибка раздела: " .. tostring(res),
        ctx.c4({ 255, 110, 110, 255 }), 0.85)
    return y + 20
end
local function openTab(tabId)
    local menu = _G.GRND_MENU
    if type(menu) ~= "table" then return false end
    menu.open = true
    local tabs = _G.GRND_MENU_TABS
    if type(tabs) == "table" then
        for i = 1, #tabs do
            if type(tabs[i]) == "table" and tabs[i].id == tabId then
                menu.tab = i
                break
            end
        end
    end
    if type(_G.grndEnsureRender) == "function" then pcall(_G.grndEnsureRender, true) end
    return true
end
function MP.draw(raw)
    local okDraw, err = pcall(MP.drawInner, raw)
    if okDraw then
        MP.drawError = nil
        return
    end
    MP.drawError = tostring(err)
    local fn = _G.grndUiErrLog
    if type(fn) == "function" then pcall(fn, "панель МП", err) end
    MP.errSaid = MP.errSaid or {}
    if not MP.errSaid[MP.drawError] then
        MP.errSaid[MP.drawError] = true
        pcall(say, "панель МП: ошибка — " .. tostring(err):sub(1, 140) .. " (подробности: /mp diag)", "error")
    end
    local im = _G.GRND_IM
    if im then
        local okPos, pos = pcall(im.GetWindowPos)
        if okPos and pos and pos.x then
            local x = (raw and raw.x or 0) + 16
            local y = (raw and raw.y or 0) + 14
            pcall(function()
                im.SetCursorPos(im.ImVec2(x, y))
                im.TextUnformatted("Ошибка панели МП: " .. tostring(err))
                im.SetCursorPos(im.ImVec2(x, y + 20))
                im.TextUnformatted("подробности: /mp diag (или resource/grnd/logs/grnd_err.log)")
            end)
        end
    end
end
function MP.drawInner(raw)
    local im = _G.GRND_IM
    if not im then return end
    local okPos, pos = pcall(im.GetWindowPos)
    if not okPos or not pos then return end
    local px, py = tonumber(pos.x) or 0, tonumber(pos.y) or 0
    local dl = im.GetWindowDrawList()
    if not dl then return end
    if type(MP.form) ~= "table" then MP.form = {} end
    if type(MP.form.messages) ~= "table" then MP.form.messages = { "" } end
    if type(MP.give) ~= "table" then MP.give = {} end
    if type(MP.take) ~= "table" then MP.take = {} end
    if type(MP.presets) ~= "table" then MP.presets = {} end
    if type(MP.fields) ~= "table" then MP.fields = {} end
    for i = 1, #GIVE_CATS do
        local G = MP.give[GIVE_CATS[i].key]
        if type(G) ~= "table" then G = {} MP.give[GIVE_CATS[i].key] = G end
        if type(G.rows) ~= "table" then G.rows = { "" } end
        G.on = G.on and true or false
    end
    for i = 1, #TAKE_CATS do
        MP.take[TAKE_CATS[i].key] = MP.take[TAKE_CATS[i].key] and true or false
    end
    local frameErr = nil
    local TH = theme()
    local fnText = rawget(_G, "grndUiText")
    if type(fnText) ~= "function" then fnText = nil end
    local baseText = fnText or uiTextFallback(im)
    local ctx = {
        im = im, dl = dl, dt = 0.016, x = px, y = py,
        at = function(x, y) return im.ImVec2(px + x, py + y) end,
        pos = function(x, y) return im.ImVec2(x, y) end,
        col32 = col32, rgba = rgba,
        c4 = function(t)
            if type(t) == "table" then
                return rgba(t[1] or 200, t[2] or 200, t[3] or 200, t[4] or 255)
            end
            if type(t) == "number" then return col32(t) end
            return rgba(160, 156, 175, 255)
        end,
        roundRect = roundRect, gradRect = gradRect,
        uiText = function(x, y, s, col, sc)
            local ok, w, h = pcall(baseText, x, y, s, col, sc)
            if ok then return w, h end
            return 0, 14
        end,
        tsize = function(s) return tsizeOf(im, s) end,
    }
    local cx = (raw and raw.x or 0) + 8
    local cy = (raw and raw.y or 0) + 14
    local cw = math.max(280, (raw and raw.w or 640) + 20)
    local ch = math.max(160, (raw and raw.h or 480))
    MP.drawFrames = (MP.drawFrames or 0) + 1
    MP.diag = { x = px + cx, y = py + cy, cw = cw, ch = ch, at = now() }
    local maxScroll = math.max(0, (MP.totalH or 0) - ch)
    MP.scroll = math.max(0, math.min(maxScroll, MP.scroll or 0))
    local mx, my, wheel
    if im.GetIO then
        local okIo, io = pcall(im.GetIO)
        if okIo and io then
            if io.MousePos then mx, my = tonumber(io.MousePos.x), tonumber(io.MousePos.y) end
            wheel = tonumber(io.MouseWheel) or 0
        end
    end
    if not mx and _G.GRND_MOUSE then
        mx, my = tonumber(_G.GRND_MOUSE.x), tonumber(_G.GRND_MOUSE.y)
    end
    if wheel and wheel ~= 0 and mx then
        local inside = mx >= px + cx and mx <= px + cx + cw
            and my >= py + cy and my <= py + cy + ch
        if inside and (now() - (MP.wheelAt or 0)) > 0.05 then
            MP.wheelAt = now()
            MP.scroll = math.max(0, math.min(maxScroll, MP.scroll - wheel * 42))
        end
    end
    local clipPushed = false
    if dl.PushClipRect then
        clipPushed = pcall(dl.PushClipRect, dl, ctx.at(cx, cy), ctx.at(cx + cw, cy + ch), true)
    end
    local y = cy - (MP.scroll or 0)
    local y0 = y
    local function drawTopButtons(y)
        local mw = math.floor((cw - 8) / 2)
        local rw = cw - mw - 8
        local radiusView = MP.view == "radius"
        if button(ctx, "create", cx, y, mw, M_ROW, "Создать МП",
            { selected = not radiusView }) then
            MP.view = "mp"
            MP.scroll = 0
            if openTab("mppanel") then
                flash("Панель МП открыта", "info")
            end
        end
        if button(ctx, "giverad", cx + mw + 8, y, rw, M_ROW,
            "Выдача в радиусе", { selected = radiusView }) then
            MP.view = "radius"
            MP.givePopup = nil
            MP.scroll = 0
            flash("Выдача в радиусе", "info")
        end
        return y + M_ROW + 16
    end
    local okT, resT = pcall(drawTopButtons, y)
    if okT and tonumber(resT) then
        y = tonumber(resT)
    else
        frameErr = frameErr or tostring(resT)
        y = y + M_ROW + 16
    end
    if MP.view == "radius" then
        y = drawRadiusView(ctx, cx, y, cw)
        MP.totalH = y - y0 + 12
        if clipPushed and dl.PopClipRect then pcall(dl.PopClipRect, dl) end
        return
    end
    local contentStart = y
    local function drawContent(y)
        if MP.canUseMsg() then
            y = section(ctx, cx, y, cw, "ОБЪЯВЛЕНИЯ В /MSG")
            local msgDel
            local msgW = math.min(cw - 30, MP_FIELD_MAX_W)
            for i = 1, #MP.form.messages do
                textInput(ctx, "msg:" .. i, "##mp_msg_" .. i, 140,
                    MP.form.messages[i] or "", cx, y, msgW, BIG_ROW,
                    "текст объявления",
                    function(v) MP.form.messages[i] = v end)
                iconButton(ctx, "msgdel_" .. i, cx + msgW + 4, y, trashIcon,
                    function() msgDel = i end, BIG_ROW)
                y = y + BIG_ROW + 6
            end
            if button(ctx, "msgadd", cx, y, msgW, M_ROW, "+ Добавить", {}) then
                if #MP.form.messages < MAX_MSG then
                    table.insert(MP.form.messages, "")
                    MP.touch()
                end
            end
            if msgDel and MP.form.messages[msgDel] ~= nil then
                table.remove(MP.form.messages, msgDel)
                dropFields("msg:")
                MP.touch()
            end
            y = y + M_ROW + 10
        end
        y = section(ctx, cx, y, cw, "ТРИГГЕР И УСЛОВИЯ")
        local formW = math.min(cw, MP_FIELD_MAX_W)
        textInput(ctx, "trigger", "##mp_trigger", 40, MP.form.trigger,
            cx, y, formW, BIG_ROW, "триггер в репорте, например: дигла",
            function(v) MP.form.trigger = v end)
        y = y + BIG_ROW + M_GAP + 4
        y = section(ctx, cx, y, cw, "ВЫДАТЬ ИГРОКУ ПОСЛЕ ТЕЛЕПОРТА")
        for i = 1, #GIVE_CATS do
            local cat = GIVE_CATS[i]
            local G = MP.give[cat.key]
            local headerY = y
            if switchRow(ctx, "sw_" .. cat.key, cx + 4, headerY + 5, G.on) then
                G.on = not G.on
                if G.on and #G.rows == 0 then G.rows[1] = "" end
                MP.touch()
            end
            ctx.uiText(cx + 62, headerY + 8, string.upper(cat.title),
                ctx.c4(G.on and theme().textHi or theme().textDim), 0.92)
            if gearButton(ctx, cat.key,
                cx + 62 + mpTextW(ctx, string.upper(cat.title), 0.92) + 18,
                headerY + 17, G.on or MP.givePopup == cat.key) then
                MP.givePopup = (MP.givePopup == cat.key) and nil or cat.key
            end
            y = headerY + M_ROW
            if MP.givePopup == cat.key then
                y = drawGivePopup(ctx, cx, y, cw, cat.key)
            end
            if i < #GIVE_CATS then
                y = y + 12
            end
        end
        y = y + 4
        y = section(ctx, cx, y, cw, "ЗАБРАТЬ")
        for i, t in ipairs(TAKE_CATS) do
            local rowY = y
            if switchRow(ctx, "take_" .. t.key, cx + 4, rowY + 5, MP.take[t.key]) then
                MP.take[t.key] = not MP.take[t.key]
                MP.touch()
            end
            ctx.uiText(cx + 62, rowY + 8, t.title,
                ctx.c4(MP.take[t.key] and TH.textHi or TH.textDim), 0.95)
            y = rowY + M_ROW
            if i < #TAKE_CATS then
                y = y + 11
            end
        end
        y = y + 6
        y = section(ctx, cx, y, cw, "ЗАГОТОВКИ")
        y = fieldAt(ctx, cx, y, formW, "НАЗВАНИЕ", "presetName", "##mp_preset_name",
            48, MP.presetName, "например: дигла | ночь",
            function(v) MP.presetName = v end, BIG_ROW)
        y = y + 4
        if button(ctx, "psave", cx, y, cw, M_ROW, "Сохранить заготовку", {}) then
            local ok, msg = MP.savePreset(MP.presetName)
            MP.flash = { text = msg, at = now(), kind = ok and "ok" or "err" }
        end
        y = y + M_ROW + 8
        if #(MP.presets or {}) == 0 then
            ctx.uiText(cx + 2, y + 4, "заготовок пока нет", ctx.c4(TH.textMuted), 0.9)
            y = y + 22
        else
            local pw = math.floor((cw - 6) / 2)
            for i = 1, #(MP.presets or {}) do
                local p = MP.presets[i]
                local col = (i - 1) % 2
                local rowi = math.floor((i - 1) / 2)
                local x = cx + col * (pw + 6)
                local yy = y + rowi * (M_ROW + 6)
                if button(ctx, "pload_" .. i, x, yy, pw - M_ROW - 4, M_ROW,
                    string.format("%d.  %s", i, tostring(p.name or "")),
                    { align = "left" }) then
                    local ok, msg = MP.usePreset(p.name)
                    MP.flash = { text = msg, at = now(), kind = ok and "ok" or "err" }
                end
                iconButton(ctx, "pdel_" .. i, x + pw - M_ROW, yy, trashIcon,
                    function()
                        local ok, msg = MP.deletePreset(p.name)
                        flash(msg or "Заготовка не найдена", ok and "ok" or "error")
                    end)
            end
            y = y + math.ceil(#(MP.presets or {}) / 2) * (M_ROW + 6) + 4
        end
        return y
    end
    local okC, resC = pcall(drawContent, y)
    if okC and tonumber(resC) then
        MP.contentH = tonumber(resC) - contentStart
        y = tonumber(resC)
    else
        frameErr = frameErr or tostring(resC)
        local h = tonumber(MP.contentH) or 160
        pcall(ctx.uiText, cx + 2, contentStart + 6,
            "ошибка в содержимом панели: " .. tostring(MP.blockError):sub(1, 80),
            ctx.c4({ 255, 120, 120, 255 }), 0.85)
        y = contentStart + math.max(80, h)
    end
    y = y + 6
    y = y + 4
    local function drawStartStop(yy)
        if MP.active then
            if button(ctx, "stop", cx, yy, cw, M_ROW + 4, "Остановить", { danger = true }) then
                MP.stop("кнопкой в панели")
            end
        else
            if button(ctx, "start_mp", cx, yy, cw, M_ROW + 4, "Начать", { selected = true }) then
                local started = MP.start()
                if not started then
                    local f = MP.flash
                    say("запуск не выполнен: " .. tostring(f and f.text or "проверьте форму"), "error")
                end
            end
        end
        return yy
    end
    local okSS, resSS = pcall(drawStartStop, y)
    if okSS and tonumber(resSS) then y = tonumber(resSS)
    else frameErr = frameErr or tostring(resSS) end
    if frameErr then
        MP.blockError = frameErr
        MP.blockErrN = (MP.blockErrN or 0) + 1
    else
        MP.blockError = nil
    end
    MP.totalH = y - y0 + M_ROW + 12
    if clipPushed and dl.PopClipRect then pcall(dl.PopClipRect, dl) end
    local maxS = math.max(0, (MP.totalH or 0) - ch)
    if maxS > 1 then
        local frac = math.min(1, ch / math.max(1, MP.totalH))
        local barH = math.max(30, ch * frac)
        local barY = cy + (ch - barH) * math.min(1, math.max(0, (MP.scroll or 0) / maxS))
        local sx = cx + cw + 4
        roundRect(ctx.dl, ctx.at(sx, cy), ctx.at(sx + 4, cy + ch),
            col32(255, 255, 255, 14), 2)
        roundRect(ctx.dl, ctx.at(sx, barY), ctx.at(sx + 4, barY + barH),
            col32(255, 255, 255, 72), 2)
    end
end
local tabBound = false
local function bindTab()
    if tabBound then return true end
    local tabs = _G.GRND_MENU_TABS
    if type(tabs) ~= "table" then return false end
    for i = 1, #tabs do
        if type(tabs[i]) == "table" and tabs[i].id == "mppanel" then
            tabs[i].draw = function(ctx) pcall(MP.draw, ctx) end
            tabBound = true
            return true
        end
    end
    return false
end
local hookOkAt = 0
local chainAt = 0
function MP.tick()
    if not MP.loaded then pcall(MP.load) end
    if not tabBound then pcall(bindTab) end
    if MP.active and type(grndUiBlocked) == "function" and grndUiBlocked() then
        MP.stop("МП остановлено: открыт экран авторизации")
        return
    end
    if not MP.chainReady and not MP.chainSeen and (now() - (chainAt or 0)) > 10 then
        chainAt = now()
        local okCall, hooked = pcall(installHook)
        MP.hookOk = okCall and hooked == true
    end
    local okPump, errPump = pcall(MP.pump)
    if not okPump then pcall(MP.recoverJob, errPump) end
    local t = now()
    if MP.dirtyAt and (t - MP.dirtyAt) > 1.2 then
        MP.dirtyAt = nil
        pcall(MP.save)
    end
end
function MP.reset()
    local was = MP.active
    MP.active = false
    MP.watch = false
    MP.jobs, MP.cur, MP.lock = {}, nil, {}
    MP.announce = nil
    MP.givePopup = nil
    MP.runtimeForm = nil
    MP.log = {}
    MP.players, MP.sent, MP.done = 0, 0, 0
    MP.lastCmd = ""
    MP.nextAt = 0
    MP.lastMessageText, MP.lastMessageAt = nil, -math.huge
    MP.stat = { parsed = 0, matched = 0, skipped = 0, dropped = 0 }
    MP.preview = nil
    if was then
        flash("Состояние МП сброшено", "warn")
        say("состояние сброшено", "warn")
    end
end
do
    local bound = false
    for i = 1, #MENU_TABS do
        if type(MENU_TABS[i]) == "table" and MENU_TABS[i].id == "mppanel" then
            MENU_TABS[i].draw = function(ctx) pcall(MP.draw, ctx) end
            bound = true
            break
        end
    end
    if not bound then
        MENU_TABS[#MENU_TABS + 1] = { id = "mppanel", name = "Панель МП" }
        MENU_TABS[#MENU_TABS].draw = function(ctx) pcall(MP.draw, ctx) end
    end
end
local function mpDiag()
    local im = _G.GRND_IM
    local function yn(v) return v and "да" or "нет" end
    local function apiState(has, fn)
        if not has then return "нет" end
        local ok, res = pcall(fn)
        if not ok or res == false then return "ошибка" end
        if res == nil then return "нет" end
        return "да"
    end
    local L = {}
    local function emit(text, kind)
        L[#L + 1] = tostring(text)
        pcall(say, text, kind)
    end
    emit("=== Панель МП: диагностика ===", "info")
    emit("версия " .. tostring(GRND_SCRIPT_VERSION or _G.GRND_SCRIPT_VERSION or "?")
        .. " · кадров ImGui: " .. tostring(_G.GRND_UIFRAME or 0)
        .. " · кадров панели: " .. tostring(MP.drawFrames or 0), "info")
    if MP.diag and MP.diag.at then
