end
if type(sampRegisterChatCommand) == "function" then
    pcall(sampRegisterChatCommand, "mp", function(arg)
        local raw = tostring(arg or ""):gsub("^%s+", ""):gsub("%s+$", "")
        local a, rest = raw:match("^(%S+)%s*(.*)$")
        a = tostring(a or ""):lower()
        if a == "start" then
            local okStart = MP.start()
            if not okStart then say("запуск отменён — проверьте сообщение в панели", "warn") end
        elseif a == "stop" then
            if not MP.stop("Остановлено командой /mp stop") then say("МП уже остановлено", "info") end
        elseif a == "reset" then
            local wasActive = MP.active
            MP.reset()
            if not wasActive then say("состояние сброшено", "info") end
        elseif a == "show" then
            local good, msg, lines = MP.dryRun()
            say(msg, good and "ok" or "warn")
            if good and lines then
                for _, c in ipairs(lines) do say("  " .. c, "info") end
            end
        elseif a == "hook" then
            local okCall, hooked = pcall(installHook)
            local okHook = okCall and hooked == true
            MP.hookOk = okHook
            say("перехват чата: " .. (okHook and "установлен" or "НЕ установлен"),
                okHook and "ok" or "error")
        elseif a == "diag" or a == "лог" or a == "log" then
            pcall(mpDiag)
        elseif a == "save" then
            local good, msg = MP.savePreset(rest)
            say(msg, good and "ok" or "warn")
        elseif a == "load" then
            local good, msg = MP.usePreset(rest)
            say(msg, good and "ok" or "warn")
        elseif a == "del" then
            local good = MP.deletePreset(rest)
            say(good and "Заготовка удалена" or "Заготовка не найдена",
                good and "ok" or "warn")
        else
            say((MP.active and "активно" or "выключено")
                .. " · в очереди: " .. #MP.jobs
                .. " · команд: " .. tostring(MP.sent)
                .. " · заготовок: " .. #MP.presets, "info")
        end
        return true
    end)
end
pcall(MP.load)
return MP
end)()
_G.GRND_QR = (function()
local QR = {
