}
local MAX_TEXT = 512
local MAX_NAME = 48
local MAX_CHAT = 118
local MAX_BUF  = 244
local MAX_PTIME = 8
local MAX_PREASON = 96
local function theme() return (GRND_UIKIT and GRND_UIKIT.TH) or {} end
local function utf(s)
    s = tostring(s or "")
    if type(grndUtf8Text) == "function" then
        local ok, v = pcall(grndUtf8Text, s)
        if ok and type(v) == "string" and v ~= "" then return v end
    end
    return s
end
local function lower(s)
    s = tostring(s or "")
    if type(grndLowerUtf) == "function" then
        local ok, v = pcall(grndLowerUtf, s)
        if ok and type(v) == "string" then return v end
    end
    return s:lower()
end
local function trim(s)
    return (tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", ""))
end
local function oneLine(s)
    s = tostring(s or ""):gsub("\r\n", "\n"):gsub("\r", "\n")
    s = s:gsub("[ \t]*\n[ \t]*", " ")
    return trim(s:gsub("%s+", " "))
end
local function cleanText(s)
    s = tostring(s or ""):gsub("\r\n", "\n"):gsub("\r", "\n"):gsub("%z", "")
    local out = {}
    for line in (s .. "\n"):gmatch("([^\n]*)\n") do out[#out + 1] = (line:gsub("[ \t]+$", "")) end
    while #out > 0 and out[#out] == "" do out[#out] = nil end
    while #out > 0 and out[1] == "" do table.remove(out, 1) end
    return table.concat(out, "\n")
end
local function utf8Len(s)
    s = tostring(s or "")
    if type(grndUtf8Len) == "function" then
        local ok, n = pcall(grndUtf8Len, s)
        if ok and type(n) == "number" then return n end
    end
    local n = 0
    for _ in s:gmatch("[\0-\127\194-\244][\128-\191]*") do n = n + 1 end
    return n
end
local function byteCut(s, maxBytes)
    s = tostring(s or "")
    if #s <= maxBytes then return s end
    local i, last = 1, 0
    while i <= #s do
        local b = s:byte(i)
        local step = (b >= 240 and 4) or (b >= 224 and 3) or (b >= 192 and 2) or 1
        if i + step - 1 > maxBytes then break end
        last = i + step - 1
        i = i + step
    end
    return s:sub(1, last)
end
local function utf8Cut(s, maxChars)
    s = tostring(s or "")
    maxChars = math.max(0, math.floor(tonumber(maxChars) or 0))
    if maxChars <= 0 then return "" end
    if type(grndBinderUtf8Cut) == "function" then
        local ok, cut = pcall(grndBinderUtf8Cut, s, maxChars)
        if ok and type(cut) == "string" then return cut end
    end
    local i, n = 1, 0
    while i <= #s and n < maxChars do
        local b = s:byte(i)
        local step = (b >= 240 and 4) or (b >= 224 and 3) or (b >= 192 and 2) or 1
        i = i + step
        n = n + 1
    end
    return s:sub(1, i - 1)
end
local function esc(s)
    if type(grndBinderEscape) == "function" then
        local ok, v = pcall(grndBinderEscape, s)
        if ok and type(v) == "string" then return v end
    end
    return (tostring(s or ""):gsub("\r", ""):gsub("\\", "\\\\"):gsub("\n", "\\n"))
end
local function unesc(s)
    s = tostring(s or "")
    if type(grndBinderUnescape) == "function" then
        local ok, v = pcall(grndBinderUnescape, s)
        if ok and type(v) == "string" then return v end
    end
    local out, i, n = {}, 1, #s
    while i <= n do
        local c = s:sub(i, i)
        if c == "\\" and i < n then
            local n1 = s:sub(i + 1, i + 1)
            if n1 == "n" then out[#out + 1] = "\n"
            elseif n1 == "\\" then out[#out + 1] = "\\"
            else out[#out + 1] = n1 end
            i = i + 2
        else
            out[#out + 1] = c
            i = i + 1
        end
    end
    return table.concat(out)
end
local function clampText(s, cap)
    s = tostring(s or "")
    if #s > cap then s = utf8Cut(s, cap) end
    return s
end
local function fitW(s, maxW, measure, scale)
    s = tostring(s or "")
    if s == "" or type(measure) ~= "function" then return s, 0 end
    scale = scale or 1
    local ok, w = pcall(measure, s, scale)
    w = (ok and tonumber(w)) or 0
    if not maxW or maxW <= 6 or w <= maxW then return s, w end
    local chars = {}
    for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do chars[#chars + 1] = ch end
    local keep = math.floor(#chars * (maxW - 10) / math.max(1, w))
    if keep < 1 then keep = 1 end
    if keep > #chars - 1 then keep = #chars - 1 end
    local shown = table.concat(chars, "", 1, keep) .. "…"
    for _ = 1, 8 do
        local ok2, w2 = pcall(measure, shown, scale)
        w2 = (ok2 and tonumber(w2)) or w
        if w2 <= maxW or keep <= 1 then return shown, w2 end
        keep = keep - 1
        shown = table.concat(chars, "", 1, keep) .. "…"
    end
    return shown, w
end
local function fit(s, maxW, measure, scale)
    local shown = fitW(s, maxW, measure, scale)
    return shown
end
local function wrapW(s, maxW, measure, scale)
    s = tostring(s or "")
    scale = tonumber(scale) or 1
    local out, line = {}, ""
    local function width(t)
        if type(measure) == "function" then
            local ok, w = pcall(measure, t, scale)
            if ok and type(w) == "number" then return w end
        end
        return #tostring(t) * 7 * scale
    end
    for word in s:gmatch("%S+") do
        if line == "" then
            line = word
        else
            local cand = line .. " " .. word
            if width(cand) <= maxW then
                line = cand
            else
                out[#out + 1] = line
                line = word
            end
        end
        if width(line) > maxW then line = fitW(line, maxW, measure, scale) end
    end
    if line ~= "" then out[#out + 1] = line end
    return out
end
local function lineH(ctx, scale)
    scale = tonumber(scale) or 1
    local h = 14 * scale
    if ctx and type(ctx.tsize) == "function" then
        local ok, _, hh = pcall(ctx.tsize, "X")
        if ok and type(hh) == "number" and hh > 0 then h = hh * scale end
    end
    return h
end
local function bufGet(im, key, cap)
    local f = QR.bufs[key]
    if f and (f.cap ~= cap or f.im ~= im) then f = nil; QR.bufs[key] = nil end
    if not f then
        if not (im and im.new and im.new.char) then return nil end
        local ok, b = pcall(function() return im.new.char[cap]() end)
        if not (ok and b) then return nil end
        f = { buf = b, cap = cap, im = im, pending = true }
        QR.bufs[key] = f
    end
    return f
end
local function bufWrite(key, value)
    local f = QR.bufs[key]
    if not f then return end
    local text = byteCut(clampText(value, f.cap - 1), f.cap - 1)
    if type(grndBinderWriteCBuf) == "function" then
        pcall(grndBinderWriteCBuf, f.buf, f.cap, text)
    end
    f.pending = false
end
local function bufText(key)
    local f = QR.bufs[key]
    if not f then return "" end
    if type(grndBinderReadCBuf) == "function" then
        local ok, v = pcall(grndBinderReadCBuf, f.buf)
        if ok and type(v) == "string" then return (v:gsub("%z", "")) end
    end
    return ""
end
local function bufReload(key)
    local f = QR.bufs[key]
    if f then f.pending = true end
end
local function wheelDelta(im)
    local w = 0
    if im and im.GetIO then
        local ok, io = pcall(im.GetIO)
        if ok and io then w = tonumber(io.MouseWheel) or 0 end
    end
    return w
end
local function mouse(im)
    local mx, my
    if im and im.GetIO then
        local ok, io = pcall(im.GetIO)
        if ok and io and io.MousePos then
            mx, my = tonumber(io.MousePos.x), tonumber(io.MousePos.y)
        end
    end
    if not mx and _G.GRND_MOUSE then
        mx, my = tonumber(_G.GRND_MOUSE.x), tonumber(_G.GRND_MOUSE.y)
    end
    return mx, my
end
local function scrollWheel(im, mx, my, x, y, w, h, cur, maxScroll, step)
    if not (mx and my) or maxScroll <= 0 then return cur end
    if mx < x or mx > x + w or my < y or my > y + h then return cur end
    local dw = wheelDelta(im)
    if dw == 0 then return cur end
    local now = os.clock()
    if now - (QR.wheelAt or 0) < 0.05 then return cur end
    QR.wheelAt = now
    return math.max(0, math.min(maxScroll, cur - dw * (step or 44)))
end
function QR.path()
    if type(this_script_dir) == "function" then
        local okd, sd = pcall(this_script_dir)
        if okd and sd and tostring(sd) ~= "" then
            local pp = tostring(sd)
            while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
            local sep = "\\"
            local okc, cf = pcall(function() return package.config end)
            if okc and type(cf) == "string" and #cf > 0 then sep = cf:sub(1, 1) end
            return pp .. sep .. "grnd_repquick.cfg"
        end
    end
    return "grnd_repquick.cfg"
end
function QR.modeOk(v)
    v = tostring(v or "")
    if v == "input" then return "input" end
    return "ans"
end
local DEMOS = {
    { name = "Приветствие", text = "Приветствую, чем могу помочь?" },
    { name = "Принято в работу", text = "Приветствую, ваше обращение принято. Ожидайте ответа." },
    { name = "Нарушитель наказан", text = "Приветствую, нарушитель будет наказан. Спасибо за обращение!" },
    { name = "Нарушения нет", text = "Приветствую, в данной ситуации нарушения правил нет." },
    { name = "Нужны доказательства", text = "Приветствую, доказательств недостаточно. Прикрепите скриншот или видео." },
}
local function dropDemos()
    if type(QR.items) ~= "table" or #QR.items == 0 then return 0 end
    local keep, removed = {}, 0
    for i = 1, #QR.items do
        local it = QR.items[i]
        local demo = false
        for d = 1, #DEMOS do
            if it.name == DEMOS[d].name and it.text == DEMOS[d].text then demo = true; break end
        end
        if demo then removed = removed + 1 else keep[#keep + 1] = it end
    end
    if removed > 0 then
        QR.items = keep
        if QR.selId and not QR.byId(QR.selId) then QR.selId, QR.formKey = nil, nil end
    end
    return removed
end
function QR.normalize()
    if type(QR.items) ~= "table" then QR.items = {} end
    local seen, out, maxId = {}, {}, 0
    for i = 1, #QR.items do
        local it = QR.items[i]
        if type(it) == "table" then
            local id = math.floor(tonumber(it.id) or 0)
            if id <= 0 or seen[id] then
                id = 0
                repeat id = id + 1 until not seen[id]
            end
            local name = clampText(trim(utf(it.name or "")), MAX_NAME)
            local text = clampText(cleanText(utf(it.text or "")), MAX_TEXT)
            if name == "" and text ~= "" then name = utf8Cut(oneLine(text), 28) end
            if name ~= "" or text ~= "" then
                if name == "" then name = "Шаблон " .. tostring(id) end
                seen[id] = true
                if id > maxId then maxId = id end
                out[#out + 1] = { id = id, name = name, text = text }
            end
        end
    end
    QR.items = out
    QR.nextId = math.max(math.floor(tonumber(QR.nextId) or 1), maxId + 1)
    QR.mode = QR.modeOk(QR.mode)
    if QR.selId and not seen[math.floor(tonumber(QR.selId) or 0)] then QR.selId = nil end
    return out
end
function QR.load()
    if QR.loaded then return true end
    QR.loaded = true
    local items, mode, nextId = {}, nil, nil
    local demoMark = nil
    local hadRows = false
    local ok, f = pcall(GRND_CONFIG.open, QR.path(), "r")
    if ok and f then
        local cur = nil
        for line in f:lines() do
            line = tostring(line or "")
            if line == "---" then
                hadRows = true
                cur = {}
                items[#items + 1] = cur
            else
                local k, v = line:match("^([%w_]+)=(.*)$")
                if k then
                    hadRows = true
                    if cur then
                        if k == "id" then cur.id = tonumber(v)
                        elseif k == "name" then cur.name = unesc(v)
                        elseif k == "text" then cur.text = unesc(v) end
                    else
                        if k == "mode" then mode = v
                        elseif k == "nextId" then nextId = tonumber(v)
                        elseif k == "demo" then demoMark = tonumber(v) end
                    end
                end
            end
        end
        pcall(f.close, f)
    end
    QR.items = items
    if mode then QR.mode = QR.modeOk(mode) end
    if nextId then QR.nextId = nextId end
    QR.normalize()
    if hadRows and not demoMark then
        dropDemos()
        pcall(QR.save)
    end
    return true
end
function QR.ensure()
    if not QR.loaded then pcall(QR.load) end
    if type(QR.items) ~= "table" then pcall(QR.normalize) end
    return QR
end
function QR.save()
    QR.normalize()
    local ok, f = pcall(GRND_CONFIG.open, QR.path(), "w")
    if not ok or not f then return false end
    local escv = esc
    f:write("mode=" .. tostring(QR.mode or "test") .. "\n")
    f:write("nextId=" .. tostring(QR.nextId or 1) .. "\n")
    f:write("demo=1\n")
    for i = 1, #QR.items do
        local it = QR.items[i]
        f:write("---\n")
        f:write("id=" .. tostring(it.id or 0) .. "\n")
        f:write("name=" .. escv(tostring(it.name or "")) .. "\n")
        f:write("text=" .. escv(tostring(it.text or "")) .. "\n")
    end
    pcall(f.close, f)
    if GRND_CONFIG and type(GRND_CONFIG.flush) == "function" then
        pcall(GRND_CONFIG.flush)
    end
    return true
end
function QR.byId(id)
    id = math.floor(tonumber(id) or 0)
    if type(QR.items) ~= "table" then return nil, nil end
    for i = 1, #QR.items do
        if QR.items[i].id == id then return QR.items[i], i end
    end
    return nil, nil
end
function QR.count()
    return (type(QR.items) == "table") and #QR.items or 0
end
function QR.noteShow(text, kind)
    QR.note, QR.noteKind, QR.noteAt = tostring(text or ""), kind or "ok", os.clock()
end
function QR.add(name, text)
    QR.ensure()
    local id = math.max(1, math.floor(tonumber(QR.nextId) or 1))
    QR.nextId = id + 1
    local it = {
        id = id,
        name = clampText(trim(utf(name or "")), MAX_NAME),
        text = clampText(cleanText(utf(text or "")), MAX_TEXT),
    }
    if it.name == "" and it.text ~= "" then it.name = utf8Cut(oneLine(it.text), 28) end
    QR.items[#QR.items + 1] = it
    return it
end
function QR.update(id, name, text)
    local it = QR.byId(id)
    if not it then return false end
    it.name = clampText(trim(utf(name or "")), MAX_NAME)
    it.text = clampText(cleanText(utf(text or "")), MAX_TEXT)
    if it.name == "" and it.text ~= "" then it.name = utf8Cut(oneLine(it.text), 28) end
    return true
end
function QR.remove(id)
    id = math.floor(tonumber(id) or 0)
    if type(QR.items) ~= "table" then return false end
    for i = 1, #QR.items do
        if QR.items[i].id == id then
            table.remove(QR.items, i)
            if QR.selId == id then QR.selId, QR.formKey = nil, nil end
            return true
        end
    end
    return false
end
function QR.move(id, dir)
    local it, idx = QR.byId(id)
    if not it then return false end
    local other = idx + ((dir or 0) < 0 and -1 or 1)
    if other < 1 or other > #QR.items then return false end
    QR.items[idx], QR.items[other] = QR.items[other], QR.items[idx]
    return true
end
function QR.myNick()
    local id
    if type(sampGetLocalPlayerId) == "function" then
        local ok, v = pcall(sampGetLocalPlayerId)
        if ok and type(v) == "number" then id = math.floor(v) end
    end
    if id and type(sampGetPlayerNickname) == "function" then
        local ok, v = pcall(sampGetPlayerNickname, id)
        if ok and type(v) == "string" and v ~= "" then return utf(v) end
    end
    return "?"
end
function QR.apply(text, rep)
    local s = tostring(text or "")
    rep = (type(rep) == "table") and rep or {}
    local nick = tostring(rep.nick or rep.author or "")
    local author = tostring(rep.author or rep.nick or "")
    local pid = tostring(rep.id or rep.playerId or "")
    local target = tostring(rep.foundId or "") ~= "" and tostring(rep.foundId) or pid
    local map = {
        ["{ник}"] = nick, ["{nick}"] = nick,
        ["{автор}"] = author, ["{reporter}"] = author,
        ["{ид}"] = target, ["{id}"] = target,
        ["{ID}"] = target,
        ["{время}"] = os.date("%H:%M"), ["{time}"] = os.date("%H:%M"),
        ["{мой_ник}"] = QR.myNick(), ["{mynick}"] = QR.myNick(),
    }
    for k, v in pairs(map) do
        if v ~= "" then
            local safe = tostring(v):gsub("%%", "%%%%")
            s = s:gsub(k, safe)
        end
    end
    return s
end
function QR.repInfo()
    local R = _G.GRND_REP
    if type(R) ~= "table" then return { nick = "", id = "" } end
    return { nick = tostring(R.author or ""), id = tostring(R.playerId or "") }
end
function QR.toast(text, kind, life)
    if type(notify) == "table" and type(notify.add) == "function" then
        pcall(notify.add, tostring(text or ""), kind or "ok", life or 3.2)
    end
end
function QR.sendChat(cmd)
    if type(cmd) ~= "string" or cmd == "" then return false end
    QR.chats = (QR.chats or 0) + 1
    if type(grndChatSend) == "function" then
        local ok, res = pcall(grndChatSend, cmd)
        if ok and res ~= false then return true end
    end
    if type(sampSendChat) == "function" then
        local text = cmd
        if type(grndAnsiText) == "function" then
            local okA, ansi = pcall(grndAnsiText, cmd)
            if okA and type(ansi) == "string" and ansi ~= "" then text = ansi end
        end
        return pcall(sampSendChat, text) and true or false
    end
    return false
end
function QR.queueCmd(cmd)
    cmd = tostring(cmd or "")
    if cmd == "" then return false end
    if type(grndRepQueue) == "function" then
        local out = cmd
        if type(grndAnsiText) == "function" then
            local okA, ansi = pcall(grndAnsiText, cmd)
            if okA and type(ansi) == "string" and ansi ~= "" then out = ansi end
        end
        if pcall(grndRepQueue, out) then
            QR.chats = (QR.chats or 0) + 1
            return true
        end
    end
    return QR.sendChat(cmd)
end
function QR.closeReport()
    local R = _G.GRND_REP
    if type(R) == "table" then
        R.open = false
        R.focused = false
    end
    QR.pickOpen, QR.pickFocus = false, false
    if type(QR.pun) == "table" then QR.pun.pickOpen, QR.pun.pickFocus = false, false end
    return true
end
function QR.choose(it)
    if type(it) ~= "table" then return false end
    local rep = QR.repInfo()
    local text = trim(QR.apply(it.text or "", rep))
    QR.pickOpen, QR.pickFocus = false, false
    local label = tostring(it.name or "шаблон")
    if oneLine(text) == "" then
        QR.toast("Шаблон «" .. label .. "» пуст", "warn", 2.5)
        return false
    end
    local mode = QR.modeOk(QR.mode)
    if mode == "input" then
        local R = _G.GRND_REP
        local buf = R and R.answer
        if buf and type(grndBinderWriteCBuf) == "function" then
            local body = text
            if lower(body):find("^приветствую") then
                body = body:gsub("^[Пп]риветствую[,!]?%s*", "")
            end
            local fit256 = byteCut(oneLine(body), MAX_BUF)
            if fit256 ~= oneLine(body) then
                QR.toast("Текст шаблона обрезан под поле ответа", "warn", 3)
            end
            if pcall(grndBinderWriteCBuf, buf, 256, fit256) then
                if R then R.focused = false end
                QR.toast("Шаблон «" .. label .. "» вставлен в поле ответа", "ok", 2.6)
                return true
            end
        end
        mode = "ans"
    end
    do
        local pid = tostring(rep.id or "")
        if pid:match("^%d+$") and type(grndRepAnswer) == "function" then
            local okA, res = pcall(grndRepAnswer, pid, text)
            if okA and res ~= false then
                QR.toast("Ответ игроку /ans " .. pid .. ": «" .. utf8Cut(label, 20) .. "»", "ok", 2.8)
                QR.closeReport()
                return true
            end
        end
    end
    mode = "ans"
    local R = _G.GRND_REP
    local buf = R and R.answer
    if buf and type(grndBinderWriteCBuf) == "function" then
        local line = byteCut(oneLine(text), MAX_BUF)
        pcall(grndBinderWriteCBuf, buf, 256, line)
        if R then R.focused = false end
        QR.toast("В репорте нет ID игрока — текст шаблона вставлен в поле ответа", "warn", 3.4)
        return true
    end
    QR.toast("В репорте нет ID игрока — отвечать некому", "warn", 3)
    return false
end
function QR.openPicker()
    QR.ensure()
    if QR.count() == 0 then
        QR.pickOpen, QR.pickFocus = false, false
        QR.toast("Шаблонов пока нет — создайте их в меню «Репорт», вкладка «Ответы на репорт»", "warn", 3.5)
        return false
    end
    if type(QR.pun) == "table" then QR.pun.pickOpen, QR.pun.pickFocus = false, false end
    QR.pickOpen, QR.pickFocus = true, true
    QR.pickScroll = 0
    return true
end
function QR.togglePicker()
    if QR.pickOpen then
        QR.closePicker()
    else
        QR.openPicker()
    end
end
function QR.closePicker()
    QR.pickOpen, QR.pickFocus = false, false
end
function _G.grndQrOnEsc()
    local Q = _G.GRND_QR
    if type(Q) ~= "table" then return false end
    if type(Q.auto) == "table" and Q.auto.listOpen then
        Q.auto.listOpen = false
        return true
    end
    local P = Q.pun
    if type(P) == "table" then
        if P.comboOpen then
            P.comboOpen = false
            return true
        end
        if P.pickOpen then
            P.pickOpen, P.pickFocus = false, false
            return true
        end
    end
    if Q.pickOpen then
        Q.pickOpen, Q.pickFocus = false, false
        return true
    end
    return false
end
local function fieldRect(im, fbX, fbY, fbW, fbH)
    if type(im.GetItemRectMin) == "function" and type(im.GetItemRectMax) == "function"
       and type(im.GetWindowPos) == "function" then
        local ok1, a = pcall(im.GetItemRectMin)
        local ok2, b = pcall(im.GetItemRectMax)
        local okp, p = pcall(im.GetWindowPos)
        if ok1 and ok2 and okp and a and b and p and a.x and b.x and p.x then
            return a.x - p.x, a.y - p.y, b.x - a.x, b.y - a.y
        end
    end
    return fbX, fbY, fbW, fbH
end
local function field(ctx, id, key, cap, x, y, w, h, hint, multiline, initial)
    local im = ctx.im
    local TH = theme()
    local f = bufGet(im, key, cap)
    if not f then
        ctx.roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h), ctx.col32(255, 255, 255, 8), 6)
        ctx.uiText(x + 8, y + math.floor(h / 2) - 8, "поле ввода недоступно",
            ctx.rgba(230, 150, 150, 255), 0.85)
        return false
    end
    if f.pending then bufWrite(key, initial or "") end
    local nCol, nVar = 0, 0
    local borderPushed = false
    if ctx.pushCol and im.Col then
        local push = ctx.pushCol
        if im.Col.FrameBg and push(im.Col.FrameBg, ctx.rgba(12, 15, 22, 255)) then nCol = nCol + 1 end
        if im.Col.FrameBgHovered and push(im.Col.FrameBgHovered, ctx.rgba(18, 22, 31, 255)) then nCol = nCol + 1 end
        if im.Col.FrameBgActive and push(im.Col.FrameBgActive, ctx.rgba(21, 26, 36, 255)) then nCol = nCol + 1 end
        if im.Col.Text and push(im.Col.Text, ctx.rgba(233, 237, 246, 255)) then nCol = nCol + 1 end
        if im.Col.Border and push(im.Col.Border, ctx.rgba(255, 255, 255, 58)) then
            nCol = nCol + 1
            borderPushed = true
        end
    end
    if ctx.pushVarF and im.StyleVar and im.StyleVar.FrameBorderSize then
        if ctx.pushVarF(im.StyleVar.FrameBorderSize, 1) then nVar = nVar + 1 end
    end
    if ctx.pushVarV2 and im.StyleVar and im.StyleVar.FramePadding and not multiline then
        if ctx.pushVarV2(im.StyleVar.FramePadding, 9, math.max(2, math.floor((h - 14) / 2))) then
            nVar = nVar + 1
        end
    end
    im.SetCursorPos(im.ImVec2(x, y))
    if im.SetNextItemWidth then pcall(im.SetNextItemWidth, w) end
    local changed, okCall = false, false
    if multiline and type(im.InputTextMultiline) == "function" then
        local sz = im.ImVec2(w, h)
        local function invokeMulti(sig)
            if sig == 1 then return im.InputTextMultiline(id, f.buf, cap, sz, 0) end
            if sig == 2 then return im.InputTextMultiline(id, f.buf, cap, sz) end
            if sig == 3 then return im.InputTextMultiline(id, f.buf, sz, 0) end
            return im.InputTextMultiline(id, f.buf, sz)
        end
        local order = f.multiSig and { f.multiSig } or { 1, 2, 3, 4 }
        for _, sig in ipairs(order) do
            local okM, res = pcall(invokeMulti, sig)
            if okM then
                f.multiSig = sig
                changed, okCall = (res == true), true
                break
            end
        end
        if not okCall and f.multiSig then
            f.multiSig = nil
            for _, sig in ipairs({ 1, 2, 3, 4 }) do
                local okM, res = pcall(invokeMulti, sig)
                if okM then
                    f.multiSig = sig
                    changed, okCall = (res == true), true
                    break
                end
            end
        end
        if okCall and hint and trim(bufText(key)) == "" then
            ctx.uiText(x + 9, y + 7, hint, ctx.rgba(128, 135, 154, 255), 0.9)
        end
    else
        local function call(withHint, sig)
            if withHint and type(im.InputTextWithHint) == "function" then
                local ok, r = pcall(im.InputTextWithHint, id, hint or "", f.buf, cap)
                if ok then return true, r end
                return false
            end
            if sig == 1 then
                local ok, r = pcall(im.InputText, id, f.buf, cap)
                return ok, r
            end
            local ok, r = pcall(im.InputText, id, f.buf)
            return ok, r
        end
        local okM, res = call(true, 1)
        if not okM then okM, res = call(false, 1) end
        if not okM then okM, res = call(false, 2) end
        if okM then okCall, changed = true, (res == true) end
    end
    if ctx.popVar and nVar > 0 then ctx.popVar(nVar) end
    if ctx.popCol and nCol > 0 then ctx.popCol(nCol) end
    if not borderPushed and ctx.dl and ctx.dl.AddRect then
        local rx, ry, rw, rh = fieldRect(im, x, y, w, h)
        if rw and rh and rw > 6 and rh > 6 then
            pcall(ctx.dl.AddRect, ctx.dl, ctx.at(rx + 0.5, ry + 0.5),
                ctx.at(rx + rw - 0.5, ry + rh - 0.5),
                ctx.col32(255, 255, 255, 58), 6, 0, 1)
        end
    end
    return changed
end
local function tri(dl, at, cx, cy, size, dir, col)
    local s = tonumber(size) or 4
    local pts
    if dir == "up" then
        pts = { { cx, cy - s }, { cx - s, cy + s }, { cx + s, cy + s } }
    elseif dir == "down" then
        pts = { { cx, cy + s }, { cx - s, cy - s }, { cx + s, cy - s } }
    else
        pts = { { cx + s, cy }, { cx - s, cy - s }, { cx - s, cy + s } }
    end
    local p1, p2, p3 = at(pts[1][1], pts[1][2]), at(pts[2][1], pts[2][2]), at(pts[3][1], pts[3][2])
    if dl.AddTriangleFilled then
        if pcall(dl.AddTriangleFilled, dl, p1, p2, p3, col) then return true end
    end
    if dl.AddTriangle then
        if pcall(dl.AddTriangle, dl, p1, p2, p3, col, 1) then return true end
    end
    if dl.AddLine then
        local a = pcall(dl.AddLine, dl, p1, p2, col, 1)
        local b = pcall(dl.AddLine, dl, p2, p3, col, 1)
        local c = pcall(dl.AddLine, dl, p3, p1, col, 1)
        if a and b and c then return true end
    end
    return false
end
local function button(ctx, id, x, y, w, h, label, opts)
    opts = opts or {}
    local im, dl, at = ctx.im, ctx.dl, ctx.at
    local TH = theme()
    local ac = TH.accent or { 164, 112, 224, 255 }
    im.SetCursorPos(im.ImVec2(x, y))
    local clicked = im.InvisibleButton(id, im.ImVec2(w, h)) and true or false
    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
    local act = (im.IsItemActive and im.IsItemActive()) or false
    local bg, bd, fg
    if opts.danger then
        bg = (hov or act) and ctx.col32(255, 96, 96, 56) or ctx.col32(255, 96, 96, 32)
        bd = ctx.col32(255, 96, 96, (hov or act) and 130 or 84)
        fg = ctx.col32(255, 190, 190, 255)
    elseif opts.primary then
        bg = (hov or act) and ctx.col32(TH.accent2[1], TH.accent2[2], TH.accent2[3], 255)
            or ctx.col32(ac[1], ac[2], ac[3], 235)
        bd = ctx.col32(255, 255, 255, 45)
        fg = ctx.col32(18, 15, 24, 255)
    elseif opts.selected then
        bg = ctx.col32(ac[1], ac[2], ac[3], 40)
        bd = ctx.col32(ac[1], ac[2], ac[3], 125)
        fg = ctx.col32(250, 248, 255, 255)
    elseif act then
        bg, bd, fg = ctx.col32(255, 255, 255, 38), ctx.col32(255, 255, 255, 72), ctx.col32(250, 248, 255, 255)
    elseif hov then
        bg, bd, fg = ctx.col32(255, 255, 255, 32), ctx.col32(255, 255, 255, 64), ctx.col32(250, 248, 255, 255)
    else
        bg, bd = ctx.col32(255, 255, 255, 22), ctx.col32(255, 255, 255, 40)
        fg = opts.muted and ctx.col32(208, 202, 226, 255) or ctx.col32(240, 236, 250, 255)
    end
    ctx.roundRect(dl, at(x, y), at(x + w, y + h), bg, 6)
    if dl.AddRect then
        pcall(dl.AddRect, dl, at(x + 0.5, y + 0.5), at(x + w - 0.5, y + h - 0.5), bd, 6, 0, 1)
    end
    if opts.tri then
        local tc = (hov or act) and fg or bd
        tri(dl, at, x + w / 2, y + h / 2, opts.tri == "right" and 3.6 or 4, opts.tri, tc)
        return clicked, hov
    end
    local shown, tw = fitW(label, w - 12, ctx.drawnW, 0.92)
    if not tw or tw <= 0 then
        tw = utf8Len(shown) * 7 * 0.92
    end
    ctx.uiText(x + math.max(5, (w - tw) / 2), y + (h - lineH(ctx, 0.92)) / 2, shown, fg, 0.92)
    return clicked, hov
end
local function chip(ctx, x, y, label)
    local TH = theme()
    local w = 24
    if type(ctx.drawnW) == "function" then
        local ok, v = pcall(ctx.drawnW, label, 0.85)
        if ok and type(v) == "number" then w = v end
    end
    w = w + 18
    local h = 22
    ctx.roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h),
        ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 34), 11)
    ctx.uiText(x + 9, y + (h - lineH(ctx, 0.85)) / 2 + 1, label,
        ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 255), 0.85)
    return w
end
local PICK_BH, PICK_GAP = 30, 6
local PICK_PADX, PICK_PADY = 10, 9
local PICK_MIN_W, PICK_MAX_W = 108, 240
local PICK_ATTACH = 10
local PICK_SCREEN_GAP = 10
local function pickerLayoutItems(ctx, availW, items)
    local measure = ctx.drawnW
    local function mw(str)
        if type(measure) == "function" then
            local ok, v = pcall(measure, str, 0.94)
            if ok and type(v) == "number" and v > 0 then return v end
        end
        return utf8Len(str) * 7 * 0.94
    end
    items = (type(items) == "table") and items or QR.items
    local rows, cur, curW = {}, {}, 0
    for i = 1, #items do
        local item = items[i]
        local label = trim(tostring(item.name or ""))
        if label == "" then label = "шаблон" end
        local bw = math.floor(mw(label) + 28)
        if bw < PICK_MIN_W then bw = PICK_MIN_W end
        if bw > PICK_MAX_W then bw = PICK_MAX_W end
        if bw > availW then bw = math.max(60, availW) end
        if #cur > 0 and curW + PICK_GAP + bw > availW then
            rows[#rows + 1] = cur
            cur, curW = {}, 0
        end
        cur[#cur + 1] = { it = item, w = bw, label = label }
        curW = curW + bw + (#cur > 1 and PICK_GAP or 0)
    end
    if #cur > 0 then rows[#rows + 1] = cur end
    local winW = 0
    for r = 1, #rows do
        local sum = 0
        for i = 1, #rows[r] do sum = sum + rows[r][i].w + (i > 1 and PICK_GAP or 0) end
        if sum > winW then winW = sum end
    end
    return rows, winW
end
local function pickerLayout(ctx, availW)
    return pickerLayoutItems(ctx, availW, QR.items)
end
local function pickerDraw(ctx)
    if type(ctx) ~= "table" then return false end
    local im = ctx.im
    if not (im and ctx.begin and ctx.uiText and ctx.roundRect and ctx.col32 and ctx.rgba) then
        return false
    end
    if not QR.pickOpen then return false end
    if not (_G.GRND_REP and _G.GRND_REP.open) then
        QR.pickOpen, QR.pickFocus = false, false
        return false
    end
    QR.ensure()
    if QR.count() == 0 then
        QR.pickOpen, QR.pickFocus = false, false
        QR.toast("Шаблонов пока нет — создайте их в меню «Репорт», вкладка «Ответы на репорт»", "warn", 3.5)
        return false
    end
    QR.left = (QR.left or 0) + 1
    local TH = theme()
    local acC = TH.accent or { 164, 112, 224, 255 }
    local resX, resY = getScreenResolution()
    resX, resY = tonumber(resX) or 1920, tonumber(resY) or 1080
    local rowH = PICK_BH + PICK_GAP
    local R = _G.GRND_REP
    local repX, repW, repBottom
    if type(R) == "table" then
        repX = tonumber(R.winX)
        repW = tonumber(R.winW)
        local repY, repH = tonumber(R.winY), tonumber(R.winH)
        if repY and repH and repH > 0 then repBottom = repY + repH end
    end
    if not repW or repW <= 0 then repW = 600 end
    repW = math.max(240, math.min(repW, resX - 40))
    if not repX then repX = math.floor((resX - repW) / 2) end
    local maxW = math.min(920, math.max(240, resX - 80), repW)
    local rows, contentW = pickerLayout(ctx, maxW - PICK_PADX * 2)
    local rowsH = math.max(rowH, #rows * rowH - PICK_GAP)
    local minH = PICK_PADY * 2 + rowH
    local y
    if repBottom then
        y = repBottom + PICK_ATTACH
    else
        y = math.floor(resY * 0.62)
    end
    y = math.max(16, math.min(resY - minH - PICK_SCREEN_GAP, y))
    local maxViewH = math.max(rowH, math.floor(resY - y - PICK_SCREEN_GAP) - PICK_PADY * 2)
    local viewH = math.min(rowsH, maxViewH)
    local W = math.max(96, math.min(maxW, contentW + PICK_PADX * 2))
    local H = PICK_PADY + viewH + PICK_PADY
    local x = math.max(10, math.min(math.max(10, resX - W - 10), repX))
    pcall(im.SetNextWindowPos, im.ImVec2(x, y), ctx.always or 2)
    pcall(im.SetNextWindowSize, im.ImVec2(W, H), ctx.always or 2)
    if QR.pickFocus and im.SetNextWindowFocus then pcall(im.SetNextWindowFocus) end
    local flags = ctx.wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
        "NoCollapse", "NoScrollWithMouse", "NoSavedSettings")
    local nStyle, nCol = 0, 0
    if ctx.pushVarF and im.StyleVar and im.StyleVar.WindowRounding then
        if ctx.pushVarF(im.StyleVar.WindowRounding, 12) then nStyle = nStyle + 1 end
    end
    if ctx.pushVarV2 and im.StyleVar and im.StyleVar.WindowPadding then
        if ctx.pushVarV2(im.StyleVar.WindowPadding, 0, 0) then nStyle = nStyle + 1 end
    end
    if ctx.pushCol and im.Col then
        if im.Col.WindowBg and ctx.pushCol(im.Col.WindowBg, ctx.rgba(0, 0, 0, 0)) then nCol = nCol + 1 end
        if im.Col.Border and ctx.pushCol(im.Col.Border, ctx.rgba(0, 0, 0, 0)) then nCol = nCol + 1 end
    end
    local drawn = false
    if ctx.begin("##grnd_qr_picker", flags) then
        drawn = true
        QR.pickFocus = false
        local pos = im.GetWindowPos()
        local dl = im.GetWindowDrawList()
        local function at(dx, dy) return im.ImVec2(pos.x + dx, pos.y + dy) end
        local function box(bx, by, bw, bh, col, r)
            ctx.roundRect(dl, at(bx, by), at(bx + bw, by + bh), col, r or 0)
        end
        local function frame(bx, by, bw, bh, col, r)
            if dl.AddRect then
                pcall(dl.AddRect, dl, at(bx + 0.5, by + 0.5),
                    at(bx + bw - 0.5, by + bh - 0.5), col, r or 0, 0, 1)
            end
        end
        local function text(tx, ty, str, col, sc)
            ctx.uiText(tx, ty, str, col, sc)
        end
        box(4, 5, W - 4, H - 5, ctx.col32(0, 0, 0, 90), 12)
        box(0, 0, W, H, ctx.col32(12, 13, 19, 250), 12)
        frame(0, 0, W, H, ctx.col32(255, 255, 255, 30), 12)
        local mx, my = mouse(im)
        local maxScroll = math.max(0, rowsH - viewH)
        QR.pickScroll = scrollWheel(im, mx, my, x + PICK_PADX, y + PICK_PADY,
            W - PICK_PADX * 2, viewH, tonumber(QR.pickScroll) or 0, maxScroll, 42)
        local scroll = math.max(0, math.min(maxScroll, tonumber(QR.pickScroll) or 0))
        local clip = false
        if dl.PushClipRect then
            clip = pcall(dl.PushClipRect, dl, at(PICK_PADX - 4, PICK_PADY - 3),
                at(W - PICK_PADX + 4, PICK_PADY + viewH + 3), true)
        end
        local hoverIt, chooseIt = nil, nil
        local firstRow = math.max(1, math.floor(scroll / rowH))
        for r = firstRow, #rows do
            local ry = PICK_PADY + (r - 1) * rowH - scroll
            if ry >= PICK_PADY + viewH then break end
            local bx = PICK_PADX
            for i = 1, #rows[r] do
                local cell = rows[r][i]
                local top = math.max(ry, PICK_PADY)
                local bottom = math.min(ry + PICK_BH, PICK_PADY + viewH)
                if bottom - top > 8 then
                    im.SetCursorPos(im.ImVec2(bx, top))
                    local clicked = im.InvisibleButton("##grnd_qr_q_" .. tostring(cell.it.id),
                        im.ImVec2(cell.w, bottom - top)) and true or false
                    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                    local act = (im.IsItemActive and im.IsItemActive()) or false
                    local bg = act and ctx.col32(acC[1], acC[2], acC[3], 62)
                        or (hov and ctx.col32(acC[1], acC[2], acC[3], 38)
                            or ctx.col32(255, 255, 255, 24))
                    local bd = (hov or act) and ctx.col32(acC[1], acC[2], acC[3], 155)
                        or ctx.col32(255, 255, 255, 46)
                    box(bx, ry, cell.w, PICK_BH, bg, 7)
                    frame(bx, ry, cell.w, PICK_BH, bd, 7)
                    if hov or act then
                        box(bx, ry + 5, 2, PICK_BH - 10, ctx.col32(acC[1], acC[2], acC[3], 255), 1)
                    end
                    local shown, lw = fitW(cell.label, cell.w - 18, ctx.drawnW, 0.94)
                    if not lw or lw <= 0 then lw = utf8Len(shown) * 7 * 0.94 end
                    text(bx + math.max(7, (cell.w - lw) / 2),
                        ry + (PICK_BH - lineH(ctx, 0.94)) / 2, shown,
                        ctx.col32(250, 248, 255, 255), 0.94)
                    if hov then hoverIt = cell.it end
                    if clicked then chooseIt = cell.it end
                end
                bx = bx + cell.w + PICK_GAP
            end
        end
        if clip and dl.PopClipRect then pcall(dl.PopClipRect, dl) end
        if maxScroll > 0.5 then
            box(W - 6, PICK_PADY, 3, viewH, ctx.col32(255, 255, 255, 18), 2)
            local barH = math.max(16, viewH * (viewH / rowsH))
            local barY = PICK_PADY + (scroll / maxScroll) * (viewH - barH)
            box(W - 6, barY, 3, barH, ctx.col32(acC[1], acC[2], acC[3], 200), 2)
        end
        if hoverIt and type(im.SetTooltip) == "function" then
            pcall(im.SetTooltip, oneLine(hoverIt.text or ""))
        end
        if chooseIt then QR.choose(chooseIt) end
    end
    if ctx.popCol and nCol > 0 then ctx.popCol(nCol) end
    if ctx.popVar and nStyle > 0 then ctx.popVar(nStyle) end
    return drawn
end
_G.grndQrPickerDraw = function(ctx)
    local ok, res = pcall(pickerDraw, ctx)
    if ok then return res end
    QR.drawErr = tostring(res)
    print("{FF6666}[GRND]{FFFFFF} быстрые ответы: " .. tostring(res))
    return false
end
do
    local punCmds = {
        { id = "ban",   time = true,  unit = "дней",  reason = true },
        { id = "mute",  time = true,  unit = "минут", reason = true },
        { id = "rmute", time = true,  unit = "минут", reason = true },
    }
    local punById = {}
    for i = 1, #punCmds do punById[punCmds[i].id] = punCmds[i] end
    QR.punCmds = punCmds
    function QR.punDef(id)
        return punById[tostring(id or ""):lower()]
    end
    function QR.punPath()
        local base = tostring(QR.path() or "")
        local replaced = base:gsub("grnd_repquick%.cfg$", "grnd_reppunish.cfg")
        if replaced ~= base then return replaced end
        local dir = base:match("^(.*[/\\])")
        if dir then return dir .. "grnd_reppunish.cfg" end
        return "grnd_reppunish.cfg"
    end
    local unitShort = { ["дней"] = "д", ["минут"] = "мин" }
    function QR.punPreview(it)
        if type(it) ~= "table" then return "" end
        local def = QR.punDef(it.cmd)
        if not def then return "команда не выбрана" end
        local out = "/" .. def.id
        if def.time and trim(it.time or "") ~= "" then
            out = out .. " · " .. trim(it.time) .. " " .. (unitShort[def.unit or ""] or (def.unit or ""))
        end
        if def.reason and trim(it.reason or "") ~= "" then
            out = out .. " · " .. oneLine(it.reason)
        end
        return out
    end
    function QR.punNormalize()
        local P = QR.pun
        if type(P.items) ~= "table" then P.items = {} end
        local seen, out, maxId = {}, {}, 0
        for i = 1, #P.items do
            local it = P.items[i]
            if type(it) == "table" then
                local id = math.floor(tonumber(it.id) or 0)
                if id <= 0 or seen[id] then
                    id = 0
                    repeat id = id + 1 until not seen[id]
                end
                local cmd = tostring(it.cmd or ""):lower():gsub("[^%a]", "")
                if punById[cmd] then
                    local name = clampText(trim(utf(it.name or "")), MAX_NAME)
                    local text = clampText(cleanText(utf(it.text or "")), MAX_TEXT)
                    local time = clampText((trim(utf(it.time or "")):gsub("%D", "")), MAX_PTIME)
                    local reason = clampText(oneLine(utf(it.reason or "")), MAX_PREASON)
                    if name == "" then name = utf8Cut(QR.punPreview({ cmd = cmd, time = time, reason = reason }), 28) end
                    if name == "" then name = "/" .. cmd end
                    seen[id] = true
                    if id > maxId then maxId = id end
                    out[#out + 1] = { id = id, name = name, text = text,
                                      cmd = cmd, time = time, reason = reason }
                end
            end
        end
        P.items = out
        P.nextId = math.max(math.floor(tonumber(P.nextId) or 1), maxId + 1)
        if P.selId and not seen[math.floor(tonumber(P.selId) or 0)] then P.selId = nil end
        return out
    end
    function QR.punLoad()
        local P = QR.pun
        if P.loaded then return true end
        P.loaded = true
        local items, nextId = {}, nil
        local ok, f = pcall(GRND_CONFIG.open, QR.punPath(), "r")
        if ok and f then
            local cur = nil
            for line in f:lines() do
                line = tostring(line or "")
                if line == "---" then
                    cur = {}
                    items[#items + 1] = cur
                else
                    local k, v = line:match("^([%w_]+)=(.*)$")
                    if k then
                        if cur then
                            if k == "id" then cur.id = tonumber(v)
                            elseif k == "name" then cur.name = unesc(v)
                            elseif k == "text" then cur.text = unesc(v)
                            elseif k == "cmd" then cur.cmd = v
                            elseif k == "time" then cur.time = v
                            elseif k == "reason" then cur.reason = v end
                        elseif k == "nextId" then nextId = tonumber(v) end
                    end
                end
            end
            pcall(f.close, f)
        end
        P.items = items
        if nextId then P.nextId = nextId end
        QR.punNormalize()
        return true
    end
    function QR.punEnsure()
        local P = QR.pun
        if not P.loaded then pcall(QR.punLoad) end
        if type(P.items) ~= "table" then pcall(QR.punNormalize) end
        return P
    end
    function QR.punSave()
        local P = QR.pun
        QR.punNormalize()
        local ok, f = pcall(GRND_CONFIG.open, QR.punPath(), "w")
        if not ok or not f then return false end
        local escv = esc
        f:write("nextId=" .. tostring(P.nextId or 1) .. "\n")
        for i = 1, #P.items do
            local it = P.items[i]
            f:write("---\n")
            f:write("id=" .. tostring(it.id or 0) .. "\n")
            f:write("name=" .. escv(tostring(it.name or "")) .. "\n")
            f:write("text=" .. escv(tostring(it.text or "")) .. "\n")
            f:write("cmd=" .. tostring(it.cmd or "") .. "\n")
            f:write("time=" .. tostring(it.time or "") .. "\n")
            f:write("reason=" .. tostring(it.reason or "") .. "\n")
        end
        pcall(f.close, f)
        if GRND_CONFIG and type(GRND_CONFIG.flush) == "function" then
            pcall(GRND_CONFIG.flush)
        end
        return true
    end
    function QR.punById(id)
        local P = QR.pun
        id = math.floor(tonumber(id) or 0)
        if type(P.items) ~= "table" then return nil, nil end
        for i = 1, #P.items do
            if P.items[i].id == id then return P.items[i], i end
        end
        return nil, nil
    end
    function QR.punCount()
        local P = QR.pun
        return (type(P.items) == "table") and #P.items or 0
    end
    function QR.punAdd(name, text, cmd, time, reason)
        local P = QR.pun
        QR.punEnsure()
        local id = math.max(1, math.floor(tonumber(P.nextId) or 1))
        P.nextId = id + 1
        local it = { id = id, cmd = tostring(cmd or ""):lower(), time = tostring(time or ""),
                     reason = tostring(reason or ""), name = name, text = text }
        P.items[#P.items + 1] = it
        QR.punNormalize()
        return QR.punById(id)
    end
    function QR.punUpdate(id, name, text, cmd, time, reason)
        local it = QR.punById(id)
        if not it then return false end
        it.name, it.text = name, text
        it.cmd, it.time, it.reason = tostring(cmd or ""):lower(), tostring(time or ""), tostring(reason or "")
        QR.punNormalize()
        return true
    end
    function QR.punRemove(id)
        local P = QR.pun
        id = math.floor(tonumber(id) or 0)
        if type(P.items) ~= "table" then return false end
        for i = 1, #P.items do
            if P.items[i].id == id then
                table.remove(P.items, i)
                if P.selId == id then P.selId, P.formKey = nil, nil end
                return true
            end
        end
        return false
    end
    function QR.punMove(id, dir)
        local P = QR.pun
        local it, idx = QR.punById(id)
        if not it then return false end
        local other = idx + ((dir or 0) < 0 and -1 or 1)
        if other < 1 or other > #P.items then return false end
        P.items[idx], P.items[other] = P.items[other], P.items[idx]
        return true
    end
    function QR.punCommand(it, rep)
        if type(it) ~= "table" then return "" end
        local def = QR.punDef(it.cmd)
        if not def then return "" end
        rep = (type(rep) == "table") and rep or {}
        local pid = tostring(rep.id or rep.playerId or "")
        local out = "/" .. def.id .. " " .. pid
        if def.time then
            local t = tostring(it.time or ""):gsub("%D", "")
            if t ~= "" then out = out .. " " .. t end
        end
        if def.reason then
            local r = oneLine(QR.apply(it.reason or "", rep))
            if r ~= "" then out = out .. " " .. r end
        end
        return out
    end
    function QR.punChoose(it)
        if type(it) ~= "table" then return false end
        QR.punEnsure()
        local P = QR.pun
        local rep = QR.repInfo()
        local pid = tostring(rep.id or "")
        local label = tostring(it.name or ("/" .. tostring(it.cmd or "")))
        if pid:match("^%d+$") == nil then
            QR.toast("ID игрока не распознан — наказание не отправлено", "warn", 3)
            return false
        end
        local cmd = QR.punCommand(it, rep)
        if cmd == "" then
            QR.toast("В шаблоне не выбрана команда наказания", "warn", 3)
            return false
        end
        if utf8Len(cmd) > MAX_CHAT then
            cmd = utf8Cut(cmd, MAX_CHAT - 1) .. "…"
            QR.toast("Команда обрезана под лимит строки чата", "warn", 3)
        end
        local text = trim(QR.apply(it.text or "", rep))
        local mode = QR.modeOk(QR.mode)
        P.pickOpen, P.pickFocus = false, false
        local line = oneLine(text)
        if mode == "input" then
            local R = _G.GRND_REP
            local buf = R and R.answer
            if buf and type(grndBinderWriteCBuf) == "function" and line ~= "" then
                pcall(grndBinderWriteCBuf, buf, 256, byteCut(line, MAX_BUF))
                if R then R.focused = false end
            end
            if QR.sendChat(cmd) then
                QR.toast("Наказание отправлено, текст — в поле ответа", "ok", 3.4)
                return true
            end
            QR.toast("Не удалось отправить команду наказания", "warn", 3)
            return false
        end
        if line ~= "" and type(grndRepAnswer) == "function" then
            pcall(grndRepAnswer, pid, line)
        end
        local sent = QR.queueCmd(cmd)
        if sent then
            if line ~= "" then
                QR.toast("Ответ игроку /ans " .. pid .. " и наказание «"
                    .. utf8Cut(label, 20) .. "»", "ok", 3.4)
            else
                QR.toast("Наказание «" .. utf8Cut(label, 20) .. "» по ID " .. pid, "ok", 3)
            end
            QR.closeReport()
            return true
        end
        QR.toast("Не удалось отправить команду наказания", "warn", 3)
        return false
    end
    function QR.openPunPicker()
        QR.punEnsure()
        local P = QR.pun
        if QR.punCount() == 0 then
            P.pickOpen, P.pickFocus = false, false
            QR.toast("Шаблонов наказаний нет — создайте их в меню «Репорт», вкладка «Наказания»", "warn", 3.6)
            return false
        end
        QR.pickOpen, QR.pickFocus = false, false
        P.pickOpen, P.pickFocus = true, true
        P.pickScroll = 0
        return true
    end
    function QR.togglePunPicker()
        if QR.pun.pickOpen then
            QR.closePunPicker()
        else
            QR.openPunPicker()
        end
    end
    function QR.closePunPicker()
        QR.pun.pickOpen, QR.pun.pickFocus = false, false
    end
    local function punPickerDraw(ctx)
        if type(ctx) ~= "table" then return false end
        local im = ctx.im
        if not (im and ctx.begin and ctx.uiText and ctx.roundRect and ctx.col32 and ctx.rgba) then
            return false
        end
        local P = QR.pun
        if not P.pickOpen then return false end
        if not (_G.GRND_REP and _G.GRND_REP.open) then
            P.pickOpen, P.pickFocus = false, false
            return false
        end
        QR.punEnsure()
        if QR.punCount() == 0 then
            P.pickOpen, P.pickFocus = false, false
            QR.toast("Шаблонов наказаний нет — создайте их в меню «Репорт», вкладка «Наказания»", "warn", 3.6)
            return false
        end
        P.left = (P.left or 0) + 1
        local TH = theme()
        local acC = TH.accent or { 164, 112, 224, 255 }
        local resX, resY = getScreenResolution()
        resX, resY = tonumber(resX) or 1920, tonumber(resY) or 1080
        local rowH = PICK_BH + PICK_GAP
        local R = _G.GRND_REP
        local repX, repW, repBottom
        if type(R) == "table" then
            repX, repW = tonumber(R.winX), tonumber(R.winW)
            local repY, repH = tonumber(R.winY), tonumber(R.winH)
            if repY and repH and repH > 0 then repBottom = repY + repH end
        end
        if not repW or repW <= 0 then repW = 600 end
        repW = math.max(240, math.min(repW, resX - 40))
        if not repX then repX = math.floor((resX - repW) / 2) end
        local maxW = math.min(920, math.max(240, resX - 80), repW)
        local rows, contentW = pickerLayoutItems(ctx, maxW - PICK_PADX * 2, P.items)
        local rowsH = math.max(rowH, #rows * rowH - PICK_GAP)
        local minH = PICK_PADY * 2 + rowH
        local y
        if repBottom then
            y = repBottom + PICK_ATTACH
        else
            y = math.floor(resY * 0.62)
        end
        y = math.max(16, math.min(resY - minH - PICK_SCREEN_GAP, y))
        local maxViewH = math.max(rowH, math.floor(resY - y - PICK_SCREEN_GAP) - PICK_PADY * 2)
        local viewH = math.min(rowsH, maxViewH)
        local W = math.max(96, math.min(maxW, contentW + PICK_PADX * 2))
        local H = PICK_PADY + viewH + PICK_PADY
        local x = repX + math.floor((repW - W) / 2)
        x = math.max(10, math.min(math.max(10, resX - W - 10), x))
        pcall(im.SetNextWindowPos, im.ImVec2(x, y), ctx.always or 2)
        pcall(im.SetNextWindowSize, im.ImVec2(W, H), ctx.always or 2)
        if P.pickFocus and im.SetNextWindowFocus then pcall(im.SetNextWindowFocus) end
        local flags = ctx.wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
            "NoCollapse", "NoScrollWithMouse", "NoSavedSettings")
        local nStyle, nCol = 0, 0
        if ctx.pushVarF and im.StyleVar and im.StyleVar.WindowRounding then
            if ctx.pushVarF(im.StyleVar.WindowRounding, 12) then nStyle = nStyle + 1 end
        end
        if ctx.pushVarV2 and im.StyleVar and im.StyleVar.WindowPadding then
            if ctx.pushVarV2(im.StyleVar.WindowPadding, 0, 0) then nStyle = nStyle + 1 end
        end
        if ctx.pushCol and im.Col then
            if im.Col.WindowBg and ctx.pushCol(im.Col.WindowBg, ctx.rgba(0, 0, 0, 0)) then nCol = nCol + 1 end
            if im.Col.Border and ctx.pushCol(im.Col.Border, ctx.rgba(0, 0, 0, 0)) then nCol = nCol + 1 end
        end
        local drawn = false
        if ctx.begin("##grnd_qr_pun_picker", flags) then
            drawn = true
            P.pickFocus = false
            local pos = im.GetWindowPos()
            local dl = im.GetWindowDrawList()
            local function at(dx, dy) return im.ImVec2(pos.x + dx, pos.y + dy) end
            local function box(bx, by, bw, bh, col, r)
                ctx.roundRect(dl, at(bx, by), at(bx + bw, by + bh), col, r or 0)
            end
            local function frame(bx, by, bw, bh, col, r)
                if dl.AddRect then
                    pcall(dl.AddRect, dl, at(bx + 0.5, by + 0.5),
                        at(bx + bw - 0.5, by + bh - 0.5), col, r or 0, 0, 1)
                end
            end
            local function text(tx, ty, str, col, sc)
                ctx.uiText(tx, ty, str, col, sc)
            end
            box(4, 5, W - 4, H - 5, ctx.col32(0, 0, 0, 90), 12)
            box(0, 0, W, H, ctx.col32(12, 13, 19, 250), 12)
            frame(0, 0, W, H, ctx.col32(255, 255, 255, 30), 12)
            local mx, my = mouse(im)
            local maxScroll = math.max(0, rowsH - viewH)
            P.pickScroll = scrollWheel(im, mx, my, x + PICK_PADX, y + PICK_PADY,
                W - PICK_PADX * 2, viewH, tonumber(P.pickScroll) or 0, maxScroll, 42)
            local scroll = math.max(0, math.min(maxScroll, tonumber(P.pickScroll) or 0))
            local clip = false
            if dl.PushClipRect then
                clip = pcall(dl.PushClipRect, dl, at(PICK_PADX - 4, PICK_PADY - 3),
                    at(W - PICK_PADX + 4, PICK_PADY + viewH + 3), true)
            end
            local hoverIt, chooseIt = nil, nil
            local firstRow = math.max(1, math.floor(scroll / rowH))
            for r = firstRow, #rows do
                local ry = PICK_PADY + (r - 1) * rowH - scroll
                if ry >= PICK_PADY + viewH then break end
                local bx = PICK_PADX
                for i = 1, #rows[r] do
                    local cell = rows[r][i]
                    local top = math.max(ry, PICK_PADY)
                    local bottom = math.min(ry + PICK_BH, PICK_PADY + viewH)
                    if bottom - top > 8 then
                        im.SetCursorPos(im.ImVec2(bx, top))
                        local clicked = im.InvisibleButton("##grnd_qr_pun_q_" .. tostring(cell.it.id),
                            im.ImVec2(cell.w, bottom - top)) and true or false
                        local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                        local act = (im.IsItemActive and im.IsItemActive()) or false
                        local bg = act and ctx.col32(acC[1], acC[2], acC[3], 62)
                            or (hov and ctx.col32(acC[1], acC[2], acC[3], 38)
                                or ctx.col32(255, 255, 255, 24))
                        local bd = (hov or act) and ctx.col32(acC[1], acC[2], acC[3], 155)
                            or ctx.col32(255, 255, 255, 46)
                        box(bx, ry, cell.w, PICK_BH, bg, 7)
                        frame(bx, ry, cell.w, PICK_BH, bd, 7)
                        if hov or act then
                            box(bx, ry + 5, 2, PICK_BH - 10, ctx.col32(acC[1], acC[2], acC[3], 255), 1)
                        end
                        local shown, lw = fitW(cell.label, cell.w - 18, ctx.drawnW, 0.94)
                        if not lw or lw <= 0 then lw = utf8Len(shown) * 7 * 0.94 end
                        text(bx + math.max(7, (cell.w - lw) / 2),
                            ry + (PICK_BH - lineH(ctx, 0.94)) / 2, shown,
                            ctx.col32(250, 248, 255, 255), 0.94)
                        if hov then hoverIt = cell.it end
                        if clicked then chooseIt = cell.it end
                    end
                    bx = bx + cell.w + PICK_GAP
                end
            end
            if clip and dl.PopClipRect then pcall(dl.PopClipRect, dl) end
            if maxScroll > 0.5 then
                box(W - 6, PICK_PADY, 3, viewH, ctx.col32(255, 255, 255, 18), 2)
                local barH = math.max(16, viewH * (viewH / rowsH))
                local barY = PICK_PADY + (scroll / maxScroll) * (viewH - barH)
                box(W - 6, barY, 3, barH, ctx.col32(acC[1], acC[2], acC[3], 200), 2)
            end
            if hoverIt and type(im.SetTooltip) == "function" then
                local line = QR.punCommand(hoverIt, QR.repInfo())
                local body = oneLine(hoverIt.text or "")
                if body ~= "" then line = line .. " · " .. utf8Cut(body, 40) end
                pcall(im.SetTooltip, line)
            end
            if chooseIt then QR.punChoose(chooseIt) end
        end
        if ctx.popCol and nCol > 0 then ctx.popCol(nCol) end
        if ctx.popVar and nStyle > 0 then ctx.popVar(nStyle) end
        return drawn
    end
    _G.grndQrPunPickerDraw = function(ctx)
        local ok, res = pcall(punPickerDraw, ctx)
        if ok then return res end
        QR.punDrawErr = tostring(res)
        print("{FF6666}[GRND]{FFFFFF} шаблоны наказаний: " .. tostring(res))
        return false
    end
end
local function formSync()
    local it = (not QR.isNew) and QR.selId and QR.byId(QR.selId) or nil
    local key = QR.isNew and "new" or (it and ("id:" .. tostring(it.id)) or "none")
    if QR.formKey ~= key then
        QR.formKey = key
        bufReload("editName")
        bufReload("editText")
    end
    return it
end
local function settingsList(ctx, x, y, w, h)
    local TH = theme()
    local im = ctx.im
    ctx.roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h), ctx.col32(255, 255, 255, 10), 10)
    if ctx.dl.AddRect then
        pcall(ctx.dl.AddRect, ctx.dl, ctx.at(x + 0.5, y + 0.5), ctx.at(x + w - 0.5, y + h - 0.5),
            ctx.col32(255, 255, 255, 22), 10, 0, 1)
    end
    local headH = 32
    ctx.uiText(x + 12, y + 9, "Список шаблонов",
        ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 0.9)
    local q = trim(lower(QR.filter))
    local list = {}
    for i = 1, #QR.items do
        local it = QR.items[i]
        if q == "" or lower(it.name):find(q, 1, true) or lower(it.text):find(q, 1, true) then
            list[#list + 1] = it
        end
    end
    local cnt = tostring(#list)
    if q ~= "" then cnt = cnt .. " / " .. tostring(QR.count()) end
    local cw = 30
    if type(ctx.drawnW) == "function" then
        local ok, v = pcall(ctx.drawnW, cnt, 0.82)
        if ok and type(v) == "number" then cw = v end
    end
    ctx.roundRect(ctx.dl, ctx.at(x + w - 14 - cw - 8, y + 8), ctx.at(x + w - 14, y + 26),
        ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 34), 9)
    ctx.uiText(x + w - 14 - cw - 4, y + 10, cnt,
        ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 255), 0.82)
    local listY = y + headH
    local listH = h - headH - 6
    if listH < 40 then return end
    local rowH = 48
    local maxScroll = math.max(0, #list * rowH - listH)
    local mx, my = mouse(im)
    local wp = im.GetWindowPos()
    if wp and wp.x then
        QR.listScroll = scrollWheel(im, mx, my, wp.x + x + 2, wp.y + listY, w - 4, listH,
            tonumber(QR.listScroll) or 0, maxScroll, 42)
    end
    QR.listScroll = math.max(0, math.min(maxScroll, tonumber(QR.listScroll) or 0))
    local clip = false
    if ctx.dl.PushClipRect then
        clip = pcall(ctx.dl.PushClipRect, ctx.dl, ctx.at(x + 2, listY), ctx.at(x + w - 2, listY + listH), true)
    end
    if #list == 0 then
        ctx.uiText(x + 14, listY + 10,
            (QR.count() == 0) and "Пока пусто — нажмите «+ Новый шаблон»" or "Ничего не найдено",
            ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255), 0.86)
    end
    local ac = TH.accent
    local first = math.floor((QR.listScroll or 0) / rowH)
    for i = first + 1, math.min(#list, first + math.ceil(listH / rowH) + 1) do
        local it = list[i]
        local iy = listY + (i - 1) * rowH - (QR.listScroll or 0)
        if iy + rowH >= listY and iy <= listY + listH then
            local sel = (QR.selId == it.id) and not QR.isNew
            local fully = (iy >= listY - 0.5) and (iy + rowH <= listY + listH + 0.5)
            local wy = math.max(iy + 2, listY + 1)
            local wh = math.min(iy + rowH - 4, listY + listH - 1) - wy
            local clicked = false
            if wh > 6 then
                im.SetCursorPos(im.ImVec2(x + 6, wy))
                clicked = im.InvisibleButton("##grnd_qr_row_" .. tostring(it.id),
                    im.ImVec2(w - 70, wh)) and true or false
            end
            local hov = (im.IsItemHovered and im.IsItemHovered()) or false
            ctx.roundRect(ctx.dl, ctx.at(x + 6, iy + 2), ctx.at(x + w - 6, iy + rowH - 4),
                sel and ctx.col32(ac[1], ac[2], ac[3], 32)
                    or (hov and ctx.col32(255, 255, 255, 13) or ctx.col32(255, 255, 255, 5)), 8)
            if sel then
                ctx.roundRect(ctx.dl, ctx.at(x + 6, iy + 9), ctx.at(x + 9, iy + rowH - 11),
                    ctx.col32(ac[1], ac[2], ac[3], 255), 2)
            end
            local tW = w - 12 - 52 - 18
            ctx.uiText(x + 18, iy + 7, fit(it.name or "", tW, ctx.drawnW, 0.94),
                ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 0.94)
            ctx.uiText(x + 18, iy + 25, fit(oneLine(it.text or ""), tW, ctx.drawnW, 0.78),
                ctx.col32(TH.textMuted[1], TH.textMuted[2], TH.textMuted[3], 255), 0.78)
            if clicked then
                QR.selId, QR.isNew, QR.delArm = it.id, false, nil
                QR.note = nil
            end
            local bx = x + w - 12 - 48
            local by = iy + math.floor((rowH - 6 - 24) / 2) + 3
            if fully and button(ctx, "##grnd_qr_up_" .. tostring(it.id), bx, by, 22, 24, "",
                { muted = true, tri = "up" }) then
                QR.move(it.id, -1)
                pcall(QR.save)
            elseif not fully then
                tri(ctx.dl, ctx.at, bx + 11, iy + 20, 4, "up", ctx.col32(255, 255, 255, 60))
            end
            if fully and button(ctx, "##grnd_qr_dn_" .. tostring(it.id), bx + 26, by, 22, 24, "",
                { muted = true, tri = "down" }) then
                QR.move(it.id, 1)
                pcall(QR.save)
            elseif not fully then
                tri(ctx.dl, ctx.at, bx + 37, iy + 20, 4, "down", ctx.col32(255, 255, 255, 60))
            end
        end
    end
    if clip and ctx.dl.PopClipRect then pcall(ctx.dl.PopClipRect, ctx.dl) end
    if maxScroll > 0.5 then
        local trackX = x + w - 5
        ctx.roundRect(ctx.dl, ctx.at(trackX, listY), ctx.at(trackX + 3, listY + listH),
            ctx.col32(255, 255, 255, 18), 2)
        local barH = math.max(18, listH * (listH / (#list * rowH)))
        local barY = listY + ((QR.listScroll or 0) / maxScroll) * (listH - barH)
        ctx.roundRect(ctx.dl, ctx.at(trackX, barY), ctx.at(trackX + 3, barY + barH),
            ctx.col32(ac[1], ac[2], ac[3], 200), 2)
    end
end
local function settingsEditor(ctx, x, y, w, h)
    local TH = theme()
    local it = formSync()
    ctx.roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h), ctx.col32(255, 255, 255, 10), 10)
    if ctx.dl.AddRect then
        pcall(ctx.dl.AddRect, ctx.dl, ctx.at(x + 0.5, y + 0.5), ctx.at(x + w - 0.5, y + h - 0.5),
            ctx.col32(255, 255, 255, 22), 10, 0, 1)
    end
    local title = QR.isNew and "Новый шаблон" or "Редактор шаблона"
    ctx.uiText(x + 12, y + 9, title, ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 0.9)
    if not it and not QR.isNew then
        local muted = ctx.col32(TH.textMuted[1], TH.textMuted[2], TH.textMuted[3], 255)
        local dim = ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255)
        ctx.uiText(x + 12, y + 38, "Выберите шаблон слева", muted, 0.92)
        ctx.uiText(x + 12, y + 58, "или нажмите «+ Новый шаблон».", muted, 0.92)
        ctx.uiText(x + 12, y + 92, "Кнопка «Быстрые ответы» в окне репорта", dim, 0.82)
        ctx.uiText(x + 12, y + 108, "откроет этот список с поиском,", dim, 0.82)
        ctx.uiText(x + 12, y + 124, "клик по шаблону отправит текст.", dim, 0.82)
        return
    end
    local pad = 12
    local ix, iw = x + pad, w - pad * 2
    local yy = y + 32
    ctx.uiText(ix, yy, "Название", ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255), 0.82)
    yy = yy + 17
    field(ctx, "##grnd_qr_edit_name", "editName", 64,
        ix, yy, iw, 28, "Например: Приветствие", false, it and it.name or "")
    yy = yy + 36
    ctx.uiText(ix, yy, "Текст ответа", ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255), 0.82)
    yy = yy + 17
    local btnH, footH = 32, 12
    local textH = (y + h) - yy - btnH - footH - 10
    if textH < 56 then textH = 56 end
    field(ctx, "##grnd_qr_edit_text", "editText", 2048,
        ix, yy, iw, textH, "Текст, который уйдёт игроку…", true, it and it.text or "")
    yy = yy + textH + 5
    local by = y + h - btnH - 6
    local bw1 = math.min(146, math.floor(iw * 0.4))
    if button(ctx, "##grnd_qr_save", ix, by, bw1, btnH, "Сохранить", { primary = true }) then
        local name = trim(bufText("editName"))
        local text = cleanText(bufText("editText"))
        if text == "" then
            QR.toast("Введите текст ответа", "warn", 2.6)
        else
            if QR.isNew then
                local created = QR.add(name, text)
                QR.isNew = false
                QR.selId = created and created.id or nil
                QR.formKey = nil
                formSync()
            else
                QR.update(QR.selId, name, text)
            end
            bufReload("editName")
            bufReload("editText")
            pcall(QR.save)
            QR.toast("Шаблон сохранён", "ok", 2.2)
        end
    end
    local bx = ix + bw1 + 8
    local bw2 = math.min(112, math.floor(iw * 0.28))
    if button(ctx, "##grnd_qr_cancel", bx, by, bw2, btnH, "Отмена", {}) then
        QR.isNew, QR.delArm, QR.formKey = false, nil, nil
        formSync()
        QR.toast("Изменения отменены", "ok", 2.0)
    end
    if not QR.isNew and it then
        local bx2 = bx + bw2 + 8
        local bw3 = iw - (bx2 - ix)
        if bw3 >= 90 then
            local label = (QR.delArm == it.id) and "Точно удалить?" or "Удалить"
            if button(ctx, "##grnd_qr_remove", bx2, by, bw3, btnH, label, { danger = true }) then
                if QR.delArm == it.id then
                    QR.remove(it.id)
                    QR.delArm, QR.formKey = nil, nil
                    formSync()
                    pcall(QR.save)
                    QR.toast("Шаблон удалён", "ok", 2.2)
                else
                    QR.delArm = it.id
                end
            end
        end
    end
end
local function settingsDraw(ctx)
    if type(ctx) ~= "table" then return false end
    local im = ctx.im
    if not (im and ctx.uiText and ctx.roundRect and ctx.col32 and ctx.rgba and ctx.at) then
        return false
    end
    local TH = theme()
    QR.ensure()
    local x, y, w, h = ctx.x, ctx.y, ctx.w, ctx.h
    if not (x and y and w and h) or w < 240 or h < 140 then return false end
    ctx.uiText(x, y + 1, "Шаблоны быстрых ответов",
        ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 1.0)
    local tw = 220
    if type(ctx.drawnW) == "function" then
        local ok, v = pcall(ctx.drawnW, "Шаблоны быстрых ответов", 1.0)
        if ok and type(v) == "number" then tw = v end
    end
    chip(ctx, x + tw + 10, y - 2, "шаблонов: " .. tostring(QR.count()))
    local newW = 148
    local searchW = math.min(190, math.max(118, math.floor(w * 0.24)))
    local searchX = x + w - newW - searchW - 10
    if searchX > x + tw + 110 then
        field(ctx, "##grnd_qr_search", "settingsSearch", 64,
            searchX, y - 3, searchW, 28, "Поиск…", false, QR.filter)
        QR.filter = bufText("settingsSearch")
    end
    if button(ctx, "##grnd_qr_new", x + w - newW, y - 4, newW, 30, "+ Новый шаблон",
        { primary = not QR.isNew }) then
        QR.isNew, QR.selId, QR.delArm = true, nil, nil
        QR.formKey = nil
        formSync()
        QR.toast("Заполните название и текст", "ok", 2.4)
    end
    local yy = y + 34
    local gap = 14
    local listW = math.floor((w - gap) * 0.36)
    if listW < 200 then listW = 200 end
    if listW > 300 then listW = 300 end
    local contentH = (y + h) - yy
    if contentH < 120 then contentH = 120 end
    settingsList(ctx, x, yy, listW, contentH)
    settingsEditor(ctx, x + listW + gap, yy, w - listW - gap, contentH)
    return true
end
_G.grndQrSettingsDraw = function(ctx)
    local ok, res = pcall(settingsDraw, ctx)
    if ok then return res end
    QR.drawErr = tostring(res)
    print("{FF6666}[GRND]{FFFFFF} шаблоны ответов: " .. tostring(res))
    return false
end
do
    local PUN_TEXT_H = 68
    local PUN_ROW_H = 28
    local PUN_SEL_H = 28
    local function punFormSync()
        local P = QR.pun
        local it = (not P.isNew) and P.selId and QR.punById(P.selId) or nil
        local key = P.isNew and "new" or (it and ("id:" .. tostring(it.id)) or "none")
        if P.formKey ~= key then
            P.formKey = key
            bufReload("punName")
            bufReload("punText")
            bufReload("punTime")
            bufReload("punReason")
        end
        return it
    end
    local function punOutsideClick(ddX, ddY, ddW, ddH, selY, selH)
        local alive = _G and _G.grndClickAlive
        if type(alive) ~= "function" then return false end
        local ok, hit = pcall(alive)
        if not (ok and hit) then return false end
        local M = _G and _G.GRND_MOUSE
        if type(M) ~= "table" then return false end
        local mx, my = tonumber(M.x) or -1, tonumber(M.y) or -1
        if mx >= ddX and mx <= ddX + ddW and my >= ddY and my <= ddY + ddH then return false end
        if mx >= ddX and mx <= ddX + ddW and my >= selY and my <= selY + selH then return false end
        return true
    end
    local function punListDraw(ctx, x, y, w, h)
        local TH = theme()
        local im = ctx.im
        local P = QR.pun
        ctx.roundRect(ctx.dl, ctx.at(x, y), ctx.at(x + w, y + h), ctx.col32(255, 255, 255, 10), 10)
        if ctx.dl.AddRect then
            pcall(ctx.dl.AddRect, ctx.dl, ctx.at(x + 0.5, y + 0.5), ctx.at(x + w - 0.5, y + h - 0.5),
                ctx.col32(255, 255, 255, 22), 10, 0, 1)
        end
        local headH = 32
        ctx.uiText(x + 12, y + 9, "Список наказаний",
            ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 0.9)
        local q = trim(lower(P.filter))
        local list = {}
        for i = 1, #P.items do
            local it = P.items[i]
            local hay = lower(tostring(it.name or "") .. " " .. tostring(it.cmd or "") .. " "
                .. tostring(it.reason or "") .. " " .. tostring(it.text or ""))
            if q == "" or hay:find(q, 1, true) then list[#list + 1] = it end
        end
        local cnt = tostring(#list)
        if q ~= "" then cnt = cnt .. " / " .. tostring(QR.punCount()) end
        local cw = 30
        if type(ctx.drawnW) == "function" then
            local ok, v = pcall(ctx.drawnW, cnt, 0.82)
            if ok and type(v) == "number" then cw = v end
        end
        ctx.roundRect(ctx.dl, ctx.at(x + w - 14 - cw - 8, y + 8), ctx.at(x + w - 14, y + 26),
            ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 34), 9)
        ctx.uiText(x + w - 14 - cw - 4, y + 10, cnt,
            ctx.col32(TH.accent[1], TH.accent[2], TH.accent[3], 255), 0.82)
        local listY = y + headH
        local listH = h - headH - 6
        if listH < 40 then return end
        local rowH = 48
        local maxScroll = math.max(0, #list * rowH - listH)
        local mx, my = mouse(im)
        local wp = im.GetWindowPos()
        if wp and wp.x then
            P.listScroll = scrollWheel(im, mx, my, wp.x + x + 2, wp.y + listY, w - 4, listH,
                tonumber(P.listScroll) or 0, maxScroll, 42)
        end
        P.listScroll = math.max(0, math.min(maxScroll, tonumber(P.listScroll) or 0))
        local clip = false
        if ctx.dl.PushClipRect then
            clip = pcall(ctx.dl.PushClipRect, ctx.dl, ctx.at(x + 2, listY), ctx.at(x + w - 2, listY + listH), true)
        end
        if #list == 0 then
            ctx.uiText(x + 14, listY + 10,
                (QR.punCount() == 0) and "Пока пусто — нажмите «+ Новый шаблон»" or "Ничего не найдено",
                ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255), 0.86)
        end
        local ac = TH.accent or { 164, 112, 224, 255 }
        for i = 1, #list do
            local it = list[i]
            local iy = listY + (i - 1) * rowH - (P.listScroll or 0)
            local fully = (iy >= listY - 0.5) and (iy + rowH <= listY + listH + 0.5)
            if iy + rowH >= listY and iy <= listY + listH then
                local sel = (P.selId == it.id)
                local wy = math.max(iy + 2, listY + 1)
                local wh = math.min(iy + rowH - 4, listY + listH - 1) - wy
                local clicked = false
                if wh > 6 then
                    im.SetCursorPos(im.ImVec2(x + 6, wy))
                    clicked = im.InvisibleButton("##grnd_qr_pun_row_" .. tostring(it.id),
                        im.ImVec2(w - 70, wh)) and true or false
                end
                local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                ctx.roundRect(ctx.dl, ctx.at(x + 6, iy + 2), ctx.at(x + w - 6, iy + rowH - 4),
                    sel and ctx.col32(ac[1], ac[2], ac[3], 32)
                        or (hov and ctx.col32(255, 255, 255, 13) or ctx.col32(255, 255, 255, 5)), 8)
                if sel then
                    ctx.roundRect(ctx.dl, ctx.at(x + 6, iy + 9), ctx.at(x + 9, iy + rowH - 11),
                        ctx.col32(ac[1], ac[2], ac[3], 255), 2)
                end
