        end
        local pad = 12
        local ix, iw = x + pad, w - pad * 2
        local btnH, footH = 32, 12
        local by = y + h - btnH - 6
        local yy = y + 32
        ctx.uiText(ix, yy, "Название", dim, 0.82)
        yy = yy + 17
        field(ctx, "##grnd_qr_pun_name", "punName", 64,
            ix, yy, iw, 28, "Например: Мут 60 минут", false, it and it.name or "")
        yy = yy + 36
        ctx.uiText(ix, yy, "Ответ на репорт", dim, 0.82)
        yy = yy + 17
        field(ctx, "##grnd_qr_pun_text", "punText", 2048,
            ix, yy, iw, PUN_TEXT_H, "Текст, который уйдёт игроку…", true, it and it.text or "")
        yy = yy + PUN_TEXT_H + 10
        local cmdBuf = bufGet(im, "punCmd", 16)
        if not cmdBuf then
            ctx.uiText(ix, yy, "Команда наказания: поле недоступно", dim, 0.85)
            return
        end
        if P.cmdSync ~= P.formKey then
            P.cmdSync = P.formKey
            bufWrite("punCmd", it and it.cmd or "")
        end
        local curCmd = trim(bufText("punCmd")):lower()
        local def = QR.punDef(curCmd)
        ctx.uiText(ix, yy, "Команда наказания", dim, 0.82)
        yy = yy + 17
        local selY = yy
        local ac = TH.accent or { 164, 112, 224, 255 }
        im.SetCursorPos(im.ImVec2(ix, selY))
        local selClicked = im.InvisibleButton("##grnd_qr_pun_cmd", im.ImVec2(iw, PUN_SEL_H)) and true or false
        local selHov = (im.IsItemHovered and im.IsItemHovered()) or false
        ctx.roundRect(ctx.dl, ctx.at(ix, selY), ctx.at(ix + iw, selY + PUN_SEL_H),
            (selHov or P.comboOpen) and ctx.col32(255, 255, 255, 26) or ctx.col32(255, 255, 255, 12), 6)
        if ctx.dl.AddRect then
            pcall(ctx.dl.AddRect, ctx.dl, ctx.at(ix + 0.5, selY + 0.5), ctx.at(ix + iw - 0.5, selY + PUN_SEL_H - 0.5),
                (selHov or P.comboOpen) and ctx.col32(ac[1], ac[2], ac[3], 150)
                    or ctx.col32(255, 255, 255, 46), 6, 0, 1)
        end
        local curLabel = def and ("/" .. def.id) or "Выберите команду"
        ctx.uiText(ix + 10, selY + (PUN_SEL_H - lineH(ctx, 0.9)) / 2, curLabel,
            def and ctx.col32(240, 236, 250, 255) or muted, 0.9)
        tri(ctx.dl, ctx.at, ix + iw - 14, selY + PUN_SEL_H / 2, 4, "down",
            (selHov or P.comboOpen) and ctx.col32(ac[1], ac[2], ac[3], 235) or muted)
        if selClicked and QR.punCmds then
            P.comboOpen = not P.comboOpen
            P.comboScroll = 0
        end
        if P.comboOpen and QR.punCmds then
            local ddX, ddY, ddW = ix, selY + PUN_SEL_H + 4, iw
            local ddAvail = math.max(PUN_ROW_H, (by - 8) - ddY)
            local step = PUN_ROW_H + 2
            local maxRows = math.max(1, math.floor((ddAvail - 8) / step))
            local rowsN = math.min(#QR.punCmds, maxRows)
            local viewH = rowsN * step - 2
            local maxScroll = math.max(0, #QR.punCmds * step - 2 - viewH)
            local mx2, my2 = mouse(im)
            local winPos = im.GetWindowPos()
            local scx, scy = (winPos and winPos.x or 0) + ddX, (winPos and winPos.y or 0) + ddY
            P.comboScroll = scrollWheel(im, mx2, my2, scx, scy, ddW, viewH,
                tonumber(P.comboScroll) or 0, maxScroll, step)
            local scroll = math.max(0, math.min(maxScroll, tonumber(P.comboScroll) or 0))
            ctx.roundRect(ctx.dl, ctx.at(ddX - 2, ddY - 2), ctx.at(ddX + ddW + 2, ddY + viewH + 2),
                ctx.col32(16, 17, 24, 252), 8)
            if ctx.dl.AddRect then
                pcall(ctx.dl.AddRect, ctx.dl, ctx.at(ddX - 1.5, ddY - 1.5), ctx.at(ddX + ddW + 1.5, ddY + viewH + 1.5),
                    ctx.col32(255, 255, 255, 34), 8, 0, 1)
            end
            local clipDD = false
            if ctx.dl.PushClipRect then
                clipDD = pcall(ctx.dl.PushClipRect, ctx.dl, ctx.at(ddX, ddY), ctx.at(ddX + ddW, ddY + viewH), true)
            end
            local firstRow = math.max(1, math.floor(scroll / step) + 1)
            for i = firstRow, #QR.punCmds do
                local d = QR.punCmds[i]
                local ry = ddY + (i - 1) * step - scroll
                if ry >= ddY + viewH then break end
                local top = math.max(ry, ddY)
                local bottom = math.min(ry + PUN_ROW_H, ddY + viewH)
                if bottom - top > 6 then
                    im.SetCursorPos(im.ImVec2(ddX, top))
                    local clicked = im.InvisibleButton("##grnd_qr_pun_cmd_" .. d.id,
                        im.ImVec2(ddW, bottom - top)) and true or false
                    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                    local sel = (d.id == curCmd)
                    ctx.roundRect(ctx.dl, ctx.at(ddX, ry), ctx.at(ddX + ddW, ry + PUN_ROW_H),
                        sel and ctx.col32(ac[1], ac[2], ac[3], 46)
                            or (hov and ctx.col32(255, 255, 255, 20) or ctx.col32(255, 255, 255, 0)), 6)
                    if sel then
                        ctx.roundRect(ctx.dl, ctx.at(ddX + 4, ry + 7), ctx.at(ddX + 7, ry + PUN_ROW_H - 7),
                            ctx.col32(ac[1], ac[2], ac[3], 255), 2)
                    end
                    ctx.uiText(ddX + 14, ry + (PUN_ROW_H - lineH(ctx, 0.9)) / 2, "/" .. d.id,
                        sel and ctx.col32(250, 248, 255, 255)
                            or (hov and ctx.col32(240, 236, 250, 255) or ctx.col32(206, 200, 226, 255)), 0.9)
                    local hint = d.time and (d.unit or "") or "без срока"
                    if d.reason and d.time then hint = hint .. " · причина"
                    elseif d.reason then hint = "причина" end
                    local hw = 0
                    if type(ctx.drawnW) == "function" then
                        local ok, v = pcall(ctx.drawnW, hint, 0.78)
                        if ok and type(v) == "number" then hw = v end
                    end
                    ctx.uiText(ddX + ddW - 12 - hw, ry + (PUN_ROW_H - lineH(ctx, 0.78)) / 2, hint,
                        ctx.col32(150, 145, 172, 255), 0.78)
                    if clicked then
                        bufWrite("punCmd", d.id)
                        P.comboOpen = false
                    end
                end
            end
            if clipDD and ctx.dl.PopClipRect then pcall(ctx.dl.PopClipRect, ctx.dl) end
            if maxScroll > 0.5 then
                ctx.roundRect(ctx.dl, ctx.at(ddX + ddW - 4, ddY + 2), ctx.at(ddX + ddW - 2, ddY + viewH - 2),
                    ctx.col32(255, 255, 255, 18), 2)
                local barH = math.max(14, (viewH - 4) * viewH / (#QR.punCmds * step - 2))
                local barY = ddY + 2 + (scroll / maxScroll) * (viewH - 4 - barH)
                ctx.roundRect(ctx.dl, ctx.at(ddX + ddW - 4, barY), ctx.at(ddX + ddW - 2, barY + barH),
                    ctx.col32(ac[1], ac[2], ac[3], 200), 2)
            end
            local winP = im.GetWindowPos()
            if punOutsideClick((winP and winP.x or 0) + ddX, (winP and winP.y or 0) + ddY, ddW, viewH,
                    (winP and winP.x or 0) + ix, (winP and winP.y or 0) + selY, PUN_SEL_H) then
                P.comboOpen = false
            end
        else
            yy = selY + PUN_SEL_H + 8
            if def and def.time then
                ctx.uiText(ix, yy, "Время, " .. tostring(def.unit or ""), dim, 0.82)
                yy = yy + 17
                field(ctx, "##grnd_qr_pun_time", "punTime", 16,
                    ix, yy, math.min(160, iw), 28, "Только число", false, it and it.time or "")
                yy = yy + 36
            end
            if def and def.reason then
                ctx.uiText(ix, yy, "Причина", dim, 0.82)
                yy = yy + 17
                field(ctx, "##grnd_qr_pun_reason", "punReason", 256,
                    ix, yy, iw, 28, "Например: флуд в чате", false, it and it.reason or "")
                yy = yy + 36
            end
        end
        local bw1 = math.min(146, math.floor(iw * 0.4))
        if button(ctx, "##grnd_qr_pun_save", ix, by, bw1, btnH, "Сохранить", { primary = true }) then
            local name = trim(bufText("punName"))
            local text = cleanText(bufText("punText"))
            local cmd = trim(bufText("punCmd")):lower()
            local tdef = QR.punDef(cmd)
            local time = (trim(bufText("punTime")):gsub("%D", ""))
            local reason = oneLine(bufText("punReason"))
            if not tdef then
                QR.toast("Выберите команду наказания", "warn", 2.8)
            elseif tdef.time and time == "" then
                QR.toast("Введите время наказания (только число)", "warn", 2.8)
            elseif tdef.reason and reason == "" then
                QR.toast("Введите причину наказания", "warn", 2.8)
            else
                if P.isNew then
                    local created = QR.punAdd(name, text, cmd, time, reason)
                    P.isNew = false
                    P.selId = created and created.id or nil
                else
                    QR.punUpdate(P.selId, name, text, cmd, time, reason)
                end
                P.formKey, P.cmdSync = nil, nil
                punFormSync()
                bufReload("punName")
                bufReload("punText")
                bufReload("punTime")
                bufReload("punReason")
                pcall(QR.punSave)
                QR.toast("Наказание сохранено", "ok", 2.2)
            end
        end
        local bx = ix + bw1 + 8
        local bw2 = math.min(112, math.floor(iw * 0.28))
        if button(ctx, "##grnd_qr_pun_cancel", bx, by, bw2, btnH, "Отмена", {}) then
            P.isNew, P.delArm, P.formKey, P.cmdSync = false, nil, nil, nil
            P.comboOpen = false
            punFormSync()
            QR.toast("Изменения отменены", "ok", 2.0)
        end
        if not P.isNew and it then
            local bx2 = bx + bw2 + 8
            local bw3 = iw - (bx2 - ix)
            if bw3 >= 90 then
                local label = (P.delArm == it.id) and "Точно удалить?" or "Удалить"
                if button(ctx, "##grnd_qr_pun_remove", bx2, by, bw3, btnH, label, { danger = true }) then
                    if P.delArm == it.id then
                        QR.punRemove(it.id)
                        P.delArm, P.formKey, P.cmdSync = nil, nil, nil
                        punFormSync()
                        pcall(QR.punSave)
                        QR.toast("Наказание удалено", "ok", 2.2)
                    else
                        P.delArm = it.id
                    end
                end
            end
        end
    end
    local function punSettingsDraw(ctx)
        if type(ctx) ~= "table" then return false end
        local im = ctx.im
        if not (im and ctx.uiText and ctx.roundRect and ctx.col32 and ctx.rgba and ctx.at) then
            return false
        end
        local TH = theme()
        QR.punEnsure()
        local P = QR.pun
        local x, y, w, h = ctx.x, ctx.y, ctx.w, ctx.h
        if not (x and y and w and h) or w < 240 or h < 140 then return false end
        ctx.uiText(x, y + 1, "Шаблоны наказаний",
            ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255), 1.0)
        local tw = 220
        if type(ctx.drawnW) == "function" then
            local ok, v = pcall(ctx.drawnW, "Шаблоны наказаний", 1.0)
            if ok and type(v) == "number" then tw = v end
        end
        chip(ctx, x + tw + 10, y - 2, "шаблонов: " .. tostring(QR.punCount()))
        local newW = 148
        local searchW = math.min(190, math.max(118, math.floor(w * 0.24)))
        local searchX = x + w - newW - searchW - 10
        if searchX > x + tw + 110 then
            field(ctx, "##grnd_qr_pun_search", "punSearch", 64,
                searchX, y - 3, searchW, 28, "Поиск…", false, P.filter)
            P.filter = bufText("punSearch")
        end
        if button(ctx, "##grnd_qr_pun_new", x + w - newW, y - 4, newW, 30, "+ Новый шаблон",
            { primary = P.isNew }) then
            P.isNew, P.selId, P.delArm = true, nil, nil
            P.formKey, P.cmdSync, P.comboOpen = nil, nil, false
            punFormSync()
            QR.toast("Выберите команду наказания и заполните поля", "ok", 2.6)
        end
        local yy = y + 34
        local gap = 14
        local listW = math.floor((w - gap) * 0.36)
        if listW < 200 then listW = 200 end
        if listW > 300 then listW = 300 end
        local contentH = (y + h) - yy
        if contentH < 120 then contentH = 120 end
        punListDraw(ctx, x, yy, listW, contentH)
        punEditorDraw(ctx, x + listW + gap, yy, w - listW - gap, contentH)
        return true
    end
    _G.grndQrPunishDraw = function(ctx)
        local ok, res = pcall(punSettingsDraw, ctx)
        if ok then return res end
        QR.punDrawErr = tostring(res)
        print("{FF6666}[GRND]{FFFFFF} шаблоны наказаний: " .. tostring(res))
        return false
    end
end
do
    local MAX_ATRIG = 2048
    local TRIG_CAP = MAX_ATRIG * 2 + 1
    local MAX_TABS = 15
    local AUTO_GAP = 0.5
    local AUTO_CMDS = {
        { id = "sp",   label = "/sp",         hint = "слежка за игроком" },
        { id = "goto", label = "/goto",       hint = "телепорт к игроку" },
        { id = "none", label = "Без команды", hint = "только ответ" },
    }
    QR.autoCmds = AUTO_CMDS
    local AUTO_LOW = {
        ["А"]="а",["Б"]="б",["В"]="в",["Г"]="г",["Д"]="д",["Е"]="е",["Ё"]="ё",["Ж"]="ж",
        ["З"]="з",["И"]="и",["Й"]="й",["К"]="к",["Л"]="л",["М"]="м",["Н"]="н",["О"]="о",
        ["П"]="п",["Р"]="р",["С"]="с",["Т"]="т",["У"]="у",["Ф"]="ф",["Х"]="х",["Ц"]="ц",
        ["Ч"]="ч",["Ш"]="ш",["Щ"]="щ",["Ъ"]="ъ",["Ы"]="ы",["Ь"]="ь",["Э"]="э",["Ю"]="ю",
        ["Я"]="я",
    }
    local function autoLower(str)
        str = tostring(str or ""):lower()
        if str == "" then return str end
        local out = {}
        for ch in str:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
            out[#out + 1] = AUTO_LOW[ch] or ch
        end
        return table.concat(out)
    end
    local function autoPlain(str)
        str = tostring(str or "")
        str = str:gsub("{%x%x%x%x%x%x%x%x}", ""):gsub("{%x%x%x%x%x%x}", "")
        str = str:gsub("%[К%-во репорта:%s*%d+%]", " ")
        str = str:gsub("[%c]", " ")
        return trim(str:gsub("%s+", " "))
    end
    function QR.repCountOf(msg)
        local pat = "%[[^%]]*[Рр]епорта%s*:%s*(%d*)%s*%]"
        local low = autoLower(tostring(msg or ""))
        local n = low:match(pat)
        if n == nil then return nil end
        return tonumber(n) or 1
    end
    function QR.autoPath()
        local base = tostring(QR.path() or "")
        local replaced = base:gsub("grnd_repquick%.cfg$", "grnd_repauto.cfg")
        if replaced ~= base then return replaced end
        local dir = base:match("^(.*[/\\])")
        if dir then return dir .. "grnd_repauto.cfg" end
        return "grnd_repauto.cfg"
    end
    function QR.autoCmdId(v)
        v = tostring(v or ""):lower():gsub("[^%a]", "")
        if v == "goto" or v == "none" then return v end
        return "sp"
    end
    function QR.autoCmdLabel(id)
        id = QR.autoCmdId(id)
        for i = 1, #AUTO_CMDS do
            if AUTO_CMDS[i].id == id then return AUTO_CMDS[i].label end
        end
        return "/sp"
    end
    function QR.autoNewTab()
        return { trigger = "", answer = "", command = "sp" }
    end
    function QR.autoTabs()
        local A = QR.auto
        if type(A.tabs) ~= "table" then A.tabs = {} end
        local out = {}
        for i = 1, #A.tabs do
            local t = A.tabs[i]
            if type(t) == "table" then out[#out + 1] = t end
        end
        if #out == 0 then out[1] = QR.autoNewTab() end
        while #out > MAX_TABS do table.remove(out) end
        A.tabs = out
        A.sel = math.max(1, math.min(#out, math.floor(tonumber(A.sel) or 1)))
        return out
    end
    function QR.autoTab(i)
        local tabs = QR.autoTabs()
        i = math.floor(tonumber(i) or QR.auto.sel or 1)
        if i < 1 then i = 1 end
        if i > #tabs then i = #tabs end
        return tabs[i], i
    end
    function QR.autoLabel(i)
        local t = QR.auto.tabs and QR.auto.tabs[i]
        local trg = t and tostring(t.trigger or "") or ""
        if trim(trg) ~= "" then return trim(trg) end
        return "Вкладка " .. tostring(i)
    end
    function QR.autoAdd()
        local tabs = QR.autoTabs()
        if #tabs >= MAX_TABS then
            QR.toast("Больше " .. tostring(MAX_TABS) .. " вкладок не нужно", "warn", 2.6)
            return nil
        end
        tabs[#tabs + 1] = QR.autoNewTab()
        QR.auto.sel = #tabs
        QR.auto.listOpen = false
        pcall(QR.autoSave)
        return QR.auto.sel
    end
    function QR.autoDel(i)
        local tabs = QR.autoTabs()
        i = math.floor(tonumber(i) or QR.auto.sel or 1)
        if i < 1 or i > #tabs then return false end
        if #tabs <= 1 then
            tabs[1] = QR.autoNewTab()
            QR.auto.sel = 1
        else
            table.remove(tabs, i)
            if QR.auto.sel > #tabs then QR.auto.sel = #tabs end
        end
        QR.auto.listOpen = false
        if type(QR.bufs) == "table" then
            for k in pairs(QR.bufs) do
                if tostring(k):find("^auto") then QR.bufs[k] = nil end
            end
        end
        pcall(QR.autoSave)
        return true
    end
    function QR.autoTrigList(tab)
        tab = tab or QR.autoTab()
        local raw = tostring(tab and tab.trigger or "")
        local out = {}
        for piece in (raw .. ","):gmatch("([^,;\n]*)[,;\n]") do
            local wide = piece:find("%b{}") ~= nil
            local lowPiece = autoLower(piece)
            local pun = lowPiece:find("{punishments}", 1, true) ~= nil
            local idv = lowPiece:find("{id}", 1, true) ~= nil
            local w = trim(autoLower(autoPlain((piece:gsub("%b{}", " ")))))
            if w ~= "" then
                out[#out + 1] = { word = w, wide = wide, pun = pun, idv = idv }
            end
        end
        return out
    end
    function QR.autoPlainWords(tab)
        local list, n = QR.autoTrigList(tab), 0
        for i = 1, #list do
            if not list[i].pun and not list[i].idv then n = n + 1 end
        end
        return n
    end
    function QR.autoTriggers(tab)
        local list, out = QR.autoTrigList(tab), {}
        for i = 1, #list do out[i] = list[i].word end
        return out
    end
    local function autoWordStart(rest)
        if rest == "" then return false end
        local b = rest:byte(1)
        if b == nil then return false end
        if b < 0x80 then return rest:sub(1, 1):match("[%w_]") ~= nil end
        return b == 0xD0 or b == 0xD1
    end
    local function autoLastChar(t)
        return tostring(t or ""):match("([%z\1-\127\194-\244][\128-\191]*)$") or ""
    end
    local function autoWordAt(low, trig)
        if trig == "" then return nil end
        local from = 1
        while true do
            local s1, s2 = low:find(trig, from, true)
            if not s1 then return nil end
            local before = autoLastChar(low:sub(1, s1 - 1))
            if not autoWordStart(before) and not autoWordStart(low:sub(s2 + 1)) then
                return s1
            end
            from = s1 + 1
        end
    end
    local function autoWordHit(low, trig)
        return autoWordAt(low, trig) ~= nil
    end
    local function autoChunks(line)
        line = tostring(line or "")
        if #line <= 100 then return { line } end
        if type(QR.punChunks) == "function" then
            local ok, out = pcall(QR.punChunks, line, 100)
            if ok and type(out) == "table" and #out > 0 then return out end
        end
        return { line }
    end
    function QR.autoFindReportId(text)
        text = tostring(text or "")
        local init = 1
        while true do
            local s1, s2 = text:find("%d+", init)
            if not s1 then return nil end
            local num = text:sub(s1, s2)
            if #num <= 5 and not autoWordStart(autoLastChar(text:sub(1, s1 - 1)))
                and not autoWordStart(text:sub(s2 + 1)) then
                return num
            end
            init = s2 + 1
        end
    end
    function QR.autoNickById(id)
        local num = tonumber(id)
        if not num or num < 0 or num > 1003 then return nil end
        if type(_G.sampGetPlayerNickname) ~= "function" then return nil end
        local ok, n = pcall(_G.sampGetPlayerNickname, num)
        if ok and type(n) == "string" and n ~= "" then return n, num end
        return nil
    end
    function QR.autoNickInText(text)
        text = tostring(text or "")
        if text == "" then return nil end
        if type(_G.sampIsPlayerConnected) ~= "function"
            or type(_G.sampGetPlayerNickname) ~= "function" then return nil end
        local maxid = 1003
        if type(_G.sampGetMaxPlayerId) == "function" then
            local ok, n = pcall(_G.sampGetMaxPlayerId)
            if ok and tonumber(n) then
                maxid = math.max(0, math.min(1003, math.floor(tonumber(n))))
            end
        end
        local players = {}
        for id = 0, maxid do
            local okC, on = pcall(_G.sampIsPlayerConnected, id)
            if okC and on then
                local okN, nick = pcall(_G.sampGetPlayerNickname, id)
                if okN and type(nick) == "string" and nick ~= "" then
                    players[autoLower(nick)] = { nick = nick, id = id }
                end
            end
        end
        local low = autoLower(text)
        for w in low:gmatch("[%w_%.%-]+") do
            if #w >= 3 and #w <= 24 and w:find("%a") then
                local hit = players[w]
                if hit then return hit.nick, hit.id end
            end
        end
        return nil
    end
    function QR.autoTargetOf(text, foundId)
        local n, id = QR.autoNickById(foundId)
        if n then return n, id end
        return QR.autoNickInText(text)
    end
    function QR.autoVarFlags(tab)
        local low = autoLower(tostring((tab and tab.trigger) or "")) .. " "
            .. autoLower(tostring((tab and tab.answer) or ""))
        return low:find("{id}", 1, true) ~= nil, low:find("{all}", 1, true) ~= nil,
            low:find("{punishments}", 1, true) ~= nil
    end
    function QR.autoMatchAll(text)
        local low = trim(autoLower(autoPlain(text)))
        local out = {}
        if low == "" then return out, "" end
        local tabs = QR.autoTabs()
        local found, best, dropped = {}, nil, {}
        for i = 1, #tabs do
            local list = QR.autoTrigList(tabs[i])
            local mine = nil
            for k = 1, #list do
                local it = list[k]
                local pos
                if it.wide then
                    pos = autoWordAt(low, it.word)
                elseif low == it.word then
                    pos = 1
                end
                if pos and (not mine or pos < mine.pos) then
                    mine = { pos = pos, word = it.word, pun = it.pun, idv = it.idv }
                end
            end
            if mine then
                found[#found + 1] = { idx = i, trig = mine.word, pos = mine.pos,
                    pun = mine.pun, idv = mine.idv }
                if not best or mine.pos < best then best = mine.pos end
            end
        end
        if #found > 0 then
            for k = 1, #found do
                if found[k].pos == best then
                    out[#out + 1] = { idx = found[k].idx, trig = found[k].trig,
                        pun = found[k].pun, idv = found[k].idv }
                elseif not dropped[found[k].trig] then
                    dropped[found[k].trig] = true
                end
            end
            local names = {}
            for w in pairs(dropped) do names[#names + 1] = w end
            return out, table.concat(names, ", ")
        end
        for i = 1, #tabs do
            if QR.autoBarePun(tabs[i]) then
                out[#out + 1] = { idx = i, trig = QR.autoTrigLabel(tabs[i]), pun = true }
            end
        end
        return out, ""
    end
    function QR.autoMatchTab(text)
        local hits = QR.autoMatchAll(text)
        if #hits == 0 then return nil end
        return hits[1].idx, hits[1].trig
    end
    function QR.autoReady()
        local tabs, ready = QR.autoTabs(), 0
        for i = 1, #tabs do
            local tab = tabs[i]
            local hasWord = #QR.autoTriggers(tab) > 0
            local hasAns = trim(tostring(tab.answer or "")) ~= ""
                or QR.autoPunInTrigger(tab) or QR.autoIDInTrigger(tab)
            if (hasWord or QR.autoBarePun(tab)) and hasAns then ready = ready + 1 end
        end
        return ready, #tabs
    end
    function QR.autoCmdFor(pid, tab)
        pid = tostring(pid or "")
        if pid:match("^%d+$") == nil then return nil end
        tab = tab or QR.autoTab()
        local id = QR.autoCmdId(tab and tab.command)
        if id == "none" then return nil end
        return "/" .. id .. " " .. pid
    end
    function QR.autoBarePun(tab)
        local raw = autoLower(tostring((tab and tab.trigger) or ""))
        if raw:find("{punishments}", 1, true) == nil then return false end
        return trim((raw:gsub("%b{}", " ")):gsub("[,;]", " ")) == ""
    end
    function QR.autoVarsOnly(tab)
        return #QR.autoTriggers(tab) == 0 and QR.autoBarePun(tab)
    end
    function QR.autoPunInTrigger(tab)
        local raw = autoLower(tostring((tab and tab.trigger) or ""))
        return raw:find("{punishments}", 1, true) ~= nil
    end
    QR.AUTO_GREET = "Приветствую, слежу за игроком {ник}[{ID}]"
    function QR.autoIDInTrigger(tab)
        local raw = autoLower(tostring((tab and tab.trigger) or ""))
        return raw:find("{id}", 1, true) ~= nil
    end
    function QR.autoGreet(rep)
        rep = (type(rep) == "table") and rep or {}
        local nick = tostring(rep.nick or "")
        local id = tostring(rep.foundId or "")
        if id == "" then id = tostring(rep.id or "") end
        if nick == "" and id == "" then return "" end
        local who = nick
        if nick ~= "" and id ~= "" then who = nick .. "[" .. id .. "]"
        elseif nick == "" then who = "[" .. id .. "]" end
        return "Приветствую, слежу за игроком " .. who
    end
    function QR.autoWhoStrip(line)
        line = tostring(line or "")
        line = line:gsub("{ник}", ""):gsub("{nick}", "")
        line = line:gsub("{ид}", ""):gsub("{id}", ""):gsub("{ID}", "")
        line = line:gsub("%[%s*%]", "")
        line = line:gsub("%s+", " ")
        line = line:gsub("%s+([,%.!%?:;])", "%1")
        line = line:gsub(",%s*([%.!%?:;])", "%1")
        return trim(line)
    end
    function QR.autoTrigLabel(tab)
        local low = autoLower(tostring((tab and tab.trigger) or ""))
        local v = low:match("{(%a+)}")
        if v == "punishments" then return "наказания" end
        if v == "id" then return "ID из репорта" end
        return "любой репорт"
    end
    function QR.autoAnsCmd(pid, text)
        pid = tostring(pid or "")
        local R = _G.GRND_REP
        local rc = R and R.replyCmd
        if type(rc) == "string" and rc ~= "" and tostring(R.replyPid or "") == pid then
            return (rc:gsub("%d+", pid)) .. " " .. tostring(text)
        end
        return "/ans " .. pid .. " " .. tostring(text)
    end
    function QR.answerCmd(pid, text)
        return QR.autoAnsCmd(pid, text)
    end
    function QR.autoTabCmd(pid, tab, foundId)
        local hasID = QR.autoVarFlags(tab)
        if hasID and tostring(foundId or "") ~= "" then
            return "/sp " .. tostring(foundId)
        end
        return QR.autoCmdFor(pid, tab)
    end
    function QR.autoNormalize()
        local A = QR.auto
        if type(A) ~= "table" then A = {} QR.auto = A end
        A.on = A.on and true or false
        A.fired = math.max(0, math.floor(tonumber(A.fired) or 0))
        local tabs = QR.autoTabs()
        for i = 1, #tabs do
            local t = tabs[i]
            t.trigger = clampText(oneLine(utf(t.trigger or "")), MAX_ATRIG)
            t.answer = clampText(cleanText(utf(t.answer or "")), MAX_TEXT)
            t.command = QR.autoCmdId(t.command)
        end
        return A
    end
    function QR.autoLoad()
        local A = QR.auto
        if A.loaded then return true end
        A.loaded = true
        local on, sel, legacy = nil, nil, nil
        local tabs = {}
        local ok, f = pcall(GRND_CONFIG.open, QR.autoPath(), "r")
        if ok and f then
            for line in f:lines() do
                local k, v = tostring(line or ""):match("^([%w_]+)=(.*)$")
                local idx, field = tostring(k or ""):match("^t(%d+)_(%a+)$")
                if v ~= nil then v = tostring(v) end
                if idx then
                    local n = tonumber(idx)
                    if n and n >= 1 and n <= MAX_TABS then
                        tabs[n] = tabs[n] or QR.autoNewTab()
                        if field == "trigger" then tabs[n].trigger = unesc(v)
                        elseif field == "answer" then tabs[n].answer = unesc(v)
                        elseif field == "command" then tabs[n].command = v end
                    end
                elseif k == "on" then on = (v == "1" or v == "true")
                elseif k == "sel" then sel = tonumber(v)
                elseif k == "fired" then A.fired = tonumber(v)
                elseif k == "trigger" or k == "answer" or k == "command" then
                    legacy = legacy or QR.autoNewTab()
                    legacy[k] = unesc(v)
                end
            end
            pcall(f.close, f)
        end
        if #tabs == 0 and legacy then tabs[1] = legacy end
        if #tabs == 0 then tabs[1] = QR.autoNewTab() end
        A.tabs, A.sel = tabs, sel
        if on ~= nil then A.on = on end
        QR.autoNormalize()
        return true
    end
    function QR.autoEnsure()
        local A = QR.auto
        if type(A) ~= "table" then A = {} QR.auto = A end
        if not A.loaded then pcall(QR.autoLoad) end
        return QR.autoNormalize()
    end
    function QR.autoSave()
        local A = QR.autoNormalize()
        A.dirtyAt = nil
        local ok, f = pcall(GRND_CONFIG.open, QR.autoPath(), "w")
        if not ok or not f then return false end
        f:write("on=" .. (A.on and "1" or "0") .. "\n")
        f:write("sel=" .. tostring(A.sel or 1) .. "\n")
        for i = 1, #A.tabs do
            local t = A.tabs[i]
            f:write("t" .. i .. "_trigger=" .. esc(t.trigger or "") .. "\n")
            f:write("t" .. i .. "_answer=" .. esc(t.answer or "") .. "\n")
            f:write("t" .. i .. "_command=" .. tostring(t.command or "sp") .. "\n")
        end
        pcall(f.close, f)
        if GRND_CONFIG and type(GRND_CONFIG.flush) == "function" then
            pcall(GRND_CONFIG.flush)
        end
        return true
    end
    QR.punReq = QR.punReq or { on = false, at = 0, pid = nil, nick = "", mode = "manual" }
    QR.punLog = function(msg)
        pcall(print, "[GRND] наказания: " .. tostring(msg))
    end
    QR.punCancel = function()
        local P = QR.punReq
        P.on, P.at, P.pid, P.nick, P.mode = false, 0, nil, "", nil
        P.seenTitle, P.seenText = nil, nil
    end
    QR.punBegin = function(pid, nick, mode)
        local P = QR.punReq
        if P.on then return false end
        local pidS = tostring(pid or "")
        if pidS:match("^%d+$") == nil then return false end
        P.on, P.at, P.pid, P.nick = true, os.clock(), pidS, tostring(nick or "")
        P.mode = (mode == "auto") and "auto" or "manual"
        P.seenTitle, P.seenText = nil, nil
        return true
    end
    QR.punBeginManual = function(pid, nick)
        if not QR.punBegin(pid, nick, "manual") then
            QR.toast("Наказания: уже ждём окно другого игрока", "warn", 3)
            return false
        end
        if type(sampSendChat) == "function" then
            pcall(sampSendChat, "/getinfo " .. tostring(pid))
        else
            grndRepQueue("/getinfo " .. tostring(pid))
        end
        return true
    end
    QR.punNorm = function(str)
        local t = grndToUtf(tostring(str or ""))
        t = t:gsub("{%x%x%x%x%x%x}", "")
        return t
    end
    QR.punFind = function(str, needle)
        local t = QR.punNorm(str)
        if type(_G.grndLowerUtf) == "function" then
            local ok, low = pcall(_G.grndLowerUtf, t)
            if ok and type(low) == "string" then t = low end
        else
            t = t:lower()
        end
        return t:find(needle, 1, true) ~= nil
    end
    QR.punLooksDialog = function(caption, text)
        if QR.punFind(caption, "наказани") then return true end
        if QR.punFind(caption, "наказан") then return true end
        return QR.punFind(text, "ккаунт")
    end
    QR.punParse = function(raw)
        local t = grndToUtf(tostring(raw or ""))
        t = t:gsub("{%x%x%x%x%x%x}", "")
        local out, head = {}, false
        for ln in (t .. "\n"):gmatch("([^\n]*)\n") do
            ln = ln:gsub("^%s+", ""):gsub("%s+$", "")
            if ln ~= "" then
                if not head then
                    head = true
                    if not ln:find("ккаунт", 1, true) then
                        out[#out + 1] = ln
                    end
                else
                    out[#out + 1] = ln
                end
            end
        end
        return out
    end
    QR.punChunks = function(text, limit)
        limit = tonumber(limit) or 100
        local str = tostring(text or "")
        str = str:gsub("%s*\n%s*", " | ")
        str = str:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
        local out = {}
        local function charCut(v, n)
            local i, k = 1, 0
            while i <= #v and k < n do
                local b = v:byte(i)
                local step = (b >= 240 and 4) or (b >= 224 and 3) or (b >= 192 and 2) or 1
                i = i + step
                k = k + 1
            end
            return i - 1
        end
        while str ~= "" do
            local cut = charCut(str, limit)
            if cut >= #str then
                out[#out + 1] = str
                break
            end
            local head = str:sub(1, cut)
            local lastSp
            for p in head:gmatch("()%s") do lastSp = p end
            if lastSp and lastSp > #head * 0.5 then
                out[#out + 1] = str:sub(1, lastSp - 1)
                str = str:sub(lastSp + 1)
            else
                out[#out + 1] = head
                str = str:sub(cut + 1)
            end
            str = str:gsub("^%s+", "")
        end
        return out
    end
    QR.punSay = function(pid, text)
        local chunks = QR.punChunks(text, 100)
        local pidS = tostring(pid or "")
        local pidOk = pidS:match("^%d+$") ~= nil
        local q = GRND_REP.queue
        local canJump = pidOk
            and (type(sampSendChat) == "function")
            and (type(q) ~= "table" or #q == 0)
            and ((os.clock() or 0) - (GRND_REP.queueAt or 0) >= 0.35)
        for i, c in ipairs(chunks) do
            if i == 1 and canJump then
                pcall(sampSendChat, "/ans " .. pidS .. " " .. grndRepToAnsi(c))
                pcall(grndRepHudRemove, pidS)
                GRND_REP.queueAt = os.clock()
                canJump = false
            else
                grndRepAnswer(pid, c)
            end
        end
        return #chunks
    end
    QR.punFinish = function(raw)
        local P = QR.punReq
        if not P.on then return end
        local mode, pid, nick = P.mode, P.pid, P.nick
        local seen = P.seenTitle and ("последний диалог: " .. tostring(P.seenTitle)
            .. " | " .. tostring(P.seenText or ""):gsub("%s+", " ")) or "диалогов не было"
        local who = tostring(nick or ("ID " .. tostring(pid)))
        QR.punCancel()
        local lines = (type(raw) == "string") and QR.punParse(raw) or nil
        if mode == "auto" then
            pcall(QR.autoPunAbsorb, lines)
            if not lines then QR.punLog(who .. ": окно /getinfo не распознано. " .. seen) end
            return
        end
        if not lines then
            QR.punLog("окно /getinfo не распознано. " .. seen)
        elseif #lines == 0 then
            QR.punSay(pid, "Приветствую, активных наказаний у вас нет.")
            QR.punLog(who .. ": активных наказаний нет")
        else
            QR.punSay(pid,
                "Приветствую, ваши активные наказания >> " .. table.concat(lines, " | "))
            QR.punLog(who .. ": строк наказаний " .. tostring(#lines))
        end
    end
    _G.grndQrPunOnDialog = function(dialogId, style, title, b1, b2, text)
        local P = QR.punReq
        if not P.on then return nil end
        local age = (os.clock() or 0) - (P.at or 0)
        if age > 8 then return nil end
        local body = (type(text) == "string" and text) or ""
        if body == "" then
            for _, v in ipairs({ b1, b2 }) do
                if type(v) == "string" and #v > #body then body = v end
            end
        end
        local looks = QR.punLooksDialog(title, body)
        if not looks and age <= 3.0 and #body >= 5 then
            local lowB = QR.punNorm(body)
            if type(_G.grndLowerUtf) == "function" then
                local okL, l = pcall(_G.grndLowerUtf, lowB)
                if okL and type(l) == "string" then lowB = l end
            else
                lowB = lowB:lower()
            end
            local relB = false
            if P.pid and lowB:find(tostring(P.pid), 1, true) then relB = true end
            if P.nick and P.nick ~= "" then
                local nk = P.nick
                if type(_G.grndLowerUtf) == "function" then
                    local okN, l = pcall(_G.grndLowerUtf, nk)
                    if okN and type(l) == "string" then nk = l end
                else
                    nk = nk:lower()
                end
                if lowB:find(nk, 1, true) then relB = true end
            end
            if not relB then return nil end
            local foreign = false
            if type(_G.grndRepAcceptDialog) == "function" then
                local okR, r = pcall(_G.grndRepAcceptDialog, dialogId, title, body)
                if okR and r then foreign = true end
            end
            if not foreign and type(_G.grndStatsShouldHide) == "function" then
                local okS, r = pcall(_G.grndStatsShouldHide, title, body)
                if okS and r then foreign = true end
            end
            if not foreign then looks = true end
        end
        if not looks then
            P.seenTitle, P.seenText = tostring(title or ""), tostring(body or ""):sub(1, 300)
            return nil
        end
        pcall(QR.punFinish, body)
        return true
    end
    QR.punPoll = function()
        local P = QR.punReq
        if not P.on then return end
        local now = os.clock() or 0
        local age = now - (P.at or 0)
        local limit = (P.mode == "auto") and 5 or 8
        if age > limit then
            pcall(QR.punFinish)
            return
        end
        if age < 0.1 then return end
        if type(grndSessionReady) == "function" and not grndSessionReady() then return end
        if type(sampIsDialogActive) ~= "function" then return end
        local okA, active = pcall(sampIsDialogActive)
        if not (okA and active) then return end
        local caption, text = "", ""
        if type(sampGetDialogCaption) == "function" then
            local ok, v = pcall(sampGetDialogCaption)
            if ok and type(v) == "string" then caption = v end
        end
        if type(sampGetDialogText) == "function" then
            local ok, v = pcall(sampGetDialogText)
            if ok and type(v) == "string" then text = v end
        end
        if not QR.punLooksDialog(caption, text) then return end
        local dlgId = nil
        if type(sampGetCurrentDialogId) == "function" then
            local ok, v = pcall(sampGetCurrentDialogId)
            if ok then dlgId = tonumber(v) end
        end
        pcall(QR.punFinish, text)
        if dlgId then
            if type(sampSendDialogResponse) == "function" then
                pcall(sampSendDialogResponse, dlgId, 1, -1, "")
            elseif type(sampCloseCurrentDialogWithButton) == "function" then
                pcall(sampCloseCurrentDialogWithButton, 1)
            end
        end
    end
    QR.autoPunText = function(lines)
        if type(lines) ~= "table" or #lines == 0 then return "нет активных наказаний" end
        return table.concat(lines, " | ")
    end
    QR.autoPunWrap = function(txt)
        local str = tostring(txt or "")
        if str == "" or str == "нет активных наказаний" then
            return "Приветствую, активных наказаний у вас нет."
        end
        return "Приветствую, ваши активные наказания >> " .. str
    end
    QR.autoPunFill = function(line, txt)
        local str = tostring(line or "")
        if trim(str) == "{punishments}" then return QR.autoPunWrap(txt) end
        str = str:gsub("{punishments}", function() return tostring(txt or "") end)
        return oneLine(trim(str))
    end
    QR.autoPunAbsorb = function(lines)
        local A = QR.auto
        local P = A and A.pend
        if not (P and P.on) then return false end
        A.pend = nil
        local txt = lines and QR.autoPunText(lines) or "нет данных о наказаниях"
        local plan = P.plan or {}
        local wrote = false
        for k = 1, #plan do
            local it = plan[k]
            if it.pun then
                it.line = QR.autoPunFill(it.line, txt)
                wrote = true
            end
        end
        if not wrote then return false end
        pcall(QR.autoDeliver, P.id, P.hit, P.tabs, plan)
        if not lines then
            QR.toast("Автопилот: наказания не получены — ответ без списка", "warn", 3.2)
        end
        return true
    end
    function QR.autoSpectating()
        local P = _G.grndSpecProbeState
        if type(P) == "function" then
            local ok, st = pcall(P)
            if ok and st == true then return true end
            if ok and st == false then return false end
        end
        local S = _G.GRND_SPEC
        if type(S) == "table" and S.active and S.id then return true end
        local N = _G.grndSpecNative
        if type(N) == "table" and N.camOn then return true end
        if type(grndCamSpectating) == "function" then
            local ok, v = pcall(grndCamSpectating)
            if ok and v then return true end
        end
        return false
    end
    function QR.autoPauseReason()
        if QR.autoSpectating() then return "слежка" end
        local M = _G.GRND_MP
        if type(M) == "table" and M.active then return "мероприятие" end
        return nil
    end
    function QR.autoPauseTick()
        QR.autoEnsure()
        local A = QR.auto
        local reason = QR.autoPauseReason()
        if reason ~= A.paused then
            A.paused = reason
            if A.on then
                if reason == "слежка" then
                    QR.toast("Автопилот на паузе: слежка", "warn", 3.2)
                elseif reason == "мероприятие" then
                    QR.toast("Автопилот на паузе: идёт мероприятие", "warn", 3.2)
                else
                    QR.toast("Автопилот снова работает", "ok", 2.6)
                end
            end
        end
        return reason
    end
    function QR.autoSet(on)
        QR.autoEnsure()
        local A = QR.auto
        on = on and true or false
        if A.on == on then return A.on end
        A.on = on
        A.paused = on and QR.autoPauseReason() or nil
        pcall(QR.autoSave)
        if on then
            if A.paused == "слежка" then
                QR.toast("Автопилот включён · пауза: слежка", "ok", 2.8)
            elseif A.paused == "мероприятие" then
                QR.toast("Автопилот включён · пауза: мероприятие", "ok", 2.8)
            else
                QR.toast("Автопилот включён", "ok", 2.6)
            end
        else
            QR.toast("Автопилот выключен", "info", 2.4)
        end
        return A.on
    end
    function QR.autoGuard(now)
        local A = QR.auto
        now = tonumber(now) or os.clock()
        local W = A.pend
        if W and W.on then
            if now - (W.at or 0) > 12 then
                A.pend = nil
                pcall(QR.punCancel)
            else
                return "ждём ответ на /getinfo"
            end
        end
        if now - (A.lastAt or 0) < AUTO_GAP then return "слишком часто" end
        return nil
    end
    function QR.autoOnReport(nick, pid, msg)
        QR.autoEnsure()
        local A = QR.auto
        nick, pid = tostring(nick or ""), tostring(pid or "")
        local text = autoPlain(msg)
        A.lastReport = utf8Cut(tostring(nick) .. ": " .. text, 60)
        if not A.on then
            A.lastCheck = "выключен"
            return false, "выключен"
        end
        local pause = QR.autoPauseTick()
        local id = pid:match("^%d+$")
        if not id then
            A.lastCheck = "в репорте нет ID игрока"
            return false, "нет ID"
        end
        if text == "" then
            A.lastCheck = "пустой текст репорта"
            return false, "пусто"
        end
        local hits, droppedTrig = QR.autoMatchAll(text)
        A.lastDropped = droppedTrig or ""
        if #hits == 0 then
            if pause then
                A.lastCheck = "пауза: " .. pause
                return false, pause
            end
            A.lastCheck = "триггер не найден в «" .. utf8Cut(text, 40) .. "»"
            return false, "нет триггера"
        end
        local foundId = QR.autoFindReportId(text)
        local tNick, tId = QR.autoTargetOf(text, foundId)
        if tId and not foundId then foundId = tId end
        if pause then
            if pause == "слежка" then
                local keep = {}
                for k = 1, #hits do
                    local tab = QR.autoTab(hits[k].idx)
                    local wouldCmd = (not hits[k].pun) and QR.autoTabCmd(id, tab, foundId)
                    if not wouldCmd then
                        keep[#keep + 1] = hits[k]
                    end
                end
                if #keep == 0 then
                    A.lastCheck = "пауза: слежка"
                    return false, "слежка"
                end
                hits = keep
            else
                A.lastCheck = "пауза: " .. pause
                return false, pause
            end
        end
        local hit = hits[1].trig
        local hitTabs = {}
        for k = 1, #hits do hitTabs[k] = tostring(hits[k].idx) end
        local hitTabsTxt = table.concat(hitTabs, ", ")
        A.lastCheck = "триггер «" .. hit .. "» найден: вкладки " .. hitTabsTxt
            .. (droppedTrig ~= "" and (" · позже «" .. droppedTrig .. "» (пропущено)") or "")
        if type(grndIsTyping) == "function" then
            local okT, typing = pcall(grndIsTyping)
            if okT and typing then
                A.lastCheck = "идёт ввод текста — пропуск"
                QR.toast("Автопилот: пропуск — открыт чат или ввод", "warn", 2.8)
                return false, "ввод"
            end
        end
        local guard = QR.autoGuard(os.clock())
        if guard then
            A.lastCheck = "пропуск: " .. guard
            return false, guard
        end
        local hasTarget = (foundId ~= nil and foundId ~= "") or (tNick ~= nil and tNick ~= "")
        local rep = { nick = tNick or "", author = nick, id = id, foundId = foundId }
        local repNone = { nick = "", author = nick, id = "", foundId = "" }
        local repAns = hasTarget and rep or repNone
        local plan = {}
        for k = 1, #hits do
            local tab = QR.autoTab(hits[k].idx)
            local hasAll = select(2, QR.autoVarFlags(tab))
            local ansHasPun = autoLower(tostring(tab.answer or "")):find("{punishments}", 1, true) ~= nil
            local punOnly = hits[k].pun and true or false
            local idAuto = (not punOnly) and (hits[k].idv and true or false)
            local line, pun
            if punOnly then
                line = "{punishments}"
                pun = true
            elseif idAuto and hasTarget then
                line = QR.autoGreet(rep)
                pun = false
            elseif idAuto then
                line = QR.autoWhoStrip(oneLine(QR.apply(tab.answer, repNone)))
                pun = false
            else
                line = QR.autoWhoStrip(oneLine(QR.apply(tab.answer, repAns)))
                if hasAll then
                    line = trim((line:gsub("{all}", "", 1)))
                    line = trim((line:gsub("%s+", " ")))
                end
                pun = ansHasPun
            end
            local cmd = nil
            if not punOnly then cmd = QR.autoTabCmd(id, tab, foundId) end
            if line ~= "" or cmd then
                plan[#plan + 1] = { idx = hits[k].idx, line = line, cmd = cmd, pun = pun }
            end
        end
        if #plan == 0 then
            A.lastCheck = "вкладки " .. hitTabsTxt .. ": не заполнены ответ и команда"
            return false, "пусто"
        end
        local needPun = false
        for k = 1, #plan do
            if plan[k].pun then needPun = true end
        end
        if needPun then
            if QR.punBegin(id, nick, "auto") then
                A.pend = { on = true, at = os.clock(), id = id, hit = hit,
                    tabs = hitTabsTxt, plan = plan }
                A.lastCheck = "ждём окно /getinfo: «" .. hit .. "»"
                QR.queueCmd("/getinfo " .. id)
                QR.toast("Автопилот: читаю активные наказания игрока " .. id, "info", 2.6)
                return true, "наказания"
            end
            for k = 1, #plan do
                local it = plan[k]
                if it.pun then it.line = QR.autoPunFill(it.line, "нет данных о наказаниях") end
            end
            QR.toast("Автопилот: список наказаний уже запрашивается — ответ без него",
                "warn", 3.2)
        end
        return QR.autoDeliver(id, hit, hitTabsTxt, plan)
    end
    function QR.autoDeliver(id, hit, tabsTxt, plan)
        local A = QR.auto
        local sentAns, sentCmd, cmdTxt, planTabs = 0, 0, {}, {}
        for k = 1, #plan do
            local it = plan[k]
            if it.line ~= "" then
                local chunks = autoChunks(it.line)
                for ci = 1, #chunks do
                    local sent = false
                    if type(grndRepAnswer) == "function" then
                        local okA, res = pcall(grndRepAnswer, id, chunks[ci])
                        sent = okA and res ~= false
                    end
                    if not sent and QR.queueCmd(QR.autoAnsCmd(id, chunks[ci])) then
                        sent = true
                    end
                    if sent then sentAns = sentAns + 1 end
                end
            end
            if it.cmd then
                if QR.queueCmd(it.cmd) then sentCmd = sentCmd + 1 end
                cmdTxt[#cmdTxt + 1] = it.cmd
            end
            planTabs[#planTabs + 1] = tostring(it.idx)
        end
        local now = os.clock()
        A.lastAt = now
        A.fired = (A.fired or 0) + 1
        local planTabsTxt = table.concat(planTabs, ", ")
        local sentOk = (sentAns + sentCmd) > 0
        A.lastCheck = sentOk
            and ("отправлено (вкладки " .. planTabsTxt
                .. "), триггер «" .. tostring(hit) .. "»"
                .. (tabsTxt ~= planTabsTxt and (" · план " .. tostring(tabsTxt)) or "")
                .. (A.lastDropped ~= "" and (" · позже «" .. A.lastDropped .. "»") or ""))
            or "не удалось отправить"
        if sentOk then
            local cmds = table.concat(cmdTxt, " + ")
            QR.toast("Автопилот: /ans " .. id .. (cmds ~= "" and (" + " .. cmds) or "")
                    .. " · «" .. tostring(hit) .. "»"
                    .. (#plan > 1 and (" · вкладок " .. tostring(#plan)) or ""),
                "ok", 3.6)
        else
            QR.toast("Автопилот: отправить не удалось", "warn", 3)
        end
        return sentOk, hit
    end
    function QR.autoTick()
        QR.autoEnsure()
        local A = QR.auto
        local now = os.clock()
        if A.dirtyAt and (now - A.dirtyAt) > 0.6 then
            pcall(QR.autoSave)
        end
        if not A.on then
            A.paused = nil
            return false
        end
        local reason = QR.autoPauseTick()
        return reason ~= nil
    end
    local function autoMouseOver(im, x, y, w, h)
        local M = _G and _G.GRND_MOUSE
        if type(M) ~= "table" then return false end
        local mx, my = tonumber(M.x) or -1, tonumber(M.y) or -1
        local wp = nil
        if type(im.GetWindowPos) == "function" then
            local okP, p = pcall(im.GetWindowPos)
            if okP then wp = p end
        end
        local px, py = (wp and wp.x or 0), (wp and wp.y or 0)
        local sx, sy = px + x, py + y
        return mx >= sx and mx <= sx + w and my >= sy and my <= sy + h
    end
    local function autoOutsideClick(im, x, y, w, h)
        local alive = _G and _G.grndClickAlive
        if type(alive) ~= "function" then return false end
        local ok, hit = pcall(alive)
        if not (ok and hit) then return false end
        return not autoMouseOver(im, x, y, w, h)
    end
    local function circleFilled(c2, cx, cy, r, col)
        local dl2, at2 = c2.dl, c2.at
        if not (dl2 and at2) then return false end
        if dl2.AddCircleFilled and pcall(dl2.AddCircleFilled, dl2, at2(cx, cy), r, col) then
            return true
        end
        if dl2.AddCircle and pcall(dl2.AddCircle, dl2, at2(cx, cy), r, col, 16) then
            return true
        end
        if dl2.AddRectFilled then
            return pcall(dl2.AddRectFilled, dl2, at2(cx - r, cy - r), at2(cx + r, cy + r), col)
        end
        return false
    end
    local function autoSwitch(ctx, x, y, on, id)
        local im = ctx.im
        im.SetCursorPos(im.ImVec2(x, y))
        local clicked = im.InvisibleButton(id, im.ImVec2(46, 24)) and true or false
        local hov = (im.IsItemHovered and im.IsItemHovered()) or false
        local TH = theme()
        local ac = TH.accent or { 164, 112, 224, 255 }
        local paint = _G.grndUiSwitchPaint
        if type(paint) == "function" then
            pcall(paint, { dl = ctx.dl, at = ctx.at, col32 = ctx.col32,
                           roundRect = ctx.roundRect }, x, y, on, hov, id, 0.05)
        else
            ctx.roundRect(ctx.dl, ctx.at(x + 1, y + 7), ctx.at(x + 45, y + 17),
                ctx.col32(255, 255, 255, on and 40 or 16), 8)
            local kx = on and (x + 29) or (x + 17)
            ctx.roundRect(ctx.dl, ctx.at(kx - 8, y + 7), ctx.at(kx + 8, y + 17),
                ctx.col32(ac[1], ac[2], ac[3], on and 235 or 120), 8)
        end
        return clicked
    end
    _G.grndQrAutoDraw = function(ctx)
        if type(ctx) ~= "table" then return false end
        local im = ctx.im
        if not (im and ctx.uiText and ctx.roundRect and ctx.col32 and ctx.rgba and ctx.at) then
            return false
        end
        local TH = theme()
        QR.autoEnsure()
        local A = QR.auto
        local tabs = QR.autoTabs()
        local x, y, w, h = ctx.x, ctx.y, ctx.w, ctx.h
        if not (x and y and w and h) or w < 320 or h < 200 then return false end
        local bottomY = y + h - 6
        local hi  = ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255)
        local dim = ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255)
        local mut = ctx.col32(TH.textMuted[1], TH.textMuted[2], TH.textMuted[3], 255)
        local ac  = TH.accent or { 164, 112, 224, 255 }
        local acC = ctx.col32(ac[1], ac[2], ac[3], 255)
        local warnC = ctx.col32(255, 176, 96, 255)
        local okC   = ctx.col32(120, 220, 160, 255)
        local compact = h < 540
        ctx.uiText(x, y + 1, "Автопилот", hi, 1.0)
        local on = A.on and true or false
        local paused = on and (A.paused or QR.autoPauseReason()) or nil
        local stateTxt
        if paused == "слежка" then
            stateTxt = "на паузе — слежка, вернётся сам"
        elseif paused == "мероприятие" then
            stateTxt = "на паузе — идёт мероприятие, вернётся сам"
        elseif paused then
            stateTxt = "на паузе — " .. tostring(paused)
        end
        local tabsTop = y + 30
        if stateTxt then
            circleFilled(ctx, x + 8, y + 42, 5, warnC)
            ctx.uiText(x + 22, y + 32,
                fit(stateTxt, math.max(70, w - 84), ctx.drawnW, 0.95), warnC, 0.95)
            tabsTop = y + 62
        end
        if autoSwitch(ctx, x + w - 56, y + 3, on, "##grnd_qr_auto_on") then
            QR.autoSet(not on)
        end
        local function autoCross(cx, cy, r, col)
            if not ctx.dl.AddLine then return false end
            local a = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx - r, cy - r), ctx.at(cx + r, cy + r), col, 1.4)
            local b = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx + r, cy - r), ctx.at(cx - r, cy + r), col, 1.4)
            return a and b
        end
        local function autoPlus(cx, cy, r, col)
            if not ctx.dl.AddLine then return false end
            local a = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx - r, cy), ctx.at(cx + r, cy), col, 1.6)
            local b = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx, cy - r), ctx.at(cx, cy + r), col, 1.6)
            return a and b
        end
        local tabH, tgap, tcw = 30, 6, 26
        local tabW = math.floor((w - tgap * (#tabs - 1)) / #tabs)
        if tabW > 190 then tabW = 190 end
        if tabW < 96 then tabW = 96 end
        local tx, ty = x, tabsTop
        local pendingDel = nil
        for i = 1, #tabs do
            if tx + tabW > x + w + 0.5 then tx, ty = x, ty + tabH + tgap end
            local sel = (i == A.sel)
            im.SetCursorPos(im.ImVec2(tx, ty))
            local tabClick = im.InvisibleButton("##grnd_qr_auto_tab_" .. i,
                im.ImVec2(tabW - tcw, tabH)) and true or false
            local tabHov = (im.IsItemHovered and im.IsItemHovered()) or false
            im.SetCursorPos(im.ImVec2(tx + tabW - tcw, ty))
            local crossClick = im.InvisibleButton("##grnd_qr_auto_tabc_" .. i,
                im.ImVec2(tcw, tabH)) and true or false
            local crossHov = (im.IsItemHovered and im.IsItemHovered()) or false
            local hov = tabHov or crossHov
            ctx.roundRect(ctx.dl, ctx.at(tx, ty), ctx.at(tx + tabW, ty + tabH),
                sel and ctx.col32(ac[1], ac[2], ac[3], 52)
                    or (hov and ctx.col32(255, 255, 255, 22) or ctx.col32(255, 255, 255, 12)), 6)
            if ctx.dl.AddRect then
                pcall(ctx.dl.AddRect, ctx.dl, ctx.at(tx + 0.5, ty + 0.5),
                    ctx.at(tx + tabW - 0.5, ty + tabH - 0.5),
                    sel and ctx.col32(ac[1], ac[2], ac[3], 170) or ctx.col32(255, 255, 255, 46),
                    6, 0, 1)
            end
            local lbl = fit(QR.autoLabel(i), tabW - tcw - 12, ctx.drawnW, 0.88)
            local lw = 0
            if type(ctx.drawnW) == "function" then
                local okM, v = pcall(ctx.drawnW, lbl, 0.88)
                if okM and type(v) == "number" then lw = v end
            end
            ctx.uiText(tx + math.floor((tabW - tcw - lw) / 2), ty + (tabH - lineH(ctx, 0.88)) / 2,
                lbl, sel and hi or dim, 0.88)
            local crossCol = crossHov and ctx.col32(255, 140, 140, 255) or ctx.col32(255, 255, 255, 110)
            if not autoCross(tx + tabW - tcw / 2, ty + tabH / 2, 4, crossCol) then
                ctx.uiText(tx + tabW - tcw / 2 - 3, ty + (tabH - lineH(ctx, 0.8)) / 2, "x",
                    crossCol, 0.8)
            end
            if crossClick then
                pendingDel = i
            elseif tabClick and not sel then
                A.sel = i
                A.listOpen = false
            end
            tx = tx + tabW + tgap
        end
        local plusD = tabH
        if tx + plusD > x + w + 0.5 then tx, ty = x, ty + tabH + tgap end
        im.SetCursorPos(im.ImVec2(tx, ty))
        local plusClick = im.InvisibleButton("##grnd_qr_auto_add", im.ImVec2(plusD, plusD)) and true or false
        local plusHov = (im.IsItemHovered and im.IsItemHovered()) or false
        local pcx, pcy = tx + plusD / 2, ty + plusD / 2
        circleFilled(ctx, pcx, pcy, plusD / 2,
            ctx.col32(ac[1], ac[2], ac[3], plusHov and 90 or 46))
        circleFilled(ctx, pcx, pcy, plusD / 2 - 1.5,
            ctx.col32(18, 17, 23, plusHov and 150 or 90))
        if not autoPlus(pcx, pcy, 6,
            plusHov and ctx.col32(255, 255, 255, 255) or ctx.col32(ac[1], ac[2], ac[3], 235)) then
            ctx.uiText(pcx - 4, pcy - lineH(ctx, 1.0) / 2, "+",
                plusHov and hi or acC, 1.0)
        end
        if plusClick then QR.autoAdd() end
        if pendingDel then QR.autoDel(pendingDel) end
        local yy = ty + tabH + 14
        local iw = w
        local dropPreview = false
        local hideAnsNote = false
        local varHints = {
            "Переменные — в ответе или на слове триггера: «дм{ID}», «спек{all}»",
            "{ID} — игрок из репорта: номер из жалобы или ник из текста",
            "{all} — слово сработает, даже если репорт из нескольких слов",
            "{punishments} — вместо ответа придёт список наказаний игрока (команда не выполнится)",
        }
        local varHintsShort = {
            "Переменные: {ID} — игрок из репорта; {all} — слово в любом месте репорта; "
                .. "{punishments} — наказания игрока (команда не выполнится)",
        }
        local tHintSc = 0.72
        local tHintStep = lineH(ctx, tHintSc) + 2
        local intro = wrapW(
            "Вкладка — это слово из репорта: нашлось в жалобе — игроку уходит ответ, затем команда.",
            iw, ctx.drawnW, tHintSc)
        for li = 1, #intro do
            ctx.uiText(x, yy + (li - 1) * tHintStep, intro[li], mut, tHintSc)
        end
        yy = yy + math.max(1, #intro) * tHintStep + 8
        ctx.uiText(x, yy, "Триггер", dim, 0.84)
        local sel2 = QR.autoTab()
        yy = yy + 17
        local trigHint = wrapW("Слово, по которому вкладка узнаёт свой репорт.",
            iw, ctx.drawnW, tHintSc)
        local trigHint2 = wrapW(
            "Можно ввести триггер и похожие слова к триггеру (через запятую), "
                .. "на которые скрипт тоже так будет реагировать",
            iw, ctx.drawnW, tHintSc)
        local ky = yy
        for li = 1, #trigHint do
            ctx.uiText(x, ky, trigHint[li], mut, tHintSc)
            ky = ky + tHintStep
        end
        for li = 1, #trigHint2 do
            ctx.uiText(x, ky, trigHint2[li], mut, tHintSc)
            ky = ky + tHintStep
        end
        yy = ky + 4
        local trigW = iw
        local tkey, tid = "autoTrigger" .. A.sel, "##grnd_qr_auto_trigger"
        field(ctx, tid, tkey, TRIG_CAP, x, yy, trigW, 28, "", false, sel2.trigger)
        local trigVal = trim(bufText(tkey))
        if trigVal ~= sel2.trigger then
            sel2.trigger = trigVal
            A.dirtyAt = os.clock()
        end
        yy = yy + 40
        local selPun = QR.autoPunInTrigger(sel2)
        local selID = QR.autoIDInTrigger(sel2)
        local selFree = QR.autoPlainWords(sel2) > 0
        local punHard = selPun and not selFree and not selID
        local selW, selH = math.min(280, iw), 30
        local cmdHintSc = 0.72
        local cmdHintNone = (QR.autoCmdId(sel2.command) == "none")
        local cmdHintText = cmdHintNone
            and "«Без команды»: вкладка ответит даже в слежке"
            or "Выполнится сразу после ответа"
        local cmdHintW = iw - selW - 12
        local cmdHintX = x + selW + 12
        if cmdHintW < 120
            or #wrapW(cmdHintText, cmdHintW, ctx.drawnW, cmdHintSc) > 2 then
            cmdHintX, cmdHintW = x, iw
        end
        local cmdHintLines = wrapW(cmdHintText, cmdHintW, ctx.drawnW, cmdHintSc)
        local cmdHintStep = lineH(ctx, cmdHintSc) + 2
        local ansNote, ansNoteCol
        if punHard then
            ansNote = "Этот текст не используется: в триггере {punishments} — игрок получит "
                .. "список своих наказаний, а команда не выполнится."
            ansNoteCol = warnC
        elseif selPun then
            ansNote = "Слова с {punishments} отвечают списком наказаний (без команды); "
                .. "остальные слова — этот текст и команда."
            ansNoteCol = warnC
        elseif selID and not selFree then
            ansNote = "Ответ собирается сам: «Приветствую, слежу за игроком Ник[234]» — "
                .. "этот текст уйдёт, только если в репорте нет ни номера, ни имени."
            ansNoteCol = warnC
        elseif selID then
            ansNote = "Слова с {ID} отвечают авто-приветствием и /sp; "
                .. "остальные слова — этот текст и команда."
            ansNoteCol = warnC
        end
        local ansNoteLines = ansNote and wrapW(ansNote, iw, ctx.drawnW, tHintSc) or nil
        ctx.uiText(x, yy, "Ответ игроку", dim, 0.84)
        yy = yy + 17
        local ansCap = punHard and 64 or 92
        local ansH = ansCap
        do
            local noteH0 = ansNoteLines and (#ansNoteLines * tHintStep) or 0
            local chH0 = math.max(selH,
                ((cmdHintX == x) and (selH + 6) or 0)
                    + math.max(1, #cmdHintLines) * cmdHintStep) + 10
            local minSc = 0.36
            local minStep = lineH(ctx, minSc) + 3
            local minRows = 0
            for hi = 1, #varHints do
                minRows = minRows + #wrapW(varHints[hi], iw, ctx.drawnW, minSc)
            end
            local minBlock = math.max(lineH(ctx, minSc),
                (minRows - 1) * minStep + lineH(ctx, minSc))
            local prevH0 = lineH(ctx, 0.86)
            local reserve = 6 + noteH0 + 12 + 17 + chH0 + prevH0 + 6 + minBlock + 6
            ansH = math.max(40, math.min(ansCap, math.floor(bottomY - yy - reserve)))
            if yy + ansH + reserve > bottomY and not dropPreview then
                dropPreview = true
                reserve = reserve - prevH0
                ansH = math.max(40, math.min(ansCap, math.floor(bottomY - yy - reserve)))
            end
            if yy + ansH + reserve > bottomY and ansNoteLines then
                hideAnsNote = true
                reserve = reserve - noteH0
                ansH = math.max(40, math.min(ansCap, math.floor(bottomY - yy - reserve)))
            end
        end
        local akey, aid = "autoAnswer" .. A.sel, "##grnd_qr_auto_answer"
        field(ctx, aid, akey, 1024, x, yy, iw, ansH, "Приветствую, уже смотрю…", true, sel2.answer)
        local ansVal = clampText(cleanText(bufText(akey)), MAX_TEXT)
        if ansVal ~= sel2.answer then
            sel2.answer = ansVal
            A.dirtyAt = os.clock()
        end
        yy = yy + ansH + 6
        if ansNoteLines and not hideAnsNote then
            for li = 1, #ansNoteLines do
                ctx.uiText(x, yy + (li - 1) * tHintStep, ansNoteLines[li], ansNoteCol, tHintSc)
            end
            yy = yy + #ansNoteLines * tHintStep
        end
        yy = yy + 12
        ctx.uiText(x, yy, "Команда после ответа", dim, 0.84)
        yy = yy + 17
        local selY = yy
        im.SetCursorPos(im.ImVec2(x, selY))
        local selClick = im.InvisibleButton("##grnd_qr_auto_cmd", im.ImVec2(selW, selH)) and true or false
        local selHov = (im.IsItemHovered and im.IsItemHovered()) or false
        ctx.roundRect(ctx.dl, ctx.at(x, selY), ctx.at(x + selW, selY + selH),
            (selHov or A.listOpen) and ctx.col32(255, 255, 255, 26) or ctx.col32(255, 255, 255, 12), 6)
        if ctx.dl.AddRect then
            pcall(ctx.dl.AddRect, ctx.dl, ctx.at(x + 0.5, selY + 0.5),
                ctx.at(x + selW - 0.5, selY + selH - 0.5),
                (selHov or A.listOpen) and ctx.col32(ac[1], ac[2], ac[3], 150)
                    or ctx.col32(255, 255, 255, 46), 6, 0, 1)
        end
        ctx.uiText(x + 10, selY + (selH - lineH(ctx, 0.9)) / 2, QR.autoCmdLabel(sel2.command), hi, 0.9)
        tri(ctx.dl, ctx.at, x + selW - 14, selY + selH / 2, 4, "down",
            (selHov or A.listOpen) and acC or mut)
        if selClick then A.listOpen = not A.listOpen end
        local cmdHintTop = (cmdHintX == x) and (selY + selH + 6) or selY
        for li = 1, #cmdHintLines do
            ctx.uiText(cmdHintX, cmdHintTop + (li - 1) * cmdHintStep,
                cmdHintLines[li], cmdHintNone and warnC or mut, cmdHintSc)
        end
        yy = math.max(selY + selH, cmdHintTop + math.max(1, #cmdHintLines) * cmdHintStep) + 10
        local repId = ""
        if type(_G.GRND_REP) == "table" then repId = tostring(_G.GRND_REP.playerId or "") end
        local sampleId = repId:match("^%d+$") or "25"
        local sampleLine
        if punHard then
            sampleLine = QR.autoPunWrap("Мут 60 минут")
        elseif selID and not selFree then
            sampleLine = QR.autoGreet({ nick = "Ник", id = sampleId })
        else
            sampleLine = oneLine(QR.apply(sel2.answer, { nick = "Ник", id = sampleId }))
        end
        local punNoCmd = punHard
        local cmdLine = (not punNoCmd) and QR.autoCmdFor(sampleId, sel2) or nil
        local prev
        if sampleLine == "" then
            prev = cmdLine and ("ответ пуст — уйдёт только " .. cmdLine) or "пусто: не заполнены ответ и команда"
        else
            prev = "/ans " .. sampleId .. " · " .. utf8Cut(sampleLine, punNoCmd and 24 or 40)
                .. (punNoCmd and " · команды не будет"
                    or (cmdLine and (" · затем " .. cmdLine) or " · команды нет"))
        end
        if not dropPreview then
            ctx.uiText(x, yy, fit(prev, iw, ctx.drawnW, 0.86), sampleLine == "" and warnC or mut, 0.86)
        end
        local hintY = yy + (dropPreview and 6 or (lineH(ctx, 0.86) + 6))
        local hintSc, hintStep, hintLines = nil, 0, nil
        local scales = { 0.72, 0.68, 0.64, 0.60, 0.56, 0.52, 0.48, 0.44, 0.40, 0.36 }
        local hintSets = { varHints, varHintsShort }
        for ss = 1, #hintSets do
            local src = hintSets[ss]
            for si = 1, #scales do
                local sc = scales[si]
                local step = lineH(ctx, sc) + 3
                local rows, packed = 0, {}
                for hi = 1, #src do
                    local ls = wrapW(src[hi], iw, ctx.drawnW, sc)
                    packed[#packed + 1] = ls
                    rows = rows + #ls
                end
                local blockH = math.max(lineH(ctx, sc), (rows - 1) * step + lineH(ctx, sc))
                if hintY + blockH <= bottomY then
                    hintSc, hintStep, hintLines = sc, step, packed
                    break
                end
            end
            if hintLines then break end
        end
        if hintLines then
            local hy = hintY
            for hi = 1, #hintLines do
                local ls = hintLines[hi]
                for li = 1, #ls do
                    ctx.uiText(x, hy, ls[li], mut, hintSc)
                    hy = hy + hintStep
                end
            end
        end
        if A.listOpen then
            local ddH = 30
            local ddX, ddY, ddW = x, selY + selH + 4, selW
            local viewH = #AUTO_CMDS * (ddH + 2) - 2
            ctx.roundRect(ctx.dl, ctx.at(ddX - 2, ddY - 2), ctx.at(ddX + ddW + 2, ddY + viewH + 2),
                ctx.col32(16, 17, 24, 252), 8)
            if ctx.dl.AddRect then
                pcall(ctx.dl.AddRect, ctx.dl, ctx.at(ddX - 1.5, ddY - 1.5),
                    ctx.at(ddX + ddW + 1.5, ddY + viewH + 1.5), ctx.col32(255, 255, 255, 34), 8, 0, 1)
            end
            for i = 1, #AUTO_CMDS do
                local d = AUTO_CMDS[i]
                local ryr = ddY + (i - 1) * (ddH + 2)
                im.SetCursorPos(im.ImVec2(ddX, ryr))
                local clicked = im.InvisibleButton("##grnd_qr_auto_cmd_" .. d.id,
                    im.ImVec2(ddW, ddH)) and true or false
                local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                local sel3 = (d.id == QR.autoCmdId(sel2.command))
                ctx.roundRect(ctx.dl, ctx.at(ddX, ryr), ctx.at(ddX + ddW, ryr + ddH),
                    sel3 and ctx.col32(ac[1], ac[2], ac[3], 46)
                        or (hov and ctx.col32(255, 255, 255, 20) or ctx.col32(255, 255, 255, 0)), 6)
                ctx.uiText(ddX + 12, ryr + (ddH - lineH(ctx, 0.9)) / 2, d.label,
                    sel3 and hi or dim, 0.9)
                local hw = 0
                if type(ctx.drawnW) == "function" then
                    local okM, v = pcall(ctx.drawnW, d.hint, 0.78)
                    if okM and type(v) == "number" then hw = v end
                end
                ctx.uiText(ddX + ddW - 12 - hw, ryr + (ddH - lineH(ctx, 0.78)) / 2, d.hint, mut, 0.78)
                if clicked then
                    sel2.command = d.id
                    A.listOpen = false
                    pcall(QR.autoSave)
                end
            end
            if autoOutsideClick(im, ddX, ddY, ddW, viewH)
                and not autoMouseOver(im, x, selY, selW, selH) then
                A.listOpen = false
            end
        end
        return true
    end
    _G.grndRepCountOf = QR.repCountOf
    _G.grndQrAnswerCmd = QR.answerCmd
    _G.grndQrAutoOnReport = function(nick, pid, msg)
        local ok, res = pcall(QR.autoOnReport, nick, pid, msg)
        if ok then return res end
        QR.auto.err = tostring(res)
        print("{FF6666}[GRND]{FFFFFF} автопилот: " .. tostring(res))
        return false
    end
    _G.grndQrAutoTick = function()
        local ok, res = pcall(QR.autoTick)
        if ok then return res end
        QR.auto.err = tostring(res)
        return false
    end
end
do
    local PA = QR.punAuto
    if type(PA) ~= "table" then PA = {} QR.punAuto = PA end
    local MAX_PTRIG = 512
    local TRIG_CAP  = MAX_PTRIG * 2 + 1
    local MAX_PCMD  = 244
    local CMD_CAP   = MAX_PCMD * 2 + 1
    local MAX_PTABS = 15
    local CMD_BYTES = 120
    local SHOT_DELAY = 0.6
    local SHOT_MAXDIR = 260
    local SHOT_PREFIX = "grnd_"
    local PA_FN = {}
    local function paLower(s)
        s = tostring(s or "")
        if s == "" then return s end
        if type(grndLowerUtf) == "function" then
            local ok, v = pcall(grndLowerUtf, s)
            if ok and type(v) == "string" then return v end
        end
        return s:lower()
    end
    local function paUtf(s)
        s = tostring(s or "")
        if s == "" then return s end
        if type(grndUtf8Text) == "function" then
            local ok, v = pcall(grndUtf8Text, s)
            if ok and type(v) == "string" and v ~= "" then return v end
        end
        return s
    end
    local function paPlain(s)
        s = paUtf(s)
        s = s:gsub("{%x%x%x%x%x%x%x%x}", ""):gsub("{%x%x%x%x%x%x}", "")
        s = s:gsub("\194\160", " "):gsub("\239\187\191", "")
        return s
    end
    local function paTrim(s)
        return (tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", ""))
    end
    local function paOne(s)
        return paTrim((tostring(s or ""):gsub("%s+", " ")))
    end
    local PA_PUNCT = {
        ["«"] = true, ["»"] = true, ["…"] = true, ["—"] = true, ["–"] = true,
        ["“"] = true, ["”"] = true, ["‘"] = true, ["’"] = true, ["·"] = true,
        ["•"] = true, ["№"] = true, ["°"] = true,
    }
    local function paWordChar(ch)
        if ch == nil or ch == "" then return false end
        if PA_PUNCT[ch] then return false end
        local b = ch:byte()
        if not b then return false end
        if b < 0x80 then return ch:match("[%w_]") ~= nil end
        return true
    end
    local function paCharBefore(s, pos)
        if pos <= 1 then return "" end
        local i = pos - 1
        while i > 1 and s:byte(i) >= 0x80 and s:byte(i) < 0xC0 do i = i - 1 end
        return s:sub(i, pos - 1)
    end
    local function paCharAfter(s, pos)
        if pos > #s then return "" end
        local b = s:byte(pos) or 0
        local len = (b >= 0xF0 and 4) or (b >= 0xE0 and 3) or (b >= 0xC0 and 2) or 1
        return s:sub(pos, pos + len - 1)
    end
    local PA_QT = {}
    local function paQtAdd(chars, kind, dir)
        for i = 1, #chars do PA_QT[chars[i]] = { kind = kind, dir = dir } end
    end
    paQtAdd({ '"' }, 1, 3)
    paQtAdd({ "'" }, 2, 3)
    paQtAdd({ "«" }, 1, 1) paQtAdd({ "»" }, 1, 2)
    paQtAdd({ "“", "„", "❝" }, 1, 1)
    paQtAdd({ "”", "‟", "❞" }, 1, 2)
    paQtAdd({ "‘", "‚" }, 2, 1)
    paQtAdd({ "’", "‛" }, 2, 2)
    local function paQuoteSpans(s)
        if s == "" then return nil end
        local spans, open = nil, {}
        local i = 1
        while i <= #s do
            local b = s:byte(i) or 0
            local len = (b >= 0xF0 and 4) or (b >= 0xE0 and 3) or (b >= 0xC0 and 2) or 1
            local ch = s:sub(i, i + len - 1)
            local q = PA_QT[ch]
            if q then
                local skip = (q.kind == 2 and q.dir == 3)
                    and paWordChar(paCharBefore(s, i)) and paWordChar(paCharAfter(s, i + len))
                if not skip then
                    if q.dir == 1 then
                        open[#open + 1] = { kind = q.kind, pos = i, ch = ch }
                    elseif q.dir == 2 then
                        local top = open[#open]
                        if top and top.kind == q.kind then
                            table.remove(open)
                            spans = spans or {}
                            spans[#spans + 1] = { a = top.pos, b = i + len - 1 }
                        end
                    else
                        local top = open[#open]
                        if top and top.kind == q.kind and top.ch == ch then
                            table.remove(open)
                            spans = spans or {}
                            spans[#spans + 1] = { a = top.pos, b = i + len - 1 }
                        else
                            open[#open + 1] = { kind = q.kind, pos = i, ch = ch }
                        end
                    end
                end
            end
            i = i + len
        end
        return spans
    end
    local function paInsideQuotes(spans, a, b)
        if not spans then return false end
        for i = 1, #spans do
            if spans[i].a < a and spans[i].b >= b then return true end
        end
        return false
    end
    local function paFindWord(low, word)
        if word == "" then return nil end
        local spans = paQuoteSpans(low)
        local start = 1
        while true do
            local a, b = low:find(word, start, true)
            if not a then return nil end
            if not paWordChar(paCharBefore(low, a)) and not paWordChar(paCharAfter(low, b + 1))
                and not paInsideQuotes(spans, a, b) then
                return a, b
            end
            start = a + 1
        end
    end
    local function paTagToken(t)
        if t:match("^%[.+%]$") or t:match("^%b()$") then return true end
        return #t <= 5 and t:match("^%u+$") ~= nil
    end
    local function paNickId(part)
        part = paTrim(part)
        if part == "" then return nil end
        local nick, id = part:match("^(.-)%s*[%[]%s*(%d+)%s*[%]]%s*$")
        if not nick then nick, id = part:match("^(.-)%s*%(%s*(%d+)%s*%)%s*$") end
        if not nick then nick = part end
        nick = paTrim(nick)
        if nick == "" then return nil end
        if nick:find("%s") then
            local tokens = {}
            for t in nick:gmatch("%S+") do tokens[#tokens + 1] = t end
            for i = 1, #tokens - 1 do
                if not paTagToken(tokens[i]) then return nil end
            end
            nick = tokens[#tokens] or nick
        end
        nick = nick:gsub("[%[%]%(%)]", "")
        nick = paTrim(nick)
        if nick == "" then return nil end
        return nick, id and tonumber(id) or nil
    end
    local PA_SHOUTS = {
        "крикнул", "крикнула", "крикнули", "кричит", "кричат",
        "орет", "орёт", "вопит", "шепчет",
    }
    function PA_FN.parseLine(text)
        local raw = paPlain(text)
        raw = raw:gsub("^%s*%[%d%d:%d%d:%d%d%]%s*", "")
        raw = paTrim(raw)
        if raw == "" then return nil end
        local kind, body = "say", raw
        do
            local inner = body:match("^%(%(%s*(.-)%s*%)%)%s*%)*$")
            if inner and inner ~= "" then
                kind = "ooc"
                body = paTrim(inner:gsub("%s*%)%s*$", ""))
            end
        end
        local nick, pid, msg
        if kind == "say" then
            local hit = false
            for i = 1, #PA_SHOUTS do
                local w = PA_SHOUTS[i]
                local head, tail = body:match("^(.-)%s+" .. w .. "%s*:%s*(.*)$")
                if not head then head, tail = body:match("^(.-)%s+" .. w .. "%s*!%s*(.*)$") end
                if head then
                    nick, pid = paNickId(head)
                    if nick then
                        kind, msg, hit = "shout", (tail or ""), true
                        break
                    end
                end
            end
            if not hit then
                local head, tail = body:match("^(.-)%s*:%s*(.*)$")
                if head then
                    nick, pid = paNickId(head)
                    if nick then msg = tail end
                end
            end
        else
            local head, tail = body:match("^(.-)%s*:%s*(.*)$")
            if head then
                nick, pid = paNickId(head)
                if nick then msg = tail end
            end
        end
        if not nick then return nil end
        if nick:find("%s") then return nil end
        if paLower(nick):match("^%d+$") then return nil end
        if msg == nil then msg = "" end
        return nick, pid, paOne(msg), kind
    end
    function PA_FN.trigList(tab)
        local raw = tostring(tab and tab.trigger or "")
        local mode = tostring(tab and tab.mode or "word")
        local out = {}
        for piece in (raw .. "\n"):gmatch("([^,;\n]*)[,;\n]") do
            local wide = (mode ~= "exact") or piece:find("%b{}") ~= nil
            local word = paLower(paOne(paPlain((piece:gsub("%b{}", " ")))))
            if word ~= "" then out[#out + 1] = { word = word, wide = wide } end
        end
        return out
    end
    function PA_FN.matchTab(tab, msg)
        local text = paOne(paPlain(msg))
        if text == "" then return nil end
        local low = paLower(text)
        local list = PA_FN.trigList(tab)
        for i = 1, #list do
            local w = list[i]
            if w.wide then
                if paFindWord(low, w.word) then return w.word end
            elseif low == w.word then
                return w.word
            end
        end
        return nil
    end
    function PA_FN.buildCmd(cmd, info)
        local s = paOne(tostring(cmd or ""))
        s = paOne((s:gsub("%b{}", " ")))
        if s == "" then return "" end
        info = (type(info) == "table") and info or {}
        local pid = tostring(info.pid or "")
        if pid == "" then return s end
        local first, rest = s:match("^(%S+)%s*(.*)$")
        if not first then return s end
        return first .. " " .. pid .. (rest ~= "" and (" " .. rest) or "")
    end
    PA_FN.plain = paPlain
    PA_FN.one = paOne
    local function paNewTab()
        return { trigger = "", mode = "word", cmd = "" }
    end
    PA.newTab = paNewTab
    local PA_DEF = { shot = true }
    local PA_BOOLS = { "shot" }
    local PA_FIXED = {
        { "watchSay", true }, { "watchShout", true }, { "watchOoc", true },
        { "notify", true }, { "logOn", true },
        { "skipSelf", false }, { "skipAdmins", true },
    }
    local function paBool(v, def)
        if v == nil then return def end
        if v == true or v == false then return v end
        local s = tostring(v):lower()
        if s == "1" or s == "true" then return true end
        if s == "0" or s == "false" then return false end
        local n = tonumber(s)
        if n then return n ~= 0 end
        return def
    end
    function PA.normalize()
        local A = PA
        if type(A.tabs) ~= "table" then A.tabs = {} end
        local out = {}
        for i = 1, #A.tabs do
            local t = A.tabs[i]
            if type(t) == "table" then out[#out + 1] = t end
        end
        if #out == 0 then out[1] = paNewTab() end
        while #out > MAX_PTABS do table.remove(out) end
        for i = 1, #out do
            local t = out[i]
            t.trigger = clampText(oneLine(utf(t.trigger or "")), MAX_PTRIG)
            t.cmd = clampText(oneLine(utf(t.cmd or "")), MAX_PCMD)
            t.mode = (tostring(t.mode or "") == "exact") and "exact" or "word"
            t.after, t.on = nil, nil
        end
        A.tabs = out
        A.sel = math.max(1, math.min(#out, math.floor(tonumber(A.sel) or 1)))
        A.on = paBool(A.on, false)
        for i = 1, #PA_FIXED do A[PA_FIXED[i][1]] = PA_FIXED[i][2] end
        for i = 1, #PA_BOOLS do
            local k = PA_BOOLS[i]
            A[k] = paBool(A[k], PA_DEF[k])
        end
        A.shotDir = clampText(oneLine(utf(A.shotDir or "")), SHOT_MAXDIR)
        A.fired = math.max(0, math.floor(tonumber(A.fired) or 0))
        return A
    end
    function PA.tab()
        PA.normalize()
        local t = PA.tabs[PA.sel] or PA.tabs[1]
        if type(t) ~= "table" then t = paNewTab() PA.tabs[1] = t PA.sel = 1 end
        return t, PA.sel
    end
    function PA.tabLabel(i)
        local t = PA.tabs and PA.tabs[i]
        local trg = t and trim(t.trigger or "") or ""
        local first = tostring(trg):match("^([^,;\n]*)") or ""
        first = trim(first)
        if first ~= "" then return first end
        return "Вкладка " .. tostring(i)
    end
    function PA.tabAdd()
        PA.normalize()
        if #PA.tabs >= MAX_PTABS then
            QR.toast("Больше " .. tostring(MAX_PTABS) .. " вкладок не нужно", "warn", 2.6)
            return nil
        end
        PA.tabs[#PA.tabs + 1] = paNewTab()
        PA.sel = #PA.tabs
        PA.touch()
        pcall(PA.save)
        return PA.sel
    end
    function PA.tabDel(i)
        PA.normalize()
        i = math.floor(tonumber(i) or PA.sel or 1)
        if i < 1 or i > #PA.tabs then return false end
        if #PA.tabs <= 1 then
            PA.tabs[1] = paNewTab()
            PA.sel = 1
        else
            table.remove(PA.tabs, i)
            if PA.sel > #PA.tabs then PA.sel = #PA.tabs end
        end
        if type(QR.bufs) == "table" then
            for k in pairs(QR.bufs) do
                if tostring(k):find("^pa") then QR.bufs[k] = nil end
            end
        end
        PA.touch()
        pcall(PA.save)
        return true
    end
    function PA.path()
        local dir = tostring(QR.path() or ""):match("^(.*[/\\])")
        if dir then return dir .. "grnd_punauto.cfg" end
        return "grnd_punauto.cfg"
    end
    function PA.load()
        if PA.loaded then return true end
        PA.loaded = true
        local tabs, sel = {}, nil
        local ok, f = pcall(GRND_CONFIG.open, PA.path(), "r")
        if ok and f then
            for line in f:lines() do
                local k, v = tostring(line or ""):match("^([%w_]+)=(.*)$")
                if k then
                    if v ~= nil then v = tostring(v) end
                    local idx, field = k:match("^t(%d+)_(%a+)$")
                    if idx then
                        local n = tonumber(idx)
                        if n and n >= 1 and n <= MAX_PTABS then
                            tabs[n] = tabs[n] or paNewTab()
                            if field == "trigger" then tabs[n].trigger = v
                            elseif field == "mode" then tabs[n].mode = v
                            elseif field == "cmd" then tabs[n].cmd = v end
                        end
                    elseif k == "on" then PA.on = paBool(v, false)
                    elseif k == "sel" then sel = tonumber(v)
                    elseif k == "shotDir" then PA.shotDir = v
                    elseif PA_DEF[k] ~= nil then PA[k] = paBool(v, PA_DEF[k])
                    end
                end
            end
            pcall(f.close, f)
        end
        if #tabs == 0 then tabs[1] = paNewTab() end
        PA.tabs, PA.sel = tabs, sel
        PA.normalize()
        return true
    end
    function PA.ensure()
        if type(PA) ~= "table" then PA = {} QR.punAuto = PA end
        if not PA.loaded then pcall(PA.load) end
        if type(PA.tabs) ~= "table" then pcall(PA.normalize) end
        return PA
    end
    function PA.save()
        PA.normalize()
        PA.dirtyAt = nil
        local ok, f = pcall(GRND_CONFIG.open, PA.path(), "w")
        if not ok or not f then return false end
        local function w(k, v) f:write(k .. "=" .. tostring(v) .. "\n") end
        w("on", PA.on and 1 or 0)
        w("sel", tostring(PA.sel or 1))
        for i = 1, #PA_BOOLS do w(PA_BOOLS[i], PA[PA_BOOLS[i]] and 1 or 0) end
        w("shotDir", PA.shotDir or "")
        for i = 1, #PA.tabs do
            local t = PA.tabs[i]
            w("t" .. i .. "_trigger", t.trigger or "")
            w("t" .. i .. "_mode", t.mode or "word")
            w("t" .. i .. "_cmd", t.cmd or "")
        end
        pcall(f.close, f)
        if GRND_CONFIG and type(GRND_CONFIG.flush) == "function" then
            pcall(GRND_CONFIG.flush)
        end
        return true
    end
    function PA.touch() PA.dirtyAt = os.clock() end
    function PA.set(on)
        PA.ensure()
        PA.on = on and true or false
        if not PA.on then
            PA.lastCheck = "Автопилот выключен"
        else
            PA.lastCheck = "Автопилот включён — жду строки чата"
        end
        pcall(PA.save)
        QR.toast(PA.on and "Автопилот выдачи включён" or "Автопилот выдачи выключен",
            PA.on and "ok" or "warn", 2.4)
    end
    local function paMyId()
        if type(sampGetLocalPlayerId) ~= "function" then return nil end
        local ok, id = pcall(sampGetLocalPlayerId)
        if ok and type(id) == "number" then return math.floor(id) end
        return nil
    end
    PA.myId = paMyId
    local function paNickById(id)
        id = tonumber(id)
        if not id then return nil end
        if type(sampIsPlayerConnected) == "function" then
            local okC, conn = pcall(sampIsPlayerConnected, id)
            if not (okC and conn) then return nil end
        end
        if type(sampGetPlayerNickname) ~= "function" then return nil end
        local ok, nick = pcall(sampGetPlayerNickname, id)
        if ok and type(nick) == "string" and nick ~= "" then return nick end
        return nil
    end
    local function paSameNick(a, b)
        a, b = tostring(a or ""), tostring(b or "")
        if a == "" or b == "" then return false end
        if a == b then return true end
        return paLower(paUtf(a)) == paLower(paUtf(b))
    end
    PA.sameNick = paSameNick
    local function paRoster()
        local out = {}
        local C = _G.GRND_CHATID
        if type(C) == "table" and type(C.refresh) == "function" then
            pcall(C.refresh)
            local r = C.roster
            if type(r) == "table" then
                for i = 1, #r do
                    local it = r[i]
                    if type(it) == "table" and it.nick and it.id then
                        out[#out + 1] = { nick = tostring(it.nick), id = tonumber(it.id) }
                    end
                end
            end
        end
        local me = paMyId()
        if me then
            local nick = paNickById(me)
            if nick then out[#out + 1] = { nick = nick, id = me, me = true } end
        end
        return out
    end
    PA.roster = paRoster
    function PA.resolve(nick, pidHint)
        local roster = paRoster()
        local wantId = tonumber(pidHint)
        local found, foundHint = nil, nil
        for i = 1, #roster do
            local it = roster[i]
            if paSameNick(it.nick, nick) then
                if wantId and it.id == wantId then foundHint = it.id end
                if not found then found = it.id end
            end
        end
        if foundHint then return foundHint end
        if found then return found end
        if wantId then
            local live = paNickById(wantId)
            if live and paSameNick(live, nick) then return wantId end
        end
        return nil
    end
    function PA.isAdmin(nick, id)
        local AO = _G.GRND_AO
        local list = (type(AO) == "table") and AO.list or nil
        if type(list) ~= "table" or #list == 0 then return false end
        for i = 1, #list do
            local it = list[i]
            if type(it) == "table" then
                if it.id and id and tonumber(it.id) == tonumber(id) then return true end
                if it.nick and paSameNick(it.nick, nick) then return true end
            end
        end
        return false
    end
    function PA.log(msg)
        PA.lastLog = tostring(msg or "")
    end
    local function paSend(cmd)
        cmd = tostring(cmd or "")
        if cmd == "" then return false end
        if type(QR.sendChat) == "function" then
            local ok, res = pcall(QR.sendChat, cmd)
            if ok and res ~= false then return true end
        end
        if type(grndChatSend) == "function" then
            local ok, res = pcall(grndChatSend, cmd)
            if ok and res ~= false then return true end
        end
        if type(sampSendChat) == "function" then
            local out = cmd
            if type(grndAnsiText) == "function" then
                local okA, ansi = pcall(grndAnsiText, cmd)
                if okA and type(ansi) == "string" and ansi ~= "" then out = ansi end
            end
            return pcall(sampSendChat, out) and true or false
        end
        if type(QR.queueCmd) == "function" then
            local ok, res = pcall(QR.queueCmd, cmd)
            if ok and res ~= false then return true end
        end
        if type(grndRepQueue) == "function" then
            return pcall(grndRepQueue, cmd) and true or false
        end
        return false
    end
