    local function paShotClean(v)
        local t = tostring(v or "")
        t = t:gsub("\r", ""):gsub("\n.*$", "")
        t = t:gsub("^%s+", ""):gsub("%s+$", "")
        if #t > 120 then t = t:sub(1, 117) .. "…" end
        return t
    end
    local SHOT_MOD, SHOT_TRIED = nil, false
