        return nil
    end
    local function paShotUtf8(wide)
        local out, i = {}, 0
        while true do
            local c = tonumber(wide[i]) or 0
            if c == 0 then break end
            if c < 0x80 then
                out[#out + 1] = string.char(c)
            elseif c < 0x800 then
                out[#out + 1] = string.char(0xC0 + math.floor(c / 0x40), 0x80 + (c % 0x40))
            elseif c >= 0xD800 and c < 0xDC00 then
                local lo = tonumber(wide[i + 1]) or 0
                local cp = 0x10000 + (c - 0xD800) * 0x400 + (lo - 0xDC00)
                out[#out + 1] = string.char(0xF0 + math.floor(cp / 0x40000),
                    0x80 + (math.floor(cp / 0x1000) % 0x40),
                    0x80 + (math.floor(cp / 0x40) % 0x40), 0x80 + (cp % 0x40))
                i = i + 1
            else
                out[#out + 1] = string.char(0xE0 + math.floor(c / 0x1000),
                    0x80 + (math.floor(c / 0x40) % 0x40), 0x80 + (c % 0x40))
            end
            i = i + 1
        end
        return table.concat(out)
    end
    local function paShotDocsDir()
        local ffi = paShotLibs()
        if not ffi then return nil end
        local okD = pcall(ffi.cdef, [[
            int __stdcall SHGetFolderPathW(void* hwnd, int csidl, void* hToken,
                unsigned long dwFlags, uint16_t* pszPath);
        ]])
        if not okD then return nil end
        local okS, shell = pcall(ffi.load, "shell32")
        if not (okS and shell and shell.SHGetFolderPathW) then return nil end
        local buf = ffi.new("uint16_t[?]", 512)
        local hr = shell.SHGetFolderPathW(nil, 5, nil, 0, buf)
        if (tonumber(hr) or 0) ~= 0 then return nil end
        local got = paShotUtf8(buf)
        if got == "" then return nil end
        return (got:gsub("[/\\]+$", ""))
    end
    local function paShotUserDir()
        local mod = paShotModule()
        if mod and type(mod.getUserDirectoryPath) == "function" then
            local ok, v = pcall(mod.getUserDirectoryPath)
            if ok and type(v) == "string" and v ~= "" then
                return (tostring(v):gsub("[/\\]+$", ""))
            end
        end
        local asi, ffi = paShotAsi()
        if asi and asi.GetUserDirectoryPath and ffi then
            local ok, v = pcall(function() return ffi.string(asi.GetUserDirectoryPath()) end)
            if ok and type(v) == "string" and v ~= "" then
                return (tostring(v):gsub("[/\\]+$", ""))
            end
        end
        return paShotDocsDir()
    end
    local function paShotPathList(path)
        local list = { tostring(path or "") }
        local ansi = _G.grndAnsiText
        if type(ansi) == "function" then
            local ok, v = pcall(ansi, list[1])
            if ok and type(v) == "string" and v ~= "" and v ~= list[1] then
                list[#list + 1] = v
            end
        end
        return list
    end
    local function paShotMkdir(dir)
        if type(dir) ~= "string" or dir == "" then return end
        if type(createDirectory) ~= "function" then return end
        for _, variant in ipairs(paShotPathList(dir)) do
            local d = variant:gsub("[/\\]+$", "")
            local prefix = d:match("^%a:") or ((d:sub(1, 2) == "\\\\") and "\\\\" or "")
            local cursor = prefix
            for part in d:sub(#prefix + 1):gmatch("[^/\\]+") do
                cursor = (cursor == "") and part or (cursor .. SHOT_SEP .. part)
                pcall(createDirectory, cursor)
            end
        end
    end
    local function paShotRoots(dir)
        dir = tostring(dir or ""):gsub("[/\\]+$", "")
        local abs = dir:match("^%a:[/\\]") ~= nil or dir:sub(1, 2) == "\\\\"
            or dir:sub(1, 1) == "/"
        local roots = {}
        if abs then
            roots[#roots + 1] = dir
        else
            local user = paShotUserDir()
            if user then roots[#roots + 1] = user .. SHOT_SEP .. "App screens" .. SHOT_SEP .. dir end
            roots[#roots + 1] = dir
        end
        return roots, abs
    end
    local function paShotName(nick)
        local tag = tostring(nick or ""):gsub("[^%w_%-%.,]+", "_"):sub(1, 24)
        if tag == "" then tag = "nick" end
        return string.format("grnd_%s_%s", os.date("%Y-%m-%d_%H-%M-%S"), tag)
    end
    local function paShotWritable(dir)
        if type(dir) ~= "string" or dir == "" then return false end
        for _, variant in ipairs(paShotPathList(dir)) do
            local probe = variant .. SHOT_SEP .. "grnd_write_test.tmp"
            local f = io.open(probe, "wb")
            if f then
                f:close()
                pcall(os.remove, probe)
                return true
            end
        end
        return false
    end
    local function paShotExists(path)
        if type(path) ~= "string" or path == "" then return false end
        for _, variant in ipairs(paShotPathList(path)) do
            if type(doesFileExist) == "function" then
                local ok, v = pcall(doesFileExist, variant)
                if ok and v then return true end
            end
            local f = io.open(variant, "rb")
            if f then f:close() return true end
        end
        return false
    end
    local function paShotVariants(root, name)
        return {
            root .. SHOT_SEP .. name .. ".png",
            root .. SHOT_SEP .. name,
            root .. SHOT_SEP .. name .. ".png.png",
        }
