        "d3dx9_37", "d3dx9_36", "d3dx9_35", "d3dx9_34", "d3dx9_33", "d3dx9_32",
        "d3dx9_31", "d3dx9_30", "d3dx9_29", "d3dx9_28", "d3dx9_27", "d3dx9_26",
