    local function paShotDevice()
        local ffi = paShotLibs()
        if not ffi then return nil end
        local function asPtr(v)
            if v == nil then return nil end
            local okC, p = pcall(ffi.cast, "void*", v)
            if okC and p ~= nil and p ~= ffi.NULL then return p end
            return nil
        end
        if type(getD3DDevicePtr) == "function" then
            local ok, dev = pcall(getD3DDevicePtr)
            if ok then
                local p = asPtr(dev)
                if p then return p end
            end
        end
        local okR, ptr = pcall(function() return ffi.cast("void**", 0xC97C28)[0] end)
        if okR and ptr ~= nil and ptr ~= ffi.NULL then
            local p = asPtr(ptr)
            if p then return p end
        end
        local mem = libs and libs.memory
        if mem then
            local v
            if type(mem.read) == "function" then
                local ok1, r1 = pcall(mem.read, 0xC97C28, 4, false)
                if ok1 then v = tonumber(r1) end
            end
            if not v and type(mem.getuint32) == "function" then
                local ok2, r2 = pcall(mem.getuint32, 0xC97C28, false)
                if ok2 then v = tonumber(r2) end
            end
            if not v and type(mem.readuint32) == "function" then
                local ok3, r3 = pcall(mem.readuint32, 0xC97C28)
                if ok3 then v = tonumber(r3) end
            end
            if v and v > 0x10000 and v < 0x80000000 then
                local p = asPtr(v)
                if p then return p end
            end
        end
        return nil
    end
    local function paShotWide(path)
        local ffi = paShotLibs()
        if not ffi then return nil end
        local s = tostring(path or "")
        local buf = ffi.new("uint16_t[?]", #s + 2)
        local n, i = 0, 1
        while i <= #s do
            local b = s:byte(i)
            local cp, len
            if b < 0x80 then cp, len = b, 1
            elseif b < 0xE0 then cp, len = b - 0xC0, 2
            elseif b < 0xF0 then cp, len = b - 0xE0, 3
            else cp, len = b - 0xF0, 4 end
            for k = 1, len - 1 do
                local nb = s:byte(i + k)
                if not nb then break end
                cp = cp * 0x40 + (nb - 0x80)
            end
            i = i + len
            if cp < 0x10000 then
                buf[n] = cp
                n = n + 1
            else
                cp = cp - 0x10000
                buf[n] = 0xD800 + math.floor(cp / 0x400)
                buf[n + 1] = 0xDC00 + (cp % 0x400)
                n = n + 2
            end
        end
        buf[n] = 0
        return buf
    end
    local PNG = {}
    local PIX = {}
    function PNG.u32be(n)
        n = tonumber(n) or 0
        return string.char(math.floor(n / 16777216) % 256, math.floor(n / 65536) % 256,
            math.floor(n / 256) % 256, n % 256)
    end
    PNG.crcLib, PNG.crcTried, PNG.crcTable = nil, false, nil
    function PNG.zlib()
        if PNG.crcTried then return PNG.crcLib end
        PNG.crcTried = true
        local ffi = paShotLibs()
        if not ffi then return nil end
        pcall(ffi.cdef, [[
            int compress2(unsigned char* dest, uint32_t* destLen,
                const unsigned char* source, uint32_t sourceLen, int level);
            uint32_t crc32(uint32_t crc, const unsigned char* buf, uint32_t len);
        ]])
        local names = { "zlib1", "zlib", "libz" }
        for i = 1, #names do
            local ok, lib = pcall(ffi.load, names[i])
            if ok and lib then
                local okF, both = pcall(function()
                    return (lib.compress2 ~= nil) and (lib.crc32 ~= nil)
                end)
                if okF and both then
                    PNG.crcLib = lib
                    return lib
                end
            end
        end
        return nil
    end
    function PNG.crc32(s)
        local lib = PNG.zlib()
        if lib then
            local ok, v = pcall(lib.crc32, 0, s, #s)
            if ok then return tonumber(v) or 0 end
        end
        if not PNG.crcTable then
            local t = {}
            for i = 0, 255 do
                local c = i
                for _ = 1, 8 do
                    if bit.band(c, 1) == 1 then
                        c = bit.bxor(0xEDB88320, bit.rshift(c, 1))
                    else
                        c = bit.rshift(c, 1)
                    end
                end
                t[i] = c
            end
            PNG.crcTable = t
        end
        local crc = 0xFFFFFFFF
        for i = 1, #s do
            crc = bit.bxor(PNG.crcTable[bit.band(bit.bxor(crc, s:byte(i)), 255)],
                bit.rshift(crc, 8))
        end
        return bit.bxor(crc, 0xFFFFFFFF) % 4294967296
    end
    function PNG.adler32(s)
        local a, b = 1, 0
        local M = 65521
        for i = 1, #s do
            a = (a + s:byte(i)) % M
            b = (b + a) % M
        end
        return (b * 65536 + a) % 4294967296
    end
    function PNG.chunk(kind, data)
        return PNG.u32be(#data) .. kind .. data .. PNG.u32be(PNG.crc32(kind .. data))
    end
    function PNG.deflate(raw)
        local lib = PNG.zlib()
        if lib and #raw > 0 then
            local ffi = paShotLibs()
            local src = raw
            local cap = #raw + math.floor(#raw / 1000) + 128
            local dst = ffi.new("unsigned char[?]", cap)
            local len = ffi.new("uint32_t[1]", cap)
            local ok, res = pcall(lib.compress2, dst, len, src, #raw, 6)
            local outLen = tonumber(len[0]) or 0
            if ok and (tonumber(res) or -1) == 0 and outLen > 0 and outLen < cap then
                return ffi.string(dst, outLen)
            end
        end
        local out = { "\120\1" }
        local n, pos = #raw, 1
        if n == 0 then out[#out + 1] = string.char(1, 0, 0, 255, 255) end
        while pos <= n do
            local size = math.min(65535, n - pos + 1)
            local last = (pos + size > n) and 1 or 0
            out[#out + 1] = string.char(last, size % 256, math.floor(size / 256),
                (65535 - size) % 256, math.floor((65535 - size) / 256))
            out[#out + 1] = raw:sub(pos, pos + size - 1)
            pos = pos + size
        end
        out[#out + 1] = PNG.u32be(PNG.adler32(raw))
        return table.concat(out)
    end
    function PNG.bytes(raw, w, h)
        return "\137PNG\r\n\26\n"
            .. PNG.chunk("IHDR", PNG.u32be(w) .. PNG.u32be(h) .. string.char(8, 2, 0, 0, 0))
            .. PNG.chunk("IDAT", PNG.deflate(raw))
            .. PNG.chunk("IEND", "")
    end
    function PIX.rows(surf, fmt, w, h, rect)
        local ffi = paShotLibs()
        if not ffi then return nil, "нет LuaJIT-FFI" end
        local kind
        if fmt == 21 or fmt == 22 then kind = "bgra"
        elseif fmt == 32 or fmt == 33 then kind = "rgba"
        elseif fmt == 20 then kind = "rgb"
        elseif fmt == 23 then kind = "r5g6b5"
        elseif fmt == 24 or fmt == 25 then kind = "r5g5b5"
        else return nil, "формат кадра не поддержан (D3DFMT " .. tostring(fmt) .. ")" end
        local vt = ffi.cast("void***", surf)[0]
        local okL, lockRect = pcall(ffi.cast,
            "int(__stdcall*)(void*, void*, const void*, unsigned long)", vt[13])
        local okU, unlock = pcall(ffi.cast, "int(__stdcall*)(void*)", vt[14])
        if not (okL and okU) then return nil, "LockRect/UnlockRect не привязались" end
        if not PNG.lockRectDef then
            PNG.lockRectDef = true
            pcall(ffi.cdef, [[typedef struct { int Pitch; void* pBits; } grnd_shot_locked_rect;]])
        end
        local lr = ffi.new("grnd_shot_locked_rect")
        local hr = lockRect(surf, lr, nil, 0)
        if (tonumber(hr) or 0) ~= 0 then return nil, "LockRect 0x" .. string.format("%08X", tonumber(hr) or 0) end
        local okPix, rows, wOut, err = pcall(function()
            local pitch = tonumber(lr.Pitch) or 0
            local addr = tonumber(ffi.cast("uintptr_t", lr.pBits)) or 0
            if pitch == 0 or addr == 0 then return nil, nil, "поверхность не залочилась" end
            local stride = pitch > 0 and pitch or -pitch
            local x0, y0, x1, y1 = 0, 0, w, h
            if rect then
                x0 = math.max(0, math.min(w, tonumber(rect.left) or 0))
                y0 = math.max(0, math.min(h, tonumber(rect.top) or 0))
                x1 = math.max(x0 + 1, math.min(w, tonumber(rect.right) or w))
                y1 = math.max(y0 + 1, math.min(h, tonumber(rect.bottom) or h))
            end
            local cw, ch = x1 - x0, y1 - y0
            local base = ffi.cast("uint8_t*", addr)
            local out = ffi.new("uint8_t[?]", cw * 3)
            local list = {}
            for y = 0, ch - 1 do
                local srcY = (pitch > 0) and (y0 + y) or (h - 1 - (y0 + y))
                local rowPtr = base + srcY * stride
                if kind == "rgb" then
                    list[#list + 1] = ffi.string(rowPtr + x0 * 3, cw * 3)
                elseif kind == "bgra" or kind == "rgba" then
                    local src = ffi.cast("uint32_t*", rowPtr) + x0
                    for i = 0, cw - 1 do
                        local v = tonumber(src[i]) or 0
                        local r, g, b
                        if kind == "bgra" then
                            r = bit.band(math.floor(v / 65536), 255)
                            g = bit.band(math.floor(v / 256), 255)
                            b = bit.band(v, 255)
                        else
                            r = bit.band(v, 255)
                            g = bit.band(math.floor(v / 256), 255)
                            b = bit.band(math.floor(v / 65536), 255)
                        end
                        out[i * 3] = r
                        out[i * 3 + 1] = g
                        out[i * 3 + 2] = b
                    end
                    list[#list + 1] = ffi.string(out, cw * 3)
                else
                    local src = ffi.cast("uint16_t*", rowPtr) + x0
                    for i = 0, cw - 1 do
                        local v = tonumber(src[i]) or 0
                        local r, g, b
                        if kind == "r5g6b5" then
                            r = math.floor(bit.band(math.floor(v / 2048), 31) * 255 / 31)
                            g = math.floor(bit.band(math.floor(v / 32), 63) * 255 / 63)
                            b = math.floor(bit.band(v, 31) * 255 / 31)
                        else
                            r = math.floor(bit.band(math.floor(v / 1024), 31) * 255 / 31)
                            g = math.floor(bit.band(math.floor(v / 32), 31) * 255 / 31)
                            b = math.floor(bit.band(v, 31) * 255 / 31)
                        end
                        out[i * 3] = r
                        out[i * 3 + 1] = g
                        out[i * 3 + 2] = b
                    end
                    list[#list + 1] = ffi.string(out, cw * 3)
                end
            end
            return list, cw, nil
        end)
        pcall(unlock, surf)
        if not okPix then return nil, "чтение пикселей: " .. tostring(rows) end
        if not rows then return nil, tostring(wOut or err or "не удалось прочитать пиксели") end
        return rows, wOut
    end
    local function paShotSelfWrite(surf, fmt, w, h, rect, path)
        local rows, wOut, err = PIX.rows(surf, fmt, w, h, rect)
        if not rows then return false, tostring(err) end
        local parts = {}
        for i = 1, #rows do
            parts[#parts + 1] = "\0"
            parts[#parts + 1] = rows[i]
        end
        local raw = table.concat(parts)
        local okPng, png = pcall(PNG.bytes, raw, wOut, #rows)
        if not okPng then return false, "сборка PNG: " .. tostring(png) end
        local opened = nil
        for _, variant in ipairs(paShotPathList(path)) do
            local f = io.open(variant, "wb")
            if f then
                local okW, werr = pcall(function() f:write(png) end)
                pcall(f.close, f)
                if okW and paShotExists(variant) then
                    opened = variant
                    break
                end
            end
        end
        if not opened then
            return false, "файл не открылся на запись: " .. tostring(path)
        end
        return true, string.format("%dx%d, %d КБ", wOut, #rows, math.floor(#png / 1024)), opened
    end
    local SHOT_HWND_ADDR = 0xC97C1C
    local function paShotGrabReal(path)
        local ffi = paShotLibs()
        local lib = paShotD3dx()
        if not (ffi and lib) then return false, "не найдена библиотека d3dx9 (DirectX)" end
        local dev = paShotDevice()
        if not dev then return false, "не найдено устройство D3D9" end
        local wide = paShotWide(path)
        if not wide then return false, "путь не удалось преобразовать" end
        local vtbl = ffi.cast("void***", dev)[0]
        local function bind(vt, idx, sig)
            local ok, fn = pcall(ffi.cast, sig, vt[idx])
            if not ok or fn == nil then
                return nil, "тип метода D3D9 не принят: " .. tostring(sig)
            end
            return fn
        end
        local getBackBuffer, e1 = bind(vtbl, 18, "int(__stdcall*)(void*, unsigned int, unsigned int, int, void**)")
        local getRTTData, e2 = bind(vtbl, 32, "int(__stdcall*)(void*, void*, void*)")
        local getFrontData, e3 = bind(vtbl, 33, "int(__stdcall*)(void*, unsigned int, void*)")
        local createSurface, e4 = bind(vtbl, 36,
            "int(__stdcall*)(void*, unsigned int, unsigned int, int, int, void**, void*)")
        local release, e5 = bind(vtbl, 2, "uint32_t(__stdcall*)(void*)")
        local function hrHex(hr)
            local n = tonumber(hr) or 0
            if n < 0 then n = n + 4294967296 end
            return string.format("0x%08X", n)
        end
        local function hrBad(hr) return (tonumber(hr) or 0) ~= 0 end
        if not (release and createSurface) then
            return false, "привязка методов D3D9 не удалась: " .. tostring(e5 or e4)
        end
        local bad = {}
        if getBackBuffer and getRTTData then
            local back = ffi.new("void*[1]")
            local hr = getBackBuffer(dev, 0, 0, D3D_MONO, back)
            if hrBad(hr) or back[0] == ffi.NULL then
                bad[#bad + 1] = "GetBackBuffer " .. hrHex(hr)
            else
                local src = back[0]
                local svtbl = ffi.cast("void***", src)[0]
                local getDesc, eD = bind(svtbl, 12, "int(__stdcall*)(void*, void*)")
                local desc = ffi.new("uint32_t[8]")
                local w, h, fmt
                if getDesc then
                    hr = getDesc(src, desc)
                    w, h, fmt = tonumber(desc[6]), tonumber(desc[7]), tonumber(desc[0])
                end
                if not getDesc or hrBad(hr) or not w or not h or w == 0 or h == 0 then
                    release(src)
                    bad[#bad + 1] = "не удалось узнать размер кадра"
                        .. (eD and (" (" .. tostring(eD) .. ")") or "")
                else
                    local dst = ffi.new("void*[1]")
                    hr = createSurface(dev, w, h, fmt, D3D_POOL_SYSTEMMEM, dst, nil)
                    if (hrBad(hr) or dst[0] == ffi.NULL) and fmt ~= D3D_A8R8G8B8 then
                        hr = createSurface(dev, w, h, D3D_A8R8G8B8, D3D_POOL_SYSTEMMEM, dst, nil)
                    end
                    if hrBad(hr) or dst[0] == ffi.NULL then
                        release(src)
                        bad[#bad + 1] = "CreateOffscreenPlainSurface " .. hrHex(hr)
                    else
                        hr = getRTTData(dev, src, dst[0])
                        release(src)
                        if hrBad(hr) then
                            release(dst[0])
                            bad[#bad + 1] = "GetRenderTargetData " .. hrHex(hr)
                        else
                            local okPng, pngNote, pngPath = paShotSelfWrite(dst[0], fmt, w, h, nil, path)
                            if okPng then
                                release(dst[0])
                                return true, nil, "свой PNG, задний буфер " .. tostring(pngNote), pngPath
                            end
                            bad[#bad + 1] = "свой PNG: " .. tostring(pngNote)
                            hr = lib.D3DXSaveSurfaceToFileW(wide, D3DXIFF_PNG, dst[0], nil, nil)
                            release(dst[0])
                            if not hrBad(hr) then
                                return true, nil, string.format("задний буфер %dx%d (D3DX)", w, h)
                            end
                            bad[#bad + 1] = "D3DXSaveSurfaceToFile " .. hrHex(hr)
                                .. " (" .. tostring(SHOT_D3DX_NAME) .. ")"
                        end
                    end
                end
            end
        else
            bad[#bad + 1] = "привязка GetBackBuffer не удалась: " .. tostring(e1 or e2)
        end
        if getFrontData then
            local okU, u32 = pcall(ffi.load, "user32")
            local hwnd = nil
            if okU and u32 then
                pcall(ffi.cdef, "int __stdcall IsIconic(void* hWnd);")
                pcall(ffi.cdef, "int __stdcall GetClientRect(void* hWnd, void* lpRect);")
                pcall(ffi.cdef, "int __stdcall ClientToScreen(void* hWnd, void* lpPoint);")
                pcall(ffi.cdef, "int __stdcall GetSystemMetrics(int nIndex);")
                pcall(ffi.cdef, [[typedef struct { long left; long top; long right; long bottom; } grnd_shot_rect;]])
                pcall(ffi.cdef, [[typedef struct { long x; long y; } grnd_shot_point;]])
                local okW, wptr = pcall(function() return ffi.cast("void**", SHOT_HWND_ADDR)[0] end)
                if okW and wptr ~= nil and wptr ~= ffi.NULL then hwnd = wptr end
            end
            if not (hwnd and u32 and u32.IsIconic and u32.GetSystemMetrics) then
                bad[#bad + 1] = "передний буфер: не найдено окно игры"
            elseif tonumber(u32.IsIconic(hwnd)) ~= 0 then
                bad[#bad + 1] = "передний буфер: окно игры свёрнуто"
            else
                local sw, sh = tonumber(u32.GetSystemMetrics(0)), tonumber(u32.GetSystemMetrics(1))
                local dst = ffi.new("void*[1]")
                local hr = createSurface(dev, sw or 0, sh or 0, D3D_A8R8G8B8, D3D_POOL_SYSTEMMEM, dst, nil)
                if hrBad(hr) or dst[0] == ffi.NULL then
                    bad[#bad + 1] = "передний буфер: CreateOffscreenPlainSurface " .. hrHex(hr)
                else
                    hr = getFrontData(dev, 0, dst[0])
                    if hrBad(hr) then
                        release(dst[0])
                        bad[#bad + 1] = "передний буфер: GetFrontBufferData " .. hrHex(hr)
                    else
                        local rc = ffi.new("grnd_shot_rect[1]")
                        local pt = ffi.new("grnd_shot_point[1]")
                        local okRc = u32.GetClientRect and pcall(u32.GetClientRect, hwnd, rc)
                        local okPt = u32.ClientToScreen and pcall(u32.ClientToScreen, hwnd, pt)
                        local rectPtr = nil
                        if okRc and okPt then
                            rc[0].left = rc[0].left + pt[0].x
                            rc[0].right = rc[0].right + pt[0].x
                            rc[0].top = rc[0].top + pt[0].y
                            rc[0].bottom = rc[0].bottom + pt[0].y
                            rectPtr = rc
                        end
                        local crop = nil
                        if rectPtr then
                            crop = { left = tonumber(rc[0].left), top = tonumber(rc[0].top),
                                right = tonumber(rc[0].right), bottom = tonumber(rc[0].bottom) }
                        end
                        local okPng, pngNote, pngPath = paShotSelfWrite(dst[0], D3D_A8R8G8B8,
                            sw or 0, sh or 0, crop, path)
                        if not okPng then
                            hr = lib.D3DXSaveSurfaceToFileW(wide, D3DXIFF_PNG, dst[0], nil, rectPtr)
                            if not hrBad(hr) then
                                release(dst[0])
                                return true, nil, string.format("передний буфер %dx%d (D3DX)", sw or 0, sh or 0)
                            end
                            pngNote = tostring(pngNote) .. "; D3DXSaveSurfaceToFile " .. hrHex(hr)
                        end
                        release(dst[0])
                        if okPng then
                            return true, nil, string.format("передний буфер: %s", tostring(pngNote)), pngPath
                        end
                        bad[#bad + 1] = "передний буфер: " .. tostring(pngNote)
                    end
                end
            end
        else
            bad[#bad + 1] = "привязка GetFrontBufferData не удалась: " .. tostring(e3)
        end
        return false, table.concat(bad, "; ")
    end
    local function paShotCleanDir(v)
        local dir = trim(tostring(v or ""))
        dir = dir:gsub('^"(.*)"$', "%1"):gsub("^'(.*)'$", "%1")
        return trim(dir)
    end
    local function paShotAbsDir(dir)
        dir = paShotCleanDir(dir)
        if dir == "" then return PA.shotDirDefault() end
        if dir:match("^%a:[/\\]") or dir:sub(1, 2) == "\\\\" or dir:sub(1, 1) == "/" then
            return dir
        end
        local wd = (type(getWorkingDirectory) == "function")
            and tostring(getWorkingDirectory() or "") or ""
        if wd == "" then return nil, "не понять, куда писать кадр" end
        return wd:gsub("[/\\]+$", "") .. SHOT_SEP .. dir
    end
    function PA.shotDirShow()
        local raw = tostring(PA.shotDir or "")
        if PA.shotDirShownRaw == raw and PA.shotDirShownVal then return PA.shotDirShownVal end
        local dir = paShotAbsDir(raw)
        dir = tostring(dir or "")
        if dir:match("^%a:") then dir = dir:gsub("/", "\\") end
        PA.shotDirShownRaw, PA.shotDirShownVal = raw, dir
        return dir
    end
    local function paShotFileDir(path)
        local dir = tostring(path or ""):match("^(.*)[/\\][^/\\]+$")
        if dir == nil or dir == "" then return nil end
        if dir:match("^%a:$") then dir = dir .. SHOT_SEP end
        return dir
    end
    local function paShotSelfTarget(name)
        local dir, why = paShotAbsDir(PA.shotDir)
        if not dir then return nil, why end
        dir = dir:gsub("[/\\]+$", "")
        paShotMkdir(dir)
        if not paShotWritable(dir) then
            return nil, "папка недоступна для записи: " .. tostring(dir)
                .. " (проверьте путь и права; для папок внутри «Program Files» нужен администратор)"
        end
        return dir .. SHOT_SEP .. name .. ".png", nil
    end
    local function paShotStartAlt(plan)
        local name = paShotName(plan.nick)
        local dir = PA.shotDirPath()
        local mod = paShotModule()
        local asi = paShotAsi()
        local viaMod = mod and type(mod.requestEx) == "function"
        local viaAsi = (not viaMod) and asi and asi.RequestScreenshotEx
        local note2 = nil
        local roots, abs = paShotRoots(dir)
        if abs then
            paShotMkdir(dir)
            if not paShotWritable(dir) then
                local user = paShotUserDir()
                if (viaMod or viaAsi) and user then
                    note2 = "своя папка недоступна, сохраняю в «App screens" .. SHOT_SEP .. "grnd»"
                    dir = "grnd"
                    roots, abs = paShotRoots(dir)
                else
                    return false, "папка недоступна для записи: " .. tostring(PA.shotDirPath())
                end
            end
        end
        plan.paths = {}
        plan.dirs = paShotSampDirs()
        plan.afterT = (os.time() or 0) - 2
        for i = 1, #roots do
            local v = paShotVariants(roots[i], name)
            for j = 1, #v do plan.paths[#plan.paths + 1] = v[j] end
        end
        plan.expect = plan.paths[1] or (dir .. SHOT_SEP .. name .. ".png")
        if viaMod or viaAsi then
            if abs then paShotMkdir(roots[1]) end
            local call = viaMod and function(fname) return mod.requestEx(dir, fname) end
                or function(fname) return asi.RequestScreenshotEx(dir, fname) end
            local function note(s)
                plan.note = (plan.note and (tostring(plan.note) .. " · ") or "") .. s
            end
            local ok, err = pcall(call, name)
            if ok then
                note(viaMod and "Screenshot.asi" or "Screenshot.asi (напрямую)")
            else
                local ok2 = pcall(call, name .. ".png")
                if not ok2 then
                    return false, "запрос плагина не удался (" .. tostring(err) .. ")"
                end
                note("Screenshot.asi (имя с .png)")
            end
        elseif mod and type(mod.request) == "function" then
            local ok, err = pcall(mod.request)
            if not ok then return false, "Screenshot.asi не отвечает: " .. tostring(err) end
            plan.note = ((plan.note and (tostring(plan.note) .. " · ")) or "") .. "Screenshot.asi (штатный кадр)"
        elseif asi and asi.RequestScreenshot then
            local ok, err = pcall(asi.RequestScreenshot)
            if not ok then return false, "Screenshot.asi не отвечает: " .. tostring(err) end
            plan.note = ((plan.note and (tostring(plan.note) .. " · ")) or "") .. "Screenshot.asi (штатный кадр, напрямую)"
        elseif paShotPressF8() then
            plan.note = ((plan.note and (tostring(plan.note) .. " · ")) or "") .. "клавиша F8"
            if #plan.dirs == 0 then plan.noWait = true end
        else
            return false, "нет Screenshot.asi" .. (PA.shotWhy and (" (" .. tostring(PA.shotWhy) .. ")") or "")
        end
        if note2 then plan.note = tostring(plan.note or "") .. " · " .. note2 end
        return true
    end
    function PA.shotRender()
        local job = PA.shotJob
        if type(job) ~= "table" then return end
        PA.shotJob = nil
        local okC, okS, why, realPath = pcall(PA.shotGrab, job.path)
        if okC and okS then
            PA.shotJobResult = { id = job.id, ok = true,
                path = (type(realPath) == "string" and realPath) or job.path,
                how = tostring(why or "") }
            return
        end
        local reason = (not okC) and ("ошибка: " .. tostring(okS)) or tostring(why)
        PA.shotJobResult = { id = job.id, fallback = true, path = job.path,
            why = "свой кадр не вышел: " .. reason }
    end
    PA.shotGrab = paShotGrabReal
    PA.shotWide = paShotWide
    PA.shotUtf8 = paShotUtf8
    PA.pngUtil = PNG
    PA.pngRows = PIX.rows
    PA.pngWrite = paShotSelfWrite
    PA.shotPathList = paShotPathList
    PA.shotFrameHook = false
    PA.shotRenderReady = false
    if type(addEventHandler) == "function" then
        PA.shotRenderReady = pcall(addEventHandler, "onD3DPresent",
            function() pcall(PA.shotRender) end) and true or false
    end
    if type(_G.grndShotHookInstall) == "function" then pcall(_G.grndShotHookInstall) end
    PA.shotSelfReady = function()
        if PA.shotFrameHook ~= true and type(_G.grndShotHookInstall) == "function" then
            pcall(_G.grndShotHookInstall)
        end
        if type(PA.shotGrab) ~= "function" then
            PA.shotSelfWhy = "нет функции съёмки"
            return false
        end
        if not paShotD3dx() then
            PA.shotSelfWhy = "не найдена библиотека d3dx9 (DirectX)"
            return false
        end
        if paShotDevice() == nil then
            PA.shotSelfWhy = "не найдено устройство D3D9 (адрес 0xC97C28)"
            return false
        end
        if PA.shotFrameHook ~= true and PA.shotRenderReady ~= true then
            PA.shotSelfWhy = "нет хука кадра (ImGui/onD3DPresent ещё не поднялся)"
            return false
        end
        return true
    end
    function PA.shotTake(nick)
        if PA.shot == false then
            return false, "выключено"
        end
        local plan = { nick = tostring(nick or ""), expect = nil, note = nil,
            paths = {}, dirs = {}, afterT = (os.time() or 0) - 2 }
        if PA.shotSelfReady() then
            local target, whySelf = paShotSelfTarget(paShotName(plan.nick))
            if target then
                plan.self = target
                plan.job = true
                plan.paths = { target }
                plan.expect = target
                plan.dir = paShotFileDir(target)
                plan.note = "свой кадр (D3D9)"
                return true, plan
            end
            plan.selfWhy = whySelf
        end
        local okA, whyA = paShotStartAlt(plan)
        if not okA then
            return false, whyA
        end
        if plan.selfWhy then
            plan.note = tostring(plan.note or "") .. " · свой кадр не вышел: " .. tostring(plan.selfWhy)
        end
        return true, plan
    end
    function PA.shotQueue(nick)
        if PA.shot == false then return false end
        PA.shotAt = os.clock() + SHOT_DELAY
        PA.shotNick = tostring(nick or "")
        return true
    end
    local function paShotReport(okFlag, last, logText)
        PA.shotLast = tostring(last or "")
        PA.shotFail = (not okFlag) or nil
        local tail = ""
        if not okFlag then
            tail = " (v" .. tostring(GRND_SCRIPT_VERSION or "?")
                .. (PA.shotSelfWhy and (", свой кадр: " .. tostring(PA.shotSelfWhy)) or "") .. ")"
        end
        PA.log((okFlag and "скриншот сохранён: " or "скриншот не сохранён: ")
            .. tostring(logText or last or "") .. tail)
        if PA.notify then
            QR.toast(okFlag and "Скриншот сохранен" or "Скриншот не сохранён",
                okFlag and "ok" or "warn", okFlag and 3.2 or 5)
        end
    end
    local function paShotFreshest(dir, afterT)
        if type(dir) ~= "string" or dir == "" then return nil end
        local lfs = libs and libs.lfs
        if not (lfs and type(lfs.dir) == "function") then return nil end
        local best, bestT, bestDir = nil, nil, nil
        for _, variant in ipairs(paShotPathList(dir)) do
            local okD, iter, obj = pcall(lfs.dir, variant)
            if okD and type(iter) == "function" then
                for file in iter, obj do
                    file = tostring(file)
                    if file ~= "." and file ~= ".."
                        and file:sub(1, #SHOT_PREFIX) == SHOT_PREFIX then
                        local full = variant .. SHOT_SEP .. file
                        local okA, t = pcall(lfs.attributes, full, "modification")
                        t = okA and tonumber(t) or nil
                        if t and t >= (tonumber(afterT) or 0) and (not bestT or t >= bestT) then
                            best, bestT, bestDir = file, t, variant
                        end
                    end
                end
            end
        end
        if best then return bestDir .. SHOT_SEP .. best end
        return nil
    end
    local function paShotFind(W)
        if type(W) ~= "table" then return nil end
        local list = {}
        if type(W.paths) == "table" then
            for i = 1, #W.paths do list[#list + 1] = W.paths[i] end
        end
        if W.self then list[#list + 1] = W.self end
        for i = 1, #list do
            if paShotExists(list[i]) then return list[i] end
        end
        local dir = W.dir or paShotFileDir(W.self or (W.paths and W.paths[1]))
        local f = paShotFreshest(dir, W.afterT or 0)
        if f and paShotExists(f) then return f end
        for i = 1, #(W.dirs or {}) do
            local g = paShotFresh(W.dirs[i], W.afterT or 0)
            if g then return g end
        end
        return nil
    end
    local function paShotClose(W, path, why)
        PA.shotWait, PA.shotJob, PA.shotJobResult = nil, nil, nil
        if path and path:sub(-8) == ".png.png" then
            local nice = path:sub(1, #path - 4)
            local okR, resR = pcall(os.rename, path, nice)
            if okR and resR == true then path = nice end
        end
        local note = trim(tostring((W and W.note) or ""))
        if path then
            paShotReport(true, path, tostring(path) .. (note ~= "" and (" (" .. note .. ")") or ""))
        else
            local target = tostring((W and (W.expect or W.self)) or "")
            local text = (target ~= "" and target or "папка кадра не задана")
                .. (note ~= "" and ("; " .. note) or "")
                .. (why and tostring(why) ~= "" and ("; " .. tostring(why)) or "")
            paShotReport(false, text, text)
        end
        return true
    end
    function PA.shotTick()
        local now = os.clock()
        local at = tonumber(PA.shotAt)
        if at and now >= at and PA.shotWait == nil then
            PA.shotAt = nil
            local nick = PA.shotNick or ""
            PA.shotNick = nil
            if PA.shot ~= false then
                local okC, r1, r2 = pcall(PA.shotTake, nick)
                if not okC then
                    paShotReport(false, "ошибка запроса", "ошибка запроса: " .. tostring(r1))
                elseif r1 == true and type(r2) == "table" then
                    local W = r2
                    PA.shotId = (PA.shotId or 0) + 1
                    W.id = PA.shotId
                    W.untilAt = now + (W.job and SHOT_JOB_WAIT or SHOT_WAIT)
                    W.selfAt = now + SHOT_JOB_WAIT
                    if not W.job then W.altTried = true end
                    if W.job and W.self then
                        PA.shotJob = { id = W.id, path = W.self }
                    end
                    PA.shotWait = W
                    if W.noWait == true then
                        paShotClose(W, nil, "проверить сохранение нечем")
                    end
                else
                    paShotReport(false, tostring(r2), tostring(r2))
                end
            end
        end
        local W = PA.shotWait
        if W == nil then return false end
        now = os.clock()
        local J = PA.shotJobResult
        if J then
            PA.shotJobResult = nil
            if tonumber(J.id) == tonumber(W.id) then
                PA.shotJob = nil
                W.job = nil
                if J.ok then
                    local how = trim(tostring(J.how or ""))
                    if how ~= "" then W.note = trim(tostring(W.note or "") .. " · " .. how) end
                    local p = tostring(J.path or W.self or "")
                    if not paShotExists(p) then
                        W.note = trim(tostring(W.note or "") .. " · файла нет после записи")
                    end
                else
                    W.note = trim(tostring(W.note or "") .. " · " .. tostring(J.why or "свой кадр не вышел"))
                    W.untilAt = now + SHOT_WAIT
                    W.altTried = true
                    paShotStartAlt(W)
                end
            end
        end
        local found = paShotFind(W)
        if found then return paShotClose(W, found) end
        if now >= (tonumber(W.untilAt) or 0) then
            if W.job and PA.shotJob and now < (tonumber(W.selfAt) or 0) then
                W.untilAt = now + 0.2
                return true
            end
            if W.job then
                W.job = nil
                PA.shotJob = nil
                W.note = trim(tostring(W.note or "") .. " · поток отрисовки не ответил")
            end
            if W.altTried ~= true then
                W.altTried = true
                local aOk, aWhy = paShotStartAlt(W)
                if not (aOk and (#(W.paths or {}) > 0 or #(W.dirs or {}) > 0)) then
                    return paShotClose(W, nil, aWhy or "запасной способ недоступен")
                end
                W.untilAt = now + SHOT_WAIT
                return true
            end
            local late = paShotFind(W)
            if late then return paShotClose(W, late) end
            local extra = {}
            if PA.shotWhy then extra[#extra + 1] = "плагин: " .. tostring(PA.shotWhy) end
            if PA.shotSelfWhy then extra[#extra + 1] = "свой кадр: " .. tostring(PA.shotSelfWhy) end
            return paShotClose(W, nil, table.concat(extra, "; "))
        end
        return true
    end
    function PA.fire(tab, trigger, info, sameEvent)
        local now = os.clock()
        local cmd = PA_FN.buildCmd(tab.cmd, info)
        if cmd == "" then
            PA.lastCheck = "во вкладке не заполнена «Команда наказания»"
            return false
        end
        if #cmd > CMD_BYTES then
            cmd = byteCut(cmd, CMD_BYTES)
            PA.lastCheck = "команда длиннее строки чата — обрезана"
        end
        if not paSend(cmd) then
            PA.lastCheck = "не удалось отправить команду"
            return false
        end
        PA.lastAt, PA.fired = now, (PA.fired or 0) + 1
        PA.shotQueue(info.nick)
        PA.lastCheck = "выдано: " .. cmd
        PA.log("выдано: " .. info.nick .. "[" .. tostring(info.pid) .. "] → " .. cmd
            .. " · триггер «" .. tostring(trigger) .. "»")
        if PA.notify then QR.toast("Автопилот: " .. cmd, "ok", 3.8) end
        return true
    end
    function PA.check(text)
        if not PA.on then
            PA.lastCheck = "Автопилот выключен"
            return false
        end
        if type(grndSessionReady) == "function" then
            local okR, ready = pcall(grndSessionReady)
            if okR and not ready then
                PA.lastCheck = "нет игровой сессии"
                return false
            end
        end
        local nick, pidHint, msg, kind = PA_FN.parseLine(text)
        PA.lastLine = PA_FN.one(PA_FN.plain(text))
        if not nick then
            PA.lastCheck = "строка не похожа на чат игрока"
            return false
        end
        if kind == "say" and PA.watchSay == false then
            PA.lastCheck = "обычный чат не отслеживается"
            return false
        end
        if kind == "shout" and PA.watchShout == false then
            PA.lastCheck = "крик не отслеживается"
            return false
        end
        if kind == "ooc" and PA.watchOoc == false then
            PA.lastCheck = "ООС не отслеживается"
            return false
        end
        local id = PA.resolve(nick, pidHint)
        if not id then
            PA.lastCheck = "«" .. nick .. "» не в сети — ID не найден"
            return false
        end
        if PA.skipSelf ~= false and id == paMyId() then
            PA.lastCheck = "это я — пропуск"
            return false
        end
        if PA.skipAdmins ~= false and PA.isAdmin(nick, id) then
            PA.lastCheck = "«" .. nick .. "» — администратор, пропуск"
            return false
        end
        local info = {
            nick = nick, pid = id, msg = msg, kind = kind,
            mynick = (type(QR.myNick) == "function") and QR.myNick() or "",
        }
        PA.normalize()
        local hits, fired = {}, 0
        for i = 1, #PA.tabs do
            local tab = PA.tabs[i]
            local hit = PA_FN.matchTab(tab, msg)
            if hit then hits[#hits + 1] = { tab = tab, hit = hit } end
        end
        for i = 1, #hits do
            local okF, res = pcall(PA.fire, hits[i].tab, hits[i].hit, info, i > 1)
            if okF and res then fired = fired + 1 end
        end
        local matched = #hits
        if matched == 0 then
            PA.lastCheck = "триггер не найден: «" .. utf8Cut(msg, 50) .. "»"
            return false
        end
        return fired > 0
    end
    function PA.onChat(text)
        if type(text) ~= "string" or text == "" then return false end
        if not PA.on then
            PA.lastCheck = "Автопилот выключен"
            return false
        end
        PA.ensure()
        local nick, _, msg = PA_FN.parseLine(text)
        local key = (nick and (paLower(paUtf(nick)) .. "|" .. tostring(msg)))
            or PA_FN.one(PA_FN.plain(text))
        local now = os.clock()
        if PA.seenKey == key and (now - (PA.seenAt or 0)) < 0.6 then return false end
        PA.seenKey, PA.seenAt = key, now
        local ok, res = pcall(PA.check, text)
        if not ok then
            PA.err = tostring(res)
            return false
        end
        return res
    end
    function PA.tick()
        PA.ensure()
        local now = os.clock()
        if PA.dirtyAt and (now - PA.dirtyAt) > 0.6 then pcall(PA.save) end
        local okShot, errShot = pcall(PA.shotTick)
        if not okShot then
            PA.err = tostring(errShot)
            PA.log("кадр: ошибка " .. tostring(errShot))
        end
        return true
    end
    _G.grndPunAutoOnChat = function(text)
        local ok, res = pcall(PA.onChat, text)
        if ok then return res end
        PA.err = tostring(res)
        return false
    end
    _G.grndPunAutoTick = function()
        local ok, res = pcall(PA.tick)
        if ok then return res end
        PA.err = tostring(res)
        return false
    end
    local function paW(ctx, text, scale)
        scale = tonumber(scale) or 1
        if type(ctx.drawnW) == "function" then
            local ok, v = pcall(ctx.drawnW, tostring(text or ""), scale)
            if ok and type(v) == "number" and v > 0 then return v end
        end
        return utf8Len(tostring(text or "")) * 7 * scale
    end
    local function paSwitch(ctx, x, y, on, id)
        local im = ctx.im
        im.SetCursorPos(im.ImVec2(x, y))
        local clicked = im.InvisibleButton(id, im.ImVec2(46, 24)) and true or false
        local hov = (im.IsItemHovered and im.IsItemHovered()) or false
        local TH = theme()
        local ac = TH.accent or { 164, 112, 224, 255 }
        local paint = _G.grndUiSwitchPaint
        if type(paint) == "function" then
            pcall(paint, { dl = ctx.dl, at = ctx.at, col32 = ctx.col32, roundRect = ctx.roundRect },
                x, y, on, hov, id, 0.05)
        else
            ctx.roundRect(ctx.dl, ctx.at(x + 1, y + 7), ctx.at(x + 45, y + 17),
                ctx.col32(255, 255, 255, on and 40 or 16), 8)
            local kx = on and (x + 29) or (x + 17)
            ctx.roundRect(ctx.dl, ctx.at(kx - 8, y + 7), ctx.at(kx + 8, y + 17),
                ctx.col32(ac[1], ac[2], ac[3], on and 235 or 120), 8)
        end
        return clicked
    end
    local function paToggle(ctx, id, x, y, on, label, box, scale)
        local im = ctx.im
        box = tonumber(box) or 18
        scale = tonumber(scale) or 0.86
        local labW = paW(ctx, label, scale)
        local w = box + 6 + labW
        im.SetCursorPos(im.ImVec2(x, y))
        local clicked = im.InvisibleButton(id, im.ImVec2(w, 24)) and true or false
        local hov = (im.IsItemHovered and im.IsItemHovered()) or false
        local TH = theme()
        local ac = TH.accent or { 164, 112, 224, 255 }
        local top = y + (24 - box) / 2
        ctx.roundRect(ctx.dl, ctx.at(x, top), ctx.at(x + box, top + box),
            on and ctx.col32(ac[1], ac[2], ac[3], 210) or ctx.col32(255, 255, 255, 14), 4)
        if ctx.dl.AddRect then
            pcall(ctx.dl.AddRect, ctx.dl, ctx.at(x + 0.5, top + 0.5), ctx.at(x + box - 0.5, top + box - 0.5),
                on and ctx.col32(ac[1], ac[2], ac[3], 255)
                    or (hov and ctx.col32(255, 255, 255, 120) or ctx.col32(255, 255, 255, 60)), 4, 0, 1)
        end
        if on and ctx.dl.AddLine then
            local k = box / 18
            pcall(ctx.dl.AddLine, ctx.dl, ctx.at(x + 4 * k, top + 9 * k), ctx.at(x + 7.5 * k, top + 13 * k),
                ctx.col32(20, 16, 26, 255), math.max(1.6, 2 * k))
            pcall(ctx.dl.AddLine, ctx.dl, ctx.at(x + 7.5 * k, top + 13 * k), ctx.at(x + 14 * k, top + 5 * k),
                ctx.col32(20, 16, 26, 255), math.max(1.6, 2 * k))
        end
        local col = on and ctx.col32(240, 236, 250, 255) or ctx.col32(198, 192, 216, 255)
        if hov then col = ctx.col32(252, 250, 255, 255) end
        ctx.uiText(x + box + 6, y + 4, label, col, scale)
        return clicked, w
    end
    local function paCircle(ctx, cx, cy, r, col)
        local dl2, at2 = ctx.dl, ctx.at
        if not (dl2 and at2) then return false end
        if dl2.AddCircleFilled and pcall(dl2.AddCircleFilled, dl2, at2(cx, cy), r, col) then
            return true
        end
        if dl2.AddCircle and pcall(dl2.AddCircle, dl2, at2(cx, cy), r, col, 16) then
            return true
        end
        if dl2.AddRectFilled then
            return pcall(dl2.AddRectFilled, dl2, at2(cx - r, cy - r), at2(cx + r, cy + r), col)
        end
        return false
    end
    local function paCross(ctx, cx, cy, r, col)
        if not ctx.dl.AddLine then return false end
        local a = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx - r, cy - r), ctx.at(cx + r, cy + r), col, 1.4)
        local b = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx + r, cy - r), ctx.at(cx - r, cy + r), col, 1.4)
        return a and b
    end
    local function paPlus(ctx, cx, cy, r, col)
        if not ctx.dl.AddLine then return false end
        local a = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx - r, cy), ctx.at(cx + r, cy), col, 1.6)
        local b = pcall(ctx.dl.AddLine, ctx.dl, ctx.at(cx, cy - r), ctx.at(cx, cy + r), col, 1.6)
        return a and b
    end
    local function paHint(ctx, x, y, w, text, col, maxLines)
        local lines = wrapW(text, w, ctx.drawnW, 0.72)
        local n = math.min(#lines, tonumber(maxLines) or #lines)
        for i = 1, n do
            ctx.uiText(x, y + (i - 1) * (lineH(ctx, 0.72) + 2), lines[i], col, 0.72)
        end
        return n * (lineH(ctx, 0.72) + 2)
    end
    function QR.punAutoDraw(ctx)
        if type(ctx) ~= "table" then return false end
        local im = ctx.im
        if not (im and ctx.uiText and ctx.roundRect and ctx.col32 and ctx.rgba and ctx.at) then
            return false
        end
        PA.ensure()
        local TH = theme()
        local x, y, w, h = ctx.x, ctx.y, ctx.w, ctx.h
        if not (x and y and w and h) or w < 320 or h < 190 then return false end
        local hi   = ctx.col32(TH.textHi[1], TH.textHi[2], TH.textHi[3], 255)
        local dim  = ctx.col32(TH.textDim[1], TH.textDim[2], TH.textDim[3], 255)
        local mut  = ctx.col32(TH.textMuted[1], TH.textMuted[2], TH.textMuted[3], 255)
        local ac   = TH.accent or { 164, 112, 224, 255 }
        local acC  = ctx.col32(ac[1], ac[2], ac[3], 255)
        local warnC = ctx.col32(255, 176, 96, 255)
        local bottomY = y + h - 4
        local ROW, BLOCK = 28, 12
        local LABEL = 0.82
        local TEXT = 0.72
        ctx.uiText(x, y + 1, "Автопилот наказаний", hi, 0.98)
        local swX = x + w - 46
        if paSwitch(ctx, swX, y + 2, PA.on, "##grnd_pa_switch") then PA.set(not PA.on) end
        local tabH, tgap, tcw = 28, 6, 24
        local tabW = math.floor((w - tgap * math.max(0, #PA.tabs - 1)) / math.max(1, #PA.tabs))
        if tabW > 180 then tabW = 180 end
        if tabW < 96 then tabW = 96 end
        local tx, ty = x, y + 30
        local delIdx = nil
        for i = 1, #PA.tabs do
            if tx + tabW > x + w + 0.5 then tx, ty = x, ty + tabH + tgap end
            local sel = (i == PA.sel)
            im.SetCursorPos(im.ImVec2(tx, ty))
            local tabClick = im.InvisibleButton("##grnd_pa_tab_" .. i,
                im.ImVec2(tabW - tcw, tabH)) and true or false
            local tabHov = (im.IsItemHovered and im.IsItemHovered()) or false
            im.SetCursorPos(im.ImVec2(tx + tabW - tcw, ty))
            local crossClick = im.InvisibleButton("##grnd_pa_tabc_" .. i,
                im.ImVec2(tcw, tabH)) and true or false
            local crossHov = (im.IsItemHovered and im.IsItemHovered()) or false
            local hov = tabHov or crossHov
            ctx.roundRect(ctx.dl, ctx.at(tx, ty), ctx.at(tx + tabW, ty + tabH),
                sel and ctx.col32(ac[1], ac[2], ac[3], 52)
                    or (hov and ctx.col32(255, 255, 255, 22) or ctx.col32(255, 255, 255, 12)), 6)
            if ctx.dl.AddRect then
                pcall(ctx.dl.AddRect, ctx.dl, ctx.at(tx + 0.5, ty + 0.5),
                    ctx.at(tx + tabW - 0.5, ty + tabH - 0.5),
                    sel and ctx.col32(ac[1], ac[2], ac[3], 170) or ctx.col32(255, 255, 255, 46), 6, 0, 1)
            end
            local lbl = fit(PA.tabLabel(i), tabW - tcw - 12, ctx.drawnW, 0.88)
            local lw = paW(ctx, lbl, 0.88)
            ctx.uiText(tx + math.floor((tabW - tcw - lw) / 2), ty + (tabH - lineH(ctx, 0.88)) / 2, lbl,
                sel and hi or dim, 0.88)
            local crossCol = crossHov and ctx.col32(255, 140, 140, 255) or ctx.col32(255, 255, 255, 110)
            if not paCross(ctx, tx + tabW - tcw / 2, ty + tabH / 2, 4, crossCol) then
                ctx.uiText(tx + tabW - tcw / 2 - 3, ty + (tabH - lineH(ctx, 0.8)) / 2, "x", crossCol, 0.8)
            end
            if crossClick then
                delIdx = i
            elseif tabClick and not sel then
                PA.sel = i
                PA.touch()
            end
            tx = tx + tabW + tgap
        end
        do
            local plusD = tabH
            if tx + plusD > x + w + 0.5 then tx, ty = x, ty + tabH + tgap end
            im.SetCursorPos(im.ImVec2(tx, ty))
            local plusClick = im.InvisibleButton("##grnd_pa_add", im.ImVec2(plusD, plusD)) and true or false
            local plusHov = (im.IsItemHovered and im.IsItemHovered()) or false
            local pcx, pcy = tx + plusD / 2, ty + plusD / 2
            paCircle(ctx, pcx, pcy, plusD / 2, ctx.col32(ac[1], ac[2], ac[3], plusHov and 90 or 46))
            paCircle(ctx, pcx, pcy, plusD / 2 - 1.5, ctx.col32(18, 17, 23, plusHov and 150 or 90))
            if not paPlus(ctx, pcx, pcy, 6,
                plusHov and ctx.col32(255, 255, 255, 255) or ctx.col32(ac[1], ac[2], ac[3], 235)) then
                ctx.uiText(pcx - 4, pcy - lineH(ctx, 1.0) / 2, "+", plusHov and hi or acC, 1.0)
            end
            if plusClick then PA.tabAdd() end
        end
        if delIdx then PA.tabDel(delIdx) return true end
        local tab = PA.tab()
        local twoCol = (w >= 620)
        local colGap = 22
        local colW1 = twoCol and math.floor((w - colGap) * 0.54) or w
        local colW2 = twoCol and (w - colW1 - colGap) or w
        local c1X = x
        local c2X = twoCol and (x + colW1 + colGap) or x
        local rowY = ty + tabH + 16
        local yy1, yy2 = rowY, rowY
        local function label(yy, cx, text)
            ctx.uiText(cx, yy, text, dim, LABEL)
            return yy + 15
        end
        if yy1 + 15 + ROW <= bottomY then
            yy1 = label(yy1, c1X, "Триггеры (можно несколько через запятую)")
            local tkey = "paTrig" .. PA.sel
            field(ctx, "##grnd_pa_trigger", tkey, TRIG_CAP, c1X, yy1, colW1, ROW,
                "дм, dm", false, tab.trigger)
            local tv = trim(bufText(tkey))
            if tv ~= tab.trigger then
                tab.trigger = clampText(oneLine(utf(tv)), MAX_PTRIG)
                PA.touch()
            end
            yy1 = yy1 + ROW + BLOCK
        end
        if yy1 + 15 + ROW <= bottomY then
            yy1 = label(yy1, c1X, "Команда наказания")
            local ckey = "paCmd" .. PA.sel
            field(ctx, "##grnd_pa_cmd", ckey, CMD_CAP, c1X, yy1, colW1, ROW,
                "/mute 60 2.1 ОП", false, tab.cmd)
            local cv = trim(bufText(ckey))
            if cv ~= tab.cmd then
                tab.cmd = clampText(oneLine(utf(cv)), MAX_PCMD)
                PA.touch()
            end
            yy1 = yy1 + ROW + 6
            yy1 = yy1 + paHint(ctx, c1X, yy1, colW1,
                "ID игрока подставляется сам: /mute 60 2.1 ОП → /mute 7 60 2.1 ОП", mut, 2)
            yy1 = yy1 + BLOCK
        end
        if yy1 + 24 <= bottomY then
            if paToggle(ctx, "##grnd_pa_shot", c1X, yy1, PA.shot ~= false,
                "скриншот после выдачи", 18, LABEL) then
                PA.shot = not (PA.shot ~= false)
                PA.touch()
                pcall(PA.save)
                QR.toast(PA.shot and "Скриншот после выдачи включён"
                    or "Скриншот после выдачи выключен", PA.shot and "ok" or "warn", 2.6)
            end
            yy1 = yy1 + 28
        end
        if PA.shot ~= false and yy1 + 15 + ROW <= bottomY then
            yy1 = label(yy1, c1X, "Папка для скриншотов")
            field(ctx, "##grnd_pa_shotdir", "paShotDir", SHOT_MAXDIR * 2 + 1, c1X, yy1, colW1, ROW,
                "resource\\grnd\\screenshots", false, PA.shotDir or "")
            local sv = trim(bufText("paShotDir"))
            if sv ~= (PA.shotDir or "") then
                PA.shotDir = clampText(oneLine(utf(sv)), SHOT_MAXDIR)
                PA.touch()
            end
            yy1 = yy1 + ROW + BLOCK
        end
        if not twoCol then yy2 = yy1 + BLOCK end
        if yy2 + 15 + ROW <= bottomY then
            yy2 = label(yy2, c2X, "Режим поиска")
            local items = {
                { id = "word",  name = "В любом месте" },
                { id = "exact", name = "Точное совпадение" },
            }
            local bw = math.floor((colW2 - 8) / 2)
            for i = 1, #items do
                if button(ctx, "##grnd_pa_mode_" .. items[i].id, c2X + (i - 1) * (bw + 8), yy2,
                    bw, ROW, items[i].name, { selected = (tab.mode == items[i].id) }) then
                    tab.mode = items[i].id
                    PA.touch()
                    pcall(PA.save)
                end
            end
            yy2 = yy2 + ROW + BLOCK
        end
        if yy2 + 15 <= bottomY then
            yy2 = yy2 + paHint(ctx, c2X, yy2, colW2,
                "Задержек нет: строка выдаёт наказание сразу.", mut, 1)
            yy2 = yy2 + BLOCK
        end
        do
            local stY = math.max(yy1, yy2)
            local msg
            if PA.err then
                msg = "Ошибка: " .. tostring(PA.err)
            elseif PA.shotFail and PA.shotLast then
                msg = "Кадр не сохранён: " .. tostring(PA.shotLast)
            end
            if msg and stY + lineH(ctx, TEXT) <= bottomY then
                ctx.uiText(x, stY, fit(msg, w, ctx.drawnW, TEXT), warnC, TEXT)
            end
        end
        QR.punAutoErr = nil
        return true
    end
end
function QR.selfTest()
    local fails = {}
    local function eq(name, got, exp)
        if tostring(got) ~= tostring(exp) then
            fails[#fails + 1] = name .. " got=" .. tostring(got) .. " exp=" .. tostring(exp)
        end
    end
    eq("oneLine", oneLine("а\nб\r\nв"), "а б в")
    eq("trim", trim("  тест  "), "тест")
    eq("cleanText", cleanText("а  \r\n\r\nб\r\n"), "а\n\nб")
    eq("apply", QR.apply("Привет, {ник}[{id}]!", { nick = "Игрок", id = "5" }),
        "Привет, Игрок[5]!")
    eq("applyEmpty", QR.apply("Привет, {ник}!", {}), "Привет, {ник}!")
    eq("cut", utf8Cut("привет", 3), "при")
    eq("utf8Len", utf8Len("привет"), 6)
    eq("byteCut", byteCut("привет", 7), "при")
    local sample = "строка 1\nстрока 2 \\ назад"
    eq("esc", unesc(esc(sample)), sample)
    local msg
    if #fails == 0 then
        msg = "Шаблоны ответов: проверка пройдена"
        print("{00FFAA}[GRND]{FFFFFF} " .. msg)
    else
        msg = "Шаблоны ответов: ошибок " .. tostring(#fails)
        print("{FF6666}[GRND]{FFFFFF} " .. msg .. " | " .. table.concat(fails, " | "))
    end
    return #fails == 0
end
return QR
end)()
function QR_PATH()
    local QRm = _G.GRND_QR
    if QRm and type(QRm.path) == "function" then
        local ok, v = pcall(QRm.path)
        if ok and type(v) == "string" and v ~= "" then return v end
    end
    return "grnd.cfg"
end
do
    local RT = {
        radius = 25,
        RMIN = 1, RMAX = 200,
        visible = false,
        list = nil,
        scanAt = 0,
        err = nil,
        lastAct = nil,
        loaded = false,
        clock = os.clock,
        queue = nil,
    }
    local RT_FN = {}
    function RT_FN.dist(ax, ay, az, bx, by, bz)
        local dx, dy, dz = bx - ax, by - ay, bz - az
        return math.sqrt(dx * dx + dy * dy + dz * dz)
    end
    function RT_FN.scan(raw, my, radius)
        local out = {}
        if type(raw) ~= "table" or type(my) ~= "table" then return out end
        for i = 1, #raw do
            local p = raw[i]
            if p ~= nil and p.self ~= true
                and type(p) == "table" and p.x and p.y and p.z
                and my.x and my.y and my.z then
                local same = true
                if my.interior ~= nil and p.interior ~= nil
                    and my.interior ~= p.interior then same = false end
                if same and my.zd ~= nil and p.zd ~= nil
                    and my.zd ~= p.zd then same = false end
                if same then
                    local d = RT_FN.dist(my.x, my.y, my.z, p.x, p.y, p.z)
                    if d <= radius then
                        out[#out + 1] = {
                            id = p.id,
                            nick = tostring(p.nick or ("#" .. tostring(p.id))),
                            dist = d, x = p.x, y = p.y, z = p.z,
                            self = p.self == true,
                            interior = p.interior, zd = p.zd,
                        }
                    end
                end
            end
        end
        table.sort(out, function(a, b) return a.dist < b.dist end)
        return out
    end
    function RT_FN.fill(tmpl, p)
        local s = tostring(tmpl or "")
        local function put(k, v)
            s = s:gsub(k, (tostring(v):gsub("%%", "%%%%")))
        end
        put("{id}", p and p.id or "")
        put("{ник}", p and p.nick or "")
        put("{nick}", p and p.nick or "")
        local d = (p and p.dist) and math.floor(p.dist + 0.5) or ""
        put("{дист}", d)
        put("{dist}", d)
        return s
    end
    RT.fn = RT_FN
    RT.actions = {
        { id = "spawn",    label = "Заспавнить",           level = 2, per = true },
