        { id = 35, name = "РПГ" },
        { id = 36, name = "Ракетница HS" },
        { id = 37, name = "Огнемёт" },
        { id = 38, name = "Миниган" },
        { id = 39, name = "C4" },
        { id = 41, name = "Баллончик" },
