    }
    RT.settingsOpen = nil
    function RT.actById(id)
        for i = 1, #RT.actions do
            if RT.actions[i].id == id then return RT.actions[i] end
        end
        if RT.wide and RT.wide.id == id then return RT.wide end
        return nil
    end
    function RT.path()
        local dir = tostring(QR_PATH() or ""):match("^(.*[/\\])")
        if dir then return dir .. "grnd_radtools.cfg" end
        return "grnd_radtools.cfg"
    end
    function RT.setRadius(n)
        n = math.floor(tonumber(n) or RT.radius)
        if n < RT.RMIN then n = RT.RMIN end
        if n > RT.RMAX then n = RT.RMAX end
        if n ~= RT.radius then
            RT.radius = n
            RT.list = nil
            RT.scanAt = 0
            pcall(RT.save)
        end
        return RT.radius
    end
    function RT.load()
        if RT.loaded then return true end
        RT.loaded = true
        local ok, f = pcall(GRND_CONFIG.open, RT.path(), "r")
        if ok and f then
            for line in f:lines() do
                local k, v = tostring(line or ""):match("^([%w_]+)=(.*)$")
                if k == "radius" then RT.setRadius(v) end
                if k == "wsel" then RT.settings.weapon.sel = v end
                if k == "wammo" then RT.settings.weapon.ammo = v end
                if k == "skin" then RT.settings.skin.num = v end
                if k == "armor" then RT.settings.armor.amount = v end
                if k == "vmode" then RT.settings.vehicle.mode = v end
            end
        end
        RT.clampSettings()
        return true
    end
    function RT.clampSettings()
        local S = RT.settings
        S.weapon.sel = math.floor(tonumber(S.weapon.sel) or 1)
        if S.weapon.sel < 1 then S.weapon.sel = 1 end
        if S.weapon.sel > #RT.weapons then S.weapon.sel = #RT.weapons end
        S.weapon.ammo = math.floor(tonumber(S.weapon.ammo) or 30)
        if S.weapon.ammo < 1 then S.weapon.ammo = 1 end
        if S.weapon.ammo > 999 then S.weapon.ammo = 999 end
        S.skin.num = tostring(S.skin.num or "")
        S.armor.amount = math.floor(tonumber(S.armor.amount) or 50)
        if S.armor.amount < 1 then S.armor.amount = 1 end
        if S.armor.amount > 100 then S.armor.amount = 100 end
        S.vehicle.mode = math.floor(tonumber(S.vehicle.mode) or 1)
        if S.vehicle.mode < 1 then S.vehicle.mode = 1 end
        if S.vehicle.mode > 3 then S.vehicle.mode = 3 end
    end
    function RT.save()
        RT.clampSettings()
        local ok, f = pcall(GRND_CONFIG.open, RT.path(), "w")
        if not ok or not f then return false end
        local S = RT.settings
        f:write("radius=" .. tostring(RT.radius) .. "\n")
        f:write("wsel=" .. S.weapon.sel .. "\n")
        f:write("wammo=" .. S.weapon.ammo .. "\n")
        f:write("skin=" .. S.skin.num .. "\n")
        f:write("armor=" .. S.armor.amount .. "\n")
        f:write("vmode=" .. S.vehicle.mode .. "\n")
        return true
    end
    local function rtNum(v)
        return (type(v) == "number" and v == v and math.abs(v) < 1e6) and v or nil
    end
    local function rtEntityIz(ped)
        if type(ffi) ~= "table" then return nil, nil end
        local ok, a, b = pcall(function()
            return ffi.cast("int*", ped + 0x58)[0], ffi.cast("short*", ped + 0x5A)[0]
        end)
        if ok and type(a) == "number" and type(b) == "number" then return a, b end
        return nil, nil
    end
    local function rtSelf()
        local ped = _G.PLAYER_PED or _G.playerPed
        if not ped then return nil end
        local id
        if type(sampGetPlayerIdByCharHandle) == "function" then
            local ok, v = pcall(sampGetPlayerIdByCharHandle, ped)
            if ok and type(v) == "number" and v >= 0 then id = v end
        end
        local ok, x, y, z = pcall(getCharCoordinates, ped)
        if not (ok and rtNum(x) and rtNum(y) and rtNum(z)) then return nil end
        local interior
        if type(getActiveInterior) == "function" then
            local ok2, v2 = pcall(getActiveInterior)
            if ok2 and type(v2) == "number" then interior = v2 end
        end
        local pedInt, zd = rtEntityIz(ped)
        if interior == nil then interior = pedInt end
        local nick
        if id and type(sampGetPlayerNickname) == "function" then
            local ok3, n3 = pcall(sampGetPlayerNickname, id)
            if ok3 and type(n3) == "string" then nick = n3 end
        end
        return id, rtNum(x), rtNum(y), rtNum(z), interior, zd, nick
    end
    function RT.rawPlayers(myId)
        if type(sampIsPlayerConnected) ~= "function" then
            RT.err = "нет подключения к SAMP-серверу"
            return nil
        end
        local out = {}
        for id = 0, 1003 do
            local ok, conn = pcall(sampIsPlayerConnected, id)
            if ok and conn then
                local nick
                if type(sampGetPlayerNickname) == "function" then
                    local ok2, n2 = pcall(sampGetPlayerNickname, id)
                    if ok2 and type(n2) == "string" and n2 ~= "" then nick = n2 end
                end
                local x, y, z, interior, zd
                local rok, res, ped = pcall(sampGetCharHandleBySampPlayerId, id)
                if rok and res and ped then
                    local cok, cx, cy, cz = pcall(getCharCoordinates, ped)
                    if cok and rtNum(cx) and rtNum(cy) and rtNum(cz) then
                        x, y, z = rtNum(cx), rtNum(cy), rtNum(cz)
                        interior, zd = rtEntityIz(ped)
                    end
                end
                if not x and type(sampGetStreamedOutPlayerPos) == "function" then
                    local sok, sx, sy, sz = pcall(sampGetStreamedOutPlayerPos, id)
                    if sok and rtNum(sx) and rtNum(sy) and rtNum(sz) then
                        x, y, z = rtNum(sx), rtNum(sy), rtNum(sz)
                    end
                end
                out[#out + 1] = {
                    id = id, nick = nick, x = x, y = y, z = z,
                    interior = interior, zd = zd,
                    self = (myId ~= nil and id == myId),
                }
            end
        end
        return out
    end
    function RT.scan()
        pcall(RT.load)
        local myId, mx, my, mz, mi, md = rtSelf()
        if not mx then
            RT.err = "не удалось получить ваши координаты"
            RT.list = nil
            return nil
        end
        local raw = RT.rawPlayers(myId)
        if not raw then
            RT.list = nil
            return nil
        end
        RT.list = RT_FN.scan(raw,
            { x = mx, y = my, z = mz, interior = mi, zd = md }, RT.radius)
        RT.scanAt = os.clock()
        RT.err = nil
        return RT.list
    end
    function RT.tick()
        pcall(RT.load)
        RT.pumpQueue()
        local AO = _G.GRND_AO
        local now = os.clock()
        if type(AO) == "table" and AO.enabled == false and not RT.levelFresh()
            and now >= (RT.levelProbeAt or 0) then
            pcall(RT.refreshLevels)
            RT.levelProbeAt = now + 8
        end
        if RT.visible and (RT.list == nil or now - (RT.scanAt or 0) >= 1) then
            RT.scan()
        end
    end
    local function rtSend(cmd)
        cmd = tostring(cmd or "")
        if cmd == "" then return false end
        local QRm = _G.GRND_QR
        if QRm and type(QRm.sendChat) == "function" then
            local ok, res = pcall(QRm.sendChat, cmd)
            if ok and res ~= false then return true end
        end
        if type(grndChatSend) == "function" then
            local ok, res = pcall(grndChatSend, cmd)
            if ok and res ~= false then return true end
        end
        if type(sampSendChat) == "function" then
            local out = cmd
            if type(grndAnsiText) == "function" then
                local okA, ansi = pcall(grndAnsiText, cmd)
                if okA and type(ansi) == "string" and ansi ~= "" then out = ansi end
            end
            return pcall(sampSendChat, out) and true or false
        end
        return false
    end
    local function rtToast(text, kind, t)
        local QRm = _G.GRND_QR
        if QRm and type(QRm.toast) == "function" then
            local ok = pcall(QRm.toast, text, kind or "info", t or 3)
            if ok then return end
        end
        pcall(print, text)
    end
    local function rtNickKey(st)
        st = tostring(st or ""):gsub("{[%x]+}", ""):gsub("%[%d+%]", "")
        return st:lower():gsub("[%s_%p]", "")
    end
    function RT.checker()
        local AO = _G.GRND_AO
        if type(AO) ~= "table" then return "off" end
        if AO.enabled == false then return "off" end
        return "on"
    end
    function RT.rememberLevel(n, nick)
        n = tonumber(n)
        if not n then return end
        RT.lvlSeen = { value = math.floor(n), nick = nick, at = os.clock() }
    end
    function RT.myLevel()
        local AO = _G.GRND_AO
        local list = (type(AO) == "table") and AO.list or nil
        local myId, myNick, idSource
        local now = os.clock()
        local tabIdFn = rawget(_G, "grndTabFirstLocalId")
        local tabCache = RT.tabIdCache
        if type(tabCache) == "table" and now >= (tabCache.at or 0)
            and now - tabCache.at <= 1 then
            if tabCache.id then myId, idSource = tabCache.id, "tab" end
        else
            local tabId
            if type(tabIdFn) == "function" then
                local okTab, result = pcall(tabIdFn)
                tabId = okTab and tonumber(result) or nil
            end
            if tabId and tabId >= 0 and tabId < 1004 and tabId == math.floor(tabId) then
                myId, idSource = tabId, "tab"
            end
            RT.tabIdCache = { id = myId, at = now }
        end
        if not myId and type(sampGetLocalPlayerId) == "function" then
            local okId, a, b = pcall(sampGetLocalPlayerId)
            local localId = okId and (type(a) == "number" and a
                or (a and type(b) == "number" and b)) or nil
            if localId and localId >= 0 and localId < 1004 then
                myId, idSource = math.floor(localId), "id"
            end
        end
        if not myId then
            local _, selfId, _, _, _, _, _, selfNick = pcall(rtSelf)
            if type(selfId) == "number" and selfId >= 0 and selfId < 1004 then
                myId, idSource, myNick = math.floor(selfId), "id", selfNick
            end
        end
        if myId and type(sampGetPlayerNickname) == "function" then
            local okNick, nick = pcall(sampGetPlayerNickname, myId)
            if okNick and type(nick) == "string" and nick ~= "" then myNick = nick end
        end
        if type(list) == "table" then
            if myId then
                for i = 1, #list do
                    local it = list[i]
                    if type(it) == "table" and tonumber(it.id) == myId then
                        local n = tonumber(it.lvl)
                        if n then
                            RT.rememberLevel(n, it.nick)
                            return n, idSource or "id"
                        end
                    end
                end
            end
            local myKey = rtNickKey(myNick)
            if myKey ~= "" then
                for i = 1, #list do
                    local it = list[i]
                    if type(it) == "table" and it.nick then
                        local k = rtNickKey(it.nick)
                        if k ~= "" and k == myKey then
                            local n = tonumber(it.lvl)
                            if n then
                                RT.rememberLevel(n, it.nick)
                                return n, "nick"
                            end
                        end
                    end
                end
            end
        end
        return nil, (RT.checker() == "off") and "off" or "none"
    end
    function RT.levelFresh()
        local AO = _G.GRND_AO
        local parsedAt = type(AO) == "table" and tonumber(AO.parsedAt) or nil
        local now = os.clock()
        return parsedAt ~= nil and now >= parsedAt and now - parsedAt <= 60
    end
    function RT.refreshLevels(force)
        local AO = _G.GRND_AO
        if type(AO) ~= "table" then
            return false, "чекер «Админы в сети» не загружен"
        end
        local now = os.clock()
        if not force and RT.lvlAskAt and (now - RT.lvlAskAt) < 4 then
            return false, "уже запрашиваю"
        end
        RT.lvlAskAt = now
        local request = rawget(_G, "grndAoRequestLevels")
        if type(request) ~= "function" then
            return false, "не удалось запросить /admins"
        end
        local ok, sent = pcall(request)
        if not ok or not sent then return false, "не удалось запросить /admins" end
        AO.nextAt = 0
        return true, "получаю свежие данные /admins"
    end
    function RT.cmdFor(id, p)
        local S = RT.settings
        local s = tostring(p and p.id or "")
        if id == "spawn" then return "/spawn " .. s end
        if id == "freeze" then return "/freeze " .. s end
        if id == "unfreeze" then return "/unfreeze " .. s end
        if id == "weapon" then
            local w = RT.weapons[S.weapon.sel] or RT.weapons[1]
            return string.format("/gun %s %d %d", s, w.id, S.weapon.ammo)
        end
        if id == "skin" then
            local sk = tonumber(S.skin.num)
            if not sk then return nil end
            return "/setskin " .. s .. " " .. tostring(math.floor(sk))
        end
        if id == "armor" then
            return string.format("/arm %s %d", s, S.armor.amount)
        end
        if id == "hp" then return "/hpall" end
        if id == "vehicle" then
            return "/spcars " .. tostring(S.vehicle.mode)
        end
        if id == "takeoff" then return "/weapall" end
        if id == "tpself" then return "/gethere " .. s end
        if id == "freezeall" then return "/freezeall" end
        if id == "unfreezeall" then return "/unfreezeall" end
        if id == "armall" then
            return string.format("/armall %d %d", S.armor.amount, RT.radius)
        end
        if id == "gunall" then
            local w = RT.weapons[S.weapon.sel] or RT.weapons[1]
            return string.format("/gunall %d %d %d", w.id, S.weapon.ammo,
                RT.radius)
        end
        return nil
    end
    function RT.gearClick(a)
        if RT.settings[a.id] then
            RT.settingsOpen = a.id
            RT.lastAct = a.label .. ": настройки"
        end
    end
    local function rtQueueFinish(Q)
        local names = {}
        for i = 1, math.min(4, #Q.names) do names[i] = Q.names[i] end
        if #Q.names > 4 then names[#names + 1] = "…" end
        RT.lastAct = string.format("%s: %d/%d (%s)", Q.label, Q.sent, #Q.cmds,
            table.concat(names, ", "))
        if Q.sent > 0 and Q.failed == 0 then
            rtToast(string.format("%s: %d игрокам", Q.label, Q.sent), "ok", 3)
            return true
        elseif Q.sent > 0 then
            rtToast(string.format("%s: только %d из %d", Q.label, Q.sent,
                #Q.cmds), "warn", 3.2)
            return false
        end
        rtToast("Не удалось отправить команды", "warn", 3)
        return false
    end
    function RT.pumpQueue()
        local Q = RT.queue
        if type(Q) ~= "table" or type(Q.cmds) ~= "table" then return end
        local now = RT.clock()
        if now >= Q.at and Q.i < #Q.cmds then
            local ok = rtSend(Q.cmds[Q.i + 1])
            Q.i = Q.i + 1
            if ok then Q.sent = Q.sent + 1 else Q.failed = Q.failed + 1 end
            Q.at = now + 0.15
            local names = {}
            for i = 1, math.min(4, #Q.names) do names[i] = Q.names[i] end
            if #Q.names > 4 then names[#names + 1] = "…" end
            RT.lastAct = string.format("%s: %d/%d (%s)", Q.label, Q.i,
                #Q.cmds, table.concat(names, ", "))
        end
        if Q.i >= #Q.cmds then
            RT.queue = nil
            rtQueueFinish(Q)
        end
    end
    function RT.doAction(id)
        pcall(RT.load)
        local act = RT.actById(id)
        if not act then return false end
        local lv
        if act.level and act.level > 0 then
            local levelSource
            lv, levelSource = RT.myLevel()
            if not RT.levelFresh()
                or (levelSource ~= "tab" and levelSource ~= "id" and levelSource ~= "nick") then
                lv = nil
            end
            if lv and lv < act.level then
                rtToast("Нет доступа к данной команде, нужен "
                    .. tostring(act.level) .. "-й уровень", "warn", 3.5)
                RT.lastAct = string.format(
                    "%s: нет доступа (уровень %d, нужен %d-й)",
                    act.label, lv, act.level)
                return false
            end
            if not lv then
                local _, why = RT.refreshLevels()
                rtToast("Уровень не определён (" .. tostring(why)
                    .. ") — нужен " .. tostring(act.level) .. "-й уровень",
                    "warn", 4.2)
                RT.lastAct = string.format("%s: уровень не определён (%s)",
                    act.label, tostring(why))
                return false
            end
        end
        if lv and lv >= 5 and RT.MASS[id] then
            local mass = RT.MASS[id]
            if RT.MASS_RADIUS[mass] and RT.radius > RT.RADIUS_MAX then
                rtToast("Выберите радиус не больше " .. RT.RADIUS_MAX,
                    "warn", 3.5)
                RT.lastAct = string.format("%s: радиус %d выше предела %d",
                    act.label, RT.radius, RT.RADIUS_MAX)
                return false
            end
            local cmd = RT.cmdFor(mass, nil)
            if not cmd then
                rtToast("«" .. act.label .. "»: команда не собрана", "warn", 3)
                RT.lastAct = act.label .. ": команда не собрана"
                return false
            end
            if rtSend(cmd) then
                rtToast("«" .. act.label .. "»: отправлено (" .. cmd .. ")",
                    "ok", 3)
                RT.lastAct = act.label .. ": отправлено (" .. cmd .. ")"
                return true
            end
            rtToast("Не удалось отправить команду", "warn", 3)
            RT.lastAct = act.label .. ": не удалось отправить"
            return false
        end
        if act.solo then
            local cmd = RT.cmdFor(id, nil)
            if not cmd then
                RT.lastAct = act.label .. ": команда не собрана"
                rtToast("«" .. act.label .. "»: команда не собрана", "warn", 3)
                return false
            end
            if rtSend(cmd) then
                RT.lastAct = act.label .. ": отправлено (" .. cmd .. ")"
                rtToast("«" .. act.label .. "»: отправлено", "ok", 2.8)
                return true
            end
            RT.lastAct = act.label .. ": не удалось отправить"
            rtToast("Не удалось отправить команду", "warn", 3)
            return false
        end
        if act.per then
            local list = RT.scan()
            if not list then
                rtToast("Радиус: " .. tostring(RT.err or "нет данных"),
                    "warn", 3)
                RT.lastAct = act.label .. ": " .. tostring(RT.err or "нет данных")
                return false
            end
            local cmds, names = {}, {}
            for i = 1, #list do
                local pl = list[i]
                if not (act.skipSelf and pl.self) then
                    local c = RT.cmdFor(id, pl)
                    if not c then
                        rtToast("«" .. act.label .. "»: сначала заполните "
                            .. "настройки (шестерёнка)", "warn", 3.2)
                        RT.lastAct = act.label .. ": настройка не заполнена"
                        return false
                    end
                    cmds[#cmds + 1] = c
                    names[#names + 1] = pl.nick
                end
            end
            if #cmds == 0 then
                rtToast("В радиусе " .. RT.radius .. " м никого", "info", 2.4)
                RT.lastAct = act.label .. ": в радиусе никого"
                return false
            end
            RT.queue = {
                cmds = cmds, names = names, label = act.label,
                i = 0, sent = 0, failed = 0, at = RT.clock(),
            }
            local nn = {}
            for i = 1, math.min(4, #names) do nn[i] = names[i] end
            if #names > 4 then nn[#nn + 1] = "…" end
            RT.lastAct = string.format("%s: 0/%d (%s)", act.label, #cmds,
                table.concat(nn, ", "))
            rtToast(string.format("«%s»: выдаю %d игрокам, по одной за "
                .. "150 мс", act.label, #cmds), "info", 2.6)
            return true
        end
        rtToast("«" .. act.label .. "»: команда ещё не назначена", "warn", 3.2)
        RT.lastAct = act.label .. ": команда ещё не назначена"
        return false
    end
    local function rtSettingsPage(R, cx, y, cw)
        local TH = (type(R.theme) == "function") and R.theme() or {}
        local S = RT.settings
        local key = RT.settingsOpen
        local mut = R.c4(TH.textMuted or { 140, 140, 150, 255 })
        local hi  = R.c4(TH.textHi or { 240, 240, 245, 255 })
        local ac  = (type(TH.accent) == "table") and TH.accent
            or { 164, 112, 224, 255 }
        local titles = {
            weapon = "ОРУЖИЕ", skin = "СКИН",
            armor = "БРОНЯ", vehicle = "ТРАНСПОРТ",
        }
        local rowH = 46
        local body = (key == "weapon") and (rowH * 2)
            or ((key == "skin") and 52 or rowH)
        local boxH = 60 + body + 16
        R.roundRect(R.dl, R.at(cx, y), R.at(cx + cw, y + boxH),
            R.col32(14, 15, 22, 245), 8)
        if type(R.frameRect) == "function" then
            R.frameRect(cx + 0.5, y + 0.5, cx + cw - 0.5, y + boxH - 0.5,
                R.col32(ac[1], ac[2], ac[3], 180), 8, 1)
        end
        local ix, iw = cx + 12, cw - 24
        R.uiText(ix, y + 10, "НАСТРОЙКА: " .. (titles[key] or key), hi, 0.92)
        R.uiText(ix, y + 31, "Применяется к игрокам в радиусе", mut, 0.78)
        if R.button("rt_set_close", cx + cw - 96, y + 9, 84, 26,
            "Закрыть", {}) then
            RT.settingsOpen = nil
        end
        R.roundRect(R.dl, R.at(ix, y + 51), R.at(ix + iw, y + 53),
            R.col32(255, 255, 255, 42), 1)
        local function sliderRow(yy, o)
            local bh = 26
            if R.button(o.kMinus, ix, yy, bh, bh, "-", {}) then
                o.step(-1)
            end
            local sx = ix + bh + 8
            local sw = math.max(40, iw - bh * 2 - 8 * 2)
            local frac = (o.val - o.min) / math.max(1, o.max - o.min)
            if type(R.slider) == "function" then
                local nr = R.slider(o.kSlide, sx, yy, sw, bh, frac)
                if nr then
                    o.set(o.min + nr * (o.max - o.min))
                end
            else
                R.roundRect(R.dl, R.at(sx, yy + bh / 2 - 8),
                    R.at(sx + sw, yy + bh / 2 + 8),
                    R.col32(255, 255, 255, 30), 5)
            end
            local lab = o.label
            local lw = ((type(R.tsize) == "function") and R.tsize(lab)
                or (#lab * 7)) * 0.8
            R.uiText(sx + (sw - lw) / 2, yy + (bh - 12) / 2, lab, hi, 0.8)
            if R.button(o.kPlus, ix + iw - bh, yy, bh, bh, "+", {}) then
                o.step(1)
            end
        end
        local yy = y + 60
        if key == "weapon" then
            local n = #RT.weapons
            sliderRow(yy, {
                kMinus = "rt_set_wminus", kSlide = "rt_set_wsl",
                kPlus = "rt_set_wplus",
                min = 1, max = n, val = S.weapon.sel,
                label = (function()
                    local w = RT.weapons[S.weapon.sel] or RT.weapons[1]
                    return string.format("%s (%d)", w.name, w.id)
                end)(),
                set = function(v)
                    v = math.floor(v + 0.5)
                    if v < 1 then v = 1 end
                    if v > n then v = n end
                    if v ~= S.weapon.sel then
                        S.weapon.sel = v
                        pcall(RT.save)
                    end
                end,
                step = function(d)
                    local v = S.weapon.sel + d
                    if v < 1 then v = 1 end
                    if v > n then v = n end
                    if v ~= S.weapon.sel then
                        S.weapon.sel = v
                        pcall(RT.save)
                    end
                end,
            })
            yy = yy + rowH
            sliderRow(yy, {
                kMinus = "rt_set_aminus", kSlide = "rt_set_asl",
                kPlus = "rt_set_aplus",
                min = 1, max = 999, val = S.weapon.ammo,
                label = "Патроны: " .. S.weapon.ammo,
                set = function(v)
                    v = math.floor(v + 0.5)
                    if v < 1 then v = 1 end
                    if v > 999 then v = 999 end
                    if v ~= S.weapon.ammo then
                        S.weapon.ammo = v
                        pcall(RT.save)
                    end
                end,
                step = function(d)
                    local v = S.weapon.ammo + d
                    if v < 1 then v = 1 end
                    if v > 999 then v = 999 end
                    if v ~= S.weapon.ammo then
                        S.weapon.ammo = v
                        pcall(RT.save)
                    end
                end,
            })
        elseif key == "skin" then
            R.uiText(ix, yy + 2, "Номер скина (вручную)", mut, 0.85)
            if type(R.textInput) == "function" then
                R.textInput("rt_set_skin", "##rt_set_skin", 8, S.skin.num,
                    ix, yy + 22, iw, 26, "Например: 1540",
                    function(v)
                        S.skin.num = tostring(v or "")
                        pcall(RT.save)
                    end)
            else
                R.uiText(ix, yy + 24,
                    (S.skin.num ~= "" and S.skin.num or "—"), hi, 1.0)
            end
        elseif key == "armor" then
            sliderRow(yy, {
                kMinus = "rt_set_bminus", kSlide = "rt_set_bsl",
                kPlus = "rt_set_bplus",
                min = 1, max = 100, val = S.armor.amount,
                label = "Броня: " .. S.armor.amount,
                set = function(v)
                    v = math.floor(v + 0.5)
                    if v < 1 then v = 1 end
                    if v > 100 then v = 100 end
                    if v ~= S.armor.amount then
                        S.armor.amount = v
                        pcall(RT.save)
                    end
                end,
                step = function(d)
                    local v = S.armor.amount + d
                    if v < 1 then v = 1 end
                    if v > 100 then v = 100 end
                    if v ~= S.armor.amount then
                        S.armor.amount = v
                        pcall(RT.save)
                    end
                end,
            })
        elseif key == "vehicle" then
            local vlabels = { "Админские", "Незанятые", "Все" }
            local vw = (iw - 16) / 3
            for i = 1, 3 do
                if R.button("rt_set_veh" .. i,
                        ix + (i - 1) * (vw + 8), yy, vw, 26, vlabels[i],
                        { selected = S.vehicle.mode == i }) then
                    if S.vehicle.mode ~= i then
                        S.vehicle.mode = i
                        pcall(RT.save)
                    end
                end
            end
        end
        return y + boxH
    end
    function RT.page(R, cx, y, cw)
        if type(R) ~= "table" or type(R.button) ~= "function" then return y end
        pcall(RT.load)
        if RT.list == nil then RT.scan() end
        local TH = (type(R.theme) == "function") and R.theme() or {}
        local hi  = R.c4(TH.textHi or { 240, 240, 245, 255 })
        local function W(text, scale)
            local ok, v = pcall(R.tsize, tostring(text or ""))
            return (tonumber(v) or (#tostring(text or "") * 7)) * (tonumber(scale) or 1)
        end
        y = y + 4
        local bh = 26
        if R.button("rt_minus", cx, y, bh, bh, "-", {}) then
            RT.setRadius(RT.radius - 1)
        end
        local slX = cx + bh + 8
        local slW = math.max(40, cw - bh * 2 - 8 * 2)
        local frac = (RT.radius - RT.RMIN) / (RT.RMAX - RT.RMIN)
        if type(R.slider) == "function" then
            local nr = R.slider("rt_radius_sl", slX, y, slW, bh, frac)
            if nr then
                RT.setRadius(RT.RMIN + nr * (RT.RMAX - RT.RMIN) + 0.5)
            end
        else
            R.roundRect(R.dl, R.at(slX, y + bh / 2 - 8),
                R.at(slX + slW, y + bh / 2 + 8), R.col32(255, 255, 255, 30), 5)
        end
        local lab = "Радиус: " .. RT.radius
        local labW = W(lab, 0.8)
        R.uiText(slX + (slW - labW) / 2, y + (bh - 12) / 2, lab, hi, 0.8)
        if R.button("rt_plus", cx + cw - bh, y, bh, bh, "+", {}) then
            RT.setRadius(RT.radius + 1)
        end
        y = y + bh + 10
        if RT.settingsOpen and RT.settings[RT.settingsOpen] then
            y = rtSettingsPage(R, cx, y, cw)
        else
            RT.settingsOpen = nil
            local gap, abh, gearW = 8, 26, 26
            local cellW = (cw - gap * 2) / 3
            local bw = math.max(40, cellW - gearW - gap)
            local gearCol = R.col32(255, 255, 255, 150)
            for i = 1, #RT.actions do
                if i > 9 then break end
                local a = RT.actions[i]
                local row = math.floor((i - 1) / 3)
                local col = (i - 1) % 3
                local bx = cx + col * (cellW + gap)
                local by = y + row * (abh + gap)
                if R.button("rt_act_" .. a.id, bx, by, bw, abh, a.label,
                    { cutW = bw - 12 }) then
                    RT.doAction(a.id)
                end
                if a.gear then
                    local gx, gy = bx + bw + 15, by + abh / 2
                    if type(R.gearButton) == "function" then
                        local clicked =
                            R.gearButton("rt_gear_" .. a.id, gx, gy, false)
                        if clicked then RT.gearClick(a) end
                    elseif type(R.gear) == "function" then
                        R.gear(gx, gy, gearCol)
                    end
                end
            end
            y = y + 3 * (abh + gap) - gap
            y = y + 12
            if R.button("rt_tp", cx, y, cw, abh, RT.wide.label,
                { cutW = cw - 16 }) then
                RT.doAction(RT.wide.id)
            end
            y = y + abh + 8
        end
        do
            local U = _G.GRND_UPDATE
            if type(U) == "table" then
                local muted = R.c4(TH.textMuted or { 170, 170, 180, 255 })
                local warn  = R.c4({ 255, 176, 120, 255 })
                y = y + 6
                R.uiText(cx, y, "ОБНОВЛЕНИЯ", muted, 0.9)
                local status, scol
                if U.installed then
                    status, scol = "обновление " .. tostring(U.newVer or "?")
                        .. " включается…", hi
                elseif U.state == "downloading" then
                    status, scol = "обновляюсь до " .. tostring(U.newVer or "?")
                        .. "…", hi
                elseif U.state == "checking" then
                    status, scol = "проверяю…", muted
                elseif U.state == "error" then
                    status, scol = "нет связи: " .. tostring(U.err or "?"), warn
                else
                    status, scol = "версия " .. tostring(U.cur), muted
                end
                R.uiText(cx + cw - W(status, 0.9), y, status, scol, 0.9)
                y = y + 18
            end
        end
        return y
    end
    _G.GRND_RT = RT
    _G.grndRadTick = function()
        local ok, res = pcall(RT.tick)
        if ok then return res end
        RT.err = tostring(res)
        return false
    end
end
GRND_UPDATE = _G.GRND_UPDATE or {}
local function grndUpdInit()
    local U = GRND_UPDATE
    U.cur = tostring(rawget(_G, "GRND_SCRIPT_VERSION") or "0.0.0")
    -- Keep a source-shaped marker in bytecode for clients whose updater can
    -- extract versions only from GRND_SCRIPT_VERSION = "x.y" literals.
    U.VERSION_MARKER = 'GRND_SCRIPT_VERSION = "1.29"'
    if not tostring(U.VERSION_MARKER):find(tostring(U.cur), 1, true) then
        pcall(print, "[GRND обновления] VERSION_MARKER не совпадает с версией "
            .. tostring(U.cur) .. " — сборка помечена неверно, обновите маркер")
    end
    U.TAG    = "grnd-latest"
    U.OWNER  = "kacarovmihail4-max"
    U.REPO   = "grnd-updates"
    U.VER_FILE, U.SCRIPT_FILE = "update.txt", "grnd_adm_tools.luac"
    U.MIN_BYTES = 100000
    U.MIN_BYTE_BYTES = 200000
    U.UA = "GrndTools/" .. U.cur .. " (MoonLoader)"
    U.API = "https://api.github.com/repos/" .. U.OWNER .. "/" .. U.REPO .. "/"
    U.API_HDR = "Accept: application/vnd.github.raw\r\n"
    U.CHANNELS = {
        { id = "api", kind = "api", base = U.API },
        { id = "statically", base = "https://cdn.statically.io/gh/"
            .. U.OWNER .. "/" .. U.REPO .. "/" .. U.TAG .. "/" },
        { id = "githack", base = "https://raw.githack.com/"
            .. U.OWNER .. "/" .. U.REPO .. "/" .. U.TAG .. "/" },
        { id = "raw", base = "https://raw.githubusercontent.com/"
            .. U.OWNER .. "/" .. U.REPO .. "/" .. U.TAG .. "/" },
        { id = "github", base = "https://github.com/" .. U.OWNER .. "/"
            .. U.REPO .. "/raw/" .. U.TAG .. "/" },
        { id = "jsdelivr", base = "https://cdn.jsdelivr.net/gh/"
            .. U.OWNER .. "/" .. U.REPO .. "@" .. U.TAG .. "/" },
    }
    U.period  = 0
    U.auto    = true
    U.timeout = 12
    U.fileTimeout = 60
    U.MAX_DOWNLOAD_BYTES = 16777216
    U.state = "idle"
    U.err, U.job = nil, nil
    U.newVer, U.installed = nil, false
    U.staleSeen = nil
    U.lastAt, U.wasSpawn = 0, false
    U.reloadPending = false
    U.sessionAt = 0
    U.didSessionCheck = false
    U.failOnceShown = false
    U.activeId = nil
    U.cfgLoaded = false
    U.order, U.orderPos, U.phase, U.checkReason = nil, 0, nil, nil
    U.quiet = false
    U.apiSeen = false
    U.staleTries = 0
    U.staleRetryAt = nil
    U.STALE_GAP = 180
    U.STALE_TRIES = 4
    U.probing = false
    U.probeLines = nil
    U.logs = {}
    U.io = {
        clock  = os.clock,
        time   = os.time or function() return math.floor(os.clock()) end,
        open   = io.open,
        remove = os.remove,
        rename = os.rename,
        exists = function(path)
            local f = io.open(path, "rb")
            if f then pcall(f.close, f) return true end
            return false
        end,
    }
    function U.verNum(v)
        local a, b, c = tostring(v or ""):match("^(%d+)%.(%d+)%.?(%d*)")
        if not a or not b then return 0 end
        local patch = (c == nil or c == "") and 999 or tonumber(c)
        if patch == nil then patch = 0 end
        return tonumber(a) * 1000000 + tonumber(b) * 1000 + patch
    end
    function U.bustQ()
        local t = math.floor((tonumber(U.io.time()) or 0) / 60)
        return "?v=" .. tostring(t)
    end
    function U.jsonField(body, key)
        local v = tostring(body or ""):match('"' .. key .. '"%s*:%s*"(.-)"')
        if not v then return nil end
        v = v:gsub("\\u(%x%x%x%x)", function(h)
            return string.char(tonumber(h, 16) % 256)
        end)
        v = v:gsub("\\(.)", function(c)
            if c == "n" or c == "r" or c == "t" then return "" end
            return c
        end)
        return v
    end
    function U.jsonObjectField(body, objectKey, key)
        body = tostring(body or "")
        local a = body:find('"' .. tostring(objectKey) .. '"%s*:%s*{')
        if not a then return nil end
        local open = body:find("{", a, true)
        if not open then return nil end
        local depth, quoted, escaped = 0, false, false
        for i = open, #body do
            local ch = body:sub(i, i)
            if quoted then
                if escaped then
                    escaped = false
                elseif ch == "\\" then
                    escaped = true
                elseif ch == '"' then
                    quoted = false
                end
            elseif ch == '"' then
                quoted = true
            elseif ch == "{" then
                depth = depth + 1
            elseif ch == "}" then
                depth = depth - 1
                if depth == 0 then
                    return U.jsonField(body:sub(open, i), key)
                end
            end
        end
        return nil
    end
    function U.b64decode(s)
        if type(s) ~= "string" then return nil end
        local t = U.b64tab
        if not t then
            t = {}
            local abc = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                .. "abcdefghijklmnopqrstuvwxyz0123456789+/"
            for i = 1, #abc do t[abc:sub(i, i)] = i - 1 end
            U.b64tab = t
        end
        local out, part, acc, bits = {}, {}, 0, 0
        for i = 1, #s do
            local ch = s:sub(i, i)
            if ch == "=" then break end
            local v = t[ch]
            if v then
                acc = acc * 64 + v
                bits = bits + 6
                while bits >= 8 do
                    bits = bits - 8
                    part[#part + 1] = string.char(math.floor(acc / 2 ^ bits) % 256)
                    acc = acc % 2 ^ bits
                    if #part >= 8192 then
                        out[#out + 1] = table.concat(part)
                        part = {}
                    end
                end
            end
        end
        if #part > 0 then out[#out + 1] = table.concat(part) end
        return table.concat(out)
    end
    function U.workDir()
        if type(getWorkingDirectory) == "function" then
            local ok, d = pcall(getWorkingDirectory)
            if ok and type(d) == "string" and d ~= "" then return d end
        end
        return "."
    end
    function U.scriptPath()
        if type(thisScript) == "function" then
            local ok, sc = pcall(thisScript)
            if ok and sc and type(sc.path) == "string" and sc.path ~= "" then
                return sc.path
            end
        end
        return U.workDir() .. "\\grnd_adm_tools.lua"
    end
    function U.dirOf(path)
        local dir = tostring(path or ""):match("^(.*[/\\])")
        return dir or ""
    end
    function U.cfgFile()
        return U.dirOf(U.scriptPath()) .. "config\\grnd_tools\\grnd_update.cfg"
    end
    function U.cfgLegacy() return U.dirOf(U.scriptPath()) .. "grnd_update.cfg" end
    function U.ensureDir(path)
        if type(createDirectory) ~= "function" then return end
        local base = U.dirOf(U.scriptPath())
        local rel = tostring(path or ""):sub(#base + 1)
        rel = rel and rel:match("^(.-)[/\\][^/\\]*$")
        if not rel then return end
        local acc = base
        for part in rel:gmatch("[^/\\]+") do
            acc = acc .. part
            pcall(createDirectory, acc)
            acc = acc .. "\\"
        end
    end
    function U.cfgRead()
        local C = rawget(_G, "GRND_CONFIG")
        if type(C) == "table" and type(C.open) == "function" then
            local ok, f = pcall(C.open, U.cfgFile(), "r")
            if ok and f then
                local body = f:read("*a")
                pcall(f.close, f)
                if type(body) == "string" then return body end
            end
            return nil
        end
        return U.readFile(U.cfgFile(), 8192)
    end
    function U.cfgWrite(body)
        local C = rawget(_G, "GRND_CONFIG")
        if type(C) == "table" and type(C.open) == "function" then
            local ok, f = pcall(C.open, U.cfgFile(), "w")
            if ok and f then
                local okW = pcall(f.write, f, body)
                pcall(f.close, f)
                if okW then return true end
            end
        end
        U.ensureDir(U.cfgFile())
        return U.writeFile(U.cfgFile(), body)
    end
    function U.tidyUp()
        local dir = U.dirOf(U.scriptPath())
        local drop = { "grnd_update.txt", "grnd_update.log" }
        drop[#drop + 1] = "grnd_adm_tools.lua.bak"
        drop[#drop + 1] = "grnd_adm_tools.lua.new"
        local base = tostring(U.scriptPath()):match("([^/\\]+)$")
        if base then
            drop[#drop + 1] = base .. ".bak"
            drop[#drop + 1] = base .. ".new"
            local stem = base:gsub("%.[Ll][Uu][Aa][Cc]?$", "")
            drop[#drop + 1] = stem .. ".lua.bak"
            drop[#drop + 1] = stem .. ".luac.bak"
            drop[#drop + 1] = stem .. ".lua.new"
            drop[#drop + 1] = stem .. ".luac.new"
        end
        for _, name in ipairs(drop) do
            local full = dir .. name
            if U.io.exists(full) then pcall(U.io.remove, full) end
        end
    end
    local function normBase(u)
        u = tostring(u or ""):gsub("%s+$", "")
        if u == "" then return nil end
        if u:sub(-1) ~= "/" then u = u .. "/" end
        return u
    end
    function U.notify(text, kind, life)
        text = tostring(text or "")
        if type(_G.grndSessionReady) == "function" then
            local okR, ready = pcall(_G.grndSessionReady)
            if okR and not ready then
                pcall(print, text)
                return false
            end
        end
        local N = rawget(_G, "notify")
        if type(N) == "table" and type(N.add) == "function" then
            local ok = pcall(N.add, text, kind or "ok", life or 3, true)
            if ok then return true end
        end
        local QRm = rawget(_G, "GRND_QR")
        if type(QRm) == "table" and type(QRm.toast) == "function" then
            local ok = pcall(QRm.toast, text, kind or "info", life or 3)
            if ok then return true end
        end
        pcall(print, text)
        return false
    end
    function U.refreshFrame()
        if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    end
    function U.readFile(path, maxBytes)
        if type(U.io.open) ~= "function" then return nil end
        local f = U.io.open(path, "rb")
        if not f then return nil end
        local data = f:read("*a")
        pcall(f.close, f)
        if type(data) ~= "string" then return nil end
        if maxBytes and #data > maxBytes then data = data:sub(1, maxBytes) end
        return data
    end
    function U.isBytecode(body)
        return tostring(body or ""):sub(1, 2) == "\27L"
    end
    -- LuaJIT кладёт строковые константы в дамп как kgc-строки: байт-тег
    -- (5 + длина) и сразу за ним сами байты. Настоящий номер версии — это
    -- константа, которую компилятор положил рядом с именем
    -- GRND_SCRIPT_VERSION. Строковый «маркер» (U.VERSION_MARKER) пишется в
    -- исходнике руками и на сборке может отстать от версии, поэтому он
    -- считается только запасным источником.
    function U.bytecodeConstVersion(body)
        body = tostring(body or "")
        local key = "GRND_SCRIPT_VERSION"
        local function isVer(v)
            if type(v) ~= "string" then return false end
            return v:match("^%d+%.%d+$") ~= nil or v:match("^%d+%.%d+%.%d+$") ~= nil
        end
        local after, before
        local pos = 1
        while true do
            local a = body:find(key, pos, true)
            if not a then break end
            -- ключ должен быть именно отдельной kgc-строкой, а не куском
            -- другой строки (например, самого маркера)
            if body:byte(a - 1) == 5 + #key then
                local tag = body:byte(a + #key)
                if tag and tag > 5 and tag <= 5 + 32 then
                    local v = body:sub(a + #key + 1, a + #key + (tag - 5))
                    if isVer(v) and not after then after = v end
                end
                -- запасной вариант: значение лежит ПЕРЕД именем
                for len = 3, 12 do
                    local tagPos = a - 1 - len
                    if tagPos >= 1 and body:byte(tagPos) == 5 + len then
                        local v = body:sub(tagPos + 1, tagPos + len)
                        if isVer(v) and not before then before = v end
                    end
                end
            end
            pos = a + 1
        end
        return after or before
    end
    function U.detectVersion(body)
        body = tostring(body or "")
        local marker = body:match('GRND_SCRIPT_VERSION%s*=%s*"([%d%.]+)"')
        if not U.isBytecode(body) then return marker end
        local compiled = U.bytecodeConstVersion(body)
        if compiled and marker then
            -- сборка помечена старым маркером, а скомпилирована уже новой
            -- версией: верим константе, иначе обновление отвергается forever
            return (U.verNum(compiled) > U.verNum(marker)) and compiled or marker
        end
        if compiled then return compiled end
        if marker then return marker end
        if not body:find("GRND_SCRIPT_VERSION", 1, true) then return nil end
        local best
        for ver in body:gmatch("(%d+%.%d+%.%d+)") do
            if not best or U.verNum(ver) > U.verNum(best) then best = ver end
        end
        return best
    end
    function U.installedBytecode()
        local head = U.readHead(U.scriptPath(), 4)
        if type(head) == "string" and #head >= 2 then
            return U.isBytecode(head)
        end
        return tostring(U.scriptPath()):lower():sub(-5) == ".luac"
    end
    function U.compileSource(src, chunkName)
        if type(string.dump) ~= "function" then
            return nil, "в сборке нет string.dump"
        end
        local chunk, cerr = load(tostring(src or ""),
            "@" .. tostring(chunkName or U.SRC_FILE))
        if not chunk then
            return nil, "исходник не компилируется: " .. tostring(cerr)
        end
        local okD, bc = pcall(string.dump, chunk, true)
        if not (okD and type(bc) == "string" and #bc > 0) then
            okD, bc = pcall(string.dump, chunk)
        end
        if not (okD and type(bc) == "string" and #bc > 0) then
            return nil, "string.dump: " .. tostring(bc)
        end
        if not U.isBytecode(bc) then return nil, "string.dump вернул не байткод" end
        return bc
    end
    function U.readHead(path, bytes)
        bytes = bytes or 16384
        if type(U.io.open) ~= "function" then return nil end
        local f = U.io.open(path, "rb")
        if not f then return nil end
        local data
        local ok, res = pcall(f.read, f, bytes)
        if ok and type(res) == "string" then
            data = res
        else
            ok, res = pcall(f.read, f, "*a")
            if ok and type(res) == "string" then data = res:sub(1, bytes) end
        end
        pcall(f.close, f)
        return data
    end
    function U.writeFile(path, data)
        if type(U.io.open) ~= "function" then return false end
        local f = U.io.open(path, "wb")
        if not f then return false end
        local ok = pcall(f.write, f, data)
        pcall(f.close, f)
        return ok and true or false
    end
    function U.diag(text)
        local line = os.date("%H:%M:%S") .. " " .. tostring(text)
        U.logs[#U.logs + 1] = line
        if #U.logs > 80 then table.remove(U.logs, 1) end
        return line
    end
    local function chanById(id)
        for i = 1, #U.CHANNELS do
            if U.CHANNELS[i].id == id then return U.CHANNELS[i] end
        end
    end
    local function buildOrder()
        local order, seen = {}, {}
        local function push(c)
            if c and not seen[c.id] then
                seen[c.id] = true
                order[#order + 1] = c
            end
        end
        push(chanById("cfg-repo"))
        push(chanById("cfg-mirror"))
        push(chanById(U.activeId))
        for i = 1, #U.CHANNELS do push(U.CHANNELS[i]) end
        U.order, U.orderPos = order, 0
    end
    local function nextChan()
        if not U.order then buildOrder() end
        U.orderPos = U.orderPos + 1
        local c = U.order[U.orderPos]
        U.chan = c
        return c
    end
    local function chanUrl(c, what, sha)
        if c and c.kind == "api" then
            if what == "blob" then
                return c.base .. "git/blobs/" .. tostring(sha)
            end
            local f = (what == "version") and U.VER_FILE or U.SCRIPT_FILE
            return c.base .. "contents/" .. f .. "?ref=" .. U.TAG
        end
        if what == "blob" then return nil end
        local f = (what == "version") and U.VER_FILE or U.SCRIPT_FILE
        return c.base .. f .. U.bustQ()
    end
    U.moonDl = (type(downloadUrlToFile) == "function") and downloadUrlToFile or nil
    do
        local ok, mod = pcall(require, "moonloader")
        local st = (ok and type(mod) == "table" and type(mod.download_status) == "table")
            and mod.download_status or nil
        U.ST_OK   = (st and tonumber(st.STATUS_ENDDOWNLOADDATA)) or 3
        U.ST_OK_EX = (st and tonumber(st.STATUSEX_ENDDOWNLOAD)) or 58
        U.ST_GO   = (st and tonumber(st.STATUS_DOWNLOADINGDATA)) or 5
        U.ST_LINK = (st and tonumber(st.STATUS_CONNECTING)) or 2
        -- downloadUrlToFile reports URLMon bind/progress notifications as well
        -- as the three familiar states. They are all callbacks from a live
        -- request, not failures (e.g. 1=FINDINGRESOURCE, 32=PROXYDETECTING,
        -- 34=COOKIE_SENT, 57=STATUSEX_STARTBINDING). Mark the complete standard
        -- MoonLoader notification range so these do not advance to the next
        -- mirror and orphan the still-running download.
        U.DL_PROGRESS = {}
        if st then
            for name, value in pairs(st) do
                if type(name) == "string" and name:match("^STATUS") then
                    local n = tonumber(value)
                    if n then U.DL_PROGRESS[n] = true end
                end
            end
        end
        for n = 1, 60 do U.DL_PROGRESS[n] = true end
    end
    local function jobClose(job) end
    function U.tmpFile()
        for _, key in ipairs({ "TEMP", "TMP" }) do
            local v = os.getenv and os.getenv(key)
            if type(v) == "string" and v ~= "" then
                return (v:gsub("[/\\]+$", "")) .. "\\grnd_update.txt"
            end
        end
        return U.dirOf(U.scriptPath()) .. "grnd_update.txt"
    end
    local function jobBody(job)
        if job.body then
            if #job.body > U.MAX_DOWNLOAD_BYTES then return nil end
            return job.body
        end
        if not job.path then return nil end
        local body = U.readFile(job.path, U.MAX_DOWNLOAD_BYTES + 1)
        pcall(U.io.remove, job.path)
        if body and #body > U.MAX_DOWNLOAD_BYTES then return nil end
        return body
    end
    local function startJob(url, path, headers, opts)
        if U.job then return false, "уже качаю" end
        opts = opts or {}
        local job = {
            url = url, path = path, parts = {}, headers = headers,
            mem = opts.mem and true or false, long = opts.long and true or false,
            started = U.io.clock(),
            deadline = U.io.clock() + (opts.long and U.fileTimeout or U.timeout),
        }
        U.job = job
        if U.moonDl then
            local ok, ret = pcall(U.moonDl, url, path, function(_, status)
                if U.job ~= job then return end
                local code = tonumber(status)
                if code == U.ST_OK or code == U.ST_OK_EX then
                    job.done = true
                elseif code ~= 0 and not U.DL_PROGRESS[code] then
                    job.err = code or -1
                end
            end)
            if ok and ret ~= false then
                job.backend = "moon"
                U.diag("→ MoonLoader: " .. url)
                return true
            end
            U.diag("загрузчик MoonLoader отказал: " .. tostring(ret))
        end
        U.job = nil
        U.diag("асинхронный загрузчик MoonLoader недоступен")
        return false, "нет асинхронного загрузчика"
    end
    local function jobStop()
        local job = U.job
        U.job = nil
        if job then jobClose(job) end
        return job
    end
    function U.loadCfg()
        if U.cfgLoaded then return end
        U.cfgLoaded = true
        local old = U.cfgLegacy()
        local body = U.cfgRead()
        local moved = nil
        if not body and U.io.exists(old) then
            body, moved = U.readFile(old, 8192), true
        end
        if not body then
            if moved then pcall(U.io.remove, old) end
            return
        end
        local custom = {}
        for line in body:gmatch("[^\r\n]+") do
            local k, v = tostring(line):match("^([%w_%-]+)=(.*)$")
            if k == "auto" then
                local sv = tostring(v):lower()
                U.auto = not (sv == "0" or sv == "false")
            end
            if k == "period" then
                local n = tonumber(v)
                if n and n >= 0 then U.period = n end
            end
            if k == "last" then U.lastAt = tonumber(v) or U.lastAt end
            if k == "updatedVer" then U.updatedVer = v end
            if k == "keepSpawn" then U.keepSpawnAt = tonumber(v) end
            if k == "updatedFrom" then U.updatedFrom = v end
            if k == "channel" then U.activeId = v end
            if k == "repo" or k == "mirror" then
                local base = normBase(v)
                if base then
                    local id = (k == "repo") and "cfg-repo" or "cfg-mirror"
                    custom[#custom + 1] = { id = id, base = base }
                end
            end
        end
        for i = #custom, 1, -1 do
            table.insert(U.CHANNELS, 1, custom[i])
        end
        if #custom > 0 then U.diag("канал из конфига: " .. custom[1].base) end
        if moved then
            U.saveCfg()
            pcall(U.io.remove, old)
        end
    end
    function U.saveCfg()
        local out = {}
        out[#out + 1] = "auto=" .. (U.auto and "1" or "0")
        out[#out + 1] = "period=" .. tostring(math.floor(U.period))
        out[#out + 1] = "last=" .. tostring(math.floor(U.lastAt or 0))
        if U.activeId then out[#out + 1] = "channel=" .. tostring(U.activeId) end
        if U.keepSpawnAt then out[#out + 1] = "keepSpawn=" .. tostring(U.keepSpawnAt) end
        if U.updatedVer then
            out[#out + 1] = "updatedVer=" .. tostring(U.updatedVer)
            out[#out + 1] = "updatedFrom=" .. tostring(U.updatedFrom or "0.0.0")
        end
        for i = 1, #U.CHANNELS do
            local c = U.CHANNELS[i]
            if c.id == "cfg-repo" or c.id == "cfg-mirror" then
                out[#out + 1] = (c.id == "cfg-repo" and "repo=" or "mirror=") .. c.base
            end
        end
        return U.cfgWrite(table.concat(out, "\n") .. "\n")
    end
    function U.spawned()
        local names = { "grndIsSpawnedSafe", "sampIsLocalPlayerSpawned",
            "grndIsSpawned" }
        for i = 1, #names do
            local f = rawget(_G, names[i])
            if type(f) == "function" then
                local ok, v = pcall(f)
                if ok and v then return true end
            end
        end
        local k = rawget(_G, "GRND_KEYS")
        return (type(k) == "table" and k.spawnedNow == true) and true or false
    end
    U.tidyUp()
    U.checkReason = nil
    function U.sessionReady()
        local dlg = rawget(_G, "grndAuthDialogOpen")
        if type(dlg) == "function" then
            local okD, open = pcall(dlg)
            if okD and open then return false end
        end
        local f = rawget(_G, "grndSessionReady")
        if type(f) == "function" then
            local ok, v = pcall(f)
            return ok and v == true
        end
        return U.spawned()
    end
    local function loud()
        return U.checkReason ~= "spawn" and U.checkReason ~= "stale"
    end
    local function failToast(text)
        if loud() then
            U.notify(text, "warn", 3.5)
        elseif not U.failOnceShown then
            U.failOnceShown = true
            U.notify("Обновления: сервер не отвечает — проверю при следующем заходе", "warn", 5)
        end
    end
    function U.finish(msg, kind)
        grndPerfWrite("проверка обновлений завершена: " .. tostring(msg or "ок"))
        if msg then U.state, U.err = "error", msg end
        if msg then failToast("Обновления: " .. tostring(msg)) end
        U.job = nil
        U.refreshFrame()
    end
    function U.dlVersion()
        U.phase = "version"
        while true do
            local c = nextChan()
            if not c then
                if U.staleSeen then
                    U.state = "uptodate"
                    if not U.quiet then
                        U.notify("Обновлений нет — версия " .. U.cur, "ok", 2.6)
                    end
                    U.armStaleRetry()
                    U.finish()
                    return false
                end
                U.finish("нет связи ни с одним каналом (" .. #U.order .. " шт.)")
                return false
            end
            U.diag(("канал %s: пробую %s"):format(c.id, U.VER_FILE))
            U.chan = c
            local url = chanUrl(c, "version")
            local hdr = (c.kind == "api") and U.API_HDR or nil
            if startJob(url, U.tmpFile(), hdr) then
                return true
            end
        end
    end
    local function startText(url, hdr)
        return startJob(url, U.scriptPath() .. ".new", hdr, { long = true })
    end
    local function startApiObject(phase, endpoint)
        U.phase = phase
        U.chan = chanById("api") or U.chan
        U.diag("api: запрашиваю " .. phase)
        return startText(U.API .. endpoint, nil)
    end
    local function startApiCommit(sha)
        return startApiObject("api-commit", "git/commits/" .. tostring(sha))
    end
    local function startApiTag(sha)
        return startApiObject("api-tag", "git/tags/" .. tostring(sha))
    end
    local function startApiTree(sha)
        return startApiObject("api-tree", "git/trees/" .. tostring(sha))
    end
    local function startApiRef()
        U.apiTagDepth = 0
        return startApiObject("api-ref", "git/ref/tags/" .. U.TAG)
    end
    local function startApiBlob(sha)
        return U.dlBlob(sha)
    end
    local function findApiBlobSha(body, path)
        for item in tostring(body or ""):gmatch("{([^{}]*)}") do
            if U.jsonField(item, "path") == path
                and U.jsonField(item, "type") == "blob" then
                return U.jsonField(item, "sha")
            end
        end
        return nil
    end
    function U.dlScript()
        U.phase = "file"
        while true do
            local c = nextChan()
            if not c then
                if U.rejectVer then
                    U.finish(("канал отдаёт сборку %s, а в update.txt %s — "
                        .. "перезалейте файл обновления"):format(
                        tostring(U.rejectVer), tostring(U.newVer)))
                else
                    U.finish("файл не скачался ни с одного канала")
                end
                return false
            end
            U.diag("качаю сам скрипт: " .. c.id)
            U.chan = c
            if startText(chanUrl(c, "script"),
                    (c.kind == "api") and U.API_HDR or nil) then
                return true
            end
        end
    end
    function U.dlBlob(sha)
        U.phase = "blob"
        local base = (U.chan and U.chan.kind == "api") and U.chan.base or U.API
        U.diag("api: файл большой — беру содержимое по sha "
            .. tostring(sha):sub(1, 8))
        if startText(chanUrl({ kind = "api", base = base }, "blob", sha), nil) then
            return true
        end
        return U.dlScript()
    end
    function U.markInstalled(fromVer, toVer)
        U.updatedFrom, U.updatedVer = tostring(fromVer), tostring(toVer)
        local okS = U.saveCfg()
        grndPerfWrite(("обновление сохранено: %s -> %s (запись конфига: %s)")
            :format(tostring(fromVer), tostring(toVer), tostring(okS)))
    end
    function U.markSeen()
        if U.markChecked then return end
        U.markChecked = true
        U.loadCfg()
        local to, from = U.updatedVer, U.updatedFrom
        grndPerfWrite(("после запуска: отметка обновления=%s, текущая версия=%s")
            :format(tostring(to), tostring(U.cur)))
        if not to or U.verNum(to) ~= U.verNum(U.cur) then return end
        U.justUpdated = { from = from or "?", to = to }
        U.state = "ready"
        U.updatedVer, U.updatedFrom = nil, nil
        U.lastAt = math.floor(U.io.time())
        U.saveCfg()
        U.notify("Обновление завершено", "ok", 3)
        U.refreshFrame()
    end
    local function finishVersion(job)
        local body = tostring(jobBody(job) or "")
        local id = tostring(U.chan and U.chan.id)
        if body:sub(1, 1) == "{" then
            local b64 = U.jsonField(body, "content")
            if b64 and #b64 > 0 then
                body = U.b64decode(b64) or ""
            else
                body = ""
            end
        end
        -- Public releases may use either a build version (1.20.03) or a
        -- release version without a patch component (1.20).
        local ver = body:match("(%d+%.%d+%.%d+)")
            or body:match("(%d+%.%d+)")
        if not ver then
            U.diag(("канал %s: в ответе нет номера версии (%d байт)")
                :format(id, #body))
            if U.probing then
                local line = ("%s: в ответе нет номера версии"):format(id)
                U.probeLines[#U.probeLines + 1] = line
                U.probeSay(line)
                return U.probeNext()
            end
            return U.dlVersion()
        end
        U.diag(("канал %s: версия %s (у нас %s)"):format(id, ver, U.cur))
        if U.probing then
            local line = ("%s: версия %s (у нас %s)"):format(id, ver, U.cur)
            U.probeLines[#U.probeLines + 1] = ("%s: версия %s"):format(id, ver)
            U.probeSay(line)
            return U.probeNext()
        end
        local c = U.chan
        if c and c.kind == "api" then U.apiSeen = true end
        if U.verNum(ver) < U.verNum(U.cur) then
            U.staleSeen = ver
            U.diag("канал " .. id .. ": файл из кэша (" .. ver .. ")")
            return U.dlVersion()
        end
        if U.verNum(ver) > U.verNum(U.cur) then
            U.newVer, U.state = ver, "downloading"
            if c and c.id ~= U.activeId then
                U.activeId = c.id
                U.saveCfg()
            end
            U.notify("Обновляюсь до версии " .. ver, "info", 3.2)
            buildOrder()
            return U.dlScript()
        end
        U.state = "uptodate"
        if c and c.id ~= U.activeId then
            U.activeId = c.id
            U.saveCfg()
        end
        if not U.quiet then
            U.notify("Обновлений нет — версия " .. U.cur, "ok", 2.6)
        end
        if not U.apiSeen then
            U.diag(("канал %s: кэш CDN мог отдать старый файл — перепроверю"):format(id))
            U.armStaleRetry()
        end
        U.finish()
        return true
    end
    local function dropTemp(job)
        if job and job.path then pcall(U.io.remove, job.path) end
    end
    local function install(job)
        local body = jobBody(job)
        -- Contents API иногда завершает загрузку большого файла пустым
        -- ответом в некоторых версиях URLMon/MoonLoader. Ищем файл по цепочке
        -- tag → tree → blob до перехода на CDN-зеркала.
        if (not body or #body == 0) and U.phase == "file"
            and U.chan and U.chan.kind == "api" then
            U.diag("api: Contents API вернул пустой файл — ищу git/blob по тегу")
            if startApiRef() then return true end
            return U.dlScript()
        end
        if body and body:sub(1, 1) == "{" then
            local b64 = U.jsonField(body, "content")
            if b64 and #b64 > 0 then
                body = U.b64decode(b64)
            else
                local sha = U.jsonField(body, "sha")
                dropTemp(job)
                if sha then return U.dlBlob(sha) end
                body = nil
            end
        end
        local ver = U.detectVersion(body)
        local asBytecode = U.installedBytecode()
        local minBytes = U.isBytecode(body) and U.MIN_BYTE_BYTES or U.MIN_BYTES
        if not body or #body < minBytes or not ver
            or U.verNum(ver) ~= U.verNum(U.newVer) then
            dropTemp(job)
            U.diag(("скачанный файл не прошёл проверку (%d байт, версия %s, "
                .. "в канале %s)"):format(#tostring(body or ""), tostring(ver),
                tostring(U.newVer)))
            if body and ver and U.verNum(ver) ~= U.verNum(U.newVer) then
                U.rejectVer = ver
            end
            return U.dlScript()
        end
        local out = body
        if U.isBytecode(body) then
            local okLoad, chunk, loadErr = pcall(load, body,
                "@" .. tostring(U.SCRIPT_FILE))
            if not okLoad or type(chunk) ~= "function" then
                dropTemp(job)
                U.diag("байткод несовместим с LuaJIT: " .. tostring(loadErr or chunk))
                U.state, U.err = "error", "несовместимый байткод"
                failToast("Обновление не установилось: байткод несовместим "
                    .. "с LuaJIT — версия " .. U.cur .. " на месте")
                return false
            end
            U.diag(("готовый байткод проверен: %d байт"):format(#body))
        elseif asBytecode then
            local bc, cerr = U.compileSource(body, U.SCRIPT_FILE)
            if not bc or #bc < 64
                or U.verNum(U.detectVersion(bc) or "0") ~= U.verNum(U.newVer) then
                dropTemp(job)
                U.diag("не смог собрать байткод: " .. tostring(cerr))
                U.state, U.err = "error", "обновление не скомпилировалось"
                failToast("Обновление не установилось: не удалось собрать "
                    .. "байткод — версия " .. U.cur .. " на месте")
                return false
            end
            out = bc
            U.diag(("байткод собран: %d байт (из %d байт исходника)"):format(#bc, #body))
        end
        local target = U.scriptPath()
        if not U.writeFile(target, out) then
            dropTemp(job)
            U.diag("не смог записать файл скрипта (занят?)")
            U.state = "error"
            U.err = "не смог записать файл скрипта"
            failToast("Обновление не установилось (файл занят?) — версия "
                .. U.cur .. " на месте")
            return false
        end
        dropTemp(job)
        pcall(U.io.remove, target .. ".bak")
        pcall(U.io.remove, target .. ".new")
        U.state, U.installed = "ready", true
        U.diag("установлено: " .. tostring(U.newVer) .. " (" .. #body .. " байт)")
        U.notify("Обновление " .. tostring(U.newVer) .. " установлено", "ok", 3)
        U.markInstalled(U.cur, tostring(U.newVer))
        U.requestReload()
        return true
    end
    local function jobFailed(job, why)
        U.diag(("канал %s: %s"):format(tostring(U.chan and U.chan.id), tostring(why)))
        U.job = nil
        if U.probing then
            local line = ("%s: %s"):format(tostring(U.chan and U.chan.id),
                tostring(why))
            U.probeLines[#U.probeLines + 1] = line
            U.probeSay(line)
            return U.probeNext()
        end
        if U.phase == "version" then return U.dlVersion() end
        return U.dlScript()
    end
    local function jobDone(ok, why)
        local job = U.job
        if not job then return end
        if not ok then
            jobClose(job)
            return jobFailed(job, why)
        end
        jobClose(job)
        U.job = nil
        if U.phase == "api-ref" or U.phase == "api-tag" then
            local raw = tostring(jobBody(job) or "")
            local sha = U.jsonObjectField(raw, "object", "sha")
            local kind = U.jsonObjectField(raw, "object", "type")
            if not sha then
                U.diag("api: не удалось получить commit из тега")
                return U.dlScript()
            end
            if kind == "tag" then
                U.apiTagDepth = (tonumber(U.apiTagDepth) or 0) + 1
                if U.apiTagDepth > 3 then
                    U.diag("api: слишком глубокая цепочка annotated tags")
                    return U.dlScript()
                end
                if startApiTag(sha) then return true end
                return U.dlScript()
            end
            if kind ~= "commit" then
                U.diag("api: тег не указывает на commit")
                return U.dlScript()
            end
            if startApiCommit(sha) then return true end
            return U.dlScript()
        elseif U.phase == "api-commit" then
            local raw = tostring(jobBody(job) or "")
            local sha = U.jsonObjectField(raw, "tree", "sha")
            if not sha then
                U.diag("api: в commit нет tree sha")
                return U.dlScript()
            end
            if startApiTree(sha) then return true end
            return U.dlScript()
        elseif U.phase == "api-tree" then
            local raw = tostring(jobBody(job) or "")
            local sha = findApiBlobSha(raw, U.SCRIPT_FILE)
            if not sha then
                U.diag("api: в дереве нет " .. U.SCRIPT_FILE)
                return U.dlScript()
            end
            return startApiBlob(sha)
        elseif U.phase == "blob" then
            local raw = jobBody(job)
            local data = raw and U.b64decode(U.jsonField(raw, "content") or "")
            if not data or #data < U.MIN_BYTES then
                dropTemp(job)
                U.diag("api: содержимое по sha не пришло — иду по каналам")
                return U.dlScript()
            end
            job.body, job.path = data, nil
            return install(job)
        end
        if U.phase == "version" then return finishVersion(job) end
        return install(job)
    end
    function U.probeSay(line)
        line = tostring(line or "")
        if line == "" then return false end
        if type(print) == "function" then pcall(print, "[GRND] обновления: " .. line) end
        if type(_G.grndChatSay) == "function" then
            local ok = pcall(_G.grndChatSay,
                "{00D6AA}[GRND]{FFFFFF} обновления: " .. line, -1)
            if ok then return true end
        end
        return false
    end
    function U.probeDumpLog()
        local lines = U.logs or {}
        if #lines == 0 then
            U.probeSay("журнал пуст — проверка ещё не запускалась")
            return false
        end
        if type(print) == "function" then
            pcall(print, "[GRND] журнал обновлений (" .. tostring(#lines) .. " строк)")
            for i = 1, #lines do pcall(print, "[GRND] " .. tostring(lines[i])) end
        end
        U.probeSay("журнал (" .. tostring(#lines) .. " строк) записан в moonloader.log")
        return true
    end
    function U.probeNext()
        local c = nextChan()
        while c do
            U.probeLines[#U.probeLines + 1] = ("%s: проверяю…"):format(c.id)
            U.phase = "version"
            U.chan = c
            if startJob(chanUrl(c, "version"),
                U.dirOf(U.scriptPath()) .. "grnd_update.txt",
                (c.kind == "api") and U.API_HDR or nil) then
                return true
            end
            local line = ("%s: не удалось начать загрузку"):format(c.id)
            U.probeLines[#U.probeLines + 1] = line
            U.probeSay(line)
            c = nextChan()
        end
        if not c then
            U.probing, U.state = false, "uptodate"
            U.diag("обход зеркал закончен")
            U.probeDumpLog()
            U.probeSay("обход закончен, журнал в moonloader.log")
            U.refreshFrame()
            return false
        end
    end
    function U.probe()
        if U.job then jobStop() end
        if U.job then return false, "уже качаю" end
        U.loadCfg()
        U.probing = true
        U.probeLines = {}
        U.state = "checking"
        U.err = nil
        buildOrder()
        U.diag("проба каналов (" .. tostring(#U.order) .. " зеркал)")
        U.notify("Проверяю каналы обновлений…", "info", 2.5)
        return U.probeNext()
    end
    function U.check(reason)
        U.checkReason = reason or "manual"
        U.quiet = (U.checkReason == "stale")
        grndPerfWrite("проверка обновлений начата: " .. tostring(U.checkReason))
        U.loadCfg()
        if U.probing or U.job then return false, "уже проверяю" end
        U.state, U.err = "checking", nil
        if not U.justUpdated then
            U.installed = false
        end
        U.staleSeen = nil
        U.rejectVer = nil
        U.apiSeen = false
        if not U.quiet then U.lastAt = math.floor(U.io.time()) end
        U.saveCfg()
        buildOrder()
        U.diag(("проверка (%s), зеркал: %d"):format(tostring(reason), #U.order))
        if loud() then U.notify("Проверяю обновления…", "info", 2.2) end
        return U.dlVersion()
    end
    function U.armStaleRetry()
        if (U.staleTries or 0) >= (U.STALE_TRIES or 0) then return false end
        local gap = tonumber(U.STALE_GAP) or 180
        U.staleRetryAt = (tonumber(U.io.time()) or 0) + gap
        U.diag(("каналы отдали файл из кэша — повторю проверку через %d с"):format(gap))
        return true
    end
    function U.onSpawn()
        U.loadCfg()
        if not U.auto then return false end
        local now = U.io.time()
        local gap = tonumber(U.period) or 0
        if gap <= 0 then gap = 20 end
        if (now - (U.lastAt or 0)) < gap then return false end
        return U.check("spawn")
    end
    function U.tick()
        if not U.markChecked and U.sessionReady() then U.markSeen() end
        if U.reloadPending then
            U.reloadPending = false
            if U.reload() then return true end
            U.installed = true
            U.notify("Обновление скачано — включится при следующем запуске игры",
                "warn", 4)
            U.refreshFrame()
            return false
        end
        local now = U.io.clock()
        local sp = U.sessionReady()
        if sp and not U.wasSpawn then
            U.wasSpawn = true
            U.spawnAt = now
        elseif not sp then
            U.wasSpawn = false
            U.spawnChecked = false
        end
        if sp and U.wasSpawn and not U.spawnChecked and U.spawnAt and now - U.spawnAt >= 1 then
            U.spawnChecked = true
            U.onSpawn()
        end
        if U.staleRetryAt and not U.job and not U.probing and U.sessionReady() then
            local wall = tonumber(U.io.time()) or 0
            if wall >= U.staleRetryAt then
                U.staleRetryAt = nil
                U.staleTries = (U.staleTries or 0) + 1
                U.diag("повторная проверка обновлений после ответа из кэша")
                U.check("stale")
            end
        end
        local job = U.job
        if not job then return false end
        if job.backend ~= "moon" then
            return jobDone(false, "неизвестный асинхронный загрузчик")
        end
        if job.done then return jobDone(true) end
        if job.err then return jobDone(false, "статус " .. tostring(job.err)) end
        if now > job.deadline then return jobDone(false, "таймаут") end
        return false
    end
    function U.requestReload()
        U.reloadPending = true
        U.notify("Перезагружаю скрипт…", "info", 2.5)
        U.refreshFrame()
        return true
    end
    function U.consumeKeepSpawn()
        local t = U.keepSpawnAt
        if not t then return false end
        U.keepSpawnAt = nil
        pcall(U.saveCfg)
        if os.time() - t > 120 then return false end
        if type(isPlayerPlaying) ~= "function" then return false end
        local okP, playing = pcall(isPlayerPlaying, PLAYER_HANDLE)
        return okP and playing == true
    end
    function U.reload()
        grndPerfWrite("перезапуск скрипта для обновления")
        local seen = rawget(_G, "GRND_SPAWN")
        if type(seen) == "table" and seen.seen == true then
            U.keepSpawnAt = os.time()
            pcall(U.saveCfg)
        end
        if type(thisScript) == "function" then
            local ok, sc = pcall(thisScript)
            if ok and sc and type(sc.reload) == "function" then
                local okR = pcall(sc.reload, sc)
                if okR then return true end
                U.diag("перезапуск не удался: файл уже обновлён, новая "
                    .. "версия включится при следующем запуске игры")
            end
        end
        return false
    end
    local function txt(im, s)
        s = tostring(s or "")
        if type(im.TextWrapped) == "function" then
            if pcall(im.TextWrapped, s) then return end
        end
        pcall(im.Text, s)
    end
    local function btn(im, label, w)
        if type(im.Button) ~= "function" then return false end
        local ok, res
        if type(im.ImVec2) == "function" then
            ok, res = pcall(im.Button, label, im.ImVec2(w or 200, 28))
        else
            ok, res = pcall(im.Button, label)
        end
        return ok and res and true or false
    end
    local function themeColor(name, fallback)
        local th = _G.GRND_UIKIT and _G.GRND_UIKIT.TH
        local c = type(th) == "table" and th[name] or nil
        if type(c) == "table" and tonumber(c[1]) then return c end
        return fallback
    end
    local function colored(im, color, text)
        text = tostring(text or "")
        local c = color or themeColor("text", { 234, 230, 244, 255 })
        if type(im.TextColored) == "function" and type(im.ImVec4) == "function" then
            local ok = pcall(im.TextColored, im.ImVec4(c[1] / 255, c[2] / 255,
                c[3] / 255, (c[4] or 255) / 255), text)
            if ok then return end
        end
        txt(im, text)
    end
    local function hi(im, text) colored(im, themeColor("textHi", nil), text) end
    local function label(im, text) colored(im, themeColor("text", nil), text) end
    local function muted(im, text) colored(im, themeColor("textMuted", { 172, 166, 190, 255 }), text) end
    local function accent(im, text) colored(im, themeColor("accent", { 164, 112, 224, 255 }), text) end
    local function sep(im) if type(im.Separator) == "function" then pcall(im.Separator) end end
    function U.compile()
        local target = U.scriptPath()
        if U.installedBytecode() then
            U.notify("Скрипт уже скомпилирован — обновления приходят в том же "
                .. "виде (.luac)", "ok", 4)
            return false
        end
        local src = U.readFile(target)
        if not src then
            U.notify("Не смог прочитать свой файл — компиляция отменена",
                "error", 4)
            return false
        end
        local bc, cerr = U.compileSource(src, U.SRC_FILE)
        if not bc then
            U.notify("Компиляция не удалась: " .. tostring(cerr), "error", 5)
            return false
        end
        local name = tostring(target):match("([^/\\]+)$") or U.SRC_FILE
        local base = name:gsub("%.[Ll][Uu][Aa][Cc]?$", "")
        local out = U.dirOf(target) .. base .. ".luac"
        if not U.writeFile(out, bc) then
            U.notify("Не смог записать " .. base .. ".luac", "error", 4)
            return false
        end
        U.compiledTo = out
        U.notify(("Скомпилировано: %s.luac (%.1f МБ из %.1f МБ). Закройте игру, "
            .. "удалите %s и запустите снова — дальше обновления будут "
            .. "ставиться в .luac сами"):format(base, #bc / 1048576,
            #src / 1048576, name), "ok", 14)
        return true
    end
    if type(sampRegisterChatCommand) == "function" then
        pcall(sampRegisterChatCommand, "grndupdate", function(arg)
            local a = tostring(arg or ""):lower()
            if a:find("compile", 1, true) or a:find("компил", 1, true)
                or a:find("байт", 1, true) or a:find("luac", 1, true) then
                U.compile()
                U.refreshFrame()
                return
            end
            if a:find("log", 1, true) or a:find("лог", 1, true) then
                U.probeDumpLog()
                U.refreshFrame()
                return
            end
            if a:find("test", 1, true) or a:find("канал", 1, true) then
                U.probe()
            else
                U.notify("Проверяю обновления вручную…", "info", 2)
                U.check("manual")
            end
            U.refreshFrame()
        end)
    end
    _G.grndUpdTick = function()
        local ok, res = pcall(U.tick)
        if ok then return res end
        U.err = tostring(res)
        pcall(U.diag, "тик: " .. tostring(res))
        return false
    end
    _G.GRND_UPDATE = U
end
grndUpdInit()
function grndRepTabBody(ctx)
    local VER = "v1.19.196"
    if type(ctx) ~= "table" then return end
    local im, menu = ctx.im, ctx.menu
    local uiText = ctx.uiText
    if not (im and menu and uiText) then
        grndRepTabDiag("нет отрисовщиков", "нет im/menu/uiText " .. VER, 0, 0, 0, 0)
        return
    end
    local col32 = ctx.col32 or function(r, g, b, a) return 0 end
    local rgba = ctx.rgba or function(r, g, b, a) return { r, g, b, a } end
    local c32 = ctx.c32 or function(t) return col32(t[1], t[2], t[3], t[4] or 255) end
    local c4 = ctx.c4 or function(t) return rgba(t[1], t[2], t[3], t[4] or 255) end
    local tsize = ctx.tsize or function(s2) return 8 * #tostring(s2), 14 end
    local roundRect = ctx.roundRect or function() end
    local at = ctx.at or function(x, y) return im.ImVec2(x, y) end
    local grndTextW = rawget(_G, "grndTextW")
    local drawnW = ctx.drawnW
    if type(drawnW) ~= "function" then
        drawnW = function(s2, scale)
            local w = 0
            if type(grndTextW) == "function" then
                local ok, v = pcall(grndTextW, tostring(s2 or ""))
                if ok and type(v) == "number" then w = v end
            end
            if not (w > 0) then w = #tostring(s2 or "") * 7 end
            return w * (tonumber(scale) or 1)
        end
    end
    local pushCol = ctx.pushCol
    if type(pushCol) ~= "function" then
        pushCol = function(idx, col)
            if idx == nil or col == nil then return false end
            if type(im.PushStyleColor) ~= "function" then return false end
            if type(im.ImVec4) ~= "function" then return false end
            local r, g, b, a
            if col.x ~= nil then
                r = (col.x or 0) * 255
                g = (col.y or 0) * 255
                b = (col.z or 0) * 255
                a = (tonumber(col.w) or 1) * 255
            else
                r, g, b, a = col[1] or col.r or 0, col[2] or col.g or 0,
                    col[3] or col.b or 0, col[4] or col.a or 255
            end
            local okC, v = pcall(im.ImVec4, r / 255, g / 255, b / 255, a / 255)
            if not okC then return false end
            return pcall(im.PushStyleColor, idx, v)
        end
    end
    local popCol = ctx.popCol
    if type(popCol) ~= "function" then
        popCol = function(cnt)
            if type(im.PopStyleColor) ~= "function" then return end
            for _ = 1, (tonumber(cnt) or 1) do
                if not pcall(im.PopStyleColor, 1) then pcall(im.PopStyleColor) end
            end
        end
    end
    local pushVarF = ctx.pushVarF
    if type(pushVarF) ~= "function" then
        pushVarF = function(idx, val)
            if idx == nil then return false end
            if type(im.PushStyleVarFloat) == "function"
               and pcall(im.PushStyleVarFloat, idx, val) then return true end
            if type(im.PushStyleVar) == "function" then
                return pcall(im.PushStyleVar, idx, val)
            end
            return false
        end
    end
    local pushVarV2 = ctx.pushVarV2
    if type(pushVarV2) ~= "function" then
        pushVarV2 = function(idx, vx, vy)
            if idx == nil then return false end
            local v
            if type(im.ImVec2) == "function" then
                local okV, vec = pcall(im.ImVec2, vx, vy)
                if okV then v = vec end
            end
            if v == nil then v = { x = vx, y = vy } end
            if type(im.PushStyleVarVec2) == "function"
               and pcall(im.PushStyleVarVec2, idx, v) then return true end
            if type(im.PushStyleVar) == "function" then
                return pcall(im.PushStyleVar, idx, v)
            end
            return false
        end
    end
    local popVar = ctx.popVar
    if type(popVar) ~= "function" then
        popVar = function(cnt)
            if type(im.PopStyleVar) ~= "function" then return end
            for _ = 1, (tonumber(cnt) or 1) do
                if not pcall(im.PopStyleVar, 1) then pcall(im.PopStyleVar) end
            end
        end
    end
    local TH = ctx.TH
    if type(TH) ~= "table" then
        if type(ctx.theme) == "function" then
            local okT, t = pcall(ctx.theme)
            if okT and type(t) == "table" then TH = t end
        end
    end
    if type(TH) ~= "table" then
        local uk = rawget(_G, "GRND_UIKIT")
        TH = (type(uk) == "table" and type(uk.TH) == "table" and uk.TH) or {}
    end
    local S = function(k, def) return (type(TH[k]) == "table") and TH[k] or def end
    TH = {
        itemSel = S("itemSel", { 255, 255, 255, 26 }),
        itemHover = S("itemHover", { 255, 255, 255, 10 }),
        accent = S("accent", { 164, 112, 224, 255 }),
        textHi = S("textHi", { 252, 250, 255, 255 }),
        text = S("text", { 234, 230, 244, 255 }),
        textDim = S("textDim", { 198, 192, 216, 255 }),
    }
    local cardX, cardY = ctx.cardX or 0, ctx.cardY or 0
    local cardW, cardH = ctx.cardW or 0, ctx.cardH or 0
    if cardW < 200 or cardH < 140 then
        uiText(cardX + 16, cardY + 16, string.format(
            "Карточка слишком мала для раздела: %dx%d (%s)",
            math.floor(cardW), math.floor(cardH), VER), c4(TH.textDim))
        grndRepTabDiag("нет места", "мала карточка " .. VER, cardW, cardH, 0, 0)
        return
    end
    local SUBS = {
        { id = "answers", name = "Ответы на репорт", fn = "grndQrSettingsDraw" },
        { id = "punish",  name = "Наказания",        fn = "grndQrPunishDraw" },
        { id = "auto",    name = "Автопилот",        fn = "grndQrAutoDraw" },
        { id = "settings", name = "Настройки",       fn = "grndRepSettingsDraw" },
    }
    menu.reportTab = menu.reportTab or "answers"
    local cur = menu.reportTab
    local bh, gap, rowGap = 32, 10, 8
    local by = cardY + 14
    local left = cardX + 16
    local avail = cardW - 32
    local widths = {}
    for i = 1, #SUBS do
        local tw = tsize(SUBS[i].name)
        widths[i] = math.max(96, math.min(260, math.floor(tw + 30)))
    end
    local rows, row, rowW = {}, {}, 0
    for i = 1, #SUBS do
        local bw = widths[i]
        if rowW > 0 and rowW + gap + bw > avail then
            rows[#rows + 1] = row
            row, rowW = {}, 0
        end
        row[#row + 1] = i
        rowW = rowW + (#row > 1 and gap or 0) + bw
    end
    rows[#rows + 1] = row
    local ry = by
    for r = 1, #rows do
        local bx = left
        for j = 1, #rows[r] do
            local i = rows[r][j]
            local sub = SUBS[i]
            local bw = widths[i]
            local tw, th = tsize(sub.name)
            local on = (cur == sub.id)
            im.SetCursorPos(im.ImVec2(bx, ry))
            if im.InvisibleButton("##grnd_reptab_" .. sub.id, im.ImVec2(bw, bh)) then
                menu.reportTab = sub.id
                cur = sub.id
                on = true
            end
            local hov = (im.IsItemHovered and im.IsItemHovered()) or false
            roundRect(ctx.dl, at(bx, ry), at(bx + bw, ry + bh),
                on and c32(TH.itemSel)
                    or (hov and c32(TH.itemHover) or col32(255, 255, 255, 10)), 8)
            if on then
                roundRect(ctx.dl, at(bx + 16, ry + bh - 3),
                    at(bx + bw - 16, ry + bh - 1), c32(TH.accent), 2)
            end
            uiText(bx + (bw - tw) / 2, ry + (bh - th) / 2, sub.name,
                on and c4(TH.textHi) or (hov and c4(TH.text) or c4(TH.textDim)))
            bx = bx + bw + gap
        end
        ry = ry + bh + rowGap
    end
    local x, y = left, by + #rows * bh + (#rows - 1) * rowGap + 14
    local w, h = cardW - 32, (cardY + cardH - 14) - y
    if w < 60 or h < 60 then return end
    local sub = {
        im = im, dl = ctx.dl, at = at,
        uiText = uiText, tsize = tsize,
        roundRect = roundRect, col32 = col32, c32 = c32,
        rgba = rgba, c4 = c4, gradRect = ctx.gradRect,
        x = x, y = y, w = w, h = h,
        cardX = cardX, cardY = cardY, cardW = cardW, cardH = cardH,
        drawnW = drawnW, pushCol = pushCol, popCol = popCol,
        pushVarF = pushVarF, pushVarV2 = pushVarV2, popVar = popVar,
    }
    local curSub = SUBS[1]
    for i = 1, #SUBS do if SUBS[i].id == cur then curSub = SUBS[i] end end
    local fn = rawget(_G, curSub.fn)
    if type(fn) ~= "function" then
        uiText(x, y + 4, "Раздел «" .. curSub.name .. "» не загружен (" .. VER .. ")",
            c4(TH.textDim))
        grndRepTabDiag(curSub.id, "нет обработчика " .. VER, cardW, cardH, w, h)
        return
    end
    local ok, res = pcall(fn, sub)
    if not ok then
        uiText(x, y + 4, "Ошибка раздела: " .. tostring(res), c4({ 255, 110, 110, 255 }))
        grndRepTabDiag(curSub.id, "ошибка: " .. tostring(res), cardW, cardH, w, h)
    elseif res == false then
        uiText(x, y + 4, string.format(
            "Разделу не хватает места (%d×%d) — раскройте меню шире (%s)",
            math.floor(w), math.floor(h), VER), c4(TH.textDim))
        grndRepTabDiag(curSub.id, "мало места " .. VER, cardW, cardH, w, h)
    else
        grndRepTabDiag(curSub.id, "ок " .. VER, cardW, cardH, w, h)
    end
end
function grndRepTabDiag(id, why, cardW, cardH, w, h)
    grndRepTabDiagSeen = grndRepTabDiagSeen or {}
    local key = tostring(id) .. "|" .. tostring(why)
    if grndRepTabDiagSeen[key] then return end
    grndRepTabDiagSeen[key] = true
    print(string.format(
        "{B0B0B0}[GRND меню]{FFFFFF} Репорт: подраздел=%s итог=%s карточка=%dx%d раздел=%dx%d",
        tostring(id), tostring(why), math.floor(cardW), math.floor(cardH),
        math.floor(w), math.floor(h)))
end
local GRND_CLW_AIM = { vehicleCache = nil, vehicleCacheAt = 0 }
function GRND_CLW_AIM.safeField(value, key)
    if value == nil then return nil end
    local ok, result = pcall(function() return value[key] end)
    if ok then return result end
    return nil
end
function GRND_CLW_AIM.number(value)
    local ok, result = pcall(tonumber, value)
    if ok then return result end
    return nil
end
function GRND_CLW_AIM.vec3(value)
    if value == nil then return nil end
    local ok, x, y, z = pcall(function() return value[1], value[2], value[3] end)
    if ok then
        x, y, z = GRND_CLW_AIM.number(x), GRND_CLW_AIM.number(y), GRND_CLW_AIM.number(z)
        if x and y and z then return x, y, z end
    end
    ok, x, y, z = pcall(function() return value.x, value.y, value.z end)
    if ok then
        x, y, z = GRND_CLW_AIM.number(x), GRND_CLW_AIM.number(y), GRND_CLW_AIM.number(z)
        if x and y and z then return x, y, z end
    end
    ok, x, y, z = pcall(function() return value[0], value[1], value[2] end)
    if ok then
        x, y, z = GRND_CLW_AIM.number(x), GRND_CLW_AIM.number(y), GRND_CLW_AIM.number(z)
        if x and y and z then return x, y, z end
    end
    return nil
end
function GRND_CLW_AIM.vehicleOnRay(camX, camY, camZ, farX, farY, farZ, maxAlong)
    if type(getAllVehicles) ~= "function" or type(getCarCoordinates) ~= "function" then return nil end
    local now = os.clock()
    if not GRND_CLW_AIM.vehicleCache or now - GRND_CLW_AIM.vehicleCacheAt > 0.25 then
        local ok, list = pcall(getAllVehicles)
        GRND_CLW_AIM.vehicleCache = ok and type(list) == "table" and list or {}
        GRND_CLW_AIM.vehicleCacheAt = now
    end
    local rx, ry, rz = farX - camX, farY - camY, farZ - camZ
    local rayLen = math.sqrt(rx * rx + ry * ry + rz * rz)
    if rayLen < 0.001 then return nil end
    rx, ry, rz = rx / rayLen, ry / rayLen, rz / rayLen
    local bestCar, bestScore = nil, math.huge
    for _, rawCar in ipairs(GRND_CLW_AIM.vehicleCache) do
        local car = GRND_CLW_AIM.number(rawCar)
        if car and car > 0 then
            local exists = true
            local existsFn = _G.doesVehicleExist or _G.doesCarExist
            if type(existsFn) == "function" then
                local okE, yes = pcall(existsFn, car)
                exists = okE and yes and true or false
            end
            if exists then
                local okP, x, y, z = pcall(getCarCoordinates, car)
                if okP and type(x) == "number" and type(y) == "number"
                    and type(z) == "number" then
                    local vx, vy, vz = x - camX, y - camY, z - camZ
                    local along = vx * rx + vy * ry + vz * rz
                    if along > 0 and along <= maxAlong + 3.0 then
                        local px, py, pz = vx - rx * along, vy - ry * along, vz - rz * along
                        local perp2 = px * px + py * py + pz * pz
                        if perp2 <= 8.0 then
                            local behindHit = math.max(0, along - maxAlong)
                            local score = perp2 + behindHit * behindHit * 2
                            if score < bestScore then bestCar, bestScore = car, score end
                        end
                    end
                end
            end
        end
    end
    return bestCar
end

function grndMainBody()
    local okList = {}
    for k, _ in pairs(libs) do okList[#okList + 1] = k end
    do
        local sv = tostring(GRND_SCRIPT_VERSION or "1.19.202")
        pcall(function() sv = tostring(thisScript().version or sv) end)
        print("{00FFAA}[GRND]{FFFFFF} GRND TOOLS v" .. sv .. ": кнопка репорта, слежка, формы, «Размер окна»")
    end
    print("{00FFAA}[GRND]{FFFFFF} скрипт загружен. Подключено либ: "
        .. (#okList > 0 and table.concat(okList, ", ") or "нет"))
    if #failed > 0 then
        print("{FF6666}[GRND]{FFFFFF} не найдено: " .. table.concat(failed, ", "))
    end
    function grndIsSpawned()
        if not sampIsLocalPlayerSpawned then return false end
        local ok, res = pcall(sampIsLocalPlayerSpawned)
        if ok and res then return true end
        return false
    end
    local clw = {
        enabled = true,
        mode = "click",
        keyToggle = 0x04,
        keyApply = 0x01,
        aiming = false,
        marker = nil,
        markerColor = 3,
        maxDist = 700.0,
        tx = nil, ty = nil, tz = nil,
        targetCar = nil,
        tdist = 0,
        lastX = 0, lastY = 0, lastZ = 0,
        savedX = nil, savedY = nil, savedZ = nil,
    }
    GRND_CONFIG.bindClickwarp(clw)
    clw.activationKeys = { clw.keyToggle }
    local lastMouseBtn = { [1] = false, [2] = false, vk = {} }
    local function clwVkTapped(vk)
        if not wasKeyTapped(vk) then return false end
        return grndPollTap(vk)
    end
    local function clwMouseRaw(btn)
        if type(getMouseState) == "function" then
            local ok, ms = pcall(getMouseState)
            if ok and type(ms) == "number" then
                if btn == 1 then return (ms % 2) == 1 end
                if btn == 2 then return (math.floor(ms / 2) % 2) == 1 end
            end
        end
        if type(isMouseButtonDown) == "function" then
            local ok, d = pcall(isMouseButtonDown, btn)
            if ok then return d and true or false end
        end
        return nil
    end
    local function clwMouseClicked(btn)
        local cur = clwMouseRaw(btn)
        if cur == nil then
            if type(isKeyDown) == "function" then
                local ok, d = pcall(isKeyDown, btn == 1 and 0x01 or 0x02)
                if ok then
                    local prev = lastMouseBtn[btn]
                    lastMouseBtn[btn] = d and true or false
                    if d and not prev then return true end
                    if not d then return false end
                end
            end
            if btn == 1 then return GRND_MOUSE.clicked end
            return GRND_MOUSE.rclicked
        end
        local prev = lastMouseBtn[btn]
        lastMouseBtn[btn] = cur
        return cur and not prev
    end
    local function clwBtnTapped(code)
        if code == 1 or code == 2 then return clwMouseClicked(code) end
        if code == 4 or code == 0x04 then
            local cur = GRND_MOUSE.mdown and true or false
            if type(isKeyDown) == "function" then
                local ok, d = pcall(isKeyDown, 0x04)
                if ok then cur = d and true or false end
            end
            local prev = lastMouseBtn.mmb
            lastMouseBtn.mmb = cur
            if cur and not prev then
                GRND_MOUSE.mclicked = false
                return true
            end
            return false
        end
        return clwVkTapped(code)
    end
    local plainCursorOn = false
    local GRND_GM = { on = false, lastHp = 100, cmdReg = false,
        srv = false, srvKnown = false,
        autoClient = _G.GRND_GM_AUTO == true, autoServer = _G.GRND_GM_AUTO == true,
        autoFired = false }
    _G.GRND_GM = GRND_GM
    local function clwGetGroundZ(x, y)
        if type(getGroundZForCoord) == "function" then
            local ok, z = pcall(getGroundZForCoord, x, y)
            if ok and type(z) == "number" then return z end
        end
        if type(getGroundZFor3dCoord) == "function" then
            local ok, z = pcall(getGroundZFor3dCoord, x, y, 50.0, 0, 1)
            if ok and type(z) == "number" then return z end
            local ok2, z2 = pcall(getGroundZFor3dCoord, x, y, 50.0)
            if ok2 and type(z2) == "number" then return z2 end
        end
        return nil
    end
    local function clwCam()
        if not (libs.memory and type(libs.memory.readfloat) == "function") then return nil end
        local m = libs.memory
        local function rf(a)
            local ok, v = pcall(m.readfloat, a)
            if ok and type(v) == "number" then return v end
            return nil
        end
        local cx, cy, cz = rf(0xB6F028), rf(0xB6F02C), rf(0xB6F030)
        local tx, ty, tz = rf(0xB6F038), rf(0xB6F03C), rf(0xB6F040)
        if not (cx and cy and cz and tx and ty and tz) then return nil end
        return cx, cy, cz, tx, ty, tz
    end
    local function clwScreenToWorld(sx, sy)
        local cam = clwCam()
        if not cam then return nil end
        local cx, cy, cz, tx, ty, tz = cam
        local fx, fy, fz = tx - cx, ty - cy, tz - cz
        local fl = math.sqrt(fx*fx + fy*fy + fz*fz)
        if fl < 1e-5 then return nil end
        fx, fy, fz = fx/fl, fy/fl, fz/fl
        local rx, ry, rz = fy, -fx, 0
        local rl = math.sqrt(rx*rx + ry*ry + rz*rz)
        if rl < 1e-5 then return nil end
        rx, ry, rz = rx/rl, ry/rl, rz/rl
        local ux, uy, uz = ry*fz - rz*fy, rz*fx - rx*fz, rx*fy - ry*fx
        local resX, resY = getScreenResolution()
        if resX <= 0 or resY <= 0 then return nil end
        local aspect = resX / resY
        local fovDeg = nil
        if type(grndCamActiveBase) == "function" then
            local okB, base, M = pcall(grndCamActiveBase)
            if okB and base and type(M) == "table" and type(M.rf) == "function" then
                local okV, v = pcall(M.rf, base + 0xB4)
                if okV and type(v) == "number" and v == v and v >= 30 and v <= 170 then
                    fovDeg = v
                end
            end
        end
        local vFov = (fovDeg or 70) * math.pi / 180
        local hFov = 2 * math.atan(math.tan(vFov/2) * aspect)
        local ndcX = (sx / resX) * 2 - 1
        local ndcY = 1 - (sy / resY) * 2
        local dirX = fx + rx * ndcX * math.tan(hFov/2) + ux * ndcY * math.tan(vFov/2)
        local dirY = fy + ry * ndcX * math.tan(hFov/2) + uy * ndcY * math.tan(vFov/2)
        local dirZ = fz + rz * ndcX * math.tan(hFov/2) + uz * ndcY * math.tan(vFov/2)
        local dl = math.sqrt(dirX*dirX + dirY*dirY + dirZ*dirZ)
        dirX, dirY, dirZ = dirX/dl, dirY/dl, dirZ/dl
        local step, maxD = 4.0, 600.0
        for t = step, maxD, step do
            local px, py, pz = cx + dirX*t, cy + dirY*t, cz + dirZ*t
            local gz = clwGetGroundZ(px, py)
            if gz and gz <= pz + 0.8 then
                return px, py, gz
            end
        end
        return cx + dirX*40, cy + dirY*40, cz + dirZ*40
    end
    local function clwGetMousePos()
        if type(getCursorPos) == "function" then
            local ok, x, y = pcall(getCursorPos)
            if ok and type(x) == "number" then return x, y end
        end
        if type(getPcMousePosition) == "function" then
            local ok, x, y = pcall(getPcMousePosition)
            if ok and type(x) == "number" then return x, y end
        end
        return nil
    end
    local function clwSurfaceZ(x, y, zHint)
        zHint = tonumber(zHint) or 0
        if type(processLineOfSight) == "function" then
            local top = zHint + 60.0
            local okL, hit, col = pcall(processLineOfSight,
                x, y, top, x, y, zHint - 60.0,
                true, true, false, true, false, false, false, false)
            if okL and hit and type(col) == "table" and type(col.pos) == "table"
               and type(col.pos[3]) == "number" then
                return col.pos[3]
            end
        end
        local gz = clwGetGroundZ(x, y)
        if gz then return gz end
        return nil
    end
    local function clwRoofZ(x, y, zMin)
        if type(processLineOfSight) ~= "function" then return nil end
        local okL, hit, col = pcall(processLineOfSight,
            x, y, 1200.0, x, y, (tonumber(zMin) or -100) - 1.0,
            true, false, false, true, false, false, false, false)
        if okL and hit and type(col) == "table" and type(col.pos) == "table"
           and type(col.pos[3]) == "number" then
            return col.pos[3]
        end
        return nil
    end
    local function clwStopMotion()
        if type(setCharVelocity) == "function" then pcall(setCharVelocity, PLAYER_PED, 0, 0, 0) end
        if type(isCharInAnyCar) == "function" and type(getCarCharIsUsing) == "function" then
            local okIn, inCar = pcall(isCharInAnyCar, PLAYER_PED)
            if okIn and inCar then
                local okC, car = pcall(getCarCharIsUsing, PLAYER_PED)
                if okC and car and car ~= 0 then
                    if type(setCarSpeedInstantly) == "function" then pcall(setCarSpeedInstantly, car, 0) end
                    if type(setCarVelocity) == "function" then pcall(setCarVelocity, car, 0, 0, 0) end
                end
            end
        end
    end
    local function clwStopAirBreakFlightForWarp()
        local A = GRND_ABRK
        if not A or not A.fly then return false end
        local held = false
        if type(grndAbrkKeyHeld) == "function" then
            local ok, down = pcall(grndAbrkKeyHeld, A.key or 0xA1)
            held = ok and down and true or false
        end
        A.fly, A.prevKey = false, held
        A.z, A.zOff, A.hx, A.hy = nil, nil, nil, nil
        A.camDir = false
        A.lastT = 0
        if notify and type(notify.add) == "function" then
            pcall(notify.add, "AirBreak: полёт ВЫКЛ (ClickWarp)", "warn", 2)
        end
        return true
    end
    local function clwWarpTo(x, y, z)
        if not grndIsSpawned() then
            notify.add("ClickWarp: вы ещё не заспавнены", "warn", 3)
            return
        end
        if type(isCharInAnyCar) == "function" and type(getCarCharIsUsing) == "function"
        and type(setCarCoordinates) == "function" then
            local okIn, inCar = pcall(isCharInAnyCar, PLAYER_PED)
            if okIn and inCar then
                local okC, car = pcall(getCarCharIsUsing, PLAYER_PED)
                if okC and car and car ~= 0 then
                    local sz = clwSurfaceZ(x, y, z) or z
                    clwStopAirBreakFlightForWarp()
                    local okW = pcall(setCarCoordinates, car, x, y, sz + 0.5)
                    if okW then
                        clwStopMotion()
                        clw.lastX, clw.lastY, clw.lastZ = x, y, sz
                        notify.add(("ClickWarp -> %.1f, %.1f, %.1f"):format(x, y, z), "ok", 4)
                        return
                    end
                end
            end
        end
        if type(setCharCoordinates) == "function" then
            local sz = clwSurfaceZ(x, y, z) or z
            clwStopAirBreakFlightForWarp()
            local ok = pcall(setCharCoordinates, PLAYER_PED, x, y, sz + 0.05)
            if ok then
                clwStopMotion()
                clw.lastX, clw.lastY, clw.lastZ = x, y, sz
                notify.add(("ClickWarp -> %.1f, %.1f, %.1f"):format(x, y, z), "ok", 4)
                return
            end
        end
        notify.add("ClickWarp: функция телепорта недоступна", "error", 4)
    end
    local function clwDoWarp()
        local x, y, z
        if clw.mode == "blip" then
            if type(getTargetBlipCoordinates) == "function" then
                local ok, bx, by, bz = pcall(getTargetBlipCoordinates)
                if ok and type(bx) == "number" and (bx ~= 0 or by ~= 0 or bz ~= 0) then
                    x, y, z = bx, by, bz
                end
            end
            if not x then
                notify.add("ClickWarp: нет метки (правая кнопка по карте)", "warn", 3)
                return
            end
            do
                local gz = clwGetGroundZ(x, y)
                if gz then z = gz end
            end
        elseif clw.mode == "aim" then
            local resX, resY = getScreenResolution()
            x, y, z = clwScreenToWorld(resX/2, resY/2)
            if not x then
                notify.add("ClickWarp: не удалось вычислить точку", "error", 3)
                return
            end
        else
            local sx, sy = clwGetMousePos()
            if not sx then
                local resX, resY = getScreenResolution()
                sx, sy = resX/2, resY/2
            end
            x, y, z = clwScreenToWorld(sx, sy)
            if not x then
                notify.add("ClickWarp: не удалось вычислить точку", "error", 3)
                return
            end
        end
        clwWarpTo(x, y, z)
    end
    local clwFont = nil
    do
        if type(renderCreateFont) == "function" then
            local ok, f = pcall(renderCreateFont, "Verdana", 10, 5)
            if ok and f then clwFont = f end
        end
    end
    local function clwRemoveMarker()
        if clw.marker ~= nil then
            pcall(removeUser3dMarker, clw.marker)
            clw.marker = nil
        end
    end
    local function clwPlaceMarker(x, y, z)
        if type(createUser3dMarker) ~= "function" then return end
        clwRemoveMarker()
        local ok, m = pcall(createUser3dMarker, x, y, z + 1.2, clw.markerColor)
        if ok and m then clw.marker = m end
    end
    function grndCursorClipInit()
        local C = _G.GRND_CURSOR_CLIP
        if type(C) == "table" and C.init then return C end
        C = { init = true, active = false }
        _G.GRND_CURSOR_CLIP = C
        local okF, ffi = pcall(require, "ffi")
        if not (okF and ffi and ffi.cdef and ffi.load and ffi.new) then return C end
        pcall(ffi.cdef, [[
            typedef struct { long left, top, right, bottom; } GRND_CLIP_RECT;
            typedef struct { long x, y; } GRND_CLIP_POINT;
            int __stdcall GetClientRect(void* hWnd, GRND_CLIP_RECT* lpRect);
            int __stdcall ClientToScreen(void* hWnd, GRND_CLIP_POINT* lpPoint);
            int __stdcall ClipCursor(const GRND_CLIP_RECT* lpRect);
            void* __stdcall GetForegroundWindow(void);
            unsigned long __stdcall GetWindowThreadProcessId(void* hWnd, unsigned long* lpdwProcessId);
            unsigned long __stdcall GetCurrentProcessId(void);
        ]])
        local okU, u32 = pcall(ffi.load, "user32")
        local okK, k32 = pcall(ffi.load, "kernel32")
        if not (okU and u32 and okK and k32) then return C end
        local okP, pid = pcall(function() return tonumber(k32.GetCurrentProcessId()) end)
        if not okP or not pid then return C end
        local okB, pidBuf = pcall(ffi.new, "unsigned long[1]")
        local okR, rect = pcall(ffi.new, "GRND_CLIP_RECT[1]")
        local okP1, pt1 = pcall(ffi.new, "GRND_CLIP_POINT[1]")
        local okP2, pt2 = pcall(ffi.new, "GRND_CLIP_POINT[1]")
        if not (okB and okR and okP1 and okP2) then return C end
        C.ffi, C.u32, C.k32, C.pid = ffi, u32, k32, pid
        C.pidBuf, C.rect, C.pt1, C.pt2 = pidBuf, rect, pt1, pt2
        return C
    end
    function grndCursorClipRelease()
        local C = _G.GRND_CURSOR_CLIP
        if type(C) ~= "table" or not C.active or not C.u32 or not C.ffi then return end
        pcall(function() C.u32.ClipCursor(C.ffi.NULL) end)
        C.active, C.nextAt, C.signature = false, nil, nil
    end
    function grndCursorClipTick(cursorVisible)
        local C = grndCursorClipInit()
        if cursorVisible then grndCursorClipRelease(); return end
        if not (C.u32 and C.k32 and C.pidBuf and C.rect and C.pt1 and C.pt2) then return end
        local hwnd
        local okW = pcall(function() hwnd = C.u32.GetForegroundWindow() end)
        if not okW or not hwnd or hwnd == C.ffi.NULL then grndCursorClipRelease(); return end
        C.pidBuf[0] = 0
        local okId = pcall(function() C.u32.GetWindowThreadProcessId(hwnd, C.pidBuf) end)
        if not okId or tonumber(C.pidBuf[0]) ~= C.pid then grndCursorClipRelease(); return end
        local now = os.clock()
        if C.active and now < (C.nextAt or 0) then return end
        local okRect, rectValid = pcall(function()
            if C.u32.GetClientRect(hwnd, C.rect) == 0 then return false end
            C.pt1[0].x, C.pt1[0].y = C.rect[0].left, C.rect[0].top
            C.pt2[0].x, C.pt2[0].y = C.rect[0].right, C.rect[0].bottom
            if C.u32.ClientToScreen(hwnd, C.pt1) == 0
                or C.u32.ClientToScreen(hwnd, C.pt2) == 0 then return false end
            C.rect[0].left, C.rect[0].top = C.pt1[0].x, C.pt1[0].y
            C.rect[0].right, C.rect[0].bottom = C.pt2[0].x, C.pt2[0].y
            return C.rect[0].right > C.rect[0].left and C.rect[0].bottom > C.rect[0].top
        end)
        if not okRect or not rectValid then grndCursorClipRelease(); return end
        local okClip, clipped = pcall(function() return C.u32.ClipCursor(C.rect) end)
        C.active = okClip and clipped ~= 0 or C.active
        C.nextAt = now + 0.25
    end
    local function clwShowCursor(on)
        if type(showCursor) == "function" then
            if on then pcall(showCursor, true, true)
            else pcall(showCursor, false) end
        elseif type(sampSetCursorMode) == "function" then
            pcall(sampSetCursorMode, on and 3 or 0)
        end
        if type(grndCursorClipTick) == "function" then
            pcall(grndCursorClipTick, on and true or false)
        end
    end
    local function clwGetAimTarget()
        if type(getCursorPos) ~= "function" then return nil end
        if type(convertScreenCoordsToWorld3D) ~= "function" then return nil end
        if type(getActiveCameraCoordinates) ~= "function" then return nil end
        local okC, sx, sy = pcall(getCursorPos)
        if not okC or type(sx) ~= "number" or type(sy) ~= "number" then return nil end
        local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
        if not okCam or type(camX) ~= "number" then return nil end
        local okW, farX, farY, farZ = pcall(convertScreenCoordsToWorld3D, sx, sy, clw.maxDist)
        if not okW or type(farX) ~= "number" then return nil end
        if type(processLineOfSight) == "function" then
            local okL, hit, col = pcall(processLineOfSight,
                camX, camY, camZ, farX, farY, farZ,
                true, true, false, true, false, false, false, false)
            if okL and hit and col ~= nil then
                local hx, hy, hz = GRND_CLW_AIM.vec3(GRND_CLW_AIM.safeField(col, "pos"))
                if type(hx) == "number" and type(hy) == "number" and type(hz) == "number" then
                    local nx, ny, nz = GRND_CLW_AIM.vec3(GRND_CLW_AIM.safeField(col, "normal"))
                    local isWall = (nz ~= nil) and (math.abs(nz) < 0.45)
                    if nz == nil then
                        local fdx, fdy = farX - camX, farY - camY
                        local fl = math.sqrt(fdx*fdx + fdy*fdy)
                        if fl > 1e-3 then
                            local ix, iy = hx + fdx / fl * 0.6, hy + fdy / fl * 0.6
                            local rz = clwRoofZ(ix, iy, hz)
                            if rz and rz > hz + 1.0 then hx, hy, hz = ix, iy, rz end
                        end
                        isWall = false
                    end
                    if isWall then
                        nx, ny = tonumber(nx) or 0, tonumber(ny) or 0
                        local ix, iy = hx - nx * 0.6, hy - ny * 0.6
                        local rz = clwRoofZ(ix, iy, hz)
                        if rz and rz >= hz - 0.5 then
                            hx, hy, hz = ix, iy, rz
                        end
                    end
                    local dx, dy, dz = hx - camX, hy - camY, hz - camZ
                    local car = nil
                    local entity = GRND_CLW_AIM.number(GRND_CLW_AIM.safeField(col, "entity"))
                    local entityType = GRND_CLW_AIM.safeField(col, "entityType")
                    if entity and entity > 0 then
                        local exists = _G.doesVehicleExist or _G.doesCarExist
                        if type(exists) == "function" then
                            local okE, yes = pcall(exists, entity)
                            if okE and yes then car = entity end
                        elseif tonumber(entityType) == 2
                            or tostring(entityType):lower():find("vehicle", 1, true) then
                            car = entity
                        end
                    end
                    local hitDist = math.sqrt(dx*dx + dy*dy + dz*dz)
                    if not car then
                        car = GRND_CLW_AIM.vehicleOnRay(camX, camY, camZ,
                            farX, farY, farZ, hitDist)
                    end
                    return hx, hy, hz, hitDist, sx, sy, car
                end
            end
        end
        local gz = clwGetGroundZ(farX, farY)
        if gz then
            local car = GRND_CLW_AIM.vehicleOnRay(camX, camY, camZ,
                farX, farY, farZ, clw.maxDist)
            return farX, farY, gz, clw.maxDist, sx, sy, car
        end
        return nil
    end
    local SPEC_VEH_HANDLE_FNAMES = {
        "sampGetCarHandleBySampVehicleId",
        "getCarHandleBySampVehicleId",
        "sampGetVehicleHandleBySampVehicleId",
    }
    local specVehHandleFnCache = nil
    local specVehHandleFnName = nil
    local function specVehHandleFn()
        if specVehHandleFnCache ~= nil then
            return specVehHandleFnCache or nil
        end
        for i = 1, #SPEC_VEH_HANDLE_FNAMES do
            local f = _G[SPEC_VEH_HANDLE_FNAMES[i]]
            if type(f) == "function" then
                specVehHandleFnCache = f
                specVehHandleFnName = SPEC_VEH_HANDLE_FNAMES[i]
                return f
            end
        end
        specVehHandleFnCache = false
        return nil
    end
    local function specSampVehHandle(vid)
        local fn = specVehHandleFn()
        if not fn then return nil end
        local res = { pcall(fn, vid) }
        if not res[1] then return nil end
        local h = nil
        for i = 2, #res do
            if type(res[i]) == "number" and res[i] ~= 0 then h = res[i]; break end
        end
        if not h then return nil end
        if type(doesVehicleExist) == "function" then
            local okE, ex = pcall(doesVehicleExist, h)
            if okE and ex == false then return nil end
        end
        return h
    end
    local function clwSetAiming(on)
        if on == clw.aiming then return end
        if on then
            if not grndIsSpawned() then
                notify.add("ClickWarp: вы ещё не заспавнены", "warn", 3)
                return
            end
            plainCursorOn = false
            clw.aiming = true
            clw.tx, clw.ty, clw.tz = nil, nil, nil
            clw.targetCar = nil
            clwShowCursor(true)
            if type(setPlayerControl) == "function" then
                pcall(setPlayerControl, PLAYER_HANDLE, false)
            end
        else
            plainCursorOn = false
            clw.aiming = false
            clw.tx, clw.ty, clw.tz = nil, nil, nil
            clw.targetCar = nil
            clwRemoveMarker()
            clwShowCursor(false)
            if type(setPlayerControl) == "function" then
                pcall(setPlayerControl, PLAYER_HANDLE, true)
            end
        end
    end
    local function grndPlainCursorShow(on)
        if type(showCursor) == "function" then
            if on then pcall(showCursor, true)
            else pcall(showCursor, false) end
        elseif type(sampSetCursorMode) == "function" then
            pcall(sampSetCursorMode, on and 3 or 0)
        end
        if type(grndCursorClipTick) == "function" then
            pcall(grndCursorClipTick, on and true or false)
        end
    end
    local function grndF1Toast(on)
        if GRND_F1.toast == false then return end
        if notify and type(notify.add) == "function" then
            pcall(notify.add, on and "Курсор включён" or "Курсор выключен",
                on and "ok" or "info", 2)
        end
    end
    function grndTogglePlainCursor()
        if clw and clw.aiming then
            clwSetAiming(false)
            grndF1Toast(false)
            return
        end
        plainCursorOn = not plainCursorOn
        grndPlainCursorShow(plainCursorOn)
        grndF1Toast(plainCursorOn)
    end
    _G.grndPlainCursorForceOff = function()
        plainCursorOn = false
        grndPlainCursorShow(false)
    end
    _G.grndPlainCursorIsOn = function() return plainCursorOn and true or false end
    _G.grndNativeCursorShow = function(on)
        grndPlainCursorShow(on and true or false)
    end
    local function grndGMApply(on)
        if type(setCharProofs) == "function" then
            pcall(setCharProofs, PLAYER_PED, on, on, on, on, on)
        end
    end
    local function grndGMToast(on)
        if notify and type(notify.add) == "function" then
            pcall(notify.add, on and "GM включён" or "GM выключен",
                on and "ok" or "info", 2)
        end
    end
    local function grndGMClientSet(on)
        on = on and true or false
        if GRND_GM.on == on then return end
        GRND_GM.on = on
        if on then
            if type(getCharHealth) == "function" then
                local okH, hp = pcall(getCharHealth, PLAYER_PED)
                if okH and type(hp) == "number" then
                    GRND_GM.lastHp = math.min(hp, 100)
                end
            end
        end
        grndGMApply(on)
    end
    local function grndGMSrvSet(on)
        on = on and true or false
        if GRND_GM.srv == on then return end
        if type(sampSendChat) ~= "function" then return end
        pcall(sampSendChat, "/gm")
        GRND_GM.srv, GRND_GM.srvKnown = on, false
        pcall(grndCamCfgSave)
    end
    function grndGMToggle()
        local target = not GRND_GM.on
        GRND_GM.autoClient, GRND_GM.autoServer = target, target
        _G.GRND_GM_AUTO = target
        pcall(grndCamCfgSave)
        grndGMClientSet(target)
        grndGMSrvSet(target)
        grndGMToast(target)
    end
    local function grndGMFrame()
        if not GRND_GM.on then return end
        grndGMApply(true)
        if type(getCharHealth) == "function" and type(setCharHealth) == "function" then
            local okH, hp = pcall(getCharHealth, PLAYER_PED)
            if okH and type(hp) == "number" then
                local last = GRND_GM.lastHp or hp
                if hp > 0 and hp < last then
                    pcall(setCharHealth, PLAYER_PED, math.min(last, 100))
                elseif hp >= last then
                    GRND_GM.lastHp = math.min(hp, 100)
                end
            end
        end
    end
    local GM_SRV_ON = {
        "godmode enabled", "god mode enabled", "godmode on", "god mode on",
        "gm enabled", "gm on", "бессмертие включ", "годмод включ",
        "неуязвимость включ",
    }
    local GM_SRV_OFF = {
        "godmode disabled", "god mode disabled", "godmode off", "god mode off",
        "gm disabled", "gm off", "бессмертие выключ", "годмод выключ",
        "неуязвимость выключ",
    }
    local function gmSniffServerMsg(text)
        local t = tostring(text or ""):lower()
        if t == "" then return end
        for _, p in ipairs(GM_SRV_OFF) do
            if t:find(p, 1, true) then
                GRND_GM.srv, GRND_GM.srvKnown = false, true
                return
            end
        end
        for _, p in ipairs(GM_SRV_ON) do
            if t:find(p, 1, true) then
                GRND_GM.srv, GRND_GM.srvKnown = true, true
                return
            end
        end
    end
    local function clwAimFrame()
        if not clw.aiming then return end
        local x, y, z, d, sx, sy, car = clwGetAimTarget()
        if x then
            clw.tx, clw.ty, clw.tz, clw.tdist, clw.targetCar = x, y, z, d or 0, car
            clw.lastAimX, clw.lastAimY, clw.lastAimZ = x, y, z
            clwPlaceMarker(x, y, z)
            if clwFont and sx and type(renderFontDrawText) == "function" then
                local action = car and "Сесть в машину" or "TELEPORT"
                local txt = ("%.1f m  %s"):format(d or 0, action)
                if type(grndToAnsi) == "function" then
                    local okA, ansi = pcall(grndToAnsi, txt)
                    if okA and type(ansi) == "string" then txt = ansi end
                end
                pcall(renderFontDrawText, clwFont, txt, sx + 18, sy + 8, 0xFFFFFFFF)
            end
        else
            clw.tx, clw.ty, clw.tz = nil, nil, nil
            clw.targetCar = nil
            clwRemoveMarker()
        end
    end
    local function specSendChat(text)
        if type(sampSendChat) == "function" and type(text) == "string" and text ~= "" then
            pcall(sampSendChat, text)
            return true
        end
        return false
    end
    local function specSendPlayer(pid, x, y, z)
        local ok, cmd = pcall(string.format, GRND_SPEC_PLAYER_CMD, pid, x, y, z + 1.0)
        if ok and type(cmd) == "string" and cmd ~= "" then specSendChat(cmd) end
    end
    local function specSendVeh(vid, x, y, z)
        local ok, cmd = pcall(string.format, GRND_SPEC_VEH_CMD, vid, x, y, z + 1.0)
        if ok and type(cmd) == "string" and cmd ~= "" then specSendChat(cmd) end
    end
    local function specResolveVehId(handle)
        if not handle or handle == 0 then return nil end
        for _, fname in ipairs({ "sampGetVehicleIdByCarHandle", "sampGetSampVehicleIdByCarHandle" }) do
            local f = _G[fname]
            if type(f) == "function" then
                local res = { pcall(f, handle) }
                if res[1] then
                    for i = 2, #res do
                        if type(res[i]) == "number" and res[i] >= 0 and res[i] <= 2000 then
                            return res[i]
                        end
                    end
                end
            end
        end
        for id = 0, 2000 do
            if specSampVehHandle(id) == handle then return id end
        end
        return nil
    end
    local function specGetSpecPed()
        if not (grndSpecInSpec()) then return nil end
        if type(sampGetCharHandleBySampPlayerId) ~= "function" then return nil end
        local res = { pcall(sampGetCharHandleBySampPlayerId, GRND_SPEC.id) }
        if not res[1] then return nil end
        local ped = nil
        for i = 2, #res do
            if type(res[i]) == "number" and res[i] ~= 0 then ped = res[i]; break end
        end
        if not ped then return nil end
        if type(doesCharExist) == "function" then
            local okE, ex = pcall(doesCharExist, ped)
            if not (okE and ex) then return nil end
        end
        return ped
    end
    local function specGetSpecPos()
        if not (grndSpecInSpec()) then return nil end
        if type(sampGetCharHandleBySampPlayerId) ~= "function" then return nil end
        if type(getCharCoordinates) ~= "function" then return nil end
        local res = { pcall(sampGetCharHandleBySampPlayerId, GRND_SPEC.id) }
        if not res[1] then return nil end
        local ped = nil
        for i = 2, #res do
            if type(res[i]) == "number" and res[i] ~= 0 then ped = res[i]; break end
        end
        if not ped then return nil end
        if type(doesCharExist) == "function" then
            local okE, ex = pcall(doesCharExist, ped)
            if not (okE and ex) then return nil end
        end
        local okC, x, y, z = pcall(getCharCoordinates, ped)
        if okC and type(x) == "number" then return x, y, z end
        return nil
    end
    local function specFindSpecCarId()
        local ped = specGetSpecPed()
        if not ped then return nil end
        if type(isCharInAnyCar) == "function" then
            local okI, inCar = pcall(isCharInAnyCar, ped)
            if not (okI and inCar) then return nil end
        else
            return nil
        end
        if type(getCarCharIsUsing) ~= "function" then return nil end
        local okC, car = pcall(getCarCharIsUsing, ped)
        if not (okC and car and car ~= 0) then return nil end
        local vid = nil
        local okR, rid = pcall(specResolveVehId, car)
        if okR then vid = rid end
        return vid
    end
    local specArmId, specArmT = nil, 0
    local function specWarpAim()
        if not (grndSpecInSpec()) then
            if GRND_SPEC.active and GRND_SPEC.id then
                notify.add(("Слежка #%d: трек протух — /cwsp %d чтобы продолжить"):format(
                    GRND_SPEC.id, GRND_SPEC.id), "warn", 3)
            end
            return
        end
        local okV, stV = pcall(specProbeState)
        if okV and stV == false then
            grndSpecForget("state")
            notify.add("ТП отменён: ты уже не в слежке", "warn", 3)
            return
        end
        local x, y, z = clw.tx, clw.ty, clw.tz
        if not x then
            x, y, z = clwGetAimTarget()
        end
        if not x then
            notify.add("ClickWarp: нет точки — наведите на землю или здание", "warn", 2)
            return
        end
        do
            local age = os.clock() - (GRND_SPEC.confirmT or 0)
            local freshLimit = GRND_SPEC_EVENTS and 180 or GRND_SPEC_CONFIRM_SEC
            if age > freshLimit then
                if specArmId == GRND_SPEC.id and os.clock() - specArmT < 4 then
                    specArmId, specArmT = nil, 0
                else
                    specArmId, specArmT = GRND_SPEC.id, os.clock()
                    notify.add(("Слежка: точно ТП #%d? Нажми X/ЛКМ ещё раз"):format(GRND_SPEC.id), "warn", 4)
                    return
                end
            end
        end
        local pid = GRND_SPEC.id
        local carId = nil
        local okC, found = pcall(specFindSpecCarId)
        if okC then carId = found end
        if carId then
            specSendVeh(carId, x, y, z)
            notify.add(("Слежка: #%d [авто #%d] -> %.0f, %.0f"):format(pid, carId, x, y), "ok", 3)
        else
            specSendPlayer(pid, x, y, z)
            notify.add(("Слежка: #%d -> %.0f, %.0f, %.0f"):format(pid, x, y, z), "ok", 3)
        end
        clwSetAiming(false)
    end
    local function clwAntiShot()
        if type(setPlayerControl) ~= "function" then return end
        if lua_thread == nil or type(lua_thread.create) ~= "function" then return end
        pcall(setPlayerControl, PLAYER_HANDLE, false)
        lua_thread.create(function()
            wait(150)
            if not clw.aiming then
                pcall(setPlayerControl, PLAYER_HANDLE, true)
            end
        end)
    end
    local function clwBoardVehicle(car)
        car = tonumber(car)
        if not car or car <= 0 then return false, "машина больше недоступна" end
        local exists = _G.doesVehicleExist or _G.doesCarExist
        if type(exists) == "function" then
            local okE, yes = pcall(exists, car)
            if not okE or not yes then return false, "машина больше недоступна" end
        end
        if type(warpCharIntoCarAsPassenger) ~= "function" then
            return false, "посадка в машину недоступна"
        end
        if type(isCharInAnyCar) == "function" then
            local okIn, inCar = pcall(isCharInAnyCar, PLAYER_PED)
            if okIn and inCar then return false, "сначала выйдите из текущей машины" end
        end
        local seats = nil
        if type(getMaximumNumberOfPassengers) == "function" then
            local okN, n = pcall(getMaximumNumberOfPassengers, car)
            if okN and tonumber(n) and tonumber(n) >= 0 then
                seats = math.min(8, math.floor(tonumber(n)))
            end
        end
        if seats == nil then seats = 3 end
        local function boardedIntoTarget()
            if type(isCharInAnyCar) ~= "function" then return true end
            local okI, inCar = pcall(isCharInAnyCar, PLAYER_PED)
            if not (okI and inCar) then return false end
            if type(getCarCharIsUsing) == "function" then
                local okC, current = pcall(getCarCharIsUsing, PLAYER_PED)
                if okC then return tonumber(current) == car end
            end
            return true
        end
        for seat = 0, seats - 1 do
            local free = false
            if type(isCarPassengerSeatFree) == "function" then
                local okF, yes = pcall(isCarPassengerSeatFree, car, seat)
                free = okF and yes and true or false
            end
            if free then
                local okW, result = pcall(warpCharIntoCarAsPassenger, PLAYER_PED, car, seat)
                if okW and result ~= false and boardedIntoTarget() then return true end
            end
        end
        -- Motorcycles and single-seat vehicles have no passenger slot; use the
        -- driver seat only when the runtime can confirm it is empty.
        if type(getDriverOfCar) == "function" and type(warpCharIntoCarAsDriver) == "function" then
            local okD, driver = pcall(getDriverOfCar, car)
            if okD and (driver == nil or driver == false or driver == 0) then
                local okW, result = pcall(warpCharIntoCarAsDriver, PLAYER_PED, car)
                if okW and result ~= false and boardedIntoTarget() then return true end
            end
        end
        return false, "в машине нет свободного места"
    end
    local function clwApplyAim()
        if not clw.aiming then return end
        if grndSpecInSpec() then
            specWarpAim()
            clwAntiShot()
            return
        end
        local x, y, z, car = clw.tx, clw.ty, clw.tz, clw.targetCar
        if not x then
            local d, sx, sy
            x, y, z, d, sx, sy, car = clwGetAimTarget()
        end
        if not x then
            notify.add("ClickWarp: нет точки — наведите на землю или здание", "warn", 2)
            return
        end
        do
            local okP, pst = pcall(specProbeState)
            if okP and pst == true then
                notify.add("Ты в слежке, но цель неизвестна — /cwsp <id>, потом X", "warn", 4)
                clwSetAiming(false)
                return
            end
        end
        clwSetAiming(false)
        clwAntiShot()
        if car then
            local boarded, why = clwBoardVehicle(car)
            if boarded then
                notify.add("ClickWarp: вы сели в машину", "ok", 3)
            else
                notify.add("ClickWarp: " .. tostring(why or "не удалось сесть в машину"), "warn", 3)
            end
            return
        end
        clwWarpTo(x, y, z)
    end
    grndOnTerm(function(scr)
