    local im = nil
    local imKind = nil
    GRND_REP = {
        open = false,
        dialogId = -1,
        author = "Игрок",
        playerId = "?",
        question = "текст репорта",
        sourceCaption = "",
        sourceText = "",
        answer = nil,
        lastAction = "",
        seenKey = nil,
        pollAt = 0,
        dialogIdHint = 10,
        await = 0,
        strict = true,
        tpCommand = "/goto %d",
    }
    local function grndRepEnsureBuffer()
        if GRND_REP.answer then return true end
        if not (im and im.new and im.new.char) then return false end
        local ok, buf = pcall(function() return im.new.char[256]() end)
        if ok and buf then
            GRND_REP.answer = buf
            return true
        end
        return false
    end
    local function grndRepClean(s)
        s = tostring(s or "")
        s = s:gsub("{%x%x%x%x%x%x}", "")
        s = s:gsub("\r", "")
        s = s:gsub("^%s+", ""):gsub("%s+$", "")
        return s
    end
    local function grndRepIsUtf8(s)
        local i, n = 1, #s
        while i <= n do
            local b = s:byte(i)
            local len
            if b < 0x80 then len = 1
            elseif b >= 0xC2 and b <= 0xDF then len = 2
            elseif b >= 0xE0 and b <= 0xEF then len = 3
            elseif b >= 0xF0 and b <= 0xF4 then len = 4
            else return false end
            for k = 1, len - 1 do
                local c = s:byte(i + k)
                if not c or c < 0x80 or c > 0xBF then return false end
            end
            i = i + len
        end
        return true
    end
    local function grndRepUtf(s)
        s = tostring(s or "")
        if s:find("[\128-\255]") == nil then return s end
        if grndRepIsUtf8(s) then return s end
        return cp1251_to_utf8(s)
    end
    local REP_MARKERS = {
        "жалоб", "репорт", "report", "обращение", "вопрос игрока",
    }
    function _G.grndRepLooksReport(caption, text)
        local s = grndLowerUtf(grndRepUtf(tostring(caption or "")) .. " "
            .. grndRepUtf(tostring(text or "")))
        for i = 1, #REP_MARKERS do
            if s:find(REP_MARKERS[i], 1, true) then return true end
        end
        if s:find("%[%d+%]") and s:find("вопрос", 1, true) then return true end
        return false
    end
    function _G.grndRepSpawnReady()
        if (GRND_REP.await or 0) > (os.clock() or 0) then return true end
        if type(sampIsLocalPlayerSpawned) ~= "function" then return true end
        local ok, sp = pcall(sampIsLocalPlayerSpawned)
        return (ok and sp) and true or false
    end
    function _G.grndRepAcceptDialog(dialogId, caption, text)
        local id = tonumber(dialogId)
        if not id then return false end
        if GRND_REP.strict then
            if id ~= (GRND_REP.dialogIdHint or 10)
               and not _G.grndRepLooksReport(caption, text) then
                return false
            end
            if _G.grndRepLooksReport(caption, text) then
                return _G.grndRepSpawnReady()
            end
            if (GRND_REP.await or 0) > (os.clock() or 0) then
                return id == (GRND_REP.dialogIdHint or 10)
            end
            return false
        end
        return id == (GRND_REP.dialogIdHint or 10)
    end
    function _G.grndRepMarkAwait(sec)
        GRND_REP.await = (os.clock() or 0) + (tonumber(sec) or 20)
        return GRND_REP.await
    end
    local function grndRepDump(dialogId, caption, text)
        pcall(function()
            local dir = getWorkingDirectory and getWorkingDirectory() or "moonloader"
            local f = io.open(grndStoragePath("logs","grnd_report_dump.txt"), "a")
            if not f then return end
            local function hex(str)
                return (tostring(str or ""):gsub(".", function(c) return string.format("%02X ", c:byte()) end))
            end
            f:write(os.date("[%Y-%m-%d %H:%M:%S] "), "dialog=", tostring(dialogId), "\n")
            f:write("caption: ", tostring(caption or ""), "\n")
            f:write("text:    ", tostring(text or ""), "\n")
            f:write("hex:     ", hex(text), "\n\n")
            f:close()
        end)
    end
    local GRND_REP_CHAT = {}
    local function grndRepRememberChat(text)
        local t = grndRepUtf(text)
        t = t:gsub("{%x%x%x%x%x%x}", "")
        local pid, msg = t:match("%[(%d+)%]%s*:%s*(.+)$")
        if not (pid and msg and msg ~= "") then return end
        if not _G.grndRepCountOf or not _G.grndRepCountOf(msg) then return end
        msg = msg:gsub("%[[^%]]*[Рр]епорта%s*:%s*%d*%s*%]", "")
        msg = grndRepClean(msg:gsub("%[%s*%]", ""))
        if msg ~= "" then
            GRND_REP_CHAT[pid] = { text = msg, at = os.clock() }
        end
    end
    local function grndCatchParse(text)
        local t = grndRepUtf(text)
        t = t:gsub("{%x%x%x%x%x%x}", "")
        local nick, pid, msg = t:match("([%w_%.%-]+)%[(%d+)%]%s*:%s*(.+)$")
        if not nick then return nil end
        local cnt = _G.grndRepCountOf(msg)
        if not cnt then return nil end
        msg = msg:gsub("%[[^%]]*[Рр]епорта%s*:%s*%d*%s*%]", "")
        msg = msg:gsub("%[%s*%]", "")
        msg = grndRepClean(msg)
        if msg == "" then msg = "текст репорта" end
        return nick, pid, msg, cnt
    end
    function grndRepShouldHideChat(text)
        return false
    end
    function grndRepHudRemove(pid)
        pid = tostring(pid or "")
        if pid == "" then return end
        local H = GRND_REPHUD
        if not H or not H.items then return end
        for i = #H.items, 1, -1 do
            if tostring(H.items[i].pid) == pid then
                table.remove(H.items, i)
            end
        end
    end
    function grndRepRawNick(pid)
        local n = tonumber(pid)
        if not n or n < 0 or n > 1003 then return nil end
        if type(sampIsPlayerConnected) ~= "function" or type(sampGetPlayerNickname) ~= "function" then
            return nil
        end
        local okC, conn = pcall(sampIsPlayerConnected, n)
        if not (okC and (conn == true or conn == 1)) then return nil end
        local okN, nk = pcall(sampGetPlayerNickname, n)
        if okN and type(nk) == "string" and nk ~= "" then return nk end
        return nil
    end
    function grndRepHudJoin(pid)
        local H = GRND_REPHUD
        pid = tostring(pid or "")
        if pid == "" or not H or type(H.items) ~= "table" or #H.items == 0 then return end
        local hasOwn = false
        for i = 1, #H.items do
            if tostring(H.items[i].pid) == pid then hasOwn = true break end
        end
        if not hasOwn then return end
        local cur = grndRepRawNick(pid)
        for i = #H.items, 1, -1 do
            local it = H.items[i]
            if tostring(it.pid) == pid and (cur == nil or it.real == nil or it.real ~= cur) then
                table.remove(H.items, i)
            end
        end
    end
    function grndRepHudPrune()
        local H = GRND_REPHUD
        if not H or type(H.items) ~= "table" or #H.items == 0 then return end
        local t = os.clock()
        if t - (H.pruneAt or 0) < 0.5 then return end
        H.pruneAt = t
        for i = #H.items, 1, -1 do
            local it = H.items[i]
            local pidN = tonumber(it.pid)
            local drop = (pidN == nil or pidN < 0 or pidN > 1003)
            if not drop and type(sampIsPlayerConnected) == "function" then
                local okC, on = pcall(sampIsPlayerConnected, pidN)
                if okC and not (on == true or on == 1) then drop = true end
            end
            if not drop and it.real then
                local cur = grndRepRawNick(pidN)
                if cur and cur ~= it.real then drop = true end
            end
            if drop then table.remove(H.items, i) end
        end
    end
    function grndRepHudAdd(nick, pid, msg, cnt)
        if type(_G.grndPushReportCapsule) == "function" then
            pcall(_G.grndPushReportCapsule, nick, pid, msg, cnt)
        end
        if not GRND_REPHUD.enabled then return end
        pid = tostring(pid or "")
        nick = tostring(nick or "Игрок")
        msg = tostring(msg or "")
        if pid == "" then return end
        local H = GRND_REPHUD
        H.items = H.items or {}
        local real = grndRepRawNick(pid)
        for i = 1, #H.items do
            if tostring(H.items[i].pid) == pid then
                H.items[i].nick = nick
                H.items[i].msg = msg
                H.items[i].cnt = cnt
                H.items[i].time = os.date("%H:%M:%S")
                H.items[i].at = os.clock()
                H.items[i].real = real
                local it = table.remove(H.items, i)
                table.insert(H.items, 1, it)
                return
            end
        end
        table.insert(H.items, 1, {
            pid = pid, nick = nick, msg = msg, cnt = cnt,
            time = os.date("%H:%M:%S"), at = os.clock(), real = real,
        })
        while #H.items > (H.max or 12) do
            H.items[#H.items] = nil
        end
        if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    end
    local function grndRepHudTaken(text)
        if GRND_LOG.response(text) then GRND_LOG.resolve(text);return end
        local t = tostring(text or "")
        t = grndRepUtf(t)
        t = t:gsub("{%x%x%x%x%x%x}", "")
        t = t:gsub("<ADM>", "")
        local pos = t:find("ответил", 1, true)
        if not pos then
            pos = t:find("\xEE\xF2\xE2\xE5\xF2\xE8\xEB", 1, true)
        end
        if pos then
            local rest = t:sub(pos)
            local pid = rest:match("%[(%d+)%]") or rest:match("%((%d+)%)")
            if pid then
                grndRepHudRemove(pid)
                return
            end
        end
        local low = grndLowerUtf(t)
        if low:find("взял", 1, true) and (low:find("репорт", 1, true) or low:find("жалоб", 1, true)) then
            local pid = t:match("%[(%d+)%]") or t:match(".*%((%d+)%)")
            if pid then grndRepHudRemove(pid) end
        end
    end
    local function grndCatchOnChat(text)
        if not GRND_CATCH.active then return end
        if GRND_REP.open then return end
        if type(grndUiBlocked) == "function" and grndUiBlocked() then return end
        local nick, pid, msg, cnt = grndCatchParse(text)
        if not nick then return end
        GRND_CATCH.caught = (GRND_CATCH.caught or 0) + 1
        GRND_REP.dialogId = -1
        GRND_REP.author = nick
        GRND_REP.playerId = pid
        GRND_REP.question = msg
        GRND_REP.reportCount = cnt
        GRND_REP.sourceCaption = "catch"
        GRND_REP.sourceText = tostring(text or "")
        GRND_REP.lastAction = ""
        GRND_REP.seenKey = "catch|" .. tostring(text)
        GRND_REP.answer = nil
        GRND_REP.open = true
        GRND_CATCH.active = false
        pcall(grndRepHudAdd, nick, pid, msg, cnt)
        if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    end
    GRND_REPHUD.botWin = 12
    function grndRepHudBotOnChat(text)
        local H = GRND_REPHUD
        if not H then return false end
        local t = tostring(text or "")
        if t == "" then return false end
        local WIN = tonumber(H.botWin) or 12
        local tNow = os.clock()
        local b = H.bot
        if type(b) ~= "table" then b = {} H.bot = b end
        if b.lateAt and (tNow - b.lateAt) > WIN then b.lateAt, b.lateSec = nil, nil end
        if b.pmAt and (tNow - b.pmAt) > WIN then b.pmId, b.pmCmd, b.pmAt = nil, nil, nil end
        local raw = grndRepUtf(t)
        raw = raw:gsub("{%x%x%x%x%x%x}", ""):gsub("\194\160", " "):gsub("\239\187\191", "")
        local function markLate(pid)
            if type(H.items) ~= "table" then return end
            for i = 1, #H.items do
                local it = H.items[i]
                if tostring(it.pid) == tostring(pid) then
                    it.late, it.lateSec, it.bot = true, b.lateSec, true
                end
            end
        end
        local function applyPm(pid)
            if not b.pmCmd or type(H.items) ~= "table" then return end
            for i = 1, #H.items do
                local it = H.items[i]
                if tostring(it.pid) == tostring(pid) then it.pmCmd = b.pmCmd end
            end
        end
        local function addReport(nick, pid, msg, cnt)
            if type(_G.grndQrAutoOnReport) == "function" then
                pcall(_G.grndQrAutoOnReport, nick, pid, msg)
            end
            grndRepHudAdd(nick, pid, msg, cnt)
            if b.lateAt then
                markLate(pid)
                b.lateAt, b.lateSec = nil, nil
            end
            applyPm(pid)
        end
        local handled = false
        local blockPid = nil
        for line in (raw .. "\n"):gmatch("([^\n]*)\n") do
            local text = line:gsub("^%s+", ""):gsub("%s+$", "")
            if text ~= "" then
                local body, hasPrefix = nil, false
                if type(grndFormAdminLine) == "function" then
                    local okL, lNick, lId, lBody = pcall(grndFormAdminLine, text)
                    if okL and type(lBody) == "string" then
                        hasPrefix = true
                        body = lBody:match("^%s*>+%s*(.*)$")
                        if body == "" then body = nil end
                    end
                end
                if (not hasPrefix) and b.lateAt and (tNow - b.lateAt) <= 3 then
                    body = text
                end
                if body then
                    local cNick, cId, cMsg, cCnt = nil, nil, nil, nil
                    if type(grndCatchParse) == "function" then
                        cNick, cId, cMsg, cCnt = grndCatchParse(body)
                    end
                    local low = grndLowerUtf(body)
                    local clean = grndRepClean(body)
                    local nick, pid, msg
                    if not cNick then
                        nick, pid, msg = clean:match("^([^%(%):]+)%s*%((%d+)%)%s*:%s*(.*)$")
                    end
                    if cNick then
                        addReport(cNick, cId, cMsg, cCnt)
                        blockPid, handled = tostring(cId), true
                    elseif nick and pid then
                        nick = nick:gsub("^%s+", ""):gsub("%s+$", "")
                        msg = grndRepClean(msg or "")
                        if msg == "" then msg = "текст репорта" end
                        if nick ~= "" then
                            addReport(nick, pid, msg, nil)
                            blockPid, handled = tostring(pid), true
                        end
                    else
                        local secs = low:match("не ответили за%s*(%d+)")
                        if secs then
                            local seconds = tonumber(secs) or 60
                            local fresh = nil
                            if type(H.items) == "table" then
                                local it0 = H.items[1]
                                if it0 and not it0.late and (os.clock() - (it0.at or 0)) < 1 then
                                    fresh = it0.pid
                                end
                            end
                            if blockPid then
                                b.lateSec = seconds
                                markLate(blockPid)
                            elseif fresh then
                                b.lateSec = seconds
                                markLate(fresh)
                            else
                                b.lateAt, b.lateSec = os.clock(), seconds
                            end
                            handled = true
                        else
                            local pmCmd, pmId = low:match("ответить игроку:%s*(/%a+)%s*(%d+)")
                            if pmCmd then
                                b.pmId = tostring(pmId)
                                b.pmCmd = tostring(pmCmd) .. " " .. tostring(pmId)
                                b.pmAt = os.clock()
                                applyPm(b.pmId)
                                handled = true
                            end
                        end
                    end
                end
            end
        end
        return handled
    end
    local function grndRepHudOnChat(text)
        grndRepHudTaken(text)
        local okBot, botHit = pcall(grndRepHudBotOnChat, text)
        if okBot and botHit then return end
        local nick, pid, msg, cnt = grndCatchParse(text)
        if nick and type(_G.grndQrAutoOnReport) == "function" then
            pcall(_G.grndQrAutoOnReport, nick, pid, msg)
        end
        if not GRND_REPHUD.enabled then return end
        if not nick then return end
        grndRepHudAdd(nick, pid, msg, cnt)
    end
    local function grndFormsOnChat(text)
        if type(grndUiBlocked) == "function" and grndUiBlocked() then return end
        if not text or text == "" then return end
        if GRND_ADMIN_CFG and GRND_ADMIN_CFG.autoForms == false then return end
        local nick,adminId,msg=grndFormAdminLine(text)
        if not nick or not adminId or not msg then return end
        if tostring(nick):lower() == "grnd_bot" then return end
        if msg:find("Пример правильной команды", 1, true) or msg:find("Пропиши форму", 1, true)
            or msg:find("отклонена", 1, true) or msg:find("принята.", 1, true) then
            return
        end
        local idStr=tostring(adminId)
        local myId = nil
        if type(sampGetLocalPlayerId) == "function" then
            local okI, mid = pcall(sampGetLocalPlayerId)
            if okI and type(mid) == "number" then myId = mid end
        end
        if myId and tonumber(idStr) == myId then return end
        local cmd = msg:match("(/%a[%w_]*.*)")
        if cmd then
            cmd = cmd:gsub("^%s+", ""):gsub("%s+$", "")
            if #cmd < 2 or cmd:sub(1, 1) ~= "/" then cmd = nil end
        end
        if not cmd then return end
        local commandName = grndFormCommandName(cmd)
        if not grndFormIsAllowed(commandName) then return end
        local now = os.clock()
        local newForm = {
            adminNick = nick,
            adminId = tonumber(idStr) or 0,
            cmd = cmd,
            time = now,
            openedAt = nil,
        }
        _G.GRND_FORMS = _G.GRND_FORMS or { active = nil, queue = {} }
        local forms = _G.GRND_FORMS
        if type(forms.queue) ~= "table" then forms.queue = {} end
        local key = grndFormKey(newForm)
        local doneAt = type(forms.done) == "table" and forms.done[key] or nil
        if doneAt and (now - doneAt) < 3.0 then return end
        if forms.active and grndFormKey(forms.active) == key then return end
        for _, q in ipairs(forms.queue) do
            if grndFormKey(q) == key then return end
        end
        local gapEnd = tonumber(forms.nextAt) or 0
        if not forms.active then
            if gapEnd > now then
                newForm.showAt = gapEnd
                newForm.openedAt = gapEnd
            else
                newForm.openedAt = now
            end
            forms.active = newForm
        else
            table.insert(forms.queue, newForm)
        end
        if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    end
    _G.grndFormsOnChat = grndFormsOnChat
    local function grndRepHudOpenItem(it)
        if not it then return end
        if type(grndUiBlocked) == "function" and grndUiBlocked() then return end
        GRND_REP.dialogId = -1
        GRND_REP.author = it.nick
        GRND_REP.playerId = tostring(it.pid)
