        GRND_REP.reportCount = it.cnt
        GRND_REP.sourceCaption = "hud"
        GRND_REP.sourceText = ""
        GRND_REP.lastAction = ""
        GRND_REP.seenKey = "hud|" .. tostring(it.pid)
        GRND_REP.answer = nil
        GRND_REP.replyCmd = it.pmCmd
        GRND_REP.replyPid = it.pmCmd and tostring(it.pid) or nil
        GRND_REP.late = it.late and true or nil
        GRND_REP.open = true
        if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    end
    function _G.grndCatchToggle()
        GRND_CATCH.active = not GRND_CATCH.active
        if GRND_CATCH.active then
            GRND_CATCH.startedAt = os.clock()
            GRND_CATCH.caught = 0
            if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
            if notify and notify.add then pcall(notify.add, "Автоловля репорта: включена", "ok", 2) end
        else
            if notify and notify.add then pcall(notify.add, "Автоловля репорта: выключена", "info", 2) end
        end
    end
    local function grndRepChatQuestion(pid)
        local e = GRND_REP_CHAT[tostring(pid)]
        if e and os.clock() - e.at < 600 then return e.text end
        return nil
    end
    local function grndRepExtractQuestion(raw)
        local text = grndRepUtf(raw)
        text = text:gsub("{%x%x%x%x%x%x}", "")
        local a = text:find("Жалоба/Вопрос:", 1, true)
        local b = a and text:find("Введите ответ:", a + 1, true) or nil
        if a then
            local q = text:sub(a + #"Жалоба/Вопрос:", (b and b - 1) or #text)
            q = grndRepClean(q)
            if q ~= "" then return q end
        end
        for line in (text .. "\n"):gmatch("([^\n]*)\n") do
            line = grndRepClean(line)
            if line ~= "" and not line:find("Игрок:", 1, true)
               and not line:find("Введите ответ", 1, true)
               and not line:find("Жалоба/Вопрос", 1, true) then
                return line
            end
        end
        return "текст репорта"
    end
    local function grndRepSet(dialogId, caption, text)
        if type(grndUiBlocked) == "function" and grndUiBlocked() then
            GRND_REP.blockedAt = os.clock()
            return false
        end
        local cap = grndRepUtf(caption)
        local body = grndRepUtf(text)
        local full = cap .. "\n" .. body
        grndRepDump(dialogId, caption, text)
        local nick, pid = full:match("([%w_%.%-]+)%s*%[(%d+)%]")
        if not nick or nick == "" then nick = grndRepClean(cap) end
        if nick == "" then nick = "Игрок" end
        if not pid or pid == "" then pid = "?" end
        GRND_REP.dialogId = tonumber(dialogId) or -1
        GRND_REP.author = nick
        GRND_REP.playerId = pid
        GRND_REP.question = grndRepExtractQuestion(text)
        do
            local q = GRND_REP.question or ""
            local looksEmpty = (q == "текст репорта") or q:find("^%??%s*[%w_%.%-]*%s*%[%d+%]%s*$") ~= nil
            if looksEmpty then
                local fromChat = grndRepChatQuestion(pid)
                if fromChat then GRND_REP.question = fromChat end
            end
        end
        GRND_REP.sourceCaption = tostring(caption or "")
        GRND_REP.sourceText = tostring(text or "")
        GRND_REP.lastAction = ""
        GRND_REP.seenKey = tostring(dialogId) .. "|" .. tostring(caption) .. "|" .. tostring(text)
        GRND_REP.answer = nil
        GRND_REP.open = true
        if type(_G.ensureRender) == "function" then pcall(_G.ensureRender, true) end
    end
    local function grndRepToAnsi(str)
        -- Normalize once at the SA:MP boundary. grndAnsiText is UTF-8-aware and
        -- leaves already-CP1251 bytes unchanged; unconditional UTF8:decode here
        -- corrupted legacy CP1251 reasons on the direct /ans path.
        str = tostring(str or "")
        if type(_G.grndAnsiText) == "function" then
            local ok, out = pcall(_G.grndAnsiText, str)
            if ok and type(out) == "string" then return out end
        end
        return str
    end
    GRND_REP.queue = GRND_REP.queue or {}
    function grndRepQueue(cmd)
        if type(cmd) ~= "string" or cmd == "" then return end
        GRND_REP.queue[#GRND_REP.queue + 1] = cmd
    end
    function grndRepQueueTick()
        local q = GRND_REP.queue
        if not q or #q == 0 then return end
        local now = os.clock()
        if now - (GRND_REP.queueAt or 0) < 0.35 then return end
        GRND_REP.queueAt = now
        local cmd = table.remove(q, 1)
        if type(sampSendChat) == "function" then pcall(sampSendChat, cmd) end
    end
    function grndRepAnswer(pid, text)
        pid = tostring(pid or "")
        if not pid:match("^%d+$") then return false end
        local enc = grndRepToAnsi(text)
        if type(_G.grndQrAnswerCmd) == "function" then
            grndRepQueue(_G.grndQrAnswerCmd(pid, enc))
            pcall(grndRepHudRemove, pid)
            return true
        end
        local rc = GRND_REP.replyCmd
        if type(rc) == "string" and rc ~= "" and tostring(GRND_REP.replyPid or "") == pid then
            grndRepQueue(rc:gsub("%d+", pid) .. " " .. enc)
        else
            grndRepQueue("/ans " .. pid .. " " .. enc)
        end
        pcall(grndRepHudRemove, pid)
        return true
    end
    local function grndRepPoll()
        if not grndSessionReady() then return end
        if GRND_REP.open then return end
        local QR = _G.GRND_QR
        if type(QR) == "table" and type(QR.punReq) == "table" and QR.punReq.on then
            return
        end
        local now = os.clock()
        if now - (GRND_REP.pollAt or 0) < 0.10 then return end
        GRND_REP.pollAt = now
        if type(sampIsDialogActive) ~= "function"
           or type(sampGetCurrentDialogId) ~= "function" then return end
        local okA, active = pcall(sampIsDialogActive)
        if not (okA and active) then return end
        local okId, id = pcall(sampGetCurrentDialogId)
        if not okId then return end
        local caption, text = "", ""
        if type(sampGetDialogCaption) == "function" then
            local ok, v = pcall(sampGetDialogCaption)
            if ok and type(v) == "string" then caption = v end
        end
        if type(sampGetDialogText) == "function" then
            local ok, v = pcall(sampGetDialogText)
            if ok and type(v) == "string" then text = v end
        end
        if not grndRepAcceptDialog(id, caption, text) then return end
        grndRepSet(id, caption, text)
    end
    local AUTH = {
        showedLoaded = false,
        showedAuthOk = false,
        windowSeen = false,
        closedAt = nil,
        attemptFailed = false,
        failCountBase = 0,
        okDelay = 2.5,
        panelOpen = false,
        ok = false,
        dialog = false,
        spawned = false,
        failScanAt = 0,
    }
    _G.GRND_AUTH_STATE = AUTH

    do
    -- =========================================================================
    -- Новые модули интерфейса v1.28: Общие расширения, Капсулы, Недельная
    -- статистика, Чекер игроков (основы + твинки), Встроенный Chromium-браузер
    -- (Chrome + Сайт жалоб без внешних SDK DLL) и Поиск функций
    -- =========================================================================
    GRND_MAIN_EXT = _G.GRND_MAIN_EXT or {
        pauseMenu = false,
        lodOn = false,
        lodDist = 1200,
        lodMult = 1.5,
        formAcceptOn = false,
        formAcceptTpl = "[ATools]: +",
        formRejectOn = false,
        formRejectTpl = "[ATools]: Неверно указана форма / ID",
        formSoftOn = false,
        formSoftTpl = "/a [SoftCheck] {nick}[{id}] — вызов на проверку",
        customDlgOn = false,
        customDlgSearch = true,
        wsHudOn = false,
        wsX = nil,
        wsY = nil,
        wsScale = 0.85,
        -- Safe default: reloading an authenticated complaint form can lose unsaved work.
        complaintsAuto = false,
        complaintsEvery = 3,
        complaintsZoom = 80,
        chromeZoom = 100,
        pActHp = 100,
        pActArm = 100,
        pActFuel = 150,
        pActHelpTpl = "/a Игрок {nick}[{id}] нуждается в помощи!",
        pActSpecTpl = "/a Слежу за игроком {nick}[{id}]",
    }
    _G.GRND_MAIN_EXT = GRND_MAIN_EXT

    local function grndEscCfgStr(s)
        s = tostring(s or ""):gsub("[\r\n]+", " ")
        return s
    end
    function _G.grndMainExtSaveLines(f)
        if not f then return end
        local E = GRND_MAIN_EXT
        f:write("mext_pauseMenu=" .. (E.pauseMenu and "1" or "0") .. "\n")
        f:write("mext_lodOn=" .. (E.lodOn and "1" or "0") .. "\n")
        f:write("mext_lodDist=" .. tostring(math.floor(tonumber(E.lodDist) or 1200)) .. "\n")
        f:write("mext_lodMult=" .. string.format("%.2f", tonumber(E.lodMult) or 1.5) .. "\n")
        f:write("mext_formAcceptOn=" .. (E.formAcceptOn and "1" or "0") .. "\n")
        f:write("mext_formAcceptTpl=" .. grndEscCfgStr(E.formAcceptTpl) .. "\n")
        f:write("mext_formRejectOn=" .. (E.formRejectOn and "1" or "0") .. "\n")
        f:write("mext_formRejectTpl=" .. grndEscCfgStr(E.formRejectTpl) .. "\n")
        f:write("mext_formSoftOn=" .. (E.formSoftOn and "1" or "0") .. "\n")
        f:write("mext_formSoftTpl=" .. grndEscCfgStr(E.formSoftTpl) .. "\n")
        f:write("mext_customDlgOn=" .. (E.customDlgOn and "1" or "0") .. "\n")
        f:write("mext_customDlgSearch=" .. (E.customDlgSearch and "1" or "0") .. "\n")
        f:write("mext_wsHudOn=" .. (E.wsHudOn and "1" or "0") .. "\n")
        if tonumber(E.wsX) then f:write("mext_wsX=" .. tostring(math.floor(E.wsX)) .. "\n") end
        if tonumber(E.wsY) then f:write("mext_wsY=" .. tostring(math.floor(E.wsY)) .. "\n") end
        f:write("mext_wsScale=" .. string.format("%.2f", tonumber(E.wsScale) or 0.85) .. "\n")
        f:write("mext_complaintsAuto=" .. (E.complaintsAuto and "1" or "0") .. "\n")
        f:write("mext_complaintsEvery=" .. tostring(math.max(3, math.min(60, math.floor(tonumber(E.complaintsEvery) or 3)))) .. "\n")
        f:write("mext_complaintsZoom=" .. tostring(math.max(50, math.min(150, math.floor(tonumber(E.complaintsZoom) or 80)))) .. "\n")
        f:write("mext_chromeZoom=" .. tostring(math.max(50, math.min(150, math.floor(tonumber(E.chromeZoom) or 100)))) .. "\n")
        f:write("mext_pActHp=" .. tostring(math.max(1, math.min(200, math.floor(tonumber(E.pActHp) or 100)))) .. "\n")
        f:write("mext_pActArm=" .. tostring(math.max(0, math.min(100, math.floor(tonumber(E.pActArm) or 100)))) .. "\n")
        f:write("mext_pActFuel=" .. tostring(math.max(10, math.min(150, math.floor(tonumber(E.pActFuel) or 150)))) .. "\n")
        f:write("mext_pActHelpTpl=" .. grndEscCfgStr(E.pActHelpTpl) .. "\n")
        f:write("mext_pActSpecTpl=" .. grndEscCfgStr(E.pActSpecTpl) .. "\n")
        if _G.GRND_WEEKSTATS then
            _G.GRND_WEEKSTATS.hudOn = E.wsHudOn == true
            _G.GRND_WEEKSTATS.x = E.wsX
            _G.GRND_WEEKSTATS.y = E.wsY
            _G.GRND_WEEKSTATS.scale = E.wsScale
        end
    end
    function _G.grndMainExtLoadLine(key, v, num)
        local E = GRND_MAIN_EXT
        if key == "pauseMenu" then E.pauseMenu = (v == "1")
        elseif key == "lodOn" then E.lodOn = (v == "1")
        elseif key == "lodDist" and num then E.lodDist = math.max(300, math.min(3600, math.floor(num)))
        elseif key == "lodMult" and num then E.lodMult = math.max(1.0, math.min(3.0, num))
        elseif key == "formAcceptOn" then E.formAcceptOn = (v == "1")
        elseif key == "formAcceptTpl" and v ~= "" then E.formAcceptTpl = v
        elseif key == "formRejectOn" then E.formRejectOn = (v == "1")
        elseif key == "formRejectTpl" and v ~= "" then E.formRejectTpl = v
        elseif key == "formSoftOn" then E.formSoftOn = (v == "1")
        elseif key == "formSoftTpl" and v ~= "" then E.formSoftTpl = v
        elseif key == "customDlgOn" then E.customDlgOn = (v == "1")
        elseif key == "customDlgSearch" then E.customDlgSearch = (v == "1")
        elseif key == "wsHudOn" then
            E.wsHudOn = (v == "1")
            if _G.GRND_WEEKSTATS then _G.GRND_WEEKSTATS.hudOn = E.wsHudOn end
        elseif key == "wsX" and num then
            E.wsX = num
            if _G.GRND_WEEKSTATS then _G.GRND_WEEKSTATS.x = num end
        elseif key == "wsY" and num then
            E.wsY = num
            if _G.GRND_WEEKSTATS then _G.GRND_WEEKSTATS.y = num end
        elseif key == "wsScale" and num then
            E.wsScale = math.max(0.25, math.min(2.5, num))
            if _G.GRND_WEEKSTATS then _G.GRND_WEEKSTATS.scale = E.wsScale end
        elseif key == "complaintsAuto" then E.complaintsAuto = (v == "1")
        elseif key == "complaintsEvery" and num then E.complaintsEvery = math.max(3, math.min(60, math.floor(num)))
        elseif key == "complaintsZoom" and num then E.complaintsZoom = math.max(50, math.min(150, math.floor(num)))
        elseif key == "chromeZoom" and num then E.chromeZoom = math.max(50, math.min(150, math.floor(num)))
        elseif key == "pActHp" and num then E.pActHp = math.max(1, math.min(200, math.floor(num)))
        elseif key == "pActArm" and num then E.pActArm = math.max(0, math.min(100, math.floor(num)))
        elseif key == "pActFuel" and num then E.pActFuel = math.max(10, math.min(150, math.floor(num)))
        elseif key == "pActHelpTpl" and v ~= "" then E.pActHelpTpl = v
        elseif key == "pActSpecTpl" and v ~= "" then E.pActSpecTpl = v
        end
    end

    -- 1) Дальность прорисовки (безопасная проверка сигнатуры GTA:SA 1.0 US + откат)
    GRND_LOD = _G.GRND_LOD or { savedFar = nil, active = false, checked = false, supported = false }
    _G.GRND_LOD = GRND_LOD
    local function grndLodCheckSupported()
        local L = GRND_LOD
        if L.checked then return L.supported end
        L.checked = true
        local mem = libs and libs.memory or rawget(_G, "memory")
        if type(mem) ~= "table" or type(mem.getuint16) ~= "function"
            or type(mem.getfloat) ~= "function" or type(mem.setfloat) ~= "function" then
            L.supported = false
            return false
        end
        local okSig, sig = pcall(mem.getuint16, 0x82457C, true)
        local okCur, cur = pcall(mem.getfloat, 0xB7C4F0, true)
        if okSig and sig == 0x94BF and okCur and type(cur) == "number" and cur >= 50 and cur <= 10000 then
            L.supported = true
            L.mem = mem
            return true
        end
        L.supported = false
        return false
    end
    function _G.grndLodRestore()
        local L = GRND_LOD
        if L.active and L.savedFar and L.mem then
            pcall(L.mem.setfloat, 0xB7C4F0, L.savedFar, true)
        end
        L.active = false
        L.savedFar = nil
    end
    function _G.grndLodTick()
        local E = GRND_MAIN_EXT
        local L = GRND_LOD
        if not (E and E.lodOn) then
            if L.active then _G.grndLodRestore() end
            return
        end
        if not grndLodCheckSupported() then return end
        local want = math.max(300, math.min(3600, tonumber(E.lodDist) or 1200))
        local okCur, cur = pcall(L.mem.getfloat, 0xB7C4F0, true)
        if okCur and type(cur) == "number" and cur > 10 then
            if not L.active then
                L.savedFar = cur
                L.active = true
            end
            if math.abs(cur - want) > 1.0 then
                pcall(L.mem.setfloat, 0xB7C4F0, want, true)
            end
        end
    end
    if type(grndMemoryRegisterRollback) == "function" then
        pcall(grndMemoryRegisterRollback, "grnd-lod-farclip", _G.grndLodRestore)
    end
    if type(grndOnTerm) == "function" then
        pcall(grndOnTerm, _G.grndLodRestore)
    end

    -- 2) Меню паузы "Grnd Tools" (без опасных патчей CMenuManager)
    GRND_PAUSE_MENU = _G.GRND_PAUSE_MENU or { wasPaused = false, hintShownAt = -999 }
    _G.GRND_PAUSE_MENU = GRND_PAUSE_MENU
    function _G.grndPauseMenuOpenSettings()
        local m = GRND_REF and GRND_REF.menu
        if type(m) ~= "table" then return false end
        m.open = true
        for i, t in ipairs(MENU_TABS) do
            if t.id == "settings" then m.tab = i; break end
        end
        if type(_G.grndEnsureRender) == "function" then pcall(_G.grndEnsureRender, true) end
        return true
    end
    function _G.grndPauseMenuTick()
        local E = GRND_MAIN_EXT
        if not (E and E.pauseMenu) then
            GRND_PAUSE_MENU.wasPaused = false
            return
        end
        local paused = false
        if type(isPauseMenuActive) == "function" then
            local ok, v = pcall(isPauseMenuActive)
            paused = (ok and v) and true or false
        end
        if paused and not GRND_PAUSE_MENU.wasPaused then
            GRND_PAUSE_MENU.enteredAt = os.clock()
        elseif not paused and GRND_PAUSE_MENU.wasPaused then
            if type(isKeyDown) == "function" then
                local okF2, downF2 = pcall(isKeyDown, 0x71) -- F2
                if okF2 and downF2 then _G.grndPauseMenuOpenSettings() end
            end
        end
        GRND_PAUSE_MENU.wasPaused = paused
    end

    -- 3) Автоматизация форм (принята / неверно выдано / шаблон SoftCheck)
    function _G.grndFormFormatTpl(tpl, form)
        local s = tostring(tpl or "")
        if type(form) ~= "table" then return s end
        local cmd = tostring(form.cmd or "")
        local targetId = tostring(form.targetId or cmd:match("^/%S+%s+(%d+)") or "")
        local targetNick = ""
        if targetId ~= "" and tonumber(targetId) and type(sampGetPlayerNickname) == "function" then
            local okN, rawN = pcall(sampGetPlayerNickname, tonumber(targetId))
            if okN and type(rawN) == "string" and rawN ~= "" then
                targetNick = grndUtf8Text(rawN)
            end
        end
        local admNick = grndUtf8Text(tostring(form.adminNick or ""))
        local admId = tostring(form.adminId or "")
        s = s:gsub("{id}", targetId ~= "" and targetId or "?")
        s = s:gsub("{nick}", targetNick ~= "" and targetNick or ("ID " .. (targetId ~= "" and targetId or "?")))
        s = s:gsub("{admin}", admNick ~= "" and admNick or "Admin")
        s = s:gsub("{admin_id}", admId)
        s = s:gsub("{cmd}", cmd)
        return s
    end
    local function grndFormSendAutoLine(rawLine)
        local line = tostring(rawLine or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if line == "" then return false end
        if line:sub(1, 1) ~= "/" then line = "/a " .. line end
        if type(grndChatSend) == "function" then
            pcall(grndChatSend, line)
            return true
        elseif type(sampSendChat) == "function" then
            pcall(sampSendChat, line)
            return true
        end
        return false
    end
    function _G.grndFormsOnResolved(kind, form, sentCmd, sentStatus, sentWhy)
        local E = GRND_MAIN_EXT
        if type(E) ~= "table" or type(form) ~= "table" then return end
        if kind == "accept" then
            if sentStatus == "bad" then
                if E.formRejectOn and E.formRejectTpl ~= "" then
                    grndFormSendAutoLine(_G.grndFormFormatTpl(E.formRejectTpl, form))
                end
                return
            end
            if sentStatus ~= "redirected" then
                if type(_G.grndWeekStatsBump) == "function" then
                    pcall(_G.grndWeekStatsBump, "forms", 1)
                end
                if E.formAcceptOn and E.formAcceptTpl ~= "" then
                    grndFormSendAutoLine(_G.grndFormFormatTpl(E.formAcceptTpl, form))
                end
                if E.formSoftOn and E.formSoftTpl ~= "" then
                    local low = grndLowerUtf(tostring(form.cmd or "") .. " " .. tostring(form.raw or ""))
                    if low:find("чит", 1, true) or low:find("софт", 1, true)
                        or low:find("soft", 1, true) or low:find("cheat", 1, true)
                        or low:find("проверк", 1, true) then
                        grndFormSendAutoLine(_G.grndFormFormatTpl(E.formSoftTpl, form))
                    end
                end
            end
        elseif kind == "reject" then
            if E.formRejectOn and E.formRejectTpl ~= "" then
                grndFormSendAutoLine(_G.grndFormFormatTpl(E.formRejectTpl, form))
            end
        end
    end

    -- 4) Кастомные серверные диалоги (безопасная панель-компаньон с поиском и копированием)
    GRND_CUSTOM_DLG = _G.GRND_CUSTOM_DLG or { cur = nil, filter = "" }
    _G.GRND_CUSTOM_DLG = GRND_CUSTOM_DLG
    function _G.grndCustomDialogObserve(dialogId, style, title, button1, button2, text)
        local E = GRND_MAIN_EXT
        if not (E and E.customDlgOn) then
            GRND_CUSTOM_DLG.cur = nil
            return
        end
        style = tonumber(style) or -1
        -- Никогда не перехватываем пароли/авторизацию (style 3)
        if style == 3 or (type(grndAuthDialogOpen) == "function" and grndAuthDialogOpen()) then
            GRND_CUSTOM_DLG.cur = nil
            return
        end
        local cleanTitle = grndUtf8Text(tostring(title or "")):gsub("{%x%x%x%x%x%x}", "")
        local rawUtf = grndUtf8Text(tostring(text or "")):gsub("{%x%x%x%x%x%x}", "")
        local lines = {}
        for ln in (rawUtf .. "\n"):gmatch("([^\r\n]*)\r?\n") do
            if ln ~= "" then lines[#lines + 1] = ln end
            if #lines >= 200 then break end
        end
        GRND_CUSTOM_DLG.cur = {
            id = tonumber(dialogId) or 0,
            style = style,
            title = cleanTitle ~= "" and cleanTitle or ("Диалог #" .. tostring(dialogId)),
            b1 = grndUtf8Text(tostring(button1 or "")),
            b2 = grndUtf8Text(tostring(button2 or "")),
            lines = lines,
            raw = rawUtf,
            at = os.clock(),
        }
        if type(_G.grndEnsureRender) == "function" then pcall(_G.grndEnsureRender, true) end
    end
    GRND_CUSTOM_DLG.wantUi = function()
        if not (GRND_MAIN_EXT and GRND_MAIN_EXT.customDlgOn) then return false end
        if not GRND_CUSTOM_DLG.cur then return false end
        if type(grndServerDialogOpen) == "function" and not grndServerDialogOpen() then
            GRND_CUSTOM_DLG.cur = nil
            return false
        end
        return true
    end

    -- 5) Плавающие капсульные уведомления (ЧЕКЕР сверху по центру, Новый репорт снизу по центру)
    GRND_CAP_NOTIFY = _G.GRND_CAP_NOTIFY or { items = {}, seq = 0 }
    _G.GRND_CAP_NOTIFY = GRND_CAP_NOTIFY
    function _G.grndPushCheckerCapsule(badge, text, kind, life)
        local C = GRND_CAP_NOTIFY
        text = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if text == "" then return false end
        local badgeText = tostring(badge or "ЧЕКЕР")
        local now = os.clock()
        for i = #C.items, 1, -1 do
            local old = C.items[i]
            if old.slot == "top" and old.badge == badgeText and old.text == text then
                old.count = (tonumber(old.count) or 1) + 1
                old.start = now
                old.life = math.max(1.5, math.min(12, tonumber(life) or 4.5))
                return true
            end
        end
        C.seq = (C.seq or 0) + 1
        C.items[#C.items + 1] = {
            id = C.seq,
            slot = "top",
            badge = badgeText,
            text = text:sub(1, 240),
            kind = kind or "info",
            start = now,
            life = math.max(1.5, math.min(12, tonumber(life) or 4.5)),
        }
        while #C.items > 8 do
            local drop
            for i = 1, #C.items do
                if C.items[i].slot ~= "bottom" then drop = i; break end
            end
            if not drop then break end
            table.remove(C.items, drop)
        end
        if type(_G.grndEnsureRender) == "function" then pcall(_G.grndEnsureRender, true) end
        return true
    end
    function _G.grndPushReportCapsule(nick, pid, msg, cnt)
        if GRND_ADMIN_CFG and GRND_ADMIN_CFG.repToasts == false then return false end
        if type(grndSessionReady) == "function" then
            local okR, rdy = pcall(grndSessionReady)
            if okR and not rdy then return false end
        end
        local C = GRND_CAP_NOTIFY
        local cleanNick = grndUtf8Text(tostring(nick or "Игрок")):gsub("{%x%x%x%x%x%x}", "")
        local cleanPid = tostring(pid or "?")
        local cleanMsg = grndUtf8Text(tostring(msg or "")):gsub("{%x%x%x%x%x%x}", ""):gsub("%s+", " ")
        local now = os.clock()
        for i = #C.items, 1, -1 do
            if C.items[i].slot == "bottom" and tostring(C.items[i].pid) == cleanPid then
                C.items[i].nick = cleanNick
                C.items[i].title = "Новый репорт: " .. cleanNick .. "[" .. cleanPid .. "]"
                if cleanMsg ~= "" then C.items[i].text = cleanMsg end
                C.items[i].start = now
                return true
            end
        end
        C.seq = (C.seq or 0) + 1
        C.items[#C.items + 1] = {
            id = C.seq,
            slot = "bottom",
            badge = "РЕПОРТ",
            nick = cleanNick,
            pid = cleanPid,
            title = "Новый репорт: " .. cleanNick .. "[" .. cleanPid .. "]",
            text = cleanMsg ~= "" and cleanMsg or "Новое обращение от игрока",
            kind = "report",
            start = now,
            life = 5.5,
        }
        while #C.items > 8 do table.remove(C.items, 1) end
        if type(_G.grndEnsureRender) == "function" then pcall(_G.grndEnsureRender, true) end
        return true
    end

    -- 6) Недельная статистика администратора (GRND_WEEKSTATS + HUD на экране)
    GRND_WEEKSTATS = _G.GRND_WEEKSTATS or {
        days = {},
        loaded = false,
        dirty = false,
        lastSaveAt = 0,
        lastSecAt = nil,
        hudOn = GRND_MAIN_EXT.wsHudOn == true,
        x = GRND_MAIN_EXT.wsX,
        y = GRND_MAIN_EXT.wsY,
        scale = GRND_MAIN_EXT.wsScale or 0.85,
        moving = false,
        anim = 0,
    }
    _G.GRND_WEEKSTATS = GRND_WEEKSTATS
    local function wsPath()
        return grndStoragePath("cache", "week_stats.txt")
    end
    local function wsTodayKey()
        return os.date("%Y-%m-%d")
    end
    local function wsEnsureDay(dayKey)
        local W = GRND_WEEKSTATS
        W.days = W.days or {}
        local d = W.days[dayKey]
        if type(d) ~= "table" then
            d = { reports = 0, punish = 0, jail = 0, mute = 0, ban = 0, warn = 0, kick = 0, forms = 0, onlineSec = 0 }
            W.days[dayKey] = d
        end
        return d
    end
    function _G.grndWeekStatsLoad()
        local W = GRND_WEEKSTATS
        if W.loaded then return true end
        W.loaded = true
        local okO, fh = pcall(io.open, wsPath(), "r")
        if not okO or not fh then return false end
        local okR, content = pcall(function() return fh:read("*a") end)
        pcall(function() fh:close() end)
        if not okR or type(content) ~= "string" then return false end
        for line in content:gmatch("[^\r\n]+") do
            local dt, k, val = line:match("^(%d%d%d%d%-%d%d%-%d%d)|([%w_]+)=(%d+)$")
            if dt and k and val then
                local d = wsEnsureDay(dt)
                d[k] = tonumber(val) or 0
            end
        end
        return true
    end
    function _G.grndWeekStatsSave()
        local W = GRND_WEEKSTATS
        local okO, fh = pcall(io.open, wsPath(), "w")
        if not okO or not fh then return false end
        local keep = {}
        local nowTs = os.time()
        for i = 0, 13 do
            keep[os.date("%Y-%m-%d", nowTs - i * 86400)] = true
        end
        pcall(function()
            for dt, d in pairs(W.days or {}) do
                if keep[dt] and type(d) == "table" then
                    for _, field in ipairs({ "reports", "punish", "jail", "mute", "ban", "warn", "kick", "forms", "onlineSec" }) do
                        fh:write(string.format("%s|%s=%d\n", dt, field, math.max(0, math.floor(tonumber(d[field]) or 0))))
                    end
                end
            end
            fh:close()
        end)
        W.dirty = false
        W.lastSaveAt = os.clock()
        return true
    end
    function _G.grndWeekStatsBump(field, delta)
        _G.grndWeekStatsLoad()
        local d = wsEnsureDay(wsTodayKey())
        delta = tonumber(delta) or 1
        d[field] = math.max(0, (tonumber(d[field]) or 0) + delta)
        if field == "jail" or field == "mute" or field == "ban" or field == "warn" or field == "kick" then
            d.punish = math.max(0, (tonumber(d.punish) or 0) + delta)
        end
        GRND_WEEKSTATS.dirty = true
    end
    function _G.grndWeekStatsTotals()
        _G.grndWeekStatsLoad()
        local todayKey = wsTodayKey()
        local today = wsEnsureDay(todayKey)
        local week = { reports = 0, punish = 0, jail = 0, mute = 0, ban = 0, warn = 0, kick = 0, forms = 0, onlineSec = 0 }
        local history = {}
        local nowTs = os.time()
        for i = 0, 6 do
            local k = os.date("%Y-%m-%d", nowTs - i * 86400)
            local label = os.date("%d.%m", nowTs - i * 86400)
            local d = wsEnsureDay(k)
            for field in pairs(week) do
                week[field] = week[field] + (tonumber(d[field]) or 0)
            end
            history[#history + 1] = { key = k, label = label, data = d }
        end
        return today, week, history
    end
    function _G.grndWeekStatsOnChat(rawText)
        if type(rawText) ~= "string" or rawText == "" then return end
        local myNick = nil
        if type(sampGetLocalPlayerId) == "function" and type(sampGetPlayerNickname) == "function" then
            local okId, lid = pcall(sampGetLocalPlayerId)
            if okId and type(lid) == "number" then
                local okN, n = pcall(sampGetPlayerNickname, lid)
                if okN and type(n) == "string" and n ~= "" then myNick = grndUtf8Text(n) end
            end
        end
        local u = grndUtf8Text(rawText):gsub("{%x%x%x%x%x%x}", "")
        local low = grndLowerUtf(u)
        if myNick and myNick ~= "" and not u:find(myNick, 1, true) then return end
        if low:find("ответил", 1, true) and (low:find("репорт", 1, true) or low:find("вопрос", 1, true) or low:find("игроку", 1, true)) then
            _G.grndWeekStatsBump("reports", 1)
        elseif low:find("посадил", 1, true) or low:find("деморган", 1, true) then
            _G.grndWeekStatsBump("jail", 1)
        elseif low:find("заглушил", 1, true) or low:find("мут", 1, true) then
            _G.grndWeekStatsBump("mute", 1)
        elseif low:find("заблокировал", 1, true) or low:find("забанил", 1, true) then
            _G.grndWeekStatsBump("ban", 1)
        elseif low:find("предупрежден", 1, true) or low:find("варн", 1, true) then
            _G.grndWeekStatsBump("warn", 1)
        elseif low:find("кикнул", 1, true) then
            _G.grndWeekStatsBump("kick", 1)
        end
    end
    function _G.grndWeekStatsTick()
        local W = GRND_WEEKSTATS
        _G.grndWeekStatsLoad()
        local now = os.clock()
        if W.lastSecAt == nil then W.lastSecAt = now end
        if now - W.lastSecAt >= 1.0 then
            local addSec = math.min(5, math.floor(now - W.lastSecAt))
            W.lastSecAt = now
            if addSec > 0 and type(grndSessionReady) == "function" and grndSessionReady() then
                local d = wsEnsureDay(wsTodayKey())
                d.onlineSec = (tonumber(d.onlineSec) or 0) + addSec
                W.dirty = true
            end
        end
        if W.dirty and (now - (W.lastSaveAt or 0) >= 25.0) then
            _G.grndWeekStatsSave()
        end
    end
    function _G.grndWeekStatsStartMove()
        local W = GRND_WEEKSTATS
        W.origX, W.origY = W.x, W.y
        W.moving = true
        W.armed = false
        W.armAt = os.clock() + 0.15
        if type(_G.grndEnsureRender) == "function" then pcall(_G.grndEnsureRender, true) end
    end
    if type(grndOnTerm) == "function" then
        pcall(grndOnTerm, _G.grndWeekStatsSave)
    end

    -- 7) Чекер отслеживаемых игроков: основы + твинки (GRND_WATCH)
    GRND_WATCH = _G.GRND_WATCH or {
        list = {},
        loaded = false,
        scanAt = -99,
        online = {},
        inpMain = "",
        inpTwinks = "",
        inpNote = "",
        filter = "",
    }
    _G.GRND_WATCH = GRND_WATCH
    local function watchPath()
        return grndStoragePath("cache", "watch_players.txt")
    end
    function _G.grndWatchLoad()
        local W = GRND_WATCH
        if W.loaded then return true end
        W.loaded = true
        W.list = {}
        local okO, fh = pcall(io.open, watchPath(), "r")
        if not okO or not fh then return false end
        local okR, raw = pcall(function() return fh:read("*a") end)
        pcall(function() fh:close() end)
        if not okR or type(raw) ~= "string" then return false end
        for line in raw:gmatch("[^\r\n]+") do
            local mainNick, twinksCsv, note, added = line:match("^([^|\t]+)\t([^\t]*)\t([^\t]*)\t?(.*)$")
            if mainNick and mainNick ~= "" then
                local tw = {}
                for item in tostring(twinksCsv or ""):gmatch("[^,%s]+") do
                    tw[#tw + 1] = item
                end
                W.list[#W.list + 1] = {
                    main = mainNick,
                    twinks = tw,
                    note = note or "",
                    addedAt = (added ~= "" and added) or os.date("%d.%m.%Y"),
                }
            end
        end
        return true
    end
    function _G.grndWatchSave()
        local W = GRND_WATCH
        local okO, fh = pcall(io.open, watchPath(), "w")
        if not okO or not fh then return false end
        pcall(function()
            for _, item in ipairs(W.list or {}) do
                local m = tostring(item.main or ""):gsub("[\t\r\n]", "")
                local tw = table.concat(item.twinks or {}, ","):gsub("[\t\r\n]", "")
                local nt = tostring(item.note or ""):gsub("[\t\r\n]", " ")
                local ad = tostring(item.addedAt or "")
                if m ~= "" then
                    fh:write(m .. "\t" .. tw .. "\t" .. nt .. "\t" .. ad .. "\n")
                end
            end
            fh:close()
        end)
        return true
    end
    function _G.grndWatchAdd(mainNick, twinksStr, noteStr)
        _G.grndWatchLoad()
        mainNick = tostring(mainNick or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if mainNick == "" then return false, "Укажите основной ник" end
        local tw = {}
        for token in tostring(twinksStr or ""):gmatch("[^,;]+") do
            local clean = token:gsub("^%s+", ""):gsub("%s+$", "")
            if clean ~= "" and clean:lower() ~= mainNick:lower() then
                tw[#tw + 1] = clean
            end
        end
        local note = tostring(noteStr or ""):gsub("^%s+", ""):gsub("%s+$", "")
        for _, ex in ipairs(GRND_WATCH.list) do
            if tostring(ex.main):lower() == mainNick:lower() then
                ex.twinks = tw
                ex.note = note
                _G.grndWatchSave()
                GRND_WATCH.scanAt = -99
                return true, "updated"
            end
        end
        table.insert(GRND_WATCH.list, 1, {
            main = mainNick,
            twinks = tw,
            note = note,
            addedAt = os.date("%d.%m.%Y"),
        })
        _G.grndWatchSave()
        GRND_WATCH.scanAt = -99
        return true, "added"
    end
    function _G.grndWatchRemove(index)
        _G.grndWatchLoad()
        if not GRND_WATCH.list[index] then return false end
        table.remove(GRND_WATCH.list, index)
        _G.grndWatchSave()
        return true
    end
    function _G.grndWatchTick()
        local W = GRND_WATCH
        _G.grndWatchLoad()
        if #W.list == 0 then return end
        local now = os.clock()
        if now - (W.scanAt or -99) < 2.0 then return end
        W.scanAt = now
        if type(grndSessionReady) == "function" and not grndSessionReady() then return end
        local byLower = {}
        local maxId = 999
        if type(sampGetMaxPlayerId) == "function" then
            local okM, m = pcall(sampGetMaxPlayerId)
            if okM and type(m) == "number" and m >= 0 then maxId = math.min(1003, m) end
        end
        if type(sampGetPlayerNickname) == "function" then
            for id = 0, maxId do
                local conn = true
                if type(sampIsPlayerConnected) == "function" then
                    local okC, c = pcall(sampIsPlayerConnected, id)
                    conn = okC and (c == true or c == 1)
                end
                if conn then
                    local okN, n = pcall(sampGetPlayerNickname, id)
                    if okN and type(n) == "string" and n ~= "" then
                        local utfN = grndUtf8Text(n)
                        byLower[utfN:lower()] = { id = id, nick = utfN }
                    end
                end
            end
        end
        local prev = W.online or {}
        local cur = {}
        for _, entry in ipairs(W.list) do
            local key = entry.main:lower()
            local found = byLower[key]
            local isTwink = false
            if not found then
                for _, tw in ipairs(entry.twinks or {}) do
                    local f2 = byLower[tw:lower()]
                    if f2 then
                        found = f2
                        isTwink = true
                        break
                    end
                end
            end
            if found then
                cur[key] = { id = found.id, nick = found.nick, isTwink = isTwink, main = entry.main }
                if W.initializedOnce and not prev[key] then
                    local msg = isTwink
                        and string.format("%s[%d] в сети (твинк %s)", found.nick, found.id, entry.main)
                        or string.format("%s[%d] зашёл на сервер", found.nick, found.id)
                    _G.grndPushCheckerCapsule("ЧЕКЕР", msg, "ok", 5.0)
                end
            elseif W.initializedOnce and prev[key] then
                local old = prev[key]
                _G.grndPushCheckerCapsule("ЧЕКЕР",
                    string.format("%s[%d] вышел с сервера", old.nick, old.id), "warn", 4.0)
            end
        end
        W.online = cur
        W.initializedOnce = true
    end

    -- 8) Встроенный Chromium-браузер (Chrome + Сайт жалоб) без внешних NuGet SDK DLL
    GRND_BROWSER = _G.GRND_BROWSER or {
        COMPLAINTS_URL = "https://grnd.gg/admin/complaints",
        AUTH_URL = "https://grnd.gg/auth",
        CHROME_HOME = "https://www.google.com",
        activeKind = nil,
        visible = false,
        hostStarted = false,
        hostStartAt = -99,
        cmdSeq = 0,
        lastWriteAt = -99,
        lastReadAt = -99,
        lastSig = "",
        sessions = {
            chrome = {
                url = "https://www.google.com",
                inputUrl = "https://www.google.com",
                title = "Google",
                zoom = 100,
                autoRefresh = false,
                refreshEvery = 10,
                nextRefreshAt = 0,
            },
            complaints = {
                url = "https://grnd.gg/admin/complaints",
                inputUrl = "https://grnd.gg/admin/complaints",
                title = "Сайт жалоб — Grand Mobile",
                zoom = 80,
                -- Complaint pages contain authenticated forms; periodic reload can discard unsaved work.
                -- Keep it opt-in until the host can detect dirty form state safely.
                autoRefresh = false,
                refreshEvery = 3,
                nextRefreshAt = 0,
            },
        },
        status = "ожидание запуска окна Edge / Chrome",
        engineName = "Edge / Chrome",
    }
    _G.GRND_BROWSER = GRND_BROWSER

    local function browserNormalizeUrl(raw, fallback)
        local s = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then return fallback or "https://www.google.com" end
        local low = s:lower()
        -- Only permit web schemes. Reject all explicit non-web schemes rather than
        -- accidentally treating them as search text; preserve valid URL path/query/port.
        if low:match("^[%a][%w+%.%-]*:") then
            if low:match("^https?://") then return s end
            return fallback or "https://www.google.com"
        end
        if not s:find("%s") and s:find("%.") then
            return "https://" .. s
        end
        local enc = s:gsub("([^%w%-_%.~])", function(ch)
            return string.format("%%%02X", string.byte(ch))
        end)
        return "https://www.google.com/search?q=" .. enc
    end
    _G.grndBrowserNormalizeUrl = browserNormalizeUrl

    local function browserUtf8ToUtf16LeB64(str)
        local bytes = {}
        local i, n = 1, #str
        while i <= n do
            local c = str:byte(i)
            local cp = 0x3F
            if c < 0x80 then
                cp = c; i = i + 1
            elseif c >= 0xC2 and c <= 0xDF and i + 1 <= n then
                cp = (c - 0xC0) * 64 + (str:byte(i + 1) - 0x80); i = i + 2
            elseif c >= 0xE0 and c <= 0xEF and i + 2 <= n then
                cp = (c - 0xE0) * 4096 + (str:byte(i + 1) - 0x80) * 64 + (str:byte(i + 2) - 0x80); i = i + 3
            elseif c >= 0xF0 and c <= 0xF4 and i + 3 <= n then
                cp = (c - 0xF0) * 262144 + (str:byte(i + 1) - 0x80) * 4096
                    + (str:byte(i + 2) - 0x80) * 64 + (str:byte(i + 3) - 0x80); i = i + 4
            else
                i = i + 1
            end
            if cp <= 0xFFFF then
                bytes[#bytes + 1] = cp % 256
                bytes[#bytes + 1] = math.floor(cp / 256) % 256
            else
                cp = cp - 0x10000
                local hi = 0xD800 + math.floor(cp / 1024)
                local lo = 0xDC00 + (cp % 1024)
                bytes[#bytes + 1] = hi % 256; bytes[#bytes + 1] = math.floor(hi / 256) % 256
                bytes[#bytes + 1] = lo % 256; bytes[#bytes + 1] = math.floor(lo / 256) % 256
            end
        end
        local abc = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local out = {}
        local j = 1
        while j <= #bytes do
            local a = bytes[j] or 0
            local b = bytes[j + 1]
            local c = bytes[j + 2]
            local v = a * 65536 + (b or 0) * 256 + (c or 0)
            out[#out + 1] = abc:sub(math.floor(v / 262144) % 64 + 1, math.floor(v / 262144) % 64 + 1)
            out[#out + 1] = abc:sub(math.floor(v / 4096) % 64 + 1, math.floor(v / 4096) % 64 + 1)
            out[#out + 1] = b and abc:sub(math.floor(v / 64) % 64 + 1, math.floor(v / 64) % 64 + 1) or "="
            out[#out + 1] = c and abc:sub(v % 64 + 1, v % 64 + 1) or "="
            j = j + 3
        end
        return table.concat(out)
    end

    local function browserUtf8ToWideCdata(ffi, str)
        local units = {}
        local i, n = 1, #str
        while i <= n do
            local c = str:byte(i)
            local cp = 0x3F
            if c < 0x80 then cp = c; i = i + 1
            elseif c >= 0xC2 and c <= 0xDF and i + 1 <= n then
                cp = (c - 0xC0) * 64 + (str:byte(i + 1) - 0x80); i = i + 2
            elseif c >= 0xE0 and c <= 0xEF and i + 2 <= n then
                cp = (c - 0xE0) * 4096 + (str:byte(i + 1) - 0x80) * 64 + (str:byte(i + 2) - 0x80); i = i + 3
            else i = i + 1 end
            units[#units + 1] = cp
        end
        units[#units + 1] = 0
        local buf = ffi.new("wchar_t[?]", #units)
        for k = 1, #units do buf[k - 1] = units[k] end
        return buf
    end

    local function browserEnsureShell()
        local B = GRND_BROWSER
        if B.shellReady ~= nil then return B.shellReady end
        local okF, ffi = pcall(require, "ffi")
        if not okF or not ffi then B.shellReady = false; return false end
        pcall(ffi.cdef, [[
            void* __stdcall ShellExecuteW(void* hwnd, const wchar_t* lpOperation,
                const wchar_t* lpFile, const wchar_t* lpParameters,
                const wchar_t* lpDirectory, int nShowCmd);
        ]])
        local okS, sh32 = pcall(ffi.load, "shell32")
        if not okS or not sh32 then B.shellReady = false; return false end
        B.ffi, B.shell32, B.shellReady = ffi, sh32, true
        return true
    end

    function _G.grndBrowserOpenExternal(url)
        local target = browserNormalizeUrl(url, GRND_BROWSER.COMPLAINTS_URL)
        if browserEnsureShell() then
            local ffi = GRND_BROWSER.ffi
            local ok = pcall(function()
                GRND_BROWSER.shell32.ShellExecuteW(
                    nil,
                    browserUtf8ToWideCdata(ffi, "open"),
                    browserUtf8ToWideCdata(ffi, target),
                    nil, nil, 1)
            end)
            if ok then return true end
        end
        if os and type(os.execute) == "function" then
            pcall(os.execute, 'start "" "' .. target:gsub('"', '') .. '"')
            return true
        end
        return false
    end

    local BROWSER_HOST_PS1 = [=[
param([string]$CacheDir, [int]$GtaPid)
$ErrorActionPreference = 'SilentlyContinue'
Add-Type -TypeDefinition @"
using System;
using System.Text;
using System.Net;
using System.Net.Sockets;
using System.Diagnostics;
using System.Collections.Generic;
using System.Runtime.InteropServices;

public static class GrndBrowserWin32 {
    [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
    [StructLayout(LayoutKind.Sequential)] public struct POINT { public int X, Y; }
    public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc fn, IntPtr lParam);
    [DllImport("user32.dll")] public static extern bool IsWindow(IntPtr hWnd);
    [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
    [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr hWnd);
    [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] public static extern bool GetClientRect(IntPtr hWnd, out RECT rc);
    [DllImport("user32.dll")] public static extern bool ClientToScreen(IntPtr hWnd, ref POINT pt);
    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int cmd);
    [DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr hWnd, IntPtr after, int x, int y, int cx, int cy, uint flags);
    [DllImport("user32.dll")] public static extern int GetWindowLong(IntPtr hWnd, int idx);
    [DllImport("user32.dll")] public static extern int SetWindowLong(IntPtr hWnd, int idx, int val);
    [DllImport("user32.dll", EntryPoint="SetWindowLongPtr", SetLastError=true)] public static extern IntPtr SetWindowLongPtr64(IntPtr hWnd, int idx, IntPtr val);
    [DllImport("user32.dll", EntryPoint="SetWindowLong", SetLastError=true)] public static extern int SetWindowLong32(IntPtr hWnd, int idx, int val);
    [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder sb, int max);
    [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid);
    [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr hWnd, uint msg, IntPtr wp, IntPtr lp);
    [DllImport("gdi32.dll")] public static extern IntPtr CreateRectRgn(int x1, int y1, int x2, int y2);
    [DllImport("user32.dll")] public static extern int SetWindowRgn(IntPtr hWnd, IntPtr hRgn, bool redraw);

    public static void SetOwner(IntPtr child, IntPtr owner) {
        if (IntPtr.Size == 8) SetWindowLongPtr64(child, -8, owner);
        else SetWindowLong32(child, -8, owner.ToInt32());
    }
    public static HashSet<long> SnapshotChromeWindows() {
        var set = new HashSet<long>();
        EnumWindows((h, l) => {
            if (!IsWindowVisible(h)) return true;
            var sb = new StringBuilder(64);
            GetClassName(h, sb, 64);
            if (sb.ToString() == "Chrome_WidgetWin_1") set.Add(h.ToInt64());
            return true;
        }, IntPtr.Zero);
        return set;
    }
    public static IntPtr FindNewChromeWindow(HashSet<long> before) {
        IntPtr found = IntPtr.Zero;
        EnumWindows((h, l) => {
            if (!IsWindowVisible(h)) return true;
            if (before.Contains(h.ToInt64())) return true;
            var sb = new StringBuilder(64);
            GetClassName(h, sb, 64);
            if (sb.ToString() == "Chrome_WidgetWin_1") { found = h; return false; }
            return true;
        }, IntPtr.Zero);
        return found;
    }
    public static IntPtr FindProcessMainWindow(int pid) {
        IntPtr best = IntPtr.Zero;
        EnumWindows((h, l) => {
            if (!IsWindowVisible(h)) return true;
            uint wpid = 0;
            GetWindowThreadProcessId(h, out wpid);
            if ((int)wpid == pid) { best = h; return false; }
            return true;
        }, IntPtr.Zero);
        return best;
    }
    public static bool SendCdpJson(int port, string wsPath, string jsonPayload) {
        try {
            using (var tcp = new TcpClient("127.0.0.1", port)) {
                tcp.ReceiveTimeout = 600; tcp.SendTimeout = 600;
                var ns = tcp.GetStream();
                string key = Convert.ToBase64String(Guid.NewGuid().ToByteArray());
                string req = "GET " + wsPath + " HTTP/1.1\r\nHost: 127.0.0.1:" + port +
                    "\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: " + key +
                    "\r\nSec-WebSocket-Version: 13\r\n\r\n";
                byte[] hb = Encoding.ASCII.GetBytes(req);
                ns.Write(hb, 0, hb.Length);
                byte[] rbuf = new byte[1024];
                int rn = ns.Read(rbuf, 0, rbuf.Length);
                if (rn <= 0 || !Encoding.ASCII.GetString(rbuf, 0, rn).Contains("101")) return false;
                byte[] data = Encoding.UTF8.GetBytes(jsonPayload);
                byte[] mask = new byte[] { 0x37, 0xFA, 0x21, 0x3D };
                var frame = new List<byte>();
                frame.Add(0x81);
                if (data.Length < 126) { frame.Add((byte)(0x80 | data.Length)); }
                else { frame.Add(0xFE); frame.Add((byte)((data.Length >> 8) & 0xFF)); frame.Add((byte)(data.Length & 0xFF)); }
                frame.AddRange(mask);
                for (int i = 0; i < data.Length; i++) frame.Add((byte)(data[i] ^ mask[i & 3]));
                byte[] fb = frame.ToArray();
                ns.Write(fb, 0, fb.Length);
                return true;
            }
        } catch { return false; }
    }
}
"@

function Find-BrowserExe {
    $cands = @(
        "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe",
        "${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe",
        "$env:ProgramFiles\Google\Chrome\Application\chrome.exe",
        "${env:ProgramFiles(x86)}\Google\Chrome\Application\chrome.exe",
        "$env:LOCALAPPDATA\Microsoft\Edge\Application\msedge.exe",
        "$env:LOCALAPPDATA\Google\Chrome\Application\chrome.exe"
    )
    foreach ($p in $cands) { if ($p -and (Test-Path $p)) { return $p } }
    return $null
}

$cmdFile = Join-Path $CacheDir "browser_cmd.txt"
$stateFile = Join-Path $CacheDir "browser_state.txt"
$lockFile = Join-Path $CacheDir "browser_host.pid"
[IO.File]::WriteAllText($lockFile, "$PID", [Text.Encoding]::UTF8)

$exe = Find-BrowserExe
if (-not $exe) {
    [IO.File]::WriteAllText($stateFile, "status=error`nengine=none`n", [Text.Encoding]::UTF8)
    exit 1
}
$engineLabel = if ($exe -match "msedge") { "Microsoft Edge" } else { "Google Chrome" }
$port = 39281
$profileDir = Join-Path $CacheDir "chromium_profile"
New-Item -ItemType Directory -Force -Path $profileDir | Out-Null

$browserHwnd = [IntPtr]::Zero
$browserProc = $null
$lastSeq = -1
$curUrl = ""
$curZoom = 100
$wasVisible = $false
$lastHeartbeat = [DateTime]::UtcNow

function Ensure-Browser([string]$startUrl) {
    if ($script:browserHwnd -ne [IntPtr]::Zero -and [GrndBrowserWin32]::IsWindow($script:browserHwnd)) { return $true }
    $before = [GrndBrowserWin32]::SnapshotChromeWindows()
    $args = @(
        "--user-data-dir=`"$profileDir`"",
        "--remote-debugging-port=$port",
        "--remote-allow-origins=*",
        "--no-first-run",
        "--no-default-browser-check",
        "--disable-extensions",
        "--disable-popup-blocking",
        "--window-position=-32000,-32000",
        "--window-size=900,600",
        "--app=`"$startUrl`""
    )
    $script:browserProc = Start-Process -FilePath $exe -ArgumentList ($args -join " ") -PassThru
    for ($i = 0; $i -lt 45; $i++) {
        Start-Sleep -Milliseconds 100
        $h = [GrndBrowserWin32]::FindNewChromeWindow($before)
        if ($h -ne [IntPtr]::Zero) {
            $script:browserHwnd = $h
            $ex = [GrndBrowserWin32]::GetWindowLong($h, -20)
            [GrndBrowserWin32]::SetWindowLong($h, -20, ($ex -bor 0x00000080) -band (-bnot 0x00040000)) | Out-Null
            [GrndBrowserWin32]::ShowWindow($h, 0) | Out-Null
            $script:curUrl = $startUrl
            return $true
        }
    }
    return $false
}

function Get-CdpTarget {
    try {
        $wc = New-Object System.Net.WebClient
        $wc.Encoding = [Text.Encoding]::UTF8
        $json = $wc.DownloadString("http://127.0.0.1:$port/json/list")
        $mWs = [regex]::Match($json, '"webSocketDebuggerUrl"\s*:\s*"ws://127\.0\.0\.1:\d+([^"]+)"')
        $mUrl = [regex]::Match($json, '"url"\s*:\s*"([^"]+)"')
        $mTit = [regex]::Match($json, '"title"\s*:\s*"([^"]*)"')
        if ($mWs.Success) {
            return @{ ws = $mWs.Groups[1].Value; url = $mUrl.Groups[1].Value; title = $mTit.Groups[1].Value }
        }
    } catch {}
    return $null
}

$tick = 0
while ($true) {
    Start-Sleep -Milliseconds 90
    $tick++
    if ($GtaPid -gt 0) {
        $gp = Get-Process -Id $GtaPid -ErrorAction SilentlyContinue
        if (-not $gp) { break }
    }
    if (Test-Path $cmdFile) {
        $raw = [IO.File]::ReadAllText($cmdFile, [Text.Encoding]::UTF8)
        $map = @{}
        foreach ($ln in ($raw -split "`n")) {
            $idx = $ln.IndexOf('=')
            if ($idx -gt 0) { $map[$ln.Substring(0, $idx).Trim()] = $ln.Substring($idx + 1).Trim() }
        }
        if ($map["quit"] -eq "1") { break }
        $hb = 0
        if ([long]::TryParse($map["hb"], [ref]$hb)) {
            $age = [Math]::Abs(([DateTimeOffset]::UtcNow.ToUnixTimeSeconds()) - $hb)
            if ($age -le 6) { $lastHeartbeat = [DateTime]::UtcNow }
        }
        if ((([DateTime]::UtcNow) - $lastHeartbeat).TotalSeconds -gt 6.5) { break }

        $vis = ($map["visible"] -eq "1")
        $wantUrl = $map["url"]
        $action = $map["action"]
        $seq = 0; [int]::TryParse($map["seq"], [ref]$seq) | Out-Null
        $zoom = 100; [int]::TryParse($map["zoom"], [ref]$zoom) | Out-Null

        if ($vis -and $wantUrl) {
            if (Ensure-Browser $wantUrl) {
                $gtaHwnd = if ($GtaPid -gt 0) { [GrndBrowserWin32]::FindProcessMainWindow($GtaPid) } else { [IntPtr]::Zero }
                $gtaActive = $true
                if ($gtaHwnd -ne [IntPtr]::Zero) {
                    if ([GrndBrowserWin32]::IsIconic($gtaHwnd)) { $gtaActive = $false }
                    $fg = [GrndBrowserWin32]::GetForegroundWindow()
                    if ($fg -ne [IntPtr]::Zero -and $fg -ne $gtaHwnd -and $fg -ne $script:browserHwnd) { $gtaActive = $false }
                }
                if (-not $gtaActive) {
                    if ($wasVisible) { [GrndBrowserWin32]::ShowWindow($script:browserHwnd, 0) | Out-Null; $wasVisible = $false }
                } else {
                    $rx = 0; $ry = 0; $rw = 800; $rh = 500; $resX = 1920; $resY = 1080
                    [int]::TryParse($map["x"], [ref]$rx) | Out-Null
                    [int]::TryParse($map["y"], [ref]$ry) | Out-Null
                    [int]::TryParse($map["w"], [ref]$rw) | Out-Null
                    [int]::TryParse($map["h"], [ref]$rh) | Out-Null
                    [int]::TryParse($map["resX"], [ref]$resX) | Out-Null
                    [int]::TryParse($map["resY"], [ref]$resY) | Out-Null
                    $sx = $rx; $sy = $ry; $sw = $rw; $sh = $rh
                    if ($gtaHwnd -ne [IntPtr]::Zero) {
                        $crc = New-Object GrndBrowserWin32+RECT
                        if ([GrndBrowserWin32]::GetClientRect($gtaHwnd, [ref]$crc)) {
                            $cw = [Math]::Max(1, $crc.Right - $crc.Left)
                            $ch = [Math]::Max(1, $crc.Bottom - $crc.Top)
                            if ($resX -gt 0 -and $resY -gt 0) {
                                $sx = [int][Math]::Round($rx * ($cw / [double]$resX))
                                $sy = [int][Math]::Round($ry * ($ch / [double]$resY))
                                $sw = [int][Math]::Round($rw * ($cw / [double]$resX))
                                $sh = [int][Math]::Round($rh * ($ch / [double]$resY))
                            }
                            $pt = New-Object GrndBrowserWin32+POINT
                            $pt.X = $sx; $pt.Y = $sy
                            [GrndBrowserWin32]::ClientToScreen($gtaHwnd, [ref]$pt) | Out-Null
                            $sx = $pt.X; $sy = $pt.Y
                        }
                        [GrndBrowserWin32]::SetOwner($script:browserHwnd, $gtaHwnd)
                    }
                    $cropL = 8; $cropT = 32; $cropR = 8; $cropB = 8
                    $winW = [Math]::Max(200, $sw + $cropL + $cropR)
                    $winH = [Math]::Max(160, $sh + $cropT + $cropB)
                    $rgn = [GrndBrowserWin32]::CreateRectRgn($cropL, $cropT, $cropL + $sw, $cropT + $sh)
                    [GrndBrowserWin32]::SetWindowRgn($script:browserHwnd, $rgn, $true) | Out-Null
                    [GrndBrowserWin32]::SetWindowPos($script:browserHwnd, [IntPtr]::Zero, $sx - $cropL, $sy - $cropT, $winW, $winH, 0x0010 -bor 0x0004 -bor 0x0040) | Out-Null
                    $wasVisible = $true
                }

                if ($seq -ne $lastSeq) {
                    $lastSeq = $seq
                    $t = Get-CdpTarget
                    if ($t) {
                        if ($action -eq "navigate" -and $wantUrl) {
                            $esc = $wantUrl.Replace('\','\\').Replace('"','\"')
                            [GrndBrowserWin32]::SendCdpJson($port, $t.ws, "{`"id`":1,`"method`":`"Page.navigate`",`"params`":{`"url`":`"$esc`"}}") | Out-Null
                            $curUrl = $wantUrl
                        } elseif ($action -eq "reload") {
                            [GrndBrowserWin32]::SendCdpJson($port, $t.ws, '{"id":2,"method":"Page.reload","params":{}}') | Out-Null
                        } elseif ($action -eq "smart_reload") {
                            $js = "if(!/\/auth/i.test(location.pathname) && !['INPUT','TEXTAREA'].includes((document.activeElement||{}).tagName)){location.reload();}"
                            $escJs = $js.Replace('\','\\').Replace('"','\"')
                            [GrndBrowserWin32]::SendCdpJson($port, $t.ws, "{`"id`":3,`"method`":`"Runtime.evaluate`",`"params`":{`"expression`":`"$escJs`"}}") | Out-Null
                        } elseif ($action -eq "back") {
                            [GrndBrowserWin32]::SendCdpJson($port, $t.ws, '{"id":4,"method":"Runtime.evaluate","params":{"expression":"history.back()"}}') | Out-Null
                        } elseif ($action -eq "forward") {
                            [GrndBrowserWin32]::SendCdpJson($port, $t.ws, '{"id":5,"method":"Runtime.evaluate","params":{"expression":"history.forward()"}}') | Out-Null
                        }
                    }
                }
                if ($zoom -ne $curZoom -or ($tick % 12 -eq 0)) {
                    $curZoom = $zoom
                    $t = Get-CdpTarget
                    if ($t) {
                        $zf = ([Math]::Max(50, [Math]::Min(150, $zoom)) / 100.0).ToString("0.00", [Globalization.CultureInfo]::InvariantCulture)
                        [GrndBrowserWin32]::SendCdpJson($port, $t.ws, "{`"id`":6,`"method`":`"Runtime.evaluate`",`"params`":{`"expression`":`"if(document.documentElement)document.documentElement.style.zoom='$zf'`"}}") | Out-Null
                        $tmpState = "$stateFile.tmp"
                        $beat = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
                        [IO.File]::WriteAllText($tmpState, "status=ready`nengine=$engineLabel`nbeat=$beat`nurl=$($t.url)`ntitle=$($t.title)`n", [Text.Encoding]::UTF8)
                        Move-Item -Force $tmpState $stateFile
                    }
                }
            }
        } else {
            if ($wasVisible -and $script:browserHwnd -ne [IntPtr]::Zero) {
                [GrndBrowserWin32]::ShowWindow($script:browserHwnd, 0) | Out-Null
                $wasVisible = $false
            }
        }
    }
}
if ($browserHwnd -ne [IntPtr]::Zero -and [GrndBrowserWin32]::IsWindow($browserHwnd)) {
    [GrndBrowserWin32]::ShowWindow($browserHwnd, 0) | Out-Null
    [GrndBrowserWin32]::PostMessage($browserHwnd, 0x0010, [IntPtr]::Zero, [IntPtr]::Zero) | Out-Null
}
Remove-Item -Force $lockFile -ErrorAction SilentlyContinue
]=]

    local function browserPaths()
        local B = GRND_BROWSER
        if not B.cacheDir then
            local sample = grndStoragePath("cache", "browser_cmd.txt")
            B.cmdPath = sample
            B.statePath = grndStoragePath("cache", "browser_state.txt")
            B.ps1Path = grndStoragePath("cache", "grnd_browser_host.ps1")
            B.cacheDir = sample:match("^(.*)[/\\][^/\\]+$") or "."
        end
        return B.cacheDir, B.cmdPath, B.statePath, B.ps1Path
    end

    local function browserCurrentPid()
        local okF, ffi = pcall(require, "ffi")
        if not okF or not ffi then return 0 end
        pcall(ffi.cdef, "unsigned long __stdcall GetCurrentProcessId(void);")
        local okK, k32 = pcall(ffi.load, "kernel32")
        if not okK or not k32 then return 0 end
        local okP, pid = pcall(function() return tonumber(k32.GetCurrentProcessId()) end)
        return (okP and pid) or 0
    end

    local function browserWriteCmd(tbl, force)
        local B = GRND_BROWSER
        local now = os.clock()
        local sig = string.format("%s|%s|%d|%d|%d|%d|%d|%d|%s",
            tostring(tbl.visible and 1 or 0), tostring(tbl.url or ""),
            tonumber(tbl.x) or 0, tonumber(tbl.y) or 0,
            tonumber(tbl.w) or 0, tonumber(tbl.h) or 0,
            tonumber(tbl.zoom) or 100, tonumber(tbl.seq) or 0, tostring(tbl.action or ""))
        if not force and sig == B.lastSig and (now - (B.lastWriteAt or -99) < 1.2) then
            return
        end
        B.lastSig = sig
        B.lastWriteAt = now
        local _, cmdPath = browserPaths()
        local tmp = cmdPath .. ".tmp"
        local okO, fh = pcall(io.open, tmp, "wb")
        if not okO or not fh then return end
        pcall(function()
            fh:write("hb=" .. tostring(os.time()) .. "\n")
            fh:write("visible=" .. (tbl.visible and "1" or "0") .. "\n")
            fh:write("quit=" .. (tbl.quit and "1" or "0") .. "\n")
            fh:write("seq=" .. tostring(tbl.seq or B.cmdSeq or 0) .. "\n")
            fh:write("action=" .. tostring(tbl.action or "") .. "\n")
            fh:write("url=" .. tostring(tbl.url or ""):gsub("[\r\n]", "") .. "\n")
            fh:write("zoom=" .. tostring(tbl.zoom or 100) .. "\n")
            fh:write("x=" .. tostring(math.floor(tonumber(tbl.x) or 0)) .. "\n")
            fh:write("y=" .. tostring(math.floor(tonumber(tbl.y) or 0)) .. "\n")
            fh:write("w=" .. tostring(math.floor(tonumber(tbl.w) or 800)) .. "\n")
            fh:write("h=" .. tostring(math.floor(tonumber(tbl.h) or 500)) .. "\n")
            fh:write("resX=" .. tostring(math.floor(tonumber(tbl.resX) or 1920)) .. "\n")
            fh:write("resY=" .. tostring(math.floor(tonumber(tbl.resY) or 1080)) .. "\n")
            fh:close()
        end)
        pcall(os.remove, cmdPath)
        pcall(os.rename, tmp, cmdPath)
    end

    local function browserEnsureHost()
        local B = GRND_BROWSER
        local now = os.clock()
        if B.hostDead then return false end
        if B.hostStarted and (now - (B.hostStartAt or 0) < 8.0) then return true end
        local cacheDir, _, statePath, ps1Path = browserPaths()
        if B.hostStarted then
            local okS, sf = pcall(io.open, statePath, "r")
            if okS and sf then
                local state = ""
                pcall(function() state = sf:read("*a") or ""; sf:close() end)
                local st = state:match("status=([^\n]+)")
                local beat = tonumber(state:match("beat=(%d+)"))
                if st == "error" then return true end
                if st == "ready" and beat and math.abs(os.time() - beat) <= 6 then return true end
                if (now - (B.hostStartAt or 0)) > 12 then
                    B.hostStarted, B.hostDead = false, true
                    B.status = "сессия Edge / Chrome потеряна — нажмите «Повторить»"
                    return false
                end
                return true
            elseif (now - (B.hostStartAt or 0)) > 12 then
                B.hostStarted, B.hostDead = false, true
                B.status = "окно Edge / Chrome не подтвердило запуск — нажмите «Повторить»"
                return false
            end
        end
        if not browserEnsureShell() then
            B.status = "Shell32 недоступен — используйте кнопку «Внешний браузер»"
            return false
        end
        local okW, pf = pcall(io.open, ps1Path, "wb")
        if not okW or not pf then
            B.status = "нет прав записи в cache"
            return false
        end
        pcall(function() pf:write("\239\187\191" .. BROWSER_HOST_PS1); pf:close() end)
        local pid = browserCurrentPid()
        local psBoot = string.format(
            "& '%s' -CacheDir '%s' -GtaPid %d",
            ps1Path:gsub("'", "''"), cacheDir:gsub("'", "''"), pid)
        local enc = browserUtf8ToUtf16LeB64(psBoot)
        local params = "-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -EncodedCommand " .. enc
        -- Never accept a leftover ready/error file from an earlier host process.
        pcall(os.remove, statePath)
        local ffi = B.ffi
        local okExec, shellResult = pcall(function()
            return tonumber(B.shell32.ShellExecuteW(
                nil,
                browserUtf8ToWideCdata(ffi, "open"),
                browserUtf8ToWideCdata(ffi, "powershell.exe"),
                browserUtf8ToWideCdata(ffi, params),
                nil, 0)) -- SW_HIDE = 0
        end)
        local launched = okExec and type(shellResult) == "number" and shellResult > 32
        B.hostStarted = launched and true or false
        B.hostDead = false
        B.hostStartAt = now
        B.status = launched and "запуск окна Edge / Chrome…" or "не удалось запустить PowerShell-host"
        return B.hostStarted
    end

    function _G.grndBrowserRetry()
        local B = GRND_BROWSER
        B.hostStarted = false
        B.hostDead = false
        B.hostStartAt = -99
        B.lastSig = ""
        B.status = "повторный запуск окна Edge / Chrome…"
        local _, _, statePath = browserPaths()
        pcall(os.remove, statePath)
        B.cmdSeq = (B.cmdSeq or 0) + 1
        B.pendingAction = "navigate"
        return true
    end

    function _G.grndBrowserAction(kind, action, rawUrl)
        local B = GRND_BROWSER
        local S = B.sessions[kind] or B.sessions.chrome
        if action == "navigate" then
            local fallback = (kind == "complaints") and B.COMPLAINTS_URL or B.CHROME_HOME
            S.url = browserNormalizeUrl(rawUrl or S.inputUrl, fallback)
            S.inputUrl = S.url
        end
        B.cmdSeq = (B.cmdSeq or 0) + 1
        B.pendingAction = action
        B.lastSig = ""
    end

    function _G.grndBrowserTick(visible, spec)
        local B = GRND_BROWSER
        if not visible or type(spec) ~= "table" then
            if B.visible then
                B.visible = false
                B.activeKind = nil
                browserWriteCmd({ visible = false }, true)
            end
            return
        end
        local kind = (spec.kind == "complaints") and "complaints" or "chrome"
        local S = B.sessions[kind]
        if kind == "complaints" then
            S.zoom = GRND_MAIN_EXT.complaintsZoom or 80
            S.autoRefresh = GRND_MAIN_EXT.complaintsAuto ~= false
            S.refreshEvery = math.max(3, math.min(60, tonumber(GRND_MAIN_EXT.complaintsEvery) or 3))
        else
            S.zoom = GRND_MAIN_EXT.chromeZoom or 100
        end
        local now = os.clock()
        if B.activeKind ~= kind then
            B.activeKind = kind
            B.cmdSeq = (B.cmdSeq or 0) + 1
            B.pendingAction = "navigate"
            if kind == "complaints" then
                S.nextRefreshAt = now + S.refreshEvery
            end
        end
        if kind == "complaints" and S.autoRefresh then
            if (S.nextRefreshAt or 0) <= 0 then S.nextRefreshAt = now + S.refreshEvery end
            if now >= S.nextRefreshAt then
                S.nextRefreshAt = now + S.refreshEvery
                B.cmdSeq = (B.cmdSeq or 0) + 1
                B.pendingAction = "smart_reload"
            end
        end
        B.visible = true
        browserEnsureHost()
        browserWriteCmd({
            visible = true,
            url = S.url,
            zoom = S.zoom,
            seq = B.cmdSeq,
            action = B.pendingAction or "",
            x = spec.x, y = spec.y, w = spec.w, h = spec.h,
            resX = spec.resX, resY = spec.resY,
        }, B.pendingAction ~= nil)
        B.pendingAction = nil

        if now - (B.lastReadAt or -99) >= 0.35 then
            B.lastReadAt = now
            local _, _, statePath = browserPaths()
            local okR, fh = pcall(io.open, statePath, "r")
            if okR and fh then
                local content = nil
                pcall(function() content = fh:read("*a"); fh:close() end)
                if type(content) == "string" then
                    local st = content:match("status=([^\r\n]+)")
                    local eng = content:match("engine=([^\r\n]+)")
                    local liveUrl = content:match("url=([^\r\n]+)")
                    local liveTitle = content:match("title=([^\r\n]*)")
                    if eng and eng ~= "" then B.engineName = eng end
                    if st == "ready" then
                        B.status = "активен (" .. tostring(B.engineName) .. ")"
                    elseif st == "error" then
                        B.status = "браузер Edge/Chrome не найден — используйте «Внешний ↗»"
                    end
                    if liveUrl and liveUrl:match("^https?://") and not S.editingUrl then
                        S.url = liveUrl
                        S.inputUrl = liveUrl
                    end
                    if liveTitle and liveTitle ~= "" then S.title = liveTitle end
                end
            end
        end
        if B.hostStarted and (now - (B.hostStartAt or now)) > 12
            and not tostring(B.status or ""):find("активен", 1, true)
            and not tostring(B.status or ""):find("не найден", 1, true) then
            B.status = "окно Edge / Chrome не подтвердило запуск — нажмите «Повторить»"
        end
    end

    function _G.grndBrowserTerminate()
        local B = GRND_BROWSER
        B.visible = false
        pcall(browserWriteCmd, { visible = false, quit = true }, true)
    end
    if type(grndOnTerm) == "function" then
        pcall(grndOnTerm, _G.grndBrowserTerminate)
    end

    -- 9) Глобальный поиск функций по всем вкладкам и карточкам (Поиск функции...)
    GRND_FUNC_SEARCH = _G.GRND_FUNC_SEARCH or {
        query = "",
        items = {
            { title = "Дистанция камеры и Рыбий глаз", sub = "Настройки · Общие", tab = "settings", setTab = "main", kw = "камера fov рыбий глаз отдаление" },
            { title = "Настройка чата (клавиша, время, ID, строки)", sub = "Настройки · Общие", tab = "settings", setTab = "main", kw = "чат timestamp id строки клавиша" },
            { title = "Отображение времени и даты", sub = "Настройки · Общие", tab = "settings", setTab = "main", kw = "часы время дата экран clock" },
            { title = 'Меню паузы "Grnd Tools"', sub = "Настройки · Общие", tab = "settings", setTab = "main", kw = "пауза esc меню настройки" },
