    _G.GRND_FUNC_SEARCH = GRND_FUNC_SEARCH
    function _G.grndFuncSearchFilter(q)
        q = grndLowerUtf(tostring(q or ""):gsub("^%s+", ""):gsub("%s+$", ""))
        if q == "" then return {} end
        local out = {}
        for _, it in ipairs(GRND_FUNC_SEARCH.items) do
            local hay = grndLowerUtf(it.title .. " " .. it.sub .. " " .. (it.kw or ""))
            if hay:find(q, 1, true) then
                out[#out + 1] = it
            end
        end
        return out
    end
    function _G.grndFuncSearchJump(item)
        local m = GRND_REF and GRND_REF.menu
        if type(m) ~= "table" or type(item) ~= "table" then return false end
        for i, t in ipairs(MENU_TABS) do
            if t.id == item.tab then
                m.tab = i
                break
            end
        end
        if item.setTab then m.settingsTab = item.setTab end
        if item.ckTab then m.checkersTab = item.ckTab end
        GRND_FUNC_SEARCH.query = ""
        m.searchReset = true
        return true
    end
    end
    do
        local function detect(mod)
            if type(mod) ~= "table" then return nil end
            if type(mod.OnFrame) == "function"
               and type(mod.OnInitialize) == "function" then
                return "mimgui"
            end
            return "moonimgui"
        end
        local ok, mod = pcall(require, "mimgui")
        if ok then
            imKind = detect(mod)
            if imKind then im = mod end
        end
        if not im then
            ok, mod = pcall(require, "imgui")
            if ok then
                local k = detect(mod)
                if k then im, imKind = mod, k end
            end
        end
        if im then
            _G.imgui = im
            _G.grndImgui = im
        end
    end
    function grndUtf8Len(s)
        s = tostring(s or "")
        local n, i, len = 0, 1, #s
        while i <= len do
            local b = s:byte(i)
            if b >= 0xF0 then i = i + 4
            elseif b >= 0xE0 then i = i + 3
            elseif b >= 0xC0 then i = i + 2
            else i = i + 1 end
            n = n + 1
        end
        return n
    end
    function grndTextW(s)
        s = tostring(s or "")
        s = (string.gsub(s, "{%x%x%x%x%x%x}", ""))
        local chars = grndUtf8Len(s)
        local per = GRND_FONT.glyphW or (GRND_FONT.fontSize or 14) * 0.52
        local est = math.max(1, math.floor(chars * per + 0.5))
        if GRND_FONT.noMeasure then return est end
        if type(im) ~= "table" or type(im.CalcTextSize) ~= "function" then
            GRND_FONT.noMeasure = true
            pcall(grndTrace, "measure", "im.CalcTextSize нет — ширина на оценке")
            return est
        end
        local ok, a, b2 = pcall(im.CalcTextSize, s)
        local w
        if ok then
            local ta = type(a)
            if ta == "table" or ta == "cdata" then
                w = tonumber(a.x)
            elseif ta == "number" then
                w = a
            end
        end
        if w and w > 0 then
            GRND_FONT.glyphW = w / math.max(1, chars)
            return w
        end
        GRND_FONT.noMeasure = true
        pcall(grndTrace, "measure", "im.CalcTextSize недоступен — перенос по оценке")
        return est
    end
    if im then
        if type(rawget(im, "ImVec2")) ~= "function" then
            im.ImVec2 = function(x, y) return { x = tonumber(x) or 0, y = tonumber(y) or 0 } end
        end
        if type(rawget(im, "ImVec4")) ~= "function" then
            im.ImVec4 = function(r, g, b, a)
                return { x = r or 0, y = g or 0, z = b or 0, w = a or 1 }
            end
        end
        local queue = {}
        local nextId = 0
        local TYPES = {
            info = { accent = {45, 156, 219} },
            progress = { accent = {78, 174, 238} },
            ok = { accent = {76, 209, 79} },
            warn = { accent = {247, 146, 72} },
            error = { accent = {255, 100, 100} },
        }
        local function rgba(r, g, b, a)
            return im.ImVec4(r / 255, g / 255, b / 255, (a or 255) / 255)
        end
        local function col32(r, g, b, a)
            a = a or 255
            r = math.floor(tonumber(r) or 0) % 256
            g = math.floor(tonumber(g) or 0) % 256
            b = math.floor(tonumber(b) or 0) % 256
            a = math.floor(tonumber(a) or 0) % 256
            if bit and bit.bor and bit.lshift then
                return bit.bor(r, bit.lshift(g, 8), bit.lshift(b, 16), bit.lshift(a, 24))
            end
            return r + g * 0x100 + b * 0x10000 + a * 0x1000000
        end
        local function wflag(name)
            local t = rawget(im, "WindowFlags") or rawget(im, "ImGuiWindowFlags")
            local v = (type(t) == "table" or type(t) == "cdata") and t[name] or nil
            if v == nil then v = rawget(im, "ImGuiWindowFlags_" .. name) end
            if v == nil then v = rawget(im, name) end
            return tonumber(v) or 0
        end
        local function wf(...)
            local f = 0
            for i = 1, select("#", ...) do f = f + wflag(select(i, ...)) end
            return f
        end
        local function iflag(tblNames, name)
            for _, tn in ipairs(tblNames) do
                local t = rawget(im, tn)
                if t ~= nil then
                    local v = (type(t) == "table" or type(t) == "cdata") and t[name] or nil
                    if v ~= nil then return v end
                end
            end
            local v = rawget(im, name)
            if v ~= nil then return v end
            return nil
        end
        local COND_ALWAYS = iflag({ "Cond", "ImGuiCond" }, "Always")
            or iflag({ "Cond", "ImGuiCond" }, "Always") or 0
        local WIN_FLAGS = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
            "NoCollapse", "NoInputs")
        local function cornerFlags(left, right, top, bottom)
            local f = 0
            local function pick(newName, oldName)
                if im[newName] ~= nil then return im[newName] end
                if im[oldName] ~= nil then return im[oldName] end
                return nil
            end
            if left then
                local v = pick("ImDrawFlags_RoundCornersLeft", "ImDrawCornerFlags_Left")
                if v then f = f + v end
            end
            if right then
                local v = pick("ImDrawFlags_RoundCornersRight", "ImDrawCornerFlags_Right")
                if v then f = f + v end
            end
            if top then
                local v = pick("ImDrawFlags_RoundCornersTop", "ImDrawCornerFlags_Top")
                if v then f = f + v end
            end
            if bottom then
                local v = pick("ImDrawFlags_RoundCornersBottom", "ImDrawCornerFlags_Bot")
                if v then f = f + v end
            end
            return f
        end
        local function normCol(c)
            if type(c) == "table" then
                if not _G.grndFormsColWarned then
                    _G.grndFormsColWarned = true
                    print("[GRND формы] цвет пришёл таблицей — упаковал сам; источник: " ..
                        tostring((debug.traceback("", 2)):gsub("%s+", " "):sub(1, 220)))
                end
                return col32(c[1] or 255, c[2] or 255, c[3] or 255, c[4] or 255)
            end
            return c
        end
        local function roundRect(dl, p1, p2, col, rounding, flags)
            col = normCol(col)
            if rounding and rounding > 0 then
                local ok = pcall(dl.AddRectFilled, dl, p1, p2, col, rounding, flags or 0)
                if ok then return end
            end
            pcall(dl.AddRectFilled, dl, p1, p2, col)
        end
        local function gradRect(dl, p1, p2, c1, c2, rounding)
            c1, c2 = normCol(c1), normCol(c2)
            if im.ImDrawList_AddRectFilledMultiColor then
                local ok = pcall(im.ImDrawList_AddRectFilledMultiColor, dl, p1, p2, c1, c2, c2, c1)
                if ok then return end
            end
            local ok = pcall(dl.AddRectFilledMultiColor, dl, p1, p2, c1, c2, c2, c1)
            if ok then return end
            pcall(dl.AddRectFilled, dl, p1, p2, c1, rounding or 0)
        end
        local pushStyleVec2, pushStyleFloat
        local styleDepth, endDepth, colorDepth = 0, 0, 0
        local function grndPushStyleF(var, val)
            if var == nil then return false end
            local ok = false
            if im.PushStyleVarFloat then ok = pcall(im.PushStyleVarFloat, var, val) end
            if not ok then ok = pcall(im.PushStyleVar, var, val) end
            if ok then styleDepth = styleDepth + 1 end
            return ok
        end
        local function grndPushStyleV2(var, x, y)
            if var == nil then return false end
            local v = im.ImVec2(x, y)
            local ok = false
            if im.PushStyleVarVec2 then ok = pcall(im.PushStyleVarVec2, var, v) end
            if not ok then ok = pcall(im.PushStyleVar, var, v) end
            if ok then styleDepth = styleDepth + 1 end
            return ok
        end
        local function grndPushCol(var, col)
            if var == nil or col == nil then return false end
            local ok = pcall(im.PushStyleColor, var, col)
            if ok then colorDepth = colorDepth + 1 end
            return ok
        end
        local function grndPopStyle(n)
            n = n or 1
            n = math.min(n, styleDepth)
            if n <= 0 then return end
            styleDepth = styleDepth - n
            pcall(im.PopStyleVar, n)
        end
        local function grndPopCol(n)
            n = n or 1
            n = math.min(n, colorDepth)
            if n <= 0 then return end
            colorDepth = colorDepth - n
            pcall(im.PopStyleColor, n)
        end
        local function grndEnds()
            while endDepth > 0 do
                endDepth = endDepth - 1
                pcall(im.End)
            end
            grndPopStyle(styleDepth)
            grndPopCol(colorDepth)
        end
        local function grndBegin(name, flags)
            local ok, res = pcall(im.Begin, name, nil, flags)
            if not ok then return false end
            endDepth = endDepth + 1
            return res and true or false
        end
        local function grndBeginTransparent(name, flags)
            local npush = 0
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then
                npush = npush + 1
            end
            if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then
                npush = npush + 1
            end
            local ok = grndBegin(name, flags)
            grndPopCol(npush)
            return ok
        end
        local function drawToasts()
            local resX, resY = getScreenResolution()
            local marginX, marginBottom, gap = 22, 42, 8
            local maxVisible = math.max(1, math.min(5, math.floor((resY - marginBottom - 22) / 98)))
            local maxWidth = math.min(430, math.max(210, resX - marginX * 2))
            local now = os.clock()
            for i = 1, #queue do
                local item = queue[i]
                if not item.shown then
                    item.shown, item.start = true, now
                    if item.force then grndPerfWrite("тост показан: " .. tostring(item.text)) end
                end
            end
            for i = #queue, 1, -1 do
                local item = queue[i]
                if now - item.start >= item.life then table.remove(queue, i) end
            end
            if grndUiBlocked() then
                for i = #queue, 1, -1 do
                    if not queue[i].force then table.remove(queue, i) end
                end
            end
            if #queue == 0 then
                _G.GRND_TOAST_STACK_TOP = nil
                return
            end
            local function drawToastIcon(dl, kind, cx, cy, style, alpha)
                local r, g, b = style.accent[1], style.accent[2], style.accent[3]
                local a = math.floor(255 * math.max(0, math.min(1, alpha or 1)))
                local stroke = col32(r, g, b, a)
                local fill = col32(r, g, b, math.floor(34 * math.max(0, math.min(1, alpha or 1))))
                pcall(function()
                    local center = im.ImVec2(cx, cy)
                    if dl.AddCircleFilled then dl:AddCircleFilled(center, 9.5, fill, 24) end
                    if dl.AddCircle then dl:AddCircle(center, 9.5, stroke, 24, 1.45) end
                    if kind == "ok" then
                        dl:AddLine(im.ImVec2(cx - 4.3, cy), im.ImVec2(cx - 1.2, cy + 3.1), stroke, 1.8)
                        dl:AddLine(im.ImVec2(cx - 1.2, cy + 3.1), im.ImVec2(cx + 4.5, cy - 3.4), stroke, 1.8)
                    elseif kind == "warn" then
                        dl:AddLine(im.ImVec2(cx, cy - 4.4), im.ImVec2(cx, cy + 1.3), stroke, 1.8)
                        if dl.AddCircleFilled then
                            dl:AddCircleFilled(im.ImVec2(cx, cy + 4.4), 1.05, stroke, 8)
                        end
                    elseif kind == "error" then
                        dl:AddLine(im.ImVec2(cx - 3.1, cy - 3.1), im.ImVec2(cx + 3.1, cy + 3.1), stroke, 1.7)
                        dl:AddLine(im.ImVec2(cx + 3.1, cy - 3.1), im.ImVec2(cx - 3.1, cy + 3.1), stroke, 1.7)
                    elseif kind == "progress" then
                        local ang = (os.clock() or 0) * 5.5
                        dl:AddLine(im.ImVec2(cx + math.cos(ang) * 2.8, cy + math.sin(ang) * 2.8),
                            im.ImVec2(cx + math.cos(ang) * 6.2, cy + math.sin(ang) * 6.2), stroke, 2.0)
                    else
                        if dl.AddRectFilled then
                            dl:AddRectFilled(im.ImVec2(cx - 0.9, cy - 2.7),
                                im.ImVec2(cx + 0.9, cy + 4.5), stroke)
                        else
                            dl:AddLine(im.ImVec2(cx, cy - 2.7), im.ImVec2(cx, cy + 4.5), stroke, 1.8)
                        end
                        if dl.AddCircleFilled then
                            dl:AddCircleFilled(im.ImVec2(cx, cy - 5.1), 1.2, stroke, 12)
                        end
                    end
                end)
            end
            local first = math.max(1, #queue - maxVisible + 1)
            local y = resY - marginBottom
            for i = #queue, first, -1 do
                local item = queue[i]
                local age = math.max(0, now - item.start)
                local enter = math.max(0, math.min(1, age / 0.30))
                local leave = math.max(0, math.min(1, (age - (item.life - 0.30)) / 0.30))
                if age < 0.30 then item.alpha = enter
                elseif age > item.life - 0.30 then item.alpha = 1 - leave
                else item.alpha = 1 end
                local style = TYPES[item.kind] or TYPES.info
                local measured = grndTextW(item.text)
                local minWidth = math.min(280, maxWidth)
                local width = math.min(maxWidth, math.max(minWidth, measured + 60))
                local textWidth = math.max(120, width - 58)
                local lines = math.max(1, math.min(3, math.ceil(measured / textWidth)))
                local height = math.max(44, 18 + lines * 18)
                local textY = math.max(8, (height - lines * 18) / 2)
                y = y - height
                local slideY = (1 - enter) * 20 + leave * 12
                local toastX = math.max(4, math.floor((resX - width) * 0.5))
                im.SetNextWindowPos(im.ImVec2(toastX, math.max(4, y + slideY)), COND_ALWAYS)
                im.SetNextWindowSize(im.ImVec2(width, height), COND_ALWAYS)
                grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, item.alpha)
                local styR = 0
                if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 11) then styR = styR + 1 end
                grndPushCol(im.Col and im.Col.WindowBg, rgba(13, 15, 27, 246))
                grndPushCol(im.Col and im.Col.Border, rgba(42, 46, 69, 235))
                grndPushCol(im.Col and im.Col.Text, rgba(235, 238, 248, 255))
                if grndBegin("grnd_toast_" .. item.id, WIN_FLAGS) then
                    local dl = im.GetWindowDrawList()
                    local pos = im.GetWindowPos()
                    drawToastIcon(dl, item.kind, pos.x + 23, pos.y + height / 2, style, item.alpha)
                    im.SetCursorPos(im.ImVec2(44, textY))
                    if type(im.TextWrapped) == "function" then im.TextWrapped(item.text)
                    elseif im.TextUnformatted then im.TextUnformatted(item.text)
                    else im.Text(item.text) end
                    endDepth = endDepth - 1
                    pcall(im.End)
                end
                grndPopCol(3)
                grndPopStyle(1 + styR)
                y = y - gap
            end
            _G.GRND_TOAST_STACK_TOP = y
        end

        do
            -- Векторные иконки ImDrawList в экранных координатах (без PathArcTo/AddBezier)
            function _G.grndDrawVecIcon(dl, kind, cx, cy, sz, col)
                if not dl then return end
                sz = tonumber(sz) or 14
                local r = sz * 0.5
                local v = im.ImVec2
                local line = dl.AddLine
                local circ = dl.AddCircle
                local circF = dl.AddCircleFilled
                local rect = dl.AddRect
                local rectF = dl.AddRectFilled
                pcall(function()
                    if kind == "settings" then
                        if circ then circ(dl, v(cx, cy), r * 0.48, col, 16, 1.5) end
                        for k = 0, 5 do
                            local ang = k * (math.pi / 3)
                            local x1, y1 = cx + math.cos(ang) * r * 0.58, cy + math.sin(ang) * r * 0.58
                            local x2, y2 = cx + math.cos(ang) * r * 0.92, cy + math.sin(ang) * r * 0.92
                            if line then line(dl, v(x1, y1), v(x2, y2), col, 1.6) end
                        end
                    elseif kind == "report" or kind == "chat" then
                        if rect then rect(dl, v(cx - r * 0.85, cy - r * 0.72), v(cx + r * 0.85, cy + r * 0.45), col, 3, 0, 1.45) end
                        if line then
                            line(dl, v(cx - r * 0.35, cy + r * 0.45), v(cx - r * 0.55, cy + r * 0.85), col, 1.45)
                            line(dl, v(cx - r * 0.55, cy + r * 0.85), v(cx + r * 0.05, cy + r * 0.45), col, 1.45)
                            line(dl, v(cx - r * 0.45, cy - r * 0.25), v(cx + r * 0.45, cy - r * 0.25), col, 1.3)
                            line(dl, v(cx - r * 0.45, cy + r * 0.08), v(cx + r * 0.22, cy + r * 0.08), col, 1.3)
                        end
                    elseif kind == "chrome" or kind == "globe" then
                        if circ then circ(dl, v(cx, cy), r * 0.86, col, 20, 1.45) end
                        if circ then circ(dl, v(cx, cy), r * 0.36, col, 14, 1.3) end
                        if line then
                            line(dl, v(cx - r * 0.84, cy), v(cx + r * 0.84, cy), col, 1.2)
                            line(dl, v(cx, cy - r * 0.84), v(cx, cy + r * 0.84), col, 1.2)
                        end
                    elseif kind == "complaints" then
                        if rect then rect(dl, v(cx - r * 0.72, cy - r * 0.86), v(cx + r * 0.72, cy + r * 0.86), col, 2.5, 0, 1.45) end
                        if line then
                            line(dl, v(cx - r * 0.38, cy - r * 0.36), v(cx + r * 0.38, cy - r * 0.36), col, 1.35)
                            line(dl, v(cx - r * 0.38, cy), v(cx + r * 0.38, cy), col, 1.35)
                            line(dl, v(cx - r * 0.38, cy + r * 0.36), v(cx + r * 0.14, cy + r * 0.36), col, 1.35)
                        end
                    elseif kind == "punish" then
                        if line then
                            line(dl, v(cx - r * 0.65, cy + r * 0.65), v(cx + r * 0.25, cy - r * 0.25), col, 1.8)
                            line(dl, v(cx + r * 0.02, cy - r * 0.62), v(cx + r * 0.62, cy - r * 0.02), col, 2.4)
                            line(dl, v(cx - r * 0.78, cy + r * 0.82), v(cx - r * 0.12, cy + r * 0.82), col, 1.6)
                        end
                    elseif kind == "mppanel" then
                        if line then
                            line(dl, v(cx - r * 0.75, cy + r * 0.2), v(cx + r * 0.45, cy - r * 0.65), col, 1.55)
                            line(dl, v(cx - r * 0.75, cy + r * 0.2), v(cx + r * 0.45, cy + r * 0.55), col, 1.55)
                            line(dl, v(cx + r * 0.45, cy - r * 0.65), v(cx + r * 0.45, cy + r * 0.55), col, 1.55)
                            line(dl, v(cx - r * 0.42, cy + r * 0.32), v(cx - r * 0.28, cy + r * 0.82), col, 1.55)
                        end
                    elseif kind == "logs" then
                        if rect then rect(dl, v(cx - r * 0.78, cy - r * 0.78), v(cx + r * 0.78, cy + r * 0.78), col, 2.5, 0, 1.4) end
                        if line then
                            line(dl, v(cx - r * 0.42, cy - r * 0.35), v(cx + r * 0.42, cy - r * 0.35), col, 1.35)
                            line(dl, v(cx - r * 0.42, cy), v(cx + r * 0.42, cy), col, 1.35)
                            line(dl, v(cx - r * 0.42, cy + r * 0.35), v(cx + r * 0.18, cy + r * 0.35), col, 1.35)
                        end
                    elseif kind == "checkers" or kind == "eye" then
                        if line then
                            line(dl, v(cx - r * 0.88, cy), v(cx, cy - r * 0.55), col, 1.45)
                            line(dl, v(cx, cy - r * 0.55), v(cx + r * 0.88, cy), col, 1.45)
                            line(dl, v(cx + r * 0.88, cy), v(cx, cy + r * 0.55), col, 1.45)
                            line(dl, v(cx, cy + r * 0.55), v(cx - r * 0.88, cy), col, 1.45)
                        end
                        if circF then circF(dl, v(cx, cy), r * 0.26, col, 12) end
                    elseif kind == "binder" then
                        if rect then rect(dl, v(cx - r * 0.88, cy - r * 0.55), v(cx + r * 0.88, cy + r * 0.55), col, 2.5, 0, 1.45) end
                        if rectF then
                            rectF(dl, v(cx - r * 0.56, cy - r * 0.22), v(cx - r * 0.32, cy - r * 0.02), col)
                            rectF(dl, v(cx - r * 0.12, cy - r * 0.22), v(cx + r * 0.12, cy - r * 0.02), col)
                            rectF(dl, v(cx + r * 0.32, cy - r * 0.22), v(cx + r * 0.56, cy - r * 0.02), col)
                            rectF(dl, v(cx - r * 0.42, cy + r * 0.16), v(cx + r * 0.42, cy + r * 0.32), col)
                        end
                    elseif kind == "cheats" then
                        if line then
                            line(dl, v(cx + r * 0.12, cy - r * 0.88), v(cx - r * 0.52, cy + r * 0.06), col, 1.65)
                            line(dl, v(cx - r * 0.52, cy + r * 0.06), v(cx + r * 0.08, cy + r * 0.06), col, 1.65)
                            line(dl, v(cx + r * 0.08, cy + r * 0.06), v(cx - r * 0.14, cy + r * 0.88), col, 1.65)
                        end
                    elseif kind == "character" or kind == "user" then
                        if circ then circ(dl, v(cx, cy - r * 0.32), r * 0.34, col, 14, 1.45) end
                        if line then
                            line(dl, v(cx - r * 0.68, cy + r * 0.78), v(cx - r * 0.42, cy + r * 0.24), col, 1.45)
                            line(dl, v(cx - r * 0.42, cy + r * 0.24), v(cx + r * 0.42, cy + r * 0.24), col, 1.45)
                            line(dl, v(cx + r * 0.42, cy + r * 0.24), v(cx + r * 0.68, cy + r * 0.78), col, 1.45)
                        end
                    elseif kind == "fwzone" or kind == "target" then
                        if circ then circ(dl, v(cx, cy), r * 0.78, col, 18, 1.4) end
                        if circF then circF(dl, v(cx, cy), r * 0.20, col, 10) end
                        if line then
                            line(dl, v(cx - r * 0.96, cy), v(cx - r * 0.45, cy), col, 1.35)
                            line(dl, v(cx + r * 0.45, cy), v(cx + r * 0.96, cy), col, 1.35)
                            line(dl, v(cx, cy - r * 0.96), v(cx, cy - r * 0.45), col, 1.35)
                            line(dl, v(cx, cy + r * 0.45), v(cx, cy + r * 0.96), col, 1.35)
                        end
                    elseif kind == "bwzone" or kind == "shield" then
                        if line then
                            line(dl, v(cx, cy - r * 0.86), v(cx + r * 0.72, cy - r * 0.48), col, 1.45)
                            line(dl, v(cx + r * 0.72, cy - r * 0.48), v(cx + r * 0.56, cy + r * 0.36), col, 1.45)
                            line(dl, v(cx + r * 0.56, cy + r * 0.36), v(cx, cy + r * 0.88), col, 1.45)
                            line(dl, v(cx, cy + r * 0.88), v(cx - r * 0.56, cy + r * 0.36), col, 1.45)
                            line(dl, v(cx - r * 0.56, cy + r * 0.36), v(cx - r * 0.72, cy - r * 0.48), col, 1.45)
                            line(dl, v(cx - r * 0.72, cy - r * 0.48), v(cx, cy - r * 0.86), col, 1.45)
                        end
                    elseif kind == "search" then
                        if circ then circ(dl, v(cx - r * 0.14, cy - r * 0.14), r * 0.56, col, 16, 1.45) end
                        if line then line(dl, v(cx + r * 0.26, cy + r * 0.26), v(cx + r * 0.82, cy + r * 0.82), col, 1.65) end
                    elseif kind == "recenter" then
                        if rect then rect(dl, v(cx - r * 0.68, cy - r * 0.52), v(cx + r * 0.68, cy + r * 0.52), col, 2, 0, 1.35) end
                        if circF then circF(dl, v(cx, cy), r * 0.20, col, 10) end
                    elseif kind == "camera" then
                        if rect then rect(dl, v(cx - r * 0.82, cy - r * 0.52), v(cx + r * 0.82, cy + r * 0.62), col, 2.5, 0, 1.4) end
                        if circ then circ(dl, v(cx, cy + r * 0.06), r * 0.34, col, 14, 1.35) end
                    elseif kind == "clock" then
                        if circ then circ(dl, v(cx, cy), r * 0.82, col, 18, 1.4) end
                        if line then
                            line(dl, v(cx, cy), v(cx, cy - r * 0.46), col, 1.45)
                            line(dl, v(cx, cy), v(cx + r * 0.38, cy + r * 0.16), col, 1.45)
                        end
                    end
                end)
            end

            -- Капсулы GRND: единый нижний стек; важные репорты используют расширенную карточку.
            function _G.grndDrawCapsules(dt)
                local C = GRND_CAP_NOTIFY
                if not C or type(C.items) ~= "table" or #C.items == 0 then return end
                if grndUiBlocked() then return end
                local now = os.clock()
                for i = #C.items, 1, -1 do
                    if now - (C.items[i].start or now) >= (C.items[i].life or 4.5) then
                        table.remove(C.items, i)
                    end
                end
                if #C.items == 0 then return end
                local resX, resY = getScreenResolution()
                -- All GRND-created alerts share a bottom-center stack.
                local botY = resY - 88
                if tonumber(_G.GRND_TOAST_STACK_TOP) then
                    botY = math.min(botY, tonumber(_G.GRND_TOAST_STACK_TOP) - 12)
                end
                for i = 1, #C.items do
                    local it = C.items[i]
                    local age = math.max(0, now - (it.start or now))
                    local life = math.max(1.0, tonumber(it.life) or 4.5)
                    local alpha = 1
                    if age < 0.22 then alpha = age / 0.22
                    elseif age > life - 0.28 then alpha = math.max(0, (life - age) / 0.28) end

                    if it.slot == "top" then
                        local bdg = tostring(it.badge or "ЧЕКЕР")
                        local txt = tostring(it.text or "")
                        if (tonumber(it.count) or 1) > 1 then txt = txt .. " ×" .. tostring(it.count) end
                        local bw = math.max(54, grndTextW(bdg) + 18)
                        local tw = grndTextW(txt)
                        local w = math.min(math.max(220, bw + tw + 46), math.max(260, resX - 80))
                        local h = 36
                        local x = math.floor((resX - w) * 0.5)
                        local enter = math.max(0, math.min(1, age / 0.22))
                        local leave = math.max(0, math.min(1, (age - (life - 0.28)) / 0.28))
                        local y = botY - h + (1 - enter) * 16 + leave * 10
                        botY = botY - h - 6
                        im.SetNextWindowPos(im.ImVec2(x, y), COND_ALWAYS)
                        im.SetNextWindowSize(im.ImVec2(w, h), COND_ALWAYS)
                        local nS, nC = 0, 0
                        if grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, alpha) then nS = nS + 1 end
                        if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 18) then nS = nS + 1 end
                        if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then nS = nS + 1 end
                        if grndPushCol(im.Col and im.Col.WindowBg, rgba(13, 15, 27, 242)) then nC = nC + 1 end
                        if grndPushCol(im.Col and im.Col.Border, rgba(124, 134, 242, 140)) then nC = nC + 1 end
                        if grndBegin("##grnd_cap_top_" .. tostring(it.id), WIN_FLAGS) then
                            local dl = im.GetWindowDrawList()
                            local pos = im.GetWindowPos()
                            local acR, acG, acB = 124, 134, 242
                            if it.kind == "ok" or it.kind == "success" then acR, acG, acB = 68, 215, 138
                            elseif it.kind == "warn" or it.kind == "warning" then acR, acG, acB = 245, 178, 66
                            elseif it.kind == "error" then acR, acG, acB = 245, 92, 102
                            elseif it.kind == "progress" or it.kind == "loading" then acR, acG, acB = 74, 174, 235 end
                            if dl and dl.AddRectFilled then
                                pcall(dl.AddRectFilled, dl,
                                    im.ImVec2(pos.x + 8, pos.y + 6),
                                    im.ImVec2(pos.x + 8 + bw, pos.y + h - 6),
                                    col32(acR, acG, acB, math.floor(42 * alpha)), 12)
                            end
                            im.SetCursorPos(im.ImVec2(17, 9))
                            if im.TextColored then
                                im.TextColored(rgba(acR, acG, acB, 255), bdg)
                            else
                                im.Text(bdg)
                            end
                            im.SetCursorPos(im.ImVec2(18 + bw, 9))
                            if im.TextColored then
                                im.TextColored(rgba(235, 238, 248, 255), txt)
                            else
                                im.Text(txt)
                            end
                            endDepth = endDepth - 1
                            pcall(im.End)
                        end
                        grndPopCol(nC)
                        grndPopStyle(nS)
                    else
                        local title = tostring(it.title or "Новый репорт")
                        local body = tostring(it.text or "")
                        local w = math.min(math.max(340, math.max(grndTextW(title), grndTextW(body)) + 68), math.max(340, resX - 100))
                        local h = 58
                        local x = math.floor((resX - w) * 0.5)
                        local enter = math.max(0, math.min(1, age / 0.22))
                        local leave = math.max(0, math.min(1, (age - (life - 0.28)) / 0.28))
                        local y = botY - h + (1 - enter) * 16 + leave * 10
                        botY = botY - h - 8
                        local rem = math.max(0, math.min(1, 1 - age / life))
                        im.SetNextWindowPos(im.ImVec2(x, y), COND_ALWAYS)
                        im.SetNextWindowSize(im.ImVec2(w, h), COND_ALWAYS)
                        local nS, nC = 0, 0
                        if grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, alpha) then nS = nS + 1 end
                        if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 14) then nS = nS + 1 end
                        if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then nS = nS + 1 end
                        if grndPushCol(im.Col and im.Col.WindowBg, rgba(13, 15, 27, 246)) then nC = nC + 1 end
                        if grndPushCol(im.Col and im.Col.Border, rgba(124, 134, 242, 165)) then nC = nC + 1 end
                        if grndBegin("##grnd_cap_bot_" .. tostring(it.id), WIN_FLAGS) then
                            local dl = im.GetWindowDrawList()
                            local pos = im.GetWindowPos()
                            _G.grndDrawVecIcon(dl, "report", pos.x + 22, pos.y + 26, 15,
                                col32(124, 134, 242, math.floor(245 * alpha)))
                            im.SetCursorPos(im.ImVec2(42, 8))
                            if im.TextColored then
                                im.TextColored(rgba(244, 246, 255, 255), title)
                            else
                                im.Text(title)
                            end
                            im.SetCursorPos(im.ImVec2(42, 27))
                            if im.TextColored then
                                im.TextColored(rgba(155, 162, 190, 255), body)
                            else
                                im.Text(body)
                            end
                            if dl and dl.AddRectFilled then
                                pcall(dl.AddRectFilled, dl,
                                    im.ImVec2(pos.x + 12, pos.y + h - 6),
                                    im.ImVec2(pos.x + w - 12, pos.y + h - 3),
                                    col32(255, 255, 255, math.floor(22 * alpha)), 2)
                                pcall(dl.AddRectFilled, dl,
                                    im.ImVec2(pos.x + 12, pos.y + h - 6),
                                    im.ImVec2(pos.x + 12 + (w - 24) * rem, pos.y + h - 3),
                                    col32(124, 134, 242, math.floor(235 * alpha)), 2)
                            end
                            endDepth = endDepth - 1
                            pcall(im.End)
                        end
                        grndPopCol(nC)
                        grndPopStyle(nS)
                    end
                end
            end
        end
        local TH = GRND_UIKIT.TH
        local function c32(t) return col32(t[1], t[2], t[3], t[4] or 255) end
        local function c4(t) return rgba(t[1], t[2], t[3], t[4] or 255) end
        pushStyleVec2 = function(var, x, y)
            local v = im.ImVec2(x, y)
            if im.PushStyleVarVec2 then
                local ok = pcall(im.PushStyleVarVec2, var, v)
                if ok then return true end
            end
            local ok = pcall(im.PushStyleVar, var, v)
            return ok
        end
        pushStyleFloat = function(var, val)
            if im.PushStyleVarFloat then
                local ok = pcall(im.PushStyleVarFloat, var, val)
                if ok then return true end
            end
            local ok = pcall(im.PushStyleVar, var, val)
            return ok
        end
        local function uiText(x, y, str, col, scale)
            scale = scale or 1
            local pushed = grndPushCol(im.Col and im.Col.Text, col)
            local scaled = false
            if scale ~= 1 and isFnV(im.SetWindowFontScale) then
                scaled = pcall(im.SetWindowFontScale, scale)
            end
            im.SetCursorPos(im.ImVec2(x, y))
            local tx = tostring(str)
            local okS, a, b2 = pcall(im.CalcTextSize, tx)
            local sx, sy
            if okS then
                local ta = type(a)
                if ta == "table" or ta == "cdata" then
                    sx, sy = tonumber(a.x), tonumber(a.y)
                elseif ta == "number" then
                    sx, sy = a, tonumber(b2)
                end
            end
            local size = { x = sx or (grndUtf8Len(tx) * 7), y = sy or (GRND_FONT.fontSize or 14) }
            if GRND_TEXT_SHADOW == true and im.ImVec4 then
                local pushedS = grndPushCol(im.Col and im.Col.Text,
                    im.ImVec4(0, 0, 0, 0.55))
                im.SetCursorPos(im.ImVec2(x + 1, y + 1))
                if im.TextUnformatted then im.TextUnformatted(str) else im.Text(str) end
                if pushedS then grndPopCol(1) end
                im.SetCursorPos(im.ImVec2(x, y))
            end
            if im.TextUnformatted then im.TextUnformatted(str) else im.Text(str) end
            if scaled then pcall(im.SetWindowFontScale, 1) end
            if pushed then grndPopCol(1) end
            return size.x, size.y
        end
        local function drawnWb(s, scale)
            scale = scale or 1
            if isFnV(im.SetWindowFontScale) then
                if scale ~= 1 then
                    pcall(im.SetWindowFontScale, scale)
                    local okM, aM = pcall(im.CalcTextSize, tostring(s))
                    pcall(im.SetWindowFontScale, 1)
                    if okM then
                        local ta = type(aM)
                        local w = (ta == "table" or ta == "cdata")
                            and tonumber(aM.x) or tonumber(aM)
                        if w and w > 0 then return w end
                    end
                end
                return grndTextW(s) * scale
            end
            return grndTextW(s)
        end
        _G.grndUiText   = uiText
        _G.grndC4       = c4
        _G.grndCol32    = col32
        _G.grndDrawnWb  = drawnWb
        local function drawDateTimeOverlay()
            local C = GRND_CLOCK
            if type(C) ~= "table" or (not C.enabled and not C.moving) then return false end
            local timeText, dateText = grndClockText()
            local scale = GRND_CLOCK.clampScale(C.scale)
            local dateScale = math.max(0.65, math.min(1.25, scale * 0.55))
            -- Fractional font scaling makes glyph edges soft.  Prefer the
            -- integer-pixel font ladder built by the UI and never scale a
            -- rasterized glyph by a fractional factor.
            local basePx = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16
            local function clockFontInfo(targetPx)
                targetPx = math.max(9, math.min(52, math.floor(targetPx + 0.5)))
                if type(grndUiFontPick) == "function" and isFnV(im.PushFont) then
                    local okF, font, pickedPx = pcall(grndUiFontPick, targetPx)
                    if okF and font and tonumber(pickedPx) then
                        return font, tonumber(pickedPx)
                    end
                end
                return nil, basePx
            end
            local timeFont, timePx = clockFontInfo(basePx * scale)
            local dateFont, datePx = clockFontInfo(basePx * dateScale)
            local timeRatio = timePx / math.max(1, basePx)
            local dateRatio = datePx / math.max(1, basePx)
            local timeW = grndTextW(timeText) * timeRatio
            local dateW = grndTextW(dateText) * dateRatio
            local timeH = math.max(12, timePx)
            local dateH = math.max(8, datePx)
            local pad = 3
            local W = math.max(80, math.ceil(math.max(timeW, dateW) + pad * 2 + 4))
            local H = math.max(28, timeH + dateH + 4)
            local sw, sh = getScreenResolution()
            sw, sh = tonumber(sw) or 1920, tonumber(sh) or 1080
            local maxX, maxY = math.max(0, sw - W), math.max(0, sh - H)
            local function clockMousePos()
                local mx, my
                if type(getCursorPos) == "function" then
                    local okP, px, py = pcall(getCursorPos)
                    if okP then mx, my = tonumber(px), tonumber(py) end
                end
                if not mx and type(im.GetMousePos) == "function" then
                    local okM, mp = pcall(im.GetMousePos)
                    if okM and mp then mx, my = tonumber(mp.x), tonumber(mp.y) end
                end
                if not mx and GRND_MOUSE then
                    mx, my = tonumber(GRND_MOUSE.x), tonumber(GRND_MOUSE.y)
                end
                return mx, my
            end
            local mouseX, mouseY = clockMousePos()
            if C.moving and C.followCursor and mouseX and mouseY then
                C.x = math.max(0, math.min(maxX, mouseX - W / 2))
                C.y = math.max(0, math.min(maxY, mouseY - H / 2))
            else
                C.x = math.max(0, math.min(maxX, tonumber(C.x) or 10))
                C.y = math.max(0, math.min(maxY, tonumber(C.y) or 8))
            end
            local flags = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
                "NoCollapse", "NoSavedSettings", "NoFocusOnAppearing",
                "NoBringToFrontOnFocus", "NoNavInputs", "NoNavFocus")
            if not C.moving then flags = flags + wf("NoInputs") end
            im.SetNextWindowPos(im.ImVec2(C.x, C.y), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            local opened = grndBeginTransparent("##grnd_clock_overlay", flags)
            if opened then
                local dl = im.GetWindowDrawList()
                local function clockText(x, y, text, font)
                    local pushedFont = false
                    if font and isFnV(im.PushFont) then
                        pushedFont = pcall(im.PushFont, font)
                    end
                    local pushed = false
                    if grndPushCol(im.Col and im.Col.Text, rgba(255, 255, 255, 255)) then
                        pushed = true
                    end
                    im.SetCursorPos(im.ImVec2(x, y))
                    if im.TextUnformatted then im.TextUnformatted(text) else im.Text(text) end
                    if pushed then grndPopCol(1) end
                    if pushedFont and isFnV(im.PopFont) then pcall(im.PopFont) end
                end
                local theme = (GRND_UIKIT and GRND_UIKIT.TH) or grndUiTheme()
                local accent = theme.accent or { 164, 112, 224, 255 }
                if C.moving and dl.AddRect then
                    pcall(dl.AddRect, dl, im.ImVec2(1, 1), im.ImVec2(W - 1, H - 1),
                        col32(accent[1], accent[2], accent[3], 230), 3, 0, 1.2)
                end
                if C.moving then
                    local down = false
                    if type(isKeyDown) == "function" then
                        local okD, d = pcall(isKeyDown, 0x01)
                        down = okD and d and true or false
                    end
                    if not down and type(im.IsMouseDown) == "function" then
                        local okD, d = pcall(im.IsMouseDown, 0)
                        down = okD and d and true or false
                    end
                    if not down and GRND_MOUSE then down = GRND_MOUSE.down and true or false end
                    local esc = C.cancelMove and true or false
                    if type(isKeyDown) == "function" then
                        local okE, e = pcall(isKeyDown, 0x1B)
                        esc = esc or (okE and e and true or false)
                    end
                    if esc and not C.escapeDown then
                        grndClockStopMoving(true)
                    elseif C.followCursor and os.clock() >= (C.moveReadyAt or 0)
                        and down and not C.mouseWasDown then
                        -- The widget follows the cursor until the first new
                        -- left click, which fixes and saves its current center.
                        grndClockStopMoving(false)
                    end
                    C.mouseWasDown = down
                    C.escapeDown = esc
                end
                clockText(pad, 0, timeText, timeFont)
                clockText(pad, timeH, dateText, dateFont)
            end
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            return C.moving and true or false
        end
        local function klNormalFontPath(path)
            path = tostring(path or "")
            if path == "" then return path end
            local dir, name = path:match("^(.*[\\/])([^\\/]+)$")
            dir, name = dir or "", name or path
            local low = name:lower()
            local cands = {}
            local stem = low:match("^(.*)bd(%.ttf)$")
            if stem then cands[#cands + 1] = stem .. ".ttf" end
            local stem2 = low:match("^(.*)bold(%.ttf)$")
            if stem2 then cands[#cands + 1] = stem2 .. ".ttf" end
            local stem3 = low:match("^(.*)%-bold(%.otf)$")
            if stem3 then cands[#cands + 1] = stem3 .. ".otf" end
            for _, c in ipairs(cands) do
                local try = dir .. c
                local f = io.open(try, "rb")
                if f then
                    f:close()
                    pcall(grndTrace, "font", "жирный шрифт заменён на обычный: " .. try)
                    return try
                end
            end
            return path
        end
        local UI_FONT_BASE = 16
        local function uiJoin(dir, name)
            dir = tostring(dir or "")
            local sep = "\\"
            if dir:find("/", 1, true) and not dir:find("\\", 1, true) then
                sep = "/"
            elseif not dir:find("\\", 1, true) then
                local okc, cf = pcall(function() return package.config end)
                if okc and type(cf) == "string" and #cf > 0 then sep = cf:sub(1, 1) end
            end
            return dir .. sep .. tostring(name)
        end
        local function uiFontDirs()
            local out = {}
            if type(this_script_dir) == "function" then
                local okd, sd = pcall(this_script_dir)
                if okd and sd and tostring(sd) ~= "" then
                    local pp = tostring(sd)
                    while pp:sub(-1) == "/" or pp:sub(-1) == "\\" do pp = pp:sub(1, -2) end
                    out[#out + 1] = uiJoin(pp, "fonts")
                end
            end
            out[#out + 1] = uiJoin(GRND_CONFIG.base(), "fonts")
            out[#out + 1] = "C:\\Windows\\Fonts"
            return out
        end
        local UI_FONT_ORDER = { "segoeui.ttf", "tahoma.ttf", "arial.ttf",
                                "verdana.ttf", "calibri.ttf", "trebuc.ttf" }
        local function uiFontCandidates()
            local out = {}
            local function add(p)
                p = tostring(p or "")
                if p == "" then return end
                local f = io.open(p, "rb")
                if f then f:close(); out[#out + 1] = p end
            end
            if GRND_FONT.fontPath and GRND_FONT.fontPath ~= "" then
                add(klNormalFontPath(GRND_FONT.fontPath))
                local file=tostring(GRND_FONT.fontPath):match("[^/\\]+$")
                for _,dir in ipairs(uiFontDirs()) do add(klNormalFontPath(uiJoin(dir,file))) end
            end
            for _, fn in ipairs(UI_FONT_ORDER) do
                for _, d in ipairs(uiFontDirs()) do add(uiJoin(d, fn)) end
            end
            return out
        end
        function grndUiFontList()
            local out, seen = {}, {}
            local function addP(p)
                p = tostring(p or "")
                if p == "" then return end
                local f = io.open(p, "rb")
                if not f then return end
                f:close()
                local key = p:lower()
                if seen[key] then return end
                seen[key] = true
                local nm = p:match("([^\\/]+)$") or p
                out[#out + 1] = { name = nm, path = p,
                                  title = (nm:gsub("%.[%w]+$", "")) }
            end
            local dirs = uiFontDirs()
            local lfs = (type(libs) == "table" and libs.lfs) or nil
            if lfs and lfs.dir and dirs[1] then
                pcall(function()
                    for nm in lfs.dir(dirs[1]) do
                        local low = tostring(nm):lower()
                        local e = low:match("%.([%w]+)$")
                        if e == "ttf" or e == "otf" then
                            addP(uiJoin(dirs[1], tostring(nm)))
                        end
                    end
                end)
            end
            for _, fn in ipairs(UI_FONT_ORDER) do
                for _, d in ipairs(dirs) do addP(uiJoin(d, fn)) end
            end
            addP(GRND_FONT.fontPath)
            return out
        end
        function grndUiFontApply(item)
            if type(item) ~= "table" then return false end
            GRND_FONT.fontPath = item.path
            GRND_FONT.fontName = item.title or item.name
            GRND_FONT.fontUserChosen = true
            GRND_FONT.cfgDirty = true
            GRND_FONT.fontStatus = "шрифт выбран: " .. tostring(item.name)
                .. " — применится после перезагрузки скрипта"
            return true
        end
        local function uiFontAdoptShared()
            local f = im and im.__grndUiFont
            if f then
                GRND_FONT.fontObj = f
                GRND_FONT.fontBase = im.__grndUiFontBase or UI_FONT_BASE
                GRND_FONT.fontLoadedPath = im.__grndUiFontPath
                GRND_FONT.fontInitDone = true
                return true
            end
            return false
        end
        local UI_RASTER_MULT = 1.30
        local function uiFontRasterCfg()
            if type(im) ~= "table" or type(im.ImFontConfig) ~= "function" then
                return nil
            end
            local okc, cfg = pcall(im.ImFontConfig)
            if not okc or not cfg then return nil end
            local okm = pcall(function()
                cfg.RasterizerMultiply = UI_RASTER_MULT
                cfg.OversampleH = 1
                cfg.OversampleV = 1
                cfg.PixelSnapH = true
                if tonumber(cfg.RasterizerMultiply) ~= UI_RASTER_MULT then
                    error("RasterizerMultiply не применился")
                end
            end)
            if not okm then return nil end
            return cfg
        end
        local function uiFontBuild(rebuild)
            if GRND_FONT.fontInitDone then return end
            if uiFontAdoptShared() then return end
            GRND_FONT.fontInitDone = true
            GRND_FONT.fontObj = false
            pcall(grndUiCfgLoad)
            if type(GRND_FONT.fontPath) == "string"
               and GRND_FONT.fontPath:lower():match("arial%.ttf$")
               and not GRND_FONT.fontUserChosen then
                pcall(grndTrace, "font",
                    "в конфиге старое умолчание arial.ttf — заменяю шрифтом нового списка")
                GRND_FONT.fontPath, GRND_FONT.fontName = nil, nil
                GRND_FONT.cfgDirty = true
            end
            local path = klNormalFontPath(uiFontCandidates()[1])
            if not path then
                pcall(grndTrace, "font", "шрифт интерфейса: файл не найден — системный")
                return
            end
            local ok, err = pcall(function()
                local io3 = im.GetIO()
                local fonts = io3.Fonts
                local ranges
                if fonts.GetGlyphRangesCyrillic then
                    ranges = fonts:GetGlyphRangesCyrillic()
                end
                local fcfg = uiFontRasterCfg()
                pcall(grndTrace, "font", fcfg
                    and ("растер-конфиг применён: Oversample 1/1, PixelSnapH, Multiply "
                         .. tostring(UI_RASTER_MULT))
                    or "растер-конфиг НЕ поддержан обёрткой — стандартная растеризация stb")
                local function addTTF(sz, cyrOnly)
                    if ranges then
                        if fcfg then
                            local oka, ra = pcall(fonts.AddFontFromFileTTF,
                                                  fonts, path, sz, fcfg, ranges)
                            if oka and ra then return ra end
                        end
                        local okb, rb = pcall(fonts.AddFontFromFileTTF,
                                              fonts, path, sz, nil, ranges)
                        if okb and rb then return rb end
                    end
                    if cyrOnly then return nil end
                    local okc2, rc = pcall(fonts.AddFontFromFileTTF, fonts, path, sz)
                    if okc2 and rc then return rc end
                    return nil
                end
                local f = addTTF(UI_FONT_BASE)
                if not f and im.AddFontFromFileTTF then
                    local okd, rd = pcall(im.AddFontFromFileTTF, path, UI_FONT_BASE)
                    if okd then f = rd end
                end
                local ladder = im.__grndFontLadder or {}
                if ranges then
                    for _, lsz in ipairs({ 9, 11, 13, 15, 16, 17, 19, 20, 21,
                                           23, 24, 26, 28, 29, 32, 34, 36,
                                           38, 40, 42, 44, 46, 48, 52 }) do
                        if not ladder[lsz] then
                            local lf = addTTF(lsz, true)
                            if lf then ladder[lsz] = lf end
                        end
                    end
                end
                if next(ladder) then im.__grndFontLadder = ladder end
                local szl = {}
                for sz in pairs(ladder) do szl[#szl + 1] = tonumber(sz) or 0 end
                table.sort(szl)
                GRND_FONT.ladderSizes = szl
                if f then
                    if rebuild and im.RebuildFonts then
                        im.RebuildFonts()
                    end
                    GRND_FONT.fontObj = f
                    GRND_FONT.fontBase = UI_FONT_BASE
                    GRND_FONT.fontLoadedPath = path
                    im.__grndUiFont = f
                    im.__grndUiFontBase = UI_FONT_BASE
                    im.__grndUiFontPath = path
                    pcall(grndTrace, "font", "шрифт интерфейса загружен: " .. path)
                end
            end)
            if not ok then
                pcall(grndTrace, "font", "шрифт интерфейса не загрузился: " .. tostring(err))
            end
        end
        local function uiFontRegister()
            if GRND_FONT.fontHooked then return end
            GRND_FONT.fontHooked = true
            pcall(grndUiCfgLoad)
            pcall(uiFontAdoptShared)
            if imKind == "mimgui" and type(im.OnInitialize) == "function" then
                im.OnInitialize(function() uiFontBuild(false) end)
            else
                im.__grndFontHooks = im.__grndFontHooks or {}
                im.__grndFontHooks[#im.__grndFontHooks + 1] = function()
                    pcall(uiFontBuild, true)
                end
                if not im.__grndFontWrapped then
                    im.__grndFontWrapped = true
                    local prev = im.BeforeDrawFrame
                    im.BeforeDrawFrame = function(...)
                        if type(prev) == "function" then
                            local okp, e = pcall(prev, ...)
                            if not okp then pcall(grndTrace, "font", "чужой BeforeDrawFrame упал: " .. tostring(e)) end
                        end
                        for _, h in ipairs(im.__grndFontHooks) do
                            local okh, eh = pcall(h, ...)
                            if not okh then pcall(grndTrace, "font", "font-хук упал: " .. tostring(eh)) end
                        end
                    end
                end
            end
        end
        local function uiFontGet()
            return GRND_FONT.fontObj
        end
        local function uiPushFont()
            local f = uiFontGet()
            if type(f) == "number" or type(f) == "cdata" or type(f) == "table" then
                local ok = pcall(im.PushFont, f)
                if ok then return true end
            end
            return false
        end
        local function uiPopFont(pushed)
