        function grndUiFontPick(px)
            local L = im and im.__grndFontLadder
            if type(L) ~= "table" then return nil end
            local best, bsz, bd
            px = tonumber(px) or 16
            for sz, f in pairs(L) do
                local n = tonumber(sz) or 0
                local d = math.abs(n - px)
                if bd == nil or d < bd or (d == bd and n > (bsz or 0)) then
                    best, bsz, bd = f, n, d
                end
            end
            return best, bsz
        end
