        local klPrevLmb = false
        local function klLmbTapped(checker)
            local state = checker or GRND_KL
            if state and state.click then
                state.click = false
                klPrevLmb = true
                return true
            end
            local down = false
            if type(isKeyDown) == "function" then
                local ok, d = pcall(isKeyDown, 0x01)
                if ok then down = d and true or false end
            elseif GRND_MOUSE then
                down = GRND_MOUSE.down and true or false
            end
            local tapped = down and not klPrevLmb
            klPrevLmb = down
            return tapped
        end
        local function klSetMoving(on, cancelMove)
            local KL = GRND_KL
            if not KL then return end
            if on then
                if KL.moving then return end
                KL.moving = true
                KL.armed = false
                KL.armAt = os.clock() + 0.35
                KL.click = false
                KL.cancel = false
                KL.moveOldX, KL.moveOldY = KL.x, KL.y
                local mx, my = klMousePos()
                if mx and KL.x and KL.y and KL.w and KL.h
                   and mx >= KL.x and mx <= KL.x + KL.w
                   and my >= KL.y and my <= KL.y + KL.h then
                    KL.grabX, KL.grabY = mx - KL.x, my - KL.y
                else
                    KL.grabX = (KL.w or 160) / 2
                    KL.grabY = (KL.h or 60) / 2
                end
                if not KL.enabled then
                    KL.enabled = true
                    KL.cfgDirty = true
                end
                local mn = _G.GRND_MENU
                if mn then mn.open = false end
                pcall(clwShowCursor, true)
                if type(grndUiControls) == "function" then pcall(grndUiControls, true) end
                if type(notify.add) == "function" then
                    pcall(notify.add, "Kill List: двигайте мышью, ЛКМ — закрепить, ESC — отмена; по строке ЛКМ — слежка", "info", 4)
                end
            else
                if not KL.moving then return end
                KL.moving = false
                KL.click = false
                KL.armed = false
                KL.ignoreSpecUntil = os.clock() + 0.25
                if GRND_MOUSE then
                    GRND_MOUSE.clicked, GRND_MOUSE.rclicked = false, false
                    GRND_MOUSE.clickedBtn, GRND_MOUSE.rclickedBtn = nil, nil
                end
                if cancelMove and KL.moveOldX ~= nil then
                    KL.x, KL.y = KL.moveOldX, KL.moveOldY
                end
                pcall(clwShowCursor, false)
                if type(grndUiControls) == "function" then
                    local mn2=_G.GRND_MENU
                    pcall(grndUiControls,(mn2 and mn2.open) or GRND_TAB.open
                        or (_G.GRND_REP and _G.GRND_REP.open)
                        or (_G.GRND_RC and _G.GRND_RC.show)
                        or (_G.GRND_KL and _G.GRND_KL.moving)
                        or (_G.GRND_AO and _G.GRND_AO.moving))
                end
                KL.cfgDirty = true
                pcall(grndKlCfgSave)
                if type(notify.add) == "function" then
                    pcall(notify.add, cancelMove and "Kill List: перемещение отменено"
                        or "Kill List: позиция закреплена",
                        cancelMove and "warn" or "ok", 3)
                end
            end
        end
