        local function klArgbCol(c)
            if type(c) ~= "number" or c == 0 then return 235, 240, 245 end
            local u = math.floor(c) % 0x100000000
            local r = math.floor(u / 0x10000) % 256
            local g = math.floor(u / 0x100) % 256
            local b = u % 256
            if r + g + b == 0 then return 235, 240, 245 end
            local lum = 0.299 * r + 0.587 * g + 0.114 * b
            if lum < 72 then
                local lift = math.floor(72 - lum + 0.5)
                r = math.min(255, math.floor(r * 1.35 + lift))
                g = math.min(255, math.floor(g * 1.35 + lift))
                b = math.min(255, math.floor(b * 1.35 + lift))
            end
            return r, g, b
        end
        local ATL = GRND_KL_ATLAS or {}
