            end
            ATL.cell = ATL.cell or GRND_KL_ATLAS_CELL or 24
            ATL.cols = ATL.cols or GRND_KL_ATLAS_COLS or 8
            ATL.tw = ATL.tw or GRND_KL_ATLAS_W or 256
            ATL.th = ATL.th or GRND_KL_ATLAS_H or 256
            ATL.rows = math.max(1, math.ceil(#ATL.ids / math.max(1, ATL.cols)))
        end
        local function klAtlasIndex(id)
            klAtlasSync()
            id = tonumber(id) or 0
            if id == 255 then id = 53 end
            if id == 44  then id = 45 end
            for i = 1, #ATL.ids do
                if ATL.ids[i] == id then return i end
            end
            if id > 0 then
                for i = 1, #ATL.ids do
                    if ATL.ids[i] == 53 then return i end
                end
            end
            return nil
        end
