        local function klB64Decode(s)
            local A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
            local lut = {}
            for i = 1, #A do lut[A:sub(i, i)] = i - 1 end
            local out, acc, nbits = {}, 0, 0
            for i = 1, #s do
                local ch = s:sub(i, i)
                if ch == "=" then break end
                local v = lut[ch]
                if v then
                    acc = acc * 64 + v
                    nbits = nbits + 6
                    while nbits >= 8 do
                        nbits = nbits - 8
                        out[#out + 1] = string.char(math.floor(acc / 2 ^ nbits) % 256)
                    end
                    acc = acc % 2 ^ nbits
                end
            end
            return table.concat(out)
        end
