        local function klAtlasWriteFile(png)
            if ATL.fileOk then return ATL.filePath end
            local path = klAtlasFilePath()
            if not path then ATL.fileWhy = "не нашёл каталог для файла" return nil end
            local ok, f = pcall(io.open, path, "wb")
            if not ok or not f then
                ATL.fileWhy = "файл не записался: " .. tostring(path)
                return nil
            end
            local okw = pcall(f.write, f, png)
            pcall(f.close, f)
            if not okw then ATL.fileWhy = "ошибка записи: " .. tostring(path) return nil end
            ATL.fileOk = true
            return path
        end
        local function klAtlasBuffer()
            if ATL.ptr then return ATL.ptr end
            if ATL.ptrTried then return nil end
