            local okf, ffi = pcall(require, "ffi")
            if not okf or type(ffi) ~= "table" then ATL.ptrWhy = "нет ffi" return nil end
            local okb, buf = pcall(function()
                local b = ffi.new("char[?]", #ATL.png)
                ffi.copy(b, ATL.png, #ATL.png)
                return b
            end)
            if okb and buf then ATL.ptr, ATL.ffi = buf, ffi
            else ATL.ptrWhy = "буфер не создался" end
            return ATL.ptr
        end
        local function klAtlasAttempts()
            local list = {}
            local function add(name, fn) list[#list + 1] = { name = name, fn = fn } end
            if type(im.CreateTextureFromFileInMemory) == "function" then
