            if type(im.CreateTextureFromFile) == "function" then
                add("CreateTextureFromFile(grnd_kl_atlas.png)", function()
                    local path = klAtlasWriteFile(ATL.png)
                    if not path then return nil, ATL.fileWhy or "файл недоступен" end
                    return im.CreateTextureFromFile(path)
                end)
            end
            if type(im.CreateTextureFromMemory) == "function" then
                add("CreateTextureFromMemory(адрес, размер)", function()
                    local buf = klAtlasBuffer()
                    if not buf then return nil, ATL.ptrWhy or "нет буфера" end
                    local addr = buf
                    if ATL.ffi then
                        local okn, n = pcall(function()
                            return tonumber(ATL.ffi.cast("uintptr_t", buf))
                        end)
                        if okn and type(n) == "number" then addr = n end
                    end
                    return im.CreateTextureFromMemory(addr, #ATL.png)
                end)
            end
            if type(im.CreateTextureFromMemoryRaw) == "function" then
                add("CreateTextureFromMemoryRaw(адрес, размер)", function()
                    local buf = klAtlasBuffer()
                    if not buf then return nil, ATL.ptrWhy or "нет буфера" end
                    local addr = buf
                    if ATL.ffi then
                        local okn, n = pcall(function()
                            return tonumber(ATL.ffi.cast("uintptr_t", buf))
                        end)
                        if okn and type(n) == "number" then addr = n end
                    end
                    return im.CreateTextureFromMemoryRaw(addr, #ATL.png)
                end)
            end
            if type(im.LoadTextureFromFile) == "function" then
                add("LoadTextureFromFile(grnd_kl_atlas.png)", function()
                    local path = klAtlasWriteFile(ATL.png)
                    if not path then return nil, ATL.fileWhy or "файл недоступен" end
                    return im.LoadTextureFromFile(path)
                end)
            end
            return list
        end
        function grndKlAtlasEnsure(force)
            if force then ATL.tried, ATL.tex, ATL.how = false, nil, nil end
            if ATL.tried then return ATL.tex ~= nil end
            ATL.tried = true
            klAtlasSync()
            ATL.tries = {}
            if type(im) ~= "table" then ATL.why = "нет ImGui" return false end
            local okd, png = pcall(klB64Decode, GRND_KL_ATLAS_PNG or "")
            if not okd or type(png) ~= "string" or #png < 64 then
                ATL.why = "атлас не распаковался"
                pcall(grndTrace, "killlist", "значки: base64 атласа не декодировался")
                return false
            end
            ATL.png = png
            local have = {}
            for _, n in ipairs({ "CreateTextureFromFile", "CreateTextureFromFileInMemory",
                                 "CreateTextureFromMemory", "CreateTextureFromMemoryRaw",
                                 "LoadTextureFromFile" }) do
                if type(im[n]) == "function" then have[#have + 1] = n end
            end
            ATL.have = have
            if #have == 0 then
                ATL.why = "у обёртки ImGui нет функций для текстур"
                pcall(grndTrace, "killlist", "значки килл-листа: " .. ATL.why)
                return false
            end
            for _, att in ipairs(klAtlasAttempts()) do
                local ok, t, err = pcall(att.fn)
                local rec = { name = att.name, ok = false, err = nil }
                if not ok then
                    rec.err = tostring(t)
                elseif t then
                    rec.ok = true
                    ATL.tex, ATL.how = t, att.name
                else
                    rec.err = tostring(err or "функция вернула nil")
                end
                ATL.tries[#ATL.tries + 1] = rec
                if rec.ok then break end
            end
            if ATL.tex then
                pcall(grndTrace, "killlist", "значки килл-листа: оригинальный атлас загружен ("
                    .. tostring(ATL.how) .. ", " .. tostring(ATL.tw) .. "x" .. tostring(ATL.th) .. ")")
                return true
            end
            local firstErr
            for _, tr in ipairs(ATL.tries) do
                if not tr.ok and tr.err then firstErr = tr.err break end
            end
            ATL.why = "ни один способ не подошёл" .. (firstErr and (" (" .. firstErr .. ")") or "")
            pcall(grndTrace, "killlist", "значки килл-листа: атлас не загрузился — запасной рисованный силуэт")
            return false
        end
        function grndKlAtlasDiag()
            grndKlSay("— значки килл-листа —")
            grndKlSay(("обёртка ImGui: %s"):format(tostring(IMGUI_WRAP or "не определена")))
            grndKlSay(("файл атласа: %s%s"):format(
                tostring(ATL.filePath or klAtlasFilePath() or "—"),
                ATL.fileOk and " (записан)" or ""))
            if not ATL.tex then pcall(grndKlAtlasEnsure, true) end
            if ATL.tex then
                grndKlSay(("атлас ЗАГРУЖЕН: способ «%s», текстура %sx%s"):format(
                    tostring(ATL.how), tostring(ATL.tw), tostring(ATL.th)))
                return true
            end
            grndKlSay("атлас НЕ загружен — рисуется запасной силуэт")
            grndKlSay(("функции обёртки: %s"):format(
                (#(ATL.have or {}) > 0) and table.concat(ATL.have, ", ")
                or "НИ ОДНОЙ (текстуры этой сборкой не поддерживаются)"))
            for i, tr in ipairs(ATL.tries or {}) do
                grndKlSay(("  %d) %s -> %s"):format(i, tr.name,
                    tr.ok and "ок" or ("не вышло: " .. tostring(tr.err))))
            end
            if ATL.fileWhy then grndKlSay("  про файл: " .. tostring(ATL.fileWhy)) end
            if ATL.ptrWhy then grndKlSay("  про буфер: " .. tostring(ATL.ptrWhy)) end
            grndKlSay("  пришли эти строки — добавим способ под твою сборку")
            return false
        end
        local function klIconBlit(dl, at, x, y, sz, sh, id, a)
            if not (dl and id and sz and sz >= 6) then return false end
            if not grndKlAtlasEnsure() then return false end
            local idx = klAtlasIndex(id)
            if not idx then return false end
            klAtlasSync()
            local cell, cols, rows = ATL.cell, ATL.cols, ATL.rows
            local tw, th = ATL.tw, ATL.th
            local col = (idx - 1) % cols
            local row = math.floor((idx - 1) / cols)
            local iw, ih = 23, 24
            local W = math.max(1, math.floor(sz + 0.5))
            local H = math.max(1, math.floor(
                (tonumber(sh) or (sz * (ih / iw))) + 0.5))
            local u0, v0 = (col * cell) / tw, (row * cell) / th
            local u1, v1 = (col * cell + iw) / tw, (row * cell + ih) / th
            local ox, oy = math.floor(x + 0.5), math.floor(y + 0.5)
            local p1, p2 = at(ox, oy), at(ox + W, oy + H)
            local uv0, uv1 = im.ImVec2(u0, v0), im.ImVec2(u1, v1)
            local tint = col32(255, 255, 255,
                math.max(0, math.min(255, math.floor(255 * (a or 1)))))
            if type(dl.AddImage) == "function" then
                if pcall(dl.AddImage, dl, ATL.tex, p1, p2, uv0, uv1, tint) then return true end
                if pcall(dl.AddImage, dl, ATL.tex, p1, p2, uv0, uv1) then return true end
                if pcall(dl.AddImage, dl, ATL.tex, p1, p2) then return true end
                if type(dl.Image) == "function"
                   and pcall(dl.Image, dl, ATL.tex, p1, p2, uv0, uv1, tint) then return true end
            end
            return false
        end
        function grndKlAtlasPreload()
            pcall(grndBrandLogoLoad,im)
            pcall(grndKlRunsBuild)
            if ATL.tried and ATL.tex then return true end
            return pcall(grndKlAtlasEnsure)
        end
        if not ATL.hooked then
            ATL.hooked = true
            local hooked = false
            if type(im.OnInitialize) == "function" then
                hooked = pcall(im.OnInitialize, function()
                    GRND_BRAND_LOGO.retryAt=nil
                    pcall(grndKlAtlasPreload)
                end)
            end
            if not hooked then
                im.__grndTexHooks = im.__grndTexHooks or {}
                im.__grndTexHooks[#im.__grndTexHooks + 1] = function() pcall(grndKlAtlasPreload) end
                if not im.__grndTexWrapped then
                    im.__grndTexWrapped = true
                    local prevTex = im.BeforeDrawFrame
                    im.BeforeDrawFrame = function(...)
                        if type(prevTex) == "function" then
                            local okp, ep = pcall(prevTex, ...)
                            if not okp then pcall(grndTrace, "killlist", "чужой BeforeDrawFrame упал: " .. tostring(ep)) end
                        end
                        for _, h in ipairs(im.__grndTexHooks) do
                            local okh, eh = pcall(h, ...)
                            if not okh then pcall(grndTrace, "killlist", "хук текстуры упал: " .. tostring(eh)) end
                        end
                    end
                end
            end
            pcall(grndKlAtlasPreload)
        end
        if type(addEventHandler) == "function" and not ATL.resetHooked then
            ATL.resetHooked = true
            pcall(addEventHandler, "onD3DDeviceReset", function()
                ATL.tex, ATL.tried, ATL.how = nil, false, nil
                GRND_BRAND_LOGO.tex,GRND_BRAND_LOGO.retryAt=nil,nil
                ATL.needReload = true
                pcall(grndKlAtlasPreload)
            end)
        end
        local KL_RUN_COL = {
            [1] = {    8,   8,   9 },
            [2] = {  111, 111, 111 },
            [3] = {  174, 174, 174 },
            [4] = {  248, 247, 248 },
        }
        function grndKlRunsBuild()
            if ATL.runs ~= nil then return ATL.runs end
            ATL.runs = false
            local data = klB64Decode(GRND_KL_ICON_RUNS or "")
            if type(data) ~= "string" or #data < 128 then
                ATL.runsWhy = "данные значков не распаковались"
                return false
            end
            local icons, i, n = {}, 1, #data
            while i + 6 <= n do
                local x0, y0, x1, y1 = data:byte(i, i + 3)
                local ar, ag, ab = data:byte(i + 4, i + 6)
                i = i + 7
                local runs = {}
                while i <= n do
                    local b = data:byte(i)
                    if not b or b == 0xFF then i = i + 1 break end
                    runs[#runs + 1] = { t = math.floor(b / 32), y = b % 32,
                                        x0 = data:byte(i + 1), x1 = data:byte(i + 2) }
                    i = i + 3
                end
                icons[#icons + 1] = { x0 = x0, y0 = y0, x1 = x1, y1 = y1,
                                      ar = ar, ag = ag, ab = ab, runs = runs }
            end
            if #icons == 0 then
                ATL.runsWhy = "в данных значков нет ни одной записи"
                return false
            end
            ATL.runs = icons
            ATL.runsCount = #icons
            return icons
        end
        local function klRunsDraw(dl, at, x, y, bs, bh, id, a)
            if not (dl and dl.AddRectFilled and bs and bs >= 6) then return false end
            local icons = grndKlRunsBuild()
            if not icons then return false end
            local idx = klAtlasIndex(id)
            if not idx then return false end
            local ic = icons[idx]
            if not ic then return false end
            local kx = (bs / 23)
            local ky = ((tonumber(bh) or (bs * 24 / 23)) / 24)
            if kx <= 0 then kx = 1 end
            if ky <= 0 then ky = 1 end
            local BW = math.max(1, math.floor(bs + 0.5))
            local BH = math.max(1, math.floor((tonumber(bh) or (bs * 24 / 23)) + 0.5))
            local ox, oy = math.floor(x + 0.5), math.floor(y + 0.5)
            local function grid(v, k, lim)
                local t = math.floor(v * k + 0.5)
                if t < 0 then return 0 end
                if t > lim then return lim end
                return t
            end
            local function gx(v) return ox + grid(v, kx, BW) end
            local function gy(v) return oy + grid(v, ky, BH) end
            local k = (kx < ky) and kx or ky
            local A = math.max(0, math.min(255, math.floor(255 * (a or 1))))
            local tile = KL_RUN_COL[1]
            local tx0, ty0 = gx(ic.x0), gy(ic.y0)
            local tx1, ty1 = gx(ic.x1 + 1), gy(ic.y1 + 1)
            if tx1 <= tx0 then if tx0 > ox then tx0 = tx0 - 1 else tx1 = tx0 + 1 end end
            if ty1 <= ty0 then if ty0 > oy then ty0 = ty0 - 1 else ty1 = ty0 + 1 end end
            pcall(dl.AddRectFilled, dl, at(tx0, ty0), at(tx1, ty1),
                col32(tile[1], tile[2], tile[3], A),
                math.min(6, math.max(1, 5 * k)))
            for i = 1, #ic.runs do
                local r = ic.runs[i]
                local c = KL_RUN_COL[r.t]
                if not c and r.t == 5 then c = { ic.ar, ic.ag, ic.ab } end
                if c then
                    local rx0, ry0 = gx(r.x0), gy(r.y)
                    local rx1, ry1 = gx(r.x1 + 1), gy(r.y + 1)
                    if rx1 <= rx0 then if rx0 > ox then rx0 = rx0 - 1 else rx1 = rx0 + 1 end end
                    if ry1 <= ry0 then if ry0 > oy then ry0 = ry0 - 1 else ry1 = ry0 + 1 end end
                    pcall(dl.AddRectFilled, dl, at(rx0, ry0), at(rx1, ry1),
                        col32(c[1], c[2], c[3], A))
                end
            end
            return true
        end
        local function klWeaponGlyph(dl, at, x, y, bs, bh, rec, a, us, col, hole)
            local id = klIconIdOf(rec)
            if not id then return false end
            if klIconBlit(dl, at, x, y, bs, bh, id, a) then return true end
            return klRunsDraw(dl, at, x, y, bs, bh, id, a)
        end
        local function klSpecGo(nick, id)
            if not id and type(grndKlFindId) == "function" then
                local ok, r = pcall(grndKlFindId, nick)
                if ok then id = r end
            end
            if not id then
                if type(notify.add) == "function" then
                    pcall(notify.add, "Kill List: " .. tostring(nick) .. " — не в сети", "warn", 3)
                end
                return false
            end
            if type(GRND_TAB) ~= "table" then return false end
            GRND_TAB.specId = id
            GRND_TAB.open = false
            return true
        end
        local klDx = { fonts = {}, dead = false, fam = nil }
        local function klDxFamily()
            if klDx.fam then return klDx.fam end
            local known = {
                segoeui = "Segoe UI", tahoma = "Tahoma", arial = "Arial",
                verdana = "Verdana", calibri = "Calibri", trebuc = "Trebuchet MS",
            }
            local nm = "Tahoma"
            local key = nm:lower():gsub("%s+", "")
            klDx.fam = known[key] or nm
            return klDx.fam
        end
        local function klDxCol(r, g, b, al)
            local function cc(v)
                v = math.floor(tonumber(v) or 0)
                if v < 0 then v = 0 elseif v > 255 then v = 255 end
                return v
            end
            return cc(al) * 0x1000000 + cc(r) * 0x10000 + cc(g) * 0x100 + cc(b)
        end
        local function klDxFont(px)
            if GRND_KL and GRND_KL.dxReset then
                klDx.fonts, klDx.fam, klDx.dead = {}, nil, false
                GRND_KL.dxReset = false
            end
            if klDx.dead then return nil end
            if type(renderCreateFont) ~= "function"
                or type(renderFontDrawText) ~= "function"
                or type(renderGetFontDrawTextLength) ~= "function" then
                klDx.dead = true
                pcall(grndTrace, "killlist",
                    "render-библиотека недоступна — текст кил-листа через ImGui")
                return nil
            end
            px = math.floor(tonumber(px) or 16)
            if px < 7 then px = 7 end
            local key = tostring(px) .. "|" .. klDxFamily()
            local f = klDx.fonts[key]
            if f then return f end
            local fam = klDxFamily()
            local font
            local ok4, f4 = pcall(renderCreateFont, fam, -px, 4, 204)
            if ok4 and f4 then font = f4 end
            if not font then
                ok4, f4 = pcall(renderCreateFont, "Tahoma", -px, 4, 204)
                if ok4 and f4 then font = f4 end
            end
            if not font then
                local ok, f = pcall(renderCreateFont, fam, -px, 0)
                if ok and f then font = f end
            end
            if font then
                klDx.fonts[key] = font
                pcall(grndTrace, "killlist", "DX-шрифт кил-листа: "
                    .. fam .. " " .. tostring(px) .. " px, regular outlined, charset 204")
                return font
            end
            klDx.dead = true
            pcall(grndTrace, "killlist",
                "renderCreateFont не удался — текст кил-листа через ImGui")
            return nil
        end
        local aoDxFonts, aoDxBordered = {}, {}
        local function aoDxFont(px)
            px = math.floor(tonumber(px) or 14)
            if px < 7 then px = 7 elseif px > 32 then px = 32 end
            local f = aoDxFonts[px]
            if f then return f, aoDxBordered[px] end
            if type(renderCreateFont) ~= "function" then
                return klDxFont(px), false
            end
            local font, bordered = nil, false
            local ok, r = pcall(renderCreateFont, "Tahoma", -px, 4, 204)
            if ok and r then font, bordered = r, true end
            if not font then
                ok, r = pcall(renderCreateFont, "Tahoma", -px, 0)
                if ok and r then font = r end
            end
            if not font then return klDxFont(px), false end
            aoDxFonts[px] = font
            aoDxBordered[px] = bordered
            return font, bordered
        end
        local function drawKillList(dt)
            local KL = GRND_KL
            if not KL then return false end
            dt = dt or 0.016
            local target = KL.enabled and 1 or 0
            KL.anim = KL.anim or 0
            if KL.anim < target then KL.anim = math.min(target, KL.anim + dt * 8.0)
            elseif KL.anim > target then KL.anim = math.max(target, KL.anim - dt * 8.0) end
            if KL.anim <= 0 and not KL.moving then
                KL.hwK, KL.hwV, KL.hwKAt, KL.hwVAt = nil, nil, nil, nil
                return false
            end
            local a = 1 - (1 - KL.anim) * (1 - KL.anim)
            if KL.enabled or KL.moving then a = 1 end
            if KL.moving then
                pcall(clwShowCursor, true)
            end
            local resX, resY = getScreenResolution()
            local sc   = math.max(0.25, math.min(2.5, tonumber(KL.scale) or 1.0))
            local rows = math.max(1, math.min(24, math.floor(tonumber(KL.rows) or 6)))
            local baseSize = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16
            local wantPx = math.floor(baseSize * sc + 0.5)
            if wantPx < 7 then wantPx = 7 elseif wantPx > 40 then wantPx = 40 end
            local fobj, fsz
            if type(grndUiFontPick) == "function" then
                local okf, rf, rs = pcall(grndUiFontPick, wantPx)
                if okf then fobj, fsz = rf, tonumber(rs) end
            end
            local fontPushed, fontViaLadder, fsc = false, false, 1
            if fobj and isFnV(im.PushFont) then
                fontViaLadder = pcall(im.PushFont, fobj) and true or false
            end
            if fontViaLadder then
                fontPushed = true
            else
                fontPushed = uiPushFont()
                fsc = wantPx / baseSize
            end
            -- Always unwind the font stack, even if a draw-list/window call fails.
            -- Otherwise an intermittent error can leave a small font active globally.
            local baseEndDepth, nStyle = endDepth, 0
            local bodyOk, bodyResult = pcall(function()
            if math.abs(fsc - 1) < 0.01 then fsc = 1 end
            local fpx = wantPx
            if fontViaLadder then
                fpx = tonumber(fsz) or wantPx
                if fpx < 9 then fpx = wantPx end
            end
            local us  = fpx / baseSize
            local dxf = klDxFont(fpx)
            local function dxStr(s)
                s = tostring(s or "")
                if dxf and type(grndToAnsi) == "function" then
                    local ok, r = pcall(grndToAnsi, s)
                    if ok and type(r) == "string" then return r end
                end
                return s
            end
            local function dxW(s)
                local raw = tostring(s or "")
                if dxf then
                    local okw, w = pcall(renderGetFontDrawTextLength, dxf, dxStr(raw))
                    if okw and type(w) == "number" and w > 0 then return w end
                end
                return grndTextW(raw) * fsc
            end
            local function klTimeText(value)
                local raw = tostring(value or "00:00:00")
                    :gsub("^%[", ""):gsub("%]$", "")
                local h, m, s = raw:match("^(%d+):(%d+):(%d+)$")
                if not h then
                    h, m = raw:match("^(%d+):(%d+)$")
                    s = h and "0" or nil
                end
                if not h then return "[" .. raw .. "]" end
                return string.format("[%02d:%02d:%02d]", tonumber(h) or 0,
                    tonumber(m) or 0, tonumber(s) or 0)
            end
            local padX  = math.max(2, math.floor(10 * sc + 0.5))
            local padY  = math.max(1, math.floor(6 * sc + 0.5))
            local ikRaw = (fpx * 1.20) / 24
            local iconW = math.max(7, math.floor(23 * ikRaw + 0.5))
            local iconH = math.max(8, math.floor(24 * ikRaw + 0.5))
            local gapIcon = math.max(2, math.floor(7 * sc + 0.5))
            local gapK, gapV = gapIcon, gapIcon
            local timeGap = KL.showTime and math.max(1, math.floor(4 * us)) or 0
            local textH = fpx
            if dxf and type(renderGetFontDrawHeight) == "function" then
                local okh, dh = pcall(renderGetFontDrawHeight, dxf)
                if okh and type(dh) == "number" and dh > 0 and dh <= 80 then
                    textH = math.floor(dh + 0.5)
                end
            end
            local rowH = math.max(iconH + 2, math.floor(textH + 4.5))
            local shA = (KL.textShadow == false) and 0 or (dxf and 58 or 48)
            local hist = KL.hist or {}
            local yDef  = math.floor(resY * 0.30)
            local fitN  = math.floor((resY - (tonumber(KL.y) or yDef) - padY * 2) / rowH)
            if fitN < 1 then fitN = 1 end
            local n = math.min(rows, #hist, fitN)
            local list = {}
            for i = 1, n do list[i] = hist[#hist - n + i] end
            if KL.newestTop then
                local rev = {}
                for i = 1, n do rev[i] = list[n - i + 1] end
                list = rev
            end
            local kStr, vStr, wK, wV = {}, {}, {}, {}
            local kTimeStr, kTimeW, kNickW = {}, {}, {}
            local maxK, maxV, maxN = 0, 0, 0
            for i = 1, n do
                local r = list[i]
                local ks, vs = tostring(r.ku or r.k or "?"), tostring(r.vu or r.v or "?")
                ks = ks:gsub("^[%s\194\160]+", ""):gsub("[%s\194\160]+$", "")
                vs = vs:gsub("^[%s\194\160]+", ""):gsub("[%s\194\160]+$", "")
                if ks == "" then ks = "?" end
                if vs == "" then vs = "?" end
                local kb, vb = r.kidF, r.vidF
                if kb ~= nil then ks = ks .. "[" .. tostring(kb) .. "]" end
                if vb ~= nil then vs = vs .. "[" .. tostring(vb) .. "]" end
                kStr[i], vStr[i] = ks, vs
                kTimeStr[i] = KL.showTime and klTimeText(r.time) or nil
                kTimeW[i] = kTimeStr[i] and dxW(kTimeStr[i]) or 0
                kNickW[i] = dxW(ks)
                wK[i] = kNickW[i] + (kTimeStr[i] and (kTimeW[i] + timeGap) or 0)
                wV[i] = dxW(vs)
                if wK[i] > maxK then maxK = wK[i] end
                if wV[i] > maxV then maxV = wV[i] end
                if KL.showWName then
                    local wn = dxW(klWeaponLabel(r))
                    if wn > maxN then maxN = wn end
                end
            end
            if n == 0 then
                maxK = dxW("Ник_Игрока[999]")
                maxV = maxK
            end
            local clockNow = os.clock()
            local SHRINK_HOLD = 0.25
            local function klFitCol(w, key, atKey)
                local target = math.ceil(w)
                local prev = tonumber(KL[key]) or 0
                if target >= prev then
                    KL[key], KL[atKey] = target, clockNow
                    return target
                end
                local seen = tonumber(KL[atKey]) or clockNow
                if (clockNow - seen) < SHRINK_HOLD then return prev end
                local step = prev - 1
                if step < target then step = target end
                KL[key] = step
                return step
            end
            if KL.cfgDirty then KL.hwK, KL.hwV, KL.hwKAt, KL.hwVAt = nil, nil, nil, nil end
            maxK = klFitCol(maxK, "hwK", "hwKAt")
            maxV = klFitCol(maxV, "hwV", "hwVAt")
            maxK, maxV = math.ceil(maxK), math.ceil(maxV)
            local nameX = padX
            local wName = 0
            if KL.showWName and maxN > 0 then wName = math.floor(maxN) + gapV end
            local colK   = maxK
            -- Each killer's time and nickname form one width-aware group.
            local iconX  = math.floor(nameX + colK + gapK + 0.5)
            local vx0    = math.floor(iconX + iconW + wName + gapV + 0.5)
            local killerXs, iconXs = {}, {}
            local iconGroupW = iconW + wName
            for i = 1, n do
                local kx = nameX
                if KL.alignK then
                    kx = math.floor(iconX - gapK - (wK[i] or 0) + 0.5)
                    if kx < nameX then kx = nameX end
                end
                killerXs[i] = kx
                iconXs[i] = math.floor((kx + (wK[i] or 0) + vx0 - iconGroupW) / 2 + 0.5)
            end
            local hintH  = KL.moving and (math.floor(14 * us) + 8) or 0
            local hint   = "ЛКМ — закрепить   ·   ESC — отмена; по строке ЛКМ — слежка"
            local W = math.floor(vx0 + maxV + padX)
            local minW = math.floor(150 * us)
            if KL.moving then
                local hw = math.floor(dxW(hint) + padX * 2)
                if hw > minW then minW = hw end
            end
            if W < minW then W = minW end
            local H = math.floor(padY * 2 + math.max(1, n) * rowH + hintH)
            KL.dbgAlign = KL.alignK
                and (("ники убийц — вплотную к значку (зазор %d px)"):format(gapK))
                or  (("ники убийц — ровный столбец по левому краю (x=%d)"):format(padX))
            KL.dbgColK, KL.dbgColV = colK, maxV
            KL.dbgIconX, KL.dbgVx0 = iconX, vx0
            KL.dbgFpx  = fpx
            KL.dbgRowH = rowH
            KL.dbgFsc, KL.dbgFitN = fsc, fitN
            KL.dbgFontViaLadder = fontViaLadder
            KL.dbgDx    = dxf and true or false
            KL.dbgDxFam = dxf and klDxFamily() or nil
            KL.dbgDxPx  = dxf and fpx or nil
            KL.dbgShA   = shA
            if KL.x == nil then KL.x = math.floor(resX - W - 24) end
            if KL.y == nil then KL.y = math.floor(resY * 0.30) end
            if KL.x + W > resX - 4 then KL.x = resX - 4 - W end
            if KL.y + H > resY - 4 then KL.y = resY - 4 - H end
            if KL.x < 0 then KL.x = 0 end
            if KL.y < 0 then KL.y = 0 end
            local wasMoving = KL.moving
            if KL.moving then
                if not KL.armed and os.clock() > (KL.armAt or 0)
                   and not (GRND_MOUSE and GRND_MOUSE.down) then
                    KL.armed = true
                end
                local mx, my = klMousePos()
                if mx then
                    KL.x = math.floor(mx - (KL.grabX or W / 2))
                    KL.y = math.floor(my - (KL.grabY or H / 2))
                end
                KL.x = math.max(0, math.min(math.max(0, resX - 40), KL.x))
                KL.y = math.max(0, math.min(math.max(0, resY - 20), KL.y))
                if KL.cancel then
                    KL.cancel = false
                    klSetMoving(false, true)
                elseif KL.armed and klLmbTapped(KL) then
                    klSetMoving(false, false)
                end
            end
            KL.w, KL.h = W, H
            -- чекер стоит на своём месте: панель рекона его не двигает
            local hoverRow, hoverSide = nil, nil
            local cursorOn = (type(GRND_KEYS) == "table") and (GRND_KEYS.cursorOn == true)
            local leftClick = type(grndLeftClickPending) == "function"
                and grndLeftClickPending()
            local rightClick = type(grndRightClickPending) == "function"
                and grndRightClickPending()
            local canSelect = type(grndCheckerCanSelectRow) == "function"
                and grndCheckerCanSelectRow(cursorOn, leftClick,
                    KL.moving or wasMoving, KL.ignoreSpecUntil, os.clock())
            local doInteract = canSelect and n > 0 and not (menu and menu.open)
            local mx, my
            if doInteract then
                if (leftClick or rightClick) and GRND_MOUSE then
                    mx, my = tonumber(GRND_MOUSE.x), tonumber(GRND_MOUSE.y)
                else
                    mx, my = klMousePos()
                end
                if mx and tonumber(my) and type(grndCheckerPointTaken) == "function"
                   and grndCheckerPointTaken(mx, my) then
                    mx, my = nil, nil
                end
                if mx and tonumber(my) and KL.x and KL.y
                   and mx >= KL.x and mx <= KL.x + W
                   and my >= KL.y and my <= KL.y + H then
                    local idx = math.floor((my - KL.y - padY) / rowH) + 1
                    if idx >= 1 and idx <= n then
                        hoverRow = idx
                        hoverSide = ((mx - KL.x) > ((iconXs[idx] or iconX) + iconW * 0.5))
                            and "v" or "k"
                    end
                end
            end
            if (KL.moving or wasMoving) and rightClick then
                GRND_MOUSE.rclicked, GRND_MOUSE.rclickedBtn = false, nil
            elseif hoverRow and not KL.moving and leftClick then
                local r = list[hoverRow]
                if r then
                    GRND_MOUSE.clicked = false
                    local onVictim = (hoverSide == "v")
                    local nick = onVictim and (r.vu or r.v) or (r.ku or r.k)
                    local pid  = onVictim and r.vid or r.kid
                    pcall(klSpecGo, nick, pid)
                end
            end
            im.SetNextWindowPos(im.ImVec2(KL.x, KL.y), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            if grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, a) then nStyle = nStyle + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then nStyle = nStyle + 1 end
            if grndBeginTransparent("##grnd_killlist", KL_WIN_FLAGS) then
                local dl = im.GetWindowDrawList()
                local pos = im.GetWindowPos()
                local function at(dx, dy) return im.ImVec2(pos.x + dx, pos.y + dy) end
                local function col(r, g, b, al)
                    return col32(r, g, b, math.max(0, math.min(255, math.floor(al))))
                end
                local holeCol = col(0, 0, 0, 160 * a)
                local function outText(x, y, txt, r, g, b, al, shMul)
                    shMul = (shMul == nil) and 1 or shMul
                    x, y = math.floor(x), math.floor(y)
                    txt = dxStr(txt)
                    local sal = (shA > 0) and math.floor(shA * shMul) or 0
                    local ax, ay = KL.x + x, KL.y + y
                    -- Чекер всегда рисуется целиком. Он вызывается до окон:
                    -- перекрывающая панель закроет текст своим фоном вместо
                    -- того, чтобы отбрасывать всю строку при частичном пересечении.
                    if dxf then
                        if sal > 0 then
                            pcall(renderFontDrawText, dxf, txt, ax + 1, ay + 1,
                                klDxCol(0, 0, 0, sal * a))
                        end
                        pcall(renderFontDrawText, dxf, txt, ax, ay,
                            klDxCol(r, g, b, al * a))
                    else
                        if sal > 0 then
                            uiText(x + 1, y + 1, txt, col(0, 0, 0, sal * a), fsc)
                        end
                        uiText(x, y, txt, col(r, g, b, al * a), fsc)
                    end
                end
                local emptyLabel = grndKlEmptyLabel(KL, n)
                if emptyLabel then
                    outText(padX, padY + 2, emptyLabel, 150, 155, 165, 255)
                end
                for i = 1, n do
                    local r = list[i]
                    local y  = padY + (i - 1) * rowH
                    local ty = y + math.floor((rowH - textH) / 2 + 0.5)
                    local kr, kg, kb = klArgbCol(r.kc)
                    local vr, vg, vb = klArgbCol(r.vc)
                    local kw = math.ceil(wK[i] or 0)
                    local kx = killerXs[i] or nameX
                    local rowIconX = iconXs[i] or iconX
                    local nickX = kx
                    if kTimeStr[i] then
                        outText(kx, ty, kTimeStr[i], 150, 155, 165, 255)
                        nickX = kx + kTimeW[i] + timeGap
                    end
                    outText(nickX, ty, kStr[i], kr, kg, kb, 255)
                    local gy = y + math.floor((rowH - iconH) / 2 + 0.5)
                    local hasIcon = false
                    -- Глифы оружия рисуются на draw-list напрямую и могут оказаться
                    -- над окном даже при правильном порядке Begin(). Пропускаем только
                    -- сам значок, если он реально лежит под чужой панелью.
                    if not grndCheckerBandTaken(KL.x + rowIconX, KL.y + gy,
                            KL.x + rowIconX + iconW, KL.y + gy + iconH) then
                        hasIcon = klWeaponGlyph(dl, at, rowIconX, gy, iconW, iconH, r, a,
                            us, col, holeCol)
                    end
                    if KL.showWName and hasIcon then
                        local nm = klWeaponLabel(r)
                        if nm ~= "" then
                            outText(rowIconX + iconW + gapV, ty, nm, 206, 213, 226, 255, 0.9)
                        end
                    end
                    outText(vx0, ty, vStr[i], vr, vg, vb, 255)
                    if hoverRow == i then
                        local ux, uw
                        if hoverSide == "v" then
                            ux, uw = vx0, math.ceil(wV[i] or 0)
                        else
                            ux, uw = kx, kw
                        end
                        local uy = math.floor(y + rowH - 2)
                        if uy < ty + fpx + 3 then uy = math.floor(ty + fpx + 3) end
                        pcall(dl.AddLine, dl, at(ux, uy), at(ux + uw, uy),
                            col(255, 255, 255, 210 * a), 1.0)
                    end
                end
                if KL.moving then
                    if dl.AddRect then
                        pcall(dl.AddRect, dl, at(0, 0), at(W, H), c32(TH.accent), 6 * us, 0, 1.5)
                    end
                    local hw = dxW(hint)
                    local hx = math.floor((W - hw) / 2)
                    if hx < 4 then hx = 4 end
                    outText(hx, math.floor(H - hintH + 4 * us), hint,
                        TH.accent[1], TH.accent[2], TH.accent[3], 255)
                end
            end
            return KL.moving
            end)
            while endDepth > baseEndDepth do
                endDepth = endDepth - 1
                pcall(im.End)
            end
            grndPopStyle(nStyle)
            if fontPushed then
                if fontViaLadder then pcall(im.PopFont) else pcall(uiPopFont, true) end
            end
            if not bodyOk then error(bodyResult) end
            return bodyResult
        end
        local function aoSetMoving(on, cancelMove)
            local AO = GRND_AO
            if not AO then return end
            if on then
                if AO.moving then return end
                AO.moving = true
                AO.armed = false
                AO.armAt = os.clock() + 0.35
                AO.click = false
                AO.cancel = false
                AO.moveOldX, AO.moveOldY = AO.x, AO.y
                local mx, my = klMousePos()
                if mx and AO.x and AO.y and AO.w and AO.h
                   and mx >= AO.x and mx <= AO.x + AO.w
                   and my >= AO.y and my <= AO.y + AO.h then
                    AO.grabX, AO.grabY = mx - AO.x, my - AO.y
                else
                    AO.grabX = (AO.w or 160) / 2
                    AO.grabY = (AO.h or 60) / 2
                end
                if not AO.enabled then
                    AO.enabled = true
                    AO.cfgDirty = true
                end
                local mn = _G.GRND_MENU
                if mn then mn.open = false end
                pcall(clwShowCursor, true)
                if type(grndUiControls) == "function" then pcall(grndUiControls, true) end
                if notify and type(notify.add) == "function" then
                    pcall(notify.add, "Админы в сети: двигайте мышью, ЛКМ — закрепить, ESC — отмена; по строке ЛКМ — слежка", "info", 4)
                end
            else
                if not AO.moving then return end
                AO.moving = false
                AO.armed = false
                AO.click = false
                AO.ignoreSpecUntil = os.clock() + 0.25
                if GRND_MOUSE then
                    GRND_MOUSE.clicked, GRND_MOUSE.rclicked = false, false
                    GRND_MOUSE.clickedBtn, GRND_MOUSE.rclickedBtn = nil, nil
                end
                if cancelMove and AO.moveOldX ~= nil then
                    AO.x, AO.y = AO.moveOldX, AO.moveOldY
                end
                pcall(clwShowCursor, false)
                if type(grndUiControls) == "function" then
                    local mn2=_G.GRND_MENU
                    pcall(grndUiControls,(mn2 and mn2.open) or GRND_TAB.open
                        or (_G.GRND_REP and _G.GRND_REP.open)
                        or (_G.GRND_RC and _G.GRND_RC.show)
                        or (_G.GRND_KL and _G.GRND_KL.moving)
                        or (_G.GRND_AO and _G.GRND_AO.moving))
                end
                AO.cfgDirty = true
                pcall(grndAoCfgSave)
                if notify and type(notify.add) == "function" then
                    pcall(notify.add, cancelMove and "Админы в сети: перемещение отменено"
                        or "Админы в сети: позиция закреплена",
                        cancelMove and "warn" or "ok", 3)
                end
            end
        end
        local function drawAdminsOnline(dt)
            local AO = GRND_AO
            if not AO then return false end
            dt = dt or 0.016
            if AO.wantMove then
                AO.wantMove = false
                pcall(aoSetMoving, true)
            end
            local target = AO.enabled and 1 or 0
            AO.anim = AO.anim or 0
            if AO.anim < target then AO.anim = math.min(target, AO.anim + dt * 8.0)
            elseif AO.anim > target then AO.anim = math.max(target, AO.anim - dt * 8.0) end
            if AO.anim <= 0 and not AO.moving then return false end
            local a = 1 - (1 - AO.anim) * (1 - AO.anim)
            if AO.enabled or AO.moving then a = 1 end
            if AO.moving then
                pcall(clwShowCursor, true)
            end
            local resX, resY = getScreenResolution()
            local sc = math.max(0.25, math.min(2.5, tonumber(AO.scale) or 1.0))
            local baseSize = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16
            local wantPx = math.floor(baseSize * sc + 0.5)
            if wantPx < 7 then wantPx = 7 elseif wantPx > 40 then wantPx = 40 end
            local fobj, fsz
            if type(grndUiFontPick) == "function" then
                local okf, rf, rs = pcall(grndUiFontPick, wantPx)
                if okf then fobj, fsz = rf, tonumber(rs) end
            end
            local fontPushed, fontViaLadder, fsc = false, false, 1
            if fobj and isFnV(im.PushFont) then
                fontViaLadder = pcall(im.PushFont, fobj) and true or false
            end
            if fontViaLadder then
                fontPushed = true
            else
                fontPushed = uiPushFont()
                fsc = wantPx / baseSize
            end
            -- Always unwind the font stack, even if a draw-list/window call fails.
            -- Otherwise an intermittent error can leave a small font active globally.
            local baseEndDepth, nStyle = endDepth, 0
            local bodyOk, bodyResult = pcall(function()
            if math.abs(fsc - 1) < 0.01 then fsc = 1 end
            local fpx = wantPx
            if fontViaLadder then
                fpx = tonumber(fsz) or wantPx
                if fpx < 9 then fpx = wantPx end
            end
            local dxf, dxBorder = aoDxFont(fpx)
            local function dxStr(s)
                s = tostring(s or "")
                if dxf and type(grndToAnsi) == "function" then
                    local ok, r = pcall(grndToAnsi, s)
                    if ok and type(r) == "string" then return r end
                end
                return s
            end
            local function dxW(s)
                local raw = tostring(s or "")
                if dxf then
                    local okw, w = pcall(renderGetFontDrawTextLength, dxf, dxStr(raw))
                    if okw and type(w) == "number" and w > 0 then return w end
                end
                return grndTextW(raw) * fsc
            end
            local function rgbOf(id)
                if type(id) ~= "number" or id < 0 or id == 65535 then return nil end
                if type(sampGetPlayerColor) ~= "function" then return nil end
                local ok, c = pcall(sampGetPlayerColor, id)
                if not ok or type(c) ~= "number" then return nil end
                if c < 0 then c = c + 0x100000000 end
                local r = math.floor(c / 0x10000) % 256
                local g = math.floor(c / 0x100) % 256
                local b = c % 256
                if r + g + b == 0 then return nil end
                return r, g, b
            end
            local function pausedOf(id)
                if type(id) ~= "number" or type(sampIsPlayerPaused) ~= "function" then
                    return false
                end
                local ok, p = pcall(sampIsPlayerPaused, id)
                return ok and p and true or false
            end
            local pending = AO.collect or {}
            local list = (#pending > 0) and grndAoSortedCopy(pending) or (AO.list or {})
            local rows = {}
            local afkN = 0
            for i = 1, #list do
                local e = list[i]
                local id = e.id
                if (not id) and e.nick and type(sampGetPlayerIdByNickname) == "function" then
                    local ok, nid = pcall(sampGetPlayerIdByNickname, e.nick)
                    if ok and type(nid) == "number" and nid >= 0 and nid ~= 65535 then
                        id = nid
                        e.id = nid
                    end
                end
                local afk = e.afk or pausedOf(id)
                if afk then afkN = afkN + 1 end
                local r, g, b = rgbOf(id)
                rows[#rows + 1] = {
                    nick = e.nick or "?",
                    id = id,
                    lvl = e.lvl,
                    afk = afk,
                    afkSec = e.afkSec,
                    r = r, g = g, b = b,
                }
            end
            AO.afkSince = AO.afkSince or {}
            local nowClk = os.clock()
            local seenAfk = {}
            local function aoFmtAfk(sec)
                sec = math.max(0, math.floor(tonumber(sec) or 0))
                local h = math.floor(sec / 3600)
                local m = math.floor((sec % 3600) / 60)
                local s = sec % 60
                if h > 0 then
                    return string.format("%d:%02d:%02d", h, m, s)
                end
                return string.format("%02d:%02d", m, s)
            end
            for i = 1, #rows do
                local e = rows[i]
                local key = e.nick
                seenAfk[key] = true
                if e.afk then
                    if not AO.afkSince[key] then
                        AO.afkSince[key] = nowClk - (tonumber(e.afkSec) or 0)
                    end
                    e.afkStr = " | AFK " .. aoFmtAfk(nowClk - AO.afkSince[key])
                else
                    AO.afkSince[key] = nil
                    e.afkStr = nil
                end
            end
            for k, _ in pairs(AO.afkSince) do
                if not seenAfk[k] then AO.afkSince[k] = nil end
            end
            local headTitle = "Администрация"
            local headSub = string.format("%d в сети (AFK: %d)", #rows, afkN)
            local head = {
                { l = headTitle, v = "", r = 244, g = 246, b = 252 },
                { l = headSub,   v = "", r = 148, g = 156, b = 182 },
            }
            local us = fpx / 16
            local padX = math.max(3, math.floor(10 * sc + 0.5))
            local padY = math.max(2, math.floor(6 * sc + 0.5))
            local rowH = math.max(11, math.floor(fpx + 4.5))
            if dxf and type(renderGetFontDrawHeight) == "function" then
                local okH, fh = pcall(renderGetFontDrawHeight, dxf)
                if okH and type(fh) == "number" and fh > 8 then
                    rowH = math.max(11, math.floor(fh + 2))
                end
            end
            local gapH = math.max(3, math.floor(6 * sc + 0.5))
            local colGap = math.max(6, math.floor(10 * sc + 0.5))
            local shA = 0
            if dxf and not dxBorder then shA = 55
            elseif not dxf then shA = 70 end
            local hint = "ЛКМ — закрепить   ·   ESC — отмена; по строке ЛКМ — слежка"
            local hintH = AO.moving and (rowH + 6) or 0
            local headW = math.max(dxW(headTitle), dxW(headSub))
            local colIdW, colNickW, colLvlW, colAfkW = 0, 0, 0, 0
            for i = 1, #rows do
                local e = rows[i]
                local idPart = e.id and ("[" .. tostring(e.id) .. "]") or "[—]"
                e.idPart = idPart
                e.idw = dxW(idPart)
                e.nw = dxW(e.nick)
                e.lvlStr = e.lvl and (tostring(e.lvl) .. " LVL") or ""
                e.lw = e.lvlStr ~= "" and dxW(e.lvlStr) or 0
                if e.afk and AO.afkSince[e.nick] then
                    e.afkClean = "AFK " .. aoFmtAfk(nowClk - AO.afkSince[e.nick])
                else
                    e.afkClean = nil
                end
                e.aw = (e.afkClean and dxW(e.afkClean)) or 0
                if e.idw > colIdW then colIdW = e.idw end
                if e.nw > colNickW then colNickW = e.nw end
                if e.lw > colLvlW then colLvlW = e.lw end
                if e.aw > colAfkW then colAfkW = e.aw end
            end
            -- Row layout is content-left / ID-right; never reserve an ID column at the left.
            local contentW = colNickW
                + (colLvlW > 0 and (colGap + colLvlW) or 0)
                + (colAfkW > 0 and (colGap + colAfkW) or 0)
            local listW = contentW + colGap + colIdW
            if #rows == 0 then
                listW = math.max(listW, dxW("ожидание ответа /admins…"))
            end
            local maxW = math.max(headW, listW)
            if AO.moving then
                local hw = dxW(hint)
                if hw > maxW then maxW = hw end
            end
            local W = math.floor(maxW + padX * 2)
            if W < 180 then W = 180 end
            W = math.min(W, math.max(180, resX - 8))
            local sepH = math.max(1, math.floor(1 * us + 0.5))
            local H = math.floor(padY * 2 + #head * rowH + gapH + sepH + gapH
                + math.max(1, #rows) * rowH + hintH)
            if H < rowH * 3 then H = rowH * 3 end
            if AO.x == nil then AO.x = 18 end
            if AO.y == nil then AO.y = math.floor(resY * 0.10) end
            if AO.x + W > resX - 4 then AO.x = resX - 4 - W end
            if AO.y + H > resY - 4 then AO.y = resY - 4 - H end
            if AO.x < 0 then AO.x = 0 end
            if AO.y < 0 then AO.y = 0 end
            local wasMoving = AO.moving
            if AO.moving then
                if not AO.armed and os.clock() > (AO.armAt or 0)
                   and not (GRND_MOUSE and GRND_MOUSE.down) then
                    AO.armed = true
                end
                local mx, my = klMousePos()
                if mx then
                    AO.x = math.floor(mx - (AO.grabX or W / 2))
                    AO.y = math.floor(my - (AO.grabY or H / 2))
                end
                AO.x = math.max(0, math.min(math.max(0, resX - 40), AO.x))
                AO.y = math.max(0, math.min(math.max(0, resY - 20), AO.y))
                if AO.cancel then
                    AO.cancel = false
                    aoSetMoving(false, true)
                elseif AO.armed and klLmbTapped(AO) then
                    aoSetMoving(false, false)
                end
            end
            AO.w, AO.h = W, H
            local listY0 = padY + #head * rowH + math.floor(gapH * 0.45) + sepH + gapH
            local hoverI = nil
            local cursorOn = (type(GRND_KEYS) == "table") and (GRND_KEYS.cursorOn == true)
            local leftClick = type(grndLeftClickPending) == "function"
                and grndLeftClickPending()
            local rightClick = type(grndRightClickPending) == "function"
                and grndRightClickPending()
            local canSelect = type(grndCheckerCanSelectRow) == "function"
                and grndCheckerCanSelectRow(cursorOn, leftClick,
                    AO.moving or wasMoving, AO.ignoreSpecUntil, os.clock())
            local doInteract = canSelect and #rows > 0 and not (menu and menu.open)
            if doInteract then
                local mx, my
                if (leftClick or rightClick) and GRND_MOUSE then
                    mx, my = tonumber(GRND_MOUSE.x), tonumber(GRND_MOUSE.y)
                else
                    if im.GetIO then
                        local ok, io2 = pcall(im.GetIO)
                        if ok and io2 and io2.MousePos then
                            mx = tonumber(io2.MousePos.x)
                            my = tonumber(io2.MousePos.y)
                            if not mx then
                                pcall(function()
                                    mx = io2.MousePos.x + 0
                                    my = io2.MousePos.y + 0
                                end)
                            end
                        end
                    end
                    if not mx then mx, my = klMousePos() end
                end
                if mx and tonumber(my) and type(grndCheckerPointTaken) == "function"
                   and grndCheckerPointTaken(mx, my) then
                    mx, my = nil, nil
                end
                if mx and tonumber(my) and AO.x and AO.y
                   and mx >= AO.x and mx <= AO.x + W
                   and my >= AO.y + listY0 and my <= AO.y + H then
                    local idx = math.floor((my - (AO.y + listY0)) / rowH) + 1
                    if idx >= 1 and idx <= #rows then hoverI = idx end
                end
            end
            if (AO.moving or wasMoving) and rightClick then
                GRND_MOUSE.rclicked, GRND_MOUSE.rclickedBtn = false, nil
            elseif hoverI and not AO.moving and leftClick then
                local e = rows[hoverI]
                if e then
                    GRND_MOUSE.clicked = false
                    if type(klSpecGo) == "function" then
                        pcall(klSpecGo, e.nick, e.id)
                    end
                end
            end
            local function outText(x, y, txt, r, g, b, al)
                x, y = math.floor(x + 0.5), math.floor(y + 0.5)
                txt = dxStr(txt)
                al = al or 255
                local sal = shA
                local ax, ay = AO.x + x, AO.y + y
                -- Чекер рисуется целиком под окнами; панели будут отрисованы
                -- позже и перекроют только ту часть, которая реально совпала.
                if dxf then
                    if sal > 0 then
                        pcall(renderFontDrawText, dxf, txt, ax + 1, ay + 1,
                            klDxCol(0, 0, 0, sal * a))
                    end
                    pcall(renderFontDrawText, dxf, txt, ax, ay,
                        klDxCol(r, g, b, al * a))
                else
                    if sal > 0 then
                        uiText(x + 1, y + 1, txt, col32(0, 0, 0, math.floor(sal * a)), fsc)
                    end
                    uiText(x, y, txt, col32(r, g, b, math.floor(al * a)), fsc)
                end
            end
            local function fillRect(x, y, w, h, r, g, b, al)
                x, y, w, h = math.floor(x), math.floor(y), math.floor(w), math.floor(h)
                if w < 1 or h < 1 then return end
                if type(renderDrawBox) == "function" then
                    local pieces = grndCheckerClipRect(AO.x + x, AO.y + y, w, h)
                    if pieces then
                        for i = 1, #pieces do
                            local q = pieces[i]
                            pcall(renderDrawBox, q.x, q.y, q.w, q.h,
                                klDxCol(r, g, b, al * a))
                        end
                        return
                    end
                    pcall(renderDrawBox, AO.x + x, AO.y + y, w, h,
                        klDxCol(r, g, b, al * a))
                elseif not dxf then
                    local dl = im.GetWindowDrawList()
                    local pos = im.GetWindowPos()
                    dl:AddRectFilled(
                        im.ImVec2(pos.x + x, pos.y + y),
                        im.ImVec2(pos.x + x + w, pos.y + y + h),
                        col32(r, g, b, math.floor(al * a)))
                end
            end
            im.SetNextWindowPos(im.ImVec2(AO.x, AO.y), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            if grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, a) then nStyle = nStyle + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then nStyle = nStyle + 1 end
            local opened = grndBeginTransparent("##grnd_admins", KL_WIN_FLAGS)
            local dlA, atA
            if opened then
                dlA = im.GetWindowDrawList()
                local posA = im.GetWindowPos()
                atA = function(dx, dy)
                    return im.ImVec2(posA.x + dx, posA.y + dy)
                end
                local y = padY
                outText(padX, y, headTitle, 242, 245, 252, 255)
                y = y + rowH
                outText(padX, y, headSub, 142, 150, 178, 240)
                y = y + rowH
                y = y + math.floor(gapH * 0.45)
                fillRect(padX, y, W - padX * 2, sepH, 124, 134, 242, 62)
                y = y + sepH + gapH
                if #rows == 0 then
                    outText(padX, y, "ожидание ответа /admins…", 140, 145, 155, 220)
                else
                    for i = 1, #rows do
                        local e = rows[i]
                        local nr, ng, nb = e.r, e.g, e.b
                        local lv = tonumber(e.lvl)
                        local cc = lv and AO.lvlCol and AO.lvlCol[lv]
                        if type(cc) == "table" then
                            nr, ng, nb = tonumber(cc[1]), tonumber(cc[2]), tonumber(cc[3])
                        end
                        if not nr or not ng or not nb then nr, ng, nb = 235, 240, 245 end
                        local idText = e.idPart or "[—]"
                        local idW = dxW(idText)
                        local xId = W - padX - idW
                        local xText = padX
                        local textLimit = math.max(0, xId - colGap - xText)
                        local nick = tostring(e.nick or "")
                        while nick ~= "" and dxW(nick) > textLimit do
                            local cut = #nick
                            repeat cut = cut - 1 until cut <= 0 or nick:byte(cut) < 128 or nick:byte(cut) >= 192
                            nick = nick:sub(1, math.max(0, cut - 1))
                        end
                        if nick ~= e.nick and textLimit >= dxW("…") then nick = nick .. "…" end
                        outText(xText, y, nick, nr, ng, nb, 255)
                        local afterNick = xText + dxW(nick) + colGap
                        if e.lvlStr and e.lvlStr ~= "" and afterNick + e.lw <= xId - colGap then
                            outText(afterNick, y, e.lvlStr, 124, 134, 242, 245)
                            afterNick = afterNick + e.lw + colGap
                        end
                        if e.afkClean and afterNick + e.aw <= xId - colGap then
                            outText(afterNick, y, e.afkClean, 245, 172, 76, 245)
                        end
                        outText(xId, y, idText, 138, 146, 175, 245)
                        if hoverI == i then
                            local uw = math.max(8, xId - colGap - xText)
                            if uw < 8 then uw = 8 end
                            local uy = math.floor(y + rowH - 2)
                            if uy < y + fpx + 3 then uy = math.floor(y + fpx + 3) end
                            if dlA and dlA.AddLine and atA then
                                pcall(dlA.AddLine, dlA, atA(padX, uy), atA(padX + uw, uy),
                                    col32(124, 134, 242, 235), 1.0)
                            end
                        end
                        y = y + rowH
                    end
                end
                if AO.moving then
                    outText(padX, y + 4, hint, 200, 205, 215, 230)
                end
            end
            return AO.moving
            end)
            while endDepth > baseEndDepth do
                endDepth = endDepth - 1
                pcall(im.End)
            end
            grndPopStyle(nStyle)
            if fontPushed then
                if fontViaLadder then pcall(im.PopFont) else pcall(uiPopFont, true) end
            end
            if not bodyOk then error(bodyResult) end
            return bodyResult
        end
        local function softTextRgb(x, y, txt, r, g, b, al)
            -- цвет текста задаём напрямую: PushStyleColor с упакованным числом
            -- эта сборка ImGui молча игнорирует, и текст рисовался белым
            txt = tostring(txt or "")
            local a = (tonumber(al) or 255) / 255
            local function v4(rr, gg, bb, aa)
                return im.ImVec4((tonumber(rr) or 0) / 255, (tonumber(gg) or 0) / 255,
                    (tonumber(bb) or 0) / 255, aa or a)
            end
            x, y = math.floor(tonumber(x) or 0), math.floor(tonumber(y) or 0)
            if im.SetCursorPos and im.ImVec2 then
                pcall(im.SetCursorPos, im.ImVec2(x, y))
            end
            if type(im.TextColored) == "function" then
                local ok = pcall(im.TextColored, v4(r, g, b, a), txt)
                if ok then return true end
            end
            if type(im.Text) == "function" then
                local ok, err = pcall(im.Text, v4(r, g, b, a), "%s", txt)
                if ok then return true end
                ok = pcall(im.TextColored and im.TextColored or im.Text, txt)
                if ok then return true end
            end
            return false
        end
        -- размер именно игрового кадра: getScreenResolution в оконном режиме
        -- отдаёт разрешение рабочего стола, и окно списка уезжало за край экрана
        local function softScreen()
            if im.GetIO then
                local ok, io = pcall(im.GetIO)
                if ok and io then
                    local ds = io.DisplaySize
                    local w = ds and (tonumber(ds.x) or tonumber(ds[1]))
                    local h = ds and (tonumber(ds.y) or tonumber(ds[2]))
                    -- на части сборок DisplaySize отдаёт мусор (161x949):
                    -- берём его, только если размер похож на настоящий кадр
                    if w and h and w >= 200 and h >= 200 then return w, h end
                end
            end
            if type(getScreenResolution) == "function" then
                local ok, w, h = pcall(getScreenResolution)
                if ok and tonumber(w) and tonumber(h) then
                    return tonumber(w), tonumber(h)
                end
            end
            return 1920, 1080
        end
        local function drawSoftRate(dt)
            local S = GRND_SFR
            if not S then return false end
            return grndSfrDraw(dt, {
                im = im,
                text = uiText,
                textRgb = softTextRgb,
                col32 = col32,
                begin = grndBeginTransparent,
                windowDepth = function() return endDepth end,
                endWindow = function(base)
                    base = tonumber(base) or 0
                    if endDepth > base then
                        endDepth = endDepth - 1
                        pcall(im.End)
                    end
                end,
                styleF = grndPushStyleF,
                styleV2 = grndPushStyleV2,
                flags = KL_WIN_FLAGS,
                always = COND_ALWAYS,
                pushFont = uiPushFont,
                popFont = uiPopFont,
                fontPick = grndUiFontPick,
                fontBase = tonumber(GRND_FONT and GRND_FONT.fontBase) or 16,
                measure = drawnWb,
                screen = softScreen,
                mouse = klMousePos,
                tapped = klLmbTapped,
                showCursor = clwShowCursor,
                save = grndSfrCfgSave,
                rect = function(x, y, w, h, col, rad)
                    local dlS = im.GetWindowDrawList()
                    local posS = im.GetWindowPos()
                    roundRect(dlS, im.ImVec2(posS.x + x, posS.y + y),
                        im.ImVec2(posS.x + x + w, posS.y + y + h), col, rad)
                end,
                frame = function(x, y, w, h, col, rad)
                    local dlS = im.GetWindowDrawList()
                    local posS = im.GetWindowPos()
                    if dlS and dlS.AddRect then
                        pcall(dlS.AddRect, dlS, im.ImVec2(posS.x + x, posS.y + y),
                            im.ImVec2(posS.x + x + w, posS.y + y + h), col, rad, 0, 1)
                    end
                end,
            })
        end
