        do
            -- Прозрачный экранный HUD недельной статистики (GRND_WEEKSTATS)
            function _G.grndDrawWeekStatsHud(dt)
                local WS = GRND_WEEKSTATS
                if not WS or (not WS.hudOn and not WS.moving) then return false end
                local today, week = _G.grndWeekStatsTotals()
                local resX, resY = getScreenResolution()
                local sc = math.max(0.5, math.min(2.0, tonumber(WS.scale) or 0.85))
                local rowH = math.max(15, math.floor(18 * sc))
                local padX, padY = 10, 8
                local w = math.floor(236 * sc)
                local h = padY * 2 + rowH * 6 + 8
                if WS.x == nil then WS.x = 18 end
                if WS.y == nil then WS.y = math.floor(resY * 0.42) end
                if WS.moving then
                    pcall(clwShowCursor, true)
                    if not WS.armed and os.clock() > (WS.armAt or 0)
                        and not (GRND_MOUSE and GRND_MOUSE.down) then
                        WS.armed = true
                    end
                    local mx, my = klMousePos()
                    if mx and my then
                        WS.x = math.max(0, math.min(resX - w, math.floor(mx - w * 0.5)))
                        WS.y = math.max(0, math.min(resY - h, math.floor(my - h * 0.5)))
                    end
                    if WS.cancel then
                        WS.cancel = false
                        WS.x, WS.y = WS.origX, WS.origY
                        WS.moving = false
                    elseif WS.armed and klLmbTapped(WS) then
                        WS.moving = false
                        GRND_MAIN_EXT.wsX, GRND_MAIN_EXT.wsY = WS.x, WS.y
                        pcall(grndCamCfgSave)
                    end
                end
                im.SetNextWindowPos(im.ImVec2(WS.x, WS.y), COND_ALWAYS)
                im.SetNextWindowSize(im.ImVec2(w, h), COND_ALWAYS)
                local nS = 0
                if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then nS = nS + 1 end
                local baseD = endDepth
                if grndBeginTransparent("##grnd_weekstats_hud", KL_WIN_FLAGS) then
                    local dl = im.GetWindowDrawList()
                    local pos = im.GetWindowPos()
                    local onMinToday = math.floor((tonumber(today.onlineSec) or 0) / 60)
                    local onMinWeek = math.floor((tonumber(week.onlineSec) or 0) / 60)
                    local lines = {
                        { "Репорты (день / 7д):", string.format("%d / %d", today.reports or 0, week.reports or 0), col32(124, 134, 242, 255) },
                        { "Наказания (день / 7д):", string.format("%d / %d", today.punish or 0, week.punish or 0), col32(245, 178, 76, 255) },
                        { "Формы (день / 7д):", string.format("%d / %d", today.forms or 0, week.forms or 0), col32(82, 214, 148, 255) },
                        { "Онлайн (день / 7д):", string.format("%dм / %dм", onMinToday, onMinWeek), col32(158, 198, 255, 255) },
                    }
                    uiText(padX + 1, padY + 1, "Статистика", col32(0, 0, 0, 145), sc)
                    uiText(padX, padY, "Статистика", col32(242, 245, 252, 255), sc)
                    local y = padY + rowH + 2
                    if dl and dl.AddLine then
                        pcall(dl.AddLine, dl, im.ImVec2(pos.x + padX, pos.y + y),
                            im.ImVec2(pos.x + w - padX, pos.y + y), col32(124, 134, 242, 72), 1.0)
                    end
                    y = y + 5
                    for i = 1, #lines do
                        local r = lines[i]
                        uiText(padX + 1, y + 1, r[1], col32(0, 0, 0, 140), sc * 0.92)
                        uiText(padX, y, r[1], col32(168, 175, 200, 245), sc * 0.92)
                        local vw = grndTextW(r[2]) * sc * 0.92
                        uiText(w - padX - vw + 1, y + 1, r[2], col32(0, 0, 0, 140), sc * 0.92)
                        uiText(w - padX - vw, y, r[2], r[3], sc * 0.92)
                        y = y + rowH
                    end
                    if WS.moving and dl and dl.AddRect then
                        pcall(dl.AddRect, dl, im.ImVec2(pos.x + 1, pos.y + 1),
                            im.ImVec2(pos.x + w - 1, pos.y + h - 1), col32(124, 134, 242, 180), 6, 0, 1.2)
                    end
                end
                while endDepth > baseD do
                    endDepth = endDepth - 1
                    pcall(im.End)
                end
                grndPopStyle(nS)
                return WS.moving
            end

            -- Безопасная панель кастомного серверного диалога (поиск + быстрое копирование строк)
            function _G.grndDrawCustomDialog(dt)
                local D = GRND_CUSTOM_DLG
                if not (D and D.wantUi and D.wantUi()) then return false end
                local cur = D.cur
                if not cur then return false end
                local resX, resY = getScreenResolution()
                local w = math.min(360, math.max(260, math.floor(resX * 0.22)))
                local h = math.min(340, math.max(180, 74 + math.min(10, #cur.lines) * 22))
                local x = math.max(12, resX - w - 18)
                local y = math.max(80, math.floor((resY - h) * 0.5))
                im.SetNextWindowPos(im.ImVec2(x, y), COND_ALWAYS)
                im.SetNextWindowSize(im.ImVec2(w, h), COND_ALWAYS)
                local nS, nC = 0, 0
                if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 12) then nS = nS + 1 end
                if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 12, 10) then nS = nS + 1 end
                if grndPushCol(im.Col and im.Col.WindowBg, rgba(9, 9, 17, 242)) then nC = nC + 1 end
                if grndPushCol(im.Col and im.Col.Border, rgba(42, 46, 69, 235)) then nC = nC + 1 end
                local baseD = endDepth
                if grndBegin("##grnd_custom_dlg", WIN_FLAGS) then
                    uiText(12, 10, "Диалог: " .. tostring(cur.title), col32(238, 241, 250, 255), 0.92)
                    local ry = 34
                    local shown = 0
                    for i = 1, #cur.lines do
                        if shown >= 12 then break end
                        shown = shown + 1
                        uiText(12, ry, cur.lines[i], col32(165, 172, 198, 245), 0.86)
                        ry = ry + 20
                    end
                end
                while endDepth > baseD do
                    endDepth = endDepth - 1
                    pcall(im.End)
                end
                grndPopCol(nC)
                grndPopStyle(nS)
                return false
            end
        end
        local function drawMenu(dt)
            dt = dt or 0.016
            if not menu.open then
                if type(_G.grndBrowserTick) == "function" then
                    pcall(_G.grndBrowserTick, false, nil)
                end
                if GRND_UIKIT.styleDirty then
                    local ok,result=pcall(grndCamCfgSave)
                    GRND_UIKIT.styleSaveError=not (ok and result ~= false)
                    GRND_UIKIT.styleDirty=false
                end
            end
            local speed = 8.5
            if menu.open then
                menu.anim = math.min(1, (menu.anim or 0) + dt * speed)
            else
                menu.anim = math.max(0, (menu.anim or 0) - dt * speed)
            end
            if menu.anim <= 0 then return false end
            local a = 1 - (1 - menu.anim) * (1 - menu.anim)
            local resX, resY = getScreenResolution()
            local W = math.min(1372, math.max(760, resX - 40))
            local H = math.min(762, math.max(540, resY - 40))
            local SB = math.min(212, math.floor(W * 0.28))
            local BPAD = 8
            local BW = SB - BPAD * 2
            local BH, BGAP = 34, 3
            local function tsize(s)
                local ok, r = pcall(im.CalcTextSize, s)
                if ok then
                    local t = type(r)
                    if t == "table" or t == "cdata" then
                        local xx, yy = tonumber(r and r.x), tonumber(r and r.y)
                        if xx then return xx, yy or 14 end
                    elseif t == "number" then
                        return r, 14
                    end
                end
                local n = ((type(grndUtf8Len) == "function")
                    and grndUtf8Len(tostring(s)))
                    or (utf8 and utf8.len and utf8.len(tostring(s)))
                    or #tostring(s)
                return n * 7, 14
            end
            if not menu.posInit or menu.wantRecenter then
                local saved = (not menu.wantRecenter) and (GRND_CONFIG.ensure().layout.menu or {}) or {}
                local mx = tonumber(saved.x) or math.floor((resX - W) / 2)
                local my = tonumber(saved.y) or math.floor((resY - H) / 2)
                mx = math.max(0, math.min(math.max(0, resX - W), mx))
                my = math.max(0, math.min(math.max(0, resY - H), my))
                im.SetNextWindowPos(im.ImVec2(mx, my), COND_ALWAYS)
                menu.posInit = true
                menu.wantRecenter = false
            end
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, a)
            grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 14)
            grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0)
            grndPushCol(im.Col and im.Col.WindowBg, c4(TH.bg))
            grndPushCol(im.Col and im.Col.Border,   c4(TH.line))
            local violetColors, violetVars = 0, 0
            for _, entry in ipairs({
                {"Text", TH.text}, {"TextDisabled", TH.textMuted},
                {"FrameBg", {255,255,255,9}}, {"FrameBgHovered", {255,255,255,17}},
                {"FrameBgActive", {255,255,255,23}},
                {"Button", TH.itemHover}, {"ButtonHovered", TH.itemSel},
                {"ButtonActive", TH.itemPress}, {"CheckMark", TH.accent},
                {"SliderGrab", TH.accent}, {"SliderGrabActive", TH.textHi},
                {"Header", TH.itemSel}, {"HeaderHovered", TH.itemHover},
                {"HeaderActive", TH.itemPress}, {"Separator", TH.line},
                {"ScrollbarBg", {0,0,0,0}}, {"ScrollbarGrab", {255,255,255,30}},
                {"ScrollbarGrabHovered", {255,255,255,50}},
                {"ScrollbarGrabActive", TH.accent},
                {"TextSelectedBg", {TH.accent[1],TH.accent[2],TH.accent[3],65}},
            }) do
                if grndPushCol(im.Col and im.Col[entry[1]], c4(entry[2])) then
                    violetColors = violetColors + 1
                end
            end
            for _, entry in ipairs({{"FrameRounding",5},{"GrabRounding",3},
                {"ScrollbarRounding",4},{"ScrollbarSize",5}}) do
                if grndPushStyleF(im.StyleVar and im.StyleVar[entry[1]],entry[2]) then
                    violetVars = violetVars + 1
                end
            end
            local wantCursor = false
            local function drawPunishEditor(dt)
                local PUN = GRND_PUN
                if not PUN or not PUN.editId then return false end
                if not PUN.loaded then pcall(PUN.load) end
                local it = PUN.entry(PUN.editId)
                if not it or it.locked then
                    PUN.editId, PUN.addCol = nil, nil
                    return false
                end
                local d = PUN.data[it.id] or { reasons = {}, times = {} }
                PUN.data[it.id] = d
                d.reasons = type(d.reasons) == "table" and d.reasons or {}
                d.times = type(d.times) == "table" and d.times or {}
                local resX, resY = getScreenResolution()
                local W = 470
                local PADX, PADY = 16, 14
                local HEAD = 42
                local colGap = 12
                local colW = math.floor((W - PADX * 2 - colGap) / 2)
                local rowH, rowGap = 26, 6
                local addBtnH = 30
                local addModeH = 30 + 6 + 26
                local rowsTop = HEAD + 10 + 22
                local function colBottom(kind)
                    local items = (kind == "r") and d.reasons or d.times
                    local extra = (PUN.addCol == kind) and addModeH or addBtnH
                    return rowsTop + #items * (rowH + rowGap) + 4 + extra
                end
                local leftBottom = colBottom("r")
                local rightBottom = it.time and colBottom("t") or (rowsTop + 60)
                local H = math.max(leftBottom, rightBottom) + PADY
                H = math.max(240, math.min(H, math.max(240, resY - 60)))
                local function drawnW(s, scale)
                    scale = scale or 1
                    if isFnV(im.SetWindowFontScale) then
                        if scale ~= 1 then
                            pcall(im.SetWindowFontScale, scale)
                            local okM, aM = pcall(im.CalcTextSize, tostring(s))
                            pcall(im.SetWindowFontScale, 1)
                            if okM then
                                local ta = type(aM)
                                local w = (ta == "table" or ta == "cdata")
                                    and tonumber(aM.x) or tonumber(aM)
                                if w and w > 0 then return w end
                            end
                        end
                        return grndTextW(s) * scale
                    end
                    return grndTextW(s)
                end
                local function fitText(s, maxW, scale)
                    s = tostring(s)
                    if drawnW(s, scale) <= maxW then return s end
                    local out, chars = {}, 0
                    for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
                        chars = chars + 1
                        if chars > 2 and drawnW(table.concat(out) .. "…", scale) > maxW then break end
                        out[#out + 1] = ch
                    end
                    return table.concat(out) .. "…"
                end
                local COND_FIRST = iflag({ "Cond", "ImGuiCond" }, "FirstUseEver")
                    or iflag({ "Cond", "ImGuiCond" }, "Once") or COND_ALWAYS
                im.SetNextWindowPos(im.ImVec2(math.floor((resX - W) / 2),
                    math.floor((resY - H) / 2)), COND_FIRST)
                im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
                local styleN, colorN = 0, 0
                if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 12) then styleN = styleN + 1 end
                if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
                if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
                local flags = wf("NoTitleBar", "NoResize", "NoCollapse", "NoScrollbar")
                local pendingClose = false
                if grndBegin("##grnd_pun_editor", flags) then
                    local pos = im.GetWindowPos()
                    local dl2 = im.GetWindowDrawList()
                    local function eat(x, y) return im.ImVec2(pos.x + x, pos.y + y) end
                    local function box(x, y, w, h, col, r)
                        roundRect(dl2, eat(x, y), eat(x + w, y + h), col, r or 6)
                    end
                    local function frame(x, y, w, h, col, r)
                        if dl2.AddRect then
                            pcall(dl2.AddRect, dl2, eat(x, y), eat(x + w, y + h), col, r or 6, 0, 1.0)
                        end
                    end
                    box(0, 0, W, H, c32(TH.bg), 12)
                    frame(0, 0, W, H, col32(255, 255, 255, 16), 12)
                    local title = "Наказание: " .. it.id
                    uiText((W - drawnW(title, 1.05)) / 2, 13, title, c4(TH.textHi), 1.05)
                    local cbS, cbX, cbY = 24, W - 34, 9
                    im.SetCursorPos(im.ImVec2(cbX, cbY))
                    if im.InvisibleButton("##grnd_pun_close", im.ImVec2(cbS, cbS)) then
                        pendingClose = true
                    end
                    local chov = (im.IsItemHovered and im.IsItemHovered()) or false
                    if chov then box(cbX, cbY, cbS, cbS, col32(255, 96, 96, 34), 12) end
                    local lc = chov and col32(255, 128, 128, 245) or col32(255, 255, 255, 140)
                    local m = 8
                    dl2:AddLine(eat(cbX + m, cbY + m), eat(cbX + cbS - m, cbY + cbS - m), lc, 1.4)
                    dl2:AddLine(eat(cbX + cbS - m, cbY + m), eat(cbX + m, cbY + cbS - m), lc, 1.4)
                    dl2:AddRectFilled(eat(PADX, HEAD - 1), eat(W - PADX, HEAD), c32(TH.line))
                    local colY = HEAD + 10
                    local function column(cx, kind)
                        local isR = (kind == "r")
                        local items = isR and d.reasons or d.times
                        local headTxt = isR and "Причины" or ("Время в " .. tostring(it.unit or "мин") .. ".")
                        uiText(cx + (colW - drawnW(headTxt, 0.92)) / 2, colY, headTxt,
                            c4(TH.textHi), 0.92)
                        local iy = colY + 22
                        for i = 1, #items do
                            local ry = iy + (i - 1) * (rowH + rowGap)
                            im.SetCursorPos(im.ImVec2(cx, ry))
                            if im.InvisibleButton("##pun_del_" .. kind .. "_" .. i,
                                im.ImVec2(24, rowH)) then
                                table.remove(items, i)
                                PUN.cfgDirty = true
                                pcall(PUN.save)
                                return
                            end
                            local thov = (im.IsItemHovered and im.IsItemHovered()) or false
                            box(cx, ry, 24, rowH,
                                thov and col32(255, 96, 96, 30) or col32(255, 255, 255, 8), 5)
                            local tIc = thov and col32(255, 120, 120, 240)
                                or col32(255, 255, 255, 120)
                            local tx0, ty0 = cx + 7, ry + 6
                            dl2:AddRectFilled(eat(tx0 - 2, ty0), eat(tx0 + 8, ty0 + 2), tIc)
                            dl2:AddRectFilled(eat(tx0 + 1, ty0 - 2), eat(tx0 + 5, ty0), tIc)
                            if dl2.AddRect then
                                pcall(dl2.AddRect, dl2, eat(tx0 - 2, ty0 + 2),
                                    eat(tx0 + 8, ty0 + 13), tIc, 1, 0, 1.2)
                            else
                                dl2:AddRectFilled(eat(tx0 - 2, ty0 + 2), eat(tx0 + 8, ty0 + 13), tIc)
                            end
                            local vx, vw = cx + 30, colW - 30
                            box(vx, ry, vw, rowH, col32(255, 255, 255, 8), 5)
                            frame(vx + 0.5, ry + 0.5, vw - 1, rowH - 1, col32(255, 255, 255, 14), 5)
                            local s = tostring(items[i])
                            s = fitText(s, vw - 14, 0.88)
                            uiText(vx + 8, ry + (rowH - 14) / 2 + 1, s, c4(TH.text), 0.88)
                        end
                        local addY = iy + #items * (rowH + rowGap) + 4
                        if PUN.addCol == kind then
                            if not PUN.ensureBuf(im) then
                                PUN.addCol = nil
                                pcall(notify.add,
                                    "Ввод текста недоступен в этой сборке ImGui", "warn", 3)
                                return
                            end
                            local inCol, inSty = 0, 0
                            if grndPushCol(im.Col and im.Col.FrameBg, rgba(10, 13, 20, 255)) then inCol = inCol + 1 end
                            if grndPushCol(im.Col and im.Col.FrameBgHovered, rgba(16, 24, 34, 255)) then inCol = inCol + 1 end
                            if grndPushCol(im.Col and im.Col.FrameBgActive, rgba(18, 33, 43, 255)) then inCol = inCol + 1 end
                            if grndPushCol(im.Col and im.Col.Text, rgba(225, 232, 242, 255)) then inCol = inCol + 1 end
                            if grndPushCol(im.Col and im.Col.Border, rgba(255, 255, 255, 18)) then inCol = inCol + 1 end
                            if grndPushStyleV2(im.StyleVar and im.StyleVar.FramePadding, 8, 7) then inSty = inSty + 1 end
                            if grndPushStyleF(im.StyleVar and im.StyleVar.FrameBorderSize, 1) then inSty = inSty + 1 end
                            local fl = 0
                            if im.InputTextFlags and im.InputTextFlags.EnterReturnsTrue then
                                fl = im.InputTextFlags.EnterReturnsTrue
                            elseif rawget(im, "ImGuiInputTextFlags_EnterReturnsTrue") then
                                fl = rawget(im, "ImGuiInputTextFlags_EnterReturnsTrue")
                            end
                            im.SetCursorPos(im.ImVec2(cx, addY))
                            if im.PushItemWidth then pcall(im.PushItemWidth, colW) end
                            local okI, retI
                            if im.InputTextWithHint then
                                okI, retI = pcall(im.InputTextWithHint, "##pun_inp_" .. kind,
                                    isR and "причина…" or "число…", PUN.buf, 64, fl)
                            elseif im.InputText then
                                okI, retI = pcall(im.InputText, "##pun_inp_" .. kind, PUN.buf, 64, fl)
                            end
                            if not PUN.focused and im.SetKeyboardFocusHere then
                                pcall(im.SetKeyboardFocusHere, -1)
                                PUN.focused = true
                            end
                            if im.PopItemWidth then pcall(im.PopItemWidth) end
                            grndPopStyle(inSty)
                            grndPopCol(inCol)
                            frame(cx, addY, colW, 30,
                                col32(TH.accent[1], TH.accent[2], TH.accent[3], 90), 6)
                            local okClicked, cancelClicked = false, false
                            local bY = addY + 30 + 6
                            local halfW = math.floor((colW - 6) / 2)
                            im.SetCursorPos(im.ImVec2(cx, bY))
                            if im.InvisibleButton("##pun_ok_" .. kind, im.ImVec2(halfW, 26)) then okClicked = true end
                            local okHov = (im.IsItemHovered and im.IsItemHovered()) or false
                            box(cx, bY, halfW, 26,
                                okHov and c32(TH.accent2) or c32(TH.accent), 6)
                            uiText(cx + (halfW - drawnW("Добавить", 0.85)) / 2, bY + 6, "Добавить",
                                c4(TH.bg), 0.85)
                            im.SetCursorPos(im.ImVec2(cx + halfW + 6, bY))
                            if im.InvisibleButton("##pun_cn_" .. kind, im.ImVec2(colW - halfW - 6, 26)) then cancelClicked = true end
                            local cnHov = (im.IsItemHovered and im.IsItemHovered()) or false
                            box(cx + halfW + 6, bY, colW - halfW - 6, 26,
                                cnHov and col32(255, 255, 255, 18) or col32(255, 255, 255, 8), 6)
                            frame(cx + halfW + 6, bY, colW - halfW - 6, 26,
                                cnHov and col32(255, 255, 255, 32) or col32(255, 255, 255, 16), 6)
                            uiText(cx + halfW + 6 + (colW - halfW - 6 - drawnW("Отмена", 0.85)) / 2,
                                bY + 6, "Отмена", cnHov and c4(TH.textHi) or c4(TH.textDim), 0.85)
                            if cancelClicked then
                                PUN.addCol = nil
                                PUN.focused = false
                                pcall(PUN.clearBuf)
                                return
                            end
                            if (okI and retI == true and fl ~= 0) or okClicked then
                                local txt = PUN.readBuf()
                                pcall(PUN.clearBuf)
                                if txt:gsub("%s+", "") == "" then
                                    PUN.addCol = nil
                                    PUN.focused = false
                                else
                                    PUN.commit(it.id, kind, txt)
                                    PUN.focused = false
                                end
                                return
                            end
                        else
                            im.SetCursorPos(im.ImVec2(cx, addY))
                            local aClk = im.InvisibleButton("##pun_addbtn_" .. kind,
                                im.ImVec2(colW, addBtnH))
                            local aHov = (im.IsItemHovered and im.IsItemHovered()) or false
                            local aAct = (im.IsItemActive and im.IsItemActive()) or false
                            gradRect(dl2, eat(cx, addY), eat(cx + colW, addY + addBtnH),
                                (aHov or aAct) and c32(TH.accent2) or c32(TH.accent),
                                c32(TH.accent), 8)
                            uiText(cx + (colW - drawnW("Добавить", 0.92)) / 2,
                                addY + (addBtnH - 14) / 2, "Добавить", c4(TH.bg), 0.92)
                            if aClk then
                                PUN.addCol = kind
                                PUN.focused = false
                                pcall(PUN.clearBuf)
                                return
                            end
                        end
                    end
                    column(PADX, "r")
                    if it.time then
                        column(PADX + colW + colGap, "t")
                    else
                        local cx = PADX + colW + colGap
                        uiText(cx + (colW - drawnW("Время", 0.92)) / 2, colY, "Время",
                            c4(TH.textHi), 0.92)
                        local ny = colY + 22
                        box(cx, ny, colW, 60, col32(255, 255, 255, 5), 8)
                        frame(cx + 0.5, ny + 0.5, colW - 1, 59, col32(255, 255, 255, 12), 8)
                        uiText(cx + (colW - drawnW("Недоступно", 0.92)) / 2, ny + 23,
                            "Недоступно", c4(TH.textMuted), 0.92)
                    end
                end
                if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
                grndPopCol(colorN)
                grndPopStyle(styleN)
                if pendingClose then
                    PUN.editId, PUN.addCol, PUN.focused = nil, nil, false
                    pcall(PUN.clearBuf)
                end
                return true
            end
            local menuWinFlags = MENU_WIN_FLAGS
            if GRND_PUN and GRND_PUN.editId then
                menuWinFlags = menuWinFlags + wflag("NoBringToFrontOnFocus")
            end
            if grndBegin("##grnd_menu", menuWinFlags) then
                wantCursor = menu.open
                local pos = im.GetWindowPos()
                GRND_CONFIG.setLayout("menu",{x=math.floor(pos.x),y=math.floor(pos.y),
                    tab=menu.tab,settingsTab=menu.settingsTab,adminPanel=menu.adminPanel or "general",
                    punPage=menu.punPage or "give"})
                local dl  = im.GetWindowDrawList()
                local function at(dx, dy) return im.ImVec2(pos.x + dx, pos.y + dy) end
                local function menuMousePos()
                    local io2 = grndSafeGetIO(im)
                    if io2 and io2.MousePos and tonumber(io2.MousePos.x) then
                        return io2.MousePos
                    end
                    if GRND_MOUSE and GRND_MOUSE.x and GRND_MOUSE.y then
                        return { x = GRND_MOUSE.x, y = GRND_MOUSE.y }
                    end
                    return nil
                end
                local function menuSlider(x, y, w, val, vmin, vmax, step, tag)
                    local frac = 0
                    if vmax > vmin then frac = (val - vmin) / (vmax - vmin) end
                    frac = math.min(1, math.max(0, frac))
                    grndSliderPaint({ dl = dl, at = at, col32 = col32,
                        roundRect = roundRect, TH = TH }, x, y, w, 22, frac)
                    im.SetCursorPos(im.ImVec2(x - 5, y))
                    im.InvisibleButton("##ms_" .. (tag or tostring(y)), im.ImVec2(w + 10, 22))
                    local nv = val
                    local active = (im.IsItemActive and im.IsItemActive()) or false
                    if not active and GRND_MOUSE and GRND_MOUSE.down then
                        local mp = menuMousePos()
                        if mp then
                            local wp = im.GetWindowPos()
                            local sx = wp.x + x - 5
                            local sy = wp.y + y
                            if mp.x >= sx and mp.x <= sx + w + 10 and mp.y >= sy and mp.y <= sy + 22 then
                                active = true
                            end
                        end
                    end
                    if active then
                        local mp = menuMousePos()
                        if mp then
                            local wp = im.GetWindowPos()
                            local f = (mp.x - (wp.x + x)) / math.max(1, w)
                            f = math.min(1, math.max(0, f))
                            nv = vmin + f * (vmax - vmin)
                            if step and step > 0 then
                                nv = math.floor((nv - vmin) / step + 0.5) * step + vmin
                            end
                        end
                    end
                    return nv, (nv ~= val)
                end
                local function menuToggle(x, y, on, tag)
                    im.SetCursorPos(im.ImVec2(x, y))
                    local id = "##mt_" .. (tag or tostring(x) .. "_" .. tostring(y))
                    local clicked = im.InvisibleButton(id, im.ImVec2(46, 24))
                    local hovered = (im.IsItemHovered and im.IsItemHovered()) or false
                    grndUiSwitchPaint({dl=dl, at=at, col32=col32, roundRect=roundRect},
                        x,y,on,hovered,id,dt)
                    return clicked
                end
                local UI = {}
                UI.card = function(dlist, atFn, x, y, w, h, rad)
                    rad = rad or 10
                    roundRect(dlist, atFn(x, y), atFn(x + w, y + h), c32(TH.card), rad)
                    if dlist.AddRect then
                        pcall(dlist.AddRect, dlist, atFn(x + 0.5, y + 0.5),
                            atFn(x + w - 0.5, y + h - 0.5), c32(TH.line), rad, 0, 1)
                    end
                end
                UI.pill = function(x, y, h, label, selected, tag, padX)
                    padX = padX or 14
                    local tw, th = tsize(label)
                    local w = math.max(54, math.floor(tw + padX * 2))
                    im.SetCursorPos(im.ImVec2(x, y))
                    local clicked = im.InvisibleButton("##pill_" .. tostring(tag or label), im.ImVec2(w, h))
                    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                    local bg = selected and c32(TH.itemSel)
                        or (hov and c32(TH.itemHover) or col32(255, 255, 255, 7))
                    roundRect(dl, at(x, y), at(x + w, y + h), bg, 8)
                    if dl.AddRect then
                        pcall(dl.AddRect, dl, at(x + 0.5, y + 0.5), at(x + w - 0.5, y + h - 0.5),
                            selected and col32(TH.accent[1], TH.accent[2], TH.accent[3], 155)
                                or col32(42, 46, 69, 145), 8, 0, 1)
                    end
                    uiText(x + (w - tw) * 0.5, y + (h - th) * 0.5, label,
                        selected and c4(TH.textHi) or (hov and c4(TH.text) or c4(TH.textDim)), 0.92)
                    return clicked, w
                end
                UI.btn = function(dlist, atFn, x, y, w, h, label, tag, accentFill)
                    im.SetCursorPos(im.ImVec2(x, y))
                    local clicked = im.InvisibleButton("##ubtn_" .. tostring(tag or label), im.ImVec2(w, h))
                    local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                    local bg = accentFill
                        and (hov and col32(TH.accent[1], TH.accent[2], TH.accent[3], 82)
                            or col32(TH.accent[1], TH.accent[2], TH.accent[3], 52))
                        or (hov and c32(TH.itemHover) or col32(255, 255, 255, 9))
                    roundRect(dlist, atFn(x, y), atFn(x + w, y + h), bg, 8)
                    if dlist.AddRect then
                        pcall(dlist.AddRect, dlist, atFn(x + 0.5, y + 0.5), atFn(x + w - 0.5, y + h - 0.5),
                            accentFill and col32(TH.accent[1], TH.accent[2], TH.accent[3], 165)
                                or c32(TH.line), 8, 0, 1)
                    end
                    local tw, th = tsize(label)
                    local curPos = im.GetWindowPos()
                    local ox = atFn(0, 0).x - curPos.x
                    local oy = atFn(0, 0).y - curPos.y
                    uiText(ox + x + (w - tw * 0.9) * 0.5, oy + y + (h - th) * 0.5, label,
                        accentFill and c4(TH.textHi) or (hov and c4(TH.textHi) or c4(TH.text)), 0.9)
                    return clicked
                end
                UI.input = function(dlist, atFn, key, x, y, w, h, curVal, hint, maxLen)
                    maxLen = maxLen or 192
                    menu.bufs = menu.bufs or {}
                    local entry = menu.bufs[key]
                    local valStr = tostring(curVal or "")
                    if not entry then
                        entry = { last = valStr, kind = "none" }
                        if im.new and im.new.char then
                            local okB, b = pcall(function() return im.new.char[maxLen](valStr) end)
                            if okB and b then entry.buf = b; entry.kind = "mimgui" end
                        elseif type(im.ImBuffer) == "function" then
                            local okB, b = pcall(im.ImBuffer, valStr, maxLen)
                            if okB and b then entry.buf = b; entry.kind = "moonimgui" end
                        end
                        menu.bufs[key] = entry
                    elseif entry.last ~= valStr and not entry.active then
                        entry.last = valStr
                        if entry.kind == "mimgui" and entry.buf then
                            pcall(function()
                                local okF, ffi = pcall(require, "ffi")
                                if okF and ffi then
                                    ffi.fill(entry.buf, maxLen)
                                    ffi.copy(entry.buf, valStr, math.min(#valStr, maxLen - 1))
                                end
                            end)
                        elseif entry.kind == "moonimgui" and entry.buf then
                            pcall(function() entry.buf.v = valStr end)
                        end
                    end
                    roundRect(dlist, atFn(x, y), atFn(x + w, y + h), col32(7, 8, 15, 245), 8)
                    if not entry.buf then
                        if dlist.AddRect then
                            pcall(dlist.AddRect, dlist, atFn(x + 0.5, y + 0.5), atFn(x + w - 0.5, y + h - 0.5), c32(TH.line), 8, 0, 1)
                        end
                        uiText(x + 10, y + (h - 14) * 0.5, valStr ~= "" and valStr or tostring(hint or ""), c4(TH.textDim), 0.88)
                        return valStr, false, false, false
                    end
                    local nC, nS = 0, 0
                    if grndPushCol(im.Col and im.Col.FrameBg, rgba(0, 0, 0, 0)) then nC = nC + 1 end
                    if grndPushCol(im.Col and im.Col.FrameBgHovered, rgba(0, 0, 0, 0)) then nC = nC + 1 end
                    if grndPushCol(im.Col and im.Col.FrameBgActive, rgba(0, 0, 0, 0)) then nC = nC + 1 end
                    if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then nC = nC + 1 end
                    if grndPushCol(im.Col and im.Col.Text, c4(TH.textHi)) then nC = nC + 1 end
                    local padY = math.max(4, math.floor((h - 15) * 0.5))
                    if grndPushStyleV2(im.StyleVar and im.StyleVar.FramePadding, 10, padY) then nS = nS + 1 end
                    if grndPushStyleF(im.StyleVar and im.StyleVar.FrameBorderSize, 0) then nS = nS + 1 end
                    local fl = 0
                    if im.InputTextFlags and im.InputTextFlags.EnterReturnsTrue then
                        fl = im.InputTextFlags.EnterReturnsTrue
                    elseif rawget(im, "ImGuiInputTextFlags_EnterReturnsTrue") then
                        fl = rawget(im, "ImGuiInputTextFlags_EnterReturnsTrue")
                    end
                    im.SetCursorPos(im.ImVec2(x, y))
                    if im.PushItemWidth then pcall(im.PushItemWidth, w) end
                    local okI, retI = false, false
                    if entry.kind == "mimgui" then
                        if im.InputTextWithHint then
                            okI, retI = pcall(im.InputTextWithHint, "##ui_inp_" .. key, tostring(hint or ""), entry.buf, maxLen, fl)
                        elseif im.InputText then
                            okI, retI = pcall(im.InputText, "##ui_inp_" .. key, entry.buf, maxLen, fl)
                        end
                    else
                        okI, retI = pcall(im.InputText, "##ui_inp_" .. key, entry.buf, fl)
                    end
                    local act = (im.IsItemActive and im.IsItemActive()) and true or false
                    entry.active = act
                    if im.PopItemWidth then pcall(im.PopItemWidth) end
                    grndPopStyle(nS)
                    grndPopCol(nC)
                    local outStr = valStr
                    if entry.kind == "mimgui" then
                        pcall(function()
                            local okF, ffi = pcall(require, "ffi")
                            if okF and ffi then outStr = ffi.string(entry.buf) end
                        end)
                    else
                        pcall(function() outStr = tostring(entry.buf.v or "") end)
                    end
                    if outStr == "" and not act and hint and hint ~= "" and entry.kind ~= "mimgui" then
                        uiText(x + 10, y + (h - 14) * 0.5, hint, c4(TH.textMuted), 0.88)
                    end
                    if dlist.AddRect then
                        pcall(dlist.AddRect, dlist, atFn(x + 0.5, y + 0.5), atFn(x + w - 0.5, y + h - 0.5),
                            act and col32(TH.accent[1], TH.accent[2], TH.accent[3], 185) or c32(TH.line), 8, 0, 1)
                    end
                    local changed = (outStr ~= entry.last)
                    entry.last = outStr
                    local submitted = (okI and retI == true and fl ~= 0) and true or false
                    return outStr, changed, submitted, act
                end

                -- ======================== ЛЕВЫЙ САЙДБАР (до 212 px) ========================
                roundRect(dl, at(0, 0), at(SB, H), c32(TH.sidebar), 14,
                    cornerFlags(true, false, true, false))
                if not grndBrandLogoDraw({im=im,dl=dl,at=at,col32=col32,
                    x=16,y=10,w=SB-32,h=70,alpha=a}) then
                    local brand = "GRND TOOLS"
                    local brandW = tsize(brand)
                    uiText((SB - brandW) / 2, 36, brand, c4(TH.textHi))
                end
                do
                    local caption = {"Способный сделать", "работу лучше"}
                    for i, line in ipairs(caption) do
                        local width = tsize(line)
                        local scale = math.min(0.92, (SB - 28) / math.max(1, width))
                        local measured = drawnWb(line, scale)
                        uiText(math.max(10, (SB - measured) / 2), 84 + (i - 1) * 16,
                            line, c4(TH.textDim), scale)
                    end
                    local verText = "v" .. tostring(GRND_SCRIPT_VERSION or "")
                    local sc = math.min(0.80, (SB - 32) / math.max(1, tsize(verText)))
                    local mw = drawnWb(verText, sc)
                    uiText(math.max(10, (SB - mw) / 2), 118, verText, c4(TH.textMuted), sc)
                end
                -- Без разделительной линии под логотипом (согласно эталону)
                local tabsY = 138
                local styleHeight = GRND_UIKIT.pickerOpen and 246 or 68
                local tabsH = math.max(BH * 4, H - tabsY - styleHeight - 8)
                BH = math.max(30, math.min(36, math.floor((tabsH - math.max(0, #MENU_TABS - 1) * BGAP) / math.max(1, #MENU_TABS))))
                do
                    local useChild = type(im.BeginChild) == "function"
                    local contX, contY = pos.x + BPAD, pos.y + tabsY
                    if useChild then
                        im.SetCursorPos(im.ImVec2(BPAD, tabsY))
                        local cf = (im.WindowFlags and im.WindowFlags.NoScrollbar) or 0
                        local ok, res = pcall(im.BeginChild, "##grnd_tabs", im.ImVec2(BW, tabsH), false, cf)
                        useChild = ok and (res ~= false)
                        if useChild then
                            local cp = im.GetWindowPos()
                            contX, contY = cp.x, cp.y
                        end
                    end
                    local bdl = useChild and im.GetWindowDrawList() or dl
                    local function cur(x, y)
                        if useChild then im.SetCursorPos(im.ImVec2(x, y))
                        else im.SetCursorPos(im.ImVec2(BPAD + x, tabsY + y)) end
                    end
                    local function txt(x, y, s, col, sc)
                        if useChild then uiText(x, y, s, col, sc)
                        else uiText(BPAD + x, tabsY + y, s, col, sc) end
                    end
                    local function cat(dx, dy) return im.ImVec2(contX + dx, contY + dy) end
                    for i, t in ipairs(MENU_TABS) do
                        local rowY = (i - 1) * (BH + BGAP)
                        cur(0, rowY)
                        if im.InvisibleButton("##tab_" .. t.id, im.ImVec2(BW, BH)) then
                            menu.tab = i
                        end
                        local p1 = im.GetItemRectMin()
                        local p2 = im.GetItemRectMax()
                        local hovered  = (im.IsItemHovered and im.IsItemHovered()) or false
                        local pressed  = (im.IsItemActive  and im.IsItemActive())  or false
                        local selected = (menu.tab == i)
                        if selected then
                            roundRect(bdl, p1, p2, c32(TH.itemSel), 9)
                            if bdl.AddRect then
                                pcall(bdl.AddRect, bdl, p1, p2,
                                    col32(TH.accent[1], TH.accent[2], TH.accent[3], 95), 9, 0, 1)
                            end
                        elseif pressed then
                            roundRect(bdl, p1, p2, c32(TH.itemPress), 9)
                        elseif hovered then
                            roundRect(bdl, p1, p2, c32(TH.itemHover), 9)
                        end
                        _G.grndDrawVecIcon(bdl, t.id, contX + 18, contY + rowY + BH * 0.5, 15,
                            selected and col32(TH.accent[1], TH.accent[2], TH.accent[3], 255)
                                or (hovered and col32(238, 241, 250, 255) or col32(148, 155, 182, 235)))
                        local tw, th = tsize(t.name)
                        local scT = tw > (BW - 44) and math.max(0.78, (BW - 44) / math.max(1, tw)) or 0.94
                        txt(34, rowY + (BH - th) * 0.5, t.name,
                            selected and c4(TH.textHi)
                                or (hovered and c4(TH.text) or c4(TH.textDim)), scT)
                    end
                    local tabIdx0 = tonumber(menu.tab) or 1
                    if tabIdx0 < 1 or tabIdx0 > #MENU_TABS then tabIdx0 = 1 end
                    local targetY = (tabIdx0 - 1) * (BH + BGAP)
                    if menu.indY == nil then menu.indY = targetY end
                    menu.indY = menu.indY + (targetY - menu.indY) * math.min(1, dt * 16)
                    gradRect(bdl, cat(0, menu.indY + 8), cat(3.5, menu.indY + BH - 8),
                        c32(TH.accent), c32(TH.accent2), 2)
                    if useChild then
                        if type(im.EndChild) == "function" then pcall(im.EndChild)
                        else pcall(im.End) end
                    end
                end
                grndUiStylePanel({im=im,dl=dl,at=at,col32=col32,rgba=rgba,
                    roundRect=roundRect,uiText=uiText,tsize=tsize,slider=menuSlider,
                    x=BPAD,y=H-styleHeight-4,w=SB-BPAD*2,h=styleHeight})

                -- ======================== ВЕРХНИЙ ХЕДЕР И 2 ЛИНИИ ========================
                local tabIdx = tonumber(menu.tab) or 1
                if tabIdx < 1 or tabIdx > #MENU_TABS then tabIdx = 1; menu.tab = 1 end
                local tab = MENU_TABS[tabIdx] or MENU_TABS[1]
                if tab.id ~= "chrome" and tab.id ~= "complaints" then
                    if type(_G.grndBrowserTick) == "function" then
                        pcall(_G.grndBrowserTick, false, nil)
                    end
                end
                dl:AddRectFilled(at(SB, 0), at(SB + 1, H), c32(TH.line))
                dl:AddRectFilled(at(SB, 56), at(W, 57), c32(TH.line))
                dl:AddRectFilled(at(SB, 94), at(W, 95), c32(TH.line))

                _G.grndDrawVecIcon(dl, tab.id, pos.x + SB + 28, pos.y + 28, 16,
                    col32(TH.accent[1], TH.accent[2], TH.accent[3], 255))
                uiText(SB + 44, 18, tab.name, c4(TH.textHi), 1.24)

                local srchW, srchH = 248, 32
                local closeX, recenterX = W - 44, W - 82
                local srchX, srchY = recenterX - srchW - 10, 12
                do
                    if menu.searchReset then
                        menu.searchReset = false
                        if menu.bufs then menu.bufs["hdr_search"] = nil end
                    end
                    local sq, sChanged = UI.input(dl, at, "hdr_search", srchX, srchY, srchW, srchH,
                        GRND_FUNC_SEARCH.query or "", "      Поиск функции...", 96)
                    if sChanged then GRND_FUNC_SEARCH.query = sq end
                    _G.grndDrawVecIcon(dl, "search", pos.x + srchX + 16, pos.y + srchY + srchH * 0.5, 13,
                        col32(142, 150, 178, 225))

                    im.SetCursorPos(im.ImVec2(recenterX, 12))
                    if im.InvisibleButton("##grnd_recenter", im.ImVec2(32, 32)) then
                        menu.wantRecenter = true
                    end
                    local rhov = (im.IsItemHovered and im.IsItemHovered()) or false
                    roundRect(dl, at(recenterX, 12), at(recenterX + 32, 44),
                        rhov and c32(TH.itemHover) or col32(255, 255, 255, 7), 8)
                    if dl.AddRect then
                        pcall(dl.AddRect, dl, at(recenterX + 0.5, 12.5), at(recenterX + 31.5, 43.5), c32(TH.line), 8, 0, 1)
                    end
                    _G.grndDrawVecIcon(dl, "recenter", pos.x + recenterX + 16, pos.y + 28, 14,
                        rhov and col32(244, 246, 255, 255) or col32(158, 165, 192, 235))

                    im.SetCursorPos(im.ImVec2(closeX, 12))
                    if im.InvisibleButton("##grnd_close", im.ImVec2(32, 32)) then
                        menu.open = false
                    end
                    local chov = (im.IsItemHovered and im.IsItemHovered()) or false
                    roundRect(dl, at(closeX, 12), at(closeX + 32, 44),
                        chov and col32(235, 78, 92, 52) or col32(255, 255, 255, 7), 8)
                    if dl.AddRect then
                        pcall(dl.AddRect, dl, at(closeX + 0.5, 12.5), at(closeX + 31.5, 43.5),
                            chov and col32(245, 98, 112, 180) or c32(TH.line), 8, 0, 1)
                    end
                    local lc = chov and col32(255, 142, 150, 255) or col32(175, 182, 206, 235)
                    dl:AddLine(at(closeX + 11, 23), at(closeX + 21, 33), lc, 1.5)
                    dl:AddLine(at(closeX + 21, 23), at(closeX + 11, 33), lc, 1.5)
                end

                do
                    local barX, barY, barH = SB + 20, 62, 26
                    if tab.id == "settings" then
                        menu.settingsTab = menu.settingsTab or "main"
                        local stTabs = {
                            { id = "main",     name = "Общие" },
                            { id = "admin",    name = "Админ" },
                            { id = "ring",     name = "Вспомогательный круг" },
                            { id = "recon",    name = "Настройки рекона" },
                            { id = "pactions", name = "Действия с игроком" },
                        }
                        local cx = barX
                        for _, st in ipairs(stTabs) do
                            local clk, pw = UI.pill(cx, barY, barH, st.name, menu.settingsTab == st.id, "st_" .. st.id, 13)
                            if clk then menu.settingsTab = st.id end
                            cx = cx + pw + 8
                        end
                    elseif tab.id == "checkers" then
                        menu.checkersTab = menu.checkersTab or "visual"
                        local ckTabs = {
                            { id = "visual",  name = "Визуальные" },
                            { id = "players", name = "Игроки" },
                            { id = "admins",  name = "Администрация" },
                            { id = "stats",   name = "Статистика" },
                        }
                        local cx = barX
                        for _, ct in ipairs(ckTabs) do
                            local clk, pw = UI.pill(cx, barY, barH, ct.name, menu.checkersTab == ct.id, "ck_" .. ct.id, 14)
                            if clk then menu.checkersTab = ct.id end
                            cx = cx + pw + 8
                        end
                    elseif tab.id == "punish" then
                        menu.punPage = (menu.punPage == "auto") and "auto" or "give"
                        local c1, w1 = UI.pill(barX, barY, barH, "Выдача", menu.punPage == "give", "pun_give", 16)
                        if c1 then menu.punPage = "give" end
                        local c2 = UI.pill(barX + w1 + 8, barY, barH, "Автопилот", menu.punPage == "auto", "pun_auto", 16)
                        if c2 then menu.punPage = "auto" end
                    elseif tab.id == "chrome" or tab.id == "complaints" then
                        local bKind = (tab.id == "complaints") and "complaints" or "chrome"
                        local BS = GRND_BROWSER.sessions[bKind]
                        local cx = barX
                        if UI.btn(dl, at, cx, barY, 28, barH, "<", bKind .. "_back") then
                            _G.grndBrowserAction(bKind, "back")
                        end
                        cx = cx + 32
                        if UI.btn(dl, at, cx, barY, 28, barH, ">", bKind .. "_fwd") then
                            _G.grndBrowserAction(bKind, "forward")
                        end
                        cx = cx + 32
                        if UI.btn(dl, at, cx, barY, 30, barH, "↻", bKind .. "_rel") then
                            _G.grndBrowserAction(bKind, "reload")
                        end
                        cx = cx + 36
                        if bKind == "complaints" then
                            if UI.btn(dl, at, cx, barY, 78, barH, "Жалобы", "cmp_main", true) then
                                _G.grndBrowserAction("complaints", "navigate", GRND_BROWSER.COMPLAINTS_URL)
                            end
                            cx = cx + 84
                            if UI.btn(dl, at, cx, barY, 102, barH, "Авторизация", "cmp_auth") then
                                _G.grndBrowserAction("complaints", "navigate", GRND_BROWSER.AUTH_URL)
                            end
                            cx = cx + 108
                            local rightReserve = 344
                            local urlW = math.max(150, (W - rightReserve) - cx)
                            local nu, uCh, uSub, uAct = UI.input(dl, at, "url_complaints", cx, barY, urlW, barH,
                                BS.inputUrl or GRND_BROWSER.COMPLAINTS_URL, "https://grnd.gg/admin/complaints", 240)
                            BS.editingUrl = uAct
                            if uCh then BS.inputUrl = nu end
                            if uSub then _G.grndBrowserAction("complaints", "navigate", nu) end
                            cx = cx + urlW + 8
                            local zm = GRND_MAIN_EXT.complaintsZoom or 80
                            if UI.btn(dl, at, cx, barY, 24, barH, "-", "cmp_zm_dn") then
                                GRND_MAIN_EXT.complaintsZoom = math.max(50, zm - 10)
                                pcall(grndCamCfgSave)
                            end
                            uiText(cx + 28, barY + 6, tostring(GRND_MAIN_EXT.complaintsZoom or 80) .. "%", c4(TH.textHi), 0.86)
                            if UI.btn(dl, at, cx + 64, barY, 24, barH, "+", "cmp_zm_up") then
                                GRND_MAIN_EXT.complaintsZoom = math.min(150, zm + 10)
                                pcall(grndCamCfgSave)
                            end
                            cx = cx + 94
                            local arOn = GRND_MAIN_EXT.complaintsAuto ~= false
                            local arLbl = arOn and ("Авто · " .. tostring(GRND_MAIN_EXT.complaintsEvery or 3) .. "с") or "Авто: выкл"
                            if UI.btn(dl, at, cx, barY, 92, barH, arLbl, "cmp_auto", arOn) then
                                GRND_MAIN_EXT.complaintsAuto = not arOn
                                pcall(grndCamCfgSave)
                            end
                            cx = cx + 98
                            if UI.btn(dl, at, cx, barY, 104, barH, "Внешний ↗", "cmp_ext") then
                                _G.grndBrowserOpenExternal(BS.url or GRND_BROWSER.COMPLAINTS_URL)
                            end
                        else
                            if UI.btn(dl, at, cx, barY, 68, barH, "Google", "chr_home") then
                                _G.grndBrowserAction("chrome", "navigate", GRND_BROWSER.CHROME_HOME)
                            end
                            cx = cx + 74
                            local rightReserve = 224
                            local urlW = math.max(180, (W - rightReserve) - cx)
                            local nu, uCh, uSub, uAct = UI.input(dl, at, "url_chrome", cx, barY, urlW, barH,
                                BS.inputUrl or GRND_BROWSER.CHROME_HOME, "Введите адрес или поисковый запрос...", 240)
                            BS.editingUrl = uAct
                            if uCh then BS.inputUrl = nu end
                            if uSub then _G.grndBrowserAction("chrome", "navigate", nu) end
                            cx = cx + urlW + 8
                            local zm = GRND_MAIN_EXT.chromeZoom or 100
                            if UI.btn(dl, at, cx, barY, 24, barH, "-", "chr_zm_dn") then
                                GRND_MAIN_EXT.chromeZoom = math.max(50, zm - 10)
                                pcall(grndCamCfgSave)
                            end
                            uiText(cx + 28, barY + 6, tostring(GRND_MAIN_EXT.chromeZoom or 100) .. "%", c4(TH.textHi), 0.86)
                            if UI.btn(dl, at, cx + 68, barY, 24, barH, "+", "chr_zm_up") then
                                GRND_MAIN_EXT.chromeZoom = math.min(150, zm + 10)
                                pcall(grndCamCfgSave)
                            end
                            cx = cx + 98
                            if UI.btn(dl, at, cx, barY, 104, barH, "Внешний ↗", "chr_ext") then
                                _G.grndBrowserOpenExternal(BS.url or GRND_BROWSER.CHROME_HOME)
                            end
                        end
                    else
                        local subMap = {
                            report    = "Обращения игроков · быстрые ответы · автоловля репорта",
                            mppanel   = "Управление мероприятиями · массовая выдача · телепортация",
                            logs      = "Журнал событий чата, форм, репортов и действий администрации",
                            binder    = "Горячие клавиши, бинды и многострочные последовательности команд",
                            cheats    = "Админские чит-модули · полёт · инвиз · защита от AFK",
                            character = "Погода и время · быстрые телепорты · выдача транспорта и оружия",
                            fwzone    = "Семейные войны · контроль территории и возврата после больницы (RK)",
                            bwzone    = "Войны за бизнесы · зональный трекер нарушений",
                        }
                        uiText(barX, barY + 5, subMap[tab.id] or "Рабочие инструменты администратора", c4(TH.textMuted), 0.90)
                    end
                end

                -- ======================== РАБОЧАЯ ОБЛАСТЬ КОНТЕНТА ========================
                local cardX, cardY = SB + 20, 108
                local cardW, cardH = W - SB - 40, H - 124

                if cardW > 40 and cardH > 40 then
                    if type(tab.draw) == "function" then
                        do
                            UI.card(dl, at, cardX, cardY, cardW, cardH, 10)
                            im.SetCursorPos(im.ImVec2(cardX + 16, cardY + 14))
                            local ok, err = pcall(tab.draw, {
                                w = cardW - 32, h = cardH - 28, pad = 16,
                                x = cardX, y = cardY,
                            })
                            if not ok then
                                uiText(cardX + 16, cardY + 14,
                                    "Ошибка отрисовки раздела: " .. tostring(err),
                                    c4({ 255, 110, 110, 255 }))
                            end
                        end

                    elseif tab.id == "settings" then
                        do
                            local stMode = menu.settingsTab or "main"
                            if stMode == "main" then
                                im.SetCursorPos(im.ImVec2(cardX, cardY))
                                local okCh, visCh = pcall(im.BeginChild, "##grnd_set_main_grid", im.ImVec2(cardW, cardH), false, 0)
                                if okCh then
                                    if visCh ~= false then
                                        local cdl = im.GetWindowDrawList()
                                        local cpos = im.GetWindowPos()
                                        local sy = im.GetScrollY and im.GetScrollY() or 0
                                        local function cat(dx, dy) return im.ImVec2(cpos.x + dx, cpos.y + dy - sy) end
                                        local gap = 14
                                        local colW = math.floor((cardW - gap - 10) * 0.5)
                                        local xL, xR = 0, colW + gap
                                        local E = GRND_MAIN_EXT or {}
                                        local CM = GRND_CAM or {}
                                        local CH = GRND_CHAT or {}
                                        local CK = GRND_CLOCK or {}
                                        local popCtx = { im=im, dl=dl, at=at, uiText=uiText, tsize=tsize,
                                            roundRect=roundRect, col32=col32, rgba=rgba, TH=TH, dt=dt }
                                        GRND_SETUI.gearHover = false
                                        GRND_SETUI.gears = {}

                                        local function cSlider(x, y, w, val, vmin, vmax, step, tag)
                                            local frac = (vmax > vmin) and ((val - vmin) / (vmax - vmin)) or 0
                                            frac = math.min(1, math.max(0, frac))
                                            grndSliderPaint({ dl = cdl, at = cat, col32 = col32,
                                                roundRect = roundRect, TH = TH }, x, y, w, 20, frac)
                                            im.SetCursorPos(im.ImVec2(x - 4, y))
                                            im.InvisibleButton("##cms_" .. tag, im.ImVec2(w + 8, 20))
                                            local nv = val
                                            if im.IsItemActive and im.IsItemActive() then
                                                local mp = menuMousePos()
                                                if mp then
                                                    local f = math.min(1, math.max(0, (mp.x - (cpos.x + x)) / math.max(1, w)))
                                                    nv = vmin + f * (vmax - vmin)
                                                    if step and step > 0 then
                                                        nv = math.floor((nv - vmin) / step + 0.5) * step + vmin
                                                    end
                                                end
                                            end
                                            return nv, (nv ~= val)
                                        end
                                        local function cToggle(x, y, on, tag)
                                            im.SetCursorPos(im.ImVec2(x, y))
                                            local id = "##cmt_" .. tag
                                            local cl = im.InvisibleButton(id, im.ImVec2(46, 24))
                                            local hv = (im.IsItemHovered and im.IsItemHovered()) or false
                                            grndUiSwitchPaint({ dl = cdl, at = cat, col32 = col32, roundRect = roundRect },
                                                x, y, on, hv, id, dt)
                                            return cl
                                        end

                                        local r1Y, r1H = 0, 146
                                        UI.card(cdl, cat, xL, r1Y, colW, r1H, 10)
                                        uiText(xL + 16, r1Y + 12, "Дистанция камеры", c4(TH.textHi), 1.02)
                                        uiText(xL + 16, r1Y + 32, "Отдаление камеры персонажа и рыбий глаз (FOV)", c4(TH.textMuted), 0.84)
                                        if cToggle(xL + colW - 60, r1Y + 14, CM.enabled == true, "m_cam_on") then
                                            CM.enabled = not (CM.enabled == true); pcall(grndCamCfgSave)
                                        end
                                        local dStr = string.format("%.1f м", tonumber(CM.dist) or 12.0)
                                        uiText(xL + 16, r1Y + 60, "Дистанция: " .. dStr, c4(TH.text), 0.88)
