        local function argbToRgba(c)
            if type(c) ~= "number" or c == 0 then
                return rgba(220, 228, 220, 255)
            end
            c = math.floor(c) % 0x100000000
            local a = math.floor(c / 0x1000000) % 256
            local r = math.floor(c / 0x10000) % 256
            local g = math.floor(c / 0x100) % 256
            local b = c % 256
            if a == 0 then
                r = math.floor(c / 0x10000) % 256
                g = math.floor(c / 0x100) % 256
                b = c % 256
            end
            return rgba(r, g, b, 255)
        end
        local function getLocalSampId()
            if type(sampGetPlayerIdByCharHandle) == "function" then
                local ok, a, b = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
                if ok then
                    if type(a) == "number" then return a end
                    if a and type(b) == "number" then return b end
                end
            end
            if type(sampGetLocalPlayerId) == "function" then
                local ok, lid = pcall(sampGetLocalPlayerId)
                if ok and type(lid) == "number" then return lid end
            end
            return nil
        end
        local function refreshScoreboard()
            local list, total = {}, 0
            local maxId = 999
            if type(sampGetMaxPlayerId) == "function" then
                local ok, m = pcall(sampGetMaxPlayerId)
                if ok and type(m) == "number" and m > 0 then maxId = m end
            end
            local loc = getLocalSampId()
            scoreboard.localId = loc or -1
            for id = 0, maxId do
                local connected = (loc ~= nil and id == loc)
                if not connected and type(sampIsPlayerConnected) == "function" then
                    local ok, r = pcall(sampIsPlayerConnected, id)
                    connected = ok and r
                elseif not connected and type(sampGetPlayerNickname) == "function" then
                    local ok, n = pcall(sampGetPlayerNickname, id)
                    connected = ok and type(n) == "string" and n ~= ""
                end
                if connected then
                    total = total + 1
                    local nick, score, ping, color, streamed = "?", 0, 0, 0, false
                    if type(sampGetPlayerNickname) == "function" then
                        local ok, n = pcall(sampGetPlayerNickname, id)
                        if ok and type(n) == "string" and n ~= "" then nick = n end
                    end
                    if type(sampGetPlayerScore) == "function" then
                        local ok, s = pcall(sampGetPlayerScore, id)
                        if ok and type(s) == "number" then score = s end
                    end
                    if type(sampGetPlayerPing) == "function" then
                        local ok, pg = pcall(sampGetPlayerPing, id)
                        if ok and type(pg) == "number" then ping = pg end
                    end
                    if type(sampGetPlayerColor) == "function" then
                        local ok, c = pcall(sampGetPlayerColor, id)
                        if ok and type(c) == "number" then color = c end
                    end
                    if type(sampGetCharHandleBySampPlayerId) == "function" then
                        local ok, found = pcall(function()
                            local f = sampGetCharHandleBySampPlayerId(id)
                            return f and true or false
                        end)
                        if ok and found then streamed = true end
                    elseif id == loc then
                        streamed = true
                    end
                    list[#list + 1] = {
                        id = id, nick = nick, utf = cp1251_to_utf8(nick),
                        score = score, ping = ping, color = color,
                        streamed = streamed, localp = (id == loc),
                    }
                end
            end
            table.sort(list, function(a, b)
                if a.localp ~= b.localp then return a.localp end
                return a.id < b.id
            end)
            local srv = ""
            if type(sampGetCurrentServerName) == "function" then
                local ok, n = pcall(sampGetCurrentServerName)
                if ok and type(n) == "string" then srv = cp1251_to_utf8(n) end
            end
            if srv == "" then srv = "GRND" end
            scoreboard.players = list
            scoreboard.total   = total
            scoreboard.server  = srv
            scoreboard.cacheT  = os.clock()
        end
        function grndTabFirstLocalId()
            local ok = pcall(refreshScoreboard)
            if not ok then return nil end
            local first = scoreboard.players[1]
            local id = scoreboard.localId
            if not first or first.localp ~= true or type(id) ~= "number"
                or type(first.id) ~= "number" or first.id ~= id
                or id < 0 or id >= 1004 or id ~= math.floor(id) then
                return nil
            end
            if type(sampGetLocalPlayerId) == "function" then
                local okId, lid = pcall(sampGetLocalPlayerId)
                if okId and type(lid) == "number" and math.floor(lid) ~= id then
                    return nil
                end
            end
            return id
        end
        local function ensureSearchBuf()
            if scoreboard.buf then return end
            if im.new and im.new.char then
                local ok, buf = pcall(function() return im.new.char[128]() end)
                if ok and buf then
                    scoreboard.buf = buf
                    scoreboard.bufKind = "ffi"
                    return
                end
            end
            if im.ImBuffer then
                local ok, buf = pcall(im.ImBuffer, 128)
                if ok and buf then
                    scoreboard.buf = buf
                    scoreboard.bufKind = "imbuf"
                    return
                end
            end
            scoreboard.bufKind = "none"
        end
        local function readSearchBuf()
            if scoreboard.bufKind == "ffi" and scoreboard.buf then
                local ok, s = pcall(function()
                    local ffi = require "ffi"
                    return ffi.string(scoreboard.buf)
                end)
                if ok and type(s) == "string" then return s end
            elseif scoreboard.bufKind == "imbuf" and scoreboard.buf then
                local v = scoreboard.buf.v or scoreboard.buf
                if type(v) == "string" then return v end
                return tostring(v or "")
            end
            return scoreboard.search or ""
        end
        local function nickMatches(utf, q)
            if not q or q == "" then return true end
            utf = tostring(utf or "")
            q = tostring(q)
            local a, b = utf:lower(), q:lower()
            if a:find(b, 1, true) then return true end
            if utf:find(q, 1, true) then return true end
            return false
        end
        local SB_WIN_FLAGS = wf("NoTitleBar", "NoResize", "NoCollapse",
            "NoScrollbar", "NoMove", "NoScrollWithMouse")
        if wflag("NoNav") ~= 0 then
            SB_WIN_FLAGS = SB_WIN_FLAGS + wflag("NoNav")
        elseif wflag("NoNavInputs") ~= 0 then
            SB_WIN_FLAGS = SB_WIN_FLAGS + wflag("NoNavInputs")
        end
        local function drawScoreboard(dt)
            dt = dt or 0.016
            local speed = 14.0
            if GRND_TAB.open then
                scoreboard.anim = math.min(1, (scoreboard.anim or 0) + dt * speed)
            else
                scoreboard.anim = math.max(0, (scoreboard.anim or 0) - dt * speed)
            end
            if scoreboard.anim <= 0 then return false end
            if os.clock() - (scoreboard.cacheT or 0) > 0.35
               or #(scoreboard.players or {}) == 0 then
                pcall(refreshScoreboard)
            end
            local a = scoreboard.anim
            local resX, resY = getScreenResolution()
            local W = math.min(680, math.max(520, math.floor(resX * 0.48)))
            local H = math.min(640, math.max(380, math.floor(resY * 0.72)))
            local ROW = 22
            im.SetNextWindowPos(im.ImVec2(math.floor((resX - W) / 2),
                math.floor((resY - H) / 2)), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            grndPushStyleF(im.StyleVar and im.StyleVar.Alpha, a)
            grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 10)
            grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0)
            grndPushCol(im.Col and im.Col.WindowBg, c4(TH.bg))
            grndPushCol(im.Col and im.Col.Border,   c4(TH.line))
            grndPushCol(im.Col and im.Col.Text,     c4(TH.textHi))
            local wantCursor = false
            if grndBegin("GRND Scoreboard##grnd_tab", SB_WIN_FLAGS) then
                wantCursor = GRND_TAB.open
                local pos = im.GetWindowPos()
                local dl  = im.GetWindowDrawList()
                local function at(dx, dy) return im.ImVec2(pos.x + dx, pos.y + dy) end
                pcall(dl.AddRect, dl, at(0.5, 0.5), at(W - 0.5, H - 0.5),
                    c32(TH.line), 10, 0, 1.4)
                local title = (scoreboard.server ~= "" and scoreboard.server) or "GRND"
                local tw = grndTextW(title)
                uiText((W - tw) / 2, 14, title, c4(TH.textHi))
                local countStr = "Игроков: " .. tostring(scoreboard.total or 0)
                uiText(18, 38, countStr, c4(TH.text))
                local sw, sh = 168, 24
                local sx, sy = W - 18 - sw, 34
                roundRect(dl, at(sx, sy), at(sx + sw, sy + sh), c32(TH.sidebar), 8)
                pcall(dl.AddRect, dl, at(sx, sy), at(sx + sw, sy + sh), c32(TH.line), 8)
                ensureSearchBuf()
                im.SetCursorPos(im.ImVec2(sx + 8, sy + 3))
                if im.PushItemWidth then pcall(im.PushItemWidth, sw - 16) end
                grndPushCol(im.Col and im.Col.FrameBg, rgba(0, 0, 0, 0))
                grndPushCol(im.Col and im.Col.FrameBgHovered, rgba(0, 0, 0, 0))
                grndPushCol(im.Col and im.Col.FrameBgActive, rgba(0, 0, 0, 0))
                grndPushCol(im.Col and im.Col.Text, rgba(230, 236, 230, 255))
                grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0))
                if scoreboard.bufKind == "ffi" and scoreboard.buf then
                    if im.InputTextWithHint then
                        pcall(im.InputTextWithHint, "##grnd_sb_q", "Поиск", scoreboard.buf, 128)
                    elseif im.InputText then
                        pcall(im.InputText, "##grnd_sb_q", scoreboard.buf, 128)
                    end
                elseif scoreboard.bufKind == "imbuf" and scoreboard.buf then
                    if im.InputTextWithHint then
                        pcall(im.InputTextWithHint, "##grnd_sb_q", "Поиск", scoreboard.buf)
                    elseif im.InputText then
                        pcall(im.InputText, "##grnd_sb_q", scoreboard.buf)
                    end
                end
                grndPopCol(5)
                if im.PopItemWidth then pcall(im.PopItemWidth) end
                scoreboard.search = readSearchBuf()
                if (not scoreboard.search or scoreboard.search == "") then
                    if not im.InputTextWithHint or scoreboard.bufKind == "none" then
                        uiText(sx + 10, sy + 4, "Поиск", c4(TH.textMuted))
                    end
                end
                dl:AddRectFilled(at(14, 66), at(W - 14, 67), c32(TH.line))
                local colY = 72
                local xId, xNick = 18, 96
                local xLvl, xPing = W - 18 - 70 - 86, W - 18 - 70
                uiText(xId, colY, "ID", c4(TH.textMuted))
                uiText(xNick, colY, "Никнейм", c4(TH.textMuted))
                uiText(xLvl, colY, "Уровень", c4(TH.textMuted))
                uiText(xPing, colY, "Пинг", c4(TH.textMuted))
                local cb = 13
                local idw = grndTextW("ID")
                local cbx, cby = xId + idw + 6, colY + 2
                im.SetCursorPos(im.ImVec2(cbx, cby))
                if im.InvisibleButton("##grnd_sb_stream", im.ImVec2(cb, cb)) then
                    scoreboard.streamOnly = not scoreboard.streamOnly
                end
                local chov = (im.IsItemHovered and im.IsItemHovered()) or false
                local c1, c2 = at(cbx, cby), at(cbx + cb, cby + cb)
                local bcol = chov and c32(TH.text) or c32(TH.textMuted)
                pcall(dl.AddRect, dl, c1, c2, bcol, 2)
                if scoreboard.streamOnly then
                    roundRect(dl, at(cbx + 3, cby + 3), at(cbx + cb - 3, cby + cb - 3),
                        c32(TH.accent), 1)
                end
                dl:AddRectFilled(at(14, colY + 20), at(W - 14, colY + 21), c32(TH.line))
                local listY = colY + 26
                local footH = 22
                local listH = H - listY - footH - 8
                if listH < 40 then listH = 40 end
                im.SetCursorPos(im.ImVec2(8, listY))
                grndPushCol(im.Col and im.Col.ChildBg, rgba(0, 0, 0, 0))
                grndPushCol(im.Col and im.Col.ScrollbarBg,
                    rgba(TH.sidebar[1], TH.sidebar[2], TH.sidebar[3], 80))
                grndPushCol(im.Col and im.Col.ScrollbarGrab,
                    rgba(TH.accent[1], TH.accent[2], TH.accent[3], 160))
                local useChild = type(im.BeginChild) == "function"
                if useChild then
                    local ok, res = pcall(im.BeginChild, "##grnd_sb_list",
                        im.ImVec2(W - 16, listH), false)
                    useChild = ok and (res ~= false)
                end
                do
                    local q = scoreboard.search or ""
                    local row = 0
                    local cdl = useChild and im.GetWindowDrawList() or dl
                    for i = 1, #(scoreboard.players or {}) do
                        local pl = scoreboard.players[i]
                        if (not scoreboard.streamOnly or pl.streamed or pl.localp)
                            and nickMatches(pl.utf, q)
                        then
                            local ry = row * ROW
                            if useChild then im.SetCursorPos(im.ImVec2(0, ry))
                            else im.SetCursorPos(im.ImVec2(8, listY + ry)) end
                            if im.InvisibleButton("##grnd_sb_row_" .. pl.id,
                                im.ImVec2(W - 24, ROW)) then
                                if not pl.localp then
                                    GRND_TAB.specId = pl.id
                                    GRND_TAB.open = false
                                end
                            end
                            local hovered = (im.IsItemHovered and im.IsItemHovered()) or false
                            if hovered then
                                local p1, p2 = im.GetItemRectMin(), im.GetItemRectMax()
                                cdl:AddRectFilled(p1, p2, pl.localp
                                    and col32(255, 255, 255, 10)
                                    or col32(TH.accent[1], TH.accent[2], TH.accent[3], 28))
                            end
                            local tx = useChild and (xId - 8) or xId
                            local nx = useChild and (xNick - 8) or xNick
                            local lx = useChild and (xLvl - 8) or xLvl
                            local px = useChild and (xPing - 8) or xPing
                            local ty = useChild and (ry + 3) or (listY + ry + 3)
                            uiText(tx, ty, tostring(pl.id), c4(TH.text))
                            uiText(nx, ty, pl.utf, argbToRgba(pl.color))
                            uiText(lx, ty, tostring(pl.score), c4(TH.text))
                            uiText(px, ty, tostring(pl.ping), c4(TH.text))
                            row = row + 1
                        end
                    end
                    if row == 0 then
                        local empty = "Нет игроков"
                        local ew = grndTextW(empty)
                        local ey = useChild and 20 or (listY + 20)
                        uiText((W - 16 - ew) / 2, ey, empty, c4(TH.textMuted))
                    end
                    if useChild then
                        if type(im.EndChild) == "function" then pcall(im.EndChild)
                        else pcall(im.End) end
                    end
                end
                grndPopCol(3)
                local hint = "ЛКМ — слежка (/sp)   TAB / ESC — закрыть"
                local hw = grndTextW(hint)
                uiText((W - hw) / 2, H - 20, hint, c4(TH.textMuted))
            end
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            grndPopCol(3)
            grndPopStyle(3)
            return wantCursor
        end
        local function authPanel()
