        local function grndRepSplitLines(s, maxW, maxLines)
            local lines, cur = {}, ""
            for word in tostring(s or ""):gmatch("%S+") do
                local try = (cur == "") and word or (cur .. " " .. word)
                if grndTextW(try) <= maxW or cur == "" then
                    cur = try
                else
                    lines[#lines + 1] = cur
                    cur = word
                    if #lines >= maxLines then break end
                end
            end
            if #lines < maxLines and cur ~= "" then lines[#lines + 1] = cur end
            if #lines >= maxLines then
                local last = lines[maxLines]
                local full = table.concat(lines, " ")
                if #full < #tostring(s or "") then
                    while #last > 1 and grndTextW(last .. "…") > maxW do
                        last = last:sub(1, -2)
                    end
                    lines[maxLines] = last .. "…"
                end
            end
            if #lines == 0 then lines[1] = "" end
            return lines
        end
        local function grndRepIconEye(dl, cx, cy, col)
            local w, h = 8, 4.5
            local seg = 8
            local pts = {}
            for i = 0, seg do
                local t = i / seg
                local x = cx - w + 2 * w * t
                local y = cy - h * math.sin(t * math.pi)
                dl:AddLine(im.ImVec2(pts.x or x, pts.y or y), im.ImVec2(x, y), col, 1.6)
                pts.x, pts.y = x, y
            end
            pts = {}
            for i = 0, seg do
                local t = i / seg
                local x = cx - w + 2 * w * t
                local y = cy + h * math.sin(t * math.pi)
                dl:AddLine(im.ImVec2(pts.x or x, pts.y or y), im.ImVec2(x, y), col, 1.6)
                pts.x, pts.y = x, y
            end
            dl:AddCircleFilled(im.ImVec2(cx, cy), 2.4, col, 12)
        end
        local function grndRepIconRun(dl, cx, cy, col)
            local function L(x1, y1, x2, y2)
                dl:AddLine(im.ImVec2(cx + x1, cy + y1), im.ImVec2(cx + x2, cy + y2), col, 1.7)
            end
            dl:AddCircleFilled(im.ImVec2(cx + 3, cy - 7), 2.0, col, 12)
            L(1, -4, -1, 1)
            L(1, -4, 5, -2)
            L(5, -2, 7, 1)
            L(1, -4, -3, -5)
            L(-3, -5, -6, -3)
            L(-1, 1, 3, 3)
            L(3, 3, 3, 7)
            L(-1, 1, -4, 4)
            L(-4, 4, -7, 3)
        end
        local function grndRepIconGavel(dl, cx, cy, col)
            local function L(x1, y1, x2, y2, th)
                dl:AddLine(im.ImVec2(cx + x1, cy + y1), im.ImVec2(cx + x2, cy + y2), col, th)
            end
            L(-5.5, 1.5, 3.0, -6.0, 3.4)
            L(0.0, 0.0, 5.0, 5.0, 2.0)
            L(-6.5, 7.0, 4.5, 7.0, 1.8)
        end
        GRND_REP.measureW = function(s, scale)
            local canScale = (isFnV(im.SetWindowFontScale))
            local use = (canScale and scale) or 1
            if type(im.CalcTextSize) == "function" then
                if canScale and use ~= 1 then pcall(im.SetWindowFontScale, use) end
                local ok, a = pcall(im.CalcTextSize, tostring(s))
                if canScale and use ~= 1 then pcall(im.SetWindowFontScale, 1) end
                if ok then
                    local ta = type(a)
                    local w = (ta == "table" or ta == "cdata") and tonumber(a.x) or tonumber(a)
                    if w and w > 0 then return w, use end
                end
            end
            return grndTextW(s) * use, use
        end
        GRND_REP.nickOf = function(id, fallback)
            if type(sampGetPlayerNickname) == "function" then
                local ok, nm = pcall(sampGetPlayerNickname, id)
                if ok and type(nm) == "string" and nm ~= "" then
                    return grndToUtf(nm)
                end
            end
            return tostring(fallback or ("ID " .. tostring(id)))
        end
        GRND_REP.labelOf = function(id, nick)
            return tostring(nick) .. "[" .. tostring(id) .. "]"
        end
        GRND_REP.onlineMap = function()
            local now = os.clock()
            local C = GRND_REP.onlineCache
            if C and C.at and (now - C.at) < 1.0 then return C.map end
            local map = {}
            if type(sampIsPlayerConnected) == "function"
                and type(sampGetPlayerNickname) == "function" then
                for id = 0, 1003 do
                    local okC, on = pcall(sampIsPlayerConnected, id)
                    if okC and (on == true or on == 1) then
                        local okN, nm = pcall(sampGetPlayerNickname, id)
                        if okN and type(nm) == "string" and nm ~= "" then
                            map[string.lower(grndToUtf(nm))] = id
                        end
                    end
                end
            end
            GRND_REP.onlineCache = { at = now, map = map }
            return map
        end
        GRND_REP.parseTargetRaw = function(text)
            local s = tostring(text or "")
            local NICK_TOK = "[A-Za-z0-9_%.%-%[%]]+"
            local STOP = {
                admin = true, admins = true, adminka = true, help = true, ping = true,
                afk = true, lag = true, cheat = true, cheater = true, dm = true,
                deathmatch = true, pvp = true, rp = true, gm = true, vip = true,
                http = true, https = true, www = true, com = true, net = true,
                samp = true, grand = true, mob = true, car = true, bike = true,
            }
            local nick, idStr = s:match("(" .. NICK_TOK .. ")%s*%[(%d+)%]")
            if not nick then
                nick, idStr = s:match("(%a[%w_%.%-]+)%s*%((%d+)%)")
            end
            if nick and idStr then
                local nid = tonumber(idStr)
                if nid and nid >= 0 and nid <= 1000 then
                    local byNick = GRND_REP.onlineMap()[string.lower(nick)]
                    if byNick and specConnected(byNick) then
                        return { id = byNick, label = GRND_REP.nickOf(byNick, nick), source = "nick" }
                    end
                    if specConnected(nid) then
                        return { id = nid, label = GRND_REP.nickOf(nid, nick), source = "nick" }
                    end
                    return { id = nil, label = nick, source = "nick" }
                end
            end
            local s2 = s:gsub(NICK_TOK .. "%s*%[%d+%]", " ")
            for num in s2:gmatch("%d+") do
                local nid = tonumber(num)
                if nid and nid >= 0 and nid <= 1000 then
                    if specConnected(nid) then
                        return { id = nid, label = GRND_REP.nickOf(nid), source = "id" }
                    end
                    return { id = nil, label = "ID " .. tostring(nid), source = "id" }
                end
            end
            local cands, seen = {}, {}
            for tok in s:gmatch(NICK_TOK) do
                local t = tok
                if t:sub(1, 1) == "[" and t:sub(-1) == "]" then t = t:sub(2, -2) end
                if #t >= 3 and #t <= 24 and not tonumber(t) then
                    local key = string.lower(t)
                    if not seen[key] and not STOP[key] then
                        seen[key] = true
                        cands[#cands + 1] = t
                    end
                end
            end
            if #cands > 0 then
                local map = GRND_REP.onlineMap()
                table.sort(cands, function(a, b) return #a > #b end)
                for _, t in ipairs(cands) do
                    local base = t:match("^([^%[]+)%[")
                    local variants = (base and base ~= t) and { t, base } or { t }
                    for _, v in ipairs(variants) do
                        local fid = map[string.lower(v)]
                        if fid and specConnected(fid) then
                            return { id = fid, label = GRND_REP.nickOf(fid, v), source = "nick" }
                        end
                    end
                end
                for _, t in ipairs(cands) do
                    if t:find("_", 1, true) then
                        return { id = nil, label = t, source = "nick" }
                    end
                end
                if #cands == 1 and #cands[1] >= 4 then
                    return { id = nil, label = cands[1], source = "nick" }
                end
            end
            return { id = nil, label = nil, source = nil }
        end
        GRND_REP.parseTarget = function(text)
            local key = tostring(text or "")
            local now = os.clock()
            local C = GRND_REP.tgtCache
            if C and C.key == key and (now - C.at) < 0.5 then return C end
            local res = GRND_REP.parseTargetRaw(key)
            res.key, res.at = key, now
            GRND_REP.tgtCache = res
            return res
        end
        local function drawReportWindow()
            if not GRND_REP.open then return false end
            grndRepEnsureBuffer()
            local resX, resY = getScreenResolution()
            local W = 600
            local PAD = 16
            local question = tostring(GRND_REP.question or "текст репорта")
            local qLines = grndRepSplitLines(question, W - PAD * 2 - 24, 2)
            local lineH = 17
            local msgH = 14 + #qLines * lineH
            local yWho, yMsg = 44, 44 + 38
            local tgt = GRND_REP.parseTarget(question)
            local followRow = 0
            if tgt.label then followRow = 30 + 9 end
            local yFollow = yMsg + msgH + 9
            local yInput = yFollow + followRow
            local yChips = yInput + 30 + 9
            local H = yChips + 28 + 12
            local winX = math.floor((resX - W) / 2)
            local winY = math.floor((resY - H) / 2)
            im.SetNextWindowPos(im.ImVec2(winX, winY), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            GRND_REP.winX, GRND_REP.winW = winX, W
            GRND_REP.winY, GRND_REP.winH = winY, H
            local styleN, colorN = 0, 0
            if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 10) then styleN = styleN + 1 end
            if grndPushStyleF(im.StyleVar and im.StyleVar.FrameRounding, 6) then styleN = styleN + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            local flags = wf("NoTitleBar", "NoResize", "NoMove", "NoCollapse",
                "NoScrollbar", "NoScrollWithMouse")
            local wantCursor = false
            local pendingClose = false
            if grndBegin("##grnd_report", flags) then
                wantCursor = true
                local pos = im.GetWindowPos()
                local dl = im.GetWindowDrawList()
                local function at(x, y) return im.ImVec2(pos.x + x, pos.y + y) end
                local function text(x, y, value, col, scale)
                    uiText(x, y, value, col or c4(TH.textHi), scale)
                end
                local function box(x, y, w, h, col, rounding)
                    roundRect(dl, at(x, y), at(x + w, y + h), col, rounding or 3)
                end
                local function frame(x, y, w, h, col, rounding)
                    if dl.AddRect then
                        pcall(dl.AddRect, dl, at(x, y), at(x + w, y + h), col, rounding or 3, 0, 1.0)
                    end
                end
                local function tooltip(label)
                    if type(im.SetTooltip) == "function" then pcall(im.SetTooltip, label) end
                end
                local pid = tostring(GRND_REP.playerId or "?")
                local hasId = pid:match("^%d+$") ~= nil
                box(0, 0, W, H, c32(TH.bg), 10)
                frame(0, 0, W, H, col32(255, 255, 255, 14), 10)
                box(0, 3, W, 31, c32(TH.sidebar), 0)
                box(0, 34, W, 1, c32(TH.line), 0)
                text(PAD, 10, "Репорт", c4(TH.textHi), 1.06)
                local sub
                if GRND_REP.sourceCaption == "catch" then
                    sub = "автоловля · обращение игрока"
                    if GRND_REP.reportCount then sub = sub .. " · репортов: " .. tostring(GRND_REP.reportCount) end
                elseif GRND_REP.dialogId and GRND_REP.dialogId >= 0 then
                    sub = "обращение игрока · окно сервера #" .. tostring(GRND_REP.dialogId)
                elseif GRND_REP.sourceCaption == "hud" then
                    sub = "из оверлея репортов"
                else
                    sub = "обращение игрока"
                end
                text(PAD + 66, 12, sub, c4(TH.textMuted), 0.8)
                im.SetCursorPos(im.ImVec2(W - 38, 8))
                local closeClicked = im.InvisibleButton("##grnd_rep_close", im.ImVec2(26, 22))
                local closeHovered = im.IsItemHovered and im.IsItemHovered() or false
                if closeHovered then box(W - 38, 8, 26, 22, col32(255, 255, 255, 14), 5) end
                text(W - 31, 9, "×", closeHovered and c4(TH.textHi) or c4(TH.textDim), 1.05)
                if closeClicked then pendingClose = true end
                local author = tostring(GRND_REP.author or "Игрок")
                local ini = ""
                for part in author:gmatch("[^_%s%.%-]+") do
                    local ch = part:match("^[%z\1-\127\194-\244][\128-\191]*")
                    if ch then ini = ini .. ch:upper() end
                    if grndUtf8Len(ini) >= 2 then break end
                end
                if ini == "" then ini = "?" end
                box(PAD, yWho, 30, 30, col32(TH.accent[1], TH.accent[2], TH.accent[3], 34), 8)
                frame(PAD, yWho, 30, 30, col32(TH.accent[1], TH.accent[2], TH.accent[3], 90), 8)
                local iniW = grndTextW(ini) * 0.82
                text(PAD + math.max(2, (30 - iniW) / 2), yWho + 7, ini, c4(TH.accent), 0.82)
                text(PAD + 40, yWho - 1, author, c4(TH.textHi), 1.0)
                text(PAD + 40, yWho + 16, "ID " .. pid .. "  ·  игрок", c4(TH.textMuted), 0.78)
                local function iconBtn(id, x, w, label, accent, drawIcon, enabled, lscale)
                    im.SetCursorPos(im.ImVec2(x, yWho + 2))
                    local clicked = im.InvisibleButton(id, im.ImVec2(w, 26))
                    local hovered = im.IsItemHovered and im.IsItemHovered() or false
                    local active = im.IsItemActive and im.IsItemActive() or false
                    local a = accent
                    local bg, bd, fg
                    if not enabled then
                        bg, bd = col32(255, 255, 255, 5), col32(255, 255, 255, 10)
                        fg = col32(TH.textMuted[1], TH.textMuted[2], TH.textMuted[3], 255)
                    elseif active then
                        bg, bd, fg = col32(a[1], a[2], a[3], 70), col32(a[1], a[2], a[3], 220), c32(a)
                    elseif hovered then
                        bg, bd, fg = col32(a[1], a[2], a[3], 40), col32(a[1], a[2], a[3], 160), c32(a)
                    else
                        bg, bd = col32(255, 255, 255, 11), col32(255, 255, 255, 22)
                        fg = c32(TH.text)
                    end
                    box(x, yWho + 2, w, 26, bg, 6)
                    frame(x, yWho + 2, w, 26, bd, 6)
                    drawIcon(dl, pos.x + x + 16, pos.y + yWho + 15, fg)
                    local tcol = enabled and ((hovered or active) and c4(a) or c4(TH.text)) or c4(TH.textMuted)
                    text(x + 30, yWho + 6, label, tcol, lscale or 0.84)
                    return clicked and enabled, hovered
                end
                local wTp = 30 + grndTextW("Телепорт") * 0.84 + 12
                local wSp = 30 + grndTextW("Слежка") * 0.84 + 12
                local xTp = W - PAD - wTp
                local xSp = xTp - 6 - wSp
                local punLabel, punScale = "Наказания игрока", 0.84
                local punW, punDrawScale = 30 + select(1, GRND_REP.measureW(punLabel, punScale)) + 12,
                    select(2, GRND_REP.measureW(punLabel, punScale))
                local punMinX = PAD + 40 + GRND_REP.measureW(author, 1) + 6
                local xPn = xSp - 6 - punW
                if xPn < punMinX then
                    punLabel = "Наказания"
                    local w1, sc1 = GRND_REP.measureW(punLabel, punScale)
                    punW, punDrawScale = 30 + w1 + 12, sc1
                    xPn = xSp - 6 - punW
                end
                if xPn < punMinX then
                    punScale = 0.72
                    local w2, sc2 = GRND_REP.measureW(punLabel, punScale)
                    punW, punDrawScale = 30 + w2 + 12, sc2
                    xPn = xSp - 6 - punW
                end
                if xPn < punMinX then
                    punLabel = ""
                    local w3, sc3 = GRND_REP.measureW(punLabel, 1)
                    punW, punDrawScale = 30 + w3 + 12, sc3
                    xPn = xSp - 6 - punW
                end
                local punShow = true
                if xPn < punMinX then
                    punShow = false
                end
                local wPn = punShow and math.max(42, xSp - 6 - xPn) or 0
                if not punShow then xPn = xSp end
                local pnClick, pnHover = false, false
                if punShow then
                    pnClick, pnHover = iconBtn("##grnd_rep_pun", xPn, wPn, punLabel,
                        TH.accent, grndRepIconGavel, hasId, punDrawScale)
                end
                if pnHover then
                    tooltip(hasId and ("Активные наказания игрока (/getinfo " .. pid .. ")")
                        or "ID игрока не распознан")
                end
                if pnClick then
                    GRND_REP.lastAction = "punish"
                    if QR.punBeginManual(pid, author) then pendingClose = true end
                end
                local spClick, spHover = iconBtn("##grnd_rep_spec", xSp, wSp, "Слежка", TH.accent, grndRepIconEye, hasId)
                local tpClick, tpHover = iconBtn("##grnd_rep_tp", xTp, wTp, "Телепорт", TH.accent2, grndRepIconRun, hasId)
                if spHover then tooltip(hasId and ("Слежка за игроком (/sp " .. pid .. ")") or "ID игрока не распознан") end
                if tpHover then tooltip(hasId and ("Телепорт к игроку ID " .. pid) or "ID игрока не распознан") end
                if spClick then
                    GRND_REP.lastAction = "spectate"
                    grndRepAnswer(pid, "Приветствую, слежу за вами.")
                    if GRND_TAB then GRND_TAB.specId = tonumber(pid) end
                    pendingClose = true
                end
                if tpClick then
                    GRND_REP.lastAction = "teleport"
                    grndRepAnswer(pid, "Приветствую, лечу на помощь!")
                    local cmd = GRND_REP.tpCommand
                    if type(cmd) ~= "string" or cmd == "" then cmd = "/goto %d" end
                    local full = cmd:find("%%d") and string.format(cmd, tonumber(pid)) or (cmd .. " " .. pid)
                    grndRepQueue(full)
                    pendingClose = true
                end
                box(PAD, yMsg, W - PAD * 2, msgH, col32(10, 13, 20, 255), 7)
                frame(PAD, yMsg, W - PAD * 2, msgH, col32(255, 255, 255, 16), 7)
                box(PAD, yMsg + 6, 2, msgH - 12, c32(TH.accent), 1)
                for i, ln in ipairs(qLines) do
                    text(PAD + 12, yMsg + 7 + (i - 1) * lineH, ln, c4(TH.text), 0.92)
                end
                local followClicked, followHover = false, false
                if tgt.label then
                    local fbLabel = "Следить за " .. tostring(tgt.label)
                    local fbX, fbY, fbH = PAD, yFollow, 30
                    local function fbTextW(s, scale) return GRND_REP.measureW(s, scale) end
                    local function fbFit(s, maxW, scale)
                        if fbTextW(s, scale) <= maxW then return s end
                        local out = ""
                        for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
                            if fbTextW(out .. ch .. "…", scale) > maxW then break end
                            out = out .. ch
                        end
                        if out == "" then return "…" end
                        return out .. "…"
                    end
                    local fbPadL, fbPadR = 32, 16
                    local fbMaxW = W - PAD * 2
                    local fbScale = 0.9
                    local fbTw, fbDrawScale = fbTextW(fbLabel, fbScale)
                    local fbW = math.ceil(fbPadL + fbTw + fbPadR)
                    if fbW < 132 then fbW = 132 end
                    if fbW > fbMaxW then
                        local avail = fbMaxW - fbPadL - fbPadR
                        fbScale = fbScale * (avail / math.max(1, fbTw))
                        if fbScale < 0.7 then fbScale = 0.7 end
                        fbTw, fbDrawScale = fbTextW(fbLabel, fbScale)
                        if fbPadL + fbTw + fbPadR > fbMaxW then
                            fbLabel = fbFit(fbLabel, avail, fbDrawScale)
                            fbTw, fbDrawScale = fbTextW(fbLabel, fbScale)
                        end
                        fbW = math.min(fbMaxW, math.ceil(fbPadL + fbTw + fbPadR))
                    end
                    local online = (tgt.id ~= nil) and specConnected(tgt.id)
                    im.SetCursorPos(im.ImVec2(fbX, fbY))
                    followClicked = im.InvisibleButton("##grnd_rep_follow", im.ImVec2(fbW, fbH))
                    followHover = im.IsItemHovered and im.IsItemHovered() or false
                    local fbAct = im.IsItemActive and im.IsItemActive() or false
                    local aR, aG, aB = TH.accent[1], TH.accent[2], TH.accent[3]
                    if not online then aR, aG, aB = TH.textMuted[1], TH.textMuted[2], TH.textMuted[3] end
                    local bg, bd
                    if fbAct then
                        bg, bd = col32(aR, aG, aB, 60), col32(aR, aG, aB, 220)
                    elseif followHover then
                        bg, bd = col32(aR, aG, aB, 34), col32(aR, aG, aB, 160)
                    else
                        bg, bd = col32(aR, aG, aB, 14), col32(aR, aG, aB, 70)
                    end
                    box(fbX, fbY, fbW, fbH, bg, 6)
                    frame(fbX, fbY, fbW, fbH, bd, 6)
                    grndRepIconEye(dl, pos.x + fbX + 16, pos.y + fbY + fbH / 2,
                        c32({ aR, aG, aB }))
                    text(fbX + fbPadL, fbY + math.floor((fbH - 14 * fbDrawScale) / 2), fbLabel,
                        c4(online and TH.textHi or TH.text), fbDrawScale)
                    if followHover then
                        if online then
                            tooltip("Следить за " .. tostring(tgt.label)
                                .. ": ответ игроку и запуск слежки (/sp " .. tostring(tgt.id) .. ")")
                        else
                            tooltip("Игрок не в сети: игроку уйдёт ответ "
                                .. (tgt.source == "nick" and "о проверке никнейма" or "о проверке ID"))
                        end
                    end
                end
                if followClicked then
                    if tgt.id and specConnected(tgt.id) then
                        local msg = "Приветствую, слежу за игроком >> "
                            .. GRND_REP.labelOf(tgt.id, tgt.label)
                        if not grndRepAnswer(pid, msg) then
                            if notify and notify.add then
                                pcall(notify.add, "Не удалось ответить: неизвестен ID в репорте", "warn", 3)
                            end
                        end
                        grndRepQueue("/sp " .. tostring(tgt.id))
                        if type(grndSpecTrackCommand) == "function" then
                            pcall(grndSpecTrackCommand, "/sp " .. tostring(tgt.id))
                        end
                        GRND_REP.lastAction = "follow_" .. tostring(tgt.source or "id")
                    else
                        local msg
                        if tgt.source == "nick" then
                            msg = "Приветствую, возможно, игрок вышел из игры, "
                                .. "или проверьте правильность написания никнейма."
                        else
                            msg = "Приветствую, возможно, игрок вышел из игры, "
                                .. "или проверьте правильность написания ID."
                        end
                        if not grndRepAnswer(pid, msg) then
                            if notify and notify.add then
                                pcall(notify.add, "Не удалось ответить: неизвестен ID в репорте", "warn", 3)
                            end
                        end
                        if notify and notify.add then
                            pcall(notify.add, "Слежка: " .. tostring(tgt.label)
                                .. " — игрок не в сети", "warn", 3)
                        end
                        GRND_REP.lastAction = "follow_offline"
                    end
                    pendingClose = true
                end
                local sendW = 104
                local inputW = W - PAD * 2 - sendW - 6
                local inputColors = 0
                if grndPushCol(im.Col and im.Col.FrameBg, rgba(10, 13, 20, 255)) then inputColors = inputColors + 1 end
                if grndPushCol(im.Col and im.Col.FrameBgHovered, rgba(16, 24, 34, 255)) then inputColors = inputColors + 1 end
                if grndPushCol(im.Col and im.Col.FrameBgActive, rgba(18, 33, 43, 255)) then inputColors = inputColors + 1 end
                if grndPushCol(im.Col and im.Col.Text, rgba(225, 232, 242, 255)) then inputColors = inputColors + 1 end
                if grndPushCol(im.Col and im.Col.Border, rgba(255, 255, 255, 18)) then inputColors = inputColors + 1 end
                local stIn = 0
                if grndPushStyleV2(im.StyleVar and im.StyleVar.FramePadding, 9, 7) then stIn = stIn + 1 end
                if grndPushStyleF(im.StyleVar and im.StyleVar.FrameBorderSize, 1) then stIn = stIn + 1 end
                local prefix = "Приветствую,"
                local prefW = math.floor(grndTextW(prefix)) + 8
                box(PAD, yInput, prefW + 10, 30, col32(10, 13, 20, 255), 6)
                local enterPressed = false
                im.SetCursorPos(im.ImVec2(PAD + prefW + 4, yInput))
                if im.PushItemWidth then pcall(im.PushItemWidth, inputW - prefW - 4) end
                if GRND_REP.answer then
                    local fl = 0
                    if im.InputTextFlags and im.InputTextFlags.EnterReturnsTrue then
                        fl = im.InputTextFlags.EnterReturnsTrue
                    elseif rawget(im, "ImGuiInputTextFlags_EnterReturnsTrue") then
                        fl = rawget(im, "ImGuiInputTextFlags_EnterReturnsTrue")
                    end
                    local okI, r
                    if im.InputTextWithHint then
                        okI, r = pcall(im.InputTextWithHint, "##grnd_rep_answer", "продолжите ответ…", GRND_REP.answer, 256, fl)
                    elseif im.InputText then
                        okI, r = pcall(im.InputText, "##grnd_rep_answer", GRND_REP.answer, 256, fl)
                    end
                    if okI and r == true and fl ~= 0 then enterPressed = true end
                    if not GRND_REP.focused and im.SetKeyboardFocusHere then
                        pcall(im.SetKeyboardFocusHere, -1)
                        GRND_REP.focused = true
                    end
                end
                if im.PopItemWidth then pcall(im.PopItemWidth) end
                grndPopStyle(stIn)
                grndPopCol(inputColors)
                frame(PAD, yInput, inputW, 30, col32(255, 255, 255, 18), 6)
                text(PAD + 9, yInput + 8, prefix, c4(TH.accent), 0.95)
                local function repButton(x, y, w, h, label, id, primary, scale)
                    scale = scale or 0.84
                    im.SetCursorPos(im.ImVec2(x, y))
                    local clicked = im.InvisibleButton(id, im.ImVec2(w, h))
                    local hovered = im.IsItemHovered and im.IsItemHovered() or false
                    local active = im.IsItemActive and im.IsItemActive() or false
                    local bg, fg, bd
                    if primary then
                        bg = (active or hovered) and c32(TH.accent2) or c32(TH.accent)
                        bd = bg
                        fg = c4(TH.bg)
                    else
                        bg = active and col32(TH.accent[1], TH.accent[2], TH.accent[3], 58)
                            or (hovered and col32(TH.accent[1], TH.accent[2], TH.accent[3], 36)
                                or col32(255, 255, 255, 22))
                        bd = hovered and col32(TH.accent[1], TH.accent[2], TH.accent[3], 120)
                            or col32(255, 255, 255, 40)
                        fg = hovered and c4({ 252, 250, 255, 255 })
                            or c4({ 238, 234, 250, 255 })
                    end
                    local r = (h >= 28) and 6 or math.floor(h / 2)
                    box(x, y, w, h, bg, r)
                    frame(x, y, w, h, bd, r)
                    local fs = (GRND_FONT and GRND_FONT.fontSize) or 14
                    local maxW = w - 10
                    local lbl = label
                    local tw = grndTextW(lbl) * scale
                    if tw > maxW then
                        local cut = lbl
                        while grndUtf8Len(cut) > 1 and grndTextW(cut .. "…") * scale > maxW do
                            cut = cut:gsub("[%z\1-\127\194-\244][\128-\191]*$", "")
                        end
                        lbl = cut .. "…"
                        tw = grndTextW(lbl) * scale
                    end
                    local th = fs * scale
                    text(x + math.floor((w - tw) / 2), y + math.floor((h - th) / 2), lbl, fg, scale)
                    return clicked
                end
                if repButton(PAD + inputW + 6, yInput, sendW, 30, "Ответить", "##grnd_rep_answer_btn", true, 1.0) or enterPressed then
                    GRND_REP.lastAction = "Ответить"
                    local txt = ""
                    if GRND_REP.answer then
                        local okS, v = pcall(function()
                            local okF, ffi = pcall(require, "ffi")
                            if okF and ffi then return ffi.string(GRND_REP.answer) end
                            return tostring(GRND_REP.answer)
                        end)
                        if okS and type(v) == "string" then txt = v end
                    end
                    txt = txt:gsub("^%s+", ""):gsub("%s+$", "")
                    if grndLowerUtf(txt):find("^приветствую") then
                        txt = txt:gsub("^[Пп]риветствую[,!]?%s*", "")
                    end
                    if txt ~= "" and hasId then
                        grndRepAnswer(pid, prefix .. " " .. txt)
                        pendingClose = true
                    elseif notify and notify.add then
                        pcall(notify.add, txt == "" and "Введите текст ответа" or "ID игрока не распознан", "warn", 2)
                    end
                end
                local chips = {
                    { "Быстрые ответы", "##grnd_rep_quick_btn" },
                    { "Наказание", "##grnd_rep_punish_btn" },
                    { "Передать в /a", "##grnd_rep_admin_btn" },
                }
                local gap = 6
                local cw = math.floor((W - PAD * 2 - gap * (#chips - 1)) / #chips)
                local ch = 28
                for i = 1, #chips do
                    local cx = PAD + (i - 1) * (cw + gap)
                    if repButton(cx, yChips, cw, ch, chips[i][1], chips[i][2], false, 1.0) then
                        GRND_REP.lastAction = chips[i][1]
                        if i == 1 then
                            if type(_G.GRND_QR) == "table" then
                                if type(_G.GRND_QR.togglePicker) == "function" then
                                    pcall(_G.GRND_QR.togglePicker)
                                elseif type(_G.GRND_QR.openPicker) == "function" then
                                    pcall(_G.GRND_QR.openPicker)
                                end
                            end
                        elseif i == 2 then
                            if type(_G.GRND_QR) == "table" then
                                if type(_G.GRND_QR.togglePunPicker) == "function" then
                                    pcall(_G.GRND_QR.togglePunPicker)
                                elseif type(_G.GRND_QR.openPunPicker) == "function" then
                                    pcall(_G.GRND_QR.openPunPicker)
                                end
                            end
                        elseif i == 3 then
                            local qtxt = tostring(GRND_REP.question or "")
                            qtxt = qtxt:gsub("^%s+", ""):gsub("%s+$", "")
                            if qtxt == "" then qtxt = "без текста" end
                            local nick = tostring(GRND_REP.author or "Игрок")
                            local who = hasId and (nick .. "[" .. pid .. "]") or nick
                            local cmd = "/a " .. grndRepToAnsi("Обращение игрока " .. who .. ": " .. qtxt)
                            if type(sampSendChat) == "function" then
                                pcall(sampSendChat, cmd)
                            else
                                grndRepQueue(cmd)
                            end
                            if hasId then
                                grndRepAnswer(pid, "Приветствую, ваш вопрос/жалобу передал, ожидайте")
                            end
                            if notify and notify.add then
                                pcall(notify.add, "Передал в /a", "ok", 3)
                            end
                            pendingClose = true
                        end
                    end
                end
            end
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            grndPopCol(colorN)
            grndPopStyle(styleN)
            if pendingClose then
                GRND_REP.open = false
                GRND_REP.focused = false
                if type(_G.GRND_QR) == "table" then
                    _G.GRND_QR.pickOpen = false
                    local P = _G.GRND_QR.pun
                    if type(P) == "table" then P.pickOpen = false end
                end
            end
            return wantCursor
        end
        local function drawCatchWindow()
            if not GRND_CATCH.active then return false end
            local resX = getScreenResolution()
            local W, H = 232, 58
            im.SetNextWindowPos(im.ImVec2(resX - W - 24, 120), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(W, H), COND_ALWAYS)
            local styleN, colorN = 0, 0
            if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 10) then styleN = styleN + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            local flags = wf("NoTitleBar", "NoResize", "NoMove", "NoCollapse",
                "NoScrollbar", "NoScrollWithMouse", "NoInputs", "NoFocusOnAppearing", "NoBringToFrontOnFocus")
            if grndBegin("##grnd_catch", flags) then
                local pos = im.GetWindowPos()
                local dl = im.GetWindowDrawList()
                local function at(x, y) return im.ImVec2(pos.x + x, pos.y + y) end
                roundRect(dl, at(0, 0), at(W, H), c32(TH.bg), 10)
                if dl.AddRect then pcall(dl.AddRect, dl, at(0, 0), at(W, H), col32(255, 255, 255, 16), 10, 0, 1.0) end
                local cx, cy, r = 26, 31, 11
                local t = os.clock()
                local a0 = (t * 4.2) % (2 * math.pi)
                local segs = 14
                local sweep = math.pi * 1.55
                if dl.AddCircle then pcall(dl.AddCircle, dl, at(cx, cy), r, col32(255, 255, 255, 22), 24, 2.4) end
                local px, py
                for i = 0, segs do
                    local a = a0 + sweep * (i / segs)
                    local x, y = cx + math.cos(a) * r, cy + math.sin(a) * r
                    if px then
                        local al = math.floor(60 + 195 * (i / segs))
                        dl:AddLine(at(px, py), at(x, y), col32(TH.accent[1], TH.accent[2], TH.accent[3], al), 2.6)
                    end
                    px, py = x, y
                end
                local pulse = 0.5 + 0.5 * math.sin(t * 5)
                dl:AddCircleFilled(at(cx, cy), 2.2 + pulse * 1.2, col32(TH.accent[1], TH.accent[2], TH.accent[3], 120 + pulse * 135), 12)
                uiText(48, 11, "Ловля репорта", c4(TH.textHi), 1.0)
                local el = math.max(0, os.clock() - (GRND_CATCH.startedAt or 0))
                local mm, ss = math.floor(el / 60), math.floor(el % 60)
                local tm = string.format("%02d:%02d", mm, ss)
                uiText(48, 31, "ожидание · " .. tm, c4(TH.textMuted), 0.86)
                uiText(W - 14 - grndTextW(tm), 20, tm, c4(TH.accent), 1.02)
                if (GRND_CATCH.caught or 0) > 0 then
                    local ct = "поймано: " .. tostring(GRND_CATCH.caught)
                    uiText(W - 14 - grndTextW(ct) * 0.78, 40, ct, c4(TH.textDim), 0.78)
                end
            end
            if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            grndPopCol(colorN)
            grndPopStyle(styleN)
            if fontPushed then pcall(im.PopFont) end
            if ioObj then pcall(function() ioObj.FontGlobalScale = ioOld end) end
            return false
        end
        function grndSrvCardDraw(FW, FH, prefix, nick, cmdText, remaining, accent)
            local pos = im.GetWindowPos()
            local dl = im.GetWindowDrawList()
            local function at(x, y) return im.ImVec2(pos.x + x, pos.y + y) end
            roundRect(dl, at(0, 0), at(FW, FH), col32(0, 0, 0, 200), 8)
            local WHITE = col32(245, 248, 255, 255)
            local ac = type(accent) == "table" and accent or { 63, 209, 145 }
            local GREEN = col32(ac[1], ac[2], ac[3], 255)
            local BAR = col32(math.floor(ac[1] * 0.4), math.floor(ac[2] * 0.4), math.floor(ac[3] * 0.4), 205)
            local RED = col32(235, 70, 70, 255)
            local GRAY = col32(170, 176, 188, 230)
            if nick and nick ~= "" then
                uiText(12, 7, prefix, WHITE, 0.92)
                uiText(12 + drawnWb(prefix, 0.92), 7, nick, GREEN, 0.92)
            else
                uiText(12, 7, prefix, WHITE, 0.92)
            end
            roundRect(dl, at(10, 30), at(FW - 10, 52), BAR, 5)
            local ct = tostring(cmdText or "")
            local clipped = false
            while #ct > 0 and drawnWb(ct, 0.90) > FW - 36 do
                local before = #ct
                ct = grndFormUtf8Cut(ct, before - 1)
                if #ct >= before then break end
                clipped = true
            end
            if clipped then ct = (ct:gsub("%s+$", "")) .. "…" end
            uiText(16, 34, ct, WHITE, 0.90)
            local parts = { { "Принять форму: ", WHITE }, { "Y", GREEN }, { " | Для отказа: ", WHITE }, { "N", RED } }
            local lx = 12
            for _, part in ipairs(parts) do
                uiText(lx, 58, part[1], part[2], 0.90)
                lx = lx + drawnWb(part[1], 0.90)
            end
            uiText(12, 77, "Окно автоматически пропадет через " .. tostring(math.ceil(remaining or 0)) .. " секунд",
                GRAY, 0.78)
        end
        function drawFormPopup()
            if not _G.GRND_FORMS or not _G.GRND_FORMS.active then return false end
            local form = _G.GRND_FORMS.active
            local now = os.clock()
            if form.showAt and now < form.showAt then return false end
            local timeout = tonumber(_G.GRND_FORM_POPUP_TIMEOUT_SEC) or 5.0
            local openedAt = tonumber(form.openedAt) or tonumber(form.time) or now
            local elapsed = math.max(0, now - openedAt)
            local remaining = math.max(0, timeout - elapsed)
            if elapsed >= timeout then
                pcall(notify.add, "Вы не успели принять Админ форму", "warn", 4)
                if type(_G.grndFormsResolve) == "function" then
                    pcall(_G.grndFormsResolve, "timeout")
                end
                return false
            end
            local wantAccept = false
            local wantReject = false
            local resX, resY = getScreenResolution()
            local L = _G.GRND_FORM_UI_LAYOUT or { w = 400, h = 96 }
            local FW, FH = L.w or 400, L.h or 96
            local fx, fy = grndFormUiPos(resX, resY, FW, FH)
            local U = _G.GRND_FORM_UI or {}
            local R = grndFormUiRects(fx, fy)
            if type(R) == "table" then
                fx, fy = grndFormUiDrag(form, fx, fy, FW, FH, resX, resY, { x = fx, y = fy, w = FW, h = FH }, nil)
            end
            if type(_G.grndFormsKeyTick) == "function" then pcall(_G.grndFormsKeyTick) end
            grndFormUiClick(fx, fy)
            if (not _G.GRND_FORMS) or (_G.GRND_FORMS.active ~= form) then
                return false
            end
            local wantAccept = false
            local wantReject = false
            im.SetNextWindowPos(im.ImVec2(fx, fy), COND_ALWAYS)
            im.SetNextWindowSize(im.ImVec2(FW, FH), COND_ALWAYS)
            if im.SetNextWindowFocus then pcall(im.SetNextWindowFocus) end
            local styleN, colorN = 0, 0
            if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 8) then styleN = styleN + 1 end
            if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then styleN = styleN + 1 end
            if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then colorN = colorN + 1 end
            local flagsF = wf("NoTitleBar", "NoResize", "NoMove", "NoCollapse", "NoScrollbar", "NoScrollWithMouse")
            local drawn = false
            if grndBegin("##grnd_form_popup", flagsF) then
                drawn = true
                if im.BringWindowToDisplayFront then pcall(im.BringWindowToDisplayFront, im.GetCurrentWindow()) end
                grndSrvCardDraw(FW, FH, "Форма от Админа ", grndUtf8Text(form.adminNick),
                    grndUtf8Text(form.cmd), remaining, TH.accent)
                if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            end
            grndPopCol(colorN)
            grndPopStyle(styleN)
            if wantAccept then
                if type(_G.grndFormsResolve) == "function" then
                    pcall(_G.grndFormsResolve, "accept")
                end
            elseif wantReject then
                if type(_G.grndFormsResolve) == "function" then
                    pcall(_G.grndFormsResolve, "reject")
                end
            end
            return drawn
        end
        function drawGnewsPopup()
