            local remaining = math.max(0, timeout - elapsed)
            if elapsed >= timeout then
                grndGnewsClose()
                pcall(notify.add, "Вы не успели принять гос. волну", "warn", 4)
                return false
            end
            local wantAccept, wantReject = false, false
