                grndSrvCardDraw(FW, FH, "Форма на Гос. Новости", nil, "Заявка на гос. новости", remaining, TH.accent)
                if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
            end
            grndPopCol(colorN)
