            local flags = wf("NoTitleBar", "NoResize", "NoMove", "NoCollapse",
                "NoScrollbar", "NoScrollWithMouse", "NoBringToFrontOnFocus")
            local drawn = false
            local wantClose = false
            if grndBegin("##grnd_stats_popup", flags) then
                drawn = true
                if P.frontPending then
