        end
        local function getPlayerAmmo(id, slot)
            local SN = _G.grndSpecNative
            local ped = SN and SN.pedOf and SN.pedOf(id) or nil
            if not ped or type(getCharWeaponInSlot) ~= "function" then return nil end
            local ok, w, ammo = pcall(getCharWeaponInSlot, ped, slot)
            if ok and type(w) == "number" and w > 0 and type(ammo) == "number" then
                return ammo
            end
            return nil
        end
        local function getInterior(id) return nil end
        local function getVW(id) return nil end
        local function setPlayerPos(id, x, y, z)
            if type(_G.setPlayerPos) == "function" then
                local ok, r = pcall(_G.setPlayerPos, id, x, y, z)
                return ok and (r and true or true) or false
            end
            return false
        end
        function reconCopyNickname(text)
            local okF, ffi = pcall(require, "ffi")
            if not okF or not ffi then return false end
            local ansi = tostring(text or "")
            if type(grndToAnsi) == "function" then
                local okA, out = pcall(grndToAnsi, ansi)
                if okA and type(out) == "string" then ansi = out end
            end
            if ansi == "" then return false end
            pcall(function()
                ffi.cdef[[
                    int OpenClipboard(void* hWndNewOwner);
                    int EmptyClipboard(void);
                    void* GlobalAlloc(unsigned int uFlags, size_t dwBytes);
                    void* GlobalLock(void* hMem);
                    int GlobalUnlock(void* hMem);
                    void* SetClipboardData(unsigned int uFormat, void* hMem);
                    int CloseClipboard(void);
                    void* GlobalFree(void* hMem);
                ]]
            end)
            local ok, result = pcall(function()
                if ffi.C.OpenClipboard(nil) == 0 then return false end
                ffi.C.EmptyClipboard()
                local h = ffi.C.GlobalAlloc(0x0002, #ansi + 1)
                if h == nil then ffi.C.CloseClipboard(); return false end
                local p = ffi.C.GlobalLock(h)
                if p == nil then ffi.C.GlobalFree(h); ffi.C.CloseClipboard(); return false end
                ffi.copy(p, ansi, #ansi)
                ffi.cast("unsigned char*", p)[#ansi] = 0
                ffi.C.GlobalUnlock(h)
                if ffi.C.SetClipboardData(1, h) == nil then
                    ffi.C.GlobalFree(h)
                    ffi.C.CloseClipboard()
                    return false
                end
                ffi.C.CloseClipboard()
                return true
            end)
            return ok and result == true
        end
        function grndReconQuickPunishCommand(kind, targetId, timeRaw, reasonRaw, timeRequired)
            local id = tostring(kind or ""):upper()
            if id ~= "JAIL" and id ~= "BAN" and id ~= "KICK"
               and id ~= "MUTE" and id ~= "SKICK" and id ~= "WARN" then
                return nil, "Неизвестный тип наказания"
            end
            local target = tonumber(targetId)
            if not target or target < 0 or target > 9999 or target ~= math.floor(target) then
                return nil, "Некорректный ID игрока"
            end
            if id == "SKICK" then
                return "/skick " .. tostring(math.floor(target))
            end
            local expectsTime = id == "JAIL" or id == "BAN" or id == "MUTE"
            if (timeRequired == true) ~= expectsTime then
                return nil, "Схема времени для наказания настроена неверно"
            end
            local reason = tostring(reasonRaw or "")
                :gsub("[%c|{}<>~]", " "):gsub("%s+", " ")
                :gsub("^%s+", ""):gsub("%s+$", "")
            local chars = {}
            for ch in reason:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
                chars[#chars + 1] = ch
            end
            if #chars > 24 then reason = table.concat(chars, "", 1, 24) end
            if reason == "" then return nil, "Укажите причину" end
            if timeRequired then
                local rawTime = tostring(timeRaw or ""):gsub("^%s+", ""):gsub("%s+$", "")
                if not rawTime:match("^%d+$") then return nil, "Время задаётся целым числом" end
                local mins = tonumber(rawTime)
                if not mins or mins < 1 or mins > 9999 then
                    return nil, "Время должно быть от 1 до 9999"
                end
                return "/" .. id:lower() .. " " .. tostring(math.floor(target))
                    .. " " .. tostring(math.floor(mins)) .. " " .. reason
            end
            return "/" .. id:lower() .. " " .. tostring(math.floor(target)) .. " " .. reason
        end
        function grndReconQuickPunishOpen(RC, kind, targetId, targetNick)
            local id = tostring(kind or ""):upper()
            local target = tonumber(targetId)
            local P = _G.GRND_PUN
            if not RC or not target or not P then return false end
            if not P.loaded and type(P.load) == "function" then pcall(P.load) end
            local item = type(P.entry) == "function" and P.entry(id) or nil
            if not item then
                for i = 1, #(P.list or {}) do
                    if tostring(P.list[i].id or ""):upper() == id then item = P.list[i]; break end
                end
            end
            if not item then
                if notify and notify.add then pcall(notify.add, id .. " не настроен!", "warn", 2.5) end
                return false
            end
            local reasons, times = {}, {}
            local data = (type(P.data) == "table" and P.data[id]) or {}
            if id ~= "SKICK" then
                if item.locked then
                    if notify and notify.add then pcall(notify.add, id .. " не настроен!", "warn", 2.5) end
                    return false
                end
                for _, value in ipairs(type(data.reasons) == "table" and data.reasons or {}) do
                    local text = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
                    if text ~= "" then reasons[#reasons + 1] = text end
                end
                if item.time then
                    for _, value in ipairs(type(data.times) == "table" and data.times or {}) do
                        local n = tonumber(value)
                        if n and n >= 1 and n <= 9999 then times[#times + 1] = math.floor(n) end
                    end
                end
                if #reasons == 0 or (item.time and #times == 0) then
                    if notify and notify.add then pcall(notify.add, id .. " не настроен!", "warn", 2.5) end
                    return false
                end
            end
            RC.punQuick = {
                kind = id, targetId = math.floor(target), targetNick = tostring(targetNick or ("ID " .. tostring(target))),
                timeRequired = id ~= "SKICK" and item.time == true, unit = item.unit,
                reasons = reasons, times = times,
                reasonIndex = (#reasons > 0) and 1 or nil, timeIndex = (#times > 0) and 1 or nil,
                reason = "", time = "", focusPending = true,
            }
            RC.actionsWinOpen = false
            return true
        end
        function grndReconQuickPunishDraw(RC, im, resX, resY, flags, condAlways, theme, col32, rgba, uiText, c4)
            local Q = RC and RC.punQuick
            if not Q or not im then return end
            local currentId = tonumber(RC.id) or (GRND_SPEC and tonumber(GRND_SPEC.id))
            if currentId and currentId ~= tonumber(Q.targetId) then
                RC.punQuick = nil
                return
            end
            local function bufInit(key, cap, text)
                if Q[key] then return Q[key] end
                local okB, buf = pcall(function()
                    if not im.new or not im.new.char then return nil end
                    return im.new.char[cap]()
                end)
                if not okB or not buf then return nil end
                local okF, ffi = pcall(require, "ffi")
                local initial = tostring(text or "")
                if okF and ffi then pcall(ffi.copy, buf, initial, math.min(#initial, cap - 1)) end
                Q[key], Q[key .. "Cap"] = buf, cap
                return buf
            end
            local function bufSet(buf, cap, text)
                if not buf then return end
                local okF, ffi = pcall(require, "ffi")
                if not okF or not ffi then return end
                local value = tostring(text or "")
                pcall(ffi.fill, buf, cap, 0)
                pcall(ffi.copy, buf, value, math.min(#value, cap - 1))
            end
            local function bufRead(buf)
                if not buf then return "" end
                local okF, ffi = pcall(require, "ffi")
                if not okF or not ffi then return "" end
                local ok, value = pcall(ffi.string, buf)
                return ok and tostring(value or "") or ""
            end
            local function toast(text, level)
                if notify and notify.add then pcall(notify.add, text, level or "warn", 2.8) end
            end
            local function enterPressed()
                if type(im.IsWindowFocused) == "function" then
                    local okF, focused = pcall(im.IsWindowFocused)
                    if okF and not focused then return false end
                end
                if type(im.IsKeyPressed) == "function" then
                    local key = (im.Key and im.Key.Enter) or 13
                    local okK, pressed = pcall(im.IsKeyPressed, key)
                    if okK and pressed then return true end
                    if key ~= 13 then
                        local okK2, pressed2 = pcall(im.IsKeyPressed, 13)
                        if okK2 and pressed2 then return true end
                    end
                end
                if type(im.GetIO) == "function" then
                    local okIO, ioState = pcall(im.GetIO)
                    if okIO and ioState and ioState.KeysDown then
                        local okKey, down = pcall(function() return ioState.KeysDown[13] end)
                        if okKey and down then return true end
                    end
                end
                return false
            end
            local function sendQuick()
                local timeValue, reasonValue = bufRead(Q.timeBuf), bufRead(Q.reasonBuf)
                if timeValue:gsub("%s+", "") == "" and Q.timeIndex then
                    timeValue = tostring(Q.times[Q.timeIndex] or "")
                end
                if reasonValue:gsub("%s+", "") == "" and Q.reasonIndex then
                    reasonValue = tostring(Q.reasons[Q.reasonIndex] or "")
                end
                local command, err = grndReconQuickPunishCommand(Q.kind, Q.targetId,
                    timeValue, reasonValue, Q.timeRequired)
                if not command then toast(err or "Проверьте параметры наказания"); return false end
                if type(sampSendChat) ~= "function" then
                    toast("Не удалось отправить команду")
                    return false
                end
                local okSend, result = pcall(sampSendChat, command)
                if not okSend or result == false then
                    toast("Не удалось отправить команду")
                    return false
                end
                if notify and notify.add then pcall(notify.add, "Команда " .. command .. " отправлена", "ok", 2.2) end
                RC.punQuick = nil
                return true
            end
            local timed = Q.timeRequired == true
            local hasReason = Q.kind ~= "SKICK"
            local width = math.min(480, math.max(360, resX - 24))
            local height = timed and 236 or (hasReason and 232 or 170)
            height = math.min(height, math.max(160, resY - 24))
            if not Q.positioned and im.SetNextWindowPos then
                local appearing = (im.Cond and im.Cond.Appearing) or condAlways or 0
                pcall(im.SetNextWindowPos, im.ImVec2((resX - width) / 2,
                    math.max(8, (resY - height) / 2)), appearing)
                Q.positioned = true
            end
            if im.SetNextWindowSize then pcall(im.SetNextWindowSize, im.ImVec2(width, height), condAlways or 0) end
            if Q.focusPending and im.SetNextWindowFocus then pcall(im.SetNextWindowFocus); Q.focusPending = false end

            local pushedColors, pushedStyles = 0, 0
            local function themeVec(r, g, b, a)
                if type(im.ImVec4) == "function" then
                    local ok, value = pcall(im.ImVec4, (tonumber(r) or 0) / 255,
                        (tonumber(g) or 0) / 255, (tonumber(b) or 0) / 255,
                        (tonumber(a) or 255) / 255)
                    if ok and value then return value end
                end
                return rgba(r, g, b, a)
            end
            local function pushColor(name, color)
                local slot = im.Col and im.Col[name]
                if slot == nil or color == nil or type(im.PushStyleColor) ~= "function" then return end
                if pcall(im.PushStyleColor, slot, color) then pushedColors = pushedColors + 1 end
            end
            local function pushStyle(name, value, vector)
                local slot = im.StyleVar and im.StyleVar[name]
                if slot == nil then return end
                local ok = false
                if vector and im.PushStyleVarVec2 then ok = pcall(im.PushStyleVarVec2, slot, value) end
                if not ok and not vector and im.PushStyleVarFloat then ok = pcall(im.PushStyleVarFloat, slot, value) end
                if not ok then ok = pcall(im.PushStyleVar, slot, value) end
                if ok then pushedStyles = pushedStyles + 1 end
            end
            local bg = theme and theme.bg or { 20, 18, 26, 255 }
            local panel = theme and theme.sidebar or bg
            local accent = theme and theme.accent or { 164, 112, 224, 255 }
            local accent2 = theme and theme.accent2 or accent
            local text = theme and theme.text or { 220, 216, 230, 255 }
            local textHi = theme and theme.textHi or { 246, 242, 250, 255 }
            local muted = theme and theme.textMuted or { 164, 158, 180, 255 }
            local line = theme and theme.line or { 255, 255, 255, 28 }
            local function colorLuminance(rgb)
                local function channel(value)
                    local v = (tonumber(value) or 0) / 255
                    if v <= 0.04045 then return v / 12.92 end
                    return ((v + 0.055) / 1.055) ^ 2.4
                end
                return 0.2126 * channel(rgb[1]) + 0.7152 * channel(rgb[2])
                    + 0.0722 * channel(rgb[3])
            end
            local function readableInk(background, preferred)
                local baseLum = colorLuminance(background)
                local candidates = { preferred or textHi, {255, 255, 255, 255}, {20, 20, 24, 255} }
                local best, bestRatio = candidates[1], 0
                for _, candidate in ipairs(candidates) do
                    local inkLum = colorLuminance(candidate)
                    local high, low = math.max(inkLum, baseLum), math.min(inkLum, baseLum)
                    local ratio = (high + 0.05) / (low + 0.05)
                    if ratio > bestRatio then best, bestRatio = candidate, ratio end
                end
                return best
            end
            local fieldInk = readableInk(bg, textHi)
            local hintInk = readableInk(bg, muted)
            pushStyle("WindowPadding", im.ImVec2(0, 0), true)
            pushStyle("WindowRounding", 11, false)
            pushStyle("FrameRounding", 5, false)
            pushStyle("FrameBorderSize", 1, false)
            pushStyle("ItemSpacing", im.ImVec2(6, 4), true)
            pushColor("WindowBg", themeVec(panel[1], panel[2], panel[3], 248))
            pushColor("ChildBg", themeVec(bg[1], bg[2], bg[3], 235))
            pushColor("Border", themeVec(line[1], line[2], line[3], line[4] or 255))
            pushColor("Text", themeVec(text[1], text[2], text[3], 255))
            pushColor("FrameBg", themeVec(bg[1], bg[2], bg[3], 255))
            pushColor("FrameBgHovered", themeVec(panel[1], panel[2], panel[3], 255))
            pushColor("FrameBgActive", themeVec(accent[1], accent[2], accent[3], 42))
            pushColor("TextDisabled", themeVec(muted[1], muted[2], muted[3], 255))
            pushColor("TextSelectedBg", themeVec(accent[1], accent[2], accent[3], 110))

            local title = "##grnd_recon_quick_punish"
            local okBegin, visible = pcall(im.Begin, title, nil, flags or 0)
            if not okBegin then
                if pushedColors > 0 then pcall(im.PopStyleColor, pushedColors) end
                if pushedStyles > 0 then pcall(im.PopStyleVar, pushedStyles) end
                return
            end
            local submit = false
            -- Some Lua ImGui bindings return nil (rather than true) for a visible Begin window.
            if visible ~= false then
                local dl = im.GetWindowDrawList and im.GetWindowDrawList() or nil
                local pos = im.GetWindowPos and im.GetWindowPos() or im.ImVec2(0, 0)
                local function centered(value, y, color, scale)
                    local w = 0
                    if im.CalcTextSize then
                        local ok, size = pcall(im.CalcTextSize, tostring(value))
                        if ok then
                            if type(size) == "table" or type(size) == "cdata" then w = tonumber(size.x) or 0
                            else w = tonumber(size) or 0 end
                        end
                    end
                    uiText(math.max(0, (width - w) / 2), y, value, color, scale or 1)
                end
                local function paintRow(kind, index, label, rowY, rowW, selected, hovered)
                    local x, y = 0, rowY
                    local clicked = false
                    im.SetCursorPos(im.ImVec2(x, y))
                    clicked = im.InvisibleButton("##grnd_qpun_" .. kind .. "_" .. tostring(index),
                        im.ImVec2(rowW, 21))
                    local hot = (im.IsItemHovered and im.IsItemHovered()) or hovered
                    if dl and dl.AddRectFilled then
                        local color = selected and col32(accent[1], accent[2], accent[3], 46)
                            or (hot and col32(255, 255, 255, 16) or col32(255, 255, 255, 0))
                        pcall(dl.AddRectFilled, dl,
                            im.ImVec2(pos.x + x, pos.y + y),
                            im.ImVec2(pos.x + x + rowW, pos.y + y + 21), color, 4)
                    end
                    if dl then
                        local center = im.ImVec2(pos.x + 10, pos.y + y + 10.5)
                        local ring = selected and col32(accent[1], accent[2], accent[3], 255)
                            or col32(muted[1], muted[2], muted[3], 230)
                        if selected and dl.AddCircleFilled then
                            pcall(dl.AddCircleFilled, dl, center, 5, ring, 18)
                        elseif dl.AddCircle then
                            pcall(dl.AddCircle, dl, center, 5, ring, 18, 1.3)
                        end
                    end
                    uiText(21, y + 3, label, selected and c4(textHi) or c4(text), 0.88)
                    return clicked
                end
                local function beginChild(id, childW, childH)
                    local ok, shown = pcall(im.BeginChild, id, im.ImVec2(childW, childH), false, 0)
                    return ok, shown
                end
                centered("Быстрые наказания", 7, c4(textHi), 1.0)
                if dl and dl.AddRectFilled then
                    pcall(dl.AddRectFilled, dl, im.ImVec2(pos.x + 12, pos.y + 31),
                        im.ImVec2(pos.x + width - 12, pos.y + 32),
                        col32(accent[1], accent[2], accent[3], 180))
                end
                local nick = tostring(Q.targetNick or "")
                if nick:match("^ID %d+$") then nick = "" end
                local targetLine = Q.kind .. ": " .. (nick ~= "" and (nick .. "[" .. tostring(Q.targetId) .. "]")
                    or ("ID[" .. tostring(Q.targetId) .. "]"))
                centered(targetLine, 37, c4(textHi), 0.94)

                local pad, top = 11, 64
                local contentW = width - pad * 2
                local reasonW = timed and math.floor((contentW - 8) * 0.64) or contentW
                local timeW = contentW - reasonW - (timed and 8 or 0)
                local listH = 86
                if hasReason then
                    local reasonChildX = pad
                    if dl and dl.AddRectFilled then
                        pcall(dl.AddRectFilled, dl, im.ImVec2(pos.x + reasonChildX, pos.y + top),
                            im.ImVec2(pos.x + reasonChildX + reasonW, pos.y + top + listH),
                            col32(bg[1], bg[2], bg[3], 205), 5)
                    end
                    im.SetCursorPos(im.ImVec2(reasonChildX, top))
                    local reasonOk, reasonVisible = beginChild("##grnd_rc_pun_reasons", reasonW, listH)
                    if reasonOk then
                        if reasonVisible ~= false then
                            local childPos = im.GetWindowPos()
                            local parentPos, parentDl = pos, dl
                            pos = childPos or parentPos
                            if im.GetWindowDrawList then dl = im.GetWindowDrawList() or parentDl end
                            for i = 1, #Q.reasons do
                                local label = tostring(Q.reasons[i])
                                local reasonInput = bufRead(Q.reasonBuf)
                                local selected = reasonInput == label or (reasonInput == "" and Q.reasonIndex == i)
                                if paintRow("reason", i, label, (i - 1) * 22, reasonW - 4, selected) then
                                    Q.reasonIndex, Q.reason = i, ""
                                    bufSet(Q.reasonBuf, Q.reasonBufCap, "")
                                end
                            end
                            pos, dl = parentPos, parentDl
                        end
                        pcall(im.EndChild)
                    end
                end
                if timed then
                    local timeX = pad + reasonW + 8
                    if dl and dl.AddRectFilled then
                        pcall(dl.AddRectFilled, dl, im.ImVec2(pos.x + timeX, pos.y + top),
                            im.ImVec2(pos.x + timeX + timeW, pos.y + top + listH),
                            col32(bg[1], bg[2], bg[3], 205), 5)
                    end
                    im.SetCursorPos(im.ImVec2(timeX, top))
                    local timeOk, timeVisible = beginChild("##grnd_rc_pun_times", timeW, listH)
                    if timeOk then
                        if timeVisible ~= false then
                            local childPos = im.GetWindowPos()
                            local parentPos, parentDl = pos, dl
                            pos = childPos or parentPos
                            if im.GetWindowDrawList then dl = im.GetWindowDrawList() or parentDl end
                            for i = 1, #Q.times do
                                local value = tostring(Q.times[i])
                                local unit = tostring(Q.unit or (Q.kind == "BAN" and "д" or "мин"))
                                local label = value .. " " .. unit .. "."
                                local timeInput = bufRead(Q.timeBuf)
                                local selected = timeInput == value or (timeInput == "" and Q.timeIndex == i)
                                if paintRow("time", i, label, (i - 1) * 22, timeW - 4, selected) then
                                    Q.timeIndex, Q.time = i, ""
                                    bufSet(Q.timeBuf, Q.timeBufCap, "")
                                end
                            end
                            pos, dl = parentPos, parentDl
                        end
                        pcall(im.EndChild)
                    end
                end

                Q.reasonBuf = hasReason and bufInit("reasonBuf", 128, Q.reason) or nil
                if timed then Q.timeBuf = bufInit("timeBuf", 24, Q.time) end
                local fieldY = top + listH + 7
                local inputFlags = 0
                pcall(function()
                    inputFlags = (im.InputTextFlags and im.InputTextFlags.EnterReturnsTrue)
                        or rawget(im, "ImGuiInputTextFlags_EnterReturnsTrue") or 0
                end)
                local function drawInput(id, hint, buffer, cap, x, y, w)
                    if not buffer or type(im.InputText) ~= "function" then return false end
                    im.SetCursorPos(im.ImVec2(x, y))
                    local fieldColorBase = pushedColors
                    pushColor("FrameBg", themeVec(bg[1], bg[2], bg[3], 255))
                    pushColor("FrameBgHovered", themeVec(panel[1], panel[2], panel[3], 255))
                    pushColor("FrameBgActive", themeVec(accent[1], accent[2], accent[3], 64))
                    pushColor("Text", themeVec(fieldInk[1], fieldInk[2], fieldInk[3], 255))
                    pushColor("TextDisabled", themeVec(hintInk[1], hintInk[2], hintInk[3], 220))
                    pushColor("TextSelectedBg", themeVec(accent[1], accent[2], accent[3], 110))
                    pushColor("InputTextCursor", themeVec(fieldInk[1], fieldInk[2], fieldInk[3], 255))
                    pushColor("Border", themeVec(line[1], line[2], line[3], line[4] or 255))
                    if im.PushItemWidth then pcall(im.PushItemWidth, w) end
                    local okInput, result
                    if im.InputTextWithHint then
                        okInput, result = pcall(im.InputTextWithHint, id, hint, buffer, cap, inputFlags)
                    end
                    if not okInput and type(im.InputText) == "function" then
                        okInput, result = pcall(im.InputText, id, buffer, cap, inputFlags)
                    end
                    if im.PopItemWidth then pcall(im.PopItemWidth) end
                    local fieldColorCount = pushedColors - fieldColorBase
                    if fieldColorCount > 0 then
                        pcall(im.PopStyleColor, fieldColorCount)
                        pushedColors = pushedColors - fieldColorCount
                    end
                    return okInput and result == true
                end
                if hasReason then
                    local okReason, enterReason = pcall(drawInput, "##grnd_rc_pun_reason", "Причина",
                        Q.reasonBuf, Q.reasonBufCap or 128, pad, fieldY, timed and reasonW or contentW)
                    Q.reason = bufRead(Q.reasonBuf)
                    submit = submit or (okReason and enterReason == true)
                end
                if timed then
                    local timeX = pad + reasonW + 8
                    local okTime, enterTime = pcall(drawInput, "##grnd_rc_pun_time", "Время",
                        Q.timeBuf, Q.timeBufCap or 24, timeX, fieldY, timeW)
                    Q.time = bufRead(Q.timeBuf)
                    submit = submit or (okTime and enterTime == true)
                end
                if not hasReason then
                    centered("Команда: /skick " .. tostring(Q.targetId), 78, c4(text), 0.9)
                end
                local buttonY = hasReason and (fieldY + 31) or (height - 39)
                local buttonGap = 8
                local buttonW = (contentW - buttonGap) / 2
                Q.buttonHover = Q.buttonHover or {}
                local buttonNow = os.clock()
                local buttonDt = math.max(0, math.min(0.06,
                    buttonNow - (tonumber(Q.buttonAnimAt) or buttonNow)))
                Q.buttonAnimAt = buttonNow
                local function themedButton(id, label, x, y, w, h)
                    im.SetCursorPos(im.ImVec2(x, y))
                    local clicked = im.InvisibleButton(id, im.ImVec2(w, h))
                    local hovered = im.IsItemHovered and im.IsItemHovered() or false
                    local active = im.IsItemActive and im.IsItemActive() or false
                    local state = tonumber(Q.buttonHover[id]) or 0
                    local target = hovered and 1 or 0
                    state = state + (target - state) * math.min(1, buttonDt * 14)
                    Q.buttonHover[id] = state
                    local pulse = active and (0.5 + 0.5 * math.sin(buttonNow * 18)) or 0
                    local function mix(a, b, t) return a + (b - a) * t end
                    local r = mix(accent[1], accent2[1], state)
                    local g = mix(accent[2], accent2[2], state)
                    local b = mix(accent[3], accent2[3], state)
                    if active then
                        local lift = 0.10 + 0.12 * pulse
                        r, g, b = mix(r, 255, lift), mix(g, 255, lift), mix(b, 255, lift)
                    end
                    local radius = 5 + state * 0.8
                    local fillAlpha = 238 + state * 14 + pulse * 3
                    if dl and dl.AddRectFilled then
                        pcall(dl.AddRectFilled, dl, im.ImVec2(pos.x + x, pos.y + y),
                            im.ImVec2(pos.x + x + w, pos.y + y + h),
                            col32(r, g, b, fillAlpha), radius)
                    end
                    if dl and dl.AddRect then
                        local edge = (hovered or active) and accent2 or line
                        local edgeAlpha = math.min(255, (edge[4] or 255) + state * 45 + pulse * 25)
                        pcall(dl.AddRect, dl, im.ImVec2(pos.x + x + 0.5, pos.y + y + 0.5),
                            im.ImVec2(pos.x + x + w - 0.5, pos.y + y + h - 0.5),
                            col32(edge[1], edge[2], edge[3], edgeAlpha), radius, 0, 1)
                    end
                    if state > 0.02 and dl and dl.AddLine then
                        pcall(dl.AddLine, dl, im.ImVec2(pos.x + x + 8, pos.y + y + 2),
                            im.ImVec2(pos.x + x + w - 8, pos.y + y + 2),
                            col32(255, 255, 255, state * 95), 1.0)
                    end
                    local labelW = 0
                    if im.CalcTextSize then
                        local okSize, size = pcall(im.CalcTextSize, label)
                        if okSize and size then labelW = tonumber(size.x) or tonumber(size) or 0 end
                    end
                    local textInk = readableInk({r, g, b, 255}, textHi)
                    uiText(x + math.max(0, (w - labelW) / 2), y + 5,
                        label, c4(textInk), 0.98 + state * 0.04)
                    return clicked
                end
                local okSubmitButton, submitClicked = pcall(themedButton,
                    "##grnd_rc_pun_submit", "Наказать", pad, buttonY, buttonW, 28)
                if okSubmitButton and submitClicked then submit = true end
                local okCancelButton, cancelClicked = pcall(themedButton,
                    "##grnd_rc_pun_cancel", "Отменить", pad + buttonW + buttonGap, buttonY, buttonW, 28)
                if okCancelButton and cancelClicked then RC.punQuick = nil end
                if enterPressed() then submit = true end
            end
            pcall(im.End)
            if pushedColors > 0 then pcall(im.PopStyleColor, pushedColors) end
            if pushedStyles > 0 then pcall(im.PopStyleVar, pushedStyles) end
            if submit and RC.punQuick == Q then sendQuick() end
        end
        _G.GRND_RECON_UI = { pages = {
            [1] = {
                { id = "hp", label = "Выдать ХП", gear = true },
                { id = "arm", label = "Выдать броню", gear = true },
                { id = "slap", label = "Подбросить" },
                { id = "freeze", label = "Заморозить" },
                { id = "unfreeze", label = "Разморозить" },
                { id = "rgun", label = "Отобрать оружие" },
            },
            [2] = {
                { id = "flipcar", label = "Перевернуть т/с" },
                { id = "fixcar", label = "Починить т/с" },
                { id = "fuel", label = "Заправить т/с" },
                { id = "spawncar", label = "Заспавнить" },
            },
            [3] = {
                { id = "weapon", label = "Оружие" },
                { id = "licenses", label = "Лицензии" },
                { id = "skills", label = "Скилы" },
                { id = "punishments", label = "Актив.наказания" },
            },
        } }
        _G.GRND_RECON_UI.draw = function()
            local RC = GRND_RC
            if not RC or not RC.show or not im then
                -- рекон закрыт: панели у краёв тоже убираем
                if RC and RC.edge then
                    RC.edge.lOpen, RC.edge.rOpen = false, false
                    RC.edge.la, RC.edge.ra = 0, 0
                end
                return false
            end
            -- две стрелки у краёв: слева кнопки рекона, справа статистика
            RC.edge = RC.edge or {}
            local EDGE = RC.edge
            if EDGE.lOpen == nil then EDGE.lOpen = false end
            if EDGE.rOpen == nil then EDGE.rOpen = false end
            EDGE.la = tonumber(EDGE.la) or 0
            EDGE.ra = tonumber(EDGE.ra) or 0
            local function reconUtf(v)
                v = tostring(v or "")
                if type(grndToUtf) == "function" then
                    local ok, out = pcall(grndToUtf, v)
                    if ok and type(out) == "string" then return out end
                end
                return v
            end
            RC.imguiHealthy = false
            RC.imguiLastAt = os.clock()
            local id = tonumber(RC.id)
            if not id and GRND_SPEC and GRND_SPEC.active then
                id = tonumber(GRND_SPEC.id)
                RC.id = id
            end
            if not id then return false end
            local resX, resY = getScreenResolution()
            if GRND_PUN and not GRND_PUN.loaded then pcall(GRND_PUN.load) end
            local punList = (GRND_PUN and GRND_PUN.barOn ~= false)
                and GRND_PUN.list or nil
            local punItems = {}
            if type(punList) == "table" then
                for j = 1, #punList do
                    local it = punList[j]
                    if it and #punItems < 6 then
                        punItems[#punItems + 1] = it
                    end
                end
            end
            local punCnt = #punItems
            if RC.cursor == nil then RC.cursor = false end
            local function textValue(key, fallback)
                local v = RC.live and RC.live[key]
                if v ~= nil then
                    v = reconUtf(v)
                    if v ~= "" then return v end
                end
                return fallback or "—"
            end
            local function numberValue(key, fallback)
                local v = RC.live and RC.live[key]
                if v ~= nil then
                    v = tostring(v):gsub(",", ".")
                    local n = tonumber(v:match("[-+]?%d+%.?%d*"))
                    if n then return n end
                end
                return fallback
            end
            local function shortValue(v, maxChars)
                v = tostring(v or "—")
                if grndUtf8Len(v) <= maxChars then return v end
                local out, count = {}, 0
                for ch in v:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
                    count = count + 1
                    if count >= maxChars then out[#out + 1] = "…"; break end
                    out[#out + 1] = ch
                end
                return table.concat(out)
            end
            local nick = reconUtf(RC.nick or "Игрок")
            if nick == "" then nick = "Игрок" end
            local pingNum = getPlayerPing(id)
            local pingStable = grndParamNum(id, "ping",
                pingNum or (tonumber(tostring(textValue("ping", "")):match("%d+")) or nil))
            local ping = pingStable and tostring(math.floor(pingStable + 0.5))
                or tostring(textValue("ping", "—")):match("%d+") or "—"
            local hpNum = grndParamNum(id, "hp", numberValue("hp", getPlayerHealth(id)))
            local armNum = grndParamNum(id, "arm", numberValue("arm", getPlayerArmor(id)))
            local hpText = hpNum and string.format("%.1f", hpNum) or "—"
            local armText = armNum and string.format("%.1f", armNum) or "—"
            local lvlRaw = textValue("rc_level", "")
            if lvlRaw == "" then
                lvlRaw = tostring(textValue("rc_level_exp", "—")):gsub("%s*%b()", "")
            end
            if lvlRaw == "" then lvlRaw = "—" end
            -- Старую карточку рекона больше не рисуем: наказания и быстрые
            -- действия живут в панели у левого края, статистика — у правого.
            -- Здесь только считаем данные для панелей.
            local function runReconAction(item)
                local tid = tonumber(RC.actTargetId) or tonumber(RC.id)
                    or (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id))
                if not tid then
                    if notify and notify.add then pcall(notify.add, "Цель не найдена", "warn", 2) end
                    return
                end
                local tNick = (RC.actTargetNick and RC.actTargetNick ~= "") and RC.actTargetNick
                    or (RC.nick and RC.nick ~= "" and RC.nick) or ("ID " .. tostring(tid))
                local function sendQuick(cmd, message)
                    if type(sampSendChat) ~= "function" then
                        if notify and notify.add then pcall(notify.add, "Не удалось отправить команду", "warn", 2) end
                        return
                    end
                    local ok = pcall(sampSendChat, cmd)
                    if notify and notify.add then
                        pcall(notify.add, ok and message or "Не удалось отправить команду",
                            ok and "ok" or "warn", 2.2)
                    end
                end
                if item.id == "hp" then
                    local amount = grndRcClampHp(RC.actHpVal)
                    RC.actHpVal = amount
                    sendQuick("/hp " .. tostring(tid) .. " " .. tostring(amount),
                        "Выдано " .. tostring(amount) .. " ХП игроку " .. tNick)
                elseif item.id == "arm" then
                    local amount = math.max(0, math.min(100, math.floor(tonumber(RC.actArmVal) or 100)))
                    RC.actArmVal = amount
                    sendQuick("/arm " .. tostring(tid) .. " " .. tostring(amount),
                        "Выдано " .. tostring(amount) .. " брони игроку " .. tNick)
                elseif item.id == "fuel" then
                    local getter = _G.grndGetTargetVehId
                    local vid = nil
                    if type(getter) == "function" then
                        local okV, value = pcall(getter, tid, RC.actTargetPed)
                        if okV then vid = tonumber(value) end
                    end
                    vid = vid or (RC.live and tonumber(RC.live.carId))
                    if not vid then
                        if notify and notify.add then pcall(notify.add,
                            "ID транспорта не определён (игрок должен быть в авто)", "warn", 2.5) end
                        return
                    end
                    local amount = math.max(0, math.min(150, math.floor(tonumber(RC.actFuelVal) or 150)))
                    RC.actFuelVal = amount
                    sendQuick("/setfuel " .. tostring(vid) .. " " .. tostring(amount),
                        "Транспорт #" .. tostring(vid) .. " заправлен на " .. tostring(amount) .. " л")
                else
                    local actionLabels = {
                        slap = "Подбросить", freeze = "Заморозить", unfreeze = "Разморозить",
                        rgun = "Отобрать все оружие", flipcar = "Перевернуть т/с",
                        fixcar = "Починить т/с", spawncar = "Заспавнить т/с",
                        weapon = "Оружие", licenses = "Лицензии",
                        skills = "Скилы", punishments = "Активные наказания",
                    }
                    if type(_G.grndHandleActionBtn) == "function" then
                        pcall(_G.grndHandleActionBtn, actionLabels[item.id], tid, tNick, RC.actTargetPed)
                    elseif notify and notify.add then
                        pcall(notify.add, "Обработчик действия не загружен", "warn", 2)
                    end
                end
            end
            RC.edgeRunAction = runReconAction
            RC.edgeWho = { nick = nick, id = id }
            do
                local function tilePct(v, maxv)
                    local n = tonumber(v)
                    local m = tonumber(maxv) or 100
                    if not n or m <= 0 then return 0 end
                    return math.max(0, math.min(1, n / m))
                end
                RC.edgeTiles = {
                    { k = "ПИНГ", v = tostring(ping) .. " ms",
                        pct = 1 - tilePct(ping, 300) },
                    { k = "ЗДОРОВЬЕ", v = hpText,
                        pct = tilePct(hpNum, grndParamScale(hpNum)) },
                    { k = "БРОНЯ", v = armText,
                        pct = tilePct(armNum, grndParamScale(armNum)) },
                }
            end
            -- ХП, броня, пинг и скорость показаны плитками/в шапке — в списке их нет.
            RC.edgeStatRows = {
                { label = "Номер аккаунта:", value = textValue("rc_account", "—") },
                { label = "Уровень:", value = lvlRaw },
                { label = "Номер телефона", value = textValue("rc_phone", "—") },
                { label = "Варнов", value = textValue("rc_varnov", "—") },
                { label = "Пол", value = textValue("rc_gender", "—") },
                { label = "Женат на", value = textValue("rc_married", "—") },
                { label = "Орг. (ранг)", value = textValue("rc_org", "—") },
                { label = "Работа/Должность", value = textValue("rc_job", "—") },
                { label = "Бизнес", value = textValue("rc_business", "—") },
                { label = "Игровой статус", value = textValue("rc_status", "—") },
                { label = "Дом", value = textValue("rc_house", "—") },
                { label = "Квартира", value = textValue("rc_flat", "—") },
                { label = "VIP статус", value = textValue("rc_vip", "—") },
                { label = "За сегодня", value = textValue("today", "—") },
                { label = "Семья", value = textValue("rc_family", "—") },
            }
            -- ── Две стрелки у краёв экрана ─────────────────────────────
            -- Слева «>» — панель со всеми кнопками рекона (наказания и
            -- быстрые действия), справа «<» — объёмная статистика.
            -- Когда обе закрыты, на экране только два небольших кружка.
            -- Вынесено в отдельную функцию, чтобы не раздувать drawRecon.
            local function drawEdgeUi()
                local nowE = os.clock()
                local dtE = math.max(0, math.min(0.1, nowE - (EDGE.at or nowE)))
                EDGE.at = nowE
                local stepE = math.min(1, dtE * 9)
                local function glide(v, target)
                    v = tonumber(v) or 0
                    v = v + (target - v) * stepE
                    if math.abs(target - v) < 0.004 then v = target end
                    return v
                end
                EDGE.la = glide(EDGE.la, EDGE.lOpen and 1 or 0)
                EDGE.ra = glide(EDGE.ra, EDGE.rOpen and 1 or 0)

                local BALL_D, ZONE, EPAD = 34, 46, 2
                local cyE = math.floor(resY / 2)
                local bxL = EPAD + math.floor(ZONE / 2)
                local bxR = resX - EPAD - math.floor(ZONE / 2)
                -- Все быстрые действия в одной панели: страницы больше нет.
                local actsE = {}
                do
                    local pagesE = _G.GRND_RECON_UI and _G.GRND_RECON_UI.pages
                    if type(pagesE) == "table" then
                        local seenE = {}
                        for p = 1, #pagesE do
                            for i = 1, #(pagesE[p] or {}) do
                                local itE = pagesE[p][i]
                                if itE and itE.id and not seenE[itE.id] then
                                    seenE[itE.id] = true
                                    actsE[#actsE + 1] = itE
                                end
                            end
                        end
                    end
                end
                local function edgeFlags()
                    local fl = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
                        "NoCollapse", "NoFocusOnAppearing", "NoBringToFrontOnFocus",
                        "NoScrollWithMouse", "NoNavInputs", "NoNavFocus")
                    if not RC.cursor then fl = fl + wflag("NoInputs") end
                    return fl
                end

                -- ── левая панель: все кнопки рекона ────────────────────
                local PLW = 250
                local B_H, B_GAP, COL_GAP2 = 32, 6, 8
                local innerW = PLW - 28
                local colW = math.floor((innerW - COL_GAP2) / 2)
                local actRows = math.ceil(#actsE / 2)
                -- Панель поделена на два модуля: наказания и действия с игроком.
                -- Между модулями — ровная линия с подписью по центру.
                local DIV_H2, DIV_GAP = 22, 12   -- высота разделителя и отступ до него
                local needH = 12
                if punCnt > 0 then
                    needH = needH + DIV_H2 + punCnt * (B_H + B_GAP)
                end
                if actRows > 0 then
                    needH = needH + DIV_GAP + DIV_H2 + actRows * (B_H + B_GAP)
                end
                needH = needH - B_GAP + 12
                local panLH = math.min(needH, math.max(200, resY - 24))
                local panLY = math.max(8, math.min(math.max(8, resY - panLH - 8),
                    math.floor((resY - panLH) / 2)))
                -- Если кнопок больше, чем влезает в панель, список прокручивается.
                local listTopL = 6
                local listHL = math.max(40, panLH - listTopL - 6)
                local contentHL = math.max(0, needH - listTopL - 18)
                local scrollL = math.max(0, math.min(math.max(0, contentHL - listHL),
                    tonumber(EDGE.lScroll) or 0))
                EDGE.lScroll = scrollL
                -- Панель выезжает из-за края и встаёт ПРАВЕЕ стрелки,
                -- чтобы кружок не оказался на самой панели.
                local panLXopen = EPAD + ZONE + 6
                local panLX = math.floor(-PLW + (PLW + panLXopen) * EDGE.la)
                EDGE.leftRect = (EDGE.la > 0.5)
                    and { x = panLX, y = panLY, w = PLW, h = panLH } or nil
                if EDGE.la > 0.002 then
                    local stL, clL = 0, 0
                    if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then stL = stL + 1 end
                    if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 0) then stL = stL + 1 end
                    if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then clL = clL + 1 end
                    if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then clL = clL + 1 end
                    im.SetNextWindowPos(im.ImVec2(panLX, panLY), COND_ALWAYS)
                    im.SetNextWindowSize(im.ImVec2(PLW, panLH), COND_ALWAYS)
                    local lBegin = false
                    if grndBegin("##grnd_rc_edge_left", edgeFlags()) then
                        lBegin = true
                        -- Панель поднимается наверх: чекеры (kill-list, админы)
                        -- рисуются позже и иначе просвечивали бы сквозь неё.
                        if im.BringWindowToDisplayFront and im.GetCurrentWindow then
                            pcall(im.BringWindowToDisplayFront, im.GetCurrentWindow())
                        end
                        local posL = im.GetWindowPos()
                        local dlL = im.GetWindowDrawList()
                        local function atL(x, y) return im.ImVec2(posL.x + x, posL.y + y) end
                        local function fillL(x, y, w, h, col, rad)
                            if w > 0 and h > 0 then
                                roundRect(dlL, atL(x, y), atL(x + w, y + h), col, rad or 0)
                            end
                        end
                        local function frameL(x, y, w, h, col, rad)
                            if dlL.AddRect then
                                pcall(dlL.AddRect, dlL, atL(x, y), atL(x + w, y + h),
                                    col, rad or 0, 0, 1.0)
                            end
                        end
                        local function putL(x, y, txt, col, sc)
                            uiText(x, y, tostring(txt), col, sc or 1)
                        end
                        local function wL(txt, sc)
                            return grndTextW(tostring(txt)) * (sc or 1)
                        end
                        -- объёмная подложка: тень, фон, светлая кромка, блик
                        fillL(6, 8, PLW, panLH, col32(0, 0, 0, 120), 14)
                        fillL(0, 0, PLW, panLH,
                            col32(TH.sidebar[1], TH.sidebar[2], TH.sidebar[3], 255), 14)
                        fillL(10, 3, PLW - 20, 1, col32(255, 255, 255, 16), 0)
                        frameL(0.5, 0.5, PLW - 1, panLH - 1,
                            col32(TH.line[1], TH.line[2], TH.line[3], TH.line[4] or 255), 14)
                        -- Ровная линия с подписью по центру: текст стоит в разрыве
                        -- линии, слева и справа она продолжается до краёв панели.
                        local function dividerL(y, caption)
                            local sc = 0.64
                            local txt = grndToUtf and tostring(caption) or tostring(caption)
                            local tw = wL(txt, sc)
                            local cxM = PLW / 2
                            local gap = 12
                            local y0 = y + 5
                            local leftTo = math.max(14, cxM - tw / 2 - gap)
                            local rightFrom = math.min(PLW - 14, cxM + tw / 2 + gap)
                            local colLine = col32(TH.line[1], TH.line[2], TH.line[3],
                                math.min(255, math.max(40, (TH.line[4] or 255) + 18)))
                            if leftTo > 14 then
                                fillL(14, y0, leftTo - 14, 1, colLine, 0)
                            end
                            if rightFrom < PLW - 14 then
                                fillL(rightFrom, y0, PLW - 14 - rightFrom, 1, colLine, 0)
                            end
                            putL(cxM - tw / 2, y + 1, txt, c4(TH.textMuted), sc)
                        end
                        local cy = 12 - scrollL
                        local clipL = false
                        if dlL.PushClipRect then
                            clipL = pcall(dlL.PushClipRect, dlL,
                                atL(0, listTopL - 2), atL(PLW, panLH - 4), true)
                        end
                        if punCnt > 0 then
                            dividerL(cy, "Наказания")
                            cy = cy + DIV_H2
                            for i = 1, punCnt do
                                local itm = punItems[i]
                                local btnLabel = tostring((itm and itm.id) or "")
                                im.SetCursorPos(im.ImVec2(14, cy))
                                local clicked = im.InvisibleButton("##rc_edge_pun_" .. btnLabel,
                                    im.ImVec2(innerW, B_H))
                                local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                                local act2 = (im.IsItemActive and im.IsItemActive()) or false
                                fillL(14, cy, innerW, B_H,
                                    act2 and col32(TH.accent[1], TH.accent[2], TH.accent[3], 62)
                                        or (hov and col32(TH.accent[1], TH.accent[2], TH.accent[3], 34)
                                            or col32(255, 255, 255, 10)), 8)
                                fillL(16, cy + 1, innerW - 4, 1,
                                    col32(255, 255, 255, (hov or act2) and 26 or 12), 0)
                                frameL(14.5, cy + 0.5, innerW - 1, B_H - 1,
                                    (hov or act2)
                                        and col32(TH.accent[1], TH.accent[2], TH.accent[3], 130)
                                        or col32(255, 255, 255, 22), 8)
                                putL(14 + (innerW - wL(btnLabel, 0.92)) / 2,
                                    cy + (B_H - 13 * 0.92) / 2, btnLabel,
                                    hov and c4(TH.textHi) or c4(TH.text), 0.92)
                                if clicked and RC.cursor then
                                    grndReconQuickPunishOpen(RC, btnLabel, id, nick)
                                end
                                cy = cy + B_H + B_GAP
                            end
                        end
                        if actRows > 0 then
                            if punCnt > 0 then cy = cy + DIV_GAP end
                            dividerL(cy, "Действия с игроком")
                            cy = cy + DIV_H2
                            for i = 1, #actsE do
                                local item = actsE[i]
                                local colI = (i - 1) % 2
                                local rowI = math.floor((i - 1) / 2)
                                local cxp = 14 + colI * (colW + COL_GAP2)
                                local cyp = cy + rowI * (B_H + B_GAP)
                                im.SetCursorPos(im.ImVec2(cxp, cyp))
                                local clicked = im.InvisibleButton("##rc_edge_act_" .. tostring(item.id),
                                    im.ImVec2(colW, B_H))
                                local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                                local act2 = (im.IsItemActive and im.IsItemActive()) or false
                                fillL(cxp, cyp, colW, B_H,
                                    act2 and col32(TH.accent[1], TH.accent[2], TH.accent[3], 62)
                                        or (hov and col32(TH.accent[1], TH.accent[2], TH.accent[3], 34)
                                            or col32(255, 255, 255, 10)), 8)
                                fillL(cxp + 2, cyp + 1, colW - 4, 1,
                                    col32(255, 255, 255, (hov or act2) and 26 or 12), 0)
                                frameL(cxp + 0.5, cyp + 0.5, colW - 1, B_H - 1,
                                    (hov or act2)
                                        and col32(TH.accent[1], TH.accent[2], TH.accent[3], 130)
                                        or col32(255, 255, 255, 22), 8)
                                local lbl = tostring(item.label or item.id or "")
                                local lw = wL(lbl, 1)
                                local sc = math.min(0.82, math.max(0.52, (colW - 8) / math.max(1, lw)))
                                putL(cxp + (colW - wL(lbl, sc)) / 2,
                                    cyp + (B_H - 13 * sc) / 2, lbl,
                                    hov and c4(TH.textHi) or c4(TH.text), sc)
                                if clicked and RC.cursor and type(RC.edgeRunAction) == "function" then
                                    pcall(RC.edgeRunAction, item)
                                end
                            end
                        end
                        if clipL then pcall(dlL.PopClipRect, dlL) end
                    end
                    if lBegin then
                        endDepth = endDepth - 1
                        pcall(im.End)
                    end
                    grndPopCol(clL)
                    grndPopStyle(stL)
                end

                -- ── правая панель: объёмная статистика ─────────────────
                local SPW = 330   -- ширина панели статистики
                local innerS = SPW - 28
                local rowsE = RC.edgeStatRows or {}
                local tilesE = RC.edgeTiles or {}
                local rowHS, tileHS = 24, 64
                local listNeed = 0
                for i = 1, #rowsE do
                    listNeed = listNeed + ((rowsE[i].div and 13) or rowHS)
                end
                local tilesH = (#tilesE > 0) and (tileHS + 12) or 0
                local HEAD_S = 40   -- строка с ником/ID и кнопкой копирования
                local needSH = HEAD_S + tilesH + listNeed + 16
                local panSH = math.min(needSH, math.max(220, resY - 24))
                local panSY = math.max(8, math.min(math.max(8, resY - panSH - 8),
                    math.floor((resY - panSH) / 2)))
                -- Панель встаёт ЛЕВЕЕ правой стрелки, кружок остаётся снаружи.
                local panSXopen = resX - SPW - ZONE - 6
                local panSXhidden = resX + 8
                local panSX = math.floor(panSXhidden
                    + (panSXopen - panSXhidden) * EDGE.ra)
                local listTopS = HEAD_S + tilesH
                local listHS = math.max(24, panSH - listTopS - 16)
                local scrollS = math.max(0, math.min(math.max(0, listNeed - listHS),
                    tonumber(EDGE.rScroll) or 0))
                EDGE.rScroll = scrollS
                EDGE.statsRect = (EDGE.ra > 0.5)
                    and { x = panSX, y = panSY, w = SPW, h = panSH } or nil
                if EDGE.ra > 0.002 then
                    local stR, clR = 0, 0
                    if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then stR = stR + 1 end
                    if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 0) then stR = stR + 1 end
                    if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then clR = clR + 1 end
                    if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then clR = clR + 1 end
                    im.SetNextWindowPos(im.ImVec2(panSX, panSY), COND_ALWAYS)
                    im.SetNextWindowSize(im.ImVec2(SPW, panSH), COND_ALWAYS)
                    local rBegin = false
                    if grndBegin("##grnd_rc_edge_stats", edgeFlags()) then
                        rBegin = true
                        if im.BringWindowToDisplayFront and im.GetCurrentWindow then
                            pcall(im.BringWindowToDisplayFront, im.GetCurrentWindow())
                        end
                        local posS = im.GetWindowPos()
                        local dlS = im.GetWindowDrawList()
                        local function atS(x, y) return im.ImVec2(posS.x + x, posS.y + y) end
                        local function fillS(x, y, w, h, col, rad)
                            if w > 0 and h > 0 then
                                roundRect(dlS, atS(x, y), atS(x + w, y + h), col, rad or 0)
                            end
                        end
                        local function frameS(x, y, w, h, col, rad)
                            if dlS.AddRect then
                                pcall(dlS.AddRect, dlS, atS(x, y), atS(x + w, y + h),
                                    col, rad or 0, 0, 1.0)
                            end
                        end
                        local function putS(x, y, txt, col, sc)
                            uiText(x, y, tostring(txt), col, sc or 1)
                        end
                        local function wS(txt, sc)
                            return grndTextW(tostring(txt)) * (sc or 1)
                        end
                        local who = RC.edgeWho or {}
                        -- объёмная подложка
                        fillS(-6, 8, SPW, panSH, col32(0, 0, 0, 120), 14)
                        fillS(0, 0, SPW, panSH,
                            col32(TH.sidebar[1], TH.sidebar[2], TH.sidebar[3], 255), 14)
                        fillS(10, 3, SPW - 20, 1, col32(255, 255, 255, 16), 0)
                        frameS(0.5, 0.5, SPW - 1, panSH - 1,
                            col32(TH.line[1], TH.line[2], TH.line[3], TH.line[4] or 255), 14)
                        -- ник и ID крупно, отдельной строкой (без заголовка панели)
                        local nickTxt = tostring(who.nick or "—")
                        local idTxt = "[" .. tostring(who.id or "?") .. "]"
                        local cpS = 20
                        local idSc = 0.92
                        local idW = wS(idTxt, idSc)
                        local nickSc = 1.16
                        -- ник + [ID] + иконка копирования — одна строка слева,
                        -- место под иконку резервируем сразу за ID
                        local roomNick = innerS - idW - cpS - 18
                        if wS(nickTxt, nickSc) > roomNick then
                            nickSc = math.max(0.80,
                                nickSc * roomNick / math.max(1, wS(nickTxt, nickSc)))
                        end
                        local nickW2 = wS(nickTxt, nickSc)
                        local nickX2 = 14
                        local idX2 = nickX2 + nickW2 + 6
                        local cpX = idX2 + idW + 6
                        local nickY2 = 11
                        local nickH2 = 13 * nickSc
                        putS(nickX2, nickY2, nickTxt, c4(TH.textHi), nickSc)
                        putS(idX2, nickY2 + (nickH2 - 13 * idSc) / 2 + 1, idTxt,
                            col32(TH.accent[1], TH.accent[2], TH.accent[3], 255), idSc)
                        -- Кнопка «копировать ник»: только иконка, без фона и рамки.
                        -- Стоит ровно по центру строки ника (а не по верху текста).
                        local nickCY = nickY2 + nickH2 / 2
                        local cpY = math.floor(nickCY - cpS / 2 + 0.5)
                        im.SetCursorPos(im.ImVec2(cpX, cpY))
                        local cpClick = im.InvisibleButton("##rc_edge_copy", im.ImVec2(cpS, cpS))
                        local cpHov = (im.IsItemHovered and im.IsItemHovered()) or false
                        local icCol2 = cpHov
                            and col32(TH.accent[1], TH.accent[2], TH.accent[3], 255)
                            or col32(236, 232, 248, 235)
                        local iconS = 11
                        local ix = cpX + math.floor((cpS - iconS) / 2 + 0.5)
                        local iy = cpY + math.floor((cpS - iconS) / 2 + 0.5)
                        if dlS.AddRect then
                            -- задний лист — только контур
                            pcall(dlS.AddRect, dlS, atS(ix + 3.5, iy + 0.5),
                                atS(ix + 9.5, iy + 6.5), icCol2, 2, 0, 1.4)
                            -- передний лист: подложка цветом панели перекрывает
                            -- контур заднего, поэтому иконка чёткая, а не мутная
                            fillS(ix, iy + 3.5, 7, 7,
                                col32(TH.sidebar[1], TH.sidebar[2], TH.sidebar[3], 255), 2)
                            pcall(dlS.AddRect, dlS, atS(ix + 0.5, iy + 4),
                                atS(ix + 6.5, iy + 10), icCol2, 2, 0, 1.4)
                        end
                        if cpHov and type(im.SetTooltip) == "function" then
                            pcall(im.SetTooltip, "Скопировать ник")
                        end
                        if cpClick and RC.cursor then
                            local copied2 = false
                            if type(reconCopyNickname) == "function" then
                                copied2 = reconCopyNickname(nickTxt) and true or false
                            end
                            if notify and notify.add then
                                pcall(notify.add, copied2 and "Ник скопирован в буфер"
                                    or "Не удалось скопировать ник",
                                    copied2 and "ok" or "warn", 2)
                            end
                        end
                        -- плитки: пинг / HP / броня
                        if #tilesE > 0 then
                            local tgap = 8
                            local tw3 = math.floor((innerS - tgap * 2) / 3)
                            local ty = HEAD_S
                            local barPad = 9
                            local barW3 = tw3 - barPad * 2
                            for i = 1, math.min(3, #tilesE) do
                                local T = tilesE[i]
                                local tx = 14 + (i - 1) * (tw3 + tgap)
                                -- Ровная однотонная карточка: один фон и тонкий
                                -- светлый блик по верхней кромке, без половин и
                                -- смещённой тени.
                                fillS(tx, ty, tw3, tileHS, col32(255, 255, 255, 14), 10)
                                fillS(tx + 10, ty + 1, tw3 - 20, 1,
                                    col32(255, 255, 255, 26), 0)
                                frameS(tx + 0.5, ty + 0.5, tw3 - 1, tileHS - 1,
                                    col32(255, 255, 255, 30), 10)
                                putS(tx + barPad, ty + 8, T.k, c4(TH.textMuted), 0.66)
                                local vTxt = tostring(T.v or "—")
                                local vSc = 0.98
                                if wS(vTxt, vSc) > barW3 then
                                    vSc = math.max(0.60, vSc * barW3 / math.max(1, wS(vTxt, vSc)))
                                end
                                putS(tx + barPad, ty + 22, vTxt, c4(TH.textHi), vSc)
                                -- Полоска вшита в карточку: тонкая дорожка с полями
                                -- по краям и скруглением, аккурат по ширине текста.
                                local barY = ty + tileHS - 16
                                fillS(tx + barPad, barY, barW3, 4,
                                    col32(255, 255, 255, 24), 2)
                                local pct = math.max(0, math.min(1, tonumber(T.pct) or 0))
                                if pct > 0 then
                                    fillS(tx + barPad, barY,
                                        math.max(3, math.floor(barW3 * pct)), 4,
                                        col32(TH.accent[1], TH.accent[2], TH.accent[3], 225), 2)
                                end
                            end
                        end
                        -- ровные строки, как в карточке
                        local ry = listTopS - scrollS
                        for i = 1, #rowsE do
                            local it2 = rowsE[i]
                            if it2.div then
                                local dy = ry + 6
                                ry = ry + 13
                                if dy >= listTopS - 0.5 and dy <= listTopS + listHS then
                                    fillS(14, dy, innerS, 1, col32(255, 255, 255, 38), 0)
                                end
                            else
                                if ry + rowHS >= listTopS - 0.5 and ry <= listTopS + listHS then
                                    local valTxt = shortValue(it2.value, 24)
                                    local valSc = 0.84
                                    local roomV = innerS * 0.58
                                    if wS(valTxt, valSc) > roomV then
                                        valSc = math.max(0.55,
                                            valSc * roomV / math.max(1, wS(valTxt, valSc)))
                                    end
                                    local lblSc = 0.80
                                    local roomL = innerS - wS(valTxt, valSc) - 12
                                    local lblTxt = shortValue(it2.label, 26)
                                    if wS(lblTxt, lblSc) > math.max(40, roomL) then
                                        lblTxt = shortValue(lblTxt, 14)
                                        lblSc = 0.72
                                    end
                                    putS(14, ry + 3, lblTxt, c4(TH.textMuted), lblSc)
                                    putS(SPW - 14 - wS(valTxt, valSc), ry + 3, valTxt,
                                        it2.color or c4(TH.text), valSc)
                                end
                                ry = ry + rowHS
                            end
                        end
                        if listNeed > listHS then
                            local trX = SPW - 8
                            fillS(trX, listTopS, 3, listHS, col32(255, 255, 255, 16), 2)
                            local barHS = math.max(26, listHS * (listHS / listNeed))
                            local barYS = listTopS + (scrollS / listNeed) * (listHS - barHS)
                            fillS(trX, barYS, 3, barHS, col32(255, 255, 255, 120), 2)
                        end
                    end
                    if rBegin then
                        endDepth = endDepth - 1
                        pcall(im.End)
                    end
                    grndPopCol(clR)
                    grndPopStyle(stR)
                end

                -- ── сами кружки со стрелками ───────────────────────────
                local function edgeBall(side, cx2, isOpen)
                    local x0 = cx2 - math.floor(ZONE / 2)
                    local y0 = cyE - math.floor(ZONE / 2)
                    local stB, clB = 0, 0
                    if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then stB = stB + 1 end
                    if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 0) then stB = stB + 1 end
                    if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then clB = clB + 1 end
                    if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then clB = clB + 1 end
                    im.SetNextWindowPos(im.ImVec2(x0, y0), COND_ALWAYS)
                    im.SetNextWindowSize(im.ImVec2(ZONE, ZONE), COND_ALWAYS)
                    local clicked, hovered, bBegin = false, false, false
                    if grndBegin("##grnd_rc_edge_ball_" .. side, edgeFlags()) then
                        bBegin = true
                        im.SetCursorPos(im.ImVec2(0, 0))
                        clicked = im.InvisibleButton("##ball_btn", im.ImVec2(ZONE, ZONE))
                        hovered = (im.IsItemHovered and im.IsItemHovered()) or false
                        local bp = im.GetWindowPos()
                        local dl = im.GetWindowDrawList()
                        local ccx, ccy = tonumber(bp.x) + ZONE / 2, tonumber(bp.y) + ZONE / 2
                        local R = BALL_D / 2
                        local ac = TH.accent
                        local glow = hovered and 52 or (isOpen and 38 or 0)
                        if dl.AddCircleFilled then
                            if glow > 0 then
                                pcall(dl.AddCircleFilled, dl, im.ImVec2(ccx, ccy), R + 8,
                                    col32(ac[1], ac[2], ac[3], glow), 28)
                                pcall(dl.AddCircleFilled, dl, im.ImVec2(ccx, ccy), R + 3,
                                    col32(ac[1], ac[2], ac[3], glow + 20), 28)
                            end
                            pcall(dl.AddCircleFilled, dl, im.ImVec2(ccx + 1, ccy + 2), R,
                                col32(0, 0, 0, 120), 28)
                            pcall(dl.AddCircleFilled, dl, im.ImVec2(ccx, ccy), R,
                                col32(16, 14, 22, 250), 28)
                            pcall(dl.AddCircleFilled, dl, im.ImVec2(ccx, ccy - 1.5), R - 2,
                                col32(33, 28, 44, 210), 28)
                            pcall(dl.AddCircleFilled, dl, im.ImVec2(ccx, ccy - 2.5), R - 8,
                                col32(58, 49, 76, 130), 28)
                        end
                        if dl.AddCircle then
                            pcall(dl.AddCircle, dl, im.ImVec2(ccx, ccy), R - 0.5,
                                col32(255, 255, 255, hovered and 135 or 80), 28, 1.0)
                        end
                        -- блик сверху, чтобы кружок выглядел объёмным
                        if dl.PathArcTo and dl.PathStroke then
                            pcall(dl.PathArcTo, dl, im.ImVec2(ccx, ccy), R - 3.5,
                                3.4, 5.6, 18)
                            pcall(dl.PathStroke, dl, col32(255, 255, 255, 70), 0, 1.2)
                        end
                        local pointsRight = (side == "left") and (not isOpen)
                            or ((side == "right") and isOpen)
                        local tipX = ccx + (pointsRight and 4.5 or -4.5)
                        local backX = ccx + (pointsRight and -2.0 or 2.0)
                        local ink = hovered and 255 or 226
                        if dl.AddLine then
                            pcall(dl.AddLine, dl, im.ImVec2(backX, ccy - 5.2),
                                im.ImVec2(tipX, ccy), col32(240, 236, 250, ink), 2.0)
                            pcall(dl.AddLine, dl, im.ImVec2(tipX, ccy),
                                im.ImVec2(backX, ccy + 5.2), col32(240, 236, 250, ink), 2.0)
                        end
                        if hovered and type(im.SetTooltip) == "function" then
                            pcall(im.SetTooltip, (side == "left")
                                and "Кнопки действий" or "Статистика")
                        end
                    end
                    if bBegin then
                        endDepth = endDepth - 1
                        pcall(im.End)
                    end
                    grndPopCol(clB)
                    grndPopStyle(stB)
                    return clicked
                end
                if edgeBall("left", bxL, EDGE.lOpen) and RC.cursor then
                    EDGE.lOpen = not EDGE.lOpen
                end
                if edgeBall("right", bxR, EDGE.rOpen) and RC.cursor then
                    EDGE.rOpen = not EDGE.rOpen
                end
                EDGE.any = (EDGE.lOpen or EDGE.rOpen) and true or false
            end
            drawEdgeUi()
            if GRND_SPEC and GRND_SPEC.active and im and im.SetNextWindowPos then
                local S = 1.3
                local PAD, GAP, BH = 8, 7, 29
                local WIDE, NARROW = 60, 30
                local kinds = {
                    { "back", WIDE, "Предыдущий ID" },
                    { "road", NARROW, "ТП на дорогу: игрок и т/с в радиусе 20 м" },
                    { "diamond", NARROW, "ТП игрока на дорогу" },
                    { "flag", NARROW, "ТП к игроку (/spoff, затем /goto)" },
                    { "fwd", WIDE, "Следующий ID" },
                }
                local PW = 2 * PAD + 2 * WIDE + 3 * NARROW + 4 * GAP
                local PH = BH + 2 * PAD
                local SW, SH = PW * S, PH * S
                RC.specBar = RC.specBar or {}
                local SB = RC.specBar
                if not SB.x then
                    local sv = _G.GRND_UI_BAR_SAVED
                    if sv and sv.barX and sv.barY then
                        SB.x, SB.y = sv.barX, sv.barY
                    else
                        SB.x = math.floor(resX / 2 - SW / 2)
                        SB.y = 64
                    end
                end
                SB.x = math.max(0, math.min(resX - SW, SB.x))
                SB.y = math.max(0, math.min(resY - SH, SB.y))
                local barRect = { x = SB.x, y = SB.y, w = SW, h = SH }
                if RC.cursor and GRND_MOUSE.down then
                    if not SB.dragging and not SB.hov and grndMouseInside(barRect) then
                        SB.dragging = true
                        SB.dx = grndCursorX() - SB.x
                        SB.dy = grndCursorY() - SB.y
                    end
                else
                    SB.dragging = false
                end
                if SB.dragging then
                    SB.x = math.max(0, math.min(resX - SW, grndCursorX() - SB.dx))
                    SB.y = math.max(0, math.min(resY - SH, grndCursorY() - SB.dy))
                    SB.posDirty = true
                elseif SB.posDirty then
                    SB.posDirty = false
                    _G.GRND_UI_BAR_SAVED = _G.GRND_UI_BAR_SAVED or {}
                    _G.GRND_UI_BAR_SAVED.barX, _G.GRND_UI_BAR_SAVED.barY = SB.x, SB.y
                    GRND_FONT.cfgDirty = true
                    GRND_FONT.cfgSavedAt = 0
                    pcall(grndUiCfgSave)
                end
                im.SetNextWindowPos(im.ImVec2(SB.x, SB.y), COND_ALWAYS)
                im.SetNextWindowSize(im.ImVec2(SW, SH), COND_ALWAYS)
                local stB, clB = 0, 0
                if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then stB = stB + 1 end
                if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 0) then stB = stB + 1 end
                if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then clB = clB + 1 end
                if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then clB = clB + 1 end
                local flagsB = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
                    "NoCollapse", "NoFocusOnAppearing", "NoBringToFrontOnFocus")
                local anyHov = false
                local hovHint = nil
                if grndBegin("##grnd_spec_bar", flagsB) then
                    local bpos = im.GetWindowPos()
                    local bdl = im.GetWindowDrawList()
                    local function bat(x2, y2) return im.ImVec2(bpos.x + x2 * S, bpos.y + y2 * S) end
                    grndSpecRR(bdl, bat(0, 0), bat(PW, PH),
                        col32(TH.sidebar[1], TH.sidebar[2], TH.sidebar[3], 247), 14 * S)
                    if bdl.AddRect then
                        pcall(bdl.AddRect, bdl, bat(0.5, 0.5), bat(PW - 0.5, PH - 0.5),
                            col32(TH.line[1], TH.line[2], TH.line[3], TH.line[4] or 255), 14 * S, 0, 1)
                    end
                    local ic = col32(196, 200, 212, 235)
                    local bx = PAD
                    for i, kb in ipairs(kinds) do
                        local key, bw, hint = kb[1], kb[2], kb[3]
                        local by = PAD
                        im.SetCursorPos(im.ImVec2(bx * S, by * S))
                        local clicked = im.InvisibleButton("##grnd_spec_btn" .. i, im.ImVec2(bw * S, BH * S))
                        local hov = (im.IsItemHovered and im.IsItemHovered()) or false
                        local act = (im.IsItemActive and im.IsItemActive()) or false
                        if hov then
                            anyHov = true
                            hovHint = { text = hint, cx = bx + bw / 2 }
                        end
                        local ac = TH.accent
                        local bgc = (act and col32(ac[1], ac[2], ac[3], 255))
                            or (hov and col32(ac[1], ac[2], ac[3], 190)) or col32(31, 28, 41, 235)
                        grndSpecRR(bdl, bat(bx, by), bat(bx + bw, by + BH), bgc, 10 * S)
                        local cx, cy = bx + bw / 2, by + BH / 2
                        if key == "back" then
                            local tw = drawnWb("(Q)", 0.80 * S) / S
                            local gx = cx - (11 + 5 + tw) / 2
                            bdl:AddLine(bat(gx + 5, cy - 5), bat(gx, cy), ic, 1.6)
                            bdl:AddLine(bat(gx, cy), bat(gx + 5, cy + 5), ic, 1.6)
                            bdl:AddLine(bat(gx + 11, cy - 5), bat(gx + 6, cy), ic, 1.6)
                            bdl:AddLine(bat(gx + 6, cy), bat(gx + 11, cy + 5), ic, 1.6)
                            uiText((gx + 16) * S, (cy - 6) * S, "(Q)", c4(TH.textHi), 0.80 * S)
                        elseif key == "fwd" then
                            local tw = drawnWb("(E)", 0.80 * S) / S
                            local gx = cx - (tw + 5 + 11) / 2
                            uiText(gx * S, (cy - 6) * S, "(E)", c4(TH.textHi), 0.80 * S)
                            local x0 = gx + tw + 5
                            bdl:AddLine(bat(x0, cy - 5), bat(x0 + 5, cy), ic, 1.6)
                            bdl:AddLine(bat(x0 + 5, cy), bat(x0, cy + 5), ic, 1.6)
                            bdl:AddLine(bat(x0 + 6, cy - 5), bat(x0 + 11, cy), ic, 1.6)
                            bdl:AddLine(bat(x0 + 11, cy), bat(x0 + 6, cy + 5), ic, 1.6)
                        elseif key == "road" then
                            bdl:AddLine(bat(cx - 5, cy + 9), bat(cx - 2, cy - 9), ic, 1.5)
                            bdl:AddLine(bat(cx + 5, cy + 9), bat(cx + 2, cy - 9), ic, 1.5)
                            bdl:AddLine(bat(cx, cy - 6), bat(cx, cy - 4), ic, 1.8)
                            bdl:AddLine(bat(cx, cy - 1), bat(cx, cy + 1), ic, 1.8)
                            bdl:AddLine(bat(cx, cy + 4), bat(cx, cy + 6), ic, 1.8)
                        elseif key == "diamond" then
                            pcall(bdl.AddQuad, bdl, bat(cx, cy - 9), bat(cx + 9, cy), bat(cx, cy + 9), bat(cx - 9, cy), ic, 1.5)
                            bdl:AddLine(bat(cx - 3, cy + 3), bat(cx - 3, cy - 2), ic, 1.5)
                            bdl:AddLine(bat(cx - 3, cy - 2), bat(cx + 3, cy - 2), ic, 1.5)
                            bdl:AddLine(bat(cx + 0.5, cy - 4.5), bat(cx + 3, cy - 2), ic, 1.5)
                            bdl:AddLine(bat(cx + 3, cy - 2), bat(cx + 0.5, cy + 0.5), ic, 1.5)
                        elseif key == "flag" then
                            local function fat(x2, y2) return im.ImVec2(math.floor(bpos.x + x2 * S + 0.5), math.floor(bpos.y + y2 * S + 0.5)) end
                            local px = cx - 1.5
                            bdl:AddLine(fat(px, cy - 8), fat(px, cy + 8), ic, 1.5)
                            bdl:AddCircleFilled(fat(px, cy - 8), 0.75 * S, ic, 10)
                            bdl:AddCircleFilled(fat(px, cy + 8), 0.75 * S, ic, 10)
                            local fT1, fT2, fT3 = fat(px, cy - 8), fat(px + 6, cy - 5), fat(px, cy - 2)
                            if bdl.AddTriangleFilled then
                                bdl:AddTriangleFilled(fT1, fT2, fT3, ic)
                            elseif bdl.AddTriangle then
                                bdl:AddTriangle(fT1, fT2, fT3, ic, 1.5)
                            else
                                bdl:AddLine(fT1, fT2, ic, 1.5)
                                bdl:AddLine(fT2, fT3, ic, 1.5)
                                bdl:AddLine(fT3, fT1, ic, 1.5)
                            end
                            local U_R, U_CY, U_N = 3.3, cy + 4.2, 120
                            local U_OVER = 0.6
                            for k = 0, U_N do
                                local ang = -U_OVER + (math.pi + 2 * U_OVER) * k / U_N
                                bdl:AddCircleFilled(fat(px + U_R * math.cos(ang), U_CY + U_R * math.sin(ang)), 0.75 * S, ic, 10)
                            end
                        end
                        if clicked then
                            if key == "back" then grndSpecSwitch(-1)
                            elseif key == "fwd" then grndSpecSwitch(1)
                            elseif key == "road" then grndSpecRoadTp(true)
                            elseif key == "diamond" then grndSpecRoadTp(false)
                            elseif key == "flag" then grndSpecGotoTp()
                            end
                        end
                        bx = bx + bw + GAP
                    end
                end
                if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
                grndPopCol(clB)
                grndPopStyle(stB)
                SB.hov = anyHov
                if hovHint then
                    local tw = grndTextW(hovHint.text) * 0.80 * S
                    local HW = math.floor(tw + 20 * S)
                    local HH = math.floor(22 * S)
                    local hx = math.floor(SB.x + hovHint.cx * S - HW / 2)
                    hx = math.max(0, math.min(resX - HW, hx))
                    local hy = SB.y - HH - 6
                    if hy < 0 then hy = SB.y + SH + 6 end
                    im.SetNextWindowPos(im.ImVec2(hx, hy), COND_ALWAYS)
                    im.SetNextWindowSize(im.ImVec2(HW, HH), COND_ALWAYS)
                    local stH, clH = 0, 0
                    if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then stH = stH + 1 end
                    if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 0) then stH = stH + 1 end
                    if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then clH = clH + 1 end
                    if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then clH = clH + 1 end
                    local flagsH = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar",
                        "NoCollapse", "NoFocusOnAppearing", "NoBringToFrontOnFocus", "NoInputs")
                    if grndBegin("##grnd_spec_hint", flagsH) then
                        local hpos = im.GetWindowPos()
                        local hdl = im.GetWindowDrawList()
                        grndSpecRR(hdl, im.ImVec2(hpos.x, hpos.y), im.ImVec2(hpos.x + HW, hpos.y + HH),
                            col32(12, 10, 18, 235), 10 * S)
                        uiText(10 * S, 4 * S, hovHint.text, c4(TH.textHi), 0.80 * S)
                    end
                    if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
                    grndPopCol(clH)
                    grndPopStyle(stH)
                end
            end
            do
                if RC.actionsWinOpen and RC.id ~= nil
                   and RC.actionsWinRcId ~= nil and tonumber(RC.id) ~= RC.actionsWinRcId then
                    RC.actionsWinOpen = false
                    RC.actSubPopup = nil
                end
                if RC.actionsWinOpen and RC.show then
                    local A = {}
                    A.items = (GRND_PUN and GRND_PUN.actions) or {
                        "Выдать ХП", "Выдать броню", "Подбросить", "Заспавнить", "Заморозить", "Разморозить",
                        "Починить т/с", "Перевернуть т/с", "Заправить т/с", "Заспавнить т/с", "ТП на дорогу", "ТП к игроку",
                        "ТП игрока к себе", "Оружие", "Отобрать все оружие", "Статистика", "Активные наказания", "Лицензии",
                        "Сообщить в /a",
                    }
                    if #A.items < 1 then
                        RC.actionsWinOpen = false
                    else
                    A.lo = grndActLayout(A.items, math.min(resX - 24, 960))
                    A.pillH = A.lo.btn + 14
                    A.hintH = 22
                    A.pad = 12
                    A.subH = 0
                    if RC.actSubPopup == "hp" or RC.actSubPopup == "arm" or RC.actSubPopup == "fuel" then
                        A.subH = 76
                    elseif RC.actSubPopup == "report_a" then
                        A.subH = 58
                    end
                    A.aw = A.lo.w + 16
                    if A.subH > 0 and A.aw < 704 then A.aw = 704 end
                    A.subY = A.hintH + A.lo.stripH + 2
                    A.ah = A.hintH + A.lo.stripH + ((A.subH > 0) and (A.subH + 4) or 0) + 2
                    local anchorX = tonumber(RC.actionsWinAnchorX)
                    local anchorY = tonumber(RC.actionsWinAnchorY)
                    local circleY = tonumber(RC.actionsWinCircleY)
                    if RC.actionsWinUser and tonumber(RC.savedActionsWinX)
                       and tonumber(RC.savedActionsWinY) then
                        A.ax = tonumber(RC.savedActionsWinX)
                        A.ay = tonumber(RC.savedActionsWinY)
                    elseif anchorX and anchorY then
                        A.ax = math.floor(anchorX - A.aw / 2)
                        A.ay = anchorY
                        if A.ay + A.ah > resY - 6 then
                            A.ay = (circleY or anchorY) - 18 - A.ah - 10
                        end
                    else
                        A.ax = math.floor((resX - A.aw) / 2)
                        A.ay = math.max(30, resY - A.ah - 150)
                    end
                    A.ax = math.max(4, math.min(resX - A.aw - 4, A.ax))
                    A.ay = math.max(4, math.min(resY - A.ah - 4, A.ay))
                    RC.actionsWinX, RC.actionsWinY = A.ax, A.ay
                    RC.actionsWinRect = { x = A.ax, y = A.ay, w = A.aw, h = A.ah }
                    A.inPanel, A.inPill = false, false
                    A.inHint = grndMouseInside({ x = A.ax + 3, y = A.ay + 2,
                        w = A.aw - 6, h = A.hintH - 4 })
                    if A.inHint then A.inPanel = true end
                    for r = 1, #A.lo.rows do
                        local row = A.lo.rows[r]
                        if grndMouseInside({ x = A.ax + row.x, y = A.ay + A.hintH + row.y,
                                w = row.w, h = A.pillH }) then
                            A.inPanel, A.inPill, A.row = true, true, row
                        end
                    end
                    if A.subH > 0 and grndMouseInside({ x = A.ax + A.pad, y = A.ay + A.subY + 3,
                            w = A.aw - A.pad * 2, h = A.subH - 6 }) then
                        A.inPanel = true
                    end
                    if RC.cursor and GRND_MOUSE.down and not RC.actDragging
                       and (A.inPill or A.inHint) then
                        A.onBtn = false
                        if A.inPill and A.row then
                            for k = 1, #A.row.btns do
                                local b = A.row.btns[k]
                                if grndMouseInside({ x = A.ax + b.x, y = A.ay + A.hintH + A.row.y + 5,
                                        w = A.lo.btn, h = A.lo.btn }) then
                                    A.onBtn = true
                                end
                            end
                        end
                        if not A.onBtn then
                            RC.actDragging = true
                            RC.actDragDX = GRND_MOUSE.x - A.ax
                            RC.actDragDY = GRND_MOUSE.y - A.ay
                        end
                    end
                    if RC.actDragging then
                        if not (GRND_MOUSE and GRND_MOUSE.down) then
                            RC.actDragging = false
                            RC.actionsWinUser = true
                            RC.savedActionsWinX, RC.savedActionsWinY = RC.actionsWinX, RC.actionsWinY
                            if GRND_PUN and GRND_PUN.save then
                                GRND_PUN.cfgDirty = true
                                pcall(GRND_PUN.save)
                            end
                        else
                            A.ax = math.max(4, math.min(resX - A.aw - 4, GRND_MOUSE.x - (RC.actDragDX or 0)))
                            A.ay = math.max(4, math.min(resY - A.ah - 4, GRND_MOUSE.y - (RC.actDragDY or 0)))
                            RC.actionsWinX, RC.actionsWinY = A.ax, A.ay
                        end
                    end
                    if RC.cursor and not RC.actDragging and not A.inPanel
                       and (os.clock() - (RC.actionsWinAt or 0)) > 0.25
                       and type(grndLeftClickPending) == "function" and grndLeftClickPending() then
                        RC.actionsWinOpen = false
                        RC.actSubPopup = nil
                    end
                    if RC.actionsWinFocus then
                        RC.actionsWinFocus = false
                        if im.SetNextWindowFocus then
                            pcall(im.SetNextWindowFocus)
                        end
                    end
                    im.SetNextWindowPos(im.ImVec2(A.ax, A.ay), COND_ALWAYS)
                    im.SetNextWindowSize(im.ImVec2(A.aw, A.ah), COND_ALWAYS)
                    local stA, clA = 0, 0
                    if grndPushStyleV2(im.StyleVar and im.StyleVar.WindowPadding, 0, 0) then stA = stA + 1 end
                    if grndPushStyleF(im.StyleVar and im.StyleVar.WindowRounding, 12) then stA = stA + 1 end
                    if grndPushCol(im.Col and im.Col.WindowBg, rgba(0, 0, 0, 0)) then clA = clA + 1 end
                    if grndPushCol(im.Col and im.Col.Border, rgba(0, 0, 0, 0)) then clA = clA + 1 end
                    local flagsA = wf("NoTitleBar", "NoResize", "NoMove", "NoScrollbar", "NoCollapse")
                    if (not RC.cursor) or (menu and menu.open) then
                        flagsA = flagsA + wflag("NoInputs")
                    end
                    A.tip = nil
                    A.tipX = 0
                    if grndBegin("##grnd_recon_actions", flagsA) then
                        if im.BringWindowToDisplayFront then
                            pcall(im.BringWindowToDisplayFront, im.GetCurrentWindow())
                        end
                        if im.SetWindowFocus then
                            pcall(im.SetWindowFocus)
                        end
                        local apos = im.GetWindowPos()
                        local adl = im.GetWindowDrawList()
                        local function aat(x2, y2) return im.ImVec2(apos.x + x2, apos.y + y2) end
                        local function afill(x2, y2, w2, h2, c, r)
                            roundRect(adl, aat(x2, y2), aat(x2 + w2, y2 + h2), c, r or 0)
                        end
                        local function aframe(x2, y2, w2, h2, c, r)
                            if adl.AddRect then
                                pcall(adl.AddRect, adl, aat(x2, y2), aat(x2 + w2, y2 + h2),
                                    c, r or 0, 0, 1.0)
                            end
                        end
                        for r = 1, #A.lo.rows do
                            local row = A.lo.rows[r]
                            local ry = A.hintH + row.y
                            afill(row.x + 2, ry + 3, row.w, A.pillH, col32(0, 0, 0, 65), 12)
                            afill(row.x, ry, row.w, A.pillH, col32(10, 14, 20, 236), 12)
                            aframe(row.x + 0.5, ry + 0.5, row.w - 1, A.pillH - 1,
                                col32(255, 255, 255, 24), 12)
                            for k = 1, #row.divs do
                                pcall(adl.AddLine, adl, aat(row.divs[k], ry + 8),
                                    aat(row.divs[k], ry + A.pillH - 8), col32(255, 255, 255, 74), 1.2)
                            end
                            for k = 1, #row.btns do
                                local b = row.btns[k]
                                local rawLabel = tostring(A.items[b.i])
                                local subKey = grndActSubKey(rawLabel)
                                local bx, by = b.x, ry + 5
                                im.SetCursorPos(im.ImVec2(bx, by))
                                local bClicked = im.InvisibleButton("##act_" .. tostring(r) .. "_" .. tostring(k),
                                    im.ImVec2(A.lo.btn, A.lo.btn))
                                local bHov = (im.IsItemHovered and im.IsItemHovered()) or false
                                local bAct = (im.IsItemActive and im.IsItemActive()) or false
                                local isSub = (subKey ~= nil and RC.actSubPopup == subKey)
                                local hot = isSub or bHov or bAct
                                afill(bx + 1, by + 2, A.lo.btn, A.lo.btn, col32(0, 0, 0, 70), 9)
                                afill(bx, by, A.lo.btn, A.lo.btn,
                                    isSub and col32(TH.accent[1], TH.accent[2], TH.accent[3], 62)
                                        or (bAct and col32(TH.accent[1], TH.accent[2], TH.accent[3], 72)
                                            or (bHov and col32(TH.accent[1], TH.accent[2], TH.accent[3], 46)
                                                or col32(255, 255, 255, 18))), 9)
                                aframe(bx + 0.5, by + 0.5, A.lo.btn - 1, A.lo.btn - 1,
                                    isSub and col32(TH.accent[1], TH.accent[2], TH.accent[3], 190)
                                        or (bAct and col32(TH.accent[1], TH.accent[2], TH.accent[3], 215)
                                            or (bHov and col32(TH.accent[1], TH.accent[2], TH.accent[3], 170)
                                                or col32(255, 255, 255, 34))), 9)
                                if adl.AddLine then
                                    pcall(adl.AddLine, adl, aat(bx + 7, by + 1.6),
                                        aat(bx + A.lo.btn - 7, by + 1.6),
                                        col32(255, 255, 255, hot and 46 or 20), 1.0)
                                end
                                if type(_G.grndDrawActIcon) == "function" then
                                    _G.grndDrawActIcon(adl, aat, grndActIconKey(rawLabel),
                                        bx + A.lo.btn / 2, by + A.lo.btn / 2, A.lo.btn - 10,
                                        (isSub or bHov or bAct) and col32(247, 250, 255, 252)
                                            or col32(206, 214, 228, 238))
                                end
                                if bHov then
                                    A.tip = rawLabel:gsub("\n", " ")
                                    A.tipX = bx + A.lo.btn / 2
                                end
                                if bClicked then
                                    local cleanLabel = rawLabel:gsub("\n", " ")
                                    local tid = tonumber(RC.actTargetId) or tonumber(RC.id)
                                        or (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id))
                                    local tNick = (RC.actTargetNick and RC.actTargetNick ~= "") and RC.actTargetNick
                                        or (RC.nick and RC.nick ~= "" and RC.nick) or ("ID " .. tostring(tid or 0))
                                    if _G.grndHandleActionBtn then
                                        _G.grndHandleActionBtn(cleanLabel, tid, tNick, RC.actTargetPed)
                                    end
                                    if not subKey then
                                        RC.actionsWinOpen = false
                                        RC.actSubPopup = nil
                                    end
                                end
                            end
                        end
                        if A.tip then
                            local tw = drawnWb(A.tip, 0.86)
                            local tx = A.tipX - tw / 2
                            tx = math.max(6, math.min(A.aw - tw - 6, tx))
                            uiText(tx, 3, A.tip, c4(TH.textHi), 0.86)
                        end
                        if A.subH > 0 and _G.grndDrawActSubPopup then
                            A.subWas = RC.actSubPopup
                            local tid = tonumber(RC.actTargetId) or tonumber(RC.id)
                                or (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id))
                            local tNick = (RC.actTargetNick and RC.actTargetNick ~= "") and RC.actTargetNick
                                or (RC.nick and RC.nick ~= "" and RC.nick) or ("ID " .. tostring(tid or 0))
                            local okSub, errSub = pcall(_G.grndDrawActSubPopup, RC, TH, tid, tNick,
                                RC.actTargetPed, apos, adl, aat, afill, aframe, A.aw, A.pad, A.subY, A.subH,
                                { imgui = im, uiText = uiText, c4 = c4, col32 = col32, drawnWb = drawnWb })
                            if not okSub then
                                RC.actSubError = tostring(errSub)
                                if logRenderErr then logRenderErr("act_sub", errSub) end
                            end
                            if RC.actSubError and RC.actSubError ~= RC.actSubErrShown then
                                RC.actSubErrShown = RC.actSubError
                                if notify and notify.add then
                                    pcall(notify.add, "Подпанель действий: " .. tostring(RC.actSubError), "error", 6)
                                end
                                print("{FF6666}[GRND]{FFFFFF} подпанель действий: " .. tostring(RC.actSubError))
                            end
                            if A.subWas and not RC.actSubPopup
                               and grndMouseInside({ x = A.ax + A.pad, y = A.ay + A.subY + 3,
                                     w = A.aw - A.pad * 2, h = A.subH - 6 }) then
                                RC.actionsWinOpen = false
                            end
                        end
                    end
                    if endDepth > 0 then endDepth = endDepth - 1; pcall(im.End) end
                    grndPopCol(clA)
                    grndPopStyle(stA)
                    end
                end
            end
            if RC.punQuick then
                grndReconQuickPunishDraw(RC, im, resX, resY,
                    wf("NoTitleBar", "NoResize", "NoCollapse", "NoSavedSettings"),
                    COND_ALWAYS, TH, col32, rgba, uiText, c4)
            end
            return (RC.cursor or RC.actionsWinOpen or RC.punQuick
                or EDGE.lOpen or EDGE.rOpen) and true or false
        end
        function drawReconHint()
            pcall(drawReconHintDx)
            return false
        end
        function drawReconHintDx()
            local R = GRND_RC
            if not R or not R.show then return end
            if type(renderFontDrawText) ~= "function" then return end
            local hintPx = 10
            if R.hintBarFontPx ~= hintPx then
                R.hintBarFont, R.hintW = nil, nil
                R.hintBarFontPx = hintPx
            end
            if not R.hintBarFont and type(renderCreateFont) == "function" then
                for _, arg in ipairs({
                    { "Tahoma", -hintPx, 1, 204 },
                    { "Tahoma", -hintPx, 5, 204 },
                    { "Arial", -hintPx, 1, 204 },
                    { "Tahoma", -hintPx },
                }) do
                    local okF, f = pcall(renderCreateFont, unpack(arg))
                    if okF and f then R.hintBarFont = f; break end
                end
            end
            if not R.hintBarFont then R.hintBarFont = R.hintFont end
            if not R.hintBarFont then return end
            local sx, sy = getScreenResolution()
            local hint = "Чтобы включить/выключить курсор, нажмите ПКМ."
            local text = hint
            if type(grndToAnsi) == "function" then
                local okA, out = pcall(grndToAnsi, text)
                if okA and type(out) == "string" then text = out end
            end
            local tw = R.hintW
            if not tw then
                if type(renderGetFontDrawTextSize) == "function" then
                    local okW, w = pcall(renderGetFontDrawTextSize, R.hintBarFont, text)
                    if okW and type(w) == "number" and w > 10 then tw = math.floor(w) end
                end
                if not tw then tw = #text * 10 end
                R.hintW = tw
            end
            local x = sx - tw - 14
            if x < 4 then x = 4 end
            local y = sy - 26
            if y < 4 then y = 4 end
            pcall(renderFontDrawText, R.hintBarFont, text, x + 1, y + 1, 0x78000000)
            pcall(renderFontDrawText, R.hintBarFont, text, x, y, 0xC8C4CAD2)
        end
        function drawReconFallback()
            local RC = GRND_RC
            local hasData = RC and RC.live and (RC.live.id or RC.live.weap
                or RC.live.hp or RC.live.ping)
            if not RC or (not RC.show and not hasData) then return end
            local function reconUtf(v)
                v = tostring(v or "")
                if type(grndToUtf) == "function" then
                    local ok, out = pcall(grndToUtf, v)
                    if ok and type(out) == "string" then return out end
                end
                return v
            end
            local recentImgui = RC.imguiHealthy and RC.imguiLastAt
                and (os.clock() - RC.imguiLastAt < 0.5)
            if recentImgui and not RC.drawError then return end
            if type(renderFontDrawText) ~= "function" then return end
            local resX, resY = getScreenResolution()
            local W, H = 350, 274
            local x, y = resX - W - 22, 92
            local font = RC.fallbackFont
            if not font and type(renderCreateFont) == "function" then
                local okF, f = pcall(renderCreateFont, "Tahoma", -14, 1, 204)
                if okF and f then
                    font = f
                    RC.fallbackFont = f
                end
            end
            if not font then return end
            local function val(k, fallback)
                local v = RC.live and RC.live[k]
                if v == nil or tostring(v) == "" then return fallback or "—" end
                return reconUtf(v)
            end
            local function drawText(text, tx, ty, color, scale)
                local s = reconUtf(tostring(text or ""))
                if type(grndToAnsi) == "function" then s = grndToAnsi(s) end
                pcall(renderFontDrawText, font, s, x + tx, y + ty, color)
            end
            local function box(bx, by, bw, bh, color)
                if type(renderDrawBox) == "function" then
                    pcall(renderDrawBox, x + bx, y + by, bw, bh, color)
                end
            end
            box(4, 5, W, H, 0x60000000)
            box(0, 0, W, H, 0xE60B0F16)
            drawText("GRND  /  RECON", 16, 12, 0xFF00D6AA)
            drawText(val("id", RC.id and ("ID " .. tostring(RC.id)) or "ID —"), 236, 12, 0xFFDDE8F2)
            drawText(reconUtf(RC.nick or "Игрок"), 16, 34, 0xFFFFFFFF)
            drawText("GUN: " .. val("weap"), 16, 66, 0xFFE9EDF6)
            drawText("AMMO: " .. val("ammo"), 188, 66, 0xFFE9EDF6)
            drawText("PING: " .. val("ping"), 16, 91, 0xFFE9EDF6)
            drawText("AFK: " .. val("afk", "0"), 188, 91, 0xFFF79248)
            drawText("HP: " .. val("hp"), 16, 116, 0xFFFFFFFF)
            drawText("ARM: " .. val("arm"), 188, 116, 0xFFFFFFFF)
            drawText("FRACTION: " .. val("frac"), 16, 141, 0xFFE9EDF6)
            drawText("SPEED: " .. val("speed", "0"), 16, 166, 0xFFE9EDF6)
            box(16, 198, W - 32, 1, 0x35FFFFFF)
            drawText("Интерфейс реконa загружен", 16, 216, 0xFF8C94A6)
        end
        _G.grndReconFallback = drawReconFallback
        local function drawAll()
            renderedOnce = true
            _G.GRND_IMGUI_ALIVE = true
            if T_frames() == 0 then
                grndTraceFrames(1)
                grndTrace("imgui", "ПЕРВЫЙ отрисованный кадр — рендер жив")
            else
                grndTraceFrames(1)
            end
            local now = os.clock()
            local dt  = now - (menu.lastFrame or now)
            menu.lastFrame = now
            if dt < 0 or dt > 0.25 then dt = 0.016 end
            local gated = grndUiBlocked()
            if gated then
                GRND_GATE.blockedFrames = (GRND_GATE.blockedFrames or 0) + 1
                if grndUiWantsToShow() then
                    GRND_GATE.suppressed = (GRND_GATE.suppressed or 0) + 1
                    if _G.GRND_REP then _G.GRND_REP.open = false end
                    if _G.GRND_QR then
                        _G.GRND_QR.pickOpen = false
                        if type(_G.GRND_QR.pun) == "table" then _G.GRND_QR.pun.pickOpen = false end
                    end
                end
            end
            local wantCursor = false
            -- Сначала рисуем перемещаемые чекеры/часы как нижний слой. Окна
            -- приложения ниже перекроют их фоном, а не заставят чекер исчезать.
            if GRND_CLOCK and (GRND_CLOCK.enabled or GRND_CLOCK.moving) then
                local ok, e = pcall(drawDateTimeOverlay)
                if not ok then logRenderErr("clock", e)
                elseif e then wantCursor = true end
            end
            if not gated and GRND_KL then
                local ok, e = pcall(drawKillList, dt)
                if not ok then logRenderErr("killlist", e)
                elseif e then wantCursor = true end
            end
            if not gated and GRND_AO then
                local ok, e = pcall(drawAdminsOnline, dt)
                if not ok then logRenderErr("admins", e)
                elseif e then wantCursor = true end
            end
            if not gated and type(_G.grndDrawWeekStatsHud) == "function" then
                local okW, eW = pcall(_G.grndDrawWeekStatsHud, dt)
                if not okW then logRenderErr("weekstats", eW)
                elseif eW then wantCursor = true end
            end
            if GRND_FCHAT then
                if type(grndFarChatEnsureHooks) == "function" then
                    pcall(grndFarChatEnsureHooks)
                end
                if type(grndFarChatTick) == "function" then pcall(grndFarChatTick) end
                GRND_FCHAT.gated = gated and true or false
                local ok, e = pcall(drawFarChat, dt)
                if not ok then
                    GRND_FCHAT.lastErr = tostring(e)
                    logRenderErr("far_chat", e)
                elseif e then wantCursor = true end
            end
            if GRND_SFR then
                if type(grndSfrEnsureHooks) == "function" then pcall(grndSfrEnsureHooks) end
                GRND_SFR.gated = gated and true or false
                local ok, e = pcall(drawSoftRate, dt)
                if not ok then
                    GRND_SFR.lastErr = tostring(e)
                    logRenderErr("softcheck", e)
                elseif e then wantCursor = true end
            end
            -- выстрелы по патронам считаем и когда окна скрипта заблокированы
            -- серверным диалогом: события всё равно приходят
            if type(grndSfrPollAmmo) == "function" then
                local okA, errA = pcall(grndSfrPollAmmo)
                if not okA then GRND_SFR.stat.err = "патроны: " .. tostring(errA) end
            end
            if type(grndSfrPollFire) == "function" then
                local okF, errF = pcall(grndSfrPollFire)
                if not okF then GRND_SFR.stat.err = "ЛКМ: " .. tostring(errF) end
            end
            if menu.open or menu.anim > 0 then
                local ok, e = pcall(drawMenu, dt)
                if not ok then
                    pcall(grndEnds)
                    logRenderErr("menu", e)
                elseif menu.open then wantCursor = true end
            elseif type(_G.grndBrowserTick) == "function" then
                pcall(_G.grndBrowserTick, false, nil)
            end
            if GRND_TAB.open or scoreboard.anim > 0 then
                local ok, e = pcall(drawScoreboard, dt)
                if not ok then logRenderErr("scoreboard", e)
                elseif e then wantCursor = true end
            end
            if #queue > 0 then
                local ok, e = pcall(drawToasts)
                if not ok then logRenderErr("toast", e) end
            end
            if not gated and type(_G.grndDrawCapsules) == "function" then
                local okC, eC = pcall(_G.grndDrawCapsules, dt)
                if not okC then logRenderErr("capsules", eC) end
            end
            if not gated and type(_G.grndDrawCustomDialog) == "function" then
                local okD, eD = pcall(_G.grndDrawCustomDialog, dt)
                if not okD then logRenderErr("custom_dlg", eD)
                elseif eD then wantCursor = true end
            end
            local specTargetId = (GRND_SPEC and GRND_SPEC.active)
                and tonumber(GRND_SPEC.id) or nil
            if not gated and GRND_RC then
                if specTargetId then
                    GRND_RC.id = specTargetId
                    GRND_RC.show = true
                end
                if GRND_RC.show or specTargetId
                    or (GRND_RC.live and (GRND_RC.live.id or GRND_RC.live.weap
                        or GRND_RC.live.hp or GRND_RC.live.ping)) then
                    local ok, e = pcall(_G.GRND_RECON_UI.draw)
                    if not ok then
                        GRND_RC.drawError = tostring(e)
                        logRenderErr("recon", e)
                    elseif e then
                        wantCursor = true
                    end
                end
            end
            if not gated and GRND_CATCH and GRND_CATCH.active then
                local ok, e = pcall(drawCatchWindow)
                if not ok then logRenderErr("catch", e) end
            end
            if not gated and GRND_REPHUD and GRND_REPHUD.enabled then
                local ok, e = pcall(drawReportHud)
                if not ok then logRenderErr("rephud", e)
                elseif e then wantCursor = true end
            end
            if not gated and GRND_REP and GRND_REP.open then
                local ok, e = pcall(drawReportWindow)
                if not ok then logRenderErr("report", e)
                elseif e then wantCursor = true end
            end
            if not gated and type(_G.grndQrPickerDraw) == "function" then
                local qrCtx = {
                    im = im, always = COND_ALWAYS, wf = wf, begin = grndBegin,
                    uiText = uiText, roundRect = roundRect, col32 = col32,
                    rgba = rgba, c4 = c4, gradRect = gradRect, drawnW = drawnWb,
                    pushCol = grndPushCol, popCol = grndPopCol,
                    pushVarF = grndPushStyleF, pushVarV2 = grndPushStyleV2,
                    popVar = grndPopStyle,
                }
                local ok, e = pcall(_G.grndQrPickerDraw, qrCtx)
                if not ok then logRenderErr("quick_reply", e)
                elseif e then wantCursor = true end
                if type(_G.grndQrPunPickerDraw) == "function" then
                    local okP, eP = pcall(_G.grndQrPunPickerDraw, qrCtx)
                    if not okP then logRenderErr("punish_reply", eP)
                    elseif eP then wantCursor = true end
                end
            end
            if not gated and _G.GRND_FORMS and _G.GRND_FORMS.active then
                local ok, e = pcall(drawFormPopup)
                if not ok then logRenderErr("forms", e) end
            end
            if not gated and GRND_RC and GRND_RC.statsPop and _G.grndDrawStatsPopup then
                local ok, e = pcall(_G.grndDrawStatsPopup)
                if not ok then logRenderErr("stats_pop", e)
                elseif e and ((GRND_RC and GRND_RC.cursor) or menu.open) then wantCursor = true end
            end
            if not gated and _G.GRND_GNEWS and _G.GRND_GNEWS.active then
                local ok, e = pcall(drawGnewsPopup)
                if not ok then logRenderErr("gnews", e)
                elseif e and ((GRND_RC and GRND_RC.cursor) or menu.open) then wantCursor = true end
            end
            if GRND_LOG.wanted() then
                local depth=endDepth
                local ok,result=pcall(GRND_LOG.windows,{
                    im=im,begin=grndBegin,flags=wf('NoTitleBar','NoCollapse','NoResize'),
                    once=(im.Cond and im.Cond.Once) or 2,always=COND_ALWAYS,
                    push=grndPushCol,pop=grndPopCol,color=c4,color32=c32,
                    finish=function() if endDepth>depth then endDepth=endDepth-1;im.End() end end,
                    recover=function() while endDepth>depth do endDepth=endDepth-1;pcall(im.End) end end
                })
                if not ok then GRND_LOG.warn(result,'viewer');logRenderErr('chat_logs',result) elseif result then wantCursor=true end
            end
            if GRND_INPUT.active() then
                local depth=endDepth
                local ok,e=pcall(GRND_INPUT.draw,{
                    im=im,begin=grndBeginTransparent,always=COND_ALWAYS,
                    flags=wf('NoTitleBar','NoResize','NoMove','NoScrollbar','NoScrollWithMouse',
                        'NoCollapse','NoSavedSettings','NoInputs','NoNavInputs','NoNavFocus',
                        'NoFocusOnAppearing','NoBringToFrontOnFocus'),
                    text=uiText,measure=drawnWb,col32=col32,rgba=rgba,roundRect=roundRect,
                    pushFont=uiPushFont,popFont=uiPopFont,
                    finish=function()
                        while endDepth>depth do endDepth=endDepth-1;pcall(im.End) end
                    end,
                })
                if not ok then pcall(grndEnds);logRenderErr('native_input_overlay',e) end
            end
            return wantCursor
        end
        local renderRegistered = false
        local function setupRender()
            if renderRegistered then
                if imKind == "moonimgui" then im.Process = true end
                return
            end
            renderRegistered = true
            uiFontRegister()
            local function installShotHook()
                local shotPA = QR and QR.punAuto
                if type(shotPA) == "table" and type(shotPA.shotRender) == "function" then
                    _G.grndShotFrame = shotPA.shotRender
                    _G.grndShotWant = function() return shotPA.shotJob ~= nil end
                    shotPA.shotFrameHook = true
                    return true
                end
                return false
            end
            _G.grndShotHookInstall = installShotHook
            installShotHook()
            local function safeDraw()
                local ok, res = pcall(drawAll)
                if ok then return res end
                pcall(grndEnds)
                _G.GRND_IMGUI_ALIVE = false
                logRenderErr("frame", res)
                return false
            end
            local function syncIoFlags()
                local io3 = grndSafeGetIO(im)
                if io3 then
                    GRND_KEYS.imguiText = (io3.WantTextInput and true) or false
                    GRND_KEYS.imguiCaptureMouse = (io3.WantCaptureMouse and true) or false
                    GRND_KEYS.imguiCaptureKeyboard = (io3.WantCaptureKeyboard and true) or false
                end
            end
            if imKind == "moonimgui" then
                im.OnDrawFrame = function()
                    _G.GRND_IMGUI_IN_FRAME = true
                    local okFrame, errFrame = pcall(function()
                        if _G.grndShotFrame ~= nil then pcall(_G.grndShotFrame) end
                        pcall(grndFovRenderTick)
                        GRND_UIFRAME = (GRND_UIFRAME or 0) + 1
                        pcall(grndMouseFrameBegin)
                        endDepth, styleDepth, colorDepth = 0, 0, 0
                        if GRND_MOUSE.clicked or GRND_MOUSE.rclicked then
                            GRND_MOUSE.pending = true
                        else
                            GRND_MOUSE.pending = false
                        end
                        syncIoFlags()
                        local rcLock = (GRND_RC and GRND_RC.show and not GRND_RC.cursor) and true or false
                        local cursorWanted = safeDraw() or (plainCursorOn and not rcLock)
                            or ((clw ~= nil) and clw.aiming)
                            or (GRND_KL and GRND_KL.moving)
                            or (GRND_AO and GRND_AO.moving)
                            or (GRND_WEEKSTATS and GRND_WEEKSTATS.moving)
                            or (GRND_RC and GRND_RC.show and GRND_RC.cursor)
                            or false
                        GRND_KEYS.cursorOn = cursorWanted and true or false
                        im.ShowCursor = cursorWanted
                        if type(grndCursorClipTick) == "function" then
                            pcall(grndCursorClipTick, cursorWanted)
                        end
                    end)
                    _G.GRND_IMGUI_IN_FRAME = false
                    if not okFrame then logRenderErr("moonimgui_frame", errFrame) end
                end
                im.Process = true
            else
                im.OnFrame(
                    function()
                        local formUi = false
                        if type(_G.grndFormsUiWanted) == "function" then
                            formUi = _G.grndFormsUiWanted() and true or false
                        elseif _G.GRND_FORMS and _G.GRND_FORMS.active then
                            formUi = true
                        end
                        local want = GRND_INPUT.wanted() or GRND_LOG.wanted() or menu.open or menu.anim > 0 or #queue > 0 or GRND_TAB.open
                            or (_G.grndShotWant ~= nil and _G.grndShotWant() == true)
                            or scoreboard.anim > 0
                            or (GRND_KL and (GRND_KL.enabled or GRND_KL.moving))
                            or (GRND_AO and (GRND_AO.enabled or GRND_AO.moving))
                            or (GRND_WEEKSTATS and (GRND_WEEKSTATS.hudOn or GRND_WEEKSTATS.moving))
                            or (GRND_CAP_NOTIFY and GRND_CAP_NOTIFY.items and #GRND_CAP_NOTIFY.items > 0)
                            or (GRND_CUSTOM_DLG and GRND_CUSTOM_DLG.wantUi and GRND_CUSTOM_DLG.wantUi())
                            or (GRND_SFR and (GRND_SFR.enabled or GRND_SFR.moving))
                            or (GRND_FCHAT and (GRND_FCHAT.enabled or GRND_FCHAT.moving))
                            or (GRND_REP and GRND_REP.open)
                            or (GRND_REPHUD and GRND_REPHUD.enabled)
                            or (GRND_RC and GRND_RC.show)
                            or (GRND_CATCH and GRND_CATCH.active)
                            or formUi
                            or (_G.grndGnewsUiWanted and _G.grndGnewsUiWanted())
                            or (GRND_CLOCK and (GRND_CLOCK.enabled or GRND_CLOCK.moving))
                            or plainCursorOn or ((clw ~= nil) and clw.aiming)
                        if not want then
                            GRND_KEYS.imguiText = false
                            GRND_KEYS.imguiCaptureMouse = false
                            GRND_KEYS.imguiCaptureKeyboard = false
                            if type(_G.grndBrowserTick) == "function" then
                                pcall(_G.grndBrowserTick, false, nil)
                            end
                        end
                        return want and true or false
                    end,
                    function(self)
                        _G.GRND_IMGUI_IN_FRAME = true
                        local okFrame, errFrame = pcall(function()
                            if _G.grndShotFrame ~= nil then pcall(_G.grndShotFrame) end
                            GRND_UIFRAME = (GRND_UIFRAME or 0) + 1
                            pcall(grndMouseFrameBegin)
                            endDepth, styleDepth, colorDepth = 0, 0, 0
                            syncIoFlags()
                            local want = safeDraw()
                            local rcLock = (GRND_RC and GRND_RC.show and not GRND_RC.cursor) and true or false
                            local cursorWanted = want or (plainCursorOn and not rcLock)
                                or ((clw ~= nil) and clw.aiming)
                                or (GRND_KL and GRND_KL.moving)
                                or (GRND_AO and GRND_AO.moving)
                                or (GRND_WEEKSTATS and GRND_WEEKSTATS.moving)
                                or (GRND_RC and GRND_RC.show and GRND_RC.cursor)
                            GRND_KEYS.cursorOn = cursorWanted and true or false
                            if self then self.HideCursor = not cursorWanted end
                            if type(grndCursorClipTick) == "function" then
                                pcall(grndCursorClipTick, cursorWanted)
                            end
                        end)
                        _G.GRND_IMGUI_IN_FRAME = false
                        if not okFrame then logRenderErr("mimgui_frame", errFrame) end
                    end
                )
                pcall(im.OnFrame,
                    function()
                        return (GRND_CAM and GRND_CAM.fovOn == true)
                            or (_G.grndShotWant ~= nil and _G.grndShotWant() == true)
                    end,
                    function(self)
                        _G.GRND_IMGUI_IN_FRAME = true
                        if _G.grndShotFrame ~= nil then pcall(_G.grndShotFrame) end
                        pcall(grndFovRenderTick)
                        if self then self.HideCursor = true end
                        _G.GRND_IMGUI_IN_FRAME = false
                    end)
            end
        end
        ensureRender = function(force)
            setupRender()
            if force and imKind == "moonimgui" then im.Process = true end
        end
        ensureToasts = ensureRender
        _G.grndEnsureRender = ensureRender
        addEventHandler('onD3DDeviceReset', function()
            ensureRender(true)
        end)
        pcall(addEventHandler, 'onD3DPresent', function()
            pcall(grndFovRenderTick)
            -- список SOFT рисуем напрямую в кадр: без ImGui-окна он виден всегда
            if type(grndSfrDrawNative) == "function" then
                pcall(grndSfrDrawNative)
            end
            if type(grndFarChatDrawNative) == "function" then
                pcall(grndFarChatDrawNative)
            end
        end)
        function notify.add(text, kind, life, force)
            kind = tostring(kind or "info")
            if kind == "success" then kind = "ok"
            elseif kind == "warning" then kind = "warn"
            elseif kind == "loading" then kind = "progress" end
            if kind ~= "ok" and kind ~= "warn" and kind ~= "error"
                and kind ~= "progress" then kind = "info" end
            if not force and type(_G.grndSessionReady) == "function" then
                local okReady, ready = pcall(_G.grndSessionReady)
                if okReady and not ready then return false end
            end
            local message = tostring(text or "")
            if message == "" then return false end
            life = math.max(1, math.min(10, tonumber(life) or 3.5))
            local now = os.clock()
            local function enqueueToast()
                for i = #queue, math.max(1, #queue - 5), -1 do
                    local item = queue[i]
                    if item.kind == kind and item.text == message
                        and now >= item.start and now - item.start <= 0.9 then
                        item.start, item.life, item.alpha = now, life, 1
                        if imKind == "moonimgui" then im.Process = true end
                        return true
                    end
                end
                nextId = nextId + 1
                if #queue >= 8 then
                    local rank = { info = 1, progress = 1, ok = 2, warn = 3, error = 4 }
                    local drop, dropRank
                    for i = 1, #queue do
                        local r = rank[queue[i].kind] or 1
                        if not dropRank or r < dropRank then drop, dropRank = i, r end
                    end
                    if not drop or (dropRank or 1) > (rank[kind] or 1) then return false end
                    table.remove(queue, drop)
                end
                queue[#queue + 1] = {
                    id = nextId, text = message, kind = kind,
                    life = life, start = now, alpha = 1,
                    force = force and true or false,
                }
                if imKind == "moonimgui" then im.Process = true end
                return true
            end
            if not renderedOnce or _G.GRND_IMGUI_ALIVE == false then
                if force and im and imKind then
                    local queued = enqueueToast()
                    pcall(ensureRender, true)
                    if imKind == "moonimgui" then im.Process = true end
                    return queued
                end
                local oldChat = notify.chat
                notify.chat = true
                pcall(notify.say, message, kind)
                notify.chat = oldChat
                return false
            end
            return enqueueToast()
        end
        _G.GRND_IM = im
        _G.GRND_IM_KIND = imKind
        GRND_REF.im, GRND_REF.menu, GRND_REF.clw = im, menu, clw
        GRND_REF.clwSetAiming = clwSetAiming
        GRND_REF.clwApplyAim = clwApplyAim
        GRND_REF.gm, GRND_REF.spec = GRND_GM, GRND_SPEC
        GRND_REF.ensureRender = function(f) ensureRender(f) end
        ensureRender()
        IMGUI_WRAP = (imKind == "moonimgui") and "MoonImGui" or "FYP mimgui"
        if imKind == "moonimgui" or type(im.OnFrame) == "function" then
            AUTH.panelOpen = false
            AUTH.ok = true
        end
        grndTrace("imgui", "обёртка " .. tostring(IMGUI_WRAP))
        print("{00FFAA}[GRND]{FFFFFF} ImGui загружен (" .. IMGUI_WRAP .. "), рендер запущен")
        notify.chat = false
    else
        grndTrace("imgui", "ImGui НЕ загрузился — меню/таблица/килл-лист не появятся")
        print("{FF6666}[GRND]{FFFFFF} ВНИМАНИЕ: ImGui НЕ загрузился!")
        print("{FF6666}[GRND]{FFFFFF} Проверьте, что в папке moonloader/lib есть imgui.lua / mimgui.lua")
        IMGUI_WRAP = "НЕТ (imgui.lua/mimgui.lua не найдены)"
        pcall(notify.say, "ImGui не найден — меню/таблица/килл-лист недоступны.", "error")
        _G.grndReconFallback = function()
            local R = GRND_RC
            local hasData = R and R.live and (R.live.id or R.live.weap
                or R.live.hp or R.live.ping)
            if not R or (not R.show and not hasData) then return end
            if type(renderFontDrawText) ~= "function" then return end
            local sx, sy = getScreenResolution()
            local x, y, w, h = sx - 372, 92, 350, 274
            if not R.fallbackFont and type(renderCreateFont) == "function" then
                local okF, f = pcall(renderCreateFont, "Tahoma", -14, 1, 204)
                if okF and f then R.fallbackFont = f end
            end
            if not R.fallbackFont then return end
            local function utf(v)
                v = tostring(v or "")
                if type(grndToUtf) == "function" then
                    local ok, out = pcall(grndToUtf, v)
                    if ok and type(out) == "string" then v = out end
                end
                if type(grndToAnsi) == "function" then v = grndToAnsi(v) end
                return v
            end
            local function v(k, fallback)
                local z = R.live and R.live[k]
                return (z ~= nil and tostring(z) ~= "") and utf(z) or (fallback or "—")
            end
            if type(renderDrawBox) == "function" then
                pcall(renderDrawBox, x + 4, y + 5, w, h, 0x60000000)
                pcall(renderDrawBox, x, y, w, h, 0xE60B0F16)
                pcall(renderDrawBox, x, y, w, 3, 0xFF00D6AA)
            end
            local function t(s, dx, dy, c)
                pcall(renderFontDrawText, R.fallbackFont, utf(s), x + dx, y + dy, c)
            end
            t("GRND / RECON", 16, 12, 0xFF00D6AA)
            t("ID " .. v("id", R.id or "—"), 236, 12, 0xFFDDE8F2)
            t(R.nick or "Игрок", 16, 34, 0xFFFFFFFF)
            t("GUN: " .. v("weap"), 16, 66, 0xFFE9EDF6)
            t("AMMO: " .. v("ammo"), 188, 66, 0xFFE9EDF6)
            t("PING: " .. v("ping"), 16, 91, 0xFFE9EDF6)
            t("AFK: " .. v("afk", "0"), 188, 91, 0xFFF79248)
            t("HP: " .. v("hp"), 16, 116, 0xFFFFFFFF)
            t("ARM: " .. v("arm"), 188, 116, 0xFFFFFFFF)
            t("FRACTION: " .. v("frac"), 16, 141, 0xFFE9EDF6)
            t("SPEED: " .. v("speed", "0"), 16, 166, 0xFFE9EDF6)
            t("Интерфейс реконa загружен", 16, 216, 0xFF8C94A6)
        end
    end
    local lastDown = {}
    function wasKeyTapped(vk)
        if isKeyDown then
            local ok, down = pcall(isKeyDown, vk)
            if ok then
                down = down and true or false
                local prev = lastDown[vk]
                lastDown[vk] = down
                if down and not prev then return true end
            end
        end
        if wasKeyPressed then
            local ok, res = pcall(wasKeyPressed, vk)
            if ok and res then return true end
        end
        return false
    end
    local AUTH_OK_DELAY = AUTH.okDelay
    local isAuthDialog = grndAuthDialogOpen
    local function getChatLine(id)
        if not sampGetChatString then return nil, nil end
        local ok, text, prefix = pcall(sampGetChatString, id)
        if not ok then return nil, nil end
        return text, prefix
    end
    local function countAuthFailInChat()
        if not sampGetChatString then return 0 end
        local n = 0
        for id = 0, 99 do
            local t, p = getChatLine(id)
            if authTextIsFail(t) or authTextIsFail(p) then
                n = n + 1
            end
        end
        return n
    end
    do
        local ok, sampev = pcall(require, "samp.events")
        if not ok or not sampev then
            ok, sampev = pcall(require, "lib.samp.events")
        end
        if ok and sampev then
            function sampev.onInitGame(...)
                pcall(grndCamUiEnd,false)
                pcall(grndRkClearEvent)
                authChat.failAt = 0
                GRND_GATE.authSeen, GRND_GATE.unblockAt = false, 0
                GRND_GATE.why = ""
                if type(_G.GRND_AUTH_STATE) == "table" then
                    local state = _G.GRND_AUTH_STATE
                    state.showedLoaded, state.showedAuthOk, state.windowSeen = false, false, false
                    state.closedAt, state.attemptFailed, state.failCountBase = nil, false, 0
                    state.failScanAt, state.dialog, state.spawned = 0, false, false
                end
                GRND_TRACER.rates={}
                GRND_TRACER.aims={}
                if type(grndSfrClear) == 'function' then pcall(grndSfrClear) end
                if type(grndFarChatClear) == 'function' then pcall(grndFarChatClear) end
                if GRND_BULK.running then GRND_BULK.stop("Подключение изменилось. Очередь остановлена.") end
                GRND_WH.native=nil;GRND_WH.nativeAt=-999
                GRND_WH.players={};GRND_WH.scanAt=-999
            end
            function sampev.onAimSync(playerId, data)
                pcall(GRND_TRACER.aim, playerId, data)
            end
            function sampev.onSendAimSync(data)
                if GRND_TRACER.cfg and GRND_TRACER.cfg.enabled then
                    local okId, lid = pcall(GRND_TRACER.localId)
                    if okId then pcall(GRND_TRACER.aim, lid, data) end
                end
            end
            -- Ловушки выстрелов SOFT. Их приходится держать под присмотром:
            -- другой скрипт может переназначить sampev.onBulletSync уже после
            -- нас, и тогда список молча пустеет. Поэтому свою ловушку ставим
            -- заново, а чужой обработчик не ломаем — вызываем его следом.
            do
                local S = GRND_SFR
                local function hookErr(err)
                    if type(S) == "table" and type(S.stat) == "table" then
                        S.stat.err = tostring(err)
                    end
                    pcall(print, "[GRND SOFT] " .. tostring(err))
                end
                local function feed(playerId, data, own)
                    local okT, T = pcall(function() return GRND_TRACER end)
                    if not okT or type(T) ~= "table" or type(T.receive) ~= "function" then
                        hookErr("нет GRND_TRACER.receive")
                        return
                    end
                    local ok, err = pcall(T.receive, playerId, data, own, "bullet")
                    if not ok then hookErr(err) end
                end
                local function localPlayerId()
                    if type(grndSfrLocalId) == "function" then
                        local ok, id = pcall(grndSfrLocalId)
                        if ok and tonumber(id) then return tonumber(id) end
                    end
                    local okT, T = pcall(function() return GRND_TRACER end)
                    if okT and type(T) == "table" and type(T.localId) == "function" then
                        local ok, id = pcall(T.localId)
                        if ok and tonumber(id) then return tonumber(id) end
                    end
                    return nil
                end
                local function makeOther()
                    local fn
                    fn = function(playerId, data)
                        if type(S) == "table" and S.hookBullet ~= fn then return end
                        local prev = S and S.prevBullet
                        if type(prev) == "function" and prev ~= fn then
                            pcall(prev, playerId, data)
                        end
                        feed(playerId, data, false)
                    end
                    return fn
                end
                local function makeOwn()
                    local fn
                    fn = function(data)
                        if type(S) == "table" and S.hookSend ~= fn then return end
                        local prev = S and S.prevSend
                        if type(prev) == "function" and prev ~= fn then
                            pcall(prev, data)
                        end
                        -- свои выстрелы тоже идут в список SOFT
                        feed(localPlayerId(), data, true)
                    end
                    return fn
                end
                if type(S) == "table" then
                    S.sampev = sampev
                    S.hookBullet = S.hookBullet or makeOther()
                    S.hookSend = S.hookSend or makeOwn()
                    -- чужие обработчики запоминаем и вызываем после своих
                    S.prevBullet = (sampev.onBulletSync ~= S.hookBullet)
                        and sampev.onBulletSync or S.prevBullet
                    S.prevSend = (sampev.onSendBulletSync ~= S.hookSend)
                        and sampev.onSendBulletSync or S.prevSend
                    sampev.onBulletSync = S.hookBullet
                    sampev.onSendBulletSync = S.hookSend
                    S.hookAt = os.clock()
                    -- возвращает true, если ловушку пришлось поставить заново
                    function grndSfrEnsureHooks()
                        if type(S) ~= "table" or S.sampev ~= sampev then return false end
                        local fixed = false
                        if sampev.onBulletSync ~= S.hookBullet then
                            S.prevBullet = sampev.onBulletSync
                            sampev.onBulletSync = S.hookBullet
                            fixed = true
                        end
                        if sampev.onSendBulletSync ~= S.hookSend then
                            S.prevSend = sampev.onSendBulletSync
                            sampev.onSendBulletSync = S.hookSend
                            fixed = true
                        end
                        if fixed then S.hookAt = os.clock(); S.hookFixes = (S.hookFixes or 0) + 1 end
                        return fixed
                    end
                end
            end
            local function whSyncField(data, ...)
                for i = 1, select('#', ...) do
                    local name = select(i, ...)
                    local ok, v = pcall(function() return data[name] end)
                    if ok and tonumber(v) ~= nil then return tonumber(v) end
                end
                return nil
            end
            local function whSyncFind(data, kind)
                local names = (kind == 'hp')
                    and { 'playerHealth', 'health', 'hp', 'playerHP', 'bPlayerHealth' }
                    or  { 'playerArmor', 'playerArmour', 'armor', 'armour', 'bPlayerArmour' }
                for i = 1, #names do
                    local v = whSyncField(data, names[i])
                    if v ~= nil then return v end
                end
                local found
                pcall(function()
                    for k, val in pairs(data) do
                        if not found and type(k) == 'string' then
                            local lk = k:lower()
                            local hit = false
                            if kind == 'hp' then
                                hit = (lk:find('health', 1, true) or lk:find('hp', 1, true)) and true or false
                            else
                                hit = (lk:find('armor', 1, true) or lk:find('armour', 1, true)) and true or false
                            end
                            if hit and not (lk:find('vehicle', 1, true) or lk:find('car', 1, true)) then
                                found = tonumber(val)
                            end
                        end
                    end
                end)
                return found
            end
            local function whSyncPos(data)
                local okP, pos = pcall(function() return data.position end)
                if not okP or pos == nil then return nil end
                local function one(k)
                    local ok, v = pcall(function() return pos[k] end)
                    if ok then return tonumber(v) end
                end
                local x, y, z = one('x'), one('y'), one('z')
                if x and y and z then return x, y, z end
                return nil
            end
            local whSyncNamesHp = { 'playerHealth', 'health', 'hp', 'playerHP', 'bPlayerHealth' }
            local whSyncNamesAr = { 'playerArmor', 'playerArmour', 'armor', 'armour', 'bPlayerArmour' }
            local whSyncSlotPlayer, whSyncSlotVehicle, whSyncSlotPassenger = {}, {}, {}
            local function whSyncRead(data, name)
                local ok, v = pcall(function() return data[name] end)
                if ok and tonumber(v) ~= nil then return tonumber(v) end
                return nil
            end
            local function whSyncFindCached(data, slot, kind)
                local name = slot[kind]
                if name ~= nil then
                    return whSyncRead(data, name)
                end
                local names = (kind == 'hp') and whSyncNamesHp or whSyncNamesAr
                for i = 1, #names do
                    local v = whSyncRead(data, names[i])
                    if v ~= nil then slot[kind] = names[i]; return v end
                end
                return whSyncFind(data, kind)
            end
            local function whSyncPosCached(data, slot)
                if slot.pos then
                    local okP, pos = pcall(function() return data.position end)
                    if not okP or pos == nil then
                        slot.pos = nil
                        return whSyncPos(data)
                    end
                    local function one(k)
                        local ok, v = pcall(function() return pos[k] end)
                        if ok then return tonumber(v) end
                    end
                    local x, y, z = one('x'), one('y'), one('z')
                    if x and y and z then return x, y, z end
                    return nil
                end
                local x, y, z = whSyncPos(data)
                if x then slot.pos = true end
                return x, y, z
            end
            local function whSyncFeed(slot, playerId, data)
                local W = GRND_WH
                if W == nil or W.newwh ~= true then return end
                local hp = whSyncFindCached(data, slot, 'hp')
                local armor = whSyncFindCached(data, slot, 'armor')
                local x, y, z = whSyncPosCached(data, slot)
                pcall(W.onSync, playerId, hp, armor, x, y, z)
            end
            function sampev.onPlayerSync(playerId, data)
                if data then
                    whSyncFeed(whSyncSlotPlayer, playerId, data)
                    pcall(grndRkOnPlayerSync, playerId, data)
                    -- выстрел по клавише огня: нужно там, где BulletSync не приходит
                    if type(grndSfrSyncShot) == "function" then
                        pcall(grndSfrSyncShot, playerId, data, false)
                    end
                end
            end
            function sampev.onPlayerStreamIn(playerId, team, model, position)
                pcall(grndRkOnPlayerStreamIn, playerId, position)
            end
            function sampev.onPlayerStreamOut(playerId)
                pcall(grndRkOnPlayerStreamOut, playerId)
            end
            function sampev.onVehicleSync(playerId, vehicleId, data)
                if data then
                    whSyncFeed(whSyncSlotVehicle, playerId, data)
                    pcall(grndRkObservePosition, playerId, data.position)
                end
            end
            function sampev.onPassengerSync(playerId, data)
                if data then
                    whSyncFeed(whSyncSlotPassenger, playerId, data)
                    pcall(grndRkObservePosition, playerId, data.position)
                end
            end
            function sampev.onShowDialog(dialogId, style, title, button1, button2, text)
                _G.GRND_SRVDLG = { id = dialogId, style = tonumber(style) or -1, at = os.clock() }
                if GRND_SKIPZZ and GRND_SKIPZZ.on then
                    local okZ, hideZ = pcall(grndSkipZZMatch, title, text)
                    if okZ and hideZ then return false end
                end
                if not grndSessionReady() then return end
                local okSt, hideSt = pcall(grndStatsOnDialog, dialogId, style, title, button1, button2, text)
                if okSt and hideSt then return false end
                if not okSt and type(_G.grndStatsShouldHide) == "function" then
                    local okH2, hideH2 = pcall(_G.grndStatsShouldHide, title, text)
                    if okH2 and hideH2 then return false end
                end
                if type(_G.grndQrPunOnDialog) == "function" then
                    local okPn, hidePn = pcall(_G.grndQrPunOnDialog,
                        dialogId, style, title, button1, button2, text)
                    if okPn and hidePn then return false end
                end
                if grndRepAcceptDialog(dialogId, title, text) then
                    grndRepSet(dialogId, title, text)
                    return false
                end
                local okA, hideA = pcall(grndAoOnDialog, dialogId, style, title, button1, button2, text)
                if okA and hideA then return false end
                local okRc, hideRc = pcall(grndRcOnDialog, dialogId, style, title, button1, button2, text)
                if okRc and hideRc then return false end
                if type(_G.grndCustomDialogObserve) == "function" then
                    pcall(_G.grndCustomDialogObserve, dialogId, style, title, button1, button2, text)
                end
            end
            function sampev.onSendSpawn()
                GRND_SPAWN.seen = true
            end
            function sampev.onServerMessage(color, text)
                if type(text) == "string" and authTextIsFail(text) then authNoteFail() end
                if not grndSessionReady() then return end
                pcall(grndRkOnServerMessage, text)
                if _G.MP then pcall(_G.MP.onServerMessage, text) end
                if GRND_WH and GRND_WH.noteChatMsg then pcall(GRND_WH.noteChatMsg, text) end
                local okAo, hideAo = pcall(grndAoOnChat, color, text)
                if okAo and hideAo == true then return false end
                local okAp, isApproved = pcall(_G.grndFormsApprovedOnChat, text, "server")
                pcall(grndRepRememberChat, text)
                pcall(grndCatchOnChat, text)
                pcall(grndRepHudOnChat, text)
                if not (okAp and isApproved) then pcall(grndFormsOnChat, text) end
                pcall(_G.grndFormWatchOnChat, text)
                pcall(_G.grndGnewsOnChat, text)
                pcall(gmSniffServerMsg, text)
                pcall(grndKlFeedChat, text)
                pcall(grndRepShouldHideChat, text)
                pcall(grndRcOnChat, color, text)
                if type(_G.grndWeekStatsOnChat) == "function" then
                    pcall(_G.grndWeekStatsOnChat, text)
                end
                local okCi, edit = pcall(grndChatIdOnMsg, color, text)
                if okCi and type(edit) == "table" then return edit end
            end
            if _G.MP then
                _G.MP.chainReady = true
                _G.MP.hookOk = true
            end
            do
                local original=sampev.onServerMessage
                function sampev.onServerMessage(color,text)
                    local ok,result=pcall(original,color,text)
                    if not ok then result=nil end
                    if result~=false then
                        pcall(function()
                            GRND_LOG.inServer=true
                            GRND_LOG.capture(text,'server')
                            GRND_LOG.inServer=false
                        end)
                        if GRND_LOG.inServer then GRND_LOG.inServer=false end
                        if type(_G.grndPunAutoOnChat)=='function' then
                            pcall(_G.grndPunAutoOnChat,text)
                        end
                    end
                    if result==false then return false end
                    local shownColor,shownText=color,text
                    if type(result)=='table' then shownColor,shownText=result[1],result[2] end
                    local okColor,corrected=pcall(grndChatServerColor,shownText,shownColor)
                    if okColor and corrected~=shownColor then return {corrected,shownText} end
                    return result
                end
            end
            function sampev.onChatMessage(playerId,text)
                if grndSessionReady() then
                    if type(grndFarChatNoteOrdinary) == "function" then
                        pcall(grndFarChatNoteOrdinary, playerId, text)
                    end
                    pcall(function() GRND_LOG.capture(GRND_LOG.nick(playerId)..'['..tostring(playerId)..']: '..GRND_LOG.utf(text),'player') end)
                    if type(_G.grndPunAutoOnChat) == 'function' then
                        pcall(_G.grndPunAutoOnChat,
                            GRND_LOG.nick(playerId)..'['..tostring(playerId)..']: '..GRND_LOG.utf(text))
                    end
                    if GRND_WH and GRND_WH.noteChat then pcall(GRND_WH.noteChat, playerId, text) end
                end
            end
            function sampev.onPlayerChatBubble(playerId, color, distance, duration, message)
                if not grndSessionReady() then return end
                if type(grndFarChatAdd) == "function" then
                    pcall(grndFarChatAdd, playerId, distance, message)
                end
            end
            GRND_SPEC_EVENTS = true
            function sampev.onSendCommand(cmd)
                if not grndSessionReady() then return end
                pcall(grndSpecTrackCommand, cmd)
                pcall(grndAoOnCommand, cmd)
                pcall(grndRcOnCommand, cmd)
            end
            local function rcTdEvent(id, data, extra)
                if GRND_SKIPZZ and GRND_SKIPZZ.on then
                    local okZ, hideZ = pcall(grndSkipZZTextDraw, id,
                        type(data) == "string" and data or (type(extra) == "string" and extra) or nil)
                    if okZ and hideZ then return false end
                end
                if not grndSessionReady() then return end
                local text = ""
                if type(data) == "string" then
                    text = data
                elseif type(extra) == "string" then
                    text = extra
                elseif type(data) == "table" then
                    text = data.text or data.string or data.szString or ""
                end
                if text == "" and type(sampTextdrawGetString) == "function" then
                    local okS, s = pcall(sampTextdrawGetString, id)
                    if okS and type(s) == "string" then text = s end
                end
                local okH, hide = pcall(grndRcOnTextDraw, id, text)
                if okH and hide then return false end
            end
            function sampev.onShowTextDraw(id, data, extra)
                return rcTdEvent(id, data, extra)
            end
            function sampev.onTextDrawSetString(id, text)
                return rcTdEvent(id, text)
            end
            function sampev.onShowPlayerTextDraw(id, data, extra)
                return rcTdEvent(id, data, extra)
            end
            function sampev.onPlayerTextDrawSetString(id, text)
                return rcTdEvent(id, text)
            end
            function sampev.onHideTextDraw(id)
                pcall(grndSkipZZForget, id)
                pcall(grndRcOnTextDrawHide, id)
            end
            function sampev.onTextDrawHide(id)
                pcall(grndRcOnTextDrawHide, id)
            end
            function sampev.onSendCommand(command)
                if not grndSessionReady() then return end
                local m = tostring(command or "")
                local convertedUtf, changed = grndChatCommandToEnglishLayout(m, true)
                if not changed then return end
                local outgoing = grndAnsiText(convertedUtf)
                local tracked = outgoing
                if tracked:gsub("^%s*", ""):sub(1, 1) ~= "/" then tracked = "/" .. tracked end
                pcall(grndStatsOnSendChat, tracked)
                pcall(grndSpecTrackCommand, tracked)
                -- Slash commands use RPC.SERVERCOMMAND; return arguments to rewrite that RPC.
                return { outgoing }
            end
            function sampev.onSendChat(msg)
                if not grndSessionReady() then return end
                local m = tostring(msg or "")
                local convertedUtf, changed = grndChatCommandToEnglishLayout(m)
                if changed then
                    local outgoing = grndAnsiText(convertedUtf)
                    pcall(grndStatsOnSendChat, outgoing)
                    pcall(grndSpecTrackCommand, outgoing)
                    -- SAMP.Lua rewrites the outgoing RPC when the callback returns its argument table.
                    return { outgoing }
                end
                pcall(grndStatsOnSendChat, m)
                if m:gsub("^%s*", ""):sub(1, 1) == "/" then
                    pcall(grndSpecTrackCommand, m)
                end
            end
            function sampev.onSendPlayerSync(data)
                if type(grndSfrSyncShot) == "function" then
                    pcall(grndSfrSyncShot, nil, data, true)
                end
                if GRND_INVIS and GRND_INVIS.on and data then
                    local vehFound = false
                    if type(findAllRandomVehiclesInSphere) == "function" and data.position then
                        local okV, hVeh = pcall(findAllRandomVehiclesInSphere, data.position.x, data.position.y, data.position.z, 50.0, false, false)
                        if okV and hVeh and doesVehicleExist(hVeh) and type(sampGetVehicleIdByCarHandle) == "function" then
                            local okId, vehId = pcall(sampGetVehicleIdByCarHandle, hVeh)
                            if okId and vehId and vehId > 0 then
                                data.surfingVehicleId = vehId
                                if type(data.surfingOffsets) == "table" then
                                    data.surfingOffsets.x = 50.5
                                    data.surfingOffsets.y = 50.5
                                    data.surfingOffsets.z = -50.5
                                else
                                    data.surfingOffsets = { x = 50.5, y = 50.5, z = -50.5 }
                                end
                                vehFound = true
                            end
                        end
                    end
                    if not vehFound and data.position and type(data.position.z) == "number" then
                        data.position.z = data.position.z - 25.0
                    end
                end
            end
            function sampev.onSendPassengerSync(data)
                if GRND_INVIS and GRND_INVIS.on and data.position then
                    data.position.z = data.position.z - 25.0
                end
            end
            function sampev.onSendVehicleSync(data)
                if GRND_INVIS and GRND_INVIS.on and data.position then
                    data.position.z = data.position.z - 15.0
                end
            end
            function sampev.onPlayerDeathNotification(killerId, killedId, reason)
                pcall(GRND_LOG.death,killerId,killedId,reason)
                pcall(grndRkOnDeath, killerId, killedId)
                pcall(GRND_WH.onSync, killedId, 0, 0)
                if GRND_KL and GRND_KL.enabled then
                    local ok, handled = pcall(grndKlFeedRpc, killerId, killedId, reason)
                    if ok and handled then return false end
                end
            end
            function sampev.onPlayerJoin(pid,data)
                GRND_CHATID.at=-10
                local id = tonumber(pid)
                local oldIdentity = id and GRND_RK.playerNames[id]
                local oldKey = oldIdentity and oldIdentity.key
                pcall(grndRkClearPlayer, pid)
                local okName, name = pcall(function() return data.nickname end)
                if okName and type(name) == "string" then
                    local okIdentity, identity = pcall(grndRkRememberPlayer, pid, name)
                    if okIdentity and identity and oldKey then
                        pcall(grndRkMigrateIdentity, id, oldKey, identity)
                    end
                end
                pcall(grndRepHudJoin, pid)
            end
            function sampev.onPlayerQuit(pid, reason)
                GRND_CHATID.at=-10
                pcall(grndRkForgetDisconnectedPlayer, pid)
                pcall(grndRepHudRemove, pid)
                if GRND_WH and GRND_WH.sync then GRND_WH.sync[pid]=nil end
                GRND_TRACER.rates[pid]=nil
                GRND_TRACER.aims[pid]=nil
                GRND_TRACER.suspects[pid]=nil
                for id,state in pairs(GRND_TRACER.suspects) do
                    if state.target==pid then GRND_TRACER.suspects[id]=nil end
                end
                local curTid = (_G.GRND_SPEC and tonumber(_G.GRND_SPEC.id))
                    or (_G.GRND_RC and tonumber(_G.GRND_RC.id))
                    or (_G.GRND_SPEC_AUTOREF and tonumber(_G.GRND_SPEC_AUTOREF.lastTargetId))
                if (curTid and curTid == pid) or (GRND_SPEC.active and GRND_SPEC.id == pid) then
                    if type(_G.grndRcForceClose) == "function" then
                        pcall(_G.grndRcForceClose, "quit")
                    end
                    grndSpecForget("quit")
