                    pcall(notify.say, lines[i], "info")
                end
                return true
            end
            if head == "keys" then return grndDiagKeys(rest) end
            if head == "trace" then return grndDiagTrace(rest) end
            if head == "input" then return GRND_INPUT.command(rest) end
            if head == "chat" then
                if type(grndChatTest) == "function" then pcall(grndChatTest, rest) end
                return true
