                "bit.lua: " .. (bit and "есть" or "нет"),
                "memory.lua: " .. (mem and "есть" or "нет"),
                "чат: штатный ввод SA-MP; панель ввода " .. (GRND_INPUT.enabled and "ВКЛ" or "ВЫКЛ"),
                "samp.events: " .. (SAMPEV_OK and "есть" or "нет"),
                "клавиши: " .. (GRND_KEYS.blocked
                    and "перехват снят (авторизация)"
