                    .. " ok=" .. tostring(AUTH.showedAuthOk)
                    .. " fail=" .. tostring(AUTH.attemptFailed),
            }
            for i = 1, #lines do
                print("{00FFAA}[GRND]{FFFFFF} " .. lines[i])
                pcall(notify.say, lines[i], "info")
            end
            return true
        end)
        pcall(sampRegisterChatCommand, "cwsp", function(arg)
            local a = tostring(arg or ""):lower():gsub("%s+", " ")
            if a == "off" or a == "0" or a == "" then
                GRND_SPEC.active = false
                GRND_SPEC.id = nil
                GRND_SPEC.nick = ""
                GRND_SPEC.confirmT = 0
                GRND_SPEC.manualExit = true
                if _G.GRND_SPEC_AUTOREF then
