                    local failFromChat = false
                    if not failFromHook and not dialogActive and now - (AUTH.failScanAt or 0) >= 0.15 then
                        AUTH.failScanAt = now
                        local okCount, failCount = grndPerfRun("countAuthFailInChat", countAuthFailInChat)
                        failFromChat = okCount and type(failCount) == "number"
                            and failCount > (AUTH.failCountBase or 0)
                    end
                    if failFromHook or failFromChat then
                        AUTH.attemptFailed = true
                        AUTH.closedAt = nil
                        authChat.failAt = 0
                        notify.add("Пароль не подошёл — попробуйте ещё раз", "error", 4, true)
                        grndTrace("auth", "ошибка пароля в активном окне авторизации")
                    elseif not dialogActive then
                        if AUTH.closedAt == nil then
                            AUTH.closedAt = now
                            grndTrace("auth", "диалог авторизации закрыт — проверяем вход")
                        elseif now - AUTH.closedAt >= AUTH_OK_DELAY and spawnedNow then
                            AUTH.showedAuthOk = true
                            notify.add("Авторизация прошла успешно", "ok", 4, true)
                            grndTrace("auth", "авторизация подтверждена спавном игрока")
                            lastTry = now
                        end
                    else
                        AUTH.closedAt = nil
                    end
                end
            end)
            if not _okAuth then
                print("{FF6666}[GRND]{FFFFFF} auth-frame: " .. tostring(_errAuth))
            end
            if not renderedOnce and os.clock() - lastTry > 3 and tries < 10 then
                ensureRender(true)
                lastTry = os.clock()
                tries = tries + 1
            end
            local _okHot, _errHot = pcall(function()
                local function poll(k)
                    if not wasKeyTapped(k) then return false end
                    if not grndPollTap(k) then return false end
                    return true
                end
                local function pollRelease(k)
                    if type(isKeyDown) == "function" then
                        local ok, d = grndPerfRun("isKeyDown", isKeyDown,  k)
                        if (not ok) or not d then grndTapEnd(k) end
                    else
                        grndTapEnd(k)
                    end
                end
                for _, k in ipairs({ GRND_MENU_HOTKEY, 0x09, 0x1B, 0x70,
                    0x52, 0x45 }) do
                    pollRelease(k)
                end
                if GRND_INVIS and GRND_INVIS.key then
                    pollRelease(GRND_INVIS.key)
                end
                if GRND_CHAT and GRND_CHAT.key then pollRelease(GRND_CHAT.key) end
                if GRND_CHAT and GRND_CHAT.key and not GRND_CHAT.binding then
                    local isT = (GRND_CHAT.key == 0x54)
                    local busy = grndIsTyping()
                        or (menu and menu.open) or GRND_TAB.open
                        or (GRND_REP and GRND_REP.open)
                    if not isT and not busy and not GRND_CHAT.wantOpen and poll(GRND_CHAT.key) then
                        GRND_CHAT.wantOpen = os.clock()
                        GRND_CHAT.nativeT = false
                    end
                    if GRND_CHAT.wantOpen then
                        if isT then
                            if os.clock() - GRND_CHAT.wantOpen > 0.05 then
                                GRND_CHAT.wantOpen = nil
                                if not busy then grndPerfRun("grndChatOpen", grndChatOpen,  true) end
                            end
                        else
                            GRND_CHAT.wantOpen = nil
                            if not busy then grndPerfRun("grndChatOpen", grndChatOpen,  false) end
                        end
                    end
                end
                if GRND_AREP and GRND_AREP.key then pollRelease(GRND_AREP.key) end
                if GRND_CATCH and GRND_CATCH.key then pollRelease(GRND_CATCH.key) end
                local hotBusy = GRND_KEYS.blocked
                    or (BLOCK_KEYS_ON_ANY_DIALOG and GRND_KEYS.dlgActive)
                    or grndIsTyping()
                if not hotBusy and grndSpecInSpec() then
                    if poll(0x51) then grndSpecSwitch(-1) end
                    if poll(0x45) then grndSpecSwitch(1) end
                end
                if not hotBusy then
                    if grndTargetRingCanUseKey(0x52) and poll(0x52) then
                        grndTargetRingUseKey(0x52)
                    end
                    if not grndSpecInSpec() and grndTargetRingCanUseKey(0x45) and poll(0x45) then
                        grndTargetRingUseKey(0x45)
                    end
                end
                if menu then
                    if not hotBusy and poll(GRND_MENU_HOTKEY) and not grndUiBlocked() then
                        menu.open = not menu.open
                        if menu.open then ensureRender() end
                        grndTrace("key", "M(опрос) -> меню " .. (menu.open and "открыто" or "закрыто"))
                    end
                    if not hotBusy and poll(0x09) then
                        GRND_TAB.open = not GRND_TAB.open
                        GRND_TAB.held = false
                        if GRND_TAB.open then ensureRender() end
                        grndTrace("key", "TAB(опрос) -> " .. tostring(GRND_TAB.open))
                    end
                    if poll(0x1B) then grndEscAction() end
                end
                if not hotBusy and poll(0x70) and grndF1Debounced() then
                    grndF1Press()
                end
            end)
            if not _okHot then
                print("{FF6666}[GRND]{FFFFFF} hotkey-frame: " .. tostring(_errHot))
                pcall(grndTrace, "ERROR", "hotkey-frame: " .. tostring(_errHot))
            end
            if not GRND_GM.cmdReg then
                GRND_GM.cmdReg = true
                if type(sampRegisterChatCommand) == "function" then
                    pcall(sampRegisterChatCommand, "cgm", function() grndGMToggle() end)
                end
            end
            grndGMFrame()
            grndPerfRun("grndInvisFrame", grndInvisFrame)
            grndPerfRun("grndRunFrame", grndRunFrame)
            grndPerfRun("grndOxyFrame", grndOxyFrame)
            grndPerfRun("grndGetupFrame", grndGetupFrame)
            if GRND_AIR.frame then grndPerfRun("GRND_AIR.frame", GRND_AIR.frame) end
            local gmSpawned = false
            if type(grndIsSpawned) == "function" then
                local okS, sp = grndPerfRun("grndIsSpawned", grndIsSpawned)
                if okS then gmSpawned = sp and true or false end
            end
            if not gmSpawned then
                GRND_GM.autoFired = false
            elseif not GRND_GM.autoFired and grndSessionReady() then
                GRND_GM.autoFired = true
                if GRND_GM.autoClient and not GRND_GM.on then
                    grndGMClientSet(true)
                end
                if GRND_GM.autoServer and not GRND_GM.srv and _G.GRND_GM_SRV == true then
                    GRND_GM.srv, GRND_GM.srvKnown = true, false
                end
            end
            if clw then
                local clwTyping = false
                if sampIsChatInputActive then
                    local ok, r = grndPerfRun("sampIsChatInputActive", sampIsChatInputActive)
                    if ok and r then clwTyping = true end
                end
                if GRND_KEYS.typing then clwTyping = true end
                local uiBusy = clwTyping or (menu and menu.open) or GRND_TAB.open
                if not uiBusy then
                    if GRND_SPEC.active then
                        for _, ek in ipairs(GRND_SPEC_EXIT_KEYS) do
                            if wasKeyTapped(ek) then
                                grndSpecForget("key")
                                break
                            end
                        end
                    end
                    if clw.mode == "click" then
                        if clwBtnTapped(clw.keyToggle) then
                            clwSetAiming(not clw.aiming)
                        elseif clw.aiming and clwBtnTapped(clw.keyApply) then
                            clwSafe(clwApplyAim, "warp")
                        elseif clw.aiming and wasKeyTapped(GRND_SPEC_WARP_KEY) then
                            clwSafe(specWarpAim, "spec")
                        elseif clw.aiming and wasKeyTapped(0x1B) then
                            clwSetAiming(false)
                        end
                    else
                        if clwBtnTapped(clw.keyToggle) then
                            if clw.aiming then clwSetAiming(false) end
                            clwSafe(clwDoWarp, "instant")
                        end
                    end
                elseif clw.aiming then
                    clwSetAiming(false)
                end
                if clw.aiming and not grndIsSpawned() then
                    clwSetAiming(false)
                end
                if plainCursorOn and not grndIsSpawned() then
                    plainCursorOn = false
                    grndPlainCursorShow(false)
                end
                if clw.aiming then
                    grndPerfRun("clwAimFrame", clwAimFrame)
                end
            end
        until true
    end
end
_G.GRND_INT = {
    F = GRND_FONT, T = GRND_TAB, K = GRND_KEYS, F1 = GRND_F1,
    S = grndSpecNative,
}
function grndConfigRuntimeInit()
    local C=GRND_CONFIG
    if C.runtimeReady then return end
    C.ensure()
    local loaders={camCfgLoad,grndUiCfgLoad,grndBinderLoad,grndRingLoad,grndCharLoad}
    for _,fn in ipairs(loaders) do
        local ok,err=pcall(fn);if not ok then C.warn(err);C.readOnly=true;return end
    end
    if GRND_PUN and not GRND_PUN.loaded then GRND_PUN.load() end
    if GRND_KL and not GRND_KL.cfgLoaded then grndKlCfgLoad() end
    if GRND_AO and not GRND_AO.cfgLoaded then grndAoCfgLoad() end
    if GRND_SFR and not GRND_SFR.cfgLoaded then grndSfrCfgLoad() end
    if GRND_FCHAT and not GRND_FCHAT.cfgLoaded then grndFarChatCfgLoad() end
    C.restorePanels()
    if GRND_CHATID and GRND_CHATID.register then pcall(GRND_CHATID.register) end
    C.runtimeReady=true
end
function grndConfigSnapshot(force)
    if GRND_LOG then
        local ok,err=pcall(GRND_LOG.tick,force)
        if not ok then GRND_LOG.warn(err) end
    end
    local C=GRND_CONFIG
    if not C.runtimeReady or C.readOnly then return end
    if not force and os.clock()-(C.lastPoll or -10)<1 then return end
    C.lastPoll=os.clock();C.collecting=true
    if grndBinderFlushBuf then pcall(grndBinderFlushBuf) end
    if grndRingUiFlush then pcall(grndRingUiFlush) end
    local savers={grndCamCfgSave,grndUiCfgSave,grndKlCfgSave,grndAoCfgSave,
        grndSfrCfgSave,grndFarChatCfgSave,grndBinderSave,grndRingSave,grndCharSave}
    for _,fn in ipairs(savers) do
        local ok,err=pcall(fn);if not ok then C.warn(err) end
    end
    if GRND_PUN and GRND_PUN.loaded then pcall(GRND_PUN.save) end
    C.extraSnapshot();C.collecting=false
    C.flush()
end
GRND_PERF = { path = nil, t0 = 0, bytes = 0, cap = 300000, lastMs = nil, ready = nil, auth = nil, tick = nil }
function grndPerfMs()
    local P = GRND_PERF
    if P.tick == nil then
        P.tick = false
        local okF, ffi = pcall(require, "ffi")
        if okF then
            pcall(ffi.cdef, "unsigned long GetTickCount(void);")
            local okK, k32 = pcall(ffi.load, "kernel32")
            if okK and k32 then P.tick = k32.GetTickCount end
        end
    end
    if P.tick then return tonumber(P.tick()) or 0 end
    return math.floor(os.clock() * 1000)
end
function grndPerfWrite(msg)
    local P = GRND_PERF
    if P.bytes > P.cap then return end
    local line = os.date("%d.%m %H:%M:%S") .. (" +%d мс  "):format(grndPerfMs() - (P.t0 or 0))
        .. tostring(msg) .. "\n"
    P.bytes = P.bytes + #line
    local path = P.path
    if not path then
        local okP, v = pcall(grndStoragePath, "logs", "grnd_perf.txt")
        if not okP or type(v) ~= "string" then return end
        path = v
        P.path = v
    end
    local okO, f = pcall(io.open, path, "ab")
    if okO and f then f:write(line) f:close() end
end
function grndPerfStart()
    local P = GRND_PERF
    local okP, path = pcall(grndStoragePath, "logs", "grnd_perf.txt")
    if not okP or type(path) ~= "string" then return end
    P.path = path
    P.t0 = grndPerfMs()
    P.bytes = 0
    local okR, f = pcall(io.open, P.path, "rb")
    local size = 0
    if okR and f then size = f:seek("end") or 0 f:close() end
    if size > P.cap then
        local okW, w = pcall(io.open, P.path, "wb")
        if okW and w then w:close() end
    end
    grndPerfWrite("=== запуск скрипта, версия " .. tostring(GRND_SCRIPT_VERSION) .. " ===")
end
function grndPerfRun(name, fn, ...)
    local t0 = grndPerfMs()
    local ok, a, b = pcall(fn, ...)
    local dt = grndPerfMs() - t0
    if dt >= 30 then grndPerfWrite(("шаг «%s» занял %d мс"):format(tostring(name), dt)) end
    return ok, a, b
end
function main()
    GRND_CONFIG.ensure()
    GRND_CONFIG.restoreHotkeys()
    GRND_LOG.init()
    grndPerfStart()
    GRND_CONFIG.flush()
    local ok, err = pcall(grndMainBody)
    if not ok then
        GRND_MAIN_ERR = tostring(err)
        print("{FF6666}[GRND]{FFFFFF} main() упал: " .. GRND_MAIN_ERR)
        if type(sampAddChatMessage) == "function" then
            pcall(grndChatSay, "{FF6666}[GRND] main() упал: " .. GRND_MAIN_ERR, -1)
        end
    end
end